// Extreme overhead crop into a full glass of red wine:
// Vast meditative watercolor fields of cool garnet, prune, and rose-madder
// with soft haloed stain edges, a startling white meniscus highlight arc,
// tiny tear-drop wine legs on the inside glass wall, and a refracted sliver of tablecloth.

const MENISCUS_CX = 360;
const MENISCUS_CY = 810;
const MENISCUS_RX = 820;
const MENISCUS_RY = 740;
const MENISCUS_ROT = -42; // degrees

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(8913);

  // Required brush scaling
  brush.scaleBrushes(3);

  // Custom brushes scaled for 1200x1200 canvas precision
  brush.add("stain_halo", {
    type: "default",
    weight: 26,
    scatter: 1.9,
    sharpness: 0.1,
    grain: 16,
    opacity: 13,
    spacing: 0.25,
    pressure: [0.2, 1.1, 0.2],
    noise: 0.85
  });

  brush.add("stain_edge", {
    type: "default",
    weight: 3.8,
    scatter: 0.42,
    sharpness: 0.38,
    grain: 32,
    opacity: 34,
    spacing: 0.16,
    pressure: [0.15, 1.0, 0.15],
    noise: 0.9
  });

  brush.add("velvet_wash", {
    type: "marker",
    weight: 30,
    scatter: 0.12,
    opacity: 16,
    spacing: 0.14,
    pressure: [0.3, 1.0, 0.3],
    markerTip: false,
    noise: 0.2
  });

  brush.add("linen_thread", {
    type: "default",
    weight: 1.1,
    scatter: 0.04,
    sharpness: 0.88,
    grain: 50,
    opacity: 95,
    spacing: 0.1,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.25
  });

  brush.add("razor_highlight", {
    type: "default",
    weight: 2.0,
    scatter: 0.01,
    sharpness: 0.97,
    grain: 95,
    opacity: 255,
    spacing: 0.05,
    pressure: [0.08, 1.15, 0.08],
    noise: 0.04
  });

  brush.add("optical_glow", {
    type: "spray",
    weight: 15,
    scatter: 1.7,
    opacity: 24,
    spacing: 0.18,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.35
  });
}

// Convert polar (theta in degrees, radial distance d from meniscus) to canvas (x, y)
// d = 0 is the meniscus; d < 0 is inside the wine pool; d > 0 is up the inside glass wall.
function meniscusPt(theta, d = 0) {
  let rx = MENISCUS_RX + d * 0.88;
  let ry = MENISCUS_RY + d * 0.82;
  // Perspective shift along the viewing tilt axis as we move up the 3D glass wall
  let shift = d > 0 ? d * 0.24 : d * 0.05;
  let lx = rx * cos(theta) + shift;
  let ly = ry * sin(theta);
  let c = cos(MENISCUS_ROT);
  let s = sin(MENISCUS_ROT);
  return {
    x: MENISCUS_CX + lx * c - ly * s,
    y: MENISCUS_CY + lx * s + ly * c
  };
}

// Clamp any (x, y) point so it stays inside the wine pool boundary (d <= maxD)
function clampToWinePool(x, y, maxD = -2) {
  let dx = x - MENISCUS_CX;
  let dy = y - MENISCUS_CY;
  let c = cos(-MENISCUS_ROT);
  let s = sin(-MENISCUS_ROT);
  let lx = dx * c - dy * s;
  let ly = dx * s + dy * c;

  let maxRx = MENISCUS_RX + maxD * 0.88;
  let maxRy = MENISCUS_RY + maxD * 0.82;
  let shift = maxD * 0.05;
  let ex = lx - shift;
  let ey = ly;

  let norm = sqrt(sq(ex / maxRx) + sq(ey / maxRy));
  if (norm > 1.0) {
    ex /= norm;
    ey /= norm;
    lx = ex + shift;
    ly = ey;
    let c2 = cos(MENISCUS_ROT);
    let s2 = sin(MENISCUS_ROT);
    return {
      x: MENISCUS_CX + lx * c2 - ly * s2,
      y: MENISCUS_CY + lx * s2 + ly * c2,
      clamped: true
    };
  }
  return { x, y, clamped: false };
}

// Generate an organic watercolor stain polygon clamped to the wine pool
function buildOrganicStainPts(cx, cy, rx, ry, rotDeg, numPts, wobble, freq, seedOff, maxD = -3) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < numPts; i++) {
    let ang = (i / numPts) * 360;
    let n1 = noise(cos(ang) * freq + seedOff, sin(ang) * freq + seedOff);
    let n2 = noise(cos(ang) * freq * 2.3 + seedOff + 40, sin(ang) * freq * 2.3 + seedOff + 40);
    let rMod = 1.0 + (n1 - 0.5) * wobble + (n2 - 0.5) * (wobble * 0.4);
    let lx = rx * rMod * cos(ang);
    let ly = ry * rMod * sin(ang);
    let px = cx + lx * c - ly * s;
    let py = cy + lx * s + ly * c;
    let clampedPt = clampToWinePool(px, py, maxD);
    pts.push(clampedPt);
  }
  return pts;
}

// Draw a filled organic shape using brush.beginShape
function drawFilledShape(pts, curvature = 0.55) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
}

// Trace the un-clamped interior segments of an organic stain to create a soft, haloed stain edge
function drawHaloedStainEdge(pts, haloColor, ringColor, haloWeight = 1.0, ringWeight = 0.85) {
  let currentRun = [];
  let runs = [];

  for (let i = 0; i <= pts.length; i++) {
    let pt = pts[i % pts.length];
    // Only draw stain halos inside the wine pool and inside the canvas
    if (!pt.clamped && pt.x > -40 && pt.x < 1240 && pt.y > -40 && pt.y < 1240) {
      currentRun.push([pt.x, pt.y]);
    } else {
      if (currentRun.length >= 4) runs.push(currentRun);
      currentRun = [];
    }
  }
  if (currentRun.length >= 4) runs.push(currentRun);

  for (let run of runs) {
    // 1. Soft diffuse watercolor bloom halo
    brush.set("stain_halo", haloColor, haloWeight);
    brush.spline(run, 0.5);

    // 2. Concentrated pigment stain ring at the edge of the wash
    brush.set("stain_edge", ringColor, ringWeight);
    brush.spline(run, 0.5);
  }
}

// Helper to build a band polygon between d1 and d2 from thetaStart to thetaEnd
function buildArcBandPts(thetaStart, thetaEnd, steps, d1Fn, d2Fn) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let th = lerp(thetaStart, thetaEnd, t);
    let p = meniscusPt(th, d1Fn(th, t));
    pts.push({ x: p.x, y: p.y });
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let th = lerp(thetaStart, thetaEnd, t);
    let p = meniscusPt(th, d2Fn(th, t));
    pts.push({ x: p.x, y: p.y });
  }
  return pts;
}

function draw() {
  translate(-width / 2, -height / 2);

  // Cool cotton watercolor paper ground
  background("#f2f1f7");

  // =========================================================================
  // 1. UPPER-RIGHT GLASS WALL, AMBIENT CORNER & REFRACTED SLIVER OF TABLECLOTH
  // =========================================================================
  drawGlassAndRefractedTablecloth();

  // =========================================================================
  // 2. VAST SOAKED COLOR-FIELD WASHES (ROSE-MADDER, GARNET, PRUNE)
  // =========================================================================
  drawWineColorFieldWashes();

  // =========================================================================
  // 3. SOFT, HALOED STAIN EDGES & MEDITATIVE WATERCOLOR BLOOMS
  // =========================================================================
  drawInteriorStainHalos();

  // =========================================================================
  // 4. MENISCUS CAPILLARY TRANSITION & INNER GLASS WALL GLAZES
  // =========================================================================
  drawMeniscusTransitionZone();

  // =========================================================================
  // 5. TINY TEAR-DROP WINE LEGS DRIPPING DOWN THE INSIDE WALL
  // =========================================================================
  drawWineTearDropLegs();

  // =========================================================================
  // 6. HYPERREAL FOCUS: STARTLING WHITE MENISCUS ARC & PRECISE REFLECTIONS
  // =========================================================================
  drawHyperrealReflections();

  noLoop();
}

// ---------------------------------------------------------------------------
// SECTION 1: Glass Wall, Ambient Corner & Refracted Sliver of Tablecloth
// ---------------------------------------------------------------------------
function drawGlassAndRefractedTablecloth() {
  brush.noStroke();

  // 1A. Out-of-focus cool slate ambient background beyond the outer glass rim (d > 232)
  let outerCornerBand = buildArcBandPts(
    -52, 36, 28,
    (th) => 232,
    (th) => 420
  );
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.3);
  brush.fill("#4a5b78", 95);
  drawFilledShape(outerCornerBand, 0.4);

  let outerCornerDeep = buildArcBandPts(
    -42, 24, 22,
    (th) => 260,
    (th) => 420
  );
  brush.fill("#2f3e59", 110);
  drawFilledShape(outerCornerDeep, 0.4);

  // 1B. Inside Glass Wall Base Wash (d from 0 to 152) - cool rose-quartz & pale lilac-grey
  let glassWallLower = buildArcBandPts(
    -58, 72, 40,
    (th) => -2,
    (th) => 78 + 12 * sin(th * 2)
  );
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.5, 0.4);
  brush.fill("#e6cadb", 95);
  drawFilledShape(glassWallLower, 0.5);

  let glassWallUpper = buildArcBandPts(
    -56, 62, 36,
    (th) => 62,
    (th) => 154
  );
  brush.fill("#d5d8eb", 85);
  drawFilledShape(glassWallUpper, 0.5);

  // Cool violet-slate shadow along the far-top and far-right curves of the inner glass wall
  let glassShadowTop = buildArcBandPts(
    -56, -18, 20,
    (th) => 45,
    (th) => 152
  );
  brush.fill("#9ea8c7", 75);
  drawFilledShape(glassShadowTop, 0.5);

  let glassShadowRight = buildArcBandPts(
    18, 65, 22,
    (th) => 35,
    (th) => 152
  );
  brush.fill("#b89eb8", 80);
  drawFilledShape(glassShadowRight, 0.5);

  // 1C. THE REFRACTED SLIVER OF TABLECLOTH (d from 152 to 232)
  // Base sunlit cool porcelain linen sliver
  let tableclothSliverBase = buildArcBandPts(
    -50, 38, 36,
    (th) => 152,
    (th) => 232
  );
  brush.noFill();
  brush.wash("#eef3fa", 230);
  drawFilledShape(tableclothSliverBase, 0.45);
  brush.noWash();

  // Subtle cool periwinkle linen fold shadows at both ends of the refracted sliver
  let clothFoldLeft = buildArcBandPts(
    -50, -14, 20,
    (th) => 154,
    (th) => 230
  );
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.4, 0.35);
  brush.fill("#9bb0cf", 95);
  drawFilledShape(clothFoldLeft, 0.45);

  let clothFoldRight = buildArcBandPts(
    10, 38, 20,
    (th) => 154,
    (th) => 230
  );
  brush.fill("#859bbd", 105);
  drawFilledShape(clothFoldRight, 0.45);

  // Refracted cool cobalt-slate woven bistro stripe warping through the glass lens
  let bistroStripeMain = buildArcBandPts(
    -46, 32, 36,
    (th) => 182 + 8 * sin(th * 2.2),
    (th) => 202 + 8 * sin(th * 2.2)
  );
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.55, 0.65);
  brush.fill("#364f78", 165);
  drawFilledShape(bistroStripeMain, 0.45);

  brush.noFill();

  // Hyperreal woven linen threads inside the refracted sliver (warp & weft magnified by glass)
  // Warp threads running along the curved lens sliver
  for (let dOff = 156; dOff <= 228; dOff += 3.2) {
    let warpPts = [];
    let isStripe = dOff > 181 && dOff < 203;
    let isPinStripe = abs(dOff - 174) < 2.2 || abs(dOff - 210) < 2.2;

    for (let th = -45; th <= 30; th += 2.5) {
      let lensWave = 6 * sin(th * 2.2) + 1.5 * cos(th * 5.0);
      let p = meniscusPt(th, dOff + lensWave * 0.65);
      if (p.x >= -10 && p.x <= 1210 && p.y >= -10 && p.y <= 1210) {
        warpPts.push([p.x, p.y]);
      }
    }
    if (warpPts.length >= 4) {
      let col = isStripe ? "#283d61" : (isPinStripe ? "#425e8c" : "#b8c7de");
      let w = isPinStripe ? 0.65 : 0.38;
      brush.set("linen_thread", col, w);
      brush.spline(warpPts, 0.4);
    }
  }

  // Weft cross-threads cutting obliquely across the sliver with optical lens curvature
  for (let th = -42; th <= 28; th += 0.85) {
    let weftPts = [];
    for (let s = 0; s <= 6; s++) {
      let u = s / 6;
      let dCur = lerp(154, 230, u);
      // S-curve optical refraction distortion across the glass wall thickness
      let thWarp = th + 3.8 * u + 1.4 * sin(u * 180);
      let p = meniscusPt(thWarp, dCur);
      if (p.x >= -10 && p.x <= 1210 && p.y >= -10 && p.y <= 1210) {
        weftPts.push([p.x, p.y]);
      }
    }
    if (weftPts.length >= 4) {
      let inBrightFocus = th > -20 && th < 12;
      let col = inBrightFocus ? "#9fb2cc" : "#7e94b3";
      brush.set("linen_thread", col, 0.34);
      brush.spline(weftPts, 0.35);

      // Sunlit white linen thread crowns in the sharpest focal zone
      if (inBrightFocus && int(th * 2) % 2 === 0) {
        brush.set("razor_highlight", "#ffffff", 0.28);
        brush.spline(weftPts.slice(1, 5), 0.35);
      }
    }
  }

  // Crisp optical glass boundaries framing the refracted tablecloth sliver
  for (let boundaryD of [151, 154, 229, 233]) {
    let rimPts = [];
    for (let th = -48; th <= 35; th += 2.5) {
      let p = meniscusPt(th, boundaryD);
      if (p.x >= -20 && p.x <= 1220 && p.y >= -20 && p.y <= 1220) {
        rimPts.push([p.x, p.y]);
      }
    }
    if (rimPts.length >= 4) {
      if (boundaryD === 151 || boundaryD === 233) {
        brush.set("rotring", "#2b1c3d", 0.55);
        brush.spline(rimPts, 0.5);
      } else {
        brush.set("razor_highlight", "#ffffff", 0.52);
        brush.spline(rimPts, 0.5);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// SECTION 2: Vast Soaked Watercolor Fields (Garnet, Prune, Rose-Madder)
// ---------------------------------------------------------------------------
function drawWineColorFieldWashes() {
  brush.noStroke();

  // 2A. Full Wine Pool Underpainting Wash - luminous cool rose-madder & claret base
  // Leaves a translucent luminous rim right near d = 0 while grounding the entire field
  let fullWineBase = buildOrganicStainPts(
    MENISCUS_CX, MENISCUS_CY,
    MENISCUS_RX - 2, MENISCUS_RY - 2,
    MENISCUS_ROT, 72, 0.01, 1.2, 10, -1
  );
  brush.wash("#a82058", 195);
  drawFilledShape(fullWineBase, 0.5);
  brush.noWash();

  // 2B. Batch 1: Rose-Madder & Cool Magenta-Crimson Soaked Fields
  // Vast luminous outer and upper-right/bottom-right washes bleeding inward
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.68, 0.78);

  let roseMadderShapes = [
    // Sweeping rose-madder field along the upper-right meniscus curve
    buildOrganicStainPts(620, 480, 560, 480, -38, 56, 0.22, 1.4, 101, -2),
    // Upper-left to center rose-madder bloom
    buildOrganicStainPts(310, 320, 480, 420, -15, 52, 0.28, 1.6, 202, -3),
    // Lower-right rose-madder tide near the right meniscus curve
    buildOrganicStainPts(820, 880, 460, 420, -45, 52, 0.25, 1.5, 303, -2)
  ];
  brush.fill("#c9346e", 115);
  for (let pts of roseMadderShapes) drawFilledShape(pts, 0.55);

  // Deeper rose-madder / cool alizarin claret transition washes
  let claretShapes = [
    buildOrganicStainPts(520, 560, 640, 560, -40, 58, 0.24, 1.3, 404, -8),
    buildOrganicStainPts(260, 490, 520, 470, -25, 50, 0.30, 1.7, 505, -10),
    buildOrganicStainPts(720, 740, 490, 440, -35, 50, 0.26, 1.5, 606, -6)
  ];
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.72, 0.82);
  brush.fill("#9e194e", 125);
  for (let pts of claretShapes) drawFilledShape(pts, 0.55);

  // 2C. Batch 2: Cool Violet-Indigo Undertone Bleeds (cool vintage Pinot/Syrah undertone)
  let coolVioletShapes = [
    buildOrganicStainPts(440, 660, 590, 510, -35, 54, 0.28, 1.4, 707, -16),
    buildOrganicStainPts(190, 380, 430, 390, -10, 48, 0.32, 1.8, 808, -14),
    buildOrganicStainPts(640, 960, 460, 380, -50, 48, 0.26, 1.6, 909, -12)
  ];
  brush.fillBleed(0.36, "out");
  brush.fillTexture(0.65, 0.75);
  brush.fill("#43164f", 110);
  for (let pts of coolVioletShapes) drawFilledShape(pts, 0.55);

  // 2D. Batch 3: Vast Garnet Mid-Fields (the rich, meditative heart of the wine)
  let garnetMidShapes = [
    buildOrganicStainPts(410, 690, 640, 580, -42, 60, 0.25, 1.3, 1110, -14),
    buildOrganicStainPts(490, 580, 530, 460, -30, 54, 0.30, 1.6, 1212, -20),
    buildOrganicStainPts(220, 620, 490, 450, -20, 50, 0.28, 1.5, 1313, -15)
  ];
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.74, 0.85);
  brush.fill("#730f3d", 135);
  for (let pts of garnetMidShapes) drawFilledShape(pts, 0.55);

  let deepGarnetShapes = [
    buildOrganicStainPts(370, 740, 570, 510, -40, 56, 0.27, 1.4, 1414, -24),
    buildOrganicStainPts(460, 650, 450, 390, -32, 50, 0.32, 1.7, 1515, -30),
    buildOrganicStainPts(180, 880, 460, 420, -45, 48, 0.25, 1.5, 1616, -20)
  ];
  brush.fill("#590a32", 145);
  for (let pts of deepGarnetShapes) drawFilledShape(pts, 0.55);

  // 2E. Batch 4: Abyssal Prune & Damson-Noir Core Fields
  let pruneShapes = [
    buildOrganicStainPts(310, 810, 490, 440, -42, 56, 0.28, 1.4, 1717, -38),
    buildOrganicStainPts(380, 720, 410, 360, -35, 52, 0.33, 1.8, 1818, -45),
    buildOrganicStainPts(160, 580, 350, 320, -18, 48, 0.30, 1.6, 1919, -35)
  ];
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.7, 0.82);
  brush.fill("#36072c", 155);
  for (let pts of pruneShapes) drawFilledShape(pts, 0.55);

  let abyssalPruneShapes = [
    buildOrganicStainPts(270, 850, 390, 350, -40, 52, 0.26, 1.5, 2020, -55),
    buildOrganicStainPts(330, 760, 310, 270, -30, 48, 0.30, 1.7, 2121, -65),
    buildOrganicStainPts(190, 960, 320, 290, -45, 46, 0.24, 1.4, 2222, -50)
  ];
  brush.fill("#1f041e", 165);
  for (let pts of abyssalPruneShapes) drawFilledShape(pts, 0.55);

  // Deepest velvety prune core in the lower-left abyss
  let coreAbyss = buildOrganicStainPts(230, 890, 270, 240, -38, 46, 0.25, 1.5, 2323, -80);
  brush.fill("#130214", 150);
  drawFilledShape(coreAbyss, 0.55);

  // 2F. Internal Rose-Madder & Ruby Optical Caustic Glow (deep liquid translucency)
  // A subtle glowing crescent inside the lower-center/right where light focuses through the bowl
  let internalCausticOuter = buildOrganicStainPts(610, 870, 230, 140, -42, 44, 0.22, 1.6, 2424, -28);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.5, 0.6);
  brush.fill("#b8255f", 75);
  drawFilledShape(internalCausticOuter, 0.6);

  let internalCausticInner = buildOrganicStainPts(635, 855, 150, 85, -42, 40, 0.20, 1.8, 2525, -32);
  brush.fill("#e04882", 65);
  drawFilledShape(internalCausticInner, 0.6);

  brush.noFill();
}

// ---------------------------------------------------------------------------
// SECTION 3: Soft, Haloed Stain Edges (Watermarks / Backruns between Fields)
// ---------------------------------------------------------------------------
function drawInteriorStainHalos() {
  // Trace organic watercolor backrun boundaries where rose-madder, garnet, and prune bleed together
  let stainContours = [
    {
      pts: buildOrganicStainPts(560, 530, 590, 510, -38, 80, 0.24, 1.4, 101, -4),
      halo: "#e36898", ring: "#8f1548", hw: 1.15, rw: 0.9
    },
    {
      pts: buildOrganicStainPts(480, 610, 560, 490, -36, 80, 0.28, 1.5, 404, -10),
      halo: "#c43570", ring: "#690c37", hw: 1.1, rw: 0.85
    },
    {
      pts: buildOrganicStainPts(410, 690, 580, 520, -42, 80, 0.25, 1.3, 1110, -16),
      halo: "#961b51", ring: "#4a0729", hw: 1.2, rw: 0.95
    },
    {
      pts: buildOrganicStainPts(370, 740, 510, 450, -40, 76, 0.27, 1.4, 1414, -24),
      halo: "#781242", ring: "#330522", hw: 1.05, rw: 0.85
    },
    {
      pts: buildOrganicStainPts(310, 810, 440, 390, -42, 72, 0.28, 1.4, 1717, -38),
      halo: "#5c1449", ring: "#21031c", hw: 1.0, rw: 0.8
    },
    {
      pts: buildOrganicStainPts(260, 440, 450, 390, -18, 70, 0.30, 1.7, 505, -12),
      halo: "#d1477b", ring: "#75103f", hw: 0.95, rw: 0.75
    },
    {
      pts: buildOrganicStainPts(610, 870, 230, 140, -42, 60, 0.22, 1.6, 2424, -28),
      halo: "#eb71a0", ring: "#991b50", hw: 0.9, rw: 0.7
    }
  ];

  for (let sc of stainContours) {
    drawHaloedStainEdge(sc.pts, sc.halo, sc.ring, sc.hw, sc.rw);
  }
}

// ---------------------------------------------------------------------------
// SECTION 4: Meniscus Capillary Rim & Inner Glass Wall Glazes
// ---------------------------------------------------------------------------
function drawMeniscusTransitionZone() {
  // 4A. Luminous Rose-Madder Capillary Wedge just inside the meniscus (d from -18 to 0)
  for (let pass = 0; pass < 3; pass++) {
    let dOffset = -14 + pass * 5;
    let rimPts = [];
    for (let th = -56; th <= 72; th += 2.0) {
      let p = meniscusPt(th, dOffset + 1.5 * sin(th * 3));
      if (p.x >= -30 && p.x <= 1230 && p.y >= -30 && p.y <= 1230) {
        rimPts.push([p.x, p.y]);
      }
    }
    if (rimPts.length >= 4) {
      let col = pass === 0 ? "#b8255f" : (pass === 1 ? "#db4c84" : "#f08ab3");
      let w = pass === 0 ? 1.1 : (pass === 1 ? 0.85 : 0.55);
      brush.set("velvet_wash", col, w);
      brush.spline(rimPts, 0.5);
    }
  }

  // 4B. Concentrated Watercolor Stain Rim where the meniscus touches the glass (d = -1 to +1)
  let contactPts = [];
  for (let th = -56; th <= 72; th += 1.5) {
    let p = meniscusPt(th, 0.8 * sin(th * 4));
    if (p.x >= -20 && p.x <= 1220 && p.y >= -20 && p.y <= 1220) {
      contactPts.push([p.x, p.y]);
    }
  }
  if (contactPts.length >= 4) {
    brush.set("stain_halo", "#e878a4", 0.65);
    brush.spline(contactPts, 0.5);
    brush.set("stain_edge", "#6e0f3c", 0.95);
    brush.spline(contactPts, 0.5);
  }

  // 4C. Subtle Marangoni Swirl Crown (upper wetting watermark on the inside glass wall, d ~ 108..126)
  // Forms delicate scalloped arches from which the wine tear-drop legs descend
  let legAngles = [-37, -31, -25.5, -19.5, -14, -8.5, -3.5, 1.5, 6.5, 11.5, 16.8, 22, 27.5, 33, 39];
  for (let i = 0; i < legAngles.length - 1; i++) {
    let th1 = legAngles[i];
    let th2 = legAngles[i + 1];
    let archPts = [];
    let steps = 8;
    for (let s = 0; s <= steps; s++) {
      let u = s / steps;
      let th = lerp(th1, th2, u);
      // Scalloped arch dipping slightly at the ends where the legs form
      let dArch = 114 + 10 * sin(u * 180) + 4 * sin(th * 3);
      let p = meniscusPt(th, dArch);
      if (p.x >= -10 && p.x <= 1210 && p.y >= -10 && p.y <= 1210) {
        archPts.push([p.x, p.y]);
      }
    }
    if (archPts.length >= 4) {
      brush.set("stain_halo", "#dfa0bc", 0.32);
      brush.spline(archPts, 0.45);
      brush.set("stain_edge", "#b85682", 0.35);
      brush.spline(archPts, 0.45);
    }
  }
}

