function drawSingleTearDropLeg(th, dHead, dTail, r, wobble) {
  let pHead = meniscusPt(th, dHead);
  let pTail = meniscusPt(th, dTail);
  if (pHead.x < -10 || pHead.x > 1210 || pHead.y < -10 || pHead.y > 1210) return;

  // Unit vector pointing down the glass wall from tail to head (toward the meniscus)
  let vx = pHead.x - pTail.x;
  let vy = pHead.y - pTail.y;
  let len = sqrt(vx * vx + vy * vy);
  if (len < 5) return;
  let ux = vx / len;
  let uy = vy / len;
  // Perpendicular vector across the glass wall
  let nx = -uy;
  let ny = ux;

  // 1. Thin wet rivulet track from the upper swirl arch down to the tear-drop head
  let trackPts = [];
  let trackHighlightPts = [];
  let steps = 7;
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let dCur = lerp(dTail, dHead + r * 0.6, u);
    let thCur = th + wobble * sin(u * 180);
    let pt = meniscusPt(thCur, dCur);
    trackPts.push([pt.x, pt.y]);
    trackHighlightPts.push([pt.x - nx * 1.1, pt.y - ny * 1.1]);
  }

  // Rose-tinted wet track & shadow edge
  brush.set("stain_edge", "#cf5f8e", 0.36);
  brush.spline(trackPts, 0.45);
  brush.set("rotring", "#8c2252", 0.28);
  brush.spline(trackPts, 0.45);

  // Specular white ridge along the wet track
  brush.set("razor_highlight", "#ffffff", 0.32);
  brush.spline(trackHighlightPts, 0.45);

  // 2. Construct the Tear-Drop Bulb (plump head at pHead tapering up toward the tail)
  let tearLen = r * 4.4;
  let dropPts = [
    // Tip of tail
    { x: pHead.x - ux * tearLen, y: pHead.y - uy * tearLen },
    // Left waist
    { x: pHead.x - ux * (r * 1.6) - nx * (r * 0.55), y: pHead.y - uy * (r * 1.6) - ny * (r * 0.55) },
    // Left belly
    { x: pHead.x - nx * r, y: pHead.y - ny * r },
    // Bottom rounded nose (pointing down toward meniscus)
    { x: pHead.x + ux * (r * 1.05), y: pHead.y + uy * (r * 1.05) },
    // Right belly
    { x: pHead.x + nx * r, y: pHead.y + ny * r },
    // Right waist
    { x: pHead.x - ux * (r * 1.6) + nx * (r * 0.55), y: pHead.y - uy * (r * 1.6) + ny * (r * 0.55) }
  ];

  // 2A. Refracted rose-ruby caustic glow cast onto the glass wall just below/beside the droplet
  let shadowPts = dropPts.map(pt => ({
    x: pt.x + ux * (r * 0.55) + nx * (r * 0.4),
    y: pt.y + uy * (r * 0.55) + ny * (r * 0.4)
  }));
  brush.noStroke();
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.3, 0.4);
  brush.fill("#b52862", 125);
  drawFilledShape(shadowPts, 0.55);

  // 2B. Translucent rose-madder droplet body
  brush.fillBleed(0.04, "in");
  brush.fill("#eb8db4", 150);
  drawFilledShape(dropPts, 0.55);
  brush.noFill();

  // 2C. Crisp dark garnet optical refraction contour along the upper/right side of the tear-drop
  let darkRimPts = [
    [dropPts[0].x, dropPts[0].y],
    [dropPts[5].x, dropPts[5].y],
    [dropPts[4].x, dropPts[4].y],
    [dropPts[3].x, dropPts[3].y]
  ];
  brush.set("rotring", "#540c31", 0.45);
  brush.spline(darkRimPts, 0.5);

  // 2D. Luminous pink-white internal bounce light along the bottom nose of the droplet
  let bouncePts = [
    [dropPts[2].x, dropPts[2].y],
    [dropPts[3].x - ux * 0.4, dropPts[3].y - uy * 0.4],
    [dropPts[4].x, dropPts[4].y]
  ];
  brush.set("razor_highlight", "#ffd6e8", 0.42);
  brush.spline(bouncePts, 0.5);

  // 2E. Startling pure white specular comma highlight on the upper-left dome of the tear-drop
  let hlPts = [
    [pHead.x - ux * (r * 1.3) - nx * (r * 0.32), pHead.y - uy * (r * 1.3) - ny * (r * 0.32)],
    [pHead.x - ux * (r * 0.35) - nx * (r * 0.52), pHead.y - uy * (r * 0.35) - ny * (r * 0.52)],
    [pHead.x + ux * (r * 0.35) - nx * (r * 0.35), pHead.y + uy * (r * 0.35) - ny * (r * 0.35)]
  ];
  brush.set("razor_highlight", "#ffffff", 0.78);
  brush.spline(hlPts, 0.5);
}

// ---------------------------------------------------------------------------
// SECTION 6: Hyperreal Focus - Startling White Meniscus Arc & Reflections
// ---------------------------------------------------------------------------
function drawHyperrealReflections() {
  // 6A. Optical High-Contrast Dark Backing Line along the Meniscus Inflection
  // Makes the startling white hairline highlight pop with razor-sharp optical focus
  let darkBackingPts = [];
  for (let th = -50; th <= 60; th += 1.5) {
    let p = meniscusPt(th, -1.2);
    if (p.x >= -10 && p.x <= 1210 && p.y >= -10 && p.y <= 1210) {
      darkBackingPts.push([p.x, p.y]);
    }
  }
  if (darkBackingPts.length >= 4) {
    brush.set("rotring", "#24041e", 0.85);
    brush.spline(darkBackingPts, 0.5);
  }

  // 6B. Soft Icy-Blue & White Optical Halation Glow along the Meniscus Highlight
  let glowPts = [];
  for (let th = -36; th <= 42; th += 2.0) {
    let p = meniscusPt(th, 2.5);
    if (p.x >= -10 && p.x <= 1210 && p.y >= -10 && p.y <= 1210) {
      glowPts.push([p.x, p.y]);
    }
  }
  if (glowPts.length >= 4) {
    brush.set("optical_glow", "#d4e8ff", 1.15);
    brush.spline(glowPts, 0.5);
    brush.set("optical_glow", "#ffffff", 0.8);
    brush.spline(glowPts, 0.5);
  }

  // 6C. THE SINGLE HAIRLINE ARC OF STARTLING WHITE HIGHLIGHT WHERE MENISCUS MEETS GLASS
  // Full sweeping hairline arc from top-center-right through apex down to lower-right
  let mainArcPts = [];
  for (let th = -48; th <= 56; th += 1.2) {
    let t = map(th, -48, 56, 0, 1);
    // Natural pressure curve: needle-thin at ends, startlingly crisp through the central curve
    let pMod = sin(t * 180);
    let pressure = 0.15 + 1.15 * pow(pMod, 0.75);
    let p = meniscusPt(th, 2.2);
    if (p.x >= -10 && p.x <= 1210 && p.y >= -10 && p.y <= 1210) {
      mainArcPts.push([p.x, p.y, pressure]);
    }
  }
  if (mainArcPts.length >= 4) {
    brush.set("razor_highlight", "#ffffff", 1.15);
    brush.spline(mainArcPts, 0.5);

    // Second surgical pass over the central focal curve for blinding pure-white brilliance
    let coreArcPts = mainArcPts.slice(12, mainArcPts.length - 14);
    if (coreArcPts.length >= 4) {
      brush.set("razor_highlight", "#ffffff", 0.95);
      brush.spline(coreArcPts, 0.5);
      brush.set("rotring", "#ffffff", 0.75);
      brush.spline(coreArcPts, 0.5);
    }
  }

  // Whisper-thin secondary capillary double-refraction glint 5.5px inside the primary arc
  let secondaryArcPts = [];
  for (let th = -22; th <= 18; th += 1.5) {
    let t = map(th, -22, 18, 0, 1);
    let pressure = 0.1 + 0.75 * sin(t * 180);
    let p = meniscusPt(th, -3.5);
    secondaryArcPts.push([p.x, p.y, pressure]);
  }
  if (secondaryArcPts.length >= 4) {
    brush.set("razor_highlight", "#f2f7ff", 0.45);
    brush.spline(secondaryArcPts, 0.5);
  }

  // 6D. Precise Curved Studio Window Reflection on the Liquid Surface (d from -82 to -48)
  // Concentrated realism on the otherwise unmodulated wine surface
  let winPanes = [
    { th1: -19.5, th2: -7.5 },
    { th1: -5.8,  th2: 5.5 }
  ];

  for (let pane of winPanes) {
    let panePts = buildArcBandPts(
      pane.th1, pane.th2, 14,
      (th) => -82,
      (th) => -50
    );

    // Soft cool periwinkle-white reflection wash on the dark wine surface
    brush.noStroke();
    brush.fillBleed(0.08, "in");
    brush.fillTexture(0.25, 0.35);
    brush.fill("#d8e6ff", 110);
    drawFilledShape(panePts, 0.35);

    // Brighter inner pane core
    let innerPanePts = buildArcBandPts(
      pane.th1 + 0.8, pane.th2 - 0.8, 12,
      (th) => -74,
      (th) => -52
    );
    brush.fill("#f2f7ff", 145);
    drawFilledShape(innerPanePts, 0.35);
    brush.noFill();

    // Razor-sharp pure white leading edge along the outer curve of the window reflection (d = -50)
    let leadingEdgePts = [];
    for (let th = pane.th1; th <= pane.th2; th += 1.2) {
      let p = meniscusPt(th, -50);
      leadingEdgePts.push([p.x, p.y]);
    }
    if (leadingEdgePts.length >= 4) {
      brush.set("optical_glow", "#ffffff", 0.55);
      brush.spline(leadingEdgePts, 0.45);
      brush.set("razor_highlight", "#ffffff", 0.82);
      brush.spline(leadingEdgePts, 0.45);
    }

    // Crisp trailing edge (d = -82)
    let trailingEdgePts = [];
    for (let th = pane.th1; th <= pane.th2; th += 1.2) {
      let p = meniscusPt(th, -82);
      trailingEdgePts.push([p.x, p.y]);
    }
    if (trailingEdgePts.length >= 4) {
      brush.set("razor_highlight", "#d0e2ff", 0.42);
      brush.spline(trailingEdgePts, 0.45);
    }
  }

  // Secondary tiny pinpoint catchlight near the upper-left meniscus curve
  let catchlightPts = [];
  for (let th = -44; th <= -37; th += 1.2) {
    let p = meniscusPt(th, -38);
    catchlightPts.push([p.x, p.y]);
  }
  if (catchlightPts.length >= 4) {
    brush.set("optical_glow", "#e3eeff", 0.45);
    brush.spline(catchlightPts, 0.45);
    brush.set("razor_highlight", "#ffffff", 0.65);
    brush.spline(catchlightPts, 0.45);
  }
}

// Hyperrealist Still Life: Half-Unwrapped Deli Sandwich in Crinkled Waxed Paper on a Stainless Counter
// Built with p5.js v2 + p5.brush in WEBGL

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);

  // Custom brush for razor-sharp fluorescent specular creases on waxed paper
  brush.add("fl_crease", {
    type: "default",
    weight: 0.45,
    scatter: 0.02,
    sharpness: 0.95,
    grain: 4,
    opacity: 245,
    spacing: 0.12,
    pressure: [0.2, 1.35, 0.15],
    noise: 0.15
  });

  // Custom brush for milky paraffin wax surface sheen
  brush.add("wax_rub", {
    type: "default",
    weight: 1.8,
    scatter: 0.65,
    sharpness: 0.2,
    grain: 18,
    opacity: 42,
    spacing: 0.35,
    pressure: [0.4, 1.0, 0.3],
    noise: 0.4
  });

  randomSeed(8472);
  noiseSeed(8472);
}

function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function lerpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function jitterPoly(pts, mag = 6, subdivisions = 1) {
  let current = pts.map(p => [p[0], p[1]]);
  for (let s = 0; s < subdivisions; s++) {
    let next = [];
    let stepMag = mag / Math.pow(1.7, s);
    for (let i = 0; i < current.length; i++) {
      let a = current[i];
      let b = current[(i + 1) % current.length];
      next.push(a);
      let mid = lerpPt(a, b, 0.5);
      let dx = b[0] - a[0];
      let dy = b[1] - a[1];
      let len = Math.hypot(dx, dy) || 1;
      let nx = -dy / len;
      let ny = dx / len;
      let nVal = (noise(mid[0] * 0.015, mid[1] * 0.015, s * 10 + i) - 0.5) * 2;
      next.push([mid[0] + nx * nVal * stepMag, mid[1] + ny * nVal * stepMag]);
    }
    current = next;
  }
  return current;
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#7F8C96");

  // STAGE 1: Stainless Steel Counter & High-Contrast Fluorescent Reflections
  drawStainlessCounter();

  // STAGE 2: High-Contrast Cast Shadows & Unfolded Waxed Paper Base Sheet
  drawCastShadowsAndBasePaper();

  // STAGE 3: Soft Pencil Underdrawing & Fogged Washes (The Veiled Right Half of the Sandwich)
  drawVeiledSandwichUnderdrawing();

  // STAGE 4: Milky, Semi-Opaque White Glazes Layered Thinly (The Waxed Paper Veil)
  drawMilkyWaxPaperGlazes();

  // STAGE 5: Grease Spots — Razor-Sharp Clarity Windows Where Oil Turns the Paper Clear
  drawGreaseSpotWindows();

  // STAGE 6: The Escaping Sandwich (Left / Center-Left) — Razor-Sharp Hyperrealism
  drawExposedSandwichSharp();

  // STAGE 7: Waxed Paper Over-Folds, Crisp Creases, Hard Fluorescent Highlights & Crumbs
  drawPaperCreasesAndHighlights();

  noLoop();
}

