    { pts: [[290, 750], [450, 765], [430, 980], [310, 960]], col: "#A85950", op: 60 },
    // Mustard ochre reflection streak
    { pts: [[340, 740], [470, 755], [450, 990], [360, 975]], col: "#C99838", op: 65 },
    // Faint lettuce green reflection
    { pts: [[220, 710], [350, 730], [330, 930], [240, 910]], col: "#9BA67C", op: 55 }
  ];
  for (let r of reflectionStreaks) {
    resetBrush();
    brush.fill(r.col, r.op);
    brush.fillBleed(0.45, "out");
    brush.fillTexture(0.3, 0.1);
    drawPoly(r.pts, 0.25);
  }

  // Brushed stainless steel horizontal grain (fine micro-striations across counter)
  resetBrush();
  for (let i = 0; i < 320; i++) {
    let y = random(8, 1192);
    // Avoid over-drawing inside the central sandwich core to save render time
    if (y > 330 && y < 780 && random() < 0.65) continue;

    let x1 = random(0, 900);
    let len = random(80, 420);
    let x2 = min(1200, x1 + len);
    let dy = (x2 - x1) * -0.015; // Slight perspective tilt of counter grain

    if (y > 195 && y < 305) {
      // Bright specular grain in the fluorescent reflection band
      brush.set("2H", random() < 0.6 ? "#F5F8FA" : "#9BA8B3", random(0.18, 0.38));
    } else if (y < 140 || y > 920 && (x1 < 280 || x1 > 820)) {
      // Dark steel grain in shadow zones
      brush.set("2H", random() < 0.5 ? "#0E1317" : "#34404B", random(0.2, 0.42));
    } else {
      // Mid-tone steel grain
      let col = random(["#4A5661", "#5E6B77", "#9AA6B0", "#B8C2CA", "#333D46"]);
      brush.set("2H", col, random(0.16, 0.35));
    }
    brush.line(x1, y, x2, y + dy);
  }

  // Subtle deli counter wear: a few crisp diagonal micro-scratches catching overhead light
  const scratches = [
    [[75, 420], [195, 448]],
    [[140, 890], [290, 845]],
    [[890, 980], [1060, 935]],
    [[960, 310], [1110, 342]],
    [[520, 1085], [690, 1058]],
    [[340, 210], [490, 232]],
    [[760, 185], [910, 168]]
  ];
  for (let s of scratches) {
    resetBrush();
    brush.set("rotring", "#323C45", 0.22);
    brush.line(s[0][0], s[0][1] + 1.5, s[1][0], s[1][1] + 1.5);
    brush.set("rotring", "#EDF2F5", 0.25);
    brush.line(s[0][0], s[0][1], s[1][0], s[1][1]);
  }
}

