  drawPoly([[285, 348], [375, 326], [475, 330], [458, 368], [335, 368]], 0.25);

  resetBrush();
  brush.mass("cpencil", "#EAE3D5", { precision: 0.65, strength: 0.35, gradient: 0.6 });
  drawPoly([[305, 338], [395, 322], [468, 326], [448, 355], [335, 355]], 0.25);

  // Baker's slash (scored ear in the rye crust) with dark blistered rim
