  // Diagonal cut face of the top bread slice (airy bone crumb)
  const topCrumbPts = [[232, 378], [355, 388], [472, 385], [488, 422], [355, 428], [228, 415]];
  resetBrush();
  brush.wash("#EBE3D5", 248);
  drawPoly(topCrumbPts, 0.08);

  // Bright bone highlight along the upper-left cut edge
  resetBrush();
  brush.wash("#FAF8F2", 225);
  drawPoly([[235, 380], [345, 388], [338, 408], [232, 402]], 0.08);

  // Subtle shadow gradient along the right side of the cut face (near the paper cuff)
  resetBrush();
