  brush.fillBleed(0.08, "in");
  drawPoly([[385, 386], [472, 385], [488, 422], [382, 425]], 0.08);

  // Porous bread alveoli (cellular air pockets) on the top bread cut face
  resetBrush();
  for (let i = 0; i < 95; i++) {
    let t = random(0.04, 0.96);
    let bx = lerp(236, 478, t);
