}

// =============================================================================
// STAGE 7: WAXED PAPER CREASES, HARD FLUORESCENT HIGHLIGHTS & FOREGROUND CRUMBS
// =============================================================================
function drawPaperCreasesAndHighlights() {
  resetBrush();

  // ---------------------------------------------------------------------------
  // 1. THE LEADING WAXED PAPER CUFF & TURNED-BACK LAPELS (x = 455..565)
  // ---------------------------------------------------------------------------
  const C1 = [512, 316];
  const C2 = [468, 418];
  const C3 = [498, 532];
  const C4 = [456, 648];
  const C5 = [528, 748];
  const C6 = [638, 812];

  // Narrow cast shadow thrown by the leading edge of the waxed paper onto the escaping sandwich
  const cuffShadows = [
    [[498, 316], [515, 316], [472, 420], [452, 418]],
    [[455, 418], [472, 418], [502, 534], [482, 534]],
    [[482, 532], [502, 532], [460, 650], [440, 648]],
    [[442, 648], [460, 648], [532, 750], [510, 752]]
  ];
  for (let cs of cuffShadows) {
    resetBrush();
    brush.fill("#1E1614", 125);
    brush.fillBleed(0.12, "out");
    drawPoly(cs, 0.05);
  }

  // Crisp triangular turned-back lapels along the leading edge of the waxed paper
  const cuffLapels = [
    { pts: [C1, [548, 368], C2], col: "#FAF9F5", op: 215 },
    { pts: [C2, [535, 472], C3], col: "#E3E7EA", op: 205 },
    { pts: [C3, [542, 595], C4], col: "#FFFFFF", op: 225 },
    { pts: [C4, [558, 692], C5], col: "#DCE1E5", op: 210 },
    { pts: [C5, [605, 765], C6], col: "#F5F3EC", op: 220 }
  ];
  for (let lp of cuffLapels) {
    resetBrush();
    brush.wash(lp.col, lp.op);
    drawPoly(lp.pts, 0);
  }

  // ---------------------------------------------------------------------------
  // 2. PRIMARY CRINKLE & CREASE NETWORK CATCHING HARD FLUORESCENT HIGHLIGHTS
  // ---------------------------------------------------------------------------
  // Helper to draw a hyperrealist waxed-paper crease:
  // A crisp cool-steel shadow trough paired immediately with a blazing white fluorescent ridge
  function drawCrease(p1, p2, weight = 0.85, shadowSide = 1, crinkleBranches = true) {
    let dx = p2[0] - p1[0];
    let dy = p2[1] - p1[1];
    let len = Math.hypot(dx, dy) || 1;
    let nx = (-dy / len) * shadowSide;
    let ny = (dx / len) * shadowSide;
    let mid = lerpPt(p1, p2, 0.5);
    let kink = [
      mid[0] + nx * random(-3.5, 3.5),
      mid[1] + ny * random(-3.5, 3.5)
    ];

    resetBrush();
    // Soft graphite/steel shadow alongside the ridge
    brush.set("2H", "#63707A", weight * 0.65);
    brush.spline([
      [p1[0] + nx * 2.2, p1[1] + ny * 2.2],
      [kink[0] + nx * 2.6, kink[1] + ny * 2.6],
      [p2[0] + nx * 2.2, p2[1] + ny * 2.2]
    ], 0.2);

    // Crisp dark micro-trough line
    brush.set("rotring", "#3E4852", weight * 0.42);
    brush.spline([
      [p1[0] + nx * 0.9, p1[1] + ny * 0.9],
      [kink[0] + nx * 1.1, kink[1] + ny * 1.1],
      [p2[0] + nx * 0.9, p2[1] + ny * 0.9]
    ], 0.2);

    // Hard fluorescent white highlight on the sharp wax crease ridge
    brush.set("fl_crease", "#FFFFFF", weight * 1.15);
    brush.spline([p1, kink, p2], 0.2);
    brush.set("rotring", "#FFFFFF", weight * 0.55);
    brush.spline([p1, kink, p2], 0.2);

    // Stress-whitened micro-crinkle crow's-feet branching off the vertices
    if (crinkleBranches) {
      for (let endPt of [p1, p2, kink]) {
        if (random() < 0.75) {
          let bAng = random(0, 360);
          let bLen = random(10, 28);
          let bEnd = [endPt[0] + cos(bAng) * bLen, endPt[1] + sin(bAng) * bLen];
          brush.set("rotring", "#74808A", 0.24);
          brush.line(endPt[0] + 0.8, endPt[1] + 0.8, bEnd[0] + 0.8, bEnd[1] + 0.8);
          brush.set("fl_crease", "#FFFFFF", weight * 0.65);
          brush.line(endPt[0], endPt[1], bEnd[0], bEnd[1]);
        }
      }
    }
  }

  // A. Blazing fluorescent highlights along the leading unwrapped cuff edge
  drawCrease(C1, C2, 1.25, 1, true);
  drawCrease(C2, C3, 1.35, -1, true);
  drawCrease(C3, C4, 1.40, 1, true);
  drawCrease(C4, C5, 1.25, -1, true);
  drawCrease(C5, C6, 1.15, 1, true);

  // Lapel inner fold creases
  drawCrease(C1, [548, 368], 0.9, -1, true);
  drawCrease([548, 368], C2, 0.95, 1, false);
  drawCrease(C2, [535, 472], 0.9, 1, true);
  drawCrease([535, 472], C3, 0.95, -1, false);
  drawCrease(C3, [542, 595], 1.05, -1, true);
  drawCrease([542, 595], C4, 1.0, 1, false);
  drawCrease(C4, [558, 692], 0.9, 1, true);
  drawCrease([558, 692], C5, 0.85, -1, false);

  // B. Facet ridge creases across the wrapped hood (some passing right over the grease spots!)
  const P1 = [635, 395];
  const P2 = [775, 435];
  const P3 = [615, 515];
  const P4 = [745, 535];
  const P5 = [885, 525];
  const P6 = [595, 645];
  const P7 = [735, 655];
  const P8 = [865, 645];
  const R1 = [685, 315];
  const R2 = [845, 355];
  const R3 = [965, 455];
  const R4 = [1025, 585];
  const R5 = [955, 725];
  const R6 = [815, 805];

  const hoodCreases = [
    // Major structural ridges over the sandwich dome
    [C1, P1, 1.0], [P1, R1, 0.95], [P1, P2, 1.05], [P2, R2, 0.9], [P2, R3, 0.85],
    [C2, P1, 1.1], [C2, P3, 1.15], [P1, P3, 0.95], [P3, P4, 1.1], [P2, P4, 0.95],
    [P4, P5, 1.0], [P2, P5, 0.85], [P5, R3, 0.9], [P5, R4, 0.95],
    [C3, P3, 1.2], [C3, P6, 1.1], [P3, P6, 1.05], [P6, P7, 1.0], [P4, P7, 0.95],
    [P7, P8, 0.95], [P5, P8, 0.9], [P8, R4, 0.9], [P8, R5, 0.95],
