  ];

  for (let hc of hoodCreases) {
    drawCrease(hc[0], hc[1], hc[2], random() < 0.5 ? 1 : -1, true);
  }

  // C. Creases across the unfolded front apron, left wing, and upper-left flap
  const baseCreases = [
    // Upper-left peeled-back flap
    [[148, 525], [285, 338], 0.95],
    [[285, 338], [515, 272], 1.05],
    [[515, 272], [685, 315], 0.9],
    [[285, 338], [320, 465], 0.85],
    [[515, 272], [495, 365], 0.9],
    // Left crumpled wing
    [[108, 662], [148, 525], 0.85],
    [[108, 662], [235, 695], 0.95],
    [[108, 662], [218, 888], 0.9],
    [[235, 695], [218, 888], 1.0],
    [[235, 695], [365, 805], 1.05],
    // Front apron crisp origami ridges
    [[218, 888], [365, 805], 1.1],
