    [[538, 1018], [695, 955], 1.15],
    [[545, 855], [695, 955], 1.0],
    [[545, 855], [735, 815], 1.05],
    [[695, 955], [892, 922], 1.0],
    [[735, 815], [892, 922], 1.05],
    // Right wing folds
    [[892, 922], [1088, 682], 0.95],
    [[735, 815], [895, 685], 0.95],
    [[895, 685], [1088, 682], 1.0],
    [[1088, 682], [975, 470], 0.85]
  ];

  for (let bc of baseCreases) {
    drawCrease(bc[0], bc[1], bc[2], random() < 0.5 ? 1 : -1, true);
