      resetBrush();
      brush.set("2H", "#6D7983", 0.28);
      brush.line(pA[0] + 1, pA[1] + 1, pB[0] + 1, pB[1] + 1);
      brush.set("fl_crease", "#FFFFFF", random(0.45, 0.85));
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }
  }

  // ---------------------------------------------------------------------------
  // 3. FOREGROUND INCIDENTS (Mustard Droplet, Shred of Lettuce, Rye Crumbs & Pepper)
  // ---------------------------------------------------------------------------
  // A. Glossy fallen mustard droplet on the front waxed paper apron at (445, 822)
  resetBrush();
  brush.wash("#593403", 215);
  drawPoly([[432, 820], [462, 816], [468, 834], [442, 840], [428, 830]], 0.4);
  resetBrush();
  brush.wash("#E0A222", 245);
  drawPoly([[430, 816], [460, 812], [465, 830], [440, 835], [426, 826]], 0.4);
  resetBrush();
  brush.wash("#F7D058", 230);
  drawPoly([[435, 818], [454, 815], [456, 825], [438, 828]], 0.4);
