function draw() {
  translate(-width / 2, -height / 2);
  randomSeed(4219);
  noiseSeed(8814);

  // 1. Base archival paper & subtle drop shadow under the instant-film print
  background("#ece8df");
  drawPaperSupportAndShadow();

  // 2. Inside the instant-film emulsion window (strictly clipped)
  brush.clip([FRAME.ix1, FRAME.iy1, FRAME.ix2, FRAME.iy2]);
  drawDuskSkyAndHorizon();
  drawDustyCarHood();
  drawHoodReflectionsAndShadow();
  drawWatermelonWedge();
  drawLooseSeedsAndDroplets();
  drawInstantFilmChemistry();
  brush.noClip();

  // 3. Thick off-white instant-film border, crisp pencil lines, thumbprint & marker scrawl
  drawInstantFilmBorder();
  drawThumbprintSmudge(292, 988);
  drawMarkerScrawl(575, 992);

  noLoop();
}

// ============================================================================
// GEOMETRY & SHAPE HELPERS
// ============================================================================

function fillShapePoly(pts, col, opac, bleed = 0.08, tex = 0.25, curv = 0.08) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opac);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.15);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function washShapePoly(pts, col, opac, curv = 0.05) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, opac);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

