function hoodRearEdgeY(x) {
  // Subtle curved windshield cowling / rear edge of the hood
  let t = (x - 210) / 780;
  return 318 + 68 * t + 14 * sin(t * 180);
}

function hoodCreaseY(x) {
  // Central sculptural crown ridge of the vintage car hood
  let t = (x - 210) / 780;
  return 348 + 435 * t;
}

function drawDustyCarHood() {
  // Main hood body polygon
  let hoodPts = [];
  for (let x = 205; x <= 995; x += 40) {
    hoodPts.push([x, hoodRearEdgeY(x)]);
  }
  hoodPts.push([995, 890]);
  hoodPts.push([205, 890]);
  washShapePoly(hoodPts, "#557c89", 245, 0.02);

  // Upper-right hood plane (tilted toward the pale dusk sky — dusty sky-blue highlight)
  let upperPlane = [];
  for (let x = 205; x <= 995; x += 40) {
    upperPlane.push([x, hoodRearEdgeY(x)]);
  }
  upperPlane.push([995, hoodCreaseY(995)]);
  upperPlane.push([205, hoodCreaseY(205)]);
