    brush.set("glaze", col, random(0.9, 1.65));
    brush.line(x1, y1 + random(-5, 5), x2, y2 + random(-5, 5));
  }

  // Sculptural hood crown ridge highlight & shadow edge (classic automotive sheet-metal crease)
  for (let i = 0; i < 6; i++) {
    let off = (i - 2.5) * 2.2;
    let col = i < 3 ? "#e4eff2" : "#2b4d57";
