  // Rear hood cowling panel gap / seam line separating the hood from the cowl/windshield base
  let seamPtsDark = [];
  let seamPtsLight = [];
  for (let x = 205; x <= 995; x += 65) {
    let sy = hoodRearEdgeY(x);
