  brush.set("fine_needle", "#0f2228", 1.35);
  brush.spline(seamPtsDark, 0.25);
  brush.set("wet_spec", "#d8e9ed", 0.65);
  brush.spline(seamPtsLight, 0.25);

  // Subtle windshield wiper cowl louver shadow in the upper-right above the hood seam
  brush.set("glaze", "#193038", 0.65);
  brush.spline([
    [520, hoodRearEdgeY(520) - 12, 0.3],
    [730, hoodRearEdgeY(730) - 15, 0.8],
