// Parametric helper for the curved bottom arcs of the wedge
function melonArcPt(t, yApexOffset, depth) {
  // t from 0 (left corner) to 1 (right corner)
  let xL = 372, yL = 548;
  let xR = 824, yR = 528;
  let x = lerp(xL, xR, t);
  let baseLineY = lerp(yL, yR, t) + yApexOffset;
  let sag = sin(t * 180) * depth;
  // Slight organic asymmetry so it feels like real cut fruit
  let asym = sin(t * 360) * 5.5;
  return [x, baseLineY + sag + asym];
}

function drawWatermelonWedge() {
  // Key 3D vertices of the cut watermelon wedge:
  // Front apex: (588, 338), Rear 3D bevel apex: (536, 332)
  // Front-left corner: (372, 548), Rear-left 3D corner: (322, 518)
  // Front-right corner: (824, 528)

  // --------------------------------------------------------------------------
  // A. OUTER DARK CYAN-GREEN RIND (Underside & 3D Left Curve)
  // --------------------------------------------------------------------------
  let outerRindPts = [
    [322, 518],
    [372, 548]
  ];
  for (let i = 1; i <= 16; i++) {
    let t = i / 16;
    outerRindPts.push(melonArcPt(t, 12, 104));
  }
  outerRindPts.push([832, 542]);
  for (let i = 16; i >= 0; i--) {
    let t = i / 16;
    outerRindPts.push(melonArcPt(t, 36, 118));
  }
  outerRindPts.push([316, 548]);

  fillShapePoly(outerRindPts, "#153035", 240, 0.06, 0.35, 0.12);

  // Mottled pale-sage watermelon rind stripes along the dark green skin
  for (let s = 0; s < 5; s++) {
    let t0 = 0.08 + s * 0.19;
    let t1 = t0 + 0.09;
    let pA = melonArcPt(t0, 16, 108);
    let pB = melonArcPt(t1, 16, 108);
    let pC = melonArcPt(t1, 33, 116);
    let pD = melonArcPt(t0, 33, 116);
    fillShapePoly([pA, pB, pC, pD], "#486e70", 135, 0.18, 0.3, 0.15);
  }

  // Deep shadow along the bottom-most turn of the green rind
  let rindShadowPts = [];
  for (let i = 0; i <= 14; i++) {
    rindShadowPts.push(melonArcPt(i / 14, 24, 112));
  }
  for (let i = 14; i >= 0; i--) {
    rindShadowPts.push(melonArcPt(i / 14, 36, 118));
  }
  fillShapePoly(rindShadowPts, "#0b1c20", 220, 0.08, 0.3, 0.12);

  // --------------------------------------------------------------------------
  // B. WHITE / CELADON-CREAM INNER RIND (Pith on Front & 3D Left Side)
  // --------------------------------------------------------------------------
  let whiteRindPts = [
    [322, 518],
    [350, 504],
    [372, 548]
  ];
  for (let i = 1; i <= 18; i++) {
    whiteRindPts.push(melonArcPt(i / 18, 0, 88));
  }
  for (let i = 18; i >= 0; i--) {
    whiteRindPts.push(melonArcPt(i / 18, 17, 106));
  }
  whiteRindPts.push([324, 536]);

  fillShapePoly(whiteRindPts, "#d7e4e0", 230, 0.1, 0.28, 0.12);

  // Subtle cool celadon-grey shading on the right side of the white rind
  let rindShadeRight = [];
  for (let i = 9; i <= 18; i++) {
    rindShadeRight.push(melonArcPt(i / 18, 2, 90));
  }
  for (let i = 18; i >= 9; i--) {
    rindShadeRight.push(melonArcPt(i / 18, 17, 106));
  }
  fillShapePoly(rindShadeRight, "#9ab5b3", 165, 0.18, 0.28, 0.12);

  // Overexposed bright highlight on the left-side white rind catching dusk sky light
  fillShapePoly([
    [325, 518],
    [372, 548],
    melonArcPt(0.32, 3, 90),
    melonArcPt(0.32, 15, 103),
    [332, 538]
  ], "#f2f6f4", 195, 0.15, 0.2, 0.1);

  // --------------------------------------------------------------------------
  // C. 3D LEFT BEVEL PLANE OF THE WATERMELON FLESH (Grazing Overexposed Light)
  // --------------------------------------------------------------------------
  let leftBevelPts = [
    [536, 332],
    [588, 338],
    [372, 548],
    [346, 508]
  ];
  fillShapePoly(leftBevelPts, "#eb6e82", 235, 0.08, 0.32, 0.06);

  // Blown warm-magenta highlight along the upper 3D bevel plane (instant film overexposure)
  fillShapePoly([
    [536, 332],
    [588, 338],
    [465, 458],
    [425, 432]
  ], "#fad3dc", 210, 0.18, 0.22, 0.08);

  fillShapePoly([
    [544, 335],
    [584, 340],
    [515, 408],
    [482, 392]
  ], "#fff0f3", 195, 0.15, 0.18, 0.08);

  // --------------------------------------------------------------------------
  // D. MAIN FRONT CUT FACE OF THE WATERMELON FLESH
  // --------------------------------------------------------------------------
  let frontFleshPts = [
    [588, 338],
    [824, 528]
  ];
  for (let i = 17; i >= 0; i--) {
    frontFleshPts.push(melonArcPt(i / 18, 0, 88));
  }
  // Base vibrant watermelon crimson-coral fill
  fillShapePoly(frontFleshPts, "#c93049", 242, 0.09, 0.38, 0.08);

  // Deep saturated ruby-crimson core in the juicy lower-center and right belly
  let bellyPts = [
    [592, 418],
    [792, 522]
  ];
  for (let i = 15; i >= 3; i--) {
    bellyPts.push(melonArcPt(i / 18, -4, 82));
  }
  bellyPts.push([435, 512]);
  fillShapePoly(bellyPts, "#9c1b31", 205, 0.22, 0.42, 0.12);

  // Even deeper cool crimson-plum shadow zone near the lower-right rind turn
  fillShapePoly([
    [615, 488],
    [806, 526],
    melonArcPt(0.85, -2, 85),
    melonArcPt(0.55, -3, 84)
  ], "#6e1425", 175, 0.25, 0.38, 0.12);

  // Warm magenta-blown highlight zone across the upper apex & upper-left face
  fillShapePoly([
    [588, 338],
    [712, 438],
    [585, 482],
    [418, 505],
    [372, 548]
  ], "#ec667b", 190, 0.26, 0.3, 0.1);

  fillShapePoly([
    [588, 338],
    [668, 404],
    [558, 438],
    [455, 468]
  ], "#f7a3b2", 185, 0.28, 0.24, 0.1);

  // Overexposed crystalline tip at the top apex of the wedge
  fillShapePoly([
    [588, 338],
    [632, 376],
    [572, 392],
    [528, 398]
  ], "#fde3e8", 200, 0.22, 0.2, 0.12);

  // --------------------------------------------------------------------------
  // E. SOFT BLEED TRANSITION BETWEEN RED FLESH & CELADON-WHITE RIND
  // --------------------------------------------------------------------------
  for (let i = 0; i < 18; i++) {
    let t0 = i / 18;
    let t1 = (i + 1) / 18;
    let p0 = melonArcPt(t0, -2, 86);
    let p1 = melonArcPt(t1, -2, 86);
    let col = t0 < 0.45 ? "#f09aa8" : (t0 < 0.75 ? "#df7586" : "#b85c6b");
    brush.set("glaze", col, random(0.55, 0.95));
    brush.line(p0[0], p0[1], p1[0], p1[1]);

    let p2 = melonArcPt(t0, 4, 92);
    let p3 = melonArcPt(t1, 4, 92);
    brush.set("glaze", "#dce8e3", random(0.45, 0.8));
    brush.line(p2[0], p2[1], p3[0], p3[1]);
  }

  // --------------------------------------------------------------------------
  // F. CELLULAR SUGARY TEXTURE & RADIAL VASCULAR STRIATIONS
  // --------------------------------------------------------------------------
  // 1. Granular cellular flesh buildup using custom "flesh_grain" brush
  const fleshZones = [
    // Upper blown magenta zone
    { count: 95, tMin: 0.05, tMax: 0.55, rMin: 0.04, rMax: 0.48, cols: ["#fad4dc", "#f49eae", "#eb6b80"] },
    // Mid coral-crimson zone
    { count: 140, tMin: 0.06, tMax: 0.92, rMin: 0.35, rMax: 0.78, cols: ["#de435b", "#c72c45", "#ef7a8e", "#b02138"] },
    // Lower deep ruby zone near the rind
    { count: 120, tMin: 0.12, tMax: 0.95, rMin: 0.65, rMax: 0.97, cols: ["#8f182c", "#a82238", "#6e1222", "#c4354c"] }
  ];

  for (let z of fleshZones) {
    for (let i = 0; i < z.count; i++) {
      let t = random(z.tMin, z.tMax);
      let r = random(z.rMin, z.rMax);
      let rimPt = melonArcPt(t, -4, 84);
      let px = lerp(588, rimPt[0], r);
      let py = lerp(342, rimPt[1], r);

      let col = random(z.cols);
      brush.set("flesh_grain", col, random(0.55, 1.35));
      let ang = atan2(rimPt[1] - 342, rimPt[0] - 588) + random(-25, 25);
      let len = random(6, 18);
      brush.line(px, py, px + cos(ang) * len, py + sin(ang) * len);
    }
  }

  // Texture on the 3D left bevel plane as well
  for (let i = 0; i < 65; i++) {
    let u = random(0.05, 0.95);
    let v = random(0.1, 0.9);
    let topX = lerp(536, 588, v);
    let topY = lerp(332, 338, v);
    let botX = lerp(346, 372, v);
    let botY = lerp(508, 548, v);
    let px = lerp(topX, botX, u);
    let py = lerp(topY, botY, u);
    let col = u < 0.45 ? random(["#fff0f3", "#fad3dc", "#f39aa9"]) : random(["#eb6b80", "#d64960", "#f5b1be"]);
    brush.set("flesh_grain", col, random(0.5, 1.1));
    brush.line(px, py, px - random(4, 11), py + random(4, 11));
  }

  // 2. Subtle radial vascular striations & fibrous fracture clefts in the flesh
  for (let i = 0; i < 26; i++) {
    let t = map(i, 0, 25, 0.08, 0.92) + random(-0.015, 0.015);
    let rimPt = melonArcPt(t, -3, 85);
    let rStart = random(0.18, 0.42);
    let rMid = lerp(rStart, 0.96, 0.52);
    let x1 = lerp(588, rimPt[0], rStart);
    let y1 = lerp(342, rimPt[1], rStart);
    let x2 = lerp(588, rimPt[0], rMid) + random(-8, 8);
    let y2 = lerp(342, rimPt[1], rMid) + random(-5, 5);
    let x3 = lerp(588, rimPt[0], 0.96);
    let y3 = lerp(342, rimPt[1], 0.96);

    let veinCol = t < 0.45 ? "#f7b0be" : "#df566c";
    brush.set("fine_needle", veinCol, random(0.55, 1.1));
    brush.spline([
      [x1, y1, 0.3],
      [x2, y2, 0.85],
      [x3, y3, 0.4]
    ], 0.25);
  }

  // Two subtle natural tension clefts (small dark crimson sugary cracks near the center of the wedge)
  const clefts = [
    [[545, 442, 0.3], [568, 468, 1.0], [585, 498, 0.3]],
    [[625, 458, 0.3], [642, 488, 0.95], [652, 518, 0.3]]
  ];
  for (let cl of clefts) {
    brush.set("fine_needle", "#520b18", 1.25);
    brush.spline(cl, 0.25);
    brush.set("wet_spec", "#fcd8e0", 0.65);
    brush.spline([
      [cl[0][0] + 1.8, cl[0][1], 0.3],
      [cl[1][0] + 2.2, cl[1][1], 0.9],
      [cl[2][0] + 1.8, cl[2][1], 0.3]
    ], 0.25);
  }

  // --------------------------------------------------------------------------
  // G. PHOTOREALISTIC SEEDS (EMBEDDED, SURFACE & EMPTY SEED CAVITIES)
  // --------------------------------------------------------------------------
  // 1. Subsurface / partially embedded seeds (muted rose-plum silhouettes under translucent flesh)
  const embeddedSeeds = [
    { t: 0.22, r: 0.62, ang: 128, s: 0.95 },
    { t: 0.34, r: 0.56, ang: 115, s: 0.9 },
    { t: 0.48, r: 0.60, ang: 96,  s: 1.0 },
    { t: 0.63, r: 0.58, ang: 78,  s: 0.95 },
    { t: 0.77, r: 0.64, ang: 60,  s: 0.9 },
    { t: 0.29, r: 0.77, ang: 118, s: 0.88 },
    { t: 0.56, r: 0.79, ang: 84,  s: 0.92 },
    { t: 0.71, r: 0.78, ang: 68,  s: 0.9 }
  ];

  for (let es of embeddedSeeds) {
    let rimPt = melonArcPt(es.t, -4, 84);
    let sx = lerp(588, rimPt[0], es.r);
    let sy = lerp(342, rimPt[1], es.r);
    drawEmbeddedSeed(sx, sy, es.ang, es.s);
  }

  // 2. Empty seed sockets / cavities (where a seed fell out when the knife sliced through)
  const cavities = [
    { t: 0.26, r: 0.68, ang: 122, s: 1.0 },
    { t: 0.52, r: 0.67, ang: 90,  s: 1.05 },
    { t: 0.68, r: 0.71, ang: 70,  s: 0.95 },
    { t: 0.41, r: 0.78, ang: 104, s: 0.92 }
  ];
  for (let cv of cavities) {
    let rimPt = melonArcPt(cv.t, -4, 84);
    let cx = lerp(588, rimPt[0], cv.r);
    let cy = lerp(342, rimPt[1], cv.r);
    drawSeedCavity(cx, cy, cv.ang, cv.s);
  }

  // 3. Crisp, glossy surface seeds arranged along the natural ovule arcs
  const surfaceSeeds = [
    // Upper ovule arc
    { t: 0.18, r: 0.69, ang: 132, s: 1.02 },
    { t: 0.31, r: 0.64, ang: 118, s: 1.08 },
    { t: 0.43, r: 0.65, ang: 102, s: 1.12 },
    { t: 0.58, r: 0.66, ang: 82,  s: 1.1 },
    { t: 0.73, r: 0.67, ang: 64,  s: 1.05 },
    { t: 0.84, r: 0.70, ang: 50,  s: 0.96 },
    // Lower ovule arc closer to the rind
    { t: 0.23, r: 0.81, ang: 125, s: 0.98 },
    { t: 0.36, r: 0.80, ang: 112, s: 1.06 },
    { t: 0.49, r: 0.82, ang: 92,  s: 1.08 },
    { t: 0.64, r: 0.81, ang: 74,  s: 1.04 },
    { t: 0.79, r: 0.82, ang: 58,  s: 0.98 },
    // One seed peeking on the 3D left bevel plane
    { x: 422, y: 472, ang: 136, s: 0.92 }
  ];

  for (let sd of surfaceSeeds) {
    let sx = sd.x;
    let sy = sd.y;
    if (sx === undefined) {
      let rimPt = melonArcPt(sd.t, -4, 84);
      sx = lerp(588, rimPt[0], sd.r);
      sy = lerp(342, rimPt[1], sd.r);
    }
    drawSurfaceSeed(sx, sy, sd.ang, sd.s);
  }

  // --------------------------------------------------------------------------
  // H. WET CRYSTALLINE SPECULAR HIGHLIGHTS ON THE FLESH & RIND
  // --------------------------------------------------------------------------
  // Crisp ridge highlight where the front cut face meets the 3D left bevel plane
  brush.set("wet_spec", "#fff2f5", 0.95);
  brush.spline([
    [588, 338, 0.9],
    [522, 402, 1.1],
    [445, 478, 0.85],
    [372, 548, 0.4]
  ], 0.12);

  // Sparkling sugar-cell micro-highlights scattered across the wet flesh (concentrated toward upper/left light)
  for (let i = 0; i < 195; i++) {
    let t = random(0.05, 0.88);
    let r = pow(random(0.05, 0.95), 1.25); // Bias slightly toward upper apex
    let rimPt = melonArcPt(t, -5, 83);
    let hx = lerp(588, rimPt[0], r);
    let hy = lerp(342, rimPt[1], r);

    let isBright = (t < 0.55 && r < 0.65) || random() < 0.35;
    let col = isBright ? "#fff3f6" : "#f9bec9";
    let w = isBright ? random(0.45, 0.95) : random(0.3, 0.65);

    brush.set("wet_spec", col, w);
    let dx = random(-2.8, 2.8);
    let dy = random(-1.8, 2.2);
    brush.line(hx, hy, hx + dx, hy + dy);
  }

  // Wet meniscus highlight along the translucent celadon-white inner rind
  let rindSpecPts = [];
  for (let i = 1; i <= 12; i++) {
    let p = melonArcPt(i / 18, 6, 94);
    rindSpecPts.push([p[0], p[1], i < 7 ? 0.95 : 0.45]);
  }
  brush.set("wet_spec", "#f5fbf9", 0.85);
  brush.spline(rindSpecPts, 0.25);

  // Crisp contour accents along the outer silhouette of the wedge
  brush.set("fine_needle", "#fad8e0", 0.9);
  brush.line(536, 332, 588, 338);
  brush.line(536, 332, 322, 518);

  brush.set("fine_needle", "#7a1426", 0.85);
  brush.line(588, 338, 824, 528);
}

function getTeardropPoints(cx, cy, angDeg, scaleVal) {
  // Pointed end at (-L, 0), rounded belly at (+L, 0) rotated by angDeg
  let L = 10.5 * scaleVal;
  let W = 5.4 * scaleVal;
  let raw = [
    [-L, 0],
    [-L * 0.35, -W * 0.58],
    [L * 0.35, -W],
    [L, 0],
    [L * 0.35, W],
    [-L * 0.35, W * 0.58]
  ];
  let pts = [];
  let ca = cos(angDeg);
  let sa = sin(angDeg);
  for (let p of raw) {
    pts.push([
      cx + p[0] * ca - p[1] * sa,
      cy + p[0] * sa + p[1] * ca
    ]);
  }
  return pts;
}

function drawEmbeddedSeed(cx, cy, angDeg, s) {
  let pts = getTeardropPoints(cx, cy, angDeg, s);
  fillShapePoly(pts, "#6e2133", 145, 0.18, 0.25, 0.25);
  let innerPts = getTeardropPoints(cx, cy, angDeg, s * 0.7);
  fillShapePoly(innerPts, "#4d1422", 130, 0.15, 0.2, 0.25);
}

function drawSeedCavity(cx, cy, angDeg, s) {
  let pts = getTeardropPoints(cx, cy, angDeg, s * 0.95);
  fillShapePoly(pts, "#590d1b", 205, 0.1, 0.3, 0.25);

  // Wet glistening rim around the lower edge of the cavity
  let ca = cos(angDeg);
  let sa = sin(angDeg);
  brush.set("wet_spec", "#fcd7df", 0.65);
  brush.spline([
    [cx - 6 * s * ca - 3 * s * sa, cy - 6 * s * sa + 3 * s * ca, 0.3],
    [cx + 2 * s * ca - 5 * s * sa, cy + 2 * s * sa + 5 * s * ca, 0.95],
    [cx + 8 * s * ca - 1 * s * sa, cy + 8 * s * sa + 1 * s * ca, 0.3]
  ], 0.3);
}

function drawSurfaceSeed(cx, cy, angDeg, s) {
  // 1. Deep ruby-black wet socket depression around the seed
  let socketPts = getTeardropPoints(cx + 0.8, cy + 1.4, angDeg, s * 1.18);
  fillShapePoly(socketPts, "#4a0915", 215, 0.08, 0.25, 0.25);

  // 2. Main seed body: deep cyan-charcoal / espresso-black
  let bodyPts = getTeardropPoints(cx, cy, angDeg, s);
  fillShapePoly(bodyPts, "#111c20", 248, 0.03, 0.2, 0.25);

  // Subtle warm mahogany-slate midtone in the center of the seed shell
  let midPts = getTeardropPoints(cx - 0.5, cy - 0.5, angDeg, s * 0.68);
  fillShapePoly(midPts, "#243136", 190, 0.05, 0.2, 0.25);

  // Crisp outline of the seed
  brush.set("fine_needle", "#070f12", 1.05);
  brush.beginShape(0.25);
  for (let p of bodyPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);

  let ca = cos(angDeg);
  let sa = sin(angDeg);

  // 3. Razor-sharp wet specular highlight arc along the upper-left curve of the seed
  brush.set("wet_spec", "#eef7f8", 0.72 * s);
  brush.spline([
    [cx - 6.5 * s * ca + 1.8 * s * sa, cy - 6.5 * s * sa - 1.8 * s * ca, 0.3],
    [cx + 1.5 * s * ca + 3.2 * s * sa, cy + 1.5 * s * sa - 3.2 * s * ca, 1.0],
    [cx + 7.2 * s * ca + 1.2 * s * sa, cy + 7.2 * s * sa - 1.2 * s * ca, 0.4]
  ], 0.3);

  // 4. Tiny glistening meniscus bead where wet pink juice hugs the seed edge
  brush.set("wet_spec", "#ffdbe3", 0.55 * s);
  brush.line(
    cx + 2 * s * ca - 4.8 * s * sa,
    cy + 2 * s * sa + 4.8 * s * ca,
    cx + 6.5 * s * ca - 3.2 * s * sa,
    cy + 6.5 * s * sa + 3.2 * s * ca
  );
}

