function drawInstantFilmBorder() {
  const { ox1, oy1, ox2, oy2, ix1, iy1, ix2, iy2 } = FRAME;

  // 1. Clean off-white wash for the 4 border panels of the instant-film mask
  // Top border
  washShapePoly([[ox1, oy1], [ox2, oy1], [ox2, iy1], [ox1, iy1]], "#f7f5ef", 252, 0);
  // Bottom wide border
  washShapePoly([[ox1, iy2], [ox2, iy2], [ox2, oy2], [ox1, oy2]], "#f7f5ef", 252, 0);
  // Left border
  washShapePoly([[ox1, iy1], [ix1, iy1], [ix1, iy2], [ox1, iy2]], "#f7f5ef", 252, 0);
  // Right border
  washShapePoly([[ix2, iy1], [ox2, iy1], [ox2, iy2], [ix2, iy2]], "#f7f5ef", 252, 0);

  // Subtle warm-cool paper/plastic shading on the lower pod-bulge margin of the Polaroid
  fillShapePoly([
    [ox1 + 4, iy2 + 4],
    [ox2 - 4, iy2 + 4],
    [ox2 - 4, iy2 + 24],
    [ox1 + 4, iy2 + 24]
  ], "#e3e1da", 110, 0.22, 0.2, 0.02);

  fillShapePoly([
    [ox1 + 4, oy2 - 22],
    [ox2 - 4, oy2 - 22],
    [ox2 - 4, oy2 - 2],
    [ox1 + 4, oy2 - 2]
  ], "#e5e2da", 95, 0.22, 0.2, 0.02);

  // Very delicate graphite hatch along the extreme right & bottom bevel of the white border
  brush.hatchStyle("2H", "#b5b8ba", 0.55);
  brush.hatch(9, 35, { rand: 0.04 });
  brush.noStroke();
  brush.noFill();
  brush.rect(ox2 - 14, oy1 + 10, 12, oy2 - oy1 - 20, "corner");
  brush.noHatch();

  // 2. Inner window bevel lip (the thickness of the die-cut paper mask around the emulsion)
  // Top & left inner edges catch shadow; bottom & right inner edges catch crisp white light
  brush.set("2H", "#8a9194", 0.9);
  brush.line(ix1 - 2.5, iy1 - 2.5, ix2 + 2.5, iy1 - 2.5);
  brush.line(ix1 - 2.5, iy1 - 2.5, ix1 - 2.5, iy2 + 2.5);

  brush.set("wet_spec", "#ffffff", 0.9);
  brush.line(ix1 - 1.5, iy2 + 2, ix2 + 2, iy2 + 2);
  brush.line(ix2 + 2, iy1 - 1.5, ix2 + 2, iy2 + 2);

  // 3. Crisp Pencil Drawing of the Inner Window Frame (HB & 2B)
  brush.set("HB", "#33393c", 1.05);
  brush.line(ix1, iy1, ix2, iy1);
  brush.line(ix2, iy1, ix2, iy2);
  brush.line(ix2, iy2, ix1, iy2);
  brush.line(ix1, iy2, ix1, iy1);

  // Second crisp hair-line pass with sharp 2H pencil for architectural precision
  brush.set("2H", "#525a5e", 0.75);
  brush.line(ix1 - 3, iy1 - 0.5, ix2 + 3, iy1 - 0.5);
  brush.line(ix2 + 0.5, iy1 - 3, ix2 + 0.5, iy2 + 3);
  brush.line(ix2 + 3, iy2 + 0.5, ix1 - 3, iy2 + 0.5);
  brush.line(ix1 - 0.5, iy2 + 3, ix1 - 0.5, iy1 - 3);

  // 4. Crisp Pencil Drawing of the Outer Instant-Film Card Border (with classic rounded corners)
  const r = 10;
  // Top edge
  brush.set("HB", "#2d3336", 1.15);
  brush.line(ox1 + r, oy1, ox2 - r, oy1);
  // Right edge
  brush.line(ox2, oy1 + r, ox2, oy2 - r);
  // Bottom edge (slightly heavier weight to ground the card)
  brush.set("2B", "#23282b", 1.25);
  brush.line(ox2 - r, oy2, ox1 + r, oy2);
  // Left edge
  brush.set("HB", "#2d3336", 1.1);
  brush.line(ox1, oy2 - r, ox1, oy1 + r);

  // Rounded corners of the outer card
  brush.set("HB", "#2d3336", 1.1);
  brush.arc(ox1 + r, oy1 + r, r, 180, 270);
  brush.arc(ox2 - r, oy1 + r, r, 270, 360);
  brush.arc(ox2 - r, oy2 - r, r, 0, 90);
  brush.arc(ox1 + r, oy2 - r, r, 90, 180);

  // Second crisp 2H construction line & subtle drafter's corner whispers
  brush.set("2H", "#6c7378", 0.65);
  brush.line(ox1 - 6, oy1, ox2 + 6, oy1);
  brush.line(ox2, oy1 - 6, ox2, oy2 + 6);
  brush.line(ox2 + 6, oy2, ox1 - 6, oy2);
  brush.line(ox1, oy2 + 6, ox1, oy1 - 6);

  // Authentic Polaroid die-cut diagonal fold seams at the 4 corners of the border mask
  brush.set("2H", "#9ba1a4", 0.65);
  // Top-left & top-right subtle mask seams
  brush.line(ox1 + 2, oy1 + 18, ix1, iy1 + 12);
  brush.line(ox2 - 2, oy1 + 18, ix2, iy1 + 12);
  // Bottom-left & bottom-right chemical pod mask seams
  brush.line(ox1 + 2, iy2 + 16, ix1, iy2);
  brush.line(ox2 - 2, iy2 + 16, ix2, iy2);

  // Subtle horizontal embossing crease near the bottom edge of the lower margin
  brush.set("2H", "#b2b7ba", 0.55);
  brush.line(ox1 + 18, oy2 - 18, ox2 - 18, oy2 - 18);
}

