function drawThumbprintSmudge(cx, cy) {
  // 1. Soft smudged graphite & faint developer-chemistry stain where a thumb gripped the wet print
  push();
  translate(cx, cy);
  rotate(-16);

  // Faint warm-pinkish developer trace mixed with cool graphite smudge
  fillShapePoly([
    [-26, -18], [-8, -32], [16, -28], [28, -8],
    [25, 18], [8, 34], [-15, 30], [-28, 10]
  ], "#d8c8cc", 75, 0.35, 0.35, 0.25);

  fillShapePoly([
    [-22, -14], [-5, -26], [14, -22], [22, -4],
    [18, 16], [4, 26], [-12, 22], [-22, 6]
  ], "#b4bcbf", 95, 0.32, 0.4, 0.25);

  // Whorled dermatoglyphic friction ridges rendered in delicate 2H/HB pencil & fine_needle
  for (let r = 3.5; r <= 27; r += 2.35) {
    let rx = r * 0.78;
    let ry = r * 1.08;
    // Draw broken oval ridge arcs to mimic a real human thumbprint whorl
    let segs = 3;
    for (let s = 0; s < segs; s++) {
      let aStart = s * 120 + random(-18, 18);
      let aEnd = aStart + random(55, 88);
      let pts = [];
      for (let a = aStart; a <= aEnd; a += 15) {
        let px = cos(a) * rx + sin(a * 2) * 0.6;
        let py = sin(a) * ry + (r - 14) * 0.12;
        pts.push([px, py, random(0.35, 0.9)]);
      }
      if (pts.length >= 2) {
        let isDarker = (r > 7 && r < 21) && random() < 0.6;
        brush.set("fine_needle", isDarker ? "#6e777b" : "#969fa3", random(0.45, 0.85));
        brush.spline(pts, 0.3);
      }
    }
  }

  // Directional graphite thumb drag smudge trailing slightly toward the bottom-left
  for (let i = 0; i < 14; i++) {
    brush.set("2H", "#9da5a8", random(0.4, 0.8));
    let ox = random(-18, 14);
    let oy = random(-16, 20);
    brush.line(ox, oy, ox - random(10, 26), oy + random(8, 22));
  }

  pop();
}

