// Hyperrealist Modernist Student Dormitory Elevation
// p5.js 2.x + p5.brush

const COLS = 3;
const ROWS = 2;
const MARGIN_X = 60;
const PIER_X = 60;
const WIN_W = 320;
const WIN_H = 460;
const ROW_Y = [65, 665];
const COL_X = [60, 440, 820];

// Helper: Reset all fill/wash/hatch/mass states
function resetStates() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

// Helper: Generate rotated ellipse points
function getEllipsePts(cx, cy, rx, ry, rotDeg = 0, steps = 28) {
  let pts = [];
  let cr = cos(rotDeg);
  let sr = sin(rotDeg);
  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let lx = rx * cos(ang);
    let ly = ry * sin(ang);
    let x = cx + lx * cr - ly * sr;
    let y = cy + lx * sr + ly * cr;
    pts.push([x, y]);
  }
  return pts;
}

// Helper: Generate arc points
function getArcPts(cx, cy, rx, ry, startDeg, endDeg, rotDeg = 0, steps = 18) {
  let pts = [];
  let cr = cos(rotDeg);
  let sr = sin(rotDeg);
  for (let i = 0; i <= steps; i++) {
    let ang = lerp(startDeg, endDeg, i / steps);
    let lx = rx * cos(ang);
    let ly = ry * sin(ang);
    let x = cx + lx * cr - ly * sr;
    let y = cy + lx * sr + ly * cr;
    pts.push([x, y]);
  }
  return pts;
}

// Helper: Watercolor filled polygon
function wcPoly(pts, col, alpha = 90, bleed = 0.12, tex = 0.45, border = 0.3, curv = 0.15) {
  resetStates();
  brush.noStroke();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetStates();
}

// Helper: Watercolor filled rectangle
function wcRect(x, y, w, h, col, alpha = 90, bleed = 0.1, tex = 0.45, border = 0.3) {
  resetStates();
  brush.noStroke();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.rect(x, y, w, h, "corner");
  resetStates();
}

// Helper: Fast opaque/translucent wash polygon
function washPoly(pts, col, alpha = 120, curv = 0.05) {
  resetStates();
  brush.noStroke();
  brush.wash(col, alpha);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetStates();
}

// Helper: Fast wash rectangle
function washRect(x, y, w, h, col, alpha = 120) {
  resetStates();
  brush.noStroke();
  brush.wash(col, alpha);
  brush.rect(x, y, w, h, "corner");
  resetStates();
}

// Helper: Hatched polygon
function hatchPoly(pts, brushName, col, weight, dist, angle, opts = { rand: 0.03 }, curv = 0) {
  resetStates();
  brush.noStroke();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetStates();
}

// Helper: Hatched rectangle
function hatchRect(x, y, w, h, brushName, col, weight, dist, angle, opts = { rand: 0.03 }) {
  hatchPoly(
    [
      [x, y],
      [x + w, y],
      [x + w, y + h],
      [x, y + h]
    ],
    brushName,
    col,
    weight,
    dist,
    angle,
    opts,
    0
  );
}

// Helper: Stroked polyline or closed shape
function strokePoly(pts, brushName, col, weight, closeShape = true, curv = 0) {
  resetStates();
  brush.set(brushName, col, weight);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

// Helper: Ruled pen line
function ruledLine(x1, y1, x2, y2, brushName = "rotring", col = "#11161C", weight = 0.5) {
  resetStates();
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(42719);
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#F5F4EE");
  brush.set("rotring", "#11161C", 0.5);

  // 1. Render the white architectural stucco facade
  drawWhiteRenderFacade();

  // 2. Render each of the 6 windows in the rigid 3x2 grid
  // Window (0,0): Reflected cloud
  // Window (0,1): Half-drawn blind
  // Window (0,2): Drooping towel
  // Window (1,0): Chipped mug on a sill
  // Window (1,1): Signal orange glow from lamp behind a curtain (main pane only)
  // Window (1,2): Desk lamp
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      let bx = COL_X[c];
      let by = ROW_Y[r];
      let idx = r * COLS + c;
      drawWindowVignette(bx, by, idx);
    }
  }

  // 3. Draw the architectural window reveals, concrete sills, and ruled-pen steel mullions
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      let bx = COL_X[c];
      let by = ROW_Y[r];
      let isOrangeWindow = (r === 1 && c === 1);
      drawWindowArchitectureAndMullions(bx, by, isOrangeWindow);
    }
  }

  // 4. Final surface unify: subtle facade joints, micro-grain, and glass highlights
  drawFinalArchitecturalDetails();

  noLoop();
}

// ============================================================================
// 1. WHITE RENDER FACADE
// ============================================================================
function drawWhiteRenderFacade() {
  // Subtle large tonal washes on the white stucco render (avoiding window cutouts)
  // Top band
  wcRect(0, 0, 1200, 68, "#EAECE6", 65, 0.15, 0.4, 0.2);
  // Middle spandrel band between floors
  wcRect(0, 525, 1200, 142, "#E6E9E4", 70, 0.15, 0.45, 0.25);
  // Bottom band
  wcRect(0, 1125, 1200, 75, "#DFE4E0", 85, 0.15, 0.45, 0.25);

  // Vertical piers
  let pierX = [
    [0, 62],
    [378, 64],
    [758, 64],
    [1138, 62]
  ];
  for (let p of pierX) {
    wcRect(p[0], 60, p[1], 470, "#ECEEE9", 55, 0.12, 0.4, 0.2);
    wcRect(p[0], 660, p[1], 470, "#E5E8E3", 65, 0.12, 0.4, 0.2);
  }

  // Warm limestone/ochre subtle weathering patches below sill zones
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      let sx = COL_X[c] - 8;
      let sy = ROW_Y[r] + WIN_H + 14;
      wcRect(sx, sy, WIN_W + 16, 26, "#DCE2EA", 55, 0.2, 0.5, 0.3);
    }
  }

  // Fine plaster stipple and mineral render texture across wall bands
  resetStates();
  let wallZones = [
    [0, 0, 1200, 65],
    [0, 525, 1200, 140],
    [0, 1125, 1200, 75],
    [0, 65, 60, 460],
    [380, 65, 60, 460],
    [760, 65, 60, 460],
    [1140, 65, 60, 460],
    [0, 665, 60, 460],
    [380, 665, 60, 460],
    [760, 665, 60, 460],
    [1140, 665, 60, 460]
  ];

  for (let z of wallZones) {
    let [zx, zy, zw, zh] = z;
    // Delicate dry horizontal trowel texture in 2H graphite
    hatchRect(zx, zy, zw, zh, "2H", "#D2D7DF", 0.35, 9, 0, { rand: 0.08 });
    // Sparse spray mineral grain
    let count = floor((zw * zh) / 3800);
    for (let i = 0; i < count; i++) {
      let px = random(zx + 4, zx + zw - 4);
      let py = random(zy + 4, zy + zh - 4);
      let len = random(6, 22);
      brush.set("spray", i % 2 === 0 ? "#C5CCD6" : "#FFFFFF", random(0.35, 0.65));
      brush.line(px, py, px + len, py + random(-2, 2));
    }
  }
}

// ============================================================================
// 2. WINDOW VIGNETTES & GRAPHITE-GREY WATERCOLOUR GLAZING
// ============================================================================
function drawWindowVignette(bx, by, idx) {
  // Window geometry constants
  let fx = bx + 12;
  let fy = by + 12;
  let gx = fx + 10; // bx + 22
  let gy = fy + 10; // by + 22
  let gw = 276;
  let gh = 422;

  // T-mullion split coordinates:
  // Top transom panes: gy to gy + 86 (height 86)
  // Horizontal transom mullion: gy + 86 to gy + 96 (10px)
  // Main lower pane: gy + 96 to gy + 422 (height 326)
  // Vertical transom mullion (top only): gx + 134 to gx + 142 (8px)
  let ty = gy + 86;
  let my = gy + 96;
  let mh = 326;
  let vx = gx + 134;

  // Clip strokes/hatches to the glazed area of this window
  brush.clip([gx - 2, gy - 2, gx + gw + 2, gy + gh + 2]);

  if (idx === 0) {
    drawVignetteReflectedCloud(gx, gy, gw, gh, ty, my, mh, vx);
  } else if (idx === 1) {
    drawVignetteHalfDrawnBlind(gx, gy, gw, gh, ty, my, mh, vx);
  } else if (idx === 2) {
    drawVignetteDroopingTowel(gx, gy, gw, gh, ty, my, mh, vx);
  } else if (idx === 3) {
    drawVignetteChippedMug(gx, gy, gw, gh, ty, my, mh, vx);
  } else if (idx === 4) {
    drawVignetteSignalOrangeCurtain(gx, gy, gw, gh, ty, my, mh, vx);
  } else if (idx === 5) {
    drawVignetteDeskLamp(gx, gy, gw, gh, ty, my, mh, vx);
  }

  brush.noClip();
}

// Common helper: base cool graphite-grey watercolor glazing for panes
function glazeCoolGraphitePane(x, y, w, h, darkness = 0) {
  let c1 = darkness > 0 ? "#1C242E" : "#25303D";
  let c2 = darkness > 0 ? "#283442" : "#344354";
  let c3 = "#46586C";

  // Layer 1: Deep graphite-slate wash
  wcRect(x, y, w, h, c1, 135, 0.08, 0.5, 0.35);
  // Layer 2: Cool graphite-grey midtone watercolor wash
  wcRect(x + 3, y + 3, w - 6, h - 6, c2, 95, 0.12, 0.55, 0.3);
  // Layer 3: Subtle lighter graphite-blue atmospheric bloom in lower-right
  wcPoly(
    [
      [x + w * 0.18, y + h * 0.25],
      [x + w, y + h * 0.08],
      [x + w, y + h],
      [x + w * 0.05, y + h]
    ],
    c3,
    55,
    0.15,
    0.45,
    0.25,
    0.1
  );
}

// Common helper: subtle diagonal glass reflections over panes
function drawGlassReflections(gx, gy, gw, gh, ty, my, mh, vx, opacityScale = 1.0) {
  // Primary diagonal reflection band across main pane
  let a1 = round(28 * opacityScale);
  let a2 = round(16 * opacityScale);

  // Main pane diagonal band 1
  washPoly(
    [
      [gx, my + 55],
      [gx + 75, my],
      [gx + 135, my],
      [gx, my + 125]
    ],
    "#DCEBFA",
    a1,
    0
  );
  // Main pane diagonal band 2 (wider, softer)
  washPoly(
    [
      [gx, my + 195],
      [gx + 215, my],
      [gx + gw, my],
      [gx + gw, my + 48],
      [gx + 35, my + mh],
      [gx, my + mh]
    ],
    "#E8F2FC",
    a2,
    0
  );
  // Crisp hairlines along the reflection edge
  ruledLine(gx, my + 195, gx + 215, my, "2H", "#F0F7FF", 0.35);
  ruledLine(gx + 35, my + mh, gx + gw, my + 48, "2H", "#D0E2F2", 0.3);

  // Top-left transom reflection
  washPoly(
    [
      [gx + 10, gy + 86],
      [gx + 92, gy],
      [gx + 128, gy],
      [gx + 46, gy + 86]
    ],
    "#E2F0FC",
    a1,
    0
  );

  // Top-right transom reflection
  washPoly(
    [
      [vx + 8, gy + 70],
      [vx + 78, gy],
      [vx + 108, gy],
      [vx + 38, gy + 86],
      [vx + 8, gy + 86]
    ],
    "#E2F0FC",
    a2,
    0
  );
}

// ----------------------------------------------------------------------------
// VIGNETTE 1 (Top-Left): THE REFLECTED CLOUD
// ----------------------------------------------------------------------------
function drawVignetteReflectedCloud(gx, gy, gw, gh, ty, my, mh, vx) {
  // 1. Base cool graphite-grey watercolor across all 3 panes
  glazeCoolGraphitePane(gx, gy, 134, 86, 1);
  glazeCoolGraphitePane(vx + 8, gy, 134, 86, 1);
  glazeCoolGraphitePane(gx, my, gw, mh, 1);

  // Faint submerged dorm room interior depth (ceiling line & dark bookshelf silhouette behind glass)
  washRect(gx + 18, my + 20, gw - 36, mh - 20, "#18202A", 55);
  washRect(gx + 185, my + 85, 75, 220, "#121820", 60);
  hatchRect(gx, my, gw, mh, "2H", "#1A222C", 0.35, 11, 90, { rand: 0.03 });

  // 2. Reflected patch of vivid saturated cerulean-cobalt sky in the glass
  wcPoly(
    [
      [gx, gy + 15],
      [gx + gw, gy],
      [gx + gw, my + 245],
      [gx + 165, my + 285],
      [gx, my + 225]
    ],
    "#1E5BB8",
    85,
    0.16,
    0.45,
    0.25,
    0.15
  );
  wcPoly(
    [
      [gx + 20, gy + 30],
      [gx + gw - 15, gy + 15],
      [gx + gw - 25, my + 195],
      [gx + 25, my + 180]
    ],
    "#3B82F6",
    75,
    0.18,
    0.4,
    0.2,
    0.2
  );

  // 3. Hyperreal Cumulus Cloud reflected across the main pane and transom panes
  // Note: Top-left transom is slightly tilted, so its reflection is offset by (+8, -10)
  let cloudShadows = [
    [gx + 135, my + 145, 112, 48],
    [gx + 85, my + 155, 68, 36],
    [gx + 195, my + 152, 65, 38],
    [gx + 140, my + 110, 95, 52]
  ];
  for (let s of cloudShadows) {
    wcPoly(getEllipsePts(s[0], s[1], s[2], s[3], -4, 24), "#475569", 95, 0.15, 0.5, 0.3, 0.2);
  }

  // Cloud mid-tone cool lavender/periwinkle billows
  let cloudMids = [
    [gx + 95, my + 95, 62, 50],
    [gx + 155, my + 78, 72, 58],
    [gx + 205, my + 112, 54, 44],
    [gx + 62, my + 125, 48, 36],
    [gx + 130, my + 128, 78, 42],
    // Upper transom continuation
    [gx + 118, gy + 64, 58, 38],
    [vx + 48, gy + 58, 56, 38]
  ];
  for (let m of cloudMids) {
    wcPoly(getEllipsePts(m[0], m[1], m[2], m[3], 0, 24), "#CBD5E1", 115, 0.14, 0.45, 0.25, 0.25);
  }

  // Sunlit cauliflower cloud domes (bright ivory and pure titanium white)
  let cloudLights = [
    [gx + 88, my + 78, 48, 42],
    [gx + 142, my + 56, 58, 48],
    [gx + 185, my + 82, 45, 38],
    [gx + 115, my + 98, 52, 38],
    [gx + 55, my + 112, 36, 28],
    [gx + 212, my + 104, 34, 28],
    // Transom sunlit domes (with tilt refraction offset in top-left pane)
    [gx + 98, gy + 54, 42, 30],
    [vx + 36, gy + 52, 46, 32],
    [vx + 76, gy + 66, 34, 24]
  ];
  for (let l of cloudLights) {
    washPoly(getEllipsePts(l[0], l[1], l[2], l[3], -6, 24), "#F8FAFC", 165, 0.25);
    wcPoly(
      getEllipsePts(l[0] - 6, l[1] - 6, l[2] * 0.75, l[3] * 0.72, -8, 20),
      "#FFFFFF",
      180,
      0.1,
      0.35,
      0.2,
      0.25
    );
  }

  // Warm golden-cream rim light on the top-left turret of the cloud
  let rimArcs = [
    [gx + 142, my + 56, 56, 46, 190, 315],
    [gx + 88, my + 78, 46, 40, 175, 290],
    [vx + 36, gy + 52, 44, 30, 195, 320],
    [gx + 98, gy + 54, 40, 28, 190, 310]
  ];
  for (let a of rimArcs) {
    let pts = getArcPts(a[0], a[1], a[2], a[3], a[4], a[5], 0, 16);
    strokePoly(pts, "cpencil", "#FEF9C3", 1.6, false, 0.2);
    strokePoly(pts, "cpencil", "#FFFFFF", 1.1, false, 0.2);
  }

  // Delicate graphite & colored-pencil modeling of internal cloud puffs
  let puffArcs = [
    [gx + 115, my + 98, 44, 32, 20, 155, "#94A3B8"],
    [gx + 155, my + 92, 50, 36, 15, 160, "#64748B"],
    [gx + 82, my + 128, 42, 26, 10, 165, "#475569"],
    [gx + 168, my + 135, 58, 30, 5, 170, "#334155"],
    [gx + 135, my + 162, 95, 24, 10, 170, "#1E293B"]
  ];
  for (let p of puffArcs) {
    let pts = getArcPts(p[0], p[1], p[2], p[3], p[4], p[5], 0, 18);
    strokePoly(pts, "cpencil", p[6], 1.1, false, 0.2);
  }

  // Subtle dark graphite glass grounding at bottom of pane
  wcRect(gx, my + 215, gw, mh - 215, "#232F3E", 85, 0.14, 0.5, 0.3);
  drawGlassReflections(gx, gy, gw, gh, ty, my, mh, vx, 0.85);
}

// ----------------------------------------------------------------------------
// VIGNETTE 2 (Top-Center): THE HALF-DRAWN BLIND
// ----------------------------------------------------------------------------
function drawVignetteHalfDrawnBlind(gx, gy, gw, gh, ty, my, mh, vx) {
  // 1. Base cool graphite-grey watercolor across all panes
  glazeCoolGraphitePane(gx, gy, 134, 86, 1);
  glazeCoolGraphitePane(vx + 8, gy, 134, 86, 1);
  glazeCoolGraphitePane(gx, my, gw, mh, 1);

  // Deep shadowy interior in the lower half below the blind
  washRect(gx, my + 155, gw, mh - 155, "#161E27", 110);
  // Subtle interior background doorframe edge in the dim room
  washRect(gx + 65, my + 165, 12, mh - 165, "#253241", 85);
  washRect(gx + 77, my + 165, 115, mh - 165, "#0F161E", 95);
  hatchRect(gx, my + 160, gw, mh - 160, "2H", "#1C2632", 0.35, 8, 90, { rand: 0.02 });

  // 2. Half-drawn Venetian Blind (covers both top transom panes + upper 52% of main pane)
  let blindBottomL = my + 162;
  let blindBottomR = my + 167; // Slight hyperreal 1-degree natural tilt on bottom rail

  // Backing shadow behind the slats
  washPoly(
    [
      [gx, gy],
      [gx + gw, gy],
      [gx + gw, blindBottomR],
      [gx, blindBottomL]
    ],
    "#1E293B",
    165,
    0
  );

  // Draw individual horizontal aluminum slats (10.5px pitch)
  let slatPitch = 10.5;
  let slatH = 7.8;
  for (let sy = gy + 4; sy < blindBottomL - 8; sy += slatPitch) {
    let t = (sy - gy) / (blindBottomL - gy);
    let dyR = t * 5; // Progressive slight tilt toward bottom rail
    let yL = sy;
    let yR = sy + dyR;

    // Slat main body (cool alabaster-cerulean silver grading from left light to right)
    washPoly(
      [
        [gx + 3, yL],
        [gx + gw - 3, yR],
        [gx + gw - 3, yR + slatH],
        [gx + 3, yL + slatH]
      ],
      "#CBD5E1",
      195,
      0
    );

    // Sunlit left-center sheen on each slat
    washPoly(
      [
        [gx + 3, yL],
        [gx + gw * 0.65, lerp(yL, yR, 0.65)],
        [gx + gw * 0.58, lerp(yL, yR, 0.58) + slatH * 0.55],
        [gx + 3, yL + slatH * 0.65]
      ],
      "#F1F5F9",
      160,
      0
    );

    // Crisp bright top edge of slat
    ruledLine(gx + 3, yL, gx + gw - 3, yR, "rotring", "#FFFFFF", 0.45);
    // Deep saturated Prussian-slate shadow gap directly beneath each slat
    ruledLine(gx + 3, yL + slatH + 0.8, gx + gw - 3, yR + slatH + 0.8, "rotring", "#0F172A", 0.75);
    ruledLine(gx + 3, yL + slatH + 1.8, gx + gw - 3, yR + slatH + 1.8, "rotring", "#1E3A5F", 0.45);
  }

  // Weighted enameled bottom rail of the blind
  washPoly(
    [
      [gx + 3, blindBottomL - 2],
      [gx + gw - 3, blindBottomR - 2],
      [gx + gw - 3, blindBottomR + 9],
      [gx + 3, blindBottomL + 9]
    ],
    "#E2E8F0",
    225,
    0
  );
  ruledLine(gx + 3, blindBottomL - 2, gx + gw - 3, blindBottomR - 2, "rotring", "#FFFFFF", 0.55);
  ruledLine(gx + 3, blindBottomL + 5, gx + gw - 3, blindBottomR + 5, "rotring", "#64748B", 0.45);
  ruledLine(gx + 3, blindBottomL + 9, gx + gw - 3, blindBottomR + 9, "rotring", "#0F172A", 0.85);

  // Two vertical woven ladder tapes with rung ticks
  let tapeX = [gx + 54, gx + gw - 54];
  for (let tx of tapeX) {
    let bY = lerp(blindBottomL, blindBottomR, (tx - gx) / gw) + 8;
    ruledLine(tx - 1.2, gy + 2, tx - 1.2, bY, "rotring", "#94A3B8", 0.4);
    ruledLine(tx, gy + 2, tx, bY, "rotring", "#F8FAFC", 0.65);
    ruledLine(tx + 1.2, gy + 2, tx + 1.2, bY, "rotring", "#64748B", 0.35);
    // Tiny horizontal cross-rungs at every slat
    for (let sy = gy + 4; sy < blindBottomL - 8; sy += slatPitch) {
      let ry = sy + ((tx - gx) / gw) * 3 + slatH * 0.5;
      ruledLine(tx - 3.5, ry, tx + 3.5, ry, "rotring", "#FFFFFF", 0.4);
    }
  }

  // Dangling pull cord & vivid saturated yellow-brass/cobalt acorn toggle on right
  let cordX = gx + gw - 54;
  let cordStartY = blindBottomR + 8;
  let cordEndX = cordX + 6;
  let cordEndY = my + 258;
  // Shadow of cord
  ruledLine(cordX + 2, cordStartY, cordEndX + 2, cordEndY, "rotring", "#090D14", 0.55);
  // Braided nylon cord (two twisted strands converging at toggle)
  ruledLine(cordX - 2, cordStartY, cordEndX, cordEndY, "rotring", "#E2E8F0", 0.55);
  ruledLine(cordX + 2, cordStartY, cordEndX, cordEndY, "rotring", "#CBD5E1", 0.45);

  // Vivid cadmium-amber/brass acorn toggle at end of cord
  let acornPts = [
    [cordEndX - 4, cordEndY],
    [cordEndX + 4, cordEndY],
    [cordEndX + 6, cordEndY + 9],
    [cordEndX + 2.5, cordEndY + 17],
    [cordEndX - 2.5, cordEndY + 17],
    [cordEndX - 6, cordEndY + 9]
  ];
  washPoly(acornPts, "#F59E0B", 235, 0.1);
  washPoly(
    [
      [cordEndX - 4, cordEndY + 1],
      [cordEndX, cordEndY + 1],
      [cordEndX - 1, cordEndY + 15],
      [cordEndX - 5, cordEndY + 9]
    ],
    "#FEF08A",
    210,
    0.1
  );
  strokePoly(acornPts, "rotring", "#1E293B", 0.45, true, 0.05);

  // Left acrylic hexagonal tilt wand hanging down to my + 205
  let wandX = gx + 30;
  ruledLine(wandX - 1.5, gy + 12, wandX - 1.5, my + 204, "rotring", "#93C5FD", 0.45);
  ruledLine(wandX, gy + 12, wandX, my + 204, "rotring", "#FFFFFF", 0.6);
  ruledLine(wandX + 1.5, gy + 12, wandX + 1.5, my + 204, "rotring", "#334155", 0.4);

  // 3. Cool graphite-grey watercolor veil over the blind (so it sits behind glass)
  wcRect(gx, gy, gw, gh, "#2B3948", 48, 0.08, 0.4, 0.25);
  drawGlassReflections(gx, gy, gw, gh, ty, my, mh, vx, 1.05);
}

// ----------------------------------------------------------------------------
// VIGNETTE 3 (Top-Right): THE DROOPING TOWEL
// ----------------------------------------------------------------------------
function drawVignetteDroopingTowel(gx, gy, gw, gh, ty, my, mh, vx) {
  // 1. Base cool graphite-grey watercolor across panes
  glazeCoolGraphitePane(gx, gy, 134, 86, 1);
  glazeCoolGraphitePane(vx + 8, gy, 134, 86, 2); // Darker open hopper cavity on top-right
  glazeCoolGraphitePane(gx, my, gw, mh, 1);

  // Top-right hopper sash is tilted inward into the dorm room!
  // Draw the dark open wedge at top of top-right transom and angled inner sash frame
  washRect(vx + 8, gy, 134, 34, "#0E131A", 180);
  washPoly(
    [
      [vx + 8, gy + 86],
      [vx + 22, gy + 24],
      [vx + 130, gy + 24],
      [vx + 142, gy + 86]
    ],
    "#1C2632",
    140,
    0
  );
  // Angled steel hopper frame lines inside the top-right pane
  ruledLine(vx + 8, gy + 86, vx + 22, gy + 24, "rotring", "#0B0F14", 0.7);
  ruledLine(vx + 142, gy + 86, vx + 130, gy + 24, "rotring", "#0B0F14", 0.7);
  ruledLine(vx + 22, gy + 24, vx + 130, gy + 24, "rotring", "#3B4A5A", 0.9);
  ruledLine(vx + 22, gy + 27, vx + 130, gy + 27, "rotring", "#0B0F14", 0.6);

  // Subtle interior dorm room background in main pane (wardrobe side & wall corner)
  washRect(gx + 22, my + 15, 95, mh - 15, "#1B242E", 65);
  hatchRect(gx, my, gw, mh, "2H", "#1A232D", 0.35, 10, 90, { rand: 0.03 });

  // 2. THE DROOPING TOWEL
  // Draped over the open hopper frame / horizontal transom mullion, drooping into main pane
  // Vivid & saturated Cobalt-Ultramarine terry-cloth towel with Crimson & Ivory border stripes
  let txL = gx + 102;
  let txR = gx + 248;
  let topRollY = gy + 64; // Starts over the open hopper sash in the transom

  // Cast shadow of the drooping towel against the interior / glass
  wcPoly(
    [
      [txL - 10, my + 4],
      [txR + 6, my + 4],
      [txR - 4, my + 215],
      [txL + 42, my + 265],
      [txL - 14, my + 245]
    ],
    "#0D1520",
    135,
    0.15,
    0.45,
    0.3,
    0.2
  );

  // Back underside fold of towel (visible on left and bottom right)
  let underFoldPts = [
    [txL - 4, topRollY + 12],
    [txL + 22, topRollY + 12],
    [txL + 28, my + 248],
    [txL - 2, my + 232]
  ];
  washPoly(underFoldPts, "#0A2246", 220, 0.12);

  // Main front drooping body of towel (catenary gravity curve, left side hangs lower)
  let towelBodyPts = [
    [txL, topRollY],
    [txL + 48, topRollY + 5],
    [txL + 98, topRollY + 2],
    [txR, topRollY + 4],
    [txR + 4, my + 110],
    [txR - 8, my + 198],
    [txL + 88, my + 228],
    [txL + 34, my + 244],
    [txL + 4, my + 226],
    [txL - 4, my + 105]
  ];
  // Base vivid cobalt-ultramarine wash
  washPoly(towelBodyPts, "#15459E", 230, 0.15);
  wcPoly(towelBodyPts, "#1D5ED8", 145, 0.08, 0.55, 0.35, 0.15);

  // Volumetric vertical folds (3 major tubular ridges + 2 deep valleys)
  // Valley 1 (left-center)
  let val1 = [
    [txL + 26, topRollY + 4],
    [txL + 52, topRollY + 6],
    [txL + 48, my + 240],
    [txL + 18, my + 236]
  ];
  washPoly(val1, "#0B2963", 185, 0.12);

  // Valley 2 (right-center)
  let val2 = [
    [txL + 84, topRollY + 4],
    [txL + 112, topRollY + 5],
    [txL + 102, my + 216],
    [txL + 74, my + 226]
  ];
  washPoly(val2, "#0D3175", 175, 0.12);

  // Ridge 1 (left sunlit fold)
  let ridge1 = [
    [txL + 2, topRollY + 1],
    [txL + 24, topRollY + 3],
    [txL + 18, my + 228],
    [txL + 2, my + 220]
  ];
  washPoly(ridge1, "#2563EB", 170, 0.12);

  // Ridge 2 (central prominent drooping fold)
  let ridge2 = [
    [txL + 52, topRollY + 5],
    [txL + 84, topRollY + 4],
    [txL + 76, my + 226],
    [txL + 46, my + 238]
  ];
  washPoly(ridge2, "#3B82F6", 175, 0.15);

  // Ridge 3 (right fold)
  let ridge3 = [
    [txL + 112, topRollY + 4],
    [txR - 2, topRollY + 5],
    [txR - 10, my + 195],
    [txL + 104, my + 214]
  ];
  washPoly(ridge3, "#2563EB", 160, 0.12);

  // Bright daylight highlight on the top rollover crest (in the open hopper transom)
  let crestPts = [
    [txL, topRollY],
    [txL + 72, topRollY + 4],
    [txR, topRollY + 3],
    [txR, topRollY + 18],
    [txL + 72, topRollY + 21],
    [txL, topRollY + 16]
  ];
  washPoly(crestPts, "#60A5FA", 185, 0.2);
  washPoly(
    [
      [txL + 6, topRollY + 1],
      [txR - 8, topRollY + 3],
      [txR - 10, topRollY + 10],
      [txL + 6, topRollY + 9]
    ],
    "#BFDBFE",
    160,
    0.2
  );

  // Vivid woven border stripes near the bottom hem of the towel (follows fold waves!)
  let hemWave = [
    [txL + 2, my + 184],
    [txL + 18, my + 192],
    [txL + 34, my + 202],
    [txL + 64, my + 190],
    [txL + 90, my + 188],
    [txL + 118, my + 172],
    [txR - 8, my + 162]
  ];

  // Helper to offset wave vertically
  function offsetWave(wave, dy1, dy2) {
    let pts = [];
    for (let i = 0; i < wave.length; i++) {
      pts.push([wave[i][0], wave[i][1] + dy1]);
    }
    for (let i = wave.length - 1; i >= 0; i--) {
      pts.push([wave[i][0], wave[i][1] + dy2]);
    }
    return pts;
  }

  // Ivory woven band 1
  washPoly(offsetWave(hemWave, -6, 0), "#F8FAFC", 215, 0.15);
  // Vivid saturated Crimson-Red woven band
  washPoly(offsetWave(hemWave, 0, 16), "#E11D48", 230, 0.15);
  // Ivory woven band 2
  washPoly(offsetWave(hemWave, 16, 22), "#F8FAFC", 215, 0.15);
  // Re-apply fold shadow valleys over the decorative bands for 3D continuity
  washPoly(
    [
      [txL + 22, my + 175],
      [txL + 48, my + 178],
      [txL + 48, my + 240],
      [txL + 20, my + 235]
    ],
    "#091936",
    115,
    0.1
  );
  washPoly(
    [
      [txL + 82, my + 165],
      [txL + 106, my + 162],
      [txL + 104, my + 216],
      [txL + 78, my + 225]
    ],
    "#091936",
    110,
    0.1
  );

  // Tactile terry-cloth micro-texture (hundreds of tiny cpencil loop marks)
  for (let i = 0; i < 240; i++) {
    let px = random(txL + 4, txR - 10);
    let py = random(topRollY + 6, my + 210);
    let col = i % 3 === 0 ? "#93C5FD" : i % 3 === 1 ? "#1E3A8A" : "#3B82F6";
    brush.set("cpencil", col, random(0.45, 0.8));
    brush.line(px, py, px + random(-2, 2), py + random(2, 5));
  }

  // Crisp contour & fold crease lines
  strokePoly(towelBodyPts, "rotring", "#091D42", 0.5, true, 0.12);
  ruledLine(txL + 28, topRollY + 12, txL + 24, my + 236, "2B", "#081838", 0.65);
  ruledLine(txL + 84, topRollY + 8, txL + 76, my + 225, "2B", "#081838", 0.65);
  ruledLine(txL + 52, topRollY + 8, txL + 46, my + 236, "cpencil", "#93C5FD", 0.6);

  // 3. Cool graphite-grey glass glaze OVER the lower main pane (veiling the lower half of the towel!)
  wcRect(gx, my, gw, mh, "#2E3D4E", 55, 0.08, 0.45, 0.25);
  drawGlassReflections(gx, gy, gw, gh, ty, my, mh, vx, 1.0);
}

// ----------------------------------------------------------------------------
// VIGNETTE 4 (Bottom-Left): THE CHIPPED MUG ON A SILL
// ----------------------------------------------------------------------------
function drawVignetteChippedMug(gx, gy, gw, gh, ty, my, mh, vx) {
  // 1. Base cool graphite-grey watercolor across all 3 panes
  glazeCoolGraphitePane(gx, gy, 134, 86, 1);
  glazeCoolGraphitePane(vx + 8, gy, 134, 86, 1);
  glazeCoolGraphitePane(gx, my, gw, mh, 1);

  // Subtle dim dorm room wall & framed print corner behind glass
  washRect(gx + 15, my + 15, gw - 30, mh - 65, "#1D2631", 65);
  washRect(gx + 165, my + 45, 85, 115, "#283544", 55);
  ruledLine(gx + 165, my + 45, gx + 165, my + 160, "2H", "#11171F", 0.45);
  ruledLine(gx + 165, my + 160, gx + 250, my + 160, "2H", "#475569", 0.4);
  hatchRect(gx, my, gw, mh - 45, "2H", "#1A222C", 0.35, 9, 90, { rand: 0.03 });

  // 2. Interior windowsill seen through the bottom of the main pane
  let sillTopY = my + mh - 46; // gy + 376
  let sillFrontY = my + mh - 20; // gy + 402
  // Sill top plane (angled in slight perspective)
  washPoly(
    [
      [gx, sillTopY],
      [gx + gw, sillTopY],
      [gx + gw, sillFrontY],
      [gx, sillFrontY]
    ],
    "#CBD5E1",
    195,
    0
  );
  // Sunlit front edge strip of interior sill
  washRect(gx, sillFrontY - 3, gw, 3, "#F1F5F9", 210);
  // Sill front apron in shadow before the outer steel frame
  washRect(gx, sillFrontY, gw, 20, "#64748B", 210);
  ruledLine(gx, sillTopY, gx + gw, sillTopY, "rotring", "#475569", 0.45);
  ruledLine(gx, sillFrontY, gx + gw, sillFrontY, "rotring", "#1E293B", 0.6);

  // Cast shadow of the mug stretching right across the interior sill
  let mx = gx + 96; // Mug left edge
  let mw = 64;      // Mug cylinder width
  let mTopY = sillTopY - 64; // Mug rim center Y
  let mBotY = sillTopY + 12; // Mug base center Y

  washPoly(
    [
      [mx + mw - 6, mBotY - 4],
      [mx + mw + 78, mBotY - 9],
      [mx + mw + 92, mBotY + 5],
      [mx + 14, mBotY + 8]
    ],
    "#334155",
    165,
    0.15
  );

  // 3. THE CHIPPED MUG (Vivid saturated Emerald-Turquoise glazed stoneware)
  // Curved D-handle on the right side of the mug (drawn before/with cylinder)
  let hOuter = getArcPts(mx + mw - 2, (mTopY + mBotY) * 0.5 + 2, 23, 24, -75, 78, 0, 20);
  let hInner = getArcPts(mx + mw - 2, (mTopY + mBotY) * 0.5 + 2, 14, 15, 78, -75, 0, 20);
  let handlePts = hOuter.concat(hInner);
  washPoly(handlePts, "#007788", 235, 0.1);
  // Handle highlight & shadow
  strokePoly(
    getArcPts(mx + mw - 2, (mTopY + mBotY) * 0.5 + 2, 20, 21, -65, 25, 0, 14),
    "cpencil",
    "#90E0EF",
    1.1,
    false,
    0.15
  );
  strokePoly(hOuter, "rotring", "#002933", 0.55, false, 0.1);
  strokePoly(hInner, "rotring", "#001D24", 0.55, false, 0.1);

  // Mug cylindrical body with elliptical bottom and top
  let botArc = getArcPts(mx + mw * 0.5, mBotY, mw * 0.5, 9, 0, 180, 0, 20);
  let bodyPts = [[mx, mTopY]].concat(botArc).concat([[mx + mw, mTopY]]);

  // Base vivid emerald-turquoise ceramic glaze
  washPoly(bodyPts, "#008B99", 240, 0.08);
  wcPoly(bodyPts, "#00A8B8", 150, 0.06, 0.45, 0.3, 0.08);

  // Cylindrical 3D shading bands across mug body
  // Deep core shadow on right-center
  washPoly(
    [
      [mx + mw * 0.58, mTopY],
      [mx + mw * 0.88, mTopY],
      [mx + mw * 0.88, mBotY + 5],
      [mx + mw * 0.58, mBotY + 8]
    ],
    "#004B57",
    185,
    0
  );
  // Subtle reflected sill light on far right edge
  washPoly(
    [
      [mx + mw * 0.88, mTopY + 2],
      [mx + mw - 1, mTopY + 2],
      [mx + mw - 1, mBotY + 1],
      [mx + mw * 0.88, mBotY + 5]
    ],
    "#48CAE4",
    115,
    0
  );
  // Glossy vertical specular highlight bar on sunlit left-front of cylinder
  washPoly(
    [
      [mx + 11, mTopY + 4],
      [mx + 22, mTopY + 5],
      [mx + 22, mBotY + 6],
      [mx + 11, mBotY + 4]
    ],
    "#90E0EF",
    175,
    0
  );
  washRect(mx + 14, mTopY + 10, 4.5, mBotY - mTopY - 8, "#FFFFFF", 210);

  // Mug top rim ellipse (stoneware interior)
  let rimOuter = getEllipsePts(mx + mw * 0.5, mTopY, mw * 0.5, 8.5, 0, 28);
  let rimInner = getEllipsePts(mx + mw * 0.5, mTopY + 0.5, mw * 0.5 - 3.5, 6.2, 0, 28);
  washPoly(rimOuter, "#E2E8F0", 235, 0.1);
  washPoly(rimInner, "#94A3B8", 225, 0.1);
  // Shadow inside left interior wall of mug
  washPoly(
    getArcPts(mx + mw * 0.5, mTopY + 0.5, mw * 0.5 - 3.5, 6.2, 110, 265, 0, 14),
    "#475569",
    190,
    0.1
  );
  // Dark tea/coffee ring inside bottom of visible rim
  strokePoly(
    getArcPts(mx + mw * 0.5, mTopY + 3.2, mw * 0.38, 3.8, 195, 345, 0, 14),
    "rotring",
    "#4E342E",
    0.65,
    false,
    0.1
  );

  // THE CHIP ON THE RIM (Front-left lip: jagged V-fracture exposing matte biscuit porcelain)
  let chipPts = [
    [mx + 12, mTopY + 5.5],
    [mx + 18, mTopY + 7.2],
    [mx + 25, mTopY + 7.8],
    [mx + 22, mTopY + 17.5],
    [mx + 16, mTopY + 19.5],
    [mx + 13, mTopY + 13.5]
  ];
  washPoly(chipPts, "#FFFBEB", 245, 0);
  // Inner fracture bevel facet in cool shadow
  washPoly(
    [
      [mx + 18, mTopY + 7.2],
      [mx + 25, mTopY + 7.8],
      [mx + 22, mTopY + 17.5],
      [mx + 18, mTopY + 14.0]
    ],
    "#CBD5E1",
    220,
    0
  );
  strokePoly(chipPts, "rotring", "#334155", 0.5, true, 0);
  ruledLine(mx + 18, mTopY + 7.2, mx + 18, mTopY + 16, "rotring", "#64748B", 0.4);

  // Crisp ruled outlines of mug body and rim
  strokePoly(bodyPts, "rotring", "#001D24", 0.6, false, 0.05);
  strokePoly(rimOuter, "rotring", "#334155", 0.45, true, 0.1);
  strokePoly(rimInner, "rotring", "#1E293B", 0.45, true, 0.1);

  // Teabag string & vivid crimson-red paper tag hanging over front-right of mug
  let strStartX = mx + mw * 0.68;
  let strStartY = mTopY + 7.5;
  let tagX = mx + mw * 0.64;
  let tagY = mTopY + 32;
  ruledLine(strStartX - 3, mTopY + 3, strStartX, strStartY, "rotring", "#F8FAFC", 0.45);
  ruledLine(strStartX, strStartY, tagX + 6, tagY, "rotring", "#F8FAFC", 0.5);
  // Crimson paper teabag tag
  let tagPts = [
    [tagX + 3, tagY],
    [tagX + 10, tagY],
    [tagX + 13, tagY + 4],
    [tagX + 12, tagY + 16],
    [tagX + 1, tagY + 15],
    [tagX + 1, tagY + 4]
  ];
  washPoly(tagPts, "#E11D48", 240, 0);
  strokePoly(tagPts, "rotring", "#4C0519", 0.4, true, 0);
  ruledLine(tagX + 5, tagY + 3, tagX + 8, tagY + 3, "rotring", "#FFFFFF", 0.45);

  // 4. Cool graphite-grey watercolor veil over the pane so the mug sits behind glass
  wcRect(gx, my, gw, mh, "#2D3C4C", 45, 0.08, 0.4, 0.25);
  drawGlassReflections(gx, gy, gw, gh, ty, my, mh, vx, 1.0);
}

// ----------------------------------------------------------------------------
// VIGNETTE 5 (Bottom-Center): SIGNAL ORANGE PANE (LAMP BEHIND A CURTAIN)
// ----------------------------------------------------------------------------
function drawVignetteSignalOrangeCurtain(gx, gy, gw, gh, ty, my, mh, vx) {
  // 1. Top two transom panes remain cool dark graphite-grey watercolor!
  // ("Exactly one pane glows signal orange from a lamp behind a curtain.")
  glazeCoolGraphitePane(gx, gy, 134, 86, 2);
  glazeCoolGraphitePane(vx + 8, gy, 134, 86, 2);
  // Subtle dark curtain header track right below the transom mullion
  washRect(gx, gy + 74, 134, 12, "#121820", 110);
  washRect(vx + 8, gy + 74, 134, 12, "#121820", 110);

  // 2. THE MAIN LOWER PANE: Blazing, vivid Signal Orange from a lamp behind a curtain
  // Base opaque wash in deep signal orange-vermilion so no white canvas dulls the saturation
  washRect(gx, my, gw, mh, "#FF3B00", 245);

  // Rich watercolor saturation layers in deep vermilion at edges and blazing signal orange across center
  wcRect(gx, my, gw, mh, "#D92300", 130, 0.08, 0.5, 0.35);
  wcRect(gx + 12, my + 12, gw - 24, mh - 24, "#FF4D00", 155, 0.12, 0.45, 0.25);

  // Lamp center coordinates behind the translucent curtain
  let lx = gx + 156;
  let ly = my + 188;

  // Radial concentric glow washes of the lamp diffusing through the curtain textile
  let glowRings = [
    [145, 155, "#FF5500", 150],
    [115, 125, "#FF6D00", 165],
    [88, 95, "#FF8800", 175],
    [64, 70, "#FFA700", 185],
    [44, 48, "#FFC800", 195],
    [28, 30, "#FFE566", 205]
  ];
  for (let g of glowRings) {
    wcPoly(getEllipsePts(lx, ly, g[0], g[1], 0, 28), g[2], g[3], 0.15, 0.4, 0.2, 0.25);
  }

  // Diffused silhouette of the lamp shade & stem behind the curtain
  // Light escapes most intensely just above the top opening and below the bottom skirt of the shade
  // Upper light plume escaping top of shade
  washPoly(
    [
      [lx - 26, ly - 28],
      [lx + 26, ly - 28],
      [lx + 58, ly - 95],
      [lx - 58, ly - 95]
    ],
    "#FFB700",
    130,
    0.15
  );
  // Lower light cone escaping bottom of shade
  washPoly(
    [
      [lx - 42, ly + 26],
      [lx + 42, ly + 26],
      [lx + 85, my + mh],
      [lx - 85, my + mh]
    ],
    "#FFA200",
    135,
    0.15
  );

  // Diffused lamp shade body (warm glowing tangerine silhouette)
  let shadePts = [
    [lx - 28, ly - 30],
    [lx + 28, ly - 30],
    [lx + 46, ly + 26],
    [lx - 46, ly + 26]
  ];
  washPoly(shadePts, "#FF5E00", 155, 0.12);

  // Incandescent white-gold hot core where the bulb filaments shine through the shade & curtain
  washPoly(getEllipsePts(lx, ly + 4, 24, 18, 0, 24), "#FFF099", 210, 0.25);
  washPoly(getEllipsePts(lx, ly + 2, 13, 10, 0, 20), "#FFFFFF", 220, 0.25);

  // Softly diffused lamp stem & base silhouette behind curtain
  washRect(lx - 4, ly + 26, 8, 72, "#C82800", 125);
  washPoly(getEllipsePts(lx, ly + 98, 28, 7, 0, 20), "#B81D00", 135, 0.15);

  // 3. Vertical translucent curtain pleats hanging from top of main pane (my) to bottom (my + mh)
  let pleatX = [0, 28, 62, 94, 132, 168, 204, 238, 276];
  for (let i = 0; i < pleatX.length - 1; i++) {
    let x1 = gx + pleatX[i];
    let x2 = gx + pleatX[i + 1];
    let xm = (x1 + x2) * 0.5;
    let distFromLamp = abs(xm - lx);

    // Deep vermilion-scarlet pleat valley on left edge of fold
    let valAlpha = map(distFromLamp, 0, 150, 75, 145);
    washPoly(
      [
        [x1, my],
        [x1 + (x2 - x1) * 0.36, my],
        [x1 + (x2 - x1) * 0.42, my + mh],
        [x1, my + mh]
      ],
      "#9E1100",
      valAlpha,
      0
    );

    // Translucent glowing orange-gold ridge on center-right of fold
    let ridgeCol = distFromLamp < 55 ? "#FFD000" : distFromLamp < 105 ? "#FF8800" : "#FF5500";
    let ridgeAlpha = map(distFromLamp, 0, 150, 95, 55);
    washPoly(
      [
        [xm, my],
        [x2 - 3, my],
        [x2 - 2, my + mh],
        [xm + 2, my + mh]
      ],
      ridgeCol,
      ridgeAlpha,
      0
    );

    // Soft vertical crease line
    ruledLine(
      x1 + 2,
      my,
      x1 + 4,
      my + mh,
      "cpencil",
      distFromLamp < 65 ? "#D92B00" : "#800E00",
      0.65
    );
  }

  // Fine woven linen textile cross-hatching across the glowing curtain
  hatchRect(gx, my, gw, mh, "cpencil", "#FF9500", 0.4, 6, 90, { rand: 0.02 });
  hatchRect(gx, my, gw, mh, "cpencil", "#CC2200", 0.35, 9, 0, { rand: 0.02 });

  // Subtle diagonal specular glass reflections over the glowing orange pane & dark transoms
  drawGlassReflections(gx, gy, gw, gh, ty, my, mh, vx, 0.65);
}

// ----------------------------------------------------------------------------
// VIGNETTE 6 (Bottom-Right): THE DESK LAMP
// ----------------------------------------------------------------------------
function drawVignetteDeskLamp(gx, gy, gw, gh, ty, my, mh, vx) {
  // 1. Base cool graphite-grey watercolor across all 3 panes
  glazeCoolGraphitePane(gx, gy, 134, 86, 1);
  glazeCoolGraphitePane(vx + 8, gy, 134, 86, 1);
  glazeCoolGraphitePane(gx, my, gw, mh, 1);

  // Subtle interior dorm room background (bookshelf edge & pinboard silhouette)
  washRect(gx + 16, my + 20, 125, 140, "#1B2530", 60);
  hatchRect(gx, my, gw, mh - 45, "2H", "#19222C", 0.35, 9, 90, { rand: 0.03 });

  // 2. Dorm study desk surface at bottom of main pane
  let deskY = my + mh - 44; // gy + 378
  washRect(gx, deskY, gw, 44, "#1E293B", 220);
  washRect(gx, deskY, gw, 5, "#475569", 210);
  ruledLine(gx, deskY, gx + gw, deskY, "rotring", "#94A3B8", 0.5);
  ruledLine(gx, deskY + 5, gx + gw, deskY + 5, "rotring", "#0F172A", 0.6);

  // Subtle warm pool of light on the desk surface & books from the desk lamp
  wcPoly(
    [
      [gx + 75, my + 125],
      [gx + 135, my + 125],
      [gx + 195, deskY + 6],
      [gx + 10, deskY + 6]
    ],
    "#7DD3FC",
    32,
    0.18,
    0.4,
    0.2,
    0.1
  );

  // Stack of two hardcover books on the left side of the desk
  // Bottom book: Vivid saturated Emerald Green spine/cover
  washRect(gx + 18, deskY - 16, 86, 16, "#059669", 230);
  washRect(gx + 22, deskY - 13, 78, 10, "#F1F5F9", 220); // Cream page block
  strokePoly(
    [
      [gx + 18, deskY - 16],
      [gx + 104, deskY - 16],
      [gx + 104, deskY],
      [gx + 18, deskY]
    ],
    "rotring",
    "#064E3B",
    0.5,
    true,
    0
  );
  // Top book: Vivid Ultramarine Blue cover
  washRect(gx + 24, deskY - 29, 74, 13, "#1D4ED8", 230);
  washRect(gx + 28, deskY - 26, 66, 8, "#E2E8F0", 220);
  strokePoly(
    [
      [gx + 24, deskY - 29],
      [gx + 98, deskY - 29],
      [gx + 98, deskY - 16],
      [gx + 24, deskY - 16]
    ],
    "rotring",
    "#1E3A8A",
    0.5,
    true,
    0
  );

  // 3. THE ARTICULATED ARCHITECT DESK LAMP (Classic Anglepoise)
  // Coordinates of key mechanical joints:
  let baseX = gx + 194;
  let baseY = deskY;
  let forkX = baseX;
  let forkY = baseY - 16;
  let elbowX = gx + 236;
  let elbowY = my + 165;
  let neckX = gx + 132;
  let neckY = my + 82;

  // Stepped circular cast-iron base (vivid Cerulean-Teal enamel + chrome rim)
  let baseBotPts = getEllipsePts(baseX, baseY + 2, 30, 6.5, 0, 24);
  let baseTopPts = getEllipsePts(baseX, baseY - 7, 24, 5, 0, 24);
  washPoly(baseBotPts, "#0369A1", 235, 0.1);
  washPoly(baseTopPts, "#0EA5E9", 235, 0.1);
  strokePoly(baseBotPts, "rotring", "#082F49", 0.55, true, 0.1);
  strokePoly(baseTopPts, "rotring", "#E0F2FE", 0.45, true, 0.1);

  // Turret swivel fork on base
  washRect(forkX - 5, forkY, 10, 11, "#CBD5E1", 230);
  strokePoly(
    [
      [forkX - 5, forkY],
      [forkX + 5, forkY],
      [forkX + 5, forkY + 11],
      [forkX - 5, forkY + 11]
    ],
    "rotring",
    "#0F172A",
    0.5,
    true,
    0
  );

  // Twin parallel lower chrome arms + twin tension springs
  // Arm 1 (front) & Arm 2 (back)
  ruledLine(forkX - 3, forkY + 2, elbowX - 4, elbowY + 4, "rotring", "#0F172A", 1.2);
  ruledLine(forkX - 3, forkY + 2, elbowX - 4, elbowY + 4, "rotring", "#F8FAFC", 0.65);
  ruledLine(forkX + 4, forkY + 4, elbowX + 3, elbowY + 6, "rotring", "#0F172A", 1.2);
  ruledLine(forkX + 4, forkY + 4, elbowX + 3, elbowY + 6, "rotring", "#CBD5E1", 0.65);

  // Coiled tension springs near base
  let spX1 = lerp(forkX, elbowX, 0.32) - 9;
  let spY1 = lerp(forkY, elbowY, 0.32);
  ruledLine(forkX - 11, forkY + 6, spX1, spY1, "rotring", "#1E293B", 1.5);
  ruledLine(forkX - 11, forkY + 6, spX1, spY1, "rotring", "#E2E8F0", 0.8);
  // Spring coil ticks
  for (let i = 0; i < 8; i++) {
    let t = i / 8;
    let cx = lerp(forkX - 10, spX1, t);
    let cy = lerp(forkY + 5, spY1, t);
    ruledLine(cx - 2, cy - 1, cx + 2, cy + 1, "rotring", "#0F172A", 0.45);
  }
  ruledLine(spX1, spY1, elbowX - 2, elbowY + 2, "rotring", "#94A3B8", 0.4);

  // Twin parallel upper chrome arms (from elbow up-left to shade neck)
  ruledLine(elbowX - 2, elbowY - 3, neckX + 4, neckY - 2, "rotring", "#0F172A", 1.2);
  ruledLine(elbowX - 2, elbowY - 3, neckX + 4, neckY - 2, "rotring", "#FFFFFF", 0.65);
  ruledLine(elbowX - 6, elbowY + 4, neckX, neckY + 5, "rotring", "#0F172A", 1.2);
  ruledLine(elbowX - 6, elbowY + 4, neckX, neckY + 5, "rotring", "#CBD5E1", 0.65);

  // Black Bakelite & chrome elbow joint plate
  let elbowPlate = getEllipsePts(elbowX - 2, elbowY + 1, 7.5, 7.5, 0, 18);
  washPoly(elbowPlate, "#1E293B", 240, 0.1);
  strokePoly(elbowPlate, "rotring", "#F8FAFC", 0.45, true, 0.1);
  // Chrome rivet center
  washPoly(getEllipsePts(elbowX - 2, elbowY + 1, 2.5, 2.5, 0, 12), "#FFFFFF", 240, 0.1);

  // Loosely looped black fabric power cord along the arms
  let cordCurve = [
    [neckX + 6, neckY + 4],
    [lerp(neckX, elbowX, 0.5) - 6, lerp(neckY, elbowY, 0.5) + 14],
    [elbowX + 6, elbowY + 2],
    [lerp(elbowX, forkX, 0.5) + 10, lerp(elbowY, forkY, 0.5) + 8],
    [baseX + 18, baseY - 2]
  ];
  strokePoly(cordCurve, "rotring", "#0F172A", 0.7, false, 0.35);

  // THE CONICAL BELL SHADE (Vivid Cerulean-Teal enamel with glowing warm-white interior)
  // Shade tilts down-left toward the books (mouth center at gx + 106, my + 124, rot = 32 deg)
  let mouthX = gx + 104;
  let mouthY = my + 124;
  let shadeRot = 34;

  // Ventilated hemispherical top cap of shade
  let capPts = getArcPts(neckX - 3, neckY + 4, 14, 14, 185, 45, shadeRot, 16);
  washPoly(capPts, "#0369A1", 240, 0.1);
  strokePoly(capPts, "rotring", "#082F49", 0.55, true, 0.1);

  // Conical flaring bell of shade
  let bellPts = [
    [neckX - 15, neckY - 3],
    [neckX + 9, neckY + 13],
    [mouthX + 31, mouthY + 21],
    [mouthX - 31, mouthY - 21]
  ];
  washPoly(bellPts, "#0284C7", 240, 0.08);
  wcPoly(bellPts, "#0EA5E9", 150, 0.06, 0.45, 0.25, 0.08);

  // Bright specular highlight stripe down the sunlit upper-left of the conical shade
  washPoly(
    [
      [neckX - 11, neckY - 1],
      [neckX - 4, neckY + 4],
      [mouthX - 8, mouthY - 6],
      [mouthX - 22, mouthY - 15]
    ],
    "#7DD3FC",
    190,
    0
  );
  ruledLine(neckX - 8, neckY + 1, mouthX - 15, mouthY - 10, "cpencil", "#E0F2FE", 1.1);

  // Core shadow on lower-right side of conical shade
  washPoly(
    [
      [neckX + 1, neckY + 8],
      [neckX + 9, neckY + 13],
      [mouthX + 31, mouthY + 21],
      [mouthX + 10, mouthY + 7]
    ],
    "#0C4A6E",
    195,
    0
  );
  strokePoly(bellPts, "rotring", "#082F49", 0.6, true, 0.05);

  // Illuminated elliptical mouth of the shade & warm bulb cone inside
  let mouthOuter = getEllipsePts(mouthX, mouthY, 37, 11, shadeRot, 28);
  let mouthInner = getEllipsePts(mouthX, mouthY, 34, 9.2, shadeRot, 28);
  washPoly(mouthOuter, "#E0F2FE", 235, 0.1);
  washPoly(mouthInner, "#FEF9C3", 235, 0.1);
  // Glowing warm bulb tip peeking inside the reflector cone
  let bulbPts = getEllipsePts(mouthX + 5, mouthY - 2, 11, 5.5, shadeRot, 18);
  washPoly(bulbPts, "#FFFFFF", 245, 0.15);
  strokePoly(mouthOuter, "rotring", "#082F49", 0.55, true, 0.1);
  strokePoly(mouthInner, "rotring", "#CA8A04", 0.45, true, 0.1);

  // 4. Cool graphite-grey watercolor veil over the pane so the desk lamp sits behind glass
  wcRect(gx, my, gw, mh, "#2B3A4A", 42, 0.08, 0.4, 0.25);
  drawGlassReflections(gx, gy, gw, gh, ty, my, mh, vx, 1.0);
}

// ============================================================================
// 3. WINDOW REVEALS, CONCRETE SILLS, AND RULED-PEN STEEL MULLIONS
// ============================================================================
function drawWindowArchitectureAndMullions(bx, by, isOrangeWindow = false) {
  let bw = WIN_W; // 320
  let bh = WIN_H; // 460
  let fx = bx + 12;
  let fy = by + 12;
  let fw = 296;
  let fh = 442;
  let gx = fx + 10;
  let gy = fy + 10;
  let gw = 276;
  let gh = 422;
  let ty = gy + 86; // Top of horizontal transom mullion
  let vx = gx + 134; // Left of vertical transom mullion

  // --------------------------------------------------------------------------
  // A. RECESSED WHITE RENDER REVEALS (Top lintel, Left jamb, Right jamb)
  // --------------------------------------------------------------------------
  // Top lintel reveal (in cool cast shadow)
  washPoly(
    [
      [bx, by],
      [bx + bw, by],
      [fx + fw, fy],
      [fx, fy]
    ],
    "#7C8DA3",
    225,
    0
  );
  hatchPoly(
    [
      [bx, by],
      [bx + bw, by],
      [fx + fw, fy],
      [fx, fy]
    ],
    "2H",
    "#526378",
    0.35,
    6,
    45,
    { rand: 0.02 },
    0
  );

  // Left jamb reveal (in cool mid-shadow)
  washPoly(
    [
      [bx, by],
      [fx, fy],
      [fx, fy + fh],
      [bx, by + bh - 6]
    ],
    "#96A6BA",
    220,
    0
  );
  hatchPoly(
    [
      [bx, by],
      [fx, fy],
      [fx, fy + fh],
      [bx, by + bh - 6]
    ],
    "2H",
    "#6B7C91",
    0.35,
    7,
    90,
    { rand: 0.02 },
    0
  );

  // Right jamb reveal (catching bright sunlit bounce, or warm orange spill in window 5)
  let rightRevealCol = isOrangeWindow ? "#F4E3D6" : "#F3F5F8";
  washPoly(
    [
      [bx + bw, by],
      [fx + fw, fy],
      [fx + fw, fy + fh],
      [bx + bw, by + bh - 6]
    ],
    rightRevealCol,
    230,
    0
  );

  // Cast shadow falling from top/left stucco reveal onto the steel frame & glass
  washRect(fx, fy, fw, 15, "#0D1520", 75);
  washRect(fx, fy + 15, 14, fh - 15, "#0D1520", 60);

  // --------------------------------------------------------------------------
  // B. STEEL OUTER FRAME & T-MULLIONS (Drawn in precise ruled Rotring pen)
  // --------------------------------------------------------------------------
  let steelDark = "#1C232B";
  let steelMid = "#2C3642";
  let steelLight = isOrangeWindow ? "#785240" : "#566678";
  let penBlack = "#0A0E13";

  // 1. Outer steel box frame (10px thick around gx, gy, gw, gh)
  // Top bar
  washRect(fx, fy, fw, 10, steelDark, 245);
  // Bottom bar
  washRect(fx, gy + gh, fw, 10, steelDark, 245);
  // Left bar
  washRect(fx, fy + 10, 10, gh, steelDark, 245);
  // Right bar
  washRect(gx + gw, fy + 10, 10, gh, steelDark, 245);

  // 2. Horizontal steel transom mullion (10px thick: ty to ty + 10)
  washRect(gx, ty, gw, 10, steelDark, 248);
  // Metallic bevel highlight along top edge of horizontal transom mullion
  washRect(gx, ty + 1.5, gw, 2.5, steelMid, 230);
  if (isOrangeWindow) {
    // Warm signal-orange light spill on underside of transom mullion & inner frame!
    washRect(gx, ty + 7.5, gw, 2.5, "#FF6D00", 170);
    washRect(gx, gy + gh - 2, gw, 3, "#FF7B00", 190);
  }

  // 3. Vertical steel transom mullion (8px thick: vx to vx + 8, from gy to ty)
  washRect(vx, gy, 8, 86, steelDark, 248);
  washRect(vx + 1.5, gy, 2, 86, steelMid, 225);

  // 4. Inner steel casement sash frames inside each of the 3 panes (4px wide)
  let panes = [
    [gx, gy, 134, 86],       // Top-left transom
    [vx + 8, gy, 134, 86],   // Top-right transom
    [gx, ty + 10, gw, 326]   // Main lower pane
  ];

  for (let i = 0; i < panes.length; i++) {
    let [px, py, pw, ph] = panes[i];
    let s = 4.5; // Sash frame width

    // Sash steel border strips
    washRect(px, py, pw, s, steelMid, 235);
    washRect(px, py + ph - s, pw, s, steelMid, 235);
    washRect(px, py + s, s, ph - s * 2, steelMid, 235);
    washRect(px + pw - s, py + s, s, ph - s * 2, steelMid, 235);

    // Outer perimeter of pane (glazing frame joint)
    strokePoly(
      [
        [px, py],
        [px + pw, py],
        [px + pw, py + ph],
        [px, py + ph]
      ],
      "rotring",
      penBlack,
      0.7,
      true,
      0
    );

    // Inner glazing bead line (precise ruled pen)
    strokePoly(
      [
        [px + s, py + s],
        [px + pw - s, py + s],
        [px + pw - s, py + ph - s],
        [px + s, py + ph - s]
      ],
      "rotring",
      penBlack,
      0.55,
      true,
      0
    );

    // Metallic specular hairline on sash bevel
    let hlCol = (isOrangeWindow && i === 2) ? "#FF9E00" : steelLight;
    ruledLine(px + s + 1, py + ph - s - 1, px + pw - s - 1, py + ph - s - 1, "rotring", hlCol, 0.4);
    ruledLine(px + pw - s - 1, py + s + 1, px + pw - s - 1, py + ph - s - 1, "rotring", hlCol, 0.4);

    // Mitered corner weld joints on each steel sash
    ruledLine(px, py, px + s, py + s, "rotring", penBlack, 0.45);
    ruledLine(px + pw, py, px + pw - s, py + s, "rotring", penBlack, 0.45);
    ruledLine(px + pw, py + ph, px + pw - s, py + ph - s, "rotring", penBlack, 0.45);
    ruledLine(px, py + ph, px + s, py + ph - s, "rotring", penBlack, 0.45);
  }

  // 5. Precision ruled pen lines for outer steel frame & T-mullions
  // Outer boundary of steel frame
  strokePoly(
    [
      [fx, fy],
      [fx + fw, fy],
      [fx + fw, fy + fh],
      [fx, fy + fh]
    ],
    "rotring",
    penBlack,
    0.8,
    true,
    0
  );
  // Inner stepped profile line of outer steel box frame
  strokePoly(
    [
      [fx + 4, fy + 4],
      [fx + fw - 4, fy + 4],
      [fx + fw - 4, fy + fh - 4],
      [fx + 4, fy + fh - 4]
    ],
    "rotring",
    "#3E4C5C",
    0.4,
    true,
    0
  );

  // Ruled profile lines along the horizontal transom mullion
  ruledLine(gx, ty, gx + gw, ty, "rotring", penBlack, 0.75);
  ruledLine(gx, ty + 3.5, gx + gw, ty + 3.5, "rotring", "#5A6B7E", 0.4);
  ruledLine(gx, ty + 6.5, gx + gw, ty + 6.5, "rotring", penBlack, 0.45);
  ruledLine(gx, ty + 10, gx + gw, ty + 10, "rotring", penBlack, 0.75);

  // Ruled profile lines along the vertical transom mullion
  ruledLine(vx, gy, vx, ty, "rotring", penBlack, 0.7);
  ruledLine(vx + 4, gy, vx + 4, ty, "rotring", "#5A6B7E", 0.4);
  ruledLine(vx + 8, gy, vx + 8, ty, "rotring", penBlack, 0.7);

  // 6. Small hyperreal hardware details: casement handle, hopper latches, hinge barrels
  // Hopper latches at bottom-center of top-left and top-right transom panes
  let latchX = [gx + 67, vx + 8 + 67];
  for (let lx of latchX) {
    washRect(lx - 5, ty - 5, 10, 4, "#94A3B8", 230);
    strokePoly(
      [
        [lx - 5, ty - 5],
        [lx + 5, ty - 5],
        [lx + 5, ty - 1],
        [lx - 5, ty - 1]
      ],
      "rotring",
      penBlack,
      0.4,
      true,
      0
    );
    // Tiny latch lever
    washRect(lx - 1.5, ty - 3, 3, 7, "#E2E8F0", 240);
    ruledLine(lx, ty - 3, lx, ty + 4, "rotring", penBlack, 0.45);
  }

  // Main casement handle on right sash rail (at mid-height of main pane)
  let hx = gx + gw - 3.5;
  let hy = ty + 10 + 148;
  washRect(hx - 2.5, hy - 8, 5, 16, "#94A3B8", 235);
  washRect(hx - 1.5, hy, 3.5, 22, "#CBD5E1", 240);
  ruledLine(hx, hy - 7, hx, hy + 21, "rotring", penBlack, 0.5);

  // Hinge barrels on left frame rail
  let hingeY = [ty + 45, ty + 275];
  for (let hy2 of hingeY) {
    washRect(gx - 2, hy2 - 7, 4, 14, "#64748B", 235);
    ruledLine(gx, hy2 - 7, gx, hy2 + 7, "rotring", penBlack, 0.55);
  }

  // --------------------------------------------------------------------------
  // C. PROJECTING PRECAST CONCRETE SILL & WEATHERING
  // --------------------------------------------------------------------------
  let sx = bx - 8;
  let sw = bw + 16; // 336
  let sy = by + bh - 6; // Overlaps bottom of reveal

  // 1. Cast shadow underneath the projecting concrete sill
  washPoly(
    [
      [sx + 4, sy + 18],
      [sx + sw + 6, sy + 18],
      [sx + sw + 6, sy + 30],
      [sx + 8, sy + 28]
    ],
    "#7A8B9E",
    175,
    0
  );
  washRect(sx + 2, sy + 18, sw, 5, "#516275", 195);

  // Subtle rainwater vertical drip stains at the left and right ends of the sill
  for (let endX of [sx + 4, sx + sw - 8]) {
    wcRect(endX, sy + 20, 7, 36, "#9AA8B8", 55, 0.2, 0.5, 0.2);
    ruledLine(endX + 3, sy + 19, endX + 3, sy + 48, "2H", "#8B99AA", 0.35);
  }

  // 2. Top sloped wash of the concrete sill (bright sunlit white)
  let sillTopCol = isOrangeWindow ? "#FFF2E6" : "#FFFFFF";
  washPoly(
    [
      [fx, fy + fh],
      [fx + fw, fy + fh],
      [sx + sw, sy + 6],
      [sx, sy + 6]
    ],
    sillTopCol,
    245,
    0
  );
  if (isOrangeWindow) {
    // Warm signal-orange reflection glow on the center of the sill top
    wcRect(bx + 35, sy, bw - 70, 7, "#FF7B00", 70, 0.15, 0.35, 0.2);
  }

  // 3. Front vertical face of the concrete sill (sy + 6 to sy + 18)
  washRect(sx, sy + 6, sw, 12, "#E2E6EC", 245);
  // Subtle lower drip shadow line on sill face
  washRect(sx, sy + 15, sw, 3, "#C4CDD8", 220);
  // Fine concrete texture on sill face
  hatchRect(sx, sy + 6, sw, 12, "2H", "#B8C2CE", 0.3, 5, 0, { rand: 0.04 });

  // 4. Crisp ruled Rotring pen lines for the reveal & concrete sill
  // Outer reveal top and side edges
  ruledLine(bx, by, bx + bw, by, "rotring", "#1E2630", 0.65);
  ruledLine(bx, by, bx, sy + 6, "rotring", "#1E2630", 0.65);
  ruledLine(bx + bw, by, bx + bw, sy + 6, "rotring", "#475569", 0.55);
  // Diagonal miter lines at top-left and top-right reveals
  ruledLine(bx, by, fx, fy, "rotring", "#1E2630", 0.55);
  ruledLine(bx + bw, by, fx + fw, fy, "rotring", "#334155", 0.5);

  // Concrete sill ruled outlines & expansion joints
  ruledLine(sx, sy + 6, sx + sw, sy + 6, "rotring", "#1E293B", 0.6);
  ruledLine(sx, sy + 18, sx + sw, sy + 18, "rotring", "#0F172A", 0.75);
  ruledLine(sx, sy + 6, sx, sy + 18, "rotring", "#1E293B", 0.6);
  ruledLine(sx + sw, sy + 6, sx + sw, sy + 18, "rotring", "#1E293B", 0.6);
  ruledLine(bx, sy + 6, sx, sy + 6, "rotring", "#1E293B", 0.5);
  ruledLine(bx + bw, sy + 6, sx + sw, sy + 6, "rotring", "#1E293B", 0.5);
  // Precast sill segment joints at one-third points
  ruledLine(sx + 112, sy + 2, sx + 112, sy + 18, "rotring", "#64748B", 0.4);
  ruledLine(sx + 224, sy + 2, sx + 224, sy + 18, "rotring", "#64748B", 0.4);
}

