// Hyperrealist study: Spilled black coffee across an embossed paper napkin on a pale ash café table

const NAPKIN_CX = 655;
const NAPKIN_CY = 635;
const NAPKIN_HALF = 395;
const NAPKIN_ANGLE = -7.5; // degrees
const QUILT_PITCH = 24;    // diamond embossing grid spacing in px
const BORDER_OUTER = 14;
const BORDER_INNER = 86;

const SPILL_ORIGIN_X = 468;
const SPILL_ORIGIN_Y = 488;
const NUM_BANDS = 11;

let cosN, sinN;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);

  randomSeed(42719);
  noiseSeed(8831);

  cosN = cos(NAPKIN_ANGLE);
  sinN = sin(NAPKIN_ANGLE);

  // Custom fine graphite tip for crisp paper embossing relief
  brush.add("emboss_pencil", {
    type: "default",
    weight: 0.28,
    scatter: 0.08,
    sharpness: 0.82,
    grain: 0.45,
    opacity: 145,
    spacing: 0.15,
    pressure: [0.65, 1.0, 0.65],
    noise: 0.35
  });

  // Custom chromatographic tide-line brush
  brush.add("tide_edge", {
    type: "default",
    weight: 0.48,
    scatter: 0.14,
    sharpness: 0.76,
    grain: 0.55,
    opacity: 170,
    spacing: 0.12,
    pressure: [0.8, 1.15, 0.75],
    noise: 0.5
  });

  // Custom dry cellulose fibre brush for wicking edges
  brush.add("dry_fibre", {
    type: "default",
    weight: 0.22,
    scatter: 0.12,
    sharpness: 0.9,
    grain: 0.75,
    opacity: 130,
    spacing: 0.15,
    pressure: [1.1, 0.6, 0.05],
    noise: 0.6
  });

  // Custom smooth gloss brush for liquid meniscus and porcelain highlights
  brush.add("gloss_pen", {
    type: "marker",
    weight: 0.7,
    scatter: 0.01,
    opacity: 220,
    spacing: 0.08,
    pressure: [0.4, 1.0, 0.4],
    markerTip: false,
    noise: 0.08
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#eae0d0");

  // 1. Pale ash café table surface
  drawAshTable();

  // 2. Napkin cast shadow and offset bottom ply
  drawNapkinShadowAndUnderPly();

  // 3. Main white paper napkin base & quarter-fold creases
  drawNapkinBase();

  // 4. Fine pencil embossed quilting pattern on dry white napkin
  drawEmbossedQuiltingBase();

  // 5. Precompute nested isochrone contours distorted by the quilting grid
  let bands = buildIsochroneBands();

  // 6. Paint nested watercolour isochrone washes (outermost tea-stain to innermost espresso)
  drawIsochroneWashes(bands);

  // 7. Draw dry-fibre feathering, capillary wicking whiskers, and hard tide-line edges
  drawDryFibreAndTideLines(bands);

  // 8. Re-inforce embossed quilting channels & border ribs across the stained bands
  drawStainedQuiltingOverlay(bands);

  // 9. Draw satellite wicking drops on napkin & glossy beads on table
  drawSatelliteDrops();

  // 10. Draw photoreal glossy pooled coffee puddle at the source
  drawGlossyPuddle();

  // 11. Draw the tipped porcelain café cup at the source
  drawTippedCup();

  noLoop();
}

// ============================================================================
// COORDINATE & QUILTING MATH HELPERS
// ============================================================================

function toNapkin(x, y) {
  let dx = x - NAPKIN_CX;
  let dy = y - NAPKIN_CY;
  return {
    u: dx * cosN + dy * sinN,
    v: -dx * sinN + dy * cosN
  };
}

function fromNapkin(u, v) {
  return {
    x: NAPKIN_CX + u * cosN - v * sinN,
    y: NAPKIN_CY + u * sinN + v * cosN
  };
}

function napkinEdgeOffset(u, v) {
  return 2.2 * (noise(u * 0.015 + 10, v * 0.015 + 20) - 0.5);
}

function isInsideNapkin(x, y, margin = 3) {
  let p = toNapkin(x, y);
  let lim = NAPKIN_HALF - margin + napkinEdgeOffset(p.u, p.v);
  return Math.abs(p.u) <= lim && Math.abs(p.v) <= lim;
}

// Evaluates the napkin's embossing relief and capillary distortion at napkin coords (u, v)
function evaluateQuiltDistortion(u, v, s) {
  let absU = Math.abs(u);
  let absV = Math.abs(v);
  let maxUV = Math.max(absU, absV);

  // Diagonal diamond quilting coordinates
  let d1 = (u + v) * 0.70710678;
  let d2 = (u - v) * 0.70710678;
  let phase1 = (d1 / QUILT_PITCH) * 360;
  let phase2 = (d2 / QUILT_PITCH) * 360;

  let c1 = cos(phase1);
  let c2 = cos(phase2);

  // Strong diamond-channel scalloping (compressed channels wick faster than pillow centers)
  let diamondScallop = 5.8 * c1 + 5.8 * c2 + 3.2 * c1 * c2;
  // Sharper step along channel intersections
  let channelStep = 2.6 * (Math.pow(0.5 + 0.5 * c1, 3) + Math.pow(0.5 + 0.5 * c2, 3) - 0.5);

  // Quarter-fold central creases channel liquid outward
  let creaseU = 15.0 * Math.exp(-(u * u) / 260.0) * (0.4 + 0.6 * s);
  let creaseV = 13.0 * Math.exp(-(v * v) / 260.0) * (0.4 + 0.6 * s);

  // If near the perimeter embossed border frame, flutes run perpendicular to edge
  let borderDistort = 0;
  if (maxUV > NAPKIN_HALF - BORDER_INNER) {
    let fluteCoord = absU > absV ? v : u;
    borderDistort = 4.2 * cos((fluteCoord / 7.5) * 360);
    diamondScallop *= 0.25;
  }

  return diamondScallop + channelStep + creaseU + creaseV + borderDistort;
}

// ============================================================================
// 1. PALE ASH CAFÉ TABLE
// ============================================================================

function drawAshTable() {
  brush.noStroke();
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.35, 0.2);

  // Subtle warm ash tonal undertones
  brush.fill("#e3d6c3", 65);
  brush.rect(0, 0, 1200, 1200, "corner");

  brush.fill("#d9c9b2", 45);
  brush.beginShape(0.2);
  brush.vertex(0, 0);
  brush.vertex(520, 0);
  brush.vertex(470, 1200);
  brush.vertex(0, 1200);
  brush.endShape(true);

  brush.fill("#efe6d8", 55);
  brush.beginShape(0.2);
  brush.vertex(520, 0);
  brush.vertex(1200, 0);
  brush.vertex(1200, 1200);
  brush.vertex(470, 1200);
  brush.endShape(true);

  brush.noFill();

  // Ash wood grain lines & cathedral arches across two wide planks
  let joinTopX = 485;
  let joinBotX = 445;

  for (let i = 0; i < 195; i++) {
    let t = i / 195;
    let baseX = t * 1240 - 20;
    let isLeftPlank = baseX < 465;

    let colChoice = i % 5 === 0 ? "#cab89f" : (i % 2 === 0 ? "#d6c6b0" : "#f2eadc");
    let wt = map(noise(i * 0.3), 0, 1, 0.22, 0.55);
    brush.set(i % 3 === 0 ? "cpencil" : "2H", colChoice, wt);

    let pts = [];
    for (let y = -10; y <= 1210; y += 40) {
      let joinXAtY = lerp(joinTopX, joinBotX, y / 1200);
      let dx = baseX - (isLeftPlank ? 210 : 860);
      // Cathedral grain wave
      let arch = Math.sin((y / 1200) * Math.PI * (isLeftPlank ? 1.4 : 1.8) + (isLeftPlank ? 0.5 : 1.7));
      let wave = 22 * Math.sin(dx * 0.018) * arch + 14 * (noise(baseX * 0.006, y * 0.004) - 0.5);
      let x = baseX + wave;

      // Keep grain faithful to its plank
      if (isLeftPlank && x > joinXAtY - 2) x = joinXAtY - 2;
      if (!isLeftPlank && x < joinXAtY + 2) x = joinXAtY + 2;

      pts.push([x, y, 0.7 + 0.4 * noise(i, y * 0.01)]);
    }
    brush.spline(pts, 0.35);
  }

  // Fine ash wood open-pore flecks
  brush.set("2H", "#bfa98e", 0.32);
  for (let i = 0; i < 420; i++) {
    let px = random(20, 1180);
    let py = random(20, 1180);
    // Skip deep interior of napkin for speed
    if (isInsideNapkin(px, py, 35)) continue;
    let len = random(4, 15);
    brush.line(px, py, px - len * 0.03, py + len);
  }

  // Plank join seam
  brush.set("HB", "#b59f84", 0.45);
  brush.line(joinTopX, 0, joinBotX, 1200);
  brush.set("2H", "#f5ede0", 0.35);
  brush.line(joinTopX + 2, 0, joinBotX + 2, 1200);
}

// ============================================================================
// 2. NAPKIN SHADOW & SECOND PLY
// ============================================================================

function drawNapkinShadowAndUnderPly() {
  // Soft layered drop shadow under the napkin
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.25, 0.2);

  let shadowOffsets = [
    { dx: 11, dy: 14, col: "#cbb89e", alpha: 75 },
    { dx: 6, dy: 8, col: "#b59f84", alpha: 85 },
    { dx: 2.5, dy: 3.5, col: "#998268", alpha: 95 }
  ];

  for (let sh of shadowOffsets) {
    brush.fill(sh.col, sh.alpha);
    brush.beginShape(0.08);
    let steps = 20;
    for (let i = 0; i < steps; i++) {
      let u = map(i, 0, steps, -NAPKIN_HALF, NAPKIN_HALF);
      let p = fromNapkin(u, -NAPKIN_HALF);
      brush.vertex(p.x + sh.dx, p.y + sh.dy);
    }
    for (let i = 0; i < steps; i++) {
      let v = map(i, 0, steps, -NAPKIN_HALF, NAPKIN_HALF);
      let p = fromNapkin(NAPKIN_HALF, v);
      brush.vertex(p.x + sh.dx, p.y + sh.dy);
    }
    for (let i = 0; i < steps; i++) {
      let u = map(i, 0, steps, NAPKIN_HALF, -NAPKIN_HALF);
      let p = fromNapkin(u, NAPKIN_HALF);
      brush.vertex(p.x + sh.dx, p.y + sh.dy);
    }
    for (let i = 0; i < steps; i++) {
      let v = map(i, 0, steps, NAPKIN_HALF, -NAPKIN_HALF);
      let p = fromNapkin(-NAPKIN_HALF, v);
      brush.vertex(p.x + sh.dx, p.y + sh.dy);
    }
    brush.endShape(true);
  }

  // Slightly rotated lower ply peeking out on right and bottom edges (classic 2-ply paper napkin detail)
  let plyAngle = NAPKIN_ANGLE + 1.35;
  let cP = cos(plyAngle);
  let sP = sin(plyAngle);
  let plyCX = NAPKIN_CX + 6;
  let plyCY = NAPKIN_CY + 7;

  brush.wash("#f2ede3", 235);
  brush.beginShape(0.05);
  let corners = [
    [-NAPKIN_HALF, -NAPKIN_HALF],
    [NAPKIN_HALF, -NAPKIN_HALF],
    [NAPKIN_HALF, NAPKIN_HALF],
    [-NAPKIN_HALF, NAPKIN_HALF]
  ];
  for (let c of corners) {
    let x = plyCX + c[0] * cP - c[1] * sP;
    let y = plyCY + c[0] * sP + c[1] * cP;
    brush.vertex(x, y);
  }
  brush.endShape(true);
  brush.noWash();

  // Edge line of lower ply
  brush.set("2H", "#b8afa2", 0.35);
  for (let s = 0; s < 4; s++) {
    let cA = corners[s];
    let cB = corners[(s + 1) % 4];
    let x1 = plyCX + cA[0] * cP - cA[1] * sP;
    let y1 = plyCY + cA[0] * sP + cA[1] * cP;
    let x2 = plyCX + cB[0] * cP - cB[1] * sP;
    let y2 = plyCY + cB[0] * sP + cB[1] * cP;
    brush.line(x1, y1, x2, y2);
  }
}

// ============================================================================
// 3. MAIN WHITE PAPER NAPKIN BASE
// ============================================================================

function getNapkinPerimeterPoints(stepCount = 28) {
  let pts = [];
  // Top edge
  for (let i = 0; i < stepCount; i++) {
    let u = map(i, 0, stepCount, -NAPKIN_HALF, NAPKIN_HALF);
    let v = -NAPKIN_HALF + napkinEdgeOffset(u, -NAPKIN_HALF);
    pts.push(fromNapkin(u, v));
  }
  // Right edge
  for (let i = 0; i < stepCount; i++) {
    let v = map(i, 0, stepCount, -NAPKIN_HALF, NAPKIN_HALF);
    let u = NAPKIN_HALF + napkinEdgeOffset(NAPKIN_HALF, v);
    pts.push(fromNapkin(u, v));
  }
  // Bottom edge
  for (let i = 0; i < stepCount; i++) {
    let u = map(i, 0, stepCount, NAPKIN_HALF, -NAPKIN_HALF);
    let v = NAPKIN_HALF + napkinEdgeOffset(u, NAPKIN_HALF);
    pts.push(fromNapkin(u, v));
  }
  // Left edge
  for (let i = 0; i < stepCount; i++) {
    let v = map(i, 0, stepCount, NAPKIN_HALF, -NAPKIN_HALF);
    let u = -NAPKIN_HALF + napkinEdgeOffset(-NAPKIN_HALF, v);
    pts.push(fromNapkin(u, v));
  }
  return pts;
}

function drawNapkinBase() {
  let perim = getNapkinPerimeterPoints(30);

  // Opaque warm-white paper base wash so wood grain stays beneath the napkin
  brush.noStroke();
  brush.wash("#faf7f0", 248);
  brush.beginShape(0.05);
  for (let p of perim) brush.vertex(p.x, p.y);
  brush.endShape(true);
  brush.noWash();

  // Subtle paper-tooth watercolour wash for warm dimensionality
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.45, 0.25);
  brush.fill("#f4efe4", 55);
  brush.beginShape(0.05);
  for (let p of perim) brush.vertex(p.x, p.y);
  brush.endShape(true);
  brush.noFill();

  // Quarter-fold central creases (u = 0 ridge, v = 0 soft valley)
  // Horizontal fold in napkin space (v = 0)
  for (let offset = -5; offset <= 5; offset += 2) {
    let col = offset < 0 ? "#e6dfd2" : (offset === 1 ? "#ffffff" : "#ece6da");
    brush.set("2H", col, 0.35);
    let p1 = fromNapkin(-NAPKIN_HALF + 4, offset);
    let p2 = fromNapkin(NAPKIN_HALF - 4, offset);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Vertical fold in napkin space (u = 0)
  for (let offset = -5; offset <= 5; offset += 2) {
    let col = offset > 0 ? "#e3dccf" : (offset === -1 ? "#ffffff" : "#ebe5d8");
    brush.set("2H", col, 0.35);
    let p1 = fromNapkin(offset, -NAPKIN_HALF + 4);
    let p2 = fromNapkin(offset, NAPKIN_HALF - 4);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Crisp shadow/highlight along the top-ply cut edges
  brush.set("2H", "#c4bbb0", 0.38);
  let strokePts = perim.map(p => [p.x, p.y, 0.8]);
  strokePts.push([perim[0].x, perim[0].y, 0.8]);
  brush.spline(strokePts, 0.15);
}

// ============================================================================
// 4. FINE PENCIL EMBOSSED QUILTING PATTERN (BASE DRY-NAPKIN PASS)
// ============================================================================

function drawEmbossedQuiltingBase() {
  let innerLim = NAPKIN_HALF - BORDER_INNER;
  let outerLim = NAPKIN_HALF - BORDER_OUTER;

  // A. Framing rules of the embossed perimeter border
  let frameRadii = [outerLim, outerLim - 6, innerLim + 6, innerLim];
  for (let r of frameRadii) {
    // Shadow side of embossed groove
    brush.set("emboss_pencil", "#b5ada0", 0.78);
    let c1 = fromNapkin(-r, -r);
    let c2 = fromNapkin(r, -r);
    let c3 = fromNapkin(r, r);
    let c4 = fromNapkin(-r, r);
    brush.line(c1.x, c1.y, c2.x, c2.y);
    brush.line(c2.x, c2.y, c3.x, c3.y);
    brush.line(c3.x, c3.y, c4.x, c4.y);
    brush.line(c4.x, c4.y, c1.x, c1.y);

    // Highlight lip of embossed groove
    brush.set("emboss_pencil", "#ffffff", 0.65);
    let h1 = fromNapkin(-r + 1.2, -r + 1.2);
    let h2 = fromNapkin(r + 1.2, -r + 1.2);
    let h3 = fromNapkin(r + 1.2, r + 1.2);
    let h4 = fromNapkin(-r + 1.2, r + 1.2);
    brush.line(h1.x, h1.y, h2.x, h2.y);
    brush.line(h4.x, h4.y, h1.x, h1.y);
  }

  // B. Crimped perpendicular flutes around all 4 border margins
  let fluteStep = 7.5;
  let fStart = -innerLim + 4;
  let fEnd = innerLim - 4;

  for (let pos = fStart; pos <= fEnd; pos += fluteStep) {
    // Top & Bottom borders
    for (let side of [-1, 1]) {
      let v1 = side * (innerLim + 9);
      let v2 = side * (outerLim - 9);
      let pA = fromNapkin(pos, v1);
      let pB = fromNapkin(pos, v2);
      brush.set("emboss_pencil", "#b8b0a2", 0.72);
      brush.line(pA.x, pA.y, pB.x, pB.y);

      let pAh = fromNapkin(pos + 1.3, v1);
      let pBh = fromNapkin(pos + 1.3, v2);
      brush.set("emboss_pencil", "#ffffff", 0.55);
      brush.line(pAh.x, pAh.y, pBh.x, pBh.y);
    }

    // Left & Right borders
    for (let side of [-1, 1]) {
      let u1 = side * (innerLim + 9);
      let u2 = side * (outerLim - 9);
      let pA = fromNapkin(u1, pos);
      let pB = fromNapkin(u2, pos);
      brush.set("emboss_pencil", "#b8b0a2", 0.72);
      brush.line(pA.x, pA.y, pB.x, pB.y);

      let pAh = fromNapkin(u1, pos + 1.3);
      let pBh = fromNapkin(u2, pos + 1.3);
      brush.set("emboss_pencil", "#ffffff", 0.55);
      brush.line(pAh.x, pAh.y, pBh.x, pBh.y);
    }
  }

  // C. Corner embossed rosettes in the 4 border corners
  let cornerSigns = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
  for (let cs of cornerSigns) {
    let cu = cs[0] * (innerLim + outerLim) * 0.5;
    let cv = cs[1] * (innerLim + outerLim) * 0.5;
    for (let d = 8; d <= 22; d += 7) {
      let p1 = fromNapkin(cu - d, cv);
      let p2 = fromNapkin(cu, cv - d);
      let p3 = fromNapkin(cu + d, cv);
      let p4 = fromNapkin(cu, cv + d);
      brush.set("emboss_pencil", "#b0a798", 0.75);
      brush.line(p1.x, p1.y, p2.x, p2.y);
      brush.line(p2.x, p2.y, p3.x, p3.y);
      brush.line(p3.x, p3.y, p4.x, p4.y);
      brush.line(p4.x, p4.y, p1.x, p1.y);
    }
  }

  // D. Interior Diagonal Diamond Quilting Pattern (u + v = c and u - v = c)
  // Channels are spaced by QUILT_PITCH * sqrt(2) in (u+v) and (u-v)
  let diagPitch = QUILT_PITCH * 1.41421356;
  let maxDiag = 2 * innerLim;

  for (let c = -maxDiag + diagPitch * 0.5; c <= maxDiag - diagPitch * 0.5; c += diagPitch) {
    // 1. Lines where u + v = c
    let uMin1 = Math.max(-innerLim, c - innerLim);
    let uMax1 = Math.min(innerLim, c + innerLim);
    if (uMax1 - uMin1 > 6) {
      drawQuiltedChannelLine(uMin1, c - uMin1, uMax1, c - uMax1, "#b4aba0", "#ffffff", 0.75);
    }

    // 2. Lines where u - v = c  =>  v = u - c
    let uMin2 = Math.max(-innerLim, c - innerLim);
    let uMax2 = Math.min(innerLim, c + innerLim);
    if (uMax2 - uMin2 > 6) {
      drawQuiltedChannelLine(uMin2, uMin2 - c, uMax2, uMax2 - c, "#b4aba0", "#ffffff", 0.75);
    }
  }

  // E. Subtle pillow-corner stipple/relief marks inside each quilted diamond cell
  brush.set("emboss_pencil", "#c2b9ad", 0.58);
  for (let c1 = -maxDiag + diagPitch; c1 <= maxDiag - diagPitch; c1 += diagPitch) {
    for (let c2 = -maxDiag + diagPitch; c2 <= maxDiag - diagPitch; c2 += diagPitch) {
      // Intersection of u + v = c1 and u - v = c2
      let u = 0.5 * (c1 + c2);
      let v = 0.5 * (c1 - c2);
      if (Math.abs(u) < innerLim - 5 && Math.abs(v) < innerLim - 5) {
        // Small embossed cross-pin at channel intersection
        let pA = fromNapkin(u - 2.2, v);
        let pB = fromNapkin(u + 2.2, v);
        let pC = fromNapkin(u, v - 2.2);
        let pD = fromNapkin(u, v + 2.2);
        brush.line(pA.x, pA.y, pB.x, pB.y);
        brush.line(pC.x, pC.y, pD.x, pD.y);
      }
    }
  }
}

// Helper to draw a lightly segmented embossed channel with shadow + highlight ridge
function drawQuiltedChannelLine(u1, v1, u2, v2, shadowCol, hiCol, wt) {
  let distUV = Math.hypot(u2 - u1, v2 - v1);
  let segs = Math.max(2, Math.floor(distUV / 17));
  let nx = -(v2 - v1) / distUV;
  let ny = (u2 - u1) / distUV;

  brush.set("emboss_pencil", shadowCol, wt);
  for (let i = 0; i < segs; i++) {
    let tA = (i + 0.08) / segs;
    let tB = (i + 0.88) / segs;
    let pA = fromNapkin(lerp(u1, u2, tA), lerp(v1, v2, tA));
    let pB = fromNapkin(lerp(u1, u2, tB), lerp(v1, v2, tB));
    brush.line(pA.x, pA.y, pB.x, pB.y);
  }

  if (hiCol) {
    brush.set("emboss_pencil", hiCol, wt * 0.72);
    for (let i = 0; i < segs; i++) {
      let tA = (i + 0.12) / segs;
      let tB = (i + 0.85) / segs;
      let pA = fromNapkin(lerp(u1, u2, tA) + nx * 1.4, lerp(v1, v2, tA) + ny * 1.4);
      let pB = fromNapkin(lerp(u1, u2, tB) + nx * 1.4, lerp(v1, v2, tB) + ny * 1.4);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }
}

// ============================================================================
// 5. COMPUTE NESTED ISOCHRONE BANDS (QUILTING-DISTORTED)
// ============================================================================

function getIsochroneRadius(s, angDeg, seedOffset = 0) {
  // Primary spill flow axis points toward ~32 degrees (down and right across the napkin)
  let dAng = angDeg - 31;

  // Directional elongation away from the tipped cup mouth
  let forwardLobe = 0.58 + 0.42 * cos(dAng);
  let secondaryLobe =
    0.16 * cos(2 * dAng - 25) +
    0.11 * cos(3 * dAng + 40) +
    0.07 * sin(4 * dAng - 15);

  // Base puddle radius on napkin (s = 0) vs maximum outer wicking reach (s = 1)
  let rInner = 64 * (0.72 + 0.34 * cos(dAng) + 0.14 * cos(2 * dAng + 20));
  let rOuter = 445 * (0.46 + 0.54 * Math.pow(forwardLobe, 1.15) + secondaryLobe);

  // Non-linear chromatographic spacing (slightly tighter near source and at outer deceleration)
  let sShaped = Math.pow(s, 0.88);
  let baseR = lerp(rInner, rOuter, sShaped);

  // Organic fluid-front noise
  let nVal = noise(
    2.2 * cos(angDeg) + seedOffset * 0.37 + 10,
    2.2 * sin(angDeg) + seedOffset * 0.37 + 20
  );
  baseR += (nVal - 0.48) * (16 + 24 * s);

  // Evaluate tentative point in napkin coordinates to apply embossing quilting distortion
  let tx = SPILL_ORIGIN_X + baseR * cos(angDeg);
  let ty = SPILL_ORIGIN_Y + baseR * sin(angDeg);
  let np = toNapkin(tx, ty);

  let quiltShift = evaluateQuiltDistortion(np.u, np.v, s);
  let totalR = baseR + quiltShift * (0.45 + 0.75 * s);

  return Math.max(28, totalR);
}

function buildIsochroneBands() {
  // Warm palette stepping from espresso umber (band 0) through burnt sienna to faintest tea-stain amber (band 10)
  const palette = [
    { wash: "#3b0f03", alpha: 118, tide: "#210600", dry: "#2e0b02", s: 0.08 }, // 0: Deepest espresso umber
    { wash: "#561905", alpha: 105, tide: "#330b01", dry: "#451304", s: 0.17 }, // 1: Espresso umber
    { wash: "#732609", alpha: 96,  tide: "#471302", dry: "#5e1d06", s: 0.26 }, // 2: Dark roasted umber-sienna
    { wash: "#8f370f", alpha: 90,  tide: "#5e1f05", dry: "#782b0a", s: 0.36 }, // 3: Deep burnt sienna
    { wash: "#ab4c18", alpha: 84,  tide: "#752c08", dry: "#913b10", s: 0.46 }, // 4: Rich burnt sienna
    { wash: "#bf6324", alpha: 78,  tide: "#8a3e0f", dry: "#a65018", s: 0.56 }, // 5: Warm burnt sienna
    { wash: "#d17d35", alpha: 74,  tide: "#9e5319", dry: "#b86825", s: 0.66 }, // 6: Golden raw sienna
    { wash: "#de974c", alpha: 68,  tide: "#b06a27", dry: "#c98138", s: 0.76 }, // 7: Warm ochre amber
    { wash: "#e8b16a", alpha: 64,  tide: "#c2833c", dry: "#d69a50", s: 0.85 }, // 8: Honey tea-stain amber
    { wash: "#f0c98b", alpha: 58,  tide: "#d19c58", dry: "#e2b370", s: 0.93 }, // 9: Pale tea-stain amber
    { wash: "#f6dec0", alpha: 52,  tide: "#dfb578", dry: "#ecc994", s: 1.00 }  // 10: Faintest tea-stain amber
  ];

  let numSamples = 180;
  let prevRadii = new Array(numSamples).fill(0);
  let bands = [];

  for (let b = 0; b < palette.length; b++) {
    let spec = palette[b];
    let washPts = [];
    let highResPts = [];
    let currentRadii = [];

    for (let i = 0; i < numSamples; i++) {
      let ang = (i / numSamples) * 360;
      let r = getIsochroneRadius(spec.s, ang, b);

      // Guarantee strict outward nesting of every isochrone band
      if (b > 0) {
        let minStep = 8.5 + 3.5 * noise(b * 2.1, i * 0.08);
        r = Math.max(r, prevRadii[i] + minStep);
      }
      currentRadii.push(r);

      let wx = SPILL_ORIGIN_X + r * cos(ang);
      let wy = SPILL_ORIGIN_Y + r * sin(ang);

      // Clamp wicking strictly within the absorbent paper napkin
      let np = toNapkin(wx, wy);
      let maxLim = NAPKIN_HALF - 4 + napkinEdgeOffset(np.u, np.v);
      let clamped = false;
      if (np.u < -maxLim) { np.u = -maxLim; clamped = true; }
      if (np.u > maxLim)  { np.u = maxLim;  clamped = true; }
      if (np.v < -maxLim) { np.v = -maxLim; clamped = true; }
      if (np.v > maxLim)  { np.v = maxLim;  clamped = true; }

      let finalPt = fromNapkin(np.u, np.v);
      highResPts.push({
        x: finalPt.x,
        y: finalPt.y,
        u: np.u,
        v: np.v,
        ang: ang,
        r: r,
        clamped: clamped
      });

      // Subsample every 2nd vertex for fast, clean watercolour polygon triangulation
      if (i % 2 === 0) {
        washPts.push(finalPt);
      }
    }

    prevRadii = currentRadii;
    bands.push({
      index: b,
      wash: spec.wash,
      alpha: spec.alpha,
      tide: spec.tide,
      dry: spec.dry,
      s: spec.s,
      washPts: washPts,
      pts: highResPts
    });
  }

  return bands;
}

// ============================================================================
// 6. PAINT WATERCOLOUR ISOCHRONE WASHES
// ============================================================================

function drawIsochroneWashes(bands) {
  brush.noStroke();

  // Paint from outermost (faintest tea-stain amber) inward to innermost (espresso umber)
  for (let b = bands.length - 1; b >= 0; b--) {
    let band = bands[b];

    // High borderIntensity creates authentic chromatographic pigment pooling at the edge
    brush.fillBleed(0.025, "in");
    brush.fillTexture(0.68, 0.92);
    brush.fill(band.wash, band.alpha);

    brush.beginShape(0.22);
    for (let p of band.washPts) {
      brush.vertex(p.x, p.y);
    }
    brush.endShape(true);
  }

  brush.noFill();
}

// ============================================================================
// 7. DRY-FIBRE FEATHERING & HARD TIDE-LINE EDGES
// ============================================================================

function drawDryFibreAndTideLines(bands) {
  // A. Dry-paper pillow highlights on the outer 3 bands (where raised diamond centers stayed dry)
  let innerLim = NAPKIN_HALF - BORDER_INNER;
  let diagPitch = QUILT_PITCH * 1.41421356;
  let maxDiag = 2 * innerLim;

  brush.set("dry_fibre", "#faf6ee", 1.15);
  for (let c1 = -maxDiag + diagPitch * 0.5; c1 <= maxDiag - diagPitch * 0.5; c1 += diagPitch * 0.5) {
    for (let c2 = -maxDiag + diagPitch * 0.5; c2 <= maxDiag - diagPitch * 0.5; c2 += diagPitch * 0.5) {
      let u = 0.5 * (c1 + c2);
      let v = 0.5 * (c1 - c2);
      if (Math.abs(u) >= innerLim - 4 || Math.abs(v) >= innerLim - 4) continue;

      let wp = fromNapkin(u, v);
      let dx = wp.x - SPILL_ORIGIN_X;
      let dy = wp.y - SPILL_ORIGIN_Y;
      let dist = Math.hypot(dx, dy);
      let ang = atan2(dy, dx);
      if (ang < 0) ang += 360;

      let idx = Math.floor((ang / 360) * 180) % 180;
      let rOuter = bands[bands.length - 1].pts[idx].r;
      let rInnerDry = bands[bands.length - 4].pts[idx].r;

      // If this pillow center sits near the outer thinning edge, leave dry paper fibre streaks
      if (dist > rInnerDry - 6 && dist < rOuter + 4) {
        for (let k = -2; k <= 2; k++) {
          let p1 = fromNapkin(u - 4.5, v + k * 1.4);
          let p2 = fromNapkin(u + 4.5, v + k * 1.4);
          brush.line(p1.x, p1.y, p2.x, p2.y);
        }
      }
    }
  }

  // B. Hard Tide-Line Edges and Dry Cellulose Fibre Whiskers for every band
  for (let b = bands.length - 1; b >= 0; b--) {
    let band = bands[b];
    let pts = band.pts;
    let n = pts.length;
    let isOuter = b >= bands.length - 4;

    // 1. Primary hard tide-line edge (chromatographic solute pinning ring)
    let tideWeight = map(b, 0, bands.length - 1, 0.95, 0.62);
    brush.set("tide_edge", band.tide, tideWeight);

    let segPts = [];
    for (let i = 0; i <= n; i++) {
      let pt = pts[i % n];
      if (!pt.clamped) {
        let pr = 0.75 + 0.45 * noise(b * 3.1, i * 0.15);
        // Outer 2 bands thin and break slightly into dry fibres
        if (b >= bands.length - 2 && noise(b * 9, i * 0.25) < 0.22) {
          if (segPts.length >= 2) brush.spline(segPts, 0.28);
          segPts = [];
          continue;
        }
        segPts.push([pt.x, pt.y, pr]);
      } else {
        if (segPts.length >= 2) brush.spline(segPts, 0.28);
        segPts = [];
      }
    }
    if (segPts.length >= 2) brush.spline(segPts, 0.28);

    // 2. Secondary crisp inner micro-rim for the coffee-ring double-edge look
    brush.set("emboss_pencil", band.dry, tideWeight * 0.7);
    let innerSeg = [];
    for (let i = 0; i <= n; i++) {
      let pt = pts[i % n];
      if (!pt.clamped && (i % 2 === 0 || !isOuter)) {
        let inX = pt.x - 1.6 * cos(pt.ang);
        let inY = pt.y - 1.6 * sin(pt.ang);
        innerSeg.push([inX, inY, 0.7]);
      } else {
        if (innerSeg.length >= 2) brush.spline(innerSeg, 0.25);
        innerSeg = [];
      }
    }
    if (innerSeg.length >= 2) brush.spline(innerSeg, 0.25);

    // 3. Dry-fibre capillary whiskers wicking along cellulose grain & diamond grooves at outer bands
    if (b >= bands.length - 5) {
      let whiskerDensity = b >= bands.length - 2 ? 1 : 2;
      brush.set("dry_fibre", band.tide, map(b, bands.length - 5, bands.length - 1, 0.7, 1.05));

      for (let i = 0; i < n; i += whiskerDensity) {
        let pt = pts[i];
        if (pt.clamped) continue;

        // Whisker wicking outward along the radial + nearest diamond groove direction
        let wLen = random(4, b === bands.length - 1 ? 16 : 9);
        let grooveAngle = NAPKIN_ANGLE + (i % 2 === 0 ? 45 : -45);
        let blendAng = lerp(pt.ang, grooveAngle, 0.38);

        let ex = pt.x + wLen * cos(blendAng);
        let ey = pt.y + wLen * sin(blendAng);
        if (isInsideNapkin(ex, ey, 5)) {
          brush.line(pt.x, pt.y, ex, ey);
        }

        // Extra fine dry cellulose cross-fibres on outermost 2 bands
        if (b >= bands.length - 2 && random() < 0.65) {
          let fLen = random(3, 11);
          let fAng = NAPKIN_ANGLE + (random() < 0.5 ? 0 : 90) + random(-8, 8);
          let fx = pt.x + fLen * cos(fAng);
          let fy = pt.y + fLen * sin(fAng);
          if (isInsideNapkin(fx, fy, 5)) {
            brush.line(pt.x, pt.y, fx, fy);
          }
        }
      }
    }
  }
}

// ============================================================================
// 8. EMBOSSED QUILTING OVERLAY INSIDE THE COFFEE STAIN
// ============================================================================

// Determines which coffee band a point (x, y) lies inside, so pencil embossing matches the local stain tone
function getStainLevelAt(x, y, bands) {
  let dx = x - SPILL_ORIGIN_X;
  let dy = y - SPILL_ORIGIN_Y;
  let dist = Math.hypot(dx, dy);
  let ang = atan2(dy, dx);
  if (ang < 0) ang += 360;

  let idx = Math.floor((ang / 360) * 180) % 180;
  if (dist > bands[bands.length - 1].pts[idx].r) return -1; // Dry white paper

  for (let b = 0; b < bands.length; b++) {
    if (dist <= bands[b].pts[idx].r) return b;
  }
  return bands.length - 1;
}

function drawStainedQuiltingOverlay(bands) {
  // Tinted graphite/sepia colours corresponding to bands 0..10 (coffee pooling in embossed grooves)
  const grooveCols = [
    "#1c0601", "#2e0b02", "#421303", "#571d06",
    "#6e290a", "#823810", "#964818", "#a65b24",
    "#b57135", "#c2864b", "#cfa068"
  ];
  const ridgeCols = [
    "#59220c", "#732e12", "#8c3d19", "#a65023",
    "#bf6630", "#d17e42", "#de9658", "#e8ad72",
    "#f0c48e", "#f6d9ae", "#fbf0dc"
  ];

  let innerLim = NAPKIN_HALF - BORDER_INNER;
  let outerLim = NAPKIN_HALF - BORDER_OUTER;
  let diagPitch = QUILT_PITCH * 1.41421356;
  let maxDiag = 2 * innerLim;

  // 1. Re-inforce interior diagonal diamond channels where they pass through the coffee bands
  for (let c = -maxDiag + diagPitch * 0.5; c <= maxDiag - diagPitch * 0.5; c += diagPitch) {
    for (let dir of [1, -1]) {
      let uMin = Math.max(-innerLim, c - innerLim);
      let uMax = Math.min(innerLim, c + innerLim);
      if (uMax - uMin <= 6) continue;

      let v1 = dir === 1 ? c - uMin : uMin - c;
      let v2 = dir === 1 ? c - uMax : uMax - c;
      let distUV = Math.hypot(uMax - uMin, v2 - v1);
      let segs = Math.max(4, Math.floor(distUV / 14));
      let nx = -(v2 - v1) / distUV;
      let ny = (uMax - uMin) / distUV;

      for (let i = 0; i < segs; i++) {
        let tMid = (i + 0.5) / segs;
        let pMid = fromNapkin(lerp(uMin, uMax, tMid), lerp(v1, v2, tMid));
        let bLvl = getStainLevelAt(pMid.x, pMid.y, bands);
        if (bLvl < 0) continue; // Only reinforce inside stained region

        let tA = (i + 0.08) / segs;
        let tB = (i + 0.90) / segs;
        let uA = lerp(uMin, uMax, tA);
        let vA = lerp(v1, v2, tA);
        let uB = lerp(uMin, uMax, tB);
        let vB = lerp(v1, v2, tB);

        let pA = fromNapkin(uA, vA);
        let pB = fromNapkin(uB, vB);
        brush.set("emboss_pencil", grooveCols[bLvl], 0.88);
        brush.line(pA.x, pA.y, pB.x, pB.y);

        // Raised edge highlight of the embossed groove
        let pAh = fromNapkin(uA + nx * 1.4, vA + ny * 1.4);
        let pBh = fromNapkin(uB + nx * 1.4, vB + ny * 1.4);
        brush.set("emboss_pencil", ridgeCols[bLvl], 0.65);
        brush.line(pAh.x, pAh.y, pBh.x, pBh.y);
      }
    }
  }

  // 2. Re-inforce the quarter-fold creases through the stained bands
  let creaseSegs = 48;
  for (let i = 0; i < creaseSegs; i++) {
    let uA = map(i, 0, creaseSegs, -NAPKIN_HALF + 8, NAPKIN_HALF - 8);
    let uB = map(i + 0.85, 0, creaseSegs, -NAPKIN_HALF + 8, NAPKIN_HALF - 8);

    // Horizontal crease (v = 0)
    let pH1 = fromNapkin(uA, 0);
    let pH2 = fromNapkin(uB, 0);
    let bH = getStainLevelAt(pH1.x, pH1.y, bands);
    if (bH >= 0) {
      brush.set("emboss_pencil", grooveCols[bH], 0.82);
      brush.line(pH1.x, pH1.y, pH2.x, pH2.y);
      let pHh1 = fromNapkin(uA, 1.8);
      let pHh2 = fromNapkin(uB, 1.8);
      brush.set("emboss_pencil", ridgeCols[bH], 0.65);
      brush.line(pHh1.x, pHh1.y, pHh2.x, pHh2.y);
    }

    // Vertical crease (u = 0)
    let pV1 = fromNapkin(0, uA);
    let pV2 = fromNapkin(0, uB);
    let bV = getStainLevelAt(pV1.x, pV1.y, bands);
    if (bV >= 0) {
      brush.set("emboss_pencil", grooveCols[bV], 0.82);
      brush.line(pV1.x, pV1.y, pV2.x, pV2.y);
      let pVh1 = fromNapkin(-1.8, uA);
      let pVh2 = fromNapkin(-1.8, uB);
      brush.set("emboss_pencil", ridgeCols[bV], 0.65);
      brush.line(pVh1.x, pVh1.y, pVh2.x, pVh2.y);
    }
  }

  // 3. Re-inforce border flutes where the stain reaches the upper-left napkin margin
  let fStart = -innerLim + 4;
  let fEnd = innerLim - 4;
  for (let pos = fStart; pos <= fEnd; pos += 7.5) {
    // Top border (v < 0) and Left border (u < 0)
    let pTop1 = fromNapkin(pos, -innerLim - 9);
    let pTop2 = fromNapkin(pos, -outerLim + 9);
    let bTop = getStainLevelAt(pTop1.x, pTop1.y, bands);
    if (bTop >= 0) {
      brush.set("emboss_pencil", grooveCols[bTop], 0.8);
      brush.line(pTop1.x, pTop1.y, pTop2.x, pTop2.y);
    }

    let pLeft1 = fromNapkin(-innerLim - 9, pos);
    let pLeft2 = fromNapkin(-outerLim + 9, pos);
    let bLeft = getStainLevelAt(pLeft1.x, pLeft1.y, bands);
    if (bLeft >= 0) {
      brush.set("emboss_pencil", grooveCols[bLeft], 0.8);
      brush.line(pLeft1.x, pLeft1.y, pLeft2.x, pLeft2.y);
    }
  }
}

// ============================================================================
// 9. SATELLITE DROPS (WICKING SPOTS ON NAPKIN & GLOSSY BEADS ON TABLE)
// ============================================================================

function drawSatelliteDrops() {
  // A. Miniature concentric wicking spots on the dry napkin
  const napkinSpots = [
    { x: 875, y: 545, r: 24 },
    { x: 920, y: 615, r: 14 },
    { x: 760, y: 895, r: 19 },
    { x: 830, y: 865, r: 11 },
    { x: 645, y: 345, r: 15 }
  ];

  for (let sp of napkinSpots) {
    let subRings = [
      { scale: 1.0,  wash: "#f2d6b0", alpha: 60, tide: "#d4a46a" },
      { scale: 0.68, wash: "#cf7d36", alpha: 78, tide: "#994c14" },
      { scale: 0.36, wash: "#6b2408", alpha: 95, tide: "#3d1002" }
    ];

    for (let sr of subRings) {
      let rad = sp.r * sr.scale;
      let pts = [];
      let sPts = [];
      for (let a = 0; a < 360; a += 18) {
        let rr = rad * (0.88 + 0.24 * noise(sp.x + cos(a), sp.y + sin(a)));
        let px = sp.x + rr * cos(a);
        let py = sp.y + rr * sin(a);
        pts.push({ x: px, y: py });
        sPts.push([px, py, 0.8]);
      }
      sPts.push(sPts[0]);

      brush.noStroke();
      brush.fillBleed(0.03, "in");
      brush.fillTexture(0.6, 0.85);
      brush.fill(sr.wash, sr.alpha);
      brush.beginShape(0.25);
      for (let p of pts) brush.vertex(p.x, p.y);
      brush.endShape(true);
      brush.noFill();

      brush.set("tide_edge", sr.tide, 0.55);
      brush.spline(sPts, 0.3);
    }
  }

  // B. Glossy unabsorbed coffee droplets on the varnished ash table
  const tableDrops = [
    { x: 185, y: 525, r: 13 },
    { x: 215, y: 560, r: 7.5 },
    { x: 435, y: 215, r: 10 },
    { x: 465, y: 232, r: 5.5 }
  ];

  for (let td of tableDrops) {
    // Contact shadow
    brush.noStroke();
    brush.wash("#8f785d", 140);
    brush.circle(td.x + 1.5, td.y + 2, td.r, 0.08);

    // Mahogany base & espresso core
    brush.wash("#4a1806", 235);
    brush.circle(td.x, td.y, td.r, 0.08);
    brush.wash("#140501", 245);
    brush.circle(td.x - 0.5, td.y - 0.5, td.r * 0.78, 0.06);
    brush.noWash();

    // Crisp white specular bead highlight
    brush.set("gloss_pen", "#fffef9", 0.55);
    brush.arc(td.x, td.y, td.r * 0.65, 200, 265);
  }
}

// ============================================================================
// 10. PHOTOREAL GLOSSY POOLED COFFEE PUDDLE AT THE SOURCE
// ============================================================================

function getPuddlePolygon(inset = 0) {
  // Smooth, high-surface-tension liquid puddle pouring from the cup mouth (355, 405) onto the napkin (545, 530)
  const baseCtrl = [
    [332, 385], [368, 368], [412, 376], [452, 402],
    [498, 412], [542, 438], [568, 476], [562, 518],
    [532, 546], [488, 552], [448, 534], [418, 542],
    [382, 526], [362, 492], [348, 456], [326, 422]
  ];

  // Center of puddle mass for inset scaling
  let cx = 452, cy = 466;
  let pts = [];
  for (let p of baseCtrl) {
    let dx = p[0] - cx;
    let dy = p[1] - cy;
    let len = Math.hypot(dx, dy);
    let scale = Math.max(0.1, (len - inset) / len);
    pts.push({
      x: cx + dx * scale,
      y: cy + dy * scale
    });
  }
  return pts;
}

function drawGlossyPuddle() {
  let outerPuddle = getPuddlePolygon(0);
  let mahoganyRim = getPuddlePolygon(3.2);
  let espressoCore = getPuddlePolygon(8.5);
  let deepCore = getPuddlePolygon(19.0);

  brush.noStroke();

  // 1. Subtle wet meniscus shadow on the table/napkin boundary
  brush.wash("#301105", 165);
  brush.beginShape(0.38);
  for (let p of outerPuddle) brush.vertex(p.x + 2, p.y + 2.5);
  brush.endShape(true);

  // 2. Translucent mahogany-amber meniscus edge
  brush.wash("#591f08", 235);
  brush.beginShape(0.38);
  for (let p of outerPuddle) brush.vertex(p.x, p.y);
  brush.endShape(true);

  // 3. Rich dark roast layer
  brush.wash("#2b0c03", 245);
  brush.beginShape(0.38);
  for (let p of mahoganyRim) brush.vertex(p.x, p.y);
  brush.endShape(true);

  // 4. Mirror-like espresso-black liquid pool
  brush.wash("#130501", 252);
  brush.beginShape(0.38);
  for (let p of espressoCore) brush.vertex(p.x, p.y);
  brush.endShape(true);

  // 5. Pitch-black deepest center
  brush.wash("#080200", 255);
  brush.beginShape(0.38);
  for (let p of deepCore) brush.vertex(p.x, p.y);
  brush.endShape(true);
  brush.noWash();

  // 6. Warm internal liquid glow along the lower-right meniscus
  brush.set("gloss_pen", "#8c3811", 0.9);
  brush.spline([
    [548, 452, 0.4], [562, 482, 0.9], [552, 518, 1.0],
    [522, 542, 0.9], [482, 546, 0.5]
  ], 0.35);

  brush.set("gloss_pen", "#b04c19", 0.5);
  brush.spline([
    [556, 468, 0.4], [556, 508, 0.9], [528, 538, 0.5]
  ], 0.35);

  // 7. Golden-hazelnut crema micro-bubbles clustered near the cup outflow & meniscus bays
  const cremaClusters = [
    { cx: 382, cy: 418, count: 34, spread: 24 },
    { cx: 422, cy: 405, count: 22, spread: 18 },
    { cx: 446, cy: 522, count: 18, spread: 15 },
    { cx: 374, cy: 486, count: 16, spread: 14 }
  ];

  // Soft golden crema base rafts
  brush.noStroke();
  for (let cl of cremaClusters) {
    brush.fillBleed(0.05, "out");
    brush.fillTexture(0.5, 0.5);
    brush.fill("#9e5822", 130);
    brush.circle(cl.cx, cl.cy, cl.spread * 0.65, 0.25);
  }
  brush.noFill();

  // Individual crema foam bubbles
  for (let cl of cremaClusters) {
    for (let i = 0; i < cl.count; i++) {
      let ang = random(360);
      let rad = Math.pow(random(), 0.7) * cl.spread;
      let bx = cl.cx + rad * cos(ang);
      let by = cl.cy + rad * sin(ang);
      let br = random(1.2, 4.2);

      let bCol = i % 3 === 0 ? "#e8b878" : (i % 2 === 0 ? "#c98542" : "#8f4916");
      brush.set("emboss_pencil", bCol, 0.65);
      brush.circle(bx, by, br, 0.1);

      if (br > 2.4) {
        // Tiny dark bubble center + white pinpoint highlight
        brush.set("emboss_pencil", "#2b0d03", 0.5);
        brush.circle(bx, by, br * 0.45, 0.05);
        brush.set("emboss_pencil", "#fffdf7", 0.55);
        brush.line(bx - br * 0.3, by - br * 0.3, bx - br * 0.1, by - br * 0.35);
      }
    }
  }

  // 8. Razor-sharp overhead window & meniscus specular reflections on the black coffee pool
  // Skylight reflection pane 1
  brush.noStroke();
  brush.wash("#fffdf8", 230);
  brush.beginShape(0.2);
  brush.vertex(448, 434);
  brush.vertex(492, 446);
  brush.vertex(482, 474);
  brush.vertex(436, 460);
  brush.endShape(true);

  // Skylight reflection pane 2 (separated by thin dark window mullion)
  brush.wash("#fffdf8", 215);
  brush.beginShape(0.2);
  brush.vertex(498, 449);
  brush.vertex(528, 462);
  brush.vertex(518, 488);
  brush.vertex(488, 476);
  brush.endShape(true);
  brush.noWash();

  // Sleek curved meniscus specular ribbons along the upper-right & lower lobes
  brush.set("gloss_pen", "#ffffff", 1.05);
  brush.spline([
    [402, 384, 0.3], [438, 404, 0.9], [488, 418, 1.1],
    [532, 442, 0.95], [554, 474, 0.4]
  ], 0.35);

  brush.set("gloss_pen", "#fffaf0", 0.65);
  brush.spline([
    [412, 390, 0.2], [446, 410, 0.7], [492, 424, 0.7], [528, 446, 0.3]
  ], 0.35);

  // Secondary meniscus highlight along the lower-left lobe
  brush.set("gloss_pen", "#ffffff", 0.78);
  brush.spline([
    [358, 464, 0.3], [372, 506, 0.9], [404, 528, 0.7], [434, 526, 0.2]
  ], 0.35);

  // Crisp highlight arc on the lower-right bulge
  brush.set("gloss_pen", "#ffffff", 0.85);
  brush.spline([
    [548, 496, 0.3], [534, 526, 0.95], [496, 538, 0.8], [468, 532, 0.2]
  ], 0.35);
}

// ============================================================================
// 11. PHOTOREAL TIPPED PORCELAIN CAFÉ CUP AT THE SOURCE
// ============================================================================

function drawTippedCup() {
  // Cup is centered around (265, 342), lying on its side with open mouth tilted toward (352, 398)
  const cupCX = 265;
  const cupCY = 342;
  const cupAng = 33; // degrees
  const cA = cos(cupAng);
  const sA = sin(cupAng);

  function toWorld(lx, ly) {
    return {
      x: cupCX + lx * cA - ly * sA,
      y: cupCY + lx * sA + ly * cA
    };
  }

  // 1. Multi-layered Cast Shadow of Cup & Handle on Table and Napkin Corner
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.35, 0.2);

  const shadowLayers = [
    { rx: 128, ry: 96, ox: 18, oy: 28, col: "#b59d82", alpha: 80 },
    { rx: 112, ry: 82, ox: 12, oy: 20, col: "#8c7358", alpha: 105 },
    { rx: 95,  ry: 66, ox: 6,  oy: 12, col: "#54402d", alpha: 135 },
    { rx: 82,  ry: 48, ox: 2,  oy: 6,  col: "#291c11", alpha: 175 }
  ];

  for (let sl of shadowLayers) {
    brush.fill(sl.col, sl.alpha);
    brush.beginShape(0.3);
    for (let a = 0; a < 360; a += 20) {
      let p = toWorld(sl.ox + sl.rx * cos(a), sl.oy + sl.ry * sin(a));
      brush.vertex(p.x, p.y);
    }
    brush.endShape(true);
  }
  brush.noFill();

  // 2. Porcelain Handle (projecting from the upper-left flank of the cup)
  // Outer handle loop & inner hole
  let handleOuter = [
    [-48, -58], [-64, -96], [-42, -126], [-4, -128], [26, -102], [22, -72]
  ];
  let handleInner = [
    [-34, -66], [-45, -92], [-30, -108], [-6, -110], [10, -92], [8, -72]
  ];

  // Handle cast shadow on ash wood table
  brush.noStroke();
  brush.wash("#8c755b", 125);
  brush.beginShape(0.35);
  for (let pt of handleOuter) {
    let w = toWorld(pt[0] + 6, pt[1] + 11);
    brush.vertex(w.x, w.y);
  }
  brush.endShape(true);

  // Handle porcelain body
  brush.wash("#ebe3d5", 250);
  brush.beginShape(0.35);
  for (let pt of handleOuter) {
    let w = toWorld(pt[0], pt[1]);
    brush.vertex(w.x, w.y);
  }
  brush.endShape(true);

  // Cut out inner handle hole with ash table tone + shadow
  brush.wash("#cbb89e", 248);
  brush.beginShape(0.35);
  for (let pt of handleInner) {
    let w = toWorld(pt[0], pt[1]);
    brush.vertex(w.x, w.y);
  }
  brush.endShape(true);
  brush.noWash();

  // Handle shading & glossy porcelain ridge highlight
  brush.set("2H", "#9e9180", 0.55);
  let hOutPts = handleOuter.map(pt => {
    let w = toWorld(pt[0], pt[1]);
    return [w.x, w.y, 0.8];
  });
  brush.spline(hOutPts, 0.35);

  let hInPts = handleInner.map(pt => {
    let w = toWorld(pt[0], pt[1]);
    return [w.x, w.y, 0.8];
  });
  brush.spline(hInPts, 0.35);

  brush.set("gloss_pen", "#ffffff", 0.85);
  let hHiPts = [[-52, -88], [-36, -118], [-4, -120], [18, -98]].map(pt => {
    let w = toWorld(pt[0], pt[1]);
    return [w.x, w.y, 0.9];
  });
  brush.spline(hHiPts, 0.35);

  // 3. Unglazed Porcelain Foot Ring at the Rear of the Cup (lx around -92)
  brush.noStroke();
  brush.wash("#d6cbb9", 252);
  brush.beginShape(0.25);
  let footPts = [
    [-82, -48], [-98, -42], [-103, -20], [-103, 20], [-98, 42], [-82, 48]
  ];
  for (let pt of footPts) {
    let w = toWorld(pt[0], pt[1]);
    brush.vertex(w.x, w.y);
  }
  brush.endShape(true);
  brush.noWash();

  brush.set("HB", "#8c7f6d", 0.48);
  let fStroke = footPts.map(pt => {
    let w = toWorld(pt[0], pt[1]);
    return [w.x, w.y, 0.8];
  });
  brush.spline(fStroke, 0.25);

  // 4. Main Ceramic Cup Body (Truncated Curved Bowl from lx = -86 to lx = +82)
  let cupOutline = [
    [-84, -52], [-50, -68], [0, -82], [48, -90], [82, -92],
    [82, 92], [48, 90], [0, 82], [-50, 68], [-84, 52]
  ];

  // Base warm ivory porcelain body
  brush.noStroke();
  brush.wash("#f2ece1", 254);
  brush.beginShape(0.28);
  for (let pt of cupOutline) {
    let w = toWorld(pt[0], pt[1]);
    brush.vertex(w.x, w.y);
  }
  brush.endShape(true);

  // Cylindrical shading bands across the cup belly (ly from -90 lit top to +90 shaded bottom)
  const bodyBands = [
    { y1: -88, y2: -52, col: "#fbf8f2", alpha: 210 }, // Sunlit upper flank
    { y1: -20, y2: 28,  col: "#e3d9c8", alpha: 180 }, // Mid-tone cylinder turn
    { y1: 22,  y2: 65,  col: "#c9bba6", alpha: 210 }, // Lower shaded belly
    { y1: 52,  y2: 90,  col: "#9e8d77", alpha: 220 }, // Deep shadow near table
    { y1: 72,  y2: 91,  col: "#6e5a44", alpha: 195 }  // Core occlusion & coffee reflection
  ];

  for (let bb of bodyBands) {
    brush.wash(bb.col, bb.alpha);
    brush.beginShape(0.2);
    let rL1 = lerp(52, 92, 0.15) * (bb.y1 / 92);
    let rR1 = 92 * (bb.y1 / 92);
    let rR2 = 92 * (bb.y2 / 92);
    let rL2 = lerp(52, 92, 0.15) * (bb.y2 / 92);
    let quad = [
      toWorld(-82, rL1),
      toWorld(80, rR1),
      toWorld(80, rR2),
      toWorld(-82, rL2)
    ];
    for (let q of quad) brush.vertex(q.x, q.y);
    brush.endShape(true);
  }
  brush.noWash();

  // Fine cylindrical form hatching on the shaded lower half of the cup
  for (let lx = -78; lx <= 74; lx += 5.5) {
    let t = (lx + 84) / 166;
    let halfH = lerp(52, 92, Math.pow(t, 0.78));
    let pTop = toWorld(lx, halfH * 0.15);
    let pMid = toWorld(lx + 4, halfH * 0.58);
    let pBot = toWorld(lx - 2, halfH * 0.96);

    brush.set("2H", "#8f7e68", 0.34);
    brush.spline([
      [pTop.x, pTop.y, 0.3],
      [pMid.x, pMid.y, 0.85],
      [pBot.x, pBot.y, 0.95]
    ], 0.3);
  }

  // Long glossy specular highlight ribbon along the sunlit upper flank of the porcelain body
  brush.noStroke();
  brush.wash("#ffffff", 235);
  brush.beginShape(0.2);
  for (let pt of [[-74, -28], [76, -48], [76, -32], [-74, -18]]) {
    let w = toWorld(pt[0], pt[1]);
    brush.vertex(w.x, w.y);
  }
  brush.endShape(true);
  brush.noWash();

  brush.set("gloss_pen", "#ffffff", 1.15);
  let specLine = [[-76, -23], [-20, -31], [35, -38], [78, -42]].map(pt => {
    let w = toWorld(pt[0], pt[1]);
    return [w.x, w.y, 1.0];
  });
  brush.spline(specLine, 0.25);

  // Crisp outer contour of cup body
  brush.set("HB", "#7a6b58", 0.48);
  let topContour = [[-84, -52], [-45, -69], [5, -83], [50, -90], [82, -92]].map(pt => {
    let w = toWorld(pt[0], pt[1]);
    return [w.x, w.y, 0.85];
  });
  brush.spline(topContour, 0.3);

  brush.set("HB", "#3d2d1e", 0.65);
  let botContour = [[-84, 52], [-45, 69], [5, 83], [50, 90], [82, 92]].map(pt => {
    let w = toWorld(pt[0], pt[1]);
    return [w.x, w.y, 0.95];
  });
  brush.spline(botContour, 0.3);

  // 5. Foreshortened Open Mouth Ellipse & Glazed Interior at lx = +82
  const mouthRX = 34;
  const mouthRY = 92;
  const rimThick = 8.5;

  // A. Outer porcelain lip ellipse
  brush.noStroke();
  brush.wash("#f7f2e8", 255);
  brush.beginShape(0.25);
  for (let a = 0; a < 360; a += 12) {
    let w = toWorld(82 + mouthRX * cos(a), mouthRY * sin(a));
    brush.vertex(w.x, w.y);
  }
  brush.endShape(true);

  // B. Concave Interior Wall of the Cup
  let inRX = mouthRX - rimThick * 0.75;
  let inRY = mouthRY - rimThick;

  brush.wash("#cbbca6", 252);
  brush.beginShape(0.25);
  for (let a = 0; a < 360; a += 12) {
    let w = toWorld(81 + inRX * cos(a), inRY * sin(a));
    brush.vertex(w.x, w.y);
  }
  brush.endShape(true);

  // Deeper interior concavity shadow (upper/inner wall)
  brush.wash("#9e8c74", 215);
  brush.beginShape(0.25);
  for (let a = 110; a <= 290; a += 15) {
    let w = toWorld(80 + inRX * 0.92 * cos(a), inRY * 0.92 * sin(a));
    brush.vertex(w.x, w.y);
  }
  for (let a = 290; a >= 110; a -= 15) {
    let w = toWorld(72 + inRX * 0.3 * cos(a), inRY * 0.55 * sin(a));
    brush.vertex(w.x, w.y);
  }
  brush.endShape(true);
  brush.noWash();

  // Dried amber/sienna crema stains inside the upper ceramic wall
