  brush.endShape(true);
  brush.noWash();

  // D. Porcelain Rim Highlights & Crisp Elliptical Contours
  brush.set("HB", "#786956", 0.5);
  let outerRimCurve = [];
  for (let a = 0; a <= 360; a += 10) {
    let w = toWorld(82 + mouthRX * cos(a), mouthRY * sin(a));
    outerRimCurve.push([w.x, w.y, 0.8]);
  }
  brush.spline(outerRimCurve, 0.3);

  brush.set("HB", "#877661", 0.45);
  let innerRimCurve = [];
  for (let a = 95; a <= 315; a += 10) {
    let w = toWorld(81 + inRX * cos(a), inRY * sin(a));
    innerRimCurve.push([w.x, w.y, 0.8]);
  }
  brush.spline(innerRimCurve, 0.3);

  // Bright specular glaze arc along the upper porcelain lip
  brush.set("gloss_pen", "#ffffff", 1.0);
  let rimGlaze = [];
  for (let a = 195; a <= 325; a += 12) {
    let w = toWorld(82 + (mouthRX - 3.5) * cos(a), (mouthRY - 4) * sin(a));
    rimGlaze.push([w.x, w.y, 0.95]);
