// =============================================================================
// GEOMETRY & LIGHTING HELPERS
// =============================================================================

function getLightVector(x, y) {
  let dx = x - LIGHT_X;
  let dy = y - LIGHT_Y;
  let d = sqrt(dx * dx + dy * dy) || 1;
  return { ux: dx / d, uy: dy / d, dist: d, angle: atan2(dy, dx) };
}

function drawBlobWash(cx, cy, rx, ry, rotDeg, col, alpha, bleed, irr = 0.12, steps = 28) {
  brush.noStroke();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(0.55, 0.35);
  let cr = cos(rotDeg);
  let sr = sin(rotDeg);
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let n = noise(cx * 0.01 + cos(a) * 1.4, cy * 0.01 + sin(a) * 1.4);
    let rScale = 1 + (n - 0.5) * 2 * irr;
    let lx = cos(a) * rx * rScale;
    let ly = sin(a) * ry * rScale;
    let px = cx + lx * cr - ly * sr;
    let py = cy + lx * sr + ly * cr;
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noFill();
}

function drawCastShadow(cx, cy, rx, ry, rotDeg, heightScale = 18, alpha = 68) {
  let lv = getLightVector(cx, cy);
  let shift = map(constrain(lv.dist, 50, 800), 50, 800, 0.4, 1.25) * heightScale;
  let sx = cx + lv.ux * shift;
  let sy = cy + lv.uy * shift;

  // Soft outer penumbra
  drawBlobWash(sx + lv.ux * 5, sy + lv.uy * 5, rx * 1.06, ry * 1.06, rotDeg, PAL.sepiaMid, alpha * 0.55, 0.28, 0.06, 24);
  // Crisp inner umbra
  drawBlobWash(sx, sy, rx * 0.96, ry * 0.96, rotDeg, PAL.ironGallDark, alpha, 0.12, 0.05, 24);

  // Fine hatching in the umbra for hyperreal graphic depth
  brush.set("2B", PAL.ironGallDark, 0.28);
  let cr = cos(rotDeg);
  let sr = sin(rotDeg);
  let count = floor((rx + ry) * 0.22);
  for (let i = 0; i < count; i++) {
    let a = random(360);
    let rad = sqrt(random()) * 0.9;
    let lx = cos(a) * rx * rad;
    let ly = sin(a) * ry * rad;
    let px = sx + lx * cr - ly * sr;
    let py = sy + lx * sr + ly * cr;
    brush.line(px - lv.ux * 6, py - lv.uy * 6, px + lv.ux * 8, py + lv.uy * 8);
  }
}

