function drawSepiaCalligraphy(x, y, w, words) {
  brush.set("rotring", PAL.sepiaMid, 0.28);
  let cx = x;
  let step = w / words;
  for (let i = 0; i < words; i++) {
    let pts = [];
    let peaks = floor(random(4, 8));
    for (let p = 0; p < peaks; p++) {
      pts.push([cx + (p / peaks) * (step - 5), y + (p % 2 === 0 ? -3.5 : 3.5) + random(-1.5, 1.5)]);
    }
    brush.spline(pts, 0.55);
    if (random() < 0.4) {
      brush.line(cx + 3, y - 7, cx + 6, y + 6); // ascender/descender
    }
    cx += step;
  }
}

