  drawBlobWash(CX + 165, CY + 155, 250, 230, 40, PAL.parchmentUmber, 55, 0.42, 0.14, 26);

  // Bright warm pool on the upper-left tabletop near the candle
  drawBlobWash(LIGHT_X + 35, LIGHT_Y + 35, 230, 210, -25, PAL.vellumLight, 95, 0.35, 0.1, 26);

  // Subtle concentric lathe/wood-grain and parchment scraping lines inside the table
  brush.set("2H", PAL.sepiaFaint, 0.22);
  for (let i = 0; i < 95; i++) {
    let y = CY - R_INNER + 25 + (i / 95) * (R_INNER * 2 - 50);
    let dy = y - CY;
    let halfChord = sqrt(max(0, R_INNER * R_INNER - dy * dy)) - 14;
    if (halfChord > 40) {
      let x1 = CX - halfChord + random(0, halfChord * 0.6);
      let x2 = x1 + random(60, halfChord * 0.85);
      x2 = min(x2, CX + halfChord);
      brush.line(x1, y + random(-2, 2), x2, y + random(-2, 2));
    }
  }
}

// =============================================================================
// 4. THE 'T' DIVISION PART I: WOVEN LINEN RUNNER (HORIZONTAL BAR OF THE T)
// =============================================================================

function drawLinenRunner() {
  let yTop = 458;
  let yBot = 554;
  let yMid = (yTop + yBot) / 2;

  // Compute chord endpoints where the runner meets the O-ring
  let xLeft = CX - sqrt(R_INNER * R_INNER - pow(yMid - CY, 2)) - 4;
  let xRight = CX + sqrt(R_INNER * R_INNER - pow(yMid - CY, 2)) + 4;

  // Rumpled pinch points along the top and bottom edges of the runner
  let topPts = [];
  let botPts = [];
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(xLeft, xRight, t);
    // Natural cloth pinch near the center T-junction and under the left/right napkins
    let pinchTop = sin(t * 180) * 6 + sin(t * 720) * 3.5 + (noise(t * 6, 1.2) - 0.5) * 10;
    let pinchBot = -sin(t * 180) * 5 + cos(t * 540) * 4 + (noise(t * 6, 4.8) - 0.5) * 10;
    if (abs(x - 600) < 90) {
      pinchTop += 7 * exp(-pow((x - 600) / 55, 2));
      pinchBot -= 5 * exp(-pow((x - 600) / 55, 2));
    }
    topPts.push([x, yTop + pinchTop]);
    botPts.push([x, yBot + pinchBot]);
  }

  // Cast shadow of the linen runner on the tabletop (away from light at upper-left)
  brush.noStroke();
  brush.fill(PAL.sepiaMid, 62);
  brush.fillBleed(0.14, "out");
  brush.beginShape(0.3);
  for (let p of topPts) brush.vertex(p[0] + 4, p[1] + 7);
  for (let i = botPts.length - 1; i >= 0; i--) brush.vertex(botPts[i][0] + 5, botPts[i][1] + 9);
  brush.endShape(true);
  brush.noFill();

  // Main linen body fill
  brush.noStroke();
  brush.fill(PAL.vellumLight, 175);
  brush.fillBleed(0.06, "out");
  brush.fillTexture(0.45, 0.25);
  brush.beginShape(0.3);
  for (let p of topPts) brush.vertex(p[0], p[1]);
  for (let i = botPts.length - 1; i >= 0; i--) brush.vertex(botPts[i][0], botPts[i][1]);
  brush.endShape(true);
  brush.noFill();

  // Draped fold valleys across the runner (3D cloth ridges catching candlelight)
  let foldXs = [235, 310, 445, 535, 605, 690, 775, 885, 965];
  for (let fx of foldXs) {
    let tilt = random(-18, 18);
    // Shadow side of fold (right side, away from light)
    drawBlobWash(fx + 8, yMid, 9, 44, tilt, PAL.vellumDark, 82, 0.15, 0.08, 18);
    brush.set("2B", PAL.sepiaMid, 0.3);
    for (let h = -38; h <= 38; h += 5) {
      brush.line(fx + 3 + h * sin(tilt), yMid + h * cos(tilt), fx + 13 + h * sin(tilt), yMid + h * cos(tilt) + 2);
    }
    // Highlight ridge of fold (left side, facing candle)
    brush.set("quill", PAL.waxLight, 0.85);
    brush.spline([
      [fx - 4 - 38 * sin(tilt), yTop + 6],
      [fx - 2, yMid],
      [fx - 4 + 38 * sin(tilt), yBot - 6]
    ], 0.45);
  }

  // Fine linen warp & weft weave texture across the runner
  brush.set("2H", PAL.vellumDark, 0.22);
  for (let wy = yTop + 6; wy <= yBot - 6; wy += 4.5) {
