function drawSpilledWineT() {
  // 1) Horizontal Wine Bleed along the Linen Runner crease (reinforcing the top bar of the T)
  let hPoints = [
    { x: 355, y: 508, rx: 32, ry: 12 },
    { x: 415, y: 514, rx: 46, ry: 16 },
    { x: 485, y: 510, rx: 54, ry: 19 },
    { x: 555, y: 515, rx: 62, ry: 24 },
    { x: 610, y: 518, rx: 68, ry: 28 },
    { x: 675, y: 514, rx: 52, ry: 20 },
    { x: 735, y: 509, rx: 38, ry: 14 },
    { x: 785, y: 512, rx: 24, ry: 10 }
  ];

  // 2) Vertical Wine River pouring from the T-nexus (600, 515) down to the Southern Ocean (600, 1038)
  let vSpine = [];
  let vSteps = 22;
  for (let i = 0; i <= vSteps; i++) {
    let t = i / vSteps;
    let y = lerp(515, 1036, t);
    // Natural meandering river channel centered on x = 600
    let x = 600 + sin(t * 340) * 16 - sin(t * 180) * 8 + (noise(t * 4, 9.1) - 0.5) * 14;
    // Wider at the goblet mouth (top) and delta estuary (bottom), narrower mid-stream
    let w = 26 * (1 - t * 0.45) + 18 * exp(-pow((t - 0.12) / 0.12, 2)) + 24 * exp(-pow((t - 0.95) / 0.1, 2));
    w += (noise(t * 9, 2.3) - 0.5) * 14;
    vSpine.push({ x, y, w: max(11, w) });
  }

  // PASS A: Capillary rose-oxblood bleed halo into cloth and parchment
  for (let hp of hPoints) {
    drawBlobWash(hp.x, hp.y, hp.rx * 1.35, hp.ry * 1.45, random(-8, 8), PAL.oxbloodWash, 62, 0.38, 0.22, 20);
  }
  for (let i = 0; i < vSpine.length; i += 2) {
    let vp = vSpine[i];
    drawBlobWash(vp.x, vp.y, vp.w * 1.45, vp.w * 1.35, random(360), PAL.oxbloodWash, 58, 0.35, 0.22, 20);
  }

  // PASS B: Deep translucent oxblood liquid body
  for (let hp of hPoints) {
    drawBlobWash(hp.x, hp.y, hp.rx, hp.ry, random(-6, 6), PAL.oxbloodMid, 135, 0.14, 0.18, 22);
  }

  // Construct unified polygon for the vertical oxblood river stream
  let leftBank = [];
  let rightBank = [];
  for (let i = 0; i < vSpine.length; i++) {
    let vp = vSpine[i];
    let lobeL = vp.w * (0.85 + 0.35 * sin(i * 47));
    let lobeR = vp.w * (0.85 + 0.35 * cos(i * 53));
    leftBank.push([vp.x - lobeL, vp.y]);
    rightBank.push([vp.x + lobeR, vp.y]);
  }

  brush.noStroke();
  brush.fill(PAL.oxbloodMid, 165);
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.45, 0.55);
  brush.beginShape(0.4);
  for (let p of leftBank) brush.vertex(p[0], p[1]);
  for (let i = rightBank.length - 1; i >= 0; i--) brush.vertex(rightBank[i][0], rightBank[i][1]);
  brush.endShape(true);
  brush.noFill();

  // PASS C: Darker coagulated oxblood core & pooling delta lobes
  for (let i = 0; i < vSpine.length; i += 3) {
    let vp = vSpine[i];
    drawBlobWash(vp.x + 2, vp.y + 2, vp.w * 0.68, vp.w * 0.85, random(-15, 15), PAL.oxbloodDark, 145, 0.06, 0.16, 18);
  }
  drawBlobWash(605, 522, 48, 22, -8, PAL.oxbloodCoag, 155, 0.06, 0.18, 22);

  // PASS D: Crisp dark surface-tension meniscus along both banks of the river
  brush.set("rotring", PAL.oxbloodCoag, 0.58);
  brush.spline(leftBank, 0.42);
  brush.spline(rightBank, 0.42);

  // Tributary rivulets & splatters branching off the main T-river
  let rivulets = [
    [[585, 620], [552, 648], [534, 672], [528, 690]],
    [[618, 685], [648, 712], [662, 742]],
    [[588, 795], [558, 825], [545, 858]],
    [[612, 890], [642, 928], [655, 965]],
    [[592, 985], [562, 1018], [542, 1038]],
    [[608, 990], [638, 1020], [658, 1038]]
  ];
  for (let riv of rivulets) {
    brush.set("cpencil", PAL.oxbloodMid, 1.3);
    brush.spline(riv, 0.45);
    brush.set("rotring", PAL.oxbloodCoag, 0.55);
    brush.spline(riv, 0.45);
    let endPt = riv[riv.length - 1];
    drawBlobWash(endPt[0], endPt[1], 7, 5, random(360), PAL.oxbloodDark, 160, 0.05, 0.15, 14);
  }

  // PASS E: Hyperreal Specular Liquid Glints (Bright vellum-white reflections along the candle-facing left meniscus!)
  brush.set("quill", PAL.waxLight, 0.95);
  for (let i = 1; i < leftBank.length - 2; i += 2) {
    let p1 = leftBank[i];
    let p2 = leftBank[i + 1];
    let midX = (p1[0] + p2[0]) * 0.5 + 3.8;
    let midY = (p1[1] + p2[1]) * 0.5;
    brush.spline([
      [p1[0] + 3.5, p1[1] + 2],
      [midX, midY],
      [p2[0] + 3.5, p2[1] - 2]
    ], 0.45);
  }
  // Specular highlights along the horizontal wine pool on the runner
  for (let hp of hPoints) {
    brush.set("quill", PAL.waxLight, 0.85);
    brush.arc(hp.x - 3, hp.y - 2, hp.ry * 0.65, 195, 295);
  }

  // Scattered wine droplets around the T-junction
  for (let d = 0; d < 28; d++) {
    let dx = 600 + random(-140, 140);
    let dy = 520 + random(-45, 480) * pow(random(), 1.4);
    let r = random(1.5, 5.5);
    drawBlobWash(dx, dy, r, r * 0.85, random(360), PAL.oxbloodDark, 150, 0.05, 0.12, 12);
    brush.set("quill", PAL.waxLight, 0.55);
    brush.point(dx - r * 0.3, dy - r * 0.3);
  }
}

// =============================================================================
// 7. THE ENCIRCLING 'O' OCEAN OF IRON-GALL PEN
// =============================================================================

function drawIronGallOceanRing() {
  // Subtle sepia-and-verdigris wash inside the annular ocean band (R_INNER to R_OUTER)
  for (let a = 0; a < 360; a += 15) {
    let rm = (R_INNER + R_OUTER) * 0.5;
    let wx = CX + cos(a) * rm;
    let wy = CY + sin(a) * rm;
    let col = (a > 30 && a < 160) ? PAL.parchmentUmber : PAL.vellumDark;
    drawBlobWash(wx, wy, 36, 24, a + 90, col, 48, 0.25, 0.15, 16);
    if (a % 45 === 0) {
      drawBlobWash(wx, wy, 28, 18, a + 90, PAL.verdigrisLight, 26, 0.3, 0.15, 14);
    }
  }

  // Structural concentric rings of the O-map frame in iron-gall pen
  let rings = [
    { r: R_INNER - 4, w: 0.45, c: PAL.ironGall },
    { r: R_INNER, w: 0.85, c: PAL.ironGallDark },
    { r: R_INNER + 5, w: 0.38, c: PAL.ironGall },
    { r: R_OUTER - 6, w: 0.38, c: PAL.ironGall },
    { r: R_OUTER, w: 0.9, c: PAL.ironGallDark },
    { r: R_OUTER + 6, w: 0.42, c: PAL.ironGall }
  ];
  brush.noFill();
  for (let rg of rings) {
    brush.set("rotring", rg.c, rg.w);
    brush.circle(CX, CY, rg.r, 0.012);
  }

  // Degree graduation tick-marks in the outer bezel (R_OUTER to R_OUTER + 6)
  brush.set("rotring", PAL.ironGallDark, 0.32);
  for (let a = 0; a < 360; a += 2) {
    let r1 = (a % 10 === 0) ? R_OUTER - 6 : R_OUTER;
    let r2 = R_OUTER + 6;
    brush.line(CX + cos(a) * r1, CY + sin(a) * r1, CX + cos(a) * r2, CY + sin(a) * r2);
  }

  // Engraved woodcut-style undulating ocean currents filling the annulus (R_INNER + 6 to R_OUTER - 7)
  let waveRings = 7;
  for (let wr = 0; wr < waveRings; wr++) {
    let baseR = map(wr, 0, waveRings - 1, R_INNER + 10, R_OUTER - 11);
    let col = (wr % 2 === 0) ? PAL.ironGallDark : PAL.ironGall;
    brush.set("rotring", col, 0.36);

    let segs = 36;
    for (let s = 0; s < segs; s++) {
      let aStart = s * (360 / segs) + wr * 3;
      let aEnd = aStart + (360 / segs) * 0.82;
      // Leave small openings for the 4 cardinal cartouches
      let midA = (aStart + aEnd) * 0.5 % 360;
      if (min(abs(midA - 0), abs(midA - 360)) < 9 || abs(midA - 90) < 9 || abs(midA - 180) < 9 || abs(midA - 270) < 9) {
        continue;
      }

      let pts = [];
      for (let k = 0; k <= 5; k++) {
        let a = lerp(aStart, aEnd, k / 5);
        let waveOffset = sin(k * 90 + s * 40) * 3.2;
        let r = baseR + waveOffset;
        pts.push([CX + cos(a) * r, CY + sin(a) * r]);
      }
      brush.spline(pts, 0.5);
    }
  }

  // Swirling whirlpool eddies & foam crests scattered in the ocean ring
  brush.set("quill", PAL.ironGallDark, 0.45);
  for (let a = 15; a < 360; a += 22.5) {
    if (a % 90 === 0) continue;
    let rm = (R_INNER + R_OUTER) * 0.5 + random(-8, 8);
    let ex = CX + cos(a) * rm;
    let ey = CY + sin(a) * rm;
    brush.arc(ex, ey, 9, a, a + 240);
    brush.arc(ex, ey, 5, a + 40, a + 290);
  }

  // Four Cardinal Direction Cartouches on the O-Ring (Medieval T-O orientation: ORIENS at top!)
  let cardinals = [
    { a: 270, label: "ORIENS" },     // Top (East / Asia)
    { a: 90, label: "OCCIDENS" },    // Bottom (West)
    { a: 180, label: "SEPTENTRIO" }, // Left (North / Europa)
    { a: 0, label: "MERIDIES" }      // Right (South / Africa)
  ];
  for (let card of cardinals) {
    let rm = (R_INNER + R_OUTER) * 0.5;
    let cx = CX + cos(card.a) * rm;
    let cy = CY + sin(card.a) * rm;
    push();
    translate(cx, cy);
    rotate(card.a + 90);
    // Vellum plaque
    drawBlobWash(0, 0, 44, 16, 0, PAL.vellumLight, 210, 0.05, 0.04, 18);
    brush.set("rotring", PAL.ironGallDark, 0.48);
    brush.noFill();
    brush.rect(-42, -14, 84, 28, "corner");
    brush.set("rotring", PAL.ironGall, 0.28);
    brush.rect(-38, -10, 76, 20, "corner");
    // Decorative scroll ears
    brush.arc(-42, 0, 8, 90, 270);
    brush.arc(42, 0, 8, 270, 450);
    // Micro-engraved Roman capitals simulation
    drawRomanInscription(0, 0, card.label);
    pop();
  }
}

function drawRomanInscription(cx, cy, textStr) {
  brush.set("rotring", PAL.ironGallDark, 0.36);
  let n = textStr.length;
  let spacing = 6.2;
  let startX = cx - ((n - 1) * spacing) / 2;
  for (let i = 0; i < n; i++) {
    let x = startX + i * spacing;
    let ch = textStr[i];
    if (ch === "O" || ch === "C") {
      brush.arc(x, cy, 3.6, ch === "O" ? 0 : 45, ch === "O" ? 360 : 315);
    } else if (ch === "I") {
      brush.line(x, cy - 4, x, cy + 4);
      brush.line(x - 1.5, cy - 4, x + 1.5, cy - 4);
      brush.line(x - 1.5, cy + 4, x + 1.5, cy + 4);
    } else if (ch === "E" || ch === "F") {
      brush.line(x - 2, cy - 4, x - 2, cy + 4);
      brush.line(x - 2, cy - 4, x + 2, cy - 4);
      brush.line(x - 2, cy, x + 1.5, cy);
      if (ch === "E") brush.line(x - 2, cy + 4, x + 2, cy + 4);
    } else if (ch === "N" || ch === "M") {
      brush.line(x - 2, cy - 4, x - 2, cy + 4);
      brush.line(x - 2, cy - 4, x + 2, cy + 4);
      brush.line(x + 2, cy - 4, x + 2, cy + 4);
    } else if (ch === "S") {
      brush.arc(x, cy - 2, 2, 110, 380);
      brush.arc(x, cy + 2, 2, 290, 560);
    } else if (ch === "R" || ch === "P" || ch === "D") {
      brush.line(x - 2, cy - 4, x - 2, cy + 4);
      brush.arc(x - 1, cy - 1.5, 2.5, 270, 450);
      if (ch === "R") brush.line(x - 0.5, cy + 0.5, x + 2, cy + 4);
    } else {
      brush.line(x, cy - 4, x, cy + 4);
      brush.line(x - 2.2, cy - 4, x + 2.2, cy - 4);
    }
  }
}

