    drawBlobWash(ox, oy, 6.5, 4.2, 35, PAL.gravyDark, 175, 0.04, 0.1, 14);
    brush.set("rotring", PAL.lampBlack, 0.35);
    brush.arc(ox, oy, 5, 20, 210);
    brush.set("quill", PAL.waxLight, 0.55);
    brush.point(ox - 1.5, oy - 1.2);
  }

  // --- 3) WINE-STAINED CRUMPLED NAPKIN AT (725, 902) ---
  drawCrumpledNapkin(725, 902, 58, 42, true);

  // Pewter spoon & dinner knife
  drawCutlery(895, 595, 965, 695, "spoon");
  drawCutlery(662, 745, 725, 835, "knife");
}

// =============================================================================
// HYPERREAL OBJECT RENDERERS (PLATES, BONES, BREAD, NAPKINS, GOBLET, CUTLERY)
// =============================================================================

function drawPlate(cx, cy, r, opts = {}) {
  let lv = getLightVector(cx, cy);
  let rWell = r * 0.67;

  // 1) Cast shadow on tabletop (shifted away from candle)
  drawCastShadow(cx, cy, r, r, 0, 22, 78);

  // 2) Plate body base in warm creamware/vellum
  drawBlobWash(cx, cy, r, r, 0, PAL.vellumWarm, 210, 0.04, 0.02, 36);

  // Rim shading on the away side (bottom-right) and highlight on candle side (top-left)
  drawBlobWash(cx + lv.ux * r * 0.25, cy + lv.uy * r * 0.25, r * 0.78, r * 0.78, 0, PAL.vellumDark, 68, 0.15, 0.04, 30);
  drawBlobWash(cx - lv.ux * r * 0.32, cy - lv.uy * r * 0.32, r * 0.55, r * 0.55, 0, PAL.waxLight, 95, 0.2, 0.04, 26);

  // 3) Concave Cavetto (Inner Well) Shadow — on a concave dish, the shadow falls on the LIGHT-FACING inner wall!
  let cavX = cx - lv.ux * (rWell * 0.14);
  let cavY = cy - lv.uy * (rWell * 0.14);
  drawBlobWash(cavX, cavY, rWell, rWell, 0, PAL.vellumDark, 85, 0.12, 0.03, 30);
  drawBlobWash(cx + lv.ux * (rWell * 0.1), cy + lv.uy * (rWell * 0.1), rWell * 0.92, rWell * 0.92, 0, PAL.vellumLight, 145, 0.12, 0.03, 30);

  // Radial curved contour hatching along the shadow crescent of the cavetto and rim
  brush.set("2H", PAL.sepiaMid, 0.26);
  for (let a = lv.angle + 115; a <= lv.angle + 245; a += 4) {
    let x1 = cx + cos(a) * (rWell * 0.78);
    let y1 = cy + sin(a) * (rWell * 0.78);
    let x2 = cx + cos(a) * rWell;
    let y2 = cy + sin(a) * rWell;
    brush.line(x1, y1, x2, y2);
  }
  for (let a = lv.angle - 65; a <= lv.angle + 65; a += 4.5) {
    let x1 = cx + cos(a) * (r * 0.86);
    let y1 = cy + sin(a) * (r * 0.86);
    let x2 = cx + cos(a) * r;
    let y2 = cy + sin(a) * r;
    brush.line(x1, y1, x2, y2);
  }

  // 4) Decorative painted band (Verdigris & Iron-Gall)
  brush.noFill();
  brush.set("cpencil", opts.rimColor || PAL.verdigrisDark, 0.55);
  brush.circle(cx, cy, r * 0.93, 0.015);
  brush.set("rotring", PAL.ironGall, 0.32);
  brush.circle(cx, cy, r * 0.89, 0.015);
  brush.circle(cx, cy, rWell, 0.018);

  // Outer structural rim of plate
  brush.set("rotring", PAL.ironGallDark, 0.52);
  brush.circle(cx, cy, r, 0.015);

  // 5) Residual gravy / oxblood jus smeared inside the plate well
  if (opts.hasJus) {
    drawBlobWash(cx + random(-10, 10), cy + random(-10, 10), rWell * 0.62, rWell * 0.45, random(360), opts.jusColor || PAL.gravyWarm, 92, 0.22, 0.28, 22);
    drawBlobWash(cx + 8, cy + 6, rWell * 0.35, rWell * 0.25, random(360), PAL.oxbloodDark, 85, 0.14, 0.25, 18);
    // Fork scratch marks & black peppercorn specks inside the well
    brush.set("rotring", PAL.lampBlack, 0.38);
    for (let p = 0; p < 14; p++) {
      let pa = random(360);
      let pr = random(rWell * 0.75);
      brush.point(cx + cos(pa) * pr, cy + sin(pa) * pr);
    }
  }

  // 6) Bright ceramic glaze specular arc facing the candle
  brush.set("quill", PAL.waxLight, 1.05);
  brush.arc(cx, cy, r * 0.96, lv.angle + 145, lv.angle + 215);
  brush.arc(cx, cy, rWell * 1.01, lv.angle - 35, lv.angle + 35);
}

function drawLongBone(x1, y1, x2, y2, w) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  let ang = atan2(dy, dx);
  let nx = -sin(ang);
  let ny = cos(ang);
  let mx = (x1 + x2) * 0.5;
  let my = (y1 + y2) * 0.5;

  // Cast shadow of the bone
  drawCastShadow(mx, my, len * 0.52, w * 0.85, ang, 9, 85);

  // Epiphyses (bilobed joint knuckles at both ends)
  let lobes = [
    { x: x1 + nx * w * 0.48, y: y1 + ny * w * 0.48, r: w * 0.65 },
    { x: x1 - nx * w * 0.48, y: y1 - ny * w * 0.48, r: w * 0.62 },
    { x: x2 + nx * w * 0.45, y: y2 + ny * w * 0.45, r: w * 0.58 },
    { x: x2 - nx * w * 0.45, y: y2 - ny * w * 0.45, r: w * 0.6 }
  ];
  for (let lb of lobes) {
    drawBlobWash(lb.x, lb.y, lb.r, lb.r * 0.9, ang, PAL.vellumMid, 210, 0.04, 0.1, 14);
  }

  // Bone shaft polygon
  let shaftPts = [
    [x1 + nx * w * 0.85, y1 + ny * w * 0.85],
    [mx + nx * w * 0.42, my + ny * w * 0.42],
    [x2 + nx * w * 0.8, y2 + ny * w * 0.8],
    [x2 - cos(ang) * w * 0.3, y2 - sin(ang) * w * 0.3],
    [x2 - nx * w * 0.8, y2 - ny * w * 0.8],
    [mx - nx * w * 0.42, my - ny * w * 0.42],
    [x1 - nx * w * 0.85, y1 - ny * w * 0.85],
    [x1 + cos(ang) * w * 0.3, y1 + sin(ang) * w * 0.3]
  ];
  brush.noStroke();
  brush.fill(PAL.vellumLight, 220);
  brush.fillBleed(0.03, "out");
  brush.beginShape(0.35);
  for (let p of shaftPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();

  // Dark roasted marrow & cartilage at the epiphyses
  drawBlobWash(x1, y1, w * 0.65, w * 0.55, ang + 90, PAL.oxbloodDark, 130, 0.08, 0.18, 14);
  drawBlobWash(x2, y2, w * 0.6, w * 0.5, ang + 90, PAL.gravyDark, 135, 0.08, 0.18, 14);

  // Spongy trabecular bone stippling on the knuckles
  brush.set("rotring", PAL.ironGallDark, 0.32);
  for (let s = 0; s < 14; s++) {
    brush.point(x1 + random(-w * 0.7, w * 0.7), y1 + random(-w * 0.7, w * 0.7));
    brush.point(x2 + random(-w * 0.65, w * 0.65), y2 + random(-w * 0.65, w * 0.65));
  }

  // Core shadow & osteological cross-contour hatching along the shaft
  brush.set("rotring", PAL.ironGall, 0.35);
  brush.spline([shaftPts[4], shaftPts[5], shaftPts[6]], 0.4);
  brush.spline([shaftPts[0], shaftPts[1], shaftPts[2]], 0.4);
  for (let lb of lobes) {
    brush.arc(lb.x, lb.y, lb.r, 0, 270);
  }
  for (let t = 0.15; t <= 0.85; t += 0.08) {
    let bx = lerp(x1, x2, t);
    let by = lerp(y1, y2, t);
    brush.line(bx - nx * w * 0.42, by - ny * w * 0.42, bx + nx * w * 0.05, by + ny * w * 0.05);
  }

  // Bright candlelight ridge along the upper shaft
  brush.set("quill", PAL.waxLight, 0.95);
  brush.spline([
    [lerp(x1, x2, 0.18) + nx * w * 0.18, lerp(y1, y2, 0.18) + ny * w * 0.18],
    [mx + nx * w * 0.14, my + ny * w * 0.14],
    [lerp(x1, x2, 0.82) + nx * w * 0.18, lerp(y1, y2, 0.82) + ny * w * 0.18]
  ], 0.4);
}

function drawRibBone(x1, y1, x2, y2, archOffset, w) {
  let mx = (x1 + x2) * 0.5;
  let my = (y1 + y2) * 0.5;
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang);
  let ny = cos(ang);
  let cx = mx + nx * archOffset;
  let cy = my + ny * archOffset;

  // Cast shadow of the curved rib
  brush.set("charcoal", PAL.ironGallDark, w * 0.25);
  brush.spline([[x1 + 5, y1 + 6], [cx + 6, cy + 7], [x2 + 5, y2 + 6]], 0.5);

  // Ivory rib body
  brush.set("cpencil", PAL.vellumLight, w * 0.35);
  brush.spline([[x1, y1], [cx, cy], [x2, y2]], 0.5);

  // Dark marrow tip & shadow contour
  brush.set("rotring", PAL.ironGallDark, 0.38);
  brush.spline([[x1 + nx * 2.2, y1 + ny * 2.2], [cx + nx * 2.4, cy + ny * 2.4], [x2 + nx * 1.8, y2 + ny * 1.8]], 0.5);
  brush.spline([[x1 - nx * 2.2, y1 - ny * 2.2], [cx - nx * 2.4, cy - ny * 2.4], [x2 - nx * 1.8, y2 - ny * 1.8]], 0.5);
  drawBlobWash(x1, y1, w * 0.8, w * 0.7, ang, PAL.oxbloodDark, 145, 0.05, 0.1, 10);

  // Bright ridge highlight
  brush.set("quill", PAL.waxLight, 0.8);
  brush.spline([[x1, y1], [cx - nx * 0.8, cy - ny * 0.8], [x2, y2]], 0.5);
}

function drawVertebra(cx, cy, ang, sz) {
  drawCastShadow(cx, cy, sz, sz * 0.75, ang, 7, 80);
  drawBlobWash(cx, cy, sz, sz * 0.72, ang, PAL.vellumMid, 215, 0.04, 0.15, 16);
  // Dark neural canal & intervertebral disc
  drawBlobWash(cx, cy, sz * 0.38, sz * 0.38, ang, PAL.oxbloodCoag, 165, 0.03, 0.1, 12);

  let ca = cos(ang);
  let sa = sin(ang);
  brush.set("rotring", PAL.ironGallDark, 0.36);
  brush.noFill();
  brush.circle(cx, cy, sz * 0.7, 0.12);
  // Transverse processes
  brush.line(cx - sa * sz * 1.15, cy + ca * sz * 1.15, cx + sa * sz * 1.15, cy - ca * sz * 1.15);
  brush.set("quill", PAL.waxLight, 0.75);
  brush.point(cx - 2, cy - 2);
}

function drawFishSkeleton(x1, y1, x2, y2) {
  let steps = 11;
  brush.set("rotring", PAL.ironGallDark, 0.45);
  brush.line(x1, y1, x2, y2);
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang);
  let ny = cos(ang);

  for (let i = 1; i < steps; i++) {
    let t = i / steps;
    let vx = lerp(x1, x2, t);
    let vy = lerp(y1, y2, t);
    let ribLen = sin(t * 180) * 26;
    // Tiny vertebra node
    brush.set("rotring", PAL.ironGallDark, 0.38);
    brush.circle(vx, vy, 2.6, 0.1);
    // Fine curved pin-bones
    brush.set("quill", PAL.vellumLight, 0.65);
    brush.spline([[vx, vy], [vx + nx * ribLen * 0.6 - cos(ang) * 5, vy + ny * ribLen * 0.6 - sin(ang) * 5], [vx + nx * ribLen - cos(ang) * 11, vy + ny * ribLen - sin(ang) * 11]], 0.45);
    brush.spline([[vx, vy], [vx - nx * ribLen * 0.6 - cos(ang) * 5, vy - ny * ribLen * 0.6 - sin(ang) * 5], [vx - nx * ribLen - cos(ang) * 11, vy - ny * ribLen - sin(ang) * 11]], 0.45);
    brush.set("rotring", PAL.ironGall, 0.24);
    brush.line(vx, vy, vx + nx * ribLen - cos(ang) * 11, vy + ny * ribLen - sin(ang) * 11);
    brush.line(vx, vy, vx - nx * ribLen - cos(ang) * 11, vy - ny * ribLen - sin(ang) * 11);
  }
}

function drawBreadCrust(cx, cy, rx, ry, rotDeg) {
  // Cast shadow
  drawCastShadow(cx, cy, rx, ry, rotDeg, 12, 85);

  // Dark blistered Maillard outer crust along one side
  let ca = cos(rotDeg);
  let sa = sin(rotDeg);
  drawBlobWash(cx - sa * ry * 0.25, cy + ca * ry * 0.25, rx * 1.04, ry * 0.95, rotDeg, PAL.gravyDark, 195, 0.05, 0.16, 20);
  drawBlobWash(cx - sa * ry * 0.32, cy + ca * ry * 0.32, rx * 0.95, ry * 0.65, rotDeg, PAL.ironGallDark, 165, 0.04, 0.18, 18);

  // Torn open airy crumb interior facing up/light
  drawBlobWash(cx + sa * ry * 0.12, cy - ca * ry * 0.12, rx * 0.88, ry * 0.78, rotDeg, PAL.vellumMid, 215, 0.05, 0.18, 22);
  drawBlobWash(cx + sa * ry * 0.18, cy - ca * ry * 0.18, rx * 0.72, ry * 0.58, rotDeg, PAL.vellumLight, 185, 0.06, 0.18, 18);

  // Alveolar air pockets (tiny shadowed pores inside the sourdough crumb!)
  let holes = floor((rx + ry) * 0.45);
  for (let h = 0; h < holes; h++) {
    let a = random(360);
    let rad = sqrt(random()) * 0.72;
    let lx = cos(a) * rx * rad;
    let ly = sin(a) * ry * rad * 0.75;
    let hx = cx + lx * ca - ly * sa;
    let hy = cy + lx * sa + ly * ca;
    let hr = random(1.4, 4.2);
    brush.set("rotring", PAL.sepiaMid, 0.32);
    brush.arc(hx, hy, hr, 140, 360);
    brush.set("quill", PAL.waxLight, 0.55);
    brush.arc(hx, hy, hr, 0, 140);
  }

  // Crisp jagged outline of torn crust
  brush.set("rotring", PAL.ironGallDark, 0.42);
  brush.circle(cx, cy, (rx + ry) * 0.48, 0.18);

  // Scattered bread crumbs around the chunk
  for (let c = 0; c < 18; c++) {
    let ca2 = random(360);
    let cd = random(rx * 1.1, rx * 2.2);
    let crx = cx + cos(ca2) * cd;
    let cry = cy + sin(ca2) * cd;
    let sz = random(1.2, 3.8);
    // Micro shadow
    brush.set("rotring", PAL.ironGallDark, 0.42);
    brush.point(crx + 1.2, cry + 1.2);
    // Crumb body
    brush.set("cpencil", random() < 0.4 ? PAL.gravyWarm : PAL.vellumLight, 0.65);
    brush.point(crx, cry);
  }
}

function drawCrumpledNapkin(cx, cy, r, seedAngle, hasWineStain) {
  let lv = getLightVector(cx, cy);

  // 1) Deep cast shadow under the crumpled cloth mass
  drawCastShadow(cx, cy, r * 1.05, r * 0.92, seedAngle, 20, 88);

  // 2) Base cloth silhouette with angular crumpled corners
  let outerPts = [];
  let lobes = 9;
  for (let i = 0; i < lobes; i++) {
    let a = seedAngle + (i / lobes) * 360;
    let rad = r * (i % 2 === 0 ? random(0.95, 1.22) : random(0.68, 0.85));
    outerPts.push([cx + cos(a) * rad, cy + sin(a) * rad]);
  }

  brush.noStroke();
  brush.fill(PAL.vellumMid, 210);
  brush.fillBleed(0.05, "out");
  brush.beginShape(0.25);
  for (let p of outerPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();

  // 3) Interior sculptural ridge facets (Leonardo-style drapery chiaroscuro)
  let hubs = [
    [cx - r * 0.18, cy - r * 0.12],
    [cx + r * 0.22, cy + r * 0.08],
    [cx - r * 0.05, cy + r * 0.25]
  ];

  for (let i = 0; i < lobes; i++) {
    let p1 = outerPts[i];
    let p2 = outerPts[(i + 1) % lobes];
    let hub = hubs[i % hubs.length];
    let facetMidX = (p1[0] + p2[0] + hub[0]) / 3;
    let facetMidY = (p1[1] + p2[1] + hub[1]) / 3;

    // Determine if this facet faces the candle or faces away
    let fAngle = atan2(facetMidY - cy, facetMidX - cx);
    let angleDiff = abs(((fAngle - (lv.angle + 180) + 540) % 360) - 180);
    let isLit = angleDiff < 85;

    brush.noStroke();
    brush.fill(isLit ? PAL.waxLight : PAL.parchmentUmber, isLit ? 155 : 95);
    brush.fillBleed(0.06, "in");
    brush.beginShape(0.18);
    brush.vertex(hub[0], hub[1]);
    brush.vertex(p1[0], p1[1]);
    brush.vertex(p2[0], p2[1]);
    brush.endShape(true);
    brush.noFill();

    // Fine directional cross-hatching inside shadow facets
    if (!isLit) {
      brush.set("2B", PAL.sepiaMid, 0.28);
      for (let t = 0.15; t <= 0.85; t += 0.12) {
        let sx = lerp(hub[0], p1[0], t);
        let sy = lerp(hub[1], p1[1], t);
        let ex = lerp(hub[0], p2[0], t);
        let ey = lerp(hub[1], p2[1], t);
        brush.line(sx, sy, ex, ey);
      }
    }

    // Crisp fold crease and bright ridge highlight
    brush.set("HB", PAL.sepiaMid, 0.36);
    brush.line(hub[0], hub[1], p1[0], p1[1]);
    if (isLit) {
      brush.set("quill", PAL.waxLight, 0.95);
      brush.line(hub[0] - 1.5, hub[1] - 1.5, p1[0] - 1.5, p1[1] - 1.5);
    }
  }

  // Optional wicked oxblood wine blotch on a corner of the napkin
  if (hasWineStain) {
    let sp = outerPts[2];
    drawBlobWash((sp[0] + cx) * 0.55, (sp[1] + cy) * 0.55, r * 0.32, r * 0.22, seedAngle + 30, PAL.oxbloodWash, 95, 0.28, 0.2, 16);
    drawBlobWash((sp[0] + cx) * 0.55, (sp[1] + cy) * 0.55, r * 0.18, r * 0.14, seedAngle + 30, PAL.oxbloodDark, 125, 0.15, 0.18, 14);
  }

  // Outer cloth contour & woven stripe near hem
  brush.set("rotring", PAL.ironGall, 0.38);
  brush.spline([...outerPts, outerPts[0]], 0.28);
}

function drawOverturnedGoblet(cx, cy, ang) {
  push();
  translate(cx, cy);
  rotate(ang);

  // Cast shadow and refractive caustic ellipse on the tabletop
  drawBlobWash(6, 12, 52, 26, 0, PAL.ironGallDark, 58, 0.2, 0.08, 22);
  drawBlobWash(-12, 16, 22, 11, 0, PAL.candleGlow, 75, 0.25, 0.08, 18); // Glass caustic glow!

  // Residual oxblood wine dregs trapped inside the tilted bowl
  drawBlobWash(18, 4, 22, 12, -10, PAL.oxbloodMid, 155, 0.08, 0.12, 18);
  drawBlobWash(28, 3, 18, 6, 0, PAL.oxbloodDark, 175, 0.05, 0.1, 16);

  // Bowl contour (mouth on the right at x = +48, stem on the left at x = -48)
  brush.set("rotring", PAL.ironGallDark, 0.42);
  brush.noFill();
  // Elliptical mouth rim
  brush.beginShape(0.5);
  for (let a = 0; a < 360; a += 20) {
    brush.vertex(46 + cos(a) * 9, sin(a) * 26);
  }
  brush.endShape(true);

  // Upper and lower bowl walls converging to the stem
  brush.spline([[46, -26], [18, -28], [-6, -16], [-16, -4]], 0.45);
  brush.spline([[46, 26], [18, 28], [-6, 16], [-16, 4]], 0.45);

  // Baluster stem & circular foot
  brush.rect(-46, -3.5, 30, 7, "corner");
  brush.circle(-28, 0, 6.5, 0.05);
  brush.beginShape(0.5);
  for (let a = 0; a < 360; a += 20) {
    brush.vertex(-48 + cos(a) * 7, sin(a) * 22);
  }
  brush.endShape(true);

  // Hyperreal glass specular highlights (razor-sharp white curves along bowl, rim, and stem)
  brush.set("quill", PAL.waxLight, 1.1);
  brush.spline([[40, -21], [16, -22], [-4, -12]], 0.4);
  brush.spline([[38, 16], [14, 18], [-2, 10]], 0.4);
  brush.line(-44, -2, -18, -2);
  brush.arc(46, 0, 18, 120, 250);
  brush.arc(-48, 0, 15, 110, 260);

  pop();
}

function drawCutlery(x1, y1, x2, y2, type) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  let ang = atan2(dy, dx);
  let mx = (x1 + x2) * 0.5;
  let my = (y1 + y2) * 0.5;

  drawCastShadow(mx, my, len * 0.5, 6, ang, 8, 82);

  push();
  translate(x1, y1);
  rotate(ang);

  let handleLen = len * 0.42;
  // Dark bone/ebony handle with brass rivets
  drawBlobWash(handleLen * 0.5, 0, handleLen * 0.5, 5.2, 0, PAL.ironGallDark, 210, 0.03, 0.06, 16);
  brush.set("rotring", PAL.lampBlack, 0.48);
  brush.rect(0, -4.5, handleLen, 9, "corner");
  brush.set("quill", PAL.waxLight, 0.75);
  brush.point(handleLen * 0.25, 0);
  brush.point(handleLen * 0.55, 0);
  brush.point(handleLen * 0.82, 0);

  if (type === "knife") {
    // Tarnished steel & verdigris blade
    drawBlobWash(handleLen + (len - handleLen) * 0.5, 1, (len - handleLen) * 0.5, 6.5, 0, PAL.verdigrisDark, 135, 0.05, 0.08, 16);
    brush.set("rotring", PAL.ironGallDark, 0.45);
    brush.spline([[handleLen, -4], [len - 18, -3.5], [len, 2], [len - 22, 7.5], [handleLen, 5]], 0.35);
    // Oxblood/jus smear on blade tip
    drawBlobWash(len - 22, 2, 16, 4.5, 5, PAL.oxbloodDark, 145, 0.08, 0.15, 12);
    // Metallic edge glint
    brush.set("quill", PAL.waxLight, 0.95);
    brush.line(handleLen + 4, -3.2, len - 6, -1.5);
  } else if (type === "fork") {
    // Two-tined carving fork
    brush.set("rotring", PAL.ironGallDark, 0.55);
    brush.line(handleLen, 0, handleLen + 22, 0);
    brush.spline([[handleLen + 22, -5.5], [len, -4.5]], 0.2);
    brush.spline([[handleLen + 22, 5.5], [len, 4.5]], 0.2);
    brush.line(handleLen + 22, -5.5, handleLen + 22, 5.5);
    brush.set("quill", PAL.waxLight, 0.8);
    brush.line(handleLen + 24, -4.8, len - 4, -4.0);
  } else if (type === "spoon") {
    // Pewter fig-shaped spoon bowl
    brush.set("rotring", PAL.ironGallDark, 0.55);
    brush.line(handleLen, 0, len - 32, 0);
    drawBlobWash(len - 16, 0, 18, 12, 0, PAL.verdigrisDark, 140, 0.05, 0.06, 18);
    drawBlobWash(len - 14, 2, 12, 8, 0, PAL.vellumMid, 160, 0.05, 0.06, 16);
    brush.set("rotring", PAL.ironGallDark, 0.45);
    brush.circle(len - 16, 0, 14, 0.08);
    brush.set("quill", PAL.waxLight, 0.9);
    brush.arc(len - 16, 0, 12, 160, 260);
  }

  pop();
}

function drawHerbSprig(x1, y1, x2, y2, leaves) {
  brush.set("rotring", PAL.ironGall, 0.35);
  brush.spline([[x1, y1], [(x1 + x2) * 0.5 + 5, (y1 + y2) * 0.5 - 4], [x2, y2]], 0.45);
  let ang = atan2(y2 - y1, x2 - x1);
  for (let i = 1; i <= leaves; i++) {
    let t = i / (leaves + 1);
    let lx = lerp(x1, x2, t);
    let ly = lerp(y1, y2, t);
    let side = (i % 2 === 0) ? 1 : -1;
    let la = ang + side * 42 + random(-8, 8);
    brush.set("cpencil", PAL.verdigrisDark, 0.55);
    brush.line(lx, ly, lx + cos(la) * 11, ly + sin(la) * 11);
    brush.set("rotring", PAL.verdigrisMid, 0.3);
    brush.line(lx, ly, lx + cos(la) * 9, ly + sin(la) * 9);
  }
}

