  brush.set("rotring", PAL.lampBlack, 0.6);
  brush.circle(cx, cy, 55, 0.015);
  brush.set("cpencil", PAL.verdigrisLight, 0.55);
  brush.circle(cx, cy, 51, 0.015);
  brush.set("rotring", PAL.ironGallDark, 0.45);
  brush.circle(cx, cy, 38, 0.015);
  brush.set("quill", PAL.candleGlow, 0.9);
  brush.arc(cx, cy, 53, 120, 250);

  // 3) Central Pillar Candle Stub & Melted Crater (`r = 26`)
  drawBlobWash(cx, cy, 27, 27, 0, PAL.waxMid, 235, 0.03, 0.06, 24);
  drawBlobWash(cx, cy, 22, 22, 0, PAL.waxLight, 235, 0.04, 0.06, 22);
  drawBlobWash(cx, cy, 14, 14, 0, PAL.candleGlow, 220, 0.12, 0.05, 20);

