function resetState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function polyShape(pts, curvature = 0, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  // Custom fine detail brush for razor-sharp zip teeth, barcodes, and scuff micro-scratches
  brush.add("needle", {
    type: "default",
    weight: 0.45,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 5,
    opacity: 230,
    spacing: 0.15,
    pressure: [0.9, 1.0, 0.8],
    noise: 0.25
  });

  // Custom flat chisel brush for hieroglyphic marks and stencil ticks
  brush.add("reed", {
    type: "marker",
    weight: 1.4,
    scatter: 0.03,
    opacity: 210,
    spacing: 0.1,
    pressure: [1.0, 0.85],
    markerTip: false,
    noise: 0.2
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Underlying cool limestone quarry block ground
  background(PAL.stoneSub);
  drawLimestonePlasterGround();

  // 2. Tomb Register Architecture: Frieze, Ruled Ochre Lines, Dado, and Portal Curtains
  drawTombArchitecture();

  // 3. Three Registers: Conveyors, Hieroglyphic Captions, and Hyperreal Baggage Procession
  drawRegisterOne(108, 434, 396);
  drawRegisterTwo(438, 764, 726);
  drawRegisterThree(768, 1094, 1056);

  // 4. Final Surface Weathering: Plaster cracks, flaking stucco islands, mineral dust
  drawSurfaceWeathering();

  noLoop();
}

// ============================================================================
// 1. LIMESTONE PLASTER WATERCOLOUR GROUND WITH FLAKING EDGES
// ============================================================================
function drawLimestonePlasterGround() {
  resetState();

  // Chisel marks and quarry stone grain around the outer margins
  brush.hatchStyle("2H", PAL.stoneDark, 0.45);
  brush.hatch(9, -32, { rand: 0.12 });
  brush.rect(10, 10, 1180, 1180);
  resetState();

  // Irregular flaking outer boundary of the limestone-gypsum plaster layer
  let plasterOutline = [];
  // Top edge
  for (let x = 38; x <= 1162; x += 28) {
    let dip = (x > 480 && x < 560) ? random(16, 34) : (x > 920 && x < 980 ? random(12, 24) : random(-6, 10));
    plasterOutline.push([x, 34 + dip]);
  }
  // Right edge
  for (let y = 45; y <= 1155; y += 28) {
    let dip = (y > 390 && y < 460) ? random(14, 32) : (y > 820 && y < 880 ? random(12, 26) : random(-6, 10));
    plasterOutline.push([1166 - dip, y]);
  }
  // Bottom edge
  for (let x = 1155; x >= 42; x -= 28) {
    let dip = (x > 660 && x < 740) ? random(14, 28) : (x > 210 && x < 280 ? random(12, 26) : random(-6, 10));
    plasterOutline.push([x, 1164 - dip]);
  }
  // Left edge
  for (let y = 1150; y >= 45; y -= 28) {
    let dip = (y > 260 && y < 330) ? random(14, 28) : (y > 690 && y < 750 ? random(14, 30) : random(-6, 10));
    plasterOutline.push([34 + dip, y]);
  }

  // Drop shadow of the thick stucco plaster slab onto the raw stone
  brush.wash(PAL.blackSlate, 55);
  let shadowPts = plasterOutline.map(p => [p[0] + 4, p[1] + 5]);
  polyShape(shadowPts, 0.08, true);
  resetState();

  // Main warm-cool limestone plaster opaque wash base
  brush.wash(PAL.plasterBase, 235);
  polyShape(plasterOutline, 0.08, true);
  resetState();

  // Layered watercolor washes for authentic limestone-plaster tonal variation (cool mineral bias)
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.45);

  const coolWashes = [
    [70, 80, 520, 360],
    [610, 90, 510, 340],
    [80, 440, 480, 320],
    [540, 450, 570, 310],
    [90, 770, 530, 330],
    [600, 780, 510, 320]
  ];
  brush.fill(PAL.plasterCool, 65);
  for (let w of coolWashes) {
    brush.rect(w[0] + random(-15, 15), w[1] + random(-10, 10), w[2], w[3]);
  }

  // Warm limestone-ochre undertones
  brush.fill(PAL.plasterWarm, 75);
  brush.rect(140, 130, 920, 280);
  brush.rect(120, 470, 950, 260);
  brush.rect(130, 790, 940, 270);

  // Subtle cool damp mineral stains near edges
  brush.fill(PAL.plasterShadow, 50);
  brush.circle(160, 210, 130, 0.4);
  brush.circle(1030, 560, 145, 0.4);
  brush.circle(230, 930, 135, 0.4);
  brush.circle(960, 180, 110, 0.4);
  brush.circle(540, 1080, 120, 0.4);
  resetState();

  // Gypsum white chalky broken edge highlight along plaster perimeter
  brush.set("cpencil", PAL.gypsumWhite, 0.9);
  polyShape(plasterOutline, 0.08, true);
  brush.set("2B", PAL.blackSlate, 0.55);
  polyShape(plasterOutline, 0.08, true);

  // Flaking detached islands of plaster near the margins
  for (let i = 0; i < 28; i++) {
    let side = i % 4;
    let fx = side === 0 ? random(60, 1140) : (side === 1 ? random(1148, 1175) : (side === 2 ? random(60, 1140) : random(22, 48)));
    let fy = side === 0 ? random(20, 46) : (side === 1 ? random(60, 1140) : (side === 2 ? random(1150, 1176) : random(60, 1140)));
    let fw = random(10, 28);
    let fh = random(8, 22);
    let flakePts = [
      [fx, fy],
      [fx + fw, fy + random(-4, 4)],
      [fx + fw * 0.85, fy + fh],
      [fx + random(-4, 4), fy + fh * 0.9]
    ];
    resetState();
    brush.wash(PAL.plasterFlake, 210);
    polyShape(flakePts, 0.05, true);
    resetState();
    brush.set("2H", PAL.blackSlate, 0.45);
    polyShape(flakePts, 0.05, true);
  }

  // Fine mineral grain stipple across the limestone wall
  resetState();
  brush.set("spray", PAL.stoneDark, 0.5);
  for (let i = 0; i < 24; i++) {
    let sx = random(70, 1130);
    let sy = random(70, 1130);
    brush.line(sx, sy, sx + random(40, 120), sy + random(-20, 20));
  }
  brush.set("spray", PAL.gypsumWhite, 0.45);
  for (let i = 0; i < 18; i++) {
    let sx = random(70, 1130);
    let sy = random(70, 1130);
    brush.line(sx, sy, sx + random(40, 110), sy + random(-15, 15));
  }
}

// ============================================================================
// 2. EGYPTIAN TOMB REGISTER LINES, BLOCK BORDER FRIEZE, AND PORTALS
// ============================================================================
function drawTombArchitecture() {
  resetState();

  const leftX = 64;
  const rightX = 1136;
  const spanW = rightX - leftX;

  // --- Top Tomb Block-Border Frieze (y: 66..98) ---
  brush.wash(PAL.gypsumWhite, 195);
  brush.rect(leftX, 66, spanW, 32);
  resetState();

  const blockColors = [PAL.blueMid, PAL.ochreRed, PAL.greenMid, PAL.blueDeep, PAL.ochreWarm, PAL.greenDeep];
  let bx = leftX + 4;
  let bIdx = 0;
  while (bx < rightX - 24) {
    let bw = 22;
    resetState();
    brush.wash(blockColors[bIdx % blockColors.length], 215);
    brush.rect(bx, 71, bw, 22);
    // White & carbon spacer bars between colored frieze blocks
    brush.wash(PAL.gypsumPure, 230);
    brush.rect(bx + bw, 71, 6, 22);
    resetState();
    brush.set("rotring", PAL.blackCarbon, 0.55);
    brush.line(bx, 71, bx, 93);
    brush.line(bx + bw, 71, bx + bw, 93);
    brush.line(bx + bw + 3, 71, bx + bw + 3, 93);
    bx += bw + 6;
    bIdx++;
  }

  // Framing ochre lines for top frieze
  drawRuledOchreBand(leftX, rightX, 64, 6);
  drawRuledOchreBand(leftX, rightX, 98, 10);

  // --- Register Divider Bands (Ruled Red Ochre with Scribe Snap-Line Marks) ---
  drawRuledOchreBand(leftX, rightX, 430, 8);
  drawRuledOchreBand(leftX, rightX, 760, 8);
  drawRuledOchreBand(leftX, rightX, 1090, 9);

  // --- Bottom Tomb Dado / Plinth Band (y: 1099..1138) ---
  resetState();
  brush.wash(PAL.blueDeep, 195);
  brush.rect(leftX, 1102, spanW, 13);
  brush.wash(PAL.gypsumWhite, 200);
  brush.rect(leftX, 1115, spanW, 6);
  brush.wash(PAL.greenDeep, 195);
  brush.rect(leftX, 1121, spanW, 13);
  resetState();

  brush.set("rotring", PAL.blackCarbon, 0.65);
  brush.line(leftX, 1102, rightX, 1102);
  brush.line(leftX, 1115, rightX, 1115);
  brush.line(leftX, 1121, rightX, 1121);
  brush.line(leftX, 1134, rightX, 1134);

  // --- Vertical Side Borders (Left & Right Tomb Jambs) ---
  resetState();
  brush.wash(PAL.ochreRed, 185);
  brush.rect(leftX - 8, 64, 8, 1070);
  brush.rect(rightX, 64, 8, 1070);
  resetState();
  brush.set("cpencil", PAL.ochreDeep, 0.85);
  brush.line(leftX - 8, 64, leftX - 8, 1134);
  brush.line(leftX, 64, leftX, 1134);
  brush.line(rightX, 64, rightX, 1134);
  brush.line(rightX + 8, 64, rightX + 8, 1134);

  // Scribe measurement tick marks along left margin
  brush.set("rotring", PAL.ochreDeep, 0.45);
  for (let y = 110; y < 1090; y += 20) {
    let tLen = (y % 100 === 10) ? 9 : 4;
    brush.line(leftX - 8 - tLen, y, leftX - 8, y);
  }

  // --- Airport Baggage Hatch Curtains at Left & Right of each Register ---
  const regBounds = [
    [108, 396],
    [438, 726],
    [768, 1056]
  ];
  for (let r = 0; r < 3; r++) {
    let ry1 = regBounds[r][0];
    let ry2 = regBounds[r][1];
    drawBaggagePortalCurtain(leftX, ry2 - 195, 22, 195, true);
    drawBaggagePortalCurtain(rightX - 20, ry2 - 195, 20, 195, false);
  }
}

function drawRuledOchreBand(x1, x2, y, h) {
  resetState();
  brush.wash(PAL.ochreRed, 215);
  brush.rect(x1, y, x2 - x1, h);
  brush.wash(PAL.ochreWarm, 95);
  brush.rect(x1, y + 1, x2 - x1, h * 0.45);
  resetState();

  // Double ruled cord-snap lines in deep ochre and carbon black
  brush.set("cpencil", PAL.ochreDeep, 0.9);
  brush.line(x1 - 6, y, x2 + 6, y);
  brush.line(x1 - 6, y + h, x2 + 6, y + h);

  brush.set("rotring", PAL.blackCarbon, 0.45);
  brush.line(x1, y - 1.5, x2, y - 1.5);
  brush.line(x1, y + h + 1.5, x2, y + h + 1.5);

  // Subtle gypsum highlight along top edge of ruled band
  brush.set("needle", PAL.gypsumWhite, 0.65);
  brush.line(x1, y + 1.2, x2, y + 1.2);
}

function drawBaggagePortalCurtain(x, y, w, h, isLeft) {
  resetState();
  // Dark aperture header frame
  brush.wash(PAL.blackDeep, 215);
  brush.rect(x, y, w, 12);
  // Hanging rubberized PVC strip curtains in side-profile overlap
  let strips = 4;
  let sw = w / strips;
  for (let i = 0; i < strips; i++) {
    let sx = x + i * sw;
    resetState();
    brush.wash(i % 2 === 0 ? PAL.blackSlate : PAL.blackCarbon, 185);
    brush.rect(sx, y + 12, sw - 0.5, h - 12);
    resetState();
    brush.set("needle", PAL.gypsumWhite, 0.5);
    brush.line(sx + 1, y + 14, sx + 1, y + h - 4);
    brush.set("rotring", PAL.blackDeep, 0.55);
    brush.line(sx, y + 12, sx, y + h);
  }
  // Ochre/Blue hazard chevron bar above the chute
  resetState();
  brush.wash(PAL.ochreWarm, 220);
  brush.rect(x, y - 8, w, 8);
  brush.set("reed", PAL.blueDeep, 0.7);
  for (let cx = x + 2; cx < x + w - 2; cx += 6) {
    brush.line(cx, y - 8, cx + 3, y);
  }
}

// ============================================================================
// 3. CONVEYOR BELT IN STRICT SIDE PROFILE
// ============================================================================
function drawConveyorBelt(x1, x2, yDeck, yBottom, seedOff) {
  let h = yBottom - yDeck;
  let beltH = 14;
  let trackY = yDeck + beltH;
  let trackH = h - beltH;

  resetState();
  // Upper dark articulated rubber slat surface
  brush.wash(PAL.blackCarbon, 235);
  brush.rect(x1, yDeck, x2 - x1, beltH);

  // Lower steel chassis / roller housing channel in cool slate & Egyptian blue-gray
  brush.wash(PAL.blackSlate, 220);
  brush.rect(x1, trackY, x2 - x1, trackH);

  // Gypsum metallic rail trim along the middle of the chassis
  brush.wash(PAL.plasterCool, 185);
  brush.rect(x1, trackY + 3, x2 - x1, 5);
  resetState();

  // Articulated overlapping rubber slats (strict side profile saw-tooth overlap marching right)
  let slatW = 24;
  for (let sx = x1; sx < x2 - 4; sx += slatW) {
    let w = min(slatW, x2 - sx);
    // Diagonal seam line between overlapping rubber plates
    brush.set("rotring", PAL.blackDeep, 0.75);
    brush.line(sx, yDeck, sx - 4, yDeck + beltH);

    // Specular gypsum white edge glint on top of each rubber slat
    brush.set("needle", PAL.gypsumWhite, 0.75);
    brush.line(sx + 1, yDeck + 1.2, sx + w - 2, yDeck + 1.2);

    // Subtle blue-gray sheen & scuff marks along rubber edge
    brush.set("needle", PAL.bluePale, 0.55);
    brush.line(sx + 2, yDeck + 3.2, sx + w * 0.7, yDeck + 3.2);

    // Rivet pin on each slat flank
    brush.set("rotring", PAL.gypsumCream, 0.7);
    brush.circle(sx + w * 0.5, yDeck + beltH * 0.55, 1.4);
  }

  // Steel return rollers and bearings visible inside chassis cutouts every 64px
  for (let rx = x1 + 28; rx < x2 - 24; rx += 56) {
    resetState();
    // Recessed dark slot
    brush.wash(PAL.blackDeep, 230);
    brush.rect(rx - 14, trackY + 9, 28, trackH - 11);
    // Twin steel rollers in side profile
    brush.wash(PAL.gypsumCream, 215);
    brush.circle(rx - 6, trackY + 14.5, 4.5);
    brush.circle(rx + 6, trackY + 14.5, 4.5);
    resetState();
    brush.set("rotring", PAL.blackDeep, 0.6);
    brush.circle(rx - 6, trackY + 14.5, 4.5);
    brush.circle(rx + 6, trackY + 14.5, 4.5);
    // Axle pin in red ochre & black
    brush.set("rotring", PAL.ochreRed, 0.75);
    brush.circle(rx - 6, trackY + 14.5, 1.3);
    brush.circle(rx + 6, trackY + 14.5, 1.3);

    // Directional stencil arrow marching left -> right between roller bays
    if (rx + 28 < x2 - 20) {
      let ax = rx + 22;
      let ay = trackY + 14.5;
      brush.set("reed", PAL.ochreWarm, 0.65);
      brush.line(ax - 5, ay, ax + 5, ay);
      brush.line(ax + 1, ay - 3, ax + 5, ay);
      brush.line(ax + 1, ay + 3, ax + 5, ay);
    }
  }

  // Crisp ruled boundaries of the conveyor assembly
  brush.set("rotring", PAL.blackDeep, 0.85);
  brush.line(x1, yDeck, x2, yDeck);
  brush.line(x1, trackY, x2, trackY);
  brush.line(x1, yBottom, x2, yBottom);
}

function drawContactShadow(x, yDeck, w) {
  resetState();
  brush.wash(PAL.blackDeep, 175);
  brush.rect(x + 4, yDeck - 2.5, w - 8, 5);
  brush.set("charcoal", PAL.blackDeep, 0.9);
  brush.line(x + 2, yDeck, x + w - 2, yDeck);
}

// ============================================================================
// 4. NEAT COLUMNS OF TINY PICTOGRAPHIC MARKS (TOMB + AVIATION HIEROGLYPHS)
// ============================================================================
function drawHieroglyphBlock(xStart, yTop, yBottom, numCols, seedVal) {
  let colW = 21;
  let totalH = yBottom - yTop;
  if (totalH < 28) return;

  resetState();
  // Faint gypsum-wash backing for the inscription block
  brush.wash(PAL.gypsumWhite, 75);
  brush.rect(xStart, yTop, numCols * colW, totalH);
  resetState();

  // Vertical ruled red-ochre column dividers
  brush.set("rotring", PAL.ochreRed, 0.55);
  for (let c = 0; c <= numCols; c++) {
    let cx = xStart + c * colW;
    brush.line(cx, yTop, cx, yBottom);
  }
  // Top & bottom thin cap lines
  brush.line(xStart, yTop, xStart + numCols * colW, yTop);

  // Populate each vertical column with neat tiny pictographs
  const glyphColors = [PAL.blueDeep, PAL.ochreRed, PAL.greenDeep, PAL.blackCarbon, PAL.blueMid];
  let glyphIndex = seedVal;

  for (let c = 0; c < numCols; c++) {
    let cx = xStart + c * colW + colW * 0.5;
    let cy = yTop + 10;
    while (cy < yBottom - 10) {
      let col = glyphColors[glyphIndex % glyphColors.length];
      let gType = glyphIndex % 12;
      drawTinyPictograph(cx, cy, gType, col);
      cy += 17;
      glyphIndex += 3;
    }
  }
}

function drawTinyPictograph(cx, cy, gType, col) {
  resetState();
  brush.set("rotring", col, 0.55);

  if (gType === 0) {
    // Profile Aircraft Glyph (marching right)
    brush.line(cx - 6, cy, cx + 6, cy); // fuselage
    brush.line(cx - 1, cy - 5, cx + 2, cy); // upper wing
    brush.line(cx - 1, cy + 5, cx + 2, cy); // lower wing
    brush.line(cx - 6, cy - 3.5, cx - 4, cy); // tail fin
  } else if (gType === 1) {
    // Barcode / Baggage Tag Tally Block
    for (let dx = -5; dx <= 5; dx += 2.5) {
      let lw = (abs(dx) === 2.5) ? 0.75 : 0.45;
      brush.set("rotring", col, lw);
      brush.line(cx + dx, cy - 4.5, cx + dx, cy + 4.5);
    }
  } else if (gType === 2) {
    // Fragile Chalice / Offering Vessel
    brush.line(cx - 4, cy - 5, cx + 4, cy - 5);
    brush.line(cx - 4, cy - 5, cx - 2, cy);
    brush.line(cx + 4, cy - 5, cx + 2, cy);
    brush.line(cx - 2, cy, cx + 2, cy);
    brush.line(cx, cy, cx, cy + 5);
    brush.line(cx - 3.5, cy + 5, cx + 3.5, cy + 5);
  } else if (gType === 3) {
    // Suitcase with Walking Legs (Egyptian 'jw' determinative!)
    brush.rect(cx - 4.5, cy - 5, 9, 6);
    brush.line(cx - 2, cy - 5, cx - 2, cy - 7);
    brush.line(cx + 2, cy - 5, cx + 2, cy - 7);
    brush.line(cx - 2, cy - 7, cx + 2, cy - 7);
    // Walking legs marching right
    brush.line(cx - 1, cy + 1, cx - 3, cy + 6);
    brush.line(cx + 1, cy + 1, cx + 3.5, cy + 6);
    brush.line(cx + 3.5, cy + 6, cx + 5.5, cy + 6);
  } else if (gType === 4) {
    // Wavy Water / Conveyor Motion Ripples (3 stacked 'n' glyphs)
    for (let dy = -3.5; dy <= 3.5; dy += 3.5) {
      brush.line(cx - 5.5, cy + dy, cx - 3, cy + dy - 1.8);
      brush.line(cx - 3, cy + dy - 1.8, cx, cy + dy + 1.8);
      brush.line(cx, cy + dy + 1.8, cx + 3, cy + dy - 1.8);
      brush.line(cx + 3, cy + dy - 1.8, cx + 5.5, cy + dy);
    }
  } else if (gType === 5) {
    // Solar Disc (`ra`) with Wing Ticks
    brush.circle(cx, cy, 3.8);
    brush.circle(cx, cy, 1.0);
    brush.line(cx - 6.5, cy, cx - 4.2, cy);
    brush.line(cx + 4.2, cy, cx + 6.5, cy);
  } else if (gType === 6) {
    // Umbrella / Keep Dry Glyph
    brush.arc(cx, cy, 5, 180, 360);
    brush.line(cx - 5, cy, cx + 5, cy);
    brush.line(cx, cy - 5, cx, cy + 5);
    brush.line(cx, cy + 5, cx - 2, cy + 5);
  } else if (gType === 7) {
    // Eye of Horus / Security Scanner Glyph
    brush.arc(cx, cy - 1, 5.5, 200, 340);
    brush.line(cx - 5.5, cy + 0.5, cx + 5.5, cy + 0.5);
    brush.circle(cx, cy - 0.5, 1.8);
    brush.line(cx, cy + 1, cx - 2, cy + 5.5);
    brush.line(cx + 1.5, cy + 1, cx + 4, cy + 4.5);
  } else if (gType === 8) {
    // Balance Scale / Baggage Weight Glyph
    brush.line(cx, cy - 5, cx, cy + 5);
    brush.line(cx - 5.5, cy - 3, cx + 5.5, cy - 3);
    brush.line(cx - 5.5, cy - 3, cx - 4.5, cy + 2);
    brush.line(cx + 5.5, cy - 3, cx + 4.5, cy + 2);
    brush.line(cx - 6.5, cy + 2, cx - 2.5, cy + 2);
    brush.line(cx + 2.5, cy + 2, cx + 6.5, cy + 2);
  } else if (gType === 9) {
    // Luggage Tag Keyhole Glyph + Plural Strokes
    brush.poly = [
      [cx - 5, cy - 2],
      [cx - 2, cy - 5],
      [cx + 5, cy - 5],
      [cx + 5, cy + 1],
      [cx - 2, cy + 1]
    ];
    polyShape(brush.poly, 0, true);
    brush.circle(cx - 2.5, cy - 2, 1.0);
    // Three plural strokes underneath
    brush.line(cx - 4, cy + 3, cx - 4, cy + 6);
    brush.line(cx, cy + 3, cx, cy + 6);
    brush.line(cx + 4, cy + 3, cx + 4, cy + 6);
  } else if (gType === 10) {
    // Egyptian Basket ('nb') + Loaf ('t')
    brush.arc(cx, cy - 2, 5.5, 0, 180);
    brush.line(cx - 5.5, cy - 2, cx + 5.5, cy - 2);
    brush.arc(cx, cy + 5.5, 3.5, 180, 360);
    brush.line(cx - 3.5, cy + 5.5, cx + 3.5, cy + 5.5);
  } else {
    // "This Way Up" Twin Arrows over Horizon Bar
    brush.line(cx - 5.5, cy + 4.5, cx + 5.5, cy + 4.5);
    for (let dx of [-2.8, 2.8]) {
      brush.line(cx + dx, cy + 3, cx + dx, cy - 4.5);
      brush.line(cx + dx - 2, cy - 2, cx + dx, cy - 4.5);
      brush.line(cx + dx + 2, cy - 2, cx + dx, cy - 4.5);
    }
  }
}

