// ============================================================================
// 6. HYPERREAL OBJECT 1: POLYCARBONATE SUITCASE IN STRICT SIDE PROFILE
// ============================================================================
function drawSuitcase(x, yDeck, w, h, cfg) {
  let wheelH = 26;
  let bodyY = yDeck - h;
  let bodyH = h - wheelH;
  let r = 16; // corner radius

  drawContactShadow(x + 8, yDeck, w - 16);

  // --- 1. Twin 360-Spinner Caster Wheel Assemblies (strict side profile) ---
  const wheelXs = [x + 26, x + w - 26];
  for (let wx of wheelXs) {
    resetState();
    // Molded plastic wheel housing bracket
    let housingPts = [
      [wx - 13, bodyY + bodyH - 2],
      [wx + 13, bodyY + bodyH - 2],
      [wx + 9, yDeck - 11],
      [wx - 5, yDeck - 11]
    ];
    brush.wash(PAL.blackCarbon, 235);
    polyShape(housingPts, 0.05, true);

    // Dual wheel tire in side profile
    let wy = yDeck - 9.5;
    brush.wash(PAL.blackDeep, 245);
    brush.circle(wx + 2, wy, 9.5);
    // Inner wheel hub in gypsum & accent
    brush.wash(PAL.plasterCool, 220);
    brush.circle(wx + 2, wy, 5.2);
    resetState();

    // Rim, rubber tread, and axle pin details
    brush.set("rotring", PAL.blackDeep, 0.75);
    brush.circle(wx + 2, wy, 9.5);
    brush.circle(wx + 2, wy, 5.2);
    brush.set("needle", PAL.gypsumPure, 0.75);
    brush.arc(wx + 2, wy, 8.2, 200, 330);
    brush.set("rotring", PAL.ochreRed, 0.8);
    brush.circle(wx + 2, wy, 1.5);
  }

  // --- 2. Telescopic Handle (if extended on left/rear spine) & Top Carry Handle ---
  if (cfg.handleUp > 0) {
    let hx = x + 22;
    let hy = bodyY - cfg.handleUp;
    resetState();
    // Chrome/Gypsum twin tubes in side profile
    brush.wash(PAL.gypsumWhite, 230);
    brush.rect(hx, hy, 7, cfg.handleUp + 2);
    brush.wash(PAL.blackCarbon, 235);
    brush.rect(hx - 4, hy - 7, 26, 8);
    resetState();
    brush.set("rotring", PAL.blackDeep, 0.65);
    brush.rect(hx, hy, 7, cfg.handleUp + 2);
    brush.rect(hx - 4, hy - 7, 26, 8);
    brush.set("needle", PAL.gypsumPure, 0.8);
    brush.line(hx + 2, hy, hx + 2, bodyY);
  }

  // Top low-profile rubberized carry handle
  let thx = x + w * 0.42;
  let thw = w * 0.34;
  resetState();
  brush.wash(PAL.blackCarbon, 230);
  polyShape([
    [thx, bodyY],
    [thx + 6, bodyY - 8],
    [thx + thw - 6, bodyY - 8],
    [thx + thw, bodyY],
    [thx + thw - 8, bodyY],
    [thx + thw - 11, bodyY - 4],
    [thx + 11, bodyY - 4],
    [thx + 8, bodyY]
  ], 0.1, true);
  resetState();
  brush.set("rotring", PAL.blackDeep, 0.6);
  brush.line(thx + 6, bodyY - 8, thx + thw - 6, bodyY - 8);

  // Left-spine rubber bumper feet (strict side profile)
  for (let fy of [bodyY + bodyH * 0.25, bodyY + bodyH * 0.72]) {
    resetState();
    brush.wash(PAL.blackCarbon, 235);
    polyShape([
      [x, fy - 9],
      [x - 5, fy - 6],
      [x - 5, fy + 6],
      [x, fy + 9]
    ], 0.05, true);
    resetState();
    brush.set("rotring", PAL.blackDeep, 0.55);
    brush.line(x - 5, fy - 6, x - 5, fy + 6);
  }

  // --- 3. Polycarbonate Shell Body ---
  let shellPts = [
    [x + r, bodyY],
    [x + w - r, bodyY],
    [x + w, bodyY + r],
    [x + w, bodyY + bodyH - r],
    [x + w - r, bodyY + bodyH],
    [x + r, bodyY + bodyH],
    [x, bodyY + bodyH - r],
    [x, bodyY + r]
  ];

  resetState();
  // Opaque pigment base + watercolor mineral bleed
  brush.wash(cfg.shellCol, 225);
  polyShape(shellPts, 0.15, true);

  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.55, 0.4);
  brush.fill(cfg.darkCol, 85);
  polyShape(shellPts, 0.15, true);
  resetState();

  // Molded polycarbonate corner bumper guards
  const corners = [
    [[x, bodyY + 26], [x, bodyY + r], [x + r, bodyY], [x + 26, bodyY], [x + 20, bodyY + 14], [x + 14, bodyY + 20]],
    [[x + w - 26, bodyY], [x + w - r, bodyY], [x + w, bodyY + r], [x + w, bodyY + 26], [x + w - 14, bodyY + 20], [x + w - 20, bodyY + 14]],
    [[x, bodyY + bodyH - 26], [x + 14, bodyY + bodyH - 20], [x + 20, bodyY + bodyH - 14], [x + 26, bodyY + bodyH], [x + r, bodyY + bodyH], [x, bodyY + bodyH - r]],
    [[x + w - 26, bodyY + bodyH], [x + w - 20, bodyY + bodyH - 14], [x + w - 14, bodyY + bodyH - 20], [x + w, bodyY + bodyH - 26], [x + w, bodyY + bodyH - r], [x + w - r, bodyY + bodyH]]
  ];
  for (let cp of corners) {
    resetState();
    brush.wash(cfg.darkCol, 155);
    polyShape(cp, 0.1, true);
    resetState();
    brush.set("rotring", PAL.blackCarbon, 0.45);
    polyShape(cp, 0.1, true);
  }

  // --- 4. Molded Polycarbonate Ribs (3D bevel highlights & shadows) ---
  if (cfg.ribMode === "vertical") {
    let spacing = (w - 36) / (cfg.numRibs + 1);
    for (let i = 1; i <= cfg.numRibs; i++) {
      let rx = x + 18 + i * spacing;
      let ry1 = bodyY + 22;
      let ry2 = bodyY + bodyH - 22;
      brush.set("cpencil", cfg.darkCol, 0.85);
      brush.line(rx - 2, ry1, rx - 2, ry2);
      brush.set("rotring", PAL.blackCarbon, 0.45);
      brush.line(rx, ry1, rx, ry2);
      brush.set("needle", PAL.gypsumPure, 0.85);
      brush.line(rx + 2, ry1, rx + 2, ry2);
    }
  } else {
    let spacing = (bodyH - 36) / (cfg.numRibs + 1);
    for (let i = 1; i <= cfg.numRibs; i++) {
      let ry = bodyY + 18 + i * spacing;
      let rx1 = x + 18;
      let rx2 = x + w - 18;
      brush.set("needle", PAL.gypsumPure, 0.85);
      brush.line(rx1, ry - 2, rx2, ry - 2);
      brush.set("rotring", PAL.blackCarbon, 0.45);
      brush.line(rx1, ry, rx2, ry);
      brush.set("cpencil", cfg.darkCol, 0.85);
      brush.line(rx1, ry + 2, rx2, ry + 2);
    }
  }

  // --- 5. Perimeter Clamshell Zipper Track & Individual Metallic Zip Teeth ---
  // In strict side profile, the perimeter zipper curves just inside the right/front edge or around the bevel
  let zx = x + w - 11;
  resetState();
  brush.wash(cfg.zipCol, 225);
  brush.rect(zx - 3.5, bodyY + 10, 7, bodyH - 20);
  resetState();

  // Individual hyperreal metallic zip teeth along the vertical seam
  for (let zy = bodyY + 13; zy < bodyY + bodyH - 13; zy += 3.2) {
    brush.set("needle", PAL.gypsumPure, 0.75);
    brush.line(zx - 2.5, zy, zx + 2.5, zy);
    brush.set("needle", PAL.blackDeep, 0.55);
    brush.line(zx - 2.2, zy + 1.5, zx + 2.2, zy + 1.5);
  }

  // Recessed TSA Lock & Dual Zipper Sliders on upper right flank
  let lockY = bodyY + 46;
  resetState();
  brush.wash(PAL.blackDeep, 235);
  brush.rect(zx - 6, lockY, 9, 26);
  brush.wash(PAL.ochreRed, 230);
  brush.rect(zx - 4, lockY + 3, 5, 5); // red TSA diamond indicator
  resetState();
  // Two hanging metal zipper pull tabs
  brush.set("rotring", PAL.gypsumPure, 0.85);
  brush.line(zx, lockY + 18, zx - 6, lockY + 30);
  brush.line(zx, lockY + 24, zx - 4, lockY + 36);

  // --- 6. Hyperreal Scuffed Polycarbonate Surface Texture ---
  drawPolycarbonateScuffs(x + 12, bodyY + 16, w - 28, bodyH - 32, cfg.seed);

  // --- 7. Peeling Airport Stickers & Barcode Labels ---
  if (cfg.sticker1) {
    drawPeelingSticker(
      x + w * cfg.sticker1.rx,
      bodyY + bodyH * cfg.sticker1.ry,
      cfg.sticker1.w,
      cfg.sticker1.h,
      cfg.sticker1.col,
      cfg.sticker1.type
    );
  }
  if (cfg.sticker2) {
    drawPeelingSticker(
      x + w * cfg.sticker2.rx,
      bodyY + bodyH * cfg.sticker2.ry,
      cfg.sticker2.w,
      cfg.sticker2.h,
      cfg.sticker2.col,
      cfg.sticker2.type
    );
  }

  // --- 8. Crisp Outer Shell Contour ---
  resetState();
  brush.set("rotring", PAL.blackDeep, 0.85);
  polyShape(shellPts, 0.15, true);
  // Specular gypsum edge highlight along top and left ridge
  brush.set("needle", PAL.gypsumPure, 0.85);
  brush.line(x + r, bodyY + 1.5, x + w - r, bodyY + 1.5);
  brush.line(x + 1.8, bodyY + r, x + 1.8, bodyY + bodyH - r);

  // --- 9. Tangled Hanging Luggage Tag from Top Handle ---
  drawTangledLuggageTag(thx + thw * 0.75, bodyY - 4, cfg.tagColor, cfg.seed);
}

function drawPolycarbonateScuffs(x, y, w, h, seed) {
  resetState();
  // Chalky gypsum friction abrasions & black rubber conveyor transfer streaks
  for (let i = 0; i < 16; i++) {
    let sx = x + ((seed * 37 + i * 53) % int(w - 14));
    let sy = y + ((seed * 23 + i * 41) % int(h - 10));
    let len = 8 + (i % 5) * 5;
    let ang = -25 + (i % 4) * 18;
    let dx = cos(ang) * len;
    let dy = sin(ang) * len;

    if (i % 2 === 0) {
      // White polycarbonate stress-whitening scratch cluster
      brush.set("needle", PAL.gypsumPure, 0.65);
      brush.line(sx, sy, sx + dx, sy + dy);
      brush.line(sx + 1, sy + 1.8, sx + dx * 0.85, sy + dy * 0.85 + 1.8);
    } else {
      // Carbon black tarmac / bumper rubber smudge
      brush.set("2B", PAL.blackDeep, 0.55);
      brush.line(sx, sy, sx + dx, sy + dy);
      brush.set("needle", PAL.blackCarbon, 0.5);
      brush.line(sx - 1, sy + 1.5, sx + dx * 0.9, sy + dy * 0.9 + 1.5);
    }
  }
}

// ============================================================================
// 7. HYPERREAL OBJECT 2: CANVAS & WEBBING DUFFEL BAG IN STRICT SIDE PROFILE
// ============================================================================
function drawDuffelBag(x, yDeck, w, h, cfg) {
  let yTop = yDeck - h;

  drawContactShadow(x + 10, yDeck, w - 20);

  // Organic slumped side-profile silhouette (flat base on conveyor, pinched ends, undulating top)
  let bodyPts = [
    [x + 14, yDeck - 2],
    [x + w * 0.5, yDeck],
    [x + w - 12, yDeck - 2],
    [x + w, yDeck - h * 0.36],
    [x + w - 6, yTop + h * 0.22],
    [x + w * 0.76, yTop + 4],
    [x + w * 0.52, yTop + 12], // central dip between haul straps
    [x + w * 0.26, yTop + 2],
    [x + 8, yTop + h * 0.20],
    [x, yDeck - h * 0.42]
  ];

  resetState();
  // Opaque base + watercolor shadow modelling
  brush.wash(cfg.bodyCol, 225);
  polyShape(bodyPts, 0.22, true);

  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.65, 0.45);
  brush.fill(cfg.darkCol, 95);
  polyShape(bodyPts, 0.22, true);
  resetState();

  // Woven heavy canvas cross-hatch texture
  brush.hatchStyle("2H", cfg.darkCol, 0.4);
  brush.hatch(5.5, 18, { rand: 0.08 });
  polyShape(bodyPts, 0.22, true);
  resetState();

  // Reinforced rubberized bottom boot / base panel
  let basePts = [
    [x + 14, yDeck - 2],
    [x + w * 0.5, yDeck],
    [x + w - 12, yDeck - 2],
    [x + w - 2, yDeck - 24],
    [x + w * 0.5, yDeck - 22],
    [x + 2, yDeck - 24]
  ];
  brush.wash(PAL.blackCarbon, 210);
  polyShape(basePts, 0.1, true);
  resetState();
  brush.set("needle", cfg.trimCol, 0.7);
  brush.line(x + 3, yDeck - 24, x + w - 3, yDeck - 24);

  // Deep fabric compression folds and creases radiating from the straps
  const folds = [
    [[x + 24, yTop + 28], [x + w * 0.28, yTop + 52], [x + 18, yDeck - 34]],
    [[x + w * 0.34, yTop + 18], [x + w * 0.48, yTop + 46], [x + w * 0.66, yTop + 22]],
    [[x + w * 0.42, yDeck - 30], [x + w * 0.55, yTop + 64], [x + w * 0.72, yDeck - 32]],
    [[x + w - 22, yTop + 30], [x + w * 0.74, yTop + 56], [x + w - 18, yDeck - 34]]
  ];
  for (let f of folds) {
    brush.set("charcoal", cfg.darkCol, 0.65);
    brush.spline(f, 0.5);
    brush.set("needle", cfg.lightCol, 0.65);
    brush.spline(f.map(p => [p[0] + 1.5, p[1] - 1.5]), 0.5);
  }

  // --- Curved Heavy-Duty Zipper Track with Individual Glint Teeth ---
  let zipPts = [
    [x + 14, yTop + h * 0.38],
    [x + w * 0.32, yTop + h * 0.26],
    [x + w * 0.68, yTop + h * 0.28],
    [x + w - 14, yTop + h * 0.40]
  ];
  brush.set("reed", PAL.blackDeep, 1.3);
  brush.spline(zipPts, 0.4);

  // Draw individual metallic zipper teeth along the curved track
  let steps = 38;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let zx = lerp(x + 16, x + w - 16, t);
    let arch = sin(t * 180) * 14;
    let zy = yTop + h * 0.39 - arch;
    brush.set("needle", PAL.gypsumPure, 0.85);
    brush.line(zx, zy - 2.5, zx, zy + 2.5);
    brush.set("needle", PAL.blackDeep, 0.55);
    brush.line(zx + 1.4, zy - 2.2, zx + 1.4, zy + 2.2);
  }

  // Zipper pull cord & metal slider in center
  let pullX = x + w * 0.54;
  let pullY = yTop + h * 0.26;
  resetState();
  brush.wash(PAL.gypsumWhite, 235);
  brush.rect(pullX - 4, pullY - 3, 9, 6);
  resetState();
  brush.set("rotring", PAL.ochreRed, 0.85);
  brush.line(pullX + 2, pullY + 2, pullX + 10, pullY + 16);
  brush.circle(pullX + 10, pullY + 16, 2.2);

  // --- Twin Heavy Woven Webbing Straps & Box-X Stitching ---
  const strapXs = [x + w * 0.27, x + w * 0.71];
  let sw = 16;
  for (let sx of strapXs) {
    resetState();
    brush.wash(cfg.strapCol, 235);
    brush.rect(sx, yTop + 4, sw, h - 6);
    resetState();

    // Ribbed webbing lines & Box-X reinforcement stitch square
    brush.set("rotring", PAL.blackDeep, 0.65);
    brush.rect(sx, yTop + 4, sw, h - 6);
    brush.set("needle", PAL.gypsumPure, 0.65);
    let boxY = yTop + h * 0.48;
    brush.rect(sx + 2, boxY, sw - 4, 16);
    brush.line(sx + 2, boxY, sx + sw - 2, boxY + 16);
    brush.line(sx + sw - 2, boxY, sx + 2, boxY + 16);
  }

  // Arched top haul handle connecting the two straps
  resetState();
  brush.set("reed", cfg.strapCol, 1.8);
  brush.spline([
    [strapXs[0] + sw * 0.5, yTop + 6],
    [x + w * 0.5, yTop - 16],
    [strapXs[1] + sw * 0.5, yTop + 6]
  ], 0.5);
  brush.set("rotring", PAL.blackDeep, 0.65);
  brush.spline([
    [strapXs[0] + sw * 0.5, yTop + 4],
    [x + w * 0.5, yTop - 18],
    [strapXs[1] + sw * 0.5, yTop + 4]
  ], 0.5);

  // End metal D-rings and trailing shoulder strap loop resting on the conveyor belt
  for (let ex of [x + 8, x + w - 8]) {
    brush.set("rotring", PAL.gypsumPure, 0.95);
    brush.circle(ex, yTop + h * 0.44, 5);
    brush.set("rotring", PAL.blackDeep, 0.5);
    brush.circle(ex, yTop + h * 0.44, 6.2);
  }
  // Slack shoulder strap curving down onto the right side of the conveyor
  brush.set("reed", cfg.strapCol, 1.3);
  brush.spline([
    [x + w - 8, yTop + h * 0.46],
    [x + w + 8, yDeck - 18],
    [x + w - 18, yDeck - 2],
    [x + w * 0.78, yDeck - 6]
  ], 0.5);

  // Peeling inspection sticker on canvas flank
  drawPeelingSticker(x + w * 0.41, yTop + h * 0.54, 34, 20, PAL.gypsumWhite, "barcode");

  // Outer contour reinforcement
  resetState();
  brush.set("rotring", PAL.blackDeep, 0.85);
  polyShape(bodyPts, 0.22, true);

  // Tangled luggage tag tied to the right strap/handle junction
  drawTangledLuggageTag(strapXs[1] + sw * 0.5, yTop + 10, cfg.tagColor, cfg.seed);
}

// ============================================================================
// 8. HYPERREAL OBJECT 3: FOLDING PRAM / STROLLER IN STRICT SIDE PROFILE
// ============================================================================
function drawPram(x, yDeck, w, h, cfg) {
  // Pram marches left-to-right: push handlebar on top-left, canopy & footrest on right
  let rearWX = x + 48;
  let rearWR = 24;
  let rearWY = yDeck - rearWR;

  let frontWX = x + w - 34;
  let frontWR = 17;
  let frontWY = yDeck - frontWR;

  let handleX = x + 6;
  let handleY = yDeck - h + 16;

  let hingeX = x + w * 0.48;
  let hingeY = yDeck - h * 0.48;

  let footX = x + w - 14;
  let footY = yDeck - 52;

  drawContactShadow(rearWX - 22, yDeck, (frontWX - rearWX) + 42);

  // --- 1. Undercarriage Mesh Storage Basket ---
  let basketPts = [
    [rearWX + 12, rearWY - 8],
    [frontWX - 14, frontWY - 8],
    [frontWX - 22, hingeY + 26],
    [rearWX + 6, hingeY + 22]
  ];
  resetState();
  brush.wash(PAL.blackSlate, 195);
  polyShape(basketPts, 0.08, true);
  resetState();
  brush.hatchStyle("needle", PAL.gypsumCream, 0.5);
  brush.hatch(5, 42, { rand: 0.05 });
  polyShape(basketPts, 0.08, true);
  resetState();
  // Tucked rolled ochre blanket inside undercarriage basket
  brush.wash(PAL.ochreWarm, 215);
  brush.circle(rearWX + 42, rearWY - 18, 12, 0.2);
  resetState();
  brush.set("rotring", PAL.blackDeep, 0.65);
  polyShape(basketPts, 0.08, true);

  // --- 2. Seat Unit & Padded Backrest (strict side profile facing right) ---
  let seatPts = [
    [hingeX - 24, handleY + 38],
    [hingeX + 4, hingeY + 12],
    [footX - 6, hingeY + 14],
    [footX, footY],
    [footX - 12, footY + 4],
    [footX - 18, hingeY + 24],
    [hingeX - 8, hingeY + 22],
    [hingeX - 36, handleY + 44]
  ];
  resetState();
  brush.wash(cfg.seatCol, 235);
  polyShape(seatPts, 0.12, true);
  resetState();
  brush.set("rotring", PAL.blackDeep, 0.75);
  polyShape(seatPts, 0.12, true);

  // Quilted seat stitching & dangling 5-point harness buckle
  brush.set("reed", cfg.accentCol, 0.9);
  brush.line(hingeX - 6, hingeY - 12, hingeX + 14, hingeY + 12);
  brush.line(hingeX + 14, hingeY + 12, hingeX + 10, hingeY + 34);
  brush.set("rotring", PAL.gypsumPure, 0.8);
  brush.circle(hingeX + 14, hingeY + 12, 3.2);

  // --- 3. Pleated Folding Sun Canopy (radial ribs fan out from central hinge) ---
  let cPivotX = hingeX + 8;
  let cPivotY = hingeY - 14;
  let cRadius = 86;
  // Canopy angles from 225 deg (top-left) to 345 deg (front-right)
  let cPts = [[cPivotX, cPivotY]];
  for (let a = 222; a <= 346; a += 15) {
    let rad = cRadius + (a % 30 === 0 ? 3 : -2);
    cPts.push([cPivotX + cos(a) * rad, cPivotY + sin(a) * rad]);
  }
  resetState();
  brush.wash(cfg.canopyCol, 230);
  polyShape(cPts, 0.12, true);

  brush.fillBleed(0.12, "in");
  brush.fill(cfg.canopyDark, 90);
  polyShape(cPts, 0.12, true);
  resetState();

  // Radial canopy tension ribs & fabric pleat highlights
  for (let a = 240; a <= 330; a += 22.5) {
    let rx = cPivotX + cos(a) * cRadius;
    let ry = cPivotY + sin(a) * cRadius;
    brush.set("rotring", PAL.blackDeep, 0.6);
    brush.line(cPivotX, cPivotY, rx, ry);
    brush.set("needle", PAL.gypsumWhite, 0.65);
    brush.line(cPivotX, cPivotY, rx - 1.5, ry - 1.5);
  }
  // Outer canopy contour & peek-a-boo mesh window flap
  brush.set("rotring", PAL.blackDeep, 0.85);
  polyShape(cPts, 0.12, true);

  // --- 4. Articulated Aluminum Frame Tubes & Mechanical Scissor Joints ---
  // Main diagonal push-bar from handlebar (top-left) down to rear wheel & front wheel
  drawFrameTube(handleX, handleY, rearWX, rearWY, 6.5, cfg.frameCol);
  drawFrameTube(hingeX, hingeY, frontWX, frontWY - 12, 6.5, cfg.frameCol);
  drawFrameTube(handleX + 18, handleY + 26, footX - 4, footY - 4, 5.5, cfg.frameCol);
  drawFrameTube(rearWX, rearWY, frontWX - 8, frontWY - 10, 5.0, PAL.blackCarbon);

  // Foam/Leatherette Push Handlebar Grip at top-left
  drawFrameTube(handleX - 4, handleY - 8, handleX + 16, handleY + 22, 8.5, cfg.accentCol);
  // Grip texture ticks
  brush.set("needle", PAL.blackDeep, 0.65);
  for (let t = 0; t <= 1; t += 0.2) {
    let gx = lerp(handleX - 4, handleX + 16, t);
    let gy = lerp(handleY - 8, handleY + 22, t);
    brush.line(gx - 3, gy + 2, gx + 3, gy - 2);
  }

  // Mechanical circular folding hinge hubs with silver rivets
  for (let jp of [[hingeX, hingeY], [cPivotX, cPivotY], [footX - 6, footY - 4]]) {
    resetState();
    brush.wash(PAL.blackDeep, 240);
    brush.circle(jp[0], jp[1], 7.5);
    resetState();
    brush.set("rotring", PAL.gypsumPure, 0.85);
    brush.circle(jp[0], jp[1], 7.5);
    brush.circle(jp[0], jp[1], 2.2);
  }

  // --- 5. Rear Spoked Wheel & Front Swivel Suspension Wheel ---
  // Rear wheel
  drawPramWheel(rearWX, rearWY, rearWR, cfg.accentCol, true);
  // Front swivel caster fork + spring suspension coil
  brush.set("rotring", PAL.blackDeep, 0.8);
  for (let sy = frontWY - 22; sy < frontWY - 10; sy += 2.5) {
    brush.line(frontWX - 4, sy, frontWX + 4, sy + 1.2);
  }
  drawPramWheel(frontWX, frontWY, frontWR, cfg.accentCol, false);

  // --- 6. Tangled Gate-Check Airline Tag Fluttering from Handlebar ---
  drawTangledLuggageTag(handleX + 8, handleY + 12, cfg.tagColor, cfg.seed);
}

function drawFrameTube(x1, y1, x2, y2, thickness, col) {
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang) * (thickness * 0.5);
  let ny = cos(ang) * (thickness * 0.5);
  let pts = [
    [x1 + nx, y1 + ny],
    [x2 + nx, y2 + ny],
    [x2 - nx, y2 - ny],
    [x1 - nx, y1 - ny]
  ];
  resetState();
  brush.wash(col, 240);
  polyShape(pts, 0, true);
  resetState();
  brush.set("rotring", PAL.blackDeep, 0.65);
  polyShape(pts, 0, true);
  brush.set("needle", PAL.gypsumPure, 0.75);
  brush.line(x1 + nx * 0.4, y1 + ny * 0.4, x2 + nx * 0.4, y2 + ny * 0.4);
}

function drawPramWheel(wx, wy, r, hubCol, hasBrake) {
  resetState();
  // Outer molded rubber tire
  brush.wash(PAL.blackDeep, 245);
  brush.circle(wx, wy, r);
  // Inner rim in gypsum white
  brush.wash(PAL.gypsumWhite, 235);
  brush.circle(wx, wy, r * 0.68);
  // Core cutout
  brush.wash(PAL.plasterBase, 225);
  brush.circle(wx, wy, r * 0.50);
  resetState();

  // Molded 5-spoke star
  for (let a = 0; a < 360; a += 72) {
    let sx = wx + cos(a) * (r * 0.58);
    let sy = wy + sin(a) * (r * 0.58);
    brush.set("reed", PAL.gypsumWhite, 1.1);
    brush.line(wx, wy, sx, sy);
    brush.set("rotring", PAL.blackDeep, 0.55);
    brush.line(wx, wy, sx, sy);
  }

  // Tire tread notches & concentric circles
  brush.set("rotring", PAL.blackDeep, 0.85);
  brush.circle(wx, wy, r);
  brush.circle(wx, wy, r * 0.68);
  brush.set("needle", PAL.gypsumPure, 0.75);
  brush.arc(wx, wy, r * 0.86, 200, 330);

  // Center axle cap
  resetState();
  brush.wash(hubCol, 240);
  brush.circle(wx, wy, r * 0.24);
  resetState();
  brush.set("rotring", PAL.blackDeep, 0.65);
  brush.circle(wx, wy, r * 0.24);

  // Red Ochre foot-brake pedal on rear wheel
  if (hasBrake) {
    resetState();
    brush.wash(PAL.ochreRed, 240);
    brush.rect(wx - 16, wy - 4, 14, 6);
    resetState();
    brush.set("rotring", PAL.blackDeep, 0.6);
    brush.rect(wx - 16, wy - 4, 14, 6);
  }
}

// ============================================================================
// 9. HYPERREAL OBJECT 4: CORRUGATED CARDBOARD BOX IN STRICT SIDE PROFILE
// ============================================================================
function drawCardboardBox(x, yDeck, w, h, cfg) {
  let yTop = yDeck - h;

  drawContactShadow(x + 4, yDeck, w - 8);

  // Slightly dented/crushed upper corner for hyperreal physical weight
  let crushDX = cfg.crushRight ? 10 : 0;
  let crushDY = cfg.crushRight ? 9 : 0;
  let leftDY = !cfg.crushRight ? 7 : 0;

  let boxPts = [
    [x, yTop + leftDY],
    [x + 24, yTop],
    [x + w - 26, yTop],
    [x + w - crushDX * 0.3, yTop + crushDY],
    [x + w, yTop + 34],
    [x + w - 2, yDeck - 2],
    [x + 2, yDeck - 2],
    [x - 1, yTop + h * 0.45]
  ];

  resetState();
  // Warm kraft ochre base wash + cool shadow bleed
  brush.wash(cfg.boxCol, 230);
  polyShape(boxPts, 0.04, true);

  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.6, 0.45);
  brush.fill(cfg.darkCol, 75);
  polyShape(boxPts, 0.04, true);
  resetState();

  // Horizontal corrugated kraft board striations
  brush.hatchStyle("2H", cfg.darkCol, 0.38);
  brush.hatch(4.5, 0, { rand: 0.05 });
  polyShape(boxPts, 0.04, true);
  resetState();

  // Diagonal crush-crease lines near the dented corner
  if (cfg.crushRight) {
    brush.set("cpencil", cfg.darkCol, 0.75);
    brush.line(x + w - 34, yTop + 2, x + w - 2, yTop + 32);
    brush.line(x + w - 46, yTop + 4, x + w - 4, yTop + 46);
    brush.set("needle", cfg.lightCol, 0.75);
    brush.line(x + w - 33, yTop + 4, x + w - 2, yTop + 34);
  } else {
    brush.set("cpencil", cfg.darkCol, 0.75);
    brush.line(x + 2, yTop + 28, x + 32, yTop + 2);
    brush.set("needle", cfg.lightCol, 0.75);
    brush.line(x + 3, yTop + 30, x + 34, yTop + 4);
  }

  // --- Exposed Corrugated Flute Wave Edge along Top Flap Seam ---
  let seamY = yTop + 14;
  resetState();
  brush.wash(cfg.darkCol, 195);
  brush.rect(x + 6, seamY - 2.5, w - 14, 5);
  resetState();
  // Tiny sinusoidal wave flutes (`~~~`) inside the cardboard edge
  brush.set("needle", PAL.gypsumCream, 0.75);
  for (let fx = x + 8; fx < x + w - 12; fx += 4.5) {
    brush.line(fx, seamY - 2, fx + 2.2, seamY + 2);
    brush.line(fx + 2.2, seamY + 2, fx + 4.5, seamY - 2);
  }

  // --- Peeling Packing Tape Strip across Top Seam & Down Flank ---
  resetState();
  brush.wash(PAL.gypsumCream, 155);
  brush.rect(x + 4, yTop + 2, w - 12, 11);
  // Vertical tape flap peeling off at the right side
  let peelX = x + w - 18;
  let peelY = yTop + 12;
  // Shadow of curled tape
  brush.set("rotring", PAL.blackDeep, 0.55);
  brush.line(peelX + 12, peelY, peelX + 18, peelY + 34);
  // Curled tape ribbon
  let tapePeelPts = [
    [peelX, peelY],
    [peelX + 14, peelY],
    [peelX + 26, peelY + 32],
