  brush.rect(bandX, yTop - 1, 7, h + 1);
  brush.rect(bandX - 1.5, yTop + h * 0.65, 10, 14);

  // Outer cardboard box contour & bottom conveyor scuff marks
  drawPolycarbonateScuffs(x + 10, yDeck - 34, w - 20, 28, cfg.seed);
