function drawPeelingSticker(x, y, w, h, col, type) {
  let curl = 10;

  resetState();
  // Cast micro-shadow underneath the curling top-right corner
  brush.wash(PAL.blackDeep, 175);
  polyShape([
    [x + w - curl, y + 2],
    [x + w + 2, y + 2],
    [x + w + 2, y + curl + 4],
    [x + w - curl - 2, y + curl + 2]
  ], 0, true);

  // Main flat adhered portion of sticker
  let flatPts = [
    [x, y],
    [x + w - curl, y],
    [x + w, y + curl],
    [x + w, y + h],
    [x, y + h]
  ];
  brush.wash(col, 235);
  polyShape(flatPts, 0, true);
  resetState();

  // Sticker graphic content (IATA barcode lines, scarab badge, or lotus emblem)
  if (type === "barcode") {
    // Red ochre header strip
    brush.wash(PAL.ochreRed, 220);
    brush.rect(x + 2, y + 2, w - curl - 4, 4);
    resetState();
    // Crisp vertical barcode bars
    for (let bx = x + 4; bx < x + w - 5; bx += 2.6) {
      let bw = ((int(bx) % 3 === 0) ? 0.85 : 0.45);
      brush.set("rotring", PAL.blackDeep, bw);
      brush.line(bx, y + 8, bx, y + h - 4);
    }
  } else if (type === "scarab") {
    brush.set("rotring", PAL.gypsumPure, 0.65);
    brush.circle(x + w * 0.45, y + h * 0.52, 5.5);
    brush.line(x + 4, y + h * 0.52, x + w - 8, y + h * 0.52);
  } else {
    brush.set("rotring", PAL.gypsumPure, 0.65);
    brush.arc(x + w * 0.45, y + h * 0.7, 7, 200, 340);
    brush.line(x + w * 0.45, y + 4, x + w * 0.45, y + h - 4);
  }

  // Border of flat sticker
  brush.set("rotring", PAL.blackDeep, 0.55);
  polyShape(flatPts, 0, true);

  // Peeling folded-back triangular paper underside in bright gypsum white
  let curlPts = [
    [x + w - curl, y],
    [x + w, y + curl],
    [x + w - curl - 3, y + curl + 3]
  ];
  resetState();
  brush.wash(PAL.gypsumPure, 250);
  polyShape(curlPts, 0, true);
  resetState();
  brush.set("rotring", PAL.blackDeep, 0.55);
  polyShape(curlPts, 0, true);
}

function drawTangledLuggageTag(anchorX, anchorY, tagCol, seed) {
  let dir = (seed % 2 === 0) ? 1 : -1;
  let tagX = anchorX + dir * 16;
  let tagY = anchorY + 26;

  resetState();
