    [anchorX + dir * 13, anchorY + 9],
    [anchorX - dir * 5, anchorY + 18],
    [tagX + 5, tagY + 2]
  ], 0.6);

  // Second tangled loop strand
  brush.set("needle", PAL.gypsumPure, 0.7);
  brush.spline([
    [anchorX, anchorY],
    [anchorX - dir * 8, anchorY + 11],
    [anchorX + dir * 12, anchorY + 20],
    [tagX + 5, tagY + 2]
  ], 0.6);

  // Secondary twisted paper barcode ribbon underneath
  let ribPts = [
