  brush.wash(PAL.gypsumCream, 235);
  polyShape(ribPts, 0.05, true);
  resetState();
  brush.set("rotring", PAL.blackDeep, 0.5);
  polyShape(ribPts, 0.05, true);

  // Primary Hanging Keyhole Luggage Tag
  let tagPts = [
    [tagX, tagY],
    [tagX + 11, tagY - 2],
    [tagX + 18, tagY + 28],
    [tagX + 3, tagY + 31],
    [tagX - 3, tagY + 6]
  ];
  resetState();
