  brush.wash(PAL.blackDeep, 140);
  polyShape(tagPts.map(p => [p[0] + 2.5, p[1] + 2.5]), 0.04, true);

  // Tag body fill
  brush.wash(tagCol, 240);
  polyShape(tagPts, 0.04, true);
  // White barcode insert on lower half of tag
  brush.wash(PAL.gypsumPure, 235);
  polyShape([
    [tagX, tagY + 11],
    [tagX + 13, tagY + 9],
    [tagX + 16, tagY + 25],
    [tagX + 3, tagY + 27]
  ], 0, true);
  resetState();

  // Tiny barcode lines & brass grommet hole on the tag
  brush.set("rotring", PAL.blackDeep, 0.55);
  polyShape(tagPts, 0.04, true);
  brush.circle(tagX + 5, tagY + 3, 1.8);
  for (let i = 0; i < 4; i++) {
    let ly = tagY + 13 + i * 3;
    brush.line(tagX + 3, ly, tagX + 12, ly - 1);
  }
}

