// Hyperrealist Isometric Sidewalk Slab — Fine Pen Stippling over Transparent Watercolour Glazes

const SLAB_R = 270;
const SLAB_H = 228;
const CX = 600;
const CY = 492;

// Light & shadow vector in (u, v) per unit of height z
// Light comes from upper back-left; shadows fall along the isometric diagonal (+u, -v)
const SH_U = 1.04;
const SH_V = -0.28;

// Hydrant position in (u, v)
const HYD_U = -88;
const HYD_V = 18;

// Cool palette constants
const PAL = {
  bg: "#EAE4F2",
  // Concrete top
  concBase: "#CFD4E2",
  concLight: "#E2E6F2",
  concMid: "#B8C0D4",
  concDamp: "#8E98B0",
  concDark: "#6A738B",
  // Cut strata - Concrete
  concSideL: "#ADB5C9",
  concSideR: "#747D94",
  // Cut strata - Gravel
  gravBaseL: "#7C859B",
  gravBaseR: "#4A5266",
  gravDark: "#242A3A",
  // Cut strata - Soil
  soilTopL: "#43394D",
  soilTopR: "#292233",
  soilBotL: "#584C63",
  soilBotR: "#342B3F",
  // Cast shadows
  shadowWash: "#565E78",
  shadowCore: "#363D52",
  // Hydrant (cool weathered crimson-alizarin + zinc primer + slate iron)
  hydLight: "#C24660",
  hydMid: "#942942",
  hydDark: "#581628",
  hydRefl: "#7A354C",
  primer: "#C8D4E6",
  ironLight: "#5C677D",
  ironDark: "#252C3B",
  ironRust: "#6E4544",
  // Moss
  mossDark: "#1B3B32",
  mossMid: "#346B57",
  mossLight: "#689E82",
  mossTip: "#9AC4A6",
  // Leaves (cool wet autumn: slate-olive, plum-umber, dusty ochre)
  leaf1: "#686856",
  leaf2: "#6C525C",
  leaf3: "#7C7662",
  // Gum blot
  gumBase: "#C7A4BA",
