  inkMid: "#4E576E",
  inkLight: "#7C869E",
  white: "#F4F7FC"
};

// Project isometric (u, v, z) to screen (x, y)
function iso(u, v, z = 0) {
  const cos30 = 0.8660254;
  const sin30 = 0.5;
  return [
    CX + (u - v) * cos30,
    CY + (u + v) * sin30 - z
  ];
}

// Helper for drawing a filled polygon with brush.beginShape
function drawPoly(pts, curv = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Helper for drawing an open or closed polyline with brush.spline or brush.line
function strokePoly(pts, closed = true) {
  if (!pts || pts.length < 2) return;
  for (let i = 0; i < pts.length - (closed ? 0 : 1); i++) {
    const a = pts[i];
    const b = pts[(i + 1) % pts.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }
}

// Helper for a single pen stipple dot
function stippleDot(x, y, len = 1.1, ang = 35) {
  const rad = ang * Math.PI / 180;
  const dx = Math.cos(rad) * len * 0.5;
  const dy = Math.sin(rad) * len * 0.5;
  brush.line(x - dx, y - dy, x + dx, y + dy);
}

// Point on hydrant cylinder at (u0, v0, z) with radius r and screen angle phiDeg
// phiDeg = 0 is right silhouette, 90 is front center, 180 is left silhouette
function cylPt(u0, v0, z, r, phiDeg) {
  const c = iso(u0, v0, z);
  const rad = phiDeg * Math.PI / 180;
  const a = r * 1.224745;
  const b = r * 0.707107;
  return [
    c[0] + a * Math.cos(rad),
    c[1] + b * Math.sin(rad)
  ];
}

// Boundary interface curves for strata along u or v in [-SLAB_R, SLAB_R]
function zConcreteBottom(t) {
  // t in [-270, 270]
  return -56 + 2.8 * Math.sin(t * 0.035) + 1.6 * Math.cos(t * 0.09);
}

function zGravelBottom(t) {
  return -126 + 4.5 * Math.cos(t * 0.025 + 0.8) + 2.5 * Math.sin(t * 0.07);
}

function zSoilMid(t) {
  return -168 + 5.0 * Math.sin(t * 0.02 + 1.4) + 2.0 * Math.cos(t * 0.06);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(8812);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.bg);
  brush.noField();

  // 1. Base Slab Washes (Top, Left Cut Face, Right Cut Face)
  drawSlabBaseWashes();

  // 2. Top Surface Concrete Watercolour Glazes, Broom Texture & Expansion Joints
  drawTopConcreteSurface();

  // 3. Isometric Cast Shadows on the Sidewalk (Hydrant, Leaves, Cap, Moss)
  drawAllCastShadows();

  // 4. Cut Sides: Concrete, Gravel & Soil Strata (Watercolour + Aggregate + Stippling)
  drawCutStrata();

  // 5. Hairline Crack & Sprouting Moss (Top & Front-Left Cut Edge)
  drawCrackAndMoss();

  // 6. Flattened Gum Blot
  drawGumBlot(118, 128);

  // 7. Three Wet Plane-Tree Leaves
  drawWetLeaves();

  // 8. Bottle Cap
  drawBottleCap(-158, 108);

  // 9. Razor-Straight Outer Margin Mask & Crisp Architectural Slab Edges
  enforceRazorEdges();

  // 10. Paint-Chipped Fire Hydrant (Rendered on top so its 3D mass rises cleanly above the slab)
  drawFireHydrant(HYD_U, HYD_V);

  noLoop();
}

// =============================================================================
// 1. SLAB BASE WASHES
// =============================================================================
function drawSlabBaseWashes() {
  const N = iso(-SLAB_R, -SLAB_R, 0);
  const E = iso(SLAB_R, -SLAB_R, 0);
  const S = iso(SLAB_R, SLAB_R, 0);
  const W = iso(-SLAB_R, SLAB_R, 0);
  const Wb = iso(-SLAB_R, SLAB_R, -SLAB_H);
  const Sb = iso(SLAB_R, SLAB_R, -SLAB_H);
  const Eb = iso(SLAB_R, -SLAB_R, -SLAB_H);

  brush.noStroke();
  brush.noFill();

  // Top face solid base wash
  brush.wash(PAL.concBase, 240);
  drawPoly([N, E, S, W]);

  // Left cut face base wash
  brush.wash(PAL.concSideL, 245);
  drawPoly([W, S, Sb, Wb]);

  // Right cut face base wash
  brush.wash(PAL.concSideR, 245);
  drawPoly([S, E, Eb, Sb]);

  brush.noWash();
}

// =============================================================================
// 2. TOP CONCRETE SURFACE GLAZES, JOINTS & STIPPLING
// =============================================================================
function drawTopConcreteSurface() {
  brush.noStroke();
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.55, 0.35);

  // Main sidewalk flags defined by expansion joints at u = 58 and v = -105 (for u < 58)
  const jU = 58;
  const jV = -105;

  // Glaze 1: Back-left flag (u in [-266, 56], v in [-266, -107])
  brush.fill(PAL.concLight, 95);
  drawPoly([
    iso(-265, -265, 0),
    iso(jU - 3, -265, 0),
    iso(jU - 3, jV - 3, 0),
    iso(-265, jV - 3, 0)
  ]);

  // Glaze 2: Front-left main flag (u in [-265, 55], v in [-102, 265])
  brush.fill(PAL.concMid, 80);
  drawPoly([
    iso(-265, jV + 3, 0),
    iso(jU - 3, jV + 3, 0),
    iso(jU - 3, 265, 0),
    iso(-265, 265, 0)
  ]);

  // Glaze 3: Right flag (u in [61, 265], v in [-265, 265])
  brush.fill(PAL.concMid, 105);
  drawPoly([
    iso(jU + 3, -265, 0),
    iso(265, -265, 0),
    iso(265, 265, 0),
    iso(jU + 3, 265, 0)
  ]);

  // Damp watercolor blotches around hydrant base, crack, and leaves
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.45);
  brush.fill(PAL.concDamp, 85);

  // Damp patch around hydrant
  const dampHyd = [];
  for (let a = 0; a < 360; a += 30) {
    const r = 68 + 18 * noise(a * 0.1, 1.2);
    dampHyd.push(iso(HYD_U + r * cos(a), HYD_V + r * sin(a), 0));
  }
  drawPoly(dampHyd, 0.3);

  // Damp patch around the three wet leaves
  const dampLeaves = [
    iso(-35, -145, 0), iso(55, -155, 0), iso(195, -55, 0),
    iso(175, 55, 0), iso(65, 48, 0), iso(-45, -75, 0)
  ];
  drawPoly(dampLeaves, 0.35);

  // Damp stain along the hairline crack
  const dampCrack = [
    iso(-215, 148, 0), iso(-60, 170, 0), iso(115, 255, 0),
    iso(90, 266, 0), iso(-70, 202, 0), iso(-220, 172, 0)
  ];
  drawPoly(dampCrack, 0.25);

  // Subtle cool violet-grey clouding near corners
  brush.fill(PAL.concDark, 42);
  drawPoly([
    iso(120, 180, 0), iso(264, 150, 0), iso(264, 264, 0), iso(80, 264, 0)
  ]);
  drawPoly([
    iso(-264, -264, 0), iso(-140, -264, 0), iso(-190, -160, 0), iso(-264, -140, 0)
  ]);

  brush.noFill();

  // Broom-finish micro-striations across the concrete flags (parallel to u axis)
  brush.set("2H", PAL.inkLight, 0.22);
  for (let v = -262; v <= 262; v += 4.5) {
    if (abs(v - jV) < 3.5) continue;
    const segs = 5;
    for (let s = 0; s < segs; s++) {
      let u1 = map(s, 0, segs, -264, 264) + random(-8, 8);
      let u2 = u1 + random(35, 78);
      u1 = constrain(u1, -265, 265);
      u2 = constrain(u2, -265, 265);
      if (u1 < jU && u2 > jU) u2 = jU - 3;
      if (u2 - u1 > 8 && random() < 0.75) {
        const p1 = iso(u1, v, 0);
        const p2 = iso(u2, v, 0);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  // Expansion Joint 1: u = 58, from v = -270 to v = +270
  drawExpansionJointU(jU, -270, 270);
  // Expansion Joint 2: v = -105, from u = -270 to u = 58
  drawExpansionJointV(jV, -270, jU);

  // Fine pen stippling & tiny surface aggregate pits across the top concrete
  for (let i = 0; i < 1650; i++) {
    const u = random(-266, 266);
    const v = random(-266, 266);
    const p = iso(u, v, 0);
    const n = noise(u * 0.018, v * 0.018);
    if (random() < 0.25) {
      brush.set("rotring", PAL.white, 0.24);
      stippleDot(p[0], p[1], 0.9, 30);
    } else if (n > 0.52) {
      brush.set("rotring", PAL.inkDark, 0.24);
      stippleDot(p[0], p[1], 1.0, random(180));
    } else {
      brush.set("rotring", PAL.inkMid, 0.2);
      stippleDot(p[0], p[1], 0.85, random(180));
    }
  }
}

function drawExpansionJointU(u0, vStart, vEnd) {
  // Dark tar/bitumen filler strip between concrete flags
  const steps = 28;
  brush.set("rotring", PAL.inkBlack, 0.55);
  for (let i = 0; i < steps; i++) {
    const v1 = map(i, 0, steps, vStart, vEnd);
    const v2 = map(i + 1, 0, steps, vStart, vEnd);
    const j1 = 0.6 * sin(v1 * 0.2);
    const j2 = 0.6 * sin(v2 * 0.2);
    const a1 = iso(u0 - 1.6 + j1, v1, 0);
    const a2 = iso(u0 - 1.6 + j2, v2, 0);
    const b1 = iso(u0 + 1.6 + j1, v1, 0);
    const b2 = iso(u0 + 1.6 + j2, v2, 0);
    brush.set("rotring", PAL.inkBlack, 0.5);
    brush.line(a1[0], a1[1], a2[0], a2[1]);
    brush.set("rotring", PAL.inkDark, 0.35);
    brush.line(b1[0], b1[1], b2[0], b2[1]);
    // Highlight lip on right side of joint
    brush.set("rotring", PAL.white, 0.35);
    const h1 = iso(u0 + 2.8 + j1, v1, 0);
    const h2 = iso(u0 + 2.8 + j2, v2, 0);
    brush.line(h1[0], h1[1], h2[0], h2[1]);
  }
}

function drawExpansionJointV(v0, uStart, uEnd) {
  const steps = 18;
  for (let i = 0; i < steps; i++) {
    const u1 = map(i, 0, steps, uStart, uEnd);
    const u2 = map(i + 1, 0, steps, uStart, uEnd);
    const j1 = 0.5 * cos(u1 * 0.2);
    const j2 = 0.5 * cos(u2 * 0.2);
    const a1 = iso(u1, v0 - 1.4 + j1, 0);
    const a2 = iso(u2, v0 - 1.4 + j2, 0);
    const b1 = iso(u1, v0 + 1.4 + j1, 0);
    const b2 = iso(u2, v0 + 1.4 + j2, 0);
    brush.set("rotring", PAL.inkBlack, 0.48);
    brush.line(a1[0], a1[1], a2[0], a2[1]);
    brush.set("rotring", PAL.inkDark, 0.32);
    brush.line(b1[0], b1[1], b2[0], b2[1]);
    brush.set("rotring", PAL.white, 0.32);
    const h1 = iso(u1, v0 + 2.5 + j1, 0);
    const h2 = iso(u2, v0 + 2.5 + j2, 0);
    brush.line(h1[0], h1[1], h2[0], h2[1]);
  }
}

// =============================================================================
// 3. ISOMETRIC CAST SHADOWS
// =============================================================================
function shadowPt(u, v, z) {
  const su = constrain(u + z * SH_U, -SLAB_R, SLAB_R);
  const sv = constrain(v + z * SH_V, -SLAB_R, SLAB_R);
  return iso(su, sv, 0);
}

function drawAllCastShadows() {
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.45, 0.4);

  // Build projected silhouette of the fire hydrant onto z = 0 along (SH_U, SH_V)
  const hydShadow = [];
  // Left base tangent to bonnet
  const profSteps = [
    [0, 50], [16, 50], [20, 40], [100, 43], [138, 44], [145, 51],
    [154, 48], [175, 43], [195, 32], [205, 16], [220, 12]
  ];
  // Upper-left edge of shadow (corresponding to -v / back side of hydrant)
  for (let i = 0; i < profSteps.length; i++) {
    const [z, r] = profSteps[i];
    hydShadow.push(shadowPt(HYD_U - r * 0.25, HYD_V - r * 0.96, z));
  }
  // Tip of pentagon nut
  hydShadow.push(shadowPt(HYD_U + 8, HYD_V, 224));
  // Lower-right edge of shadow (corresponding to +v / front side of hydrant)
  for (let i = profSteps.length - 1; i >= 0; i--) {
    const [z, r] = profSteps[i];
    // Include pumper nozzle bulge around z = 95..125 on the +v side
    let extraV = 0;
    let extraU = 0;
    if (z >= 95 && z <= 135) {
      extraV = 36;
      extraU = 6;
    }
    hydShadow.push(shadowPt(HYD_U + r * 0.25 + extraU, HYD_V + r * 0.96 + extraV, z));
  }

  // Outer soft watercolor shadow glaze
  brush.fill(PAL.shadowWash, 120);
  drawPoly(hydShadow, 0.15);

  // Side nozzle shadow lobes
  const rightNozShadow = [
    shadowPt(HYD_U + 25, HYD_V - 18, 96),
    shadowPt(HYD_U + 66, HYD_V - 16, 102),
    shadowPt(HYD_U + 66, HYD_V + 16, 118),
    shadowPt(HYD_U + 25, HYD_V + 18, 122)
  ];
  drawPoly(rightNozShadow, 0.15);

  const leftNozShadow = [
    shadowPt(HYD_U - 25, HYD_V - 22, 98),
    shadowPt(HYD_U - 64, HYD_V - 20, 108),
    shadowPt(HYD_U - 64, HYD_V + 12, 122),
    shadowPt(HYD_U - 25, HYD_V + 14, 124)
  ];
  drawPoly(leftNozShadow, 0.15);

  // Darker inner shadow core near the hydrant base
  brush.fill(PAL.shadowCore, 110);
  const coreShadow = [
    shadowPt(HYD_U - 10, HYD_V - 46, 0),
    shadowPt(HYD_U - 10, HYD_V - 42, 115),
    shadowPt(HYD_U + 12, HYD_V + 44, 115),
    shadowPt(HYD_U + 10, HYD_V + 46, 0)
  ];
  drawPoly(coreShadow, 0.1);

  brush.noFill();

  // Dangling chain shadow on the concrete
  brush.set("rotring", PAL.shadowCore, 0.45);
  const chS = [];
  for (let t = 0; t <= 1; t += 0.1) {
    const cu = lerp(HYD_U + 36, HYD_U + 60, t);
    const cv = lerp(HYD_V + 12, HYD_V + 6, t);
    const cz = lerp(112, 98, t) - 22 * sin(t * 180);
    chS.push(shadowPt(cu, cv, cz));
  }
  strokePoly(chS, false);

  // Fine diagonal pen hatching & stippling inside the hydrant cast shadow
  brush.set("rotring", PAL.inkDark, 0.25);
  for (let z = 6; z < 215; z += 3.2) {
    let r = 42;
    if (z < 18) r = 50;
    else if (z > 140 && z < 155) r = 49;
    else if (z >= 155) r = map(z, 155, 220, 45, 12);
    const p1 = shadowPt(HYD_U - r * 0.2, HYD_V - r * 0.9, z);
    const p2 = shadowPt(HYD_U + r * 0.2 + (z > 96 && z < 126 ? 8 : 0), HYD_V + r * 0.9 + (z > 96 && z < 126 ? 32 : 0), z);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Stipple along shadow penumbra
  for (let i = 0; i < 420; i++) {
    const z = random(4, 218);
    let r = z > 155 ? map(z, 155, 220, 45, 12) : 43;
    const f = random(-1.05, 1.08);
    const sp = shadowPt(HYD_U + f * r * 0.22, HYD_V + f * r * 0.95, z);
    brush.set("rotring", abs(f) > 0.8 ? PAL.inkMid : PAL.inkDark, 0.24);
    stippleDot(sp[0], sp[1], 1.0, 20);
  }
}

// =============================================================================
// 4. CUT SIDES: CONCRETE, GRAVEL & SOIL STRATA
// =============================================================================
function drawCutStrata() {
  const steps = 36;

  // Build boundary polylines for Left face (v = +SLAB_R, u from -SLAB_R to +SLAB_R)
  // and Right face (u = +SLAB_R, v from +SLAB_R down to -SLAB_R)
  const leftTop = [], leftConcBot = [], leftGravBot = [], leftSoilMid = [], leftBot = [];
  const rightTop = [], rightConcBot = [], rightGravBot = [], rightSoilMid = [], rightBot = [];

  for (let i = 0; i <= steps; i++) {
    const u = map(i, 0, steps, -SLAB_R, SLAB_R);
    leftTop.push(iso(u, SLAB_R, 0));
    leftConcBot.push(iso(u, SLAB_R, zConcreteBottom(u)));
    leftGravBot.push(iso(u, SLAB_R, zGravelBottom(u)));
    leftSoilMid.push(iso(u, SLAB_R, zSoilMid(u)));
    leftBot.push(iso(u, SLAB_R, -SLAB_H));

    const v = map(i, 0, steps, SLAB_R, -SLAB_R);
    rightTop.push(iso(SLAB_R, v, 0));
    rightConcBot.push(iso(SLAB_R, v, zConcreteBottom(v)));
    rightGravBot.push(iso(SLAB_R, v, zGravelBottom(v)));
    rightSoilMid.push(iso(SLAB_R, v, zSoilMid(v)));
    rightBot.push(iso(SLAB_R, v, -SLAB_H));
  }

  brush.noStroke();

  // --- A. Solid Washes for Strata Bands ---
  // Gravel band
  brush.wash(PAL.gravBaseL, 240);
  drawPoly(leftConcBot.concat([...leftGravBot].reverse()));
  brush.wash(PAL.gravBaseR, 245);
  drawPoly(rightConcBot.concat([...rightGravBot].reverse()));

  // Upper Soil (Humus/Loam) band
  brush.wash(PAL.soilTopL, 245);
  drawPoly(leftGravBot.concat([...leftSoilMid].reverse()));
  brush.wash(PAL.soilTopR, 250);
  drawPoly(rightGravBot.concat([...rightSoilMid].reverse()));

  // Lower Soil (Compacted Clay-Silt) band
  brush.wash(PAL.soilBotL, 245);
  drawPoly(leftSoilMid.concat([...leftBot].reverse()));
  brush.wash(PAL.soilBotR, 250);
  drawPoly(rightSoilMid.concat([...rightBot].reverse()));

  brush.noWash();

  // --- B. Transparent Watercolour Glazes on Cut Faces ---
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.6, 0.4);

  // Concrete cut face glazes
  brush.fill(PAL.concDark, 75);
  drawPoly(leftTop.concat([...leftConcBot].reverse()));
  brush.fill(PAL.inkDark, 85);
  drawPoly(rightTop.concat([...rightConcBot].reverse()));

  // Soil mottling glazes
  brush.fill(PAL.soilTopR, 95);
  drawPoly(leftGravBot.concat([...leftSoilMid].reverse()));
  brush.fill(PAL.inkBlack, 100);
  drawPoly(rightGravBot.concat([...rightBot].reverse()));

  brush.noFill();

  // --- C. Stratum 1 Detail: Sliced Concrete Aggregate & Air Voids ---
  drawConcreteCutDetails(true);  // Left face
  drawConcreteCutDetails(false); // Right face

  // --- D. Stratum 2 Detail: Packed Angular Gravel Stones ---
  drawGravelStratum(true);       // Left face
  drawGravelStratum(false);      // Right face

  // --- E. Stratum 3 Detail: Compacted Soil, Pebbles, Roots & Dense Stippling ---
  drawSoilStratum(true);         // Left face
  drawSoilStratum(false);        // Right face

  // --- F. Crisp Stratum Interface Lines ---
  brush.set("rotring", PAL.inkBlack, 0.42);
  strokePoly(leftConcBot, false);
  strokePoly(rightConcBot, false);
  strokePoly(leftGravBot, false);
  strokePoly(rightGravBot, false);
}

function drawConcreteCutDetails(isLeft) {
  // Sliced aggregate stones inside the poured concrete layer (z in [-54, -4])
  const count = 48;
  for (let i = 0; i < count; i++) {
    const t = map(i + random(0.15, 0.85), 0, count, -SLAB_R + 8, SLAB_R - 8);
    const zTop = -4;
    const zBot = zConcreteBottom(t) + 4;
    const z = random(zBot + 4, zTop - 4);
    const rw = random(4, 12);
    const rz = random(3, 7);

    const pts = [];
    const sides = int(random(5, 8));
    for (let s = 0; s < sides; s++) {
      const a = map(s, 0, sides, 0, 360) + random(-18, 18);
      const dt = rw * cos(a);
      const dz = rz * sin(a);
      const tt = constrain(t + dt, -SLAB_R + 2, SLAB_R - 2);
      const zz = constrain(z + dz, zBot, -2);
      pts.push(isLeft ? iso(tt, SLAB_R, zz) : iso(SLAB_R, tt, zz));
    }

    const colChoice = i % 4;
    let stoneCol = PAL.ironLight;
    if (colChoice === 0) stoneCol = isLeft ? "#646E84" : "#3E4658";
    else if (colChoice === 1) stoneCol = isLeft ? "#8E96AA" : "#5A6276";
    else if (colChoice === 2) stoneCol = isLeft ? "#D8DEEC" : "#9098AC";
    else stoneCol = isLeft ? "#444C60" : "#282E3E";

    brush.noStroke();
    brush.wash(stoneCol, 225);
    drawPoly(pts);
    brush.noWash();

    brush.set("rotring", PAL.inkDark, 0.25);
    strokePoly(pts, true);
  }

  // Expansion joint notch at u = 58 on Left face
  if (isLeft) {
    const jU = 58;
    const p1 = iso(jU, SLAB_R, 0);
    const p2 = iso(jU, SLAB_R, zConcreteBottom(jU));
    brush.set("rotring", PAL.inkBlack, 0.6);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Fine stippling & air-bubble pinholes in concrete cut face
  for (let i = 0; i < 420; i++) {
    const t = random(-SLAB_R + 2, SLAB_R - 2);
    const zb = zConcreteBottom(t);
    const z = random(zb, -1);
    const p = isLeft ? iso(t, SLAB_R, z) : iso(SLAB_R, t, z);
    brush.set("rotring", isLeft ? PAL.inkDark : PAL.inkBlack, random(0.2, 0.35));
    stippleDot(p[0], p[1], random(0.8, 1.3), 90);
  }
}

function drawGravelStratum(isLeft) {
  // Pack interlocking angular gravel stones between zConcreteBottom(t) and zGravelBottom(t)
  const cols = 38;
  const rows = 5;
  const stepT = (SLAB_R * 2) / cols;

  const gravelPaletteL = ["#5A6378", "#747E96", "#8F99B0", "#424A5E", "#AEB7CC", "#666C7E"];
  const gravelPaletteR = ["#384052", "#4B5368", "#5E677D", "#282F40", "#727B92", "#3E4454"];
  const pal = isLeft ? gravelPaletteL : gravelPaletteR;

  // Dark interstitial matrix behind stones
  for (let c = 0; c < cols; c++) {
    const tCenter = -SLAB_R + (c + 0.5) * stepT;
    const zTop = zConcreteBottom(tCenter);
    const zBot = zGravelBottom(tCenter);
    const stepZ = (zTop - zBot) / rows;

    for (let r = 0; r < rows; r++) {
      const t = constrain(tCenter + random(-stepT * 0.22, stepT * 0.22), -SLAB_R + 3, SLAB_R - 3);
      const z = zBot + (r + 0.5) * stepZ + random(-stepZ * 0.18, stepZ * 0.18);
      const radT = stepT * random(0.42, 0.58);
      const radZ = stepZ * random(0.44, 0.60);

      const pts = [];
      const nVerts = int(random(5, 7));
      for (let k = 0; k < nVerts; k++) {
        const ang = map(k, 0, nVerts, 0, 360) + random(-22, 22);
        const vt = constrain(t + radT * cos(ang), -SLAB_R + 1, SLAB_R - 1);
        const vz = constrain(z + radZ * sin(ang), zGravelBottom(vt) + 1, zConcreteBottom(vt) - 1);
        pts.push(isLeft ? iso(vt, SLAB_R, vz) : iso(SLAB_R, vt, vz));
      }

      const col = pal[(c * 7 + r * 3) % pal.length];
      brush.noStroke();
      brush.wash(col, 235);
      drawPoly(pts);
      brush.noWash();

      // Crisp dark crevice outline
      brush.set("rotring", PAL.inkBlack, 0.32);
      strokePoly(pts, true);

      // Angular facet ridge line inside larger stones
      if (pts.length >= 5 && random() < 0.65) {
        brush.set("rotring", isLeft ? PAL.white : PAL.inkLight, 0.22);
        brush.line(pts[0][0], pts[0][1], pts[2][0], pts[2][1]);
      }
    }
  }

  // Stipple gravel shadows & grit
  for (let i = 0; i < 380; i++) {
    const t = random(-SLAB_R + 2, SLAB_R - 2);
    const z = random(zGravelBottom(t), zConcreteBottom(t));
    const p = isLeft ? iso(t, SLAB_R, z) : iso(SLAB_R, t, z);
    brush.set("rotring", PAL.inkBlack, 0.28);
    stippleDot(p[0], p[1], 1.1, random(180));
  }
}

function drawSoilStratum(isLeft) {
  // Stratified fine horizontal/sub-horizontal silt lines in the soil
  for (let s = 0; s < 14; s++) {
    const zBase = map(s, 0, 14, -132, -SLAB_H + 5);
    brush.set("rotring", isLeft ? PAL.soilTopR : PAL.inkBlack, 0.26);
    for (let seg = 0; seg < 8; seg++) {
      const t1 = map(seg, 0, 8, -SLAB_R + 4, SLAB_R - 4) + random(-10, 10);
      const t2 = t1 + random(25, 58);
      if (t2 < SLAB_R - 2 && t1 > -SLAB_R + 2) {
        const z1 = constrain(zBase + 3 * sin(t1 * 0.04 + s), -SLAB_H + 2, zGravelBottom(t1) - 3);
        const z2 = constrain(zBase + 3 * sin(t2 * 0.04 + s), -SLAB_H + 2, zGravelBottom(t2) - 3);
        const p1 = isLeft ? iso(t1, SLAB_R, z1) : iso(SLAB_R, t1, z1);
        const p2 = isLeft ? iso(t2, SLAB_R, z2) : iso(SLAB_R, t2, z2);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  // Embedded soil pebbles & clay nodules
  for (let i = 0; i < 36; i++) {
    const t = random(-SLAB_R + 8, SLAB_R - 8);
    const z = random(-SLAB_H + 7, zGravelBottom(t) - 6);
    const rw = random(3, 8);
    const rz = random(2.5, 5.5);
    const pts = [];
    for (let a = 0; a < 360; a += 60) {
      const vt = constrain(t + rw * cos(a), -SLAB_R + 2, SLAB_R - 2);
      const vz = constrain(z + rz * sin(a), -SLAB_H + 2, zGravelBottom(vt) - 2);
      pts.push(isLeft ? iso(vt, SLAB_R, vz) : iso(SLAB_R, vt, vz));
    }
    brush.noStroke();
    brush.wash(isLeft ? "#6C6078" : "#433A4F", 220);
    drawPoly(pts);
    brush.noWash();
    brush.set("rotring", PAL.inkBlack, 0.25);
    strokePoly(pts, true);
  }

  // Fine pale rootlets dangling in upper soil layer (especially below the moss crack on Left face)
  const rootCount = isLeft ? 16 : 9;
  for (let r = 0; r < rootCount; r++) {
    let t = isLeft && r < 7 ? random(75, 135) : random(-SLAB_R + 18, SLAB_R - 18);
    let z = zGravelBottom(t) - random(0, 12);
    const rPts = [];
    const steps = int(random(5, 9));
    for (let k = 0; k < steps; k++) {
      rPts.push(isLeft ? iso(t, SLAB_R, z) : iso(SLAB_R, t, z));
      t += random(-4.5, 4.5);
      z -= random(5, 9);
      z = max(z, -SLAB_H + 3);
    }
    brush.set("rotring", isLeft ? "#B8B2C6" : "#7E788E", 0.22);
    strokePoly(rPts, false);
  }

  // Dense, obsessive pen stippling throughout the soil stratum
  const dotCount = 820;
  for (let i = 0; i < dotCount; i++) {
    const t = random(-SLAB_R + 2, SLAB_R - 2);
    const zTop = zGravelBottom(t);
    // Bias slightly denser near top of soil and bottom edge
    const uRand = random();
    const z = lerp(-SLAB_H + 1.5, zTop - 1, uRand * uRand * (3 - 2 * uRand));
    const p = isLeft ? iso(t, SLAB_R, z) : iso(SLAB_R, t, z);
    if (random() < 0.14 && isLeft) {
      brush.set("rotring", "#8E829C", 0.22);
    } else {
      brush.set("rotring", PAL.inkBlack, random(0.22, 0.38));
    }
    stippleDot(p[0], p[1], random(0.8, 1.4), random(180));
  }
}

// =============================================================================
// 5. HAIRLINE CRACK & SPROUTING MOSS
// =============================================================================
function drawCrackAndMoss() {
  // Main crack spine in (u, v) running across front-left flag to the front-left cut edge (v = 270)
  const mainSpine = [
    [-218, 152], [-188, 162], [-156, 158], [-125, 172], [-94, 179],
    [-62, 184], [-32, 198], [-4, 194], [26, 212], [54, 228],
    [78, 248], [104, 270]
  ];

  // Secondary branch splitting from [-62, 184]
  const branchSpine = [
    [-62, 184], [-42, 165], [-18, 154], [6, 134], [24, 118], [42, 112]
  ];

  // Tertiary micro-crack near the edge
  const microSpine = [
    [26, 212], [44, 196], [65, 188]
  ];

  // Draw the sharp dark crevice & chipped concrete lip along each crack
  drawCrackPath(mainSpine, 1.3);
  drawCrackPath(branchSpine, 0.8);
  drawCrackPath(microSpine, 0.5);

  // Vertical continuation of the crack down the Front-Left concrete cut face at u = 104
  const vertCrack = [
    iso(104, SLAB_R, 0),
    iso(101, SLAB_R, -14),
    iso(106, SLAB_R, -29),
    iso(102, SLAB_R, -44),
    iso(105, SLAB_R, zConcreteBottom(105))
  ];
  brush.set("rotring", PAL.white, 0.35);
  for (let i = 0; i < vertCrack.length - 1; i++) {
    brush.line(vertCrack[i][0] + 1.5, vertCrack[i][1], vertCrack[i + 1][0] + 1.5, vertCrack[i + 1][1]);
  }
  brush.set("rotring", PAL.inkBlack, 0.65);
  strokePoly(vertCrack, false);

  // --- Sprouting Moss Cushions along the Crack ---
  // Place velvety tufts of moss along the main and branch cracks
  const mossClusters = [
    // [u, v, radiusU, radiusV, heightZ]
    [-162, 160, 7, 5, 4.5],
    [-128, 171, 11, 7, 6.5],
    [-112, 175, 8, 6, 5.0],
    [-72, 182, 13, 8, 7.5],
    [-55, 186, 10, 7, 6.0],
    [-34, 197, 12, 8, 7.0],
    [-14, 195, 8, 5, 5.0],
    [14, 205, 9, 6, 5.5],
    [35, 218, 13, 8, 7.5],
    [52, 227, 10, 7, 6.5],
    [76, 247, 11, 7, 6.0],
    [98, 265, 9, 6, 5.5],
    // Branch moss tufts
    [-40, 166, 8, 5, 5.0],
    [-16, 153, 9, 6, 5.5],
    [8, 133, 6, 4, 4.0]
  ];

  // 1. Cast shadows of moss tufts onto the concrete
  brush.noStroke();
  brush.fillBleed(0.05, "in");
  brush.fill(PAL.shadowCore, 130);
  for (const [mu, mv, ru, rv, mz] of mossClusters) {
    const sPts = [];
    for (let a = 0; a < 360; a += 45) {
      const u = mu + ru * cos(a) + mz * SH_U * 0.85;
      const v = mv + rv * sin(a) + mz * SH_V * 0.85;
      sPts.push(iso(constrain(u, -SLAB_R, SLAB_R), constrain(v, -SLAB_R, SLAB_R), 0));
    }
    drawPoly(sPts, 0.25);
  }

  // 2. Watercolor base glazes for moss cushions
  brush.fillBleed(0.12, "out");
  brush.fillTexture(0.65, 0.45);
  for (const [mu, mv, ru, rv, mz] of mossClusters) {
    const mPts = [];
    for (let a = 0; a < 360; a += 40) {
      const rjit = 0.85 + 0.3 * noise(mu + a, mv);
      mPts.push(iso(mu + ru * rjit * cos(a), mv + rv * rjit * sin(a), mz * 0.45));
    }
    brush.fill(PAL.mossDark, 165);
    drawPoly(mPts, 0.3);

    // Lit upper-left cushion highlight
    const lPts = [];
    for (let a = 0; a < 360; a += 45) {
      lPts.push(iso(mu - 1.5 + ru * 0.65 * cos(a), mv + 1.0 + rv * 0.65 * sin(a), mz * 0.8));
    }
    brush.fill(PAL.mossMid, 155);
    drawPoly(lPts, 0.3);
  }
  brush.noFill();

  // 3. Obsessive pen & stipple texture for individual moss shoots
  for (const [mu, mv, ru, rv, mz] of mossClusters) {
    const count = int((ru + rv) * 4.2);
    for (let i = 0; i < count; i++) {
      const ang = random(360);
      const dist = sqrt(random()) * 0.95;
      const u = mu + dist * ru * cos(ang);
      const v = mv + dist * rv * sin(ang);
      const z = mz * (1 - dist * dist * 0.75) + random(-0.8, 1.2);
      const p = iso(u, v, z);

      // Shade from lit top-left (mossTip/mossLight) to shadowed bottom-right (mossDark/inkBlack)
      const lightVal = -cos(ang + 25) * dist;
      if (lightVal > 0.15) {
        brush.set("rotring", random() < 0.45 ? PAL.mossTip : PAL.mossLight, 0.32);
      } else if (lightVal > -0.25) {
        brush.set("rotring", PAL.mossMid, 0.32);
      } else {
        brush.set("rotring", random() < 0.5 ? PAL.mossDark : PAL.inkBlack, 0.3);
      }
      stippleDot(p[0], p[1], random(1.0, 1.8), random(60, 120));
    }
  }

  // Tiny moss tuft clinging inside the top of the vertical crack on the Front-Left cut face
  for (let i = 0; i < 32; i++) {
    const p = iso(104 + random(-3.5, 3.5), SLAB_R, random(-16, -1));
    brush.set("rotring", i % 3 === 0 ? PAL.mossLight : PAL.mossDark, 0.3);
    stippleDot(p[0], p[1], 1.3, 85);
  }
}

function drawCrackPath(spine, weightScale) {
  const finePts = [];
  for (let i = 0; i < spine.length - 1; i++) {
    const [u1, v1] = spine[i];
    const [u2, v2] = spine[i + 1];
    const sub = 6;
    for (let s = 0; s < sub; s++) {
      const t = s / sub;
      const u = lerp(u1, u2, t) + (s > 0 ? random(-1.8, 1.8) : 0);
      const v = lerp(v1, v2, t) + (s > 0 ? random(-1.8, 1.8) : 0);
      finePts.push([u, v]);
    }
  }
  finePts.push(spine[spine.length - 1]);

  // White highlight on down-right lip of crack (catches upper-left light)
  brush.set("rotring", PAL.white, 0.35 * weightScale);
  for (let i = 0; i < finePts.length - 1; i++) {
    const p1 = iso(finePts[i][0] + 1.4, finePts[i][1] - 0.8, 0);
    const p2 = iso(finePts[i + 1][0] + 1.4, finePts[i + 1][1] - 0.8, 0);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Mid-tone beveled chip edge
  brush.set("rotring", PAL.concDark, 0.55 * weightScale);
  for (let i = 0; i < finePts.length - 1; i++) {
    const p1 = iso(finePts[i][0] - 0.9, finePts[i][1] + 0.6, 0);
    const p2 = iso(finePts[i + 1][0] - 0.9, finePts[i + 1][1] + 0.6, 0);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Razor-sharp black fissure core
  brush.set("rotring", PAL.inkBlack, 0.62 * weightScale);
  for (let i = 0; i < finePts.length - 1; i++) {
    const p1 = iso(finePts[i][0], finePts[i][1], 0);
    const p2 = iso(finePts[i + 1][0], finePts[i + 1][1], 0);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// =============================================================================
// 6. FLATTENED GUM BLOT
// =============================================================================
function drawGumBlot(u0, v0) {
  const lobes = 18;
  const rimPts = [];
  const topPts = [];
  const shPts = [];

  for (let i = 0; i < lobes; i++) {
    const a = map(i, 0, lobes, 0, 360);
    // Slightly elongated amoeba shape
    const rad = 1 + 0.18 * sin(a * 2 + 20) + 0.12 * cos(a * 3 - 40) + 0.06 * sin(a * 5);
    const ru = 17.5 * rad;
    const rv = 13.5 * rad;
    const u = u0 + ru * cos(a);
    const v = v0 + rv * sin(a);
    rimPts.push(iso(u, v, 0.3));
    topPts.push(iso(u, v, 2.3));
    shPts.push(shadowPt(u, v, 2.5));
  }

  // Thin dark grime/shadow halo around the squashed perimeter
  brush.noStroke();
  brush.fillBleed(0.05, "in");
  brush.fill(PAL.shadowCore, 130);
  drawPoly(shPts, 0.25);

  // Opaque wash + watercolor glaze for the dusty pink-mauve gum
  brush.wash(PAL.gumBase, 235);
  drawPoly(topPts, 0.3);
  brush.noWash();

  brush.fillBleed(0.1, "in");
  brush.fillTexture(0.5, 0.4);
  brush.fill(PAL.gumDark, 105);
  drawPoly(rimPts, 0.3);

  // Highlight on upper-left rim
  const hlPts = [];
  for (let i = 0; i < 8; i++) {
    const a = map(i, 0, 7, 135, 315);
    hlPts.push(iso(u0 + 11 * cos(a), v0 + 8.5 * sin(a), 2.5));
  }
  brush.fill(PAL.gumLight, 140);
  drawPoly(hlPts, 0.3);
  brush.noFill();

  // Grimy outline & shoe-sole tread impression marks across the center
  brush.set("rotring", PAL.gumDark, 0.35);
  strokePoly(topPts, true);
  brush.set("rotring", PAL.inkDark, 0.28);
  strokePoly(rimPts, true);

  // Faint parallel shoe-tread ribs pressed into the gum
  for (let k = -3; k <= 3; k++) {
    const vOff = k * 2.6;
    const p1 = iso(u0 - 9 + abs(k) * 1.5, v0 + vOff - 2, 2.3);
    const p2 = iso(u0 + 9 - abs(k) * 1.5, v0 + vOff + 2, 2.3);
    brush.set("rotring", PAL.gumDark, 0.24);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Fine stippling for scuffed street grit embedded in the gum
  for (let i = 0; i < 65; i++) {
    const a = random(360);
    const d = sqrt(random());
    const p = iso(u0 + d * 15 * cos(a), v0 + d * 11 * sin(a), 2.3);
    brush.set("rotring", d > 0.75 ? PAL.inkDark : PAL.gumDark, 0.22);
    stippleDot(p[0], p[1], 0.85, random(180));
  }
}

// =============================================================================
// 7. THREE WET PLANE-TREE LEAVES
// =============================================================================
function drawWetLeaves() {
  // Three wet 5-lobed London plane-tree leaves clinging to the damp concrete
  drawSinglePlaneLeaf(-12, -116, 36, -125, PAL.leaf1, "#44483B", "#949078", 3.2);
  drawSinglePlaneLeaf(148, -28, 42, 28, PAL.leaf2, "#46333D", "#9B8082", 3.8);
  drawSinglePlaneLeaf(96, 22, 33, 142, PAL.leaf3, "#4E4D3F", "#A6A088", 3.0);
}

function drawSinglePlaneLeaf(u0, v0, scaleR, rotDeg, baseCol, darkCol, lightCol, curlZ) {
  // Polar profile of a 5-lobed Platanus (plane-tree) leaf
  // theta = 0 is the central apex lobe; +/- 52 deg are lateral lobes; +/- 112 deg are basal lobes; 180 is stem sinus
  function leafRadius(thetaDeg) {
    const a = ((thetaDeg + 540) % 360) - 180; // [-180, 180]
    const aa = abs(a);
    if (aa > 158) {
      // Deep narrow basal sinus around petiole attachment
      return 0.14 + 0.12 * ((180 - aa) / 22);
    }
    const l1 = 1.02 * exp(-pow(aa / 24, 2));
    const l2 = 0.88 * exp(-pow((aa - 56) / 22, 2));
    const l3 = 0.58 * exp(-pow((aa - 115) / 24, 2));
    const base = 0.30 + max(l1, max(l2, l3));
    // Marginal teeth/serrations near lobe tips
    const teeth = 0.045 * sin(aa * 7.5) * (base > 0.55 ? 1 : 0.2);
    return scaleR * (base + teeth);
  }

  function leafPt3D(thetaDeg, rFrac = 1.0) {
    const r = leafRadius(thetaDeg) * rFrac;
    const ang = thetaDeg + rotDeg;
    const u = u0 + r * cos(ang);
    const v = v0 + r * sin(ang);
    // Slight upward curl at lobe tips so it casts a crisp thin shadow
    const aa = abs(((thetaDeg + 540) % 360) - 180);
    const isTip = (aa < 18 || abs(aa - 56) < 15) && rFrac > 0.65;
    const z = isTip ? curlZ * pow((rFrac - 0.65) / 0.35, 1.4) : 0.6;
    return [u, v, z];
  }

  const outlinePts = [];
  const shadowPts = [];
  const wetFilmPts = [];

  for (let th = -176; th <= 176; th += 5) {
    const [u, v, z] = leafPt3D(th, 1.0);
    outlinePts.push(iso(u, v, z));
    shadowPts.push(shadowPt(u, v, z + 1.2));
    wetFilmPts.push(iso(u0 + (u - u0) * 1.12, v0 + (v - v0) * 1.12, 0));
  }

  // 1. Dark wet surface water film clinging around the leaf perimeter
  brush.noStroke();
  brush.fillBleed(0.08, "out");
  brush.fill(PAL.concDark, 75);
  drawPoly(wetFilmPts, 0.2);

  // 2. Crisp isometric cast shadow under curled lobes
  brush.fillBleed(0.03, "in");
  brush.fill(PAL.shadowCore, 155);
  drawPoly(shadowPts, 0.15);

  // 3. Leaf blade solid wash + watercolor glazes
  brush.wash(baseCol, 225);
  drawPoly(outlinePts, 0.15);
  brush.noWash();

  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.65, 0.45);
  brush.fill(darkCol, 115);
  drawPoly(outlinePts, 0.15);

  // Lighter wet highlight glaze on upper-left half of leaf blade
  const litHalf = [];
  for (let th = -110; th <= 40; th += 10) {
    const [u, v, z] = leafPt3D(th, 0.85);
    litHalf.push(iso(u, v, z));
  }
  brush.fill(lightCol, 120);
  drawPoly(litHalf, 0.25);
  brush.noFill();

  // 4. Petiole (stem) extending from sinus (theta = 180)
  const stemStart = leafPt3D(180, 0.14);
  const stemMid = [
    u0 + scaleR * 0.42 * cos(rotDeg + 188),
    v0 + scaleR * 0.42 * sin(rotDeg + 188),
    1.2
  ];
  const stemEnd = [
    u0 + scaleR * 0.72 * cos(rotDeg + 198),
    v0 + scaleR * 0.72 * sin(rotDeg + 198),
    1.8
  ];
  const sp0 = iso(...stemStart);
  const sp1 = iso(...stemMid);
  const sp2 = iso(...stemEnd);

  // Stem shadow
  brush.set("rotring", PAL.shadowCore, 0.5);
  const ss0 = shadowPt(...stemStart);
  const ss1 = shadowPt(...stemMid);
  const ss2 = shadowPt(...stemEnd);
  brush.line(ss0[0], ss0[1], ss1[0], ss1[1]);
  brush.line(ss1[0], ss1[1], ss2[0], ss2[1]);

  // Stem body
  brush.set("rotring", darkCol, 0.6);
  brush.line(sp0[0], sp0[1], sp1[0], sp1[1]);
  brush.line(sp1[0], sp1[1], sp2[0], sp2[1]);

  // 5. Crisp serrated leaf margin & palmate venation in fine pen
  brush.set("rotring", PAL.inkBlack, 0.35);
  strokePoly(outlinePts, true);

  // 5 main palmate veins radiating from petiole base
  const veinAngles = [0, -56, 56, -115, 115];
  for (const va of veinAngles) {
    const vPts = [sp0];
    for (let f = 0.2; f <= 0.96; f += 0.19) {
      const [u, v, z] = leafPt3D(va, f);
      vPts.push(iso(u, v, z));
    }
    brush.set("rotring", PAL.inkDark, 0.32);
    strokePoly(vPts, false);

    // Specular wet highlight alongside main veins
    const hPts = [];
    for (let f = 0.25; f <= 0.80; f += 0.25) {
      const [u, v, z] = leafPt3D(va - 3, f);
      hPts.push(iso(u, v, z + 0.2));
    }
    brush.set("rotring", PAL.white, 0.35);
    strokePoly(hPts, false);

    // Lateral secondary veins branching off each primary vein
    for (let f = 0.32; f <= 0.78; f += 0.22) {
      const [bu, bv, bz] = leafPt3D(va, f);
      const bp = iso(bu, bv, bz);
      for (const side of [-1, 1]) {
        const [tu, tv, tz] = leafPt3D(va + side * 16, min(0.95, f + 0.16));
        const tp = iso(tu, tv, tz);
        brush.set("rotring", darkCol, 0.22);
        brush.line(bp[0], bp[1], tp[0], tp[1]);
      }
    }
  }

  // 6. Specular water sheen & necrotic spots / stippling on the wet leaf
  for (let i = 0; i < 95; i++) {
    const th = random(-165, 165);
    const rf = sqrt(random()) * 0.92;
    const [u, v, z] = leafPt3D(th, rf);
    const p = iso(u, v, z);
    if (random() < 0.18) {
      brush.set("rotring", PAL.white, 0.32);
      stippleDot(p[0], p[1], 1.4, 25);
    } else {
      brush.set("rotring", random() < 0.5 ? PAL.inkBlack : darkCol, 0.24);
      stippleDot(p[0], p[1], 0.95, random(180));
    }
  }
}

// =============================================================================
// 8. BOTTLE CAP (21-CRIMP CROWN CAP)
// =============================================================================
function drawBottleCap(u0, v0) {
  const crimps = 21;
  const rOuter = 13.5;
  const rInner = 10.2;
  const zTop = 5.6;

  // 1. Isometric Cast Shadow of the Bottle Cap
  const capShadow = [];
  for (let i = 0; i < crimps; i++) {
    const a = map(i, 0, crimps, 0, 360);
    const u = u0 + rOuter * cos(a);
    const v = v0 + rOuter * sin(a);
    capShadow.push(shadowPt(u, v, zTop));
  }
  brush.noStroke();
  brush.fillBleed(0.04, "in");
  brush.fill(PAL.shadowCore, 165);
  drawPoly(capShadow, 0.1);
  brush.noFill();

  // 2. Corrugated metallic skirt (21 crimped flutes around the perimeter)
  const skirtOuter = [];
  const topCrown = [];
  for (let i = 0; i < crimps * 2; i++) {
    const a = map(i, 0, crimps * 2, 0, 360);
    const isPeak = i % 2 === 0;
    const rSkirt = isPeak ? rOuter : rOuter * 0.88;
    const zSkirt = isPeak ? 0.4 : 1.4;
    skirtOuter.push(iso(u0 + rSkirt * cos(a), v0 + rSkirt * sin(a), zSkirt));
    topCrown.push(iso(u0 + rInner * cos(a), v0 + rInner * sin(a), zTop));
  }

  // Wash metallic tin skirt
  brush.noStroke();
  brush.wash(PAL.capTin, 240);
  drawPoly(skirtOuter, 0.05);

  // Wash cobalt-blue painted top disc
  brush.wash(PAL.capBlue, 240);
  drawPoly(topCrown, 0.2);
  brush.noWash();

  // Watercolor shading glaze on right half of cap
  brush.fillBleed(0.08, "in");
  brush.fill(PAL.capDark, 130);
  const rightShade = [];
  for (let a = -65; a <= 115; a += 20) {
    rightShade.push(iso(u0 + rOuter * cos(a), v0 + rOuter * sin(a), 1.5));
  }
  for (let a = 115; a >= -65; a -= 20) {
    rightShade.push(iso(u0 + rInner * 0.3 * cos(a), v0 + rInner * 0.3 * sin(a), zTop));
  }
  drawPoly(rightShade, 0.15);
  brush.noFill();

  // 3. Draw individual crimp ridges & metallic highlights
  for (let i = 0; i < crimps * 2; i++) {
    const a = map(i, 0, crimps * 2, 0, 360);
    const pBot = skirtOuter[i];
    const pTop = topCrown[i];
    // Visible front/side flutes
    if (sin(a + 45) > -0.35) {
      if (i % 2 === 0) {
        brush.set("rotring", PAL.inkBlack, 0.35);
        brush.line(pBot[0], pBot[1], pTop[0], pTop[1]);
      } else {
        brush.set("rotring", a > 120 && a < 300 ? PAL.white : PAL.capLight, 0.32);
        brush.line(pBot[0], pBot[1], pTop[0], pTop[1]);
      }
    }
  }

  // Outer crimped contour & top circular bezel
  brush.set("rotring", PAL.inkBlack, 0.38);
  strokePoly(skirtOuter, true);
  brush.set("rotring", PAL.capDark, 0.34);
  strokePoly(topCrown, true);

  // Chipped silver scratch & bright rim highlight on the top face
  brush.set("rotring", PAL.white, 0.45);
  const hlArc = [];
  for (let a = 145; a <= 265; a += 20) {
    hlArc.push(iso(u0 + rInner * 0.92 * cos(a), v0 + rInner * 0.92 * sin(a), zTop + 0.2));
  }
  strokePoly(hlArc, false);

  // Scratched paint chip across center of cap
  const pScratch1 = iso(u0 - 4, v0 + 2, zTop + 0.2);
  const pScratch2 = iso(u0 + 5, v0 - 1, zTop + 0.2);
  brush.set("rotring", PAL.capTin, 0.55);
  brush.line(pScratch1[0], pScratch1[1], pScratch2[0], pScratch2[1]);
}

// =============================================================================
// 9. RAZOR-STRAIGHT OUTER EDGES AGAINST THE PALE LILAC VOID
// =============================================================================
function enforceRazorEdges() {
  const N = iso(-SLAB_R, -SLAB_R, 0);
  const E = iso(SLAB_R, -SLAB_R, 0);
  const S = iso(SLAB_R, SLAB_R, 0);
  const W = iso(-SLAB_R, SLAB_R, 0);
  const Wb = iso(-SLAB_R, SLAB_R, -SLAB_H);
  const Sb = iso(SLAB_R, SLAB_R, -SLAB_H);
  const Eb = iso(SLAB_R, -SLAB_R, -SLAB_H);

  // Clean up any stray watercolor bleed outside the 6 outer edges of the slab hexagon
  const M = 120;
  brush.noStroke();
  brush.noFill();
  brush.wash(PAL.bg, 255);

  // 6 outer margin mask polygons hugging the exact hexagonal silhouette
  drawPoly([N, W, [W[0] - M, W[1] - M], [N[0], N[1] - M]]);
  drawPoly([N, E, [E[0] + M, E[1] - M], [N[0], N[1] - M]]);
  drawPoly([W, Wb, [Wb[0] - M, Wb[1] + M], [W[0] - M, W[1] - M]]);
  drawPoly([E, Eb, [Eb[0] + M, Eb[1] + M], [E[0] + M, E[1] - M]]);
  drawPoly([Wb, Sb, [Sb[0], Sb[1] + M], [Wb[0] - M, Wb[1] + M]]);
  drawPoly([Sb, Eb, [Eb[0] + M, Eb[1] + M], [Sb[0], Sb[1] + M]]);

  brush.noWash();

  // Crisp architectural technical-pen lines along the slab perimeter and interior cut corners
  brush.set("rotring", PAL.inkBlack, 0.52);
  brush.line(N[0], N[1], E[0], E[1]);
  brush.line(N[0], N[1], W[0], W[1]);
  brush.line(W[0], W[1], Wb[0], Wb[1]);
  brush.line(E[0], E[1], Eb[0], Eb[1]);
  brush.line(Wb[0], Wb[1], Sb[0], Sb[1]);
  brush.line(Sb[0], Sb[1], Eb[0], Eb[1]);

  // Front top edges (W-S and S-E) and center vertical cut edge (S-Sb)
  brush.set("rotring", PAL.inkDark, 0.45);
  brush.line(W[0], W[1], S[0], S[1]);
  brush.line(S[0], S[1], E[0], E[1]);
  brush.line(S[0], S[1], Sb[0], Sb[1]);

  // Subtle top highlight along the front-left cut edge (W to S)
  brush.set("rotring", PAL.white, 0.38);
  brush.line(W[0], W[1] - 0.8, S[0], S[1] - 0.8);
}

// =============================================================================
// 10. PAINT-CHIPPED FIRE HYDRANT (OBSESSIVE REALISM)
// =============================================================================
function drawFireHydrant(u0, v0) {
  // Radius profile of the hydrant barrel & bonnet from z = 0 to z = 206
  function hydRadius(z) {
    if (z <= 14) return 52;
    if (z <= 20) return map(z, 14, 20, 50, 40);
    if (z <= 64) return map(z, 20, 64, 40, 42);
    if (z <= 76) return 44.5; // Raised mid-barrel cast band
    if (z <= 136) return map(z, 76, 136, 42.5, 44.5);
    if (z <= 150) return 51.5; // Upper bonnet flange
    if (z <= 156) return 47.0;
    // Domed bonnet
    const t = constrain((z - 156) / 50, 0, 1);
    return 46.5 * cos(t * 76) + 2.5;
  }

  // --- A. Back-Left Side Hose Nozzle (peeking out at phi ~ 205 deg) ---
  drawSideNozzleBackLeft(u0, v0, 110);

  // --- B. Base Flange & Anchor Bolts (z = 0 to 15) ---
  const baseBot = [], baseTop = [];
  for (let phi = -15; phi <= 195; phi += 10) {
    baseBot.push(cylPt(u0, v0, 1, 52, phi));
  }
  for (let phi = 195; phi >= -15; phi -= 10) {
    baseTop.push(cylPt(u0, v0, 14, 52, phi));
  }
  const baseTopFull = [];
  for (let phi = 0; phi < 360; phi += 12) {
    baseTopFull.push(cylPt(u0, v0, 14, 52, phi));
  }

  brush.noStroke();
  brush.wash(PAL.ironDark, 240);
  drawPoly(baseBot.concat(baseTop));
  brush.wash(PAL.hydDark, 230);
  drawPoly(baseTopFull);
  brush.noWash();

  // --- C. Main Barrel & Domed Bonnet Silhouette ---
  const zLevels = [14, 20, 45, 64, 70, 76, 105, 136, 139, 150, 155, 168, 182, 194, 205];
  const leftSil = [];
  const rightSil = [];
  for (const z of zLevels) {
    const r = hydRadius(z);
    leftSil.push(cylPt(u0, v0, z, r, 180));
    rightSil.push(cylPt(u0, v0, z, r, 0));
  }
  // Connect top cap arc across bonnet apex
  const topCap = [];
  for (let phi = 180; phi >= 0; phi -= 18) {
    topCap.push(cylPt(u0, v0, 205, hydRadius(205), phi));
  }
  const bottomArc = [];
  for (let phi = 0; phi <= 180; phi += 15) {
    bottomArc.push(cylPt(u0, v0, 14, 40, phi));
  }

  const fullBodyPoly = leftSil.concat(topCap).concat([...rightSil].reverse()).concat(bottomArc);

  // Base opaque wash in cool alizarin crimson
  brush.noStroke();
  brush.wash(PAL.hydMid, 245);
  drawPoly(fullBodyPoly);
  brush.noWash();

  // Cylindrical shading bands (Lit left phi 115..175, Mid 65..115, Core Shadow 15..65, Reflected 0..15)
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.55, 0.4);

  // Lit left zone
  drawCylinderBand(u0, v0, hydRadius, 16, 203, 118, 174, PAL.hydLight, 155);
  // Core shadow zone on right side
  drawCylinderBand(u0, v0, hydRadius, 14, 203, 12, 74, PAL.hydDark, 185);
  // Reflected cool slate-crimson on extreme right edge
  drawCylinderBand(u0, v0, hydRadius, 16, 195, 0, 16, PAL.hydRefl, 130);

  brush.noFill();

  // --- D. Vertical Flutes & Rib Channels on the Barrel and Bonnet ---
  const flutePhis = [18, 42, 68, 94, 120, 146, 168];
  for (const phi of flutePhis) {
    // Lower barrel flute (z = 24 to 132)
    const fLeft = [], fRight = [];
    for (let z = 24; z <= 132; z += 18) {
      const r = hydRadius(z);
      fLeft.push(cylPt(u0, v0, z, r, phi - 4.5));
      fRight.push(cylPt(u0, v0, z, r, phi + 4.5));
    }
    brush.set("rotring", phi < 85 ? PAL.inkBlack : PAL.hydDark, 0.34);
    strokePoly(fLeft, false);
    brush.set("rotring", phi > 95 ? PAL.white : PAL.hydLight, 0.28);
    strokePoly(fRight, false);

    // Bonnet dome flute (z = 156 to 198)
    const bFlute = [];
    for (let z = 156; z <= 198; z += 10) {
      bFlute.push(cylPt(u0, v0, z, hydRadius(z), phi));
    }
    brush.set("rotring", phi < 85 ? PAL.inkBlack : PAL.hydDark, 0.32);
    strokePoly(bFlute, false);
  }

  // --- E. Upper Bonnet Flange Ring (z = 138 to 151, r = 51.5) ---
  drawFlangeRing(u0, v0, 138, 150, 51.5, 6);

  // Base flange bolts (at z = 14, r = 46)
  for (let phi = 12; phi <= 172; phi += 26) {
    const bp = cylPt(u0, v0, 14, 46, phi);
    drawHexBolt(bp[0], bp[1], 3.8, phi > 95);
  }

  // --- F. Obsessive Chipped Paint Patches (Primer Halo + Dark Cast Iron Core) ---
  // Each chip: [zCenter, phiCenter, zSpan, phiSpan, seed]
  const chips = [
    // Heavy chipping along the upper bonnet flange & dome
    [144, 132, 10, 26, 1],
    [145, 78, 9, 22, 2],
    [172, 142, 18, 28, 3],
    [186, 105, 16, 32, 4],
    [166, 54, 15, 22, 5],
    // Mid-barrel band & lower barrel chips
    [71, 138, 13, 28, 6],
    [70, 86, 11, 20, 7],
    [48, 152, 20, 24, 8],
    [34, 112, 16, 25, 9],
    [22, 140, 14, 30, 10],
    [24, 62, 15, 26, 11],
    [88, 42, 16, 20, 12],
    [125, 156, 14, 22, 13]
  ];

  for (const [zc, phic, zs, phis, sd] of chips) {
    drawPaintChipOnCylinder(u0, v0, hydRadius, zc, phic, zs, phis, sd);
  }

  // --- G. Right Side Hose Nozzle (pointing +u, at z = 110) ---
  drawSideNozzleRight(u0, v0, 110);

  // --- H. Front-Left Large Pumper Nozzle (pointing +v, at z = 106) ---
  drawFrontPumperNozzle(u0, v0, 106);

  // --- I. Pentagon Operating Nut & Top Boss (z = 204 to 223) ---
  drawOperatingNut(u0, v0, 204);

  // --- J. Final Pen Contours, Cross-Contour Hatching & Stipple Texture on Hydrant ---
  brush.set("rotring", PAL.inkBlack, 0.48);
  strokePoly(leftSil, false);
  strokePoly(rightSil, false);

  // Specular highlight strip down the lit left side of the barrel (phi = 148)
  brush.set("rotring", PAL.white, 0.42);
  for (let z = 24; z < 132; z += 14) {
    const p1 = cylPt(u0, v0, z, hydRadius(z), 148);
    const p2 = cylPt(u0, v0, z + 9, hydRadius(z + 9), 148);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Curved cross-contour pen lines & stippling on the shadow side of the barrel & bonnet
  for (let z = 18; z <= 200; z += 4.2) {
    const r = hydRadius(z);
    const arcPts = [];
    const phiEnd = z > 152 ? 95 : 78;
    for (let phi = 4; phi <= phiEnd; phi += 12) {
      // Skip where nozzles sit
      if (z > 90 && z < 130 && phi > 20 && phi < 70) continue;
      arcPts.push(cylPt(u0, v0, z, r, phi));
    }
    brush.set("rotring", PAL.inkBlack, 0.24);
    strokePoly(arcPts, false);
  }

  // Dense pen stippling across the hydrant surface for cast-iron roughness
  for (let i = 0; i < 620; i++) {
    const z = random(15, 202);
    const phi = random(4, 176);
    // Avoid drawing over front pumper nozzle center
    if (z > 84 && z < 128 && phi > 105 && phi < 155) continue;
    const p = cylPt(u0, v0, z, hydRadius(z), phi);
    if (phi > 130 && random() < 0.35) {
      brush.set("rotring", PAL.primer, 0.24);
    } else if (phi < 75) {
      brush.set("rotring", PAL.inkBlack, 0.28);
    } else {
      brush.set("rotring", PAL.hydDark, 0.24);
    }
    stippleDot(p[0], p[1], random(0.8, 1.4), random(180));
  }
}

function drawCylinderBand(u0, v0, radFn, z1, z2, phi1, phi2, col, alphaVal) {
  const pts = [];
  const zStep = 14;
  for (let z = z1; z <= z2; z += zStep) {
    pts.push(cylPt(u0, v0, z, radFn(z), phi1));
  }
  for (let phi = phi1; phi <= phi2; phi += 12) {
    pts.push(cylPt(u0, v0, z2, radFn(z2), phi));
  }
  for (let z = z2; z >= z1; z -= zStep) {
    pts.push(cylPt(u0, v0, z, radFn(z), phi2));
  }
  for (let phi = phi2; phi >= phi1; phi -= 12) {
    pts.push(cylPt(u0, v0, z1, radFn(z1), phi));
  }
  brush.fill(col, alphaVal);
  drawPoly(pts);
}

function drawFlangeRing(u0, v0, zBot, zTop, r, nBolts) {
  const botArc = [], topArc = [];
  for (let phi = -10; phi <= 190; phi += 10) {
    botArc.push(cylPt(u0, v0, zBot, r, phi));
  }
  for (let phi = 190; phi >= -10; phi -= 10) {
    topArc.push(cylPt(u0, v0, zTop, r, phi));
  }
  brush.noStroke();
  brush.wash(PAL.hydMid, 240);
  drawPoly(botArc.concat(topArc));
  brush.noWash();

  // Shade right side of flange
  const rBot = [], rTop = [];
  for (let phi = -5; phi <= 75; phi += 10) rBot.push(cylPt(u0, v0, zBot, r, phi));
  for (let phi = 75; phi >= -5; phi -= 10) rTop.push(cylPt(u0, v0, zTop, r, phi));
  brush.fillBleed(0.05, "in");
  brush.fill(PAL.hydDark, 175);
  drawPoly(rBot.concat(rTop));
  brush.noFill();

  // Crisp top & bottom flange edges
  brush.set("rotring", PAL.inkBlack, 0.42);
  strokePoly(botArc, false);
  brush.set("rotring", PAL.inkDark, 0.36);
  strokePoly(topArc, false);

  // Bolts perched on top of the flange rim
  for (let i = 0; i < nBolts; i++) {
    const phi = map(i, 0, nBolts - 1, 14, 166);
    const bp = cylPt(u0, v0, zTop, r * 0.9, phi);
    drawHexBolt(bp[0], bp[1], 3.6, phi > 90);
  }
}

function drawHexBolt(x, y, sz, isLit) {
  const top = [
    [x - sz, y - sz * 0.8], [x + sz, y - sz * 0.8],
    [x + sz * 1.2, y - sz * 0.2], [x - sz * 1.2, y - sz * 0.2]
  ];
  const body = [
    [x - sz * 1.2, y - sz * 0.2], [x + sz * 1.2, y - sz * 0.2],
    [x + sz * 1.2, y + sz * 0.7], [x - sz * 1.2, y + sz * 0.7]
  ];
  brush.noStroke();
  brush.wash(isLit ? PAL.primer : PAL.ironLight, 235);
  drawPoly(top);
  brush.wash(PAL.ironDark, 240);
  drawPoly(body);
  brush.noWash();

  brush.set("rotring", PAL.inkBlack, 0.32);
  strokePoly(top, true);
  strokePoly(body, true);
}

function drawPaintChipOnCylinder(u0, v0, radFn, zc, phic, zs, phis, seed) {
  const primerPts = [];
  const ironPts = [];
  const steps = 12;

  for (let i = 0; i < steps; i++) {
    const a = map(i, 0, steps, 0, 360);
    const n = 0.65 + 0.55 * noise(seed * 13.7 + cos(a) * 1.3, sin(a) * 1.3);
    const dz = (zs * 0.5) * n * sin(a);
    const dphi = (phis * 0.5) * n * cos(a);

    const z1 = constrain(zc + dz * 1.22, 6, 203);
    const phi1 = constrain(phic + dphi * 1.22, 2, 178);
    primerPts.push(cylPt(u0, v0, z1, radFn(z1), phi1));

    const z2 = constrain(zc + dz * 0.88, 6, 203);
    const phi2 = constrain(phic + dphi * 0.88, 2, 178);
    ironPts.push(cylPt(u0, v0, z2, radFn(z2), phi2));
  }

  // 1. Pale cool zinc primer halo exposed around the peeled red paint
  brush.noStroke();
  brush.wash(PAL.primer, 230);
  drawPoly(primerPts);

  // 2. Dark oxidized blue-slate cast iron inside the chip
  brush.wash(phic > 95 ? PAL.ironLight : PAL.ironDark, 245);
  drawPoly(ironPts);
  brush.noWash();

  // 3. Tiny cool rust/oxidation glaze inside larger chips
  if (zs > 13) {
    brush.fillBleed(0.05, "in");
    brush.fill(PAL.ironRust, 110);
    drawPoly(ironPts);
    brush.noFill();
  }

  // 4. Crisp shadow edge along the upper-left rim of the peeled red paint (thickness of paint!)
  brush.set("rotring", PAL.inkBlack, 0.40);
  strokePoly(primerPts, true);
  brush.set("rotring", PAL.inkDark, 0.28);
  strokePoly(ironPts, true);

  // Highlight catch on bottom-right edge of the peeled paint
  brush.set("rotring", PAL.white, 0.34);
  for (let i = 0; i < 4; i++) {
    const p1 = primerPts[i];
    const p2 = primerPts[(i + 1) % primerPts.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Pitted iron stipples inside the chip
  const center = cylPt(u0, v0, zc, radFn(zc), phic);
  for (let k = 0; k < 10; k++) {
    brush.set("rotring", PAL.inkBlack, 0.26);
    stippleDot(center[0] + random(-5, 5), center[1] + random(-4, 4), 1.0, 45);
  }
}

function drawSideNozzleBackLeft(u0, v0, zNoz) {
  // Protruding toward -u (back-left)
  const rNoz = 15;
  const uStart = u0 - 30;
  const uEnd = u0 - 56;
  const bodyPts = [];
  for (let a = 0; a <= 180; a += 30) {
    bodyPts.push(iso(uStart, v0 + rNoz * cos(a), zNoz + rNoz * sin(a)));
  }
  for (let a = 180; a >= 0; a -= 30) {
    bodyPts.push(iso(uEnd, v0 + rNoz * 1.08 * cos(a), zNoz + rNoz * 1.08 * sin(a)));
  }
  brush.noStroke();
  brush.wash(PAL.hydLight, 240);
  drawPoly(bodyPts);
  // Chipped iron cap end
  const capPts = [];
  for (let a = 0; a < 360; a += 30) {
    capPts.push(iso(uEnd - 4, v0 + rNoz * 0.9 * cos(a), zNoz + rNoz * 0.9 * sin(a)));
  }
  brush.wash(PAL.ironLight, 240);
  drawPoly(capPts);
  brush.noWash();

  brush.set("rotring", PAL.inkBlack, 0.38);
  strokePoly(bodyPts, true);
  strokePoly(capPts, true);
}

function drawSideNozzleRight(u0, v0, zNoz) {
  // Protruding toward +u (front-right) from u0 + 28 to u0 + 62
  const rNoz = 15.5;
  const u1 = u0 + 26;
  const u2 = u0 + 52;
  const u3 = u0 + 62;

  const cyl = [];
  for (let a = -90; a <= 90; a += 20) {
    cyl.push(iso(u1, v0 + rNoz * cos(a), zNoz + rNoz * sin(a)));
  }
  for (let a = 90; a >= -90; a -= 20) {
    cyl.push(iso(u2, v0 + rNoz * cos(a), zNoz + rNoz * sin(a)));
  }

  const capFace = [];
  for (let a = 0; a < 360; a += 20) {
    capFace.push(iso(u3, v0 + (rNoz + 2) * cos(a), zNoz + (rNoz + 2) * sin(a)));
  }

  brush.noStroke();
  brush.wash(PAL.hydDark, 245);
  drawPoly(cyl);
  brush.wash(PAL.hydMid, 245);
  drawPoly(capFace);

  // Chipped paint on nozzle cap exposing iron & primer
  const chip = [];
  for (let a = 0; a < 360; a += 60) {
    chip.push(iso(u3 + 1, v0 + 6 * cos(a), zNoz + 4 + 6 * sin(a)));
  }
  brush.wash(PAL.primer, 230);
  drawPoly(chip);
  brush.noWash();

  // Center pentagon nut on right nozzle cap
  const nut = [];
  for (let a = 0; a < 360; a += 72) {
    nut.push(iso(u3 + 5, v0 + 5.5 * cos(a), zNoz + 5.5 * sin(a)));
  }
  brush.noStroke();
  brush.wash(PAL.ironDark, 245);
  drawPoly(nut);
  brush.noWash();

  brush.set("rotring", PAL.inkBlack, 0.42);
  strokePoly(cyl, true);
  strokePoly(capFace, true);
  strokePoly(nut, true);

  // Hanging steel chain links from barrel eye-bolt to nozzle cap
  const chainPts = [];
  for (let t = 0; t <= 1; t += 0.12) {
    const cu = lerp(u0 + 34, u3 + 3, t);
    const cv = lerp(v0 + 16, v0 + 4, t);
    const cz = lerp(zNoz - 8, zNoz - 4, t) - 18 * sin(t * 180);
    chainPts.push(iso(cu, cv, cz));
  }
  for (let i = 0; i < chainPts.length - 1; i++) {
    const p1 = chainPts[i];
    const p2 = chainPts[i + 1];
    brush.set("rotring", PAL.inkBlack, 0.65);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("rotring", PAL.primer, 0.32);
    brush.line(p1[0] - 0.8, p1[1] - 0.8, p2[0] - 0.8, p2[1] - 0.8);
  }
}

function drawFrontPumperNozzle(u0, v0, zNoz) {
  // Large steamer nozzle protruding toward +v (front-left) from v0 + 28 to v0 + 64
  const rNoz = 23.5;
  const v1 = v0 + 26;
  const v2 = v0 + 50;
  const v3 = v0 + 60;

  // Nozzle collar on barrel
  const collar = [];
  for (let a = 0; a < 360; a += 18) {
    collar.push(iso(u0 + (rNoz + 3) * cos(a), v1, zNoz + (rNoz + 3) * sin(a)));
  }
  // Threaded cap ring
  const capRing = [];
  for (let a = 0; a < 360; a += 18) {
    capRing.push(iso(u0 + (rNoz + 2) * cos(a), v2, zNoz + (rNoz + 2) * sin(a)));
  }
  // Front face of cap
  const capFront = [];
  for (let a = 0; a < 360; a += 18) {
    capFront.push(iso(u0 + rNoz * cos(a), v3, zNoz + rNoz * sin(a)));
  }

  brush.noStroke();
  brush.wash(PAL.hydMid, 245);
  drawPoly(collar);
  brush.wash(PAL.hydDark, 245);
  drawPoly(capRing);
  brush.wash(PAL.hydLight, 240);
  drawPoly(capFront);

  // Heavy paint chip across the front pumper cap face (primer + dark cast iron)
  const capChipPrimer = [
    iso(u0 - 14, v3 + 0.5, zNoz + 8),
    iso(u0 - 2, v3 + 0.5, zNoz + 18),
    iso(u0 + 12, v3 + 0.5, zNoz + 11),
    iso(u0 + 6, v3 + 0.5, zNoz - 4),
    iso(u0 - 10, v3 + 0.5, zNoz - 2)
  ];
  const capChipIron = [
    iso(u0 - 11, v3 + 0.5, zNoz + 7),
    iso(u0 - 2, v3 + 0.5, zNoz + 15),
    iso(u0 + 9, v3 + 0.5, zNoz + 9),
    iso(u0 + 4, v3 + 0.5, zNoz - 1),
    iso(u0 - 8, v3 + 0.5, zNoz + 1)
  ];
  brush.wash(PAL.primer, 235);
  drawPoly(capChipPrimer);
  brush.wash(PAL.ironDark, 245);
  drawPoly(capChipIron);

  // Center pentagon nut on the front pumper cap
  const frontNut = [];
  for (let a = 0; a < 360; a += 72) {
    frontNut.push(iso(u0 + 7.5 * cos(a - 18), v3 + 6, zNoz + 7.5 * sin(a - 18)));
  }
  brush.wash(PAL.ironLight, 240);
  drawPoly(frontNut);
  brush.noWash();

  // Two side lugs sticking out of the pumper cap at a = 0 and a = 180
  for (const side of [-1, 1]) {
    const lug = [
      iso(u0 + side * rNoz, v2 + 2, zNoz + 4),
      iso(u0 + side * (rNoz + 7), v2 + 3, zNoz + 3),
      iso(u0 + side * (rNoz + 7), v3 - 1, zNoz - 3),
      iso(u0 + side * rNoz, v3 - 1, zNoz - 4)
    ];
    brush.noStroke();
    brush.wash(side < 0 ? PAL.primer : PAL.ironDark, 240);
    drawPoly(lug);
    brush.noWash();
    brush.set("rotring", PAL.inkBlack, 0.36);
    strokePoly(lug, true);
  }

  // Pen outlines & shading on front pumper nozzle
  brush.set("rotring", PAL.inkBlack, 0.44);
  strokePoly(collar, true);
  strokePoly(capRing, true);
  strokePoly(capFront, true);
  strokePoly(frontNut, true);
  brush.set("rotring", PAL.inkDark, 0.32);
  strokePoly(capChipPrimer, true);

  // Chain loop hanging under front pumper nozzle
  const pChain = [];
  for (let t = 0; t <= 1; t += 0.12) {
    const cu = lerp(u0 - 14, u0 + 2, t);
    const cv = lerp(v1 + 2, v3 + 2, t);
    const cz = lerp(zNoz - 16, zNoz - 6, t) - 16 * sin(t * 180);
    pChain.push(iso(cu, cv, cz));
  }
  for (let i = 0; i < pChain.length - 1; i++) {
    brush.set("rotring", PAL.inkBlack, 0.65);
    brush.line(pChain[i][0], pChain[i][1], pChain[i + 1][0], pChain[i + 1][1]);
    brush.set("rotring", PAL.white, 0.30);
    brush.line(pChain[i][0] - 0.8, pChain[i][1], pChain[i + 1][0] - 0.8, pChain[i + 1][1]);
  }
}

function drawOperatingNut(u0, v0, zBase) {
  // Circular boss collar at apex of dome (z = 204 to 210, r = 16)
  const collarBot = [], collarTop = [];
  for (let phi = -10; phi <= 190; phi += 20) {
    collarBot.push(cylPt(u0, v0, zBase, 16, phi));
  }
  for (let phi = 190; phi >= -10; phi -= 20) {
    collarTop.push(cylPt(u0, v0, zBase + 6, 15, phi));
  }
  brush.noStroke();
  brush.wash(PAL.primer, 235);
  drawPoly(collarBot.concat(collarTop));

  // Pentagon operating nut (z = 210 to 223, r = 11.5)
  const nutBot = [], nutTop = [];
  const pentPhis = [18, 82, 146, 210, 295];
  for (const phi of pentPhis) {
    nutBot.push(cylPt(u0, v0, zBase + 6, 11.5, phi));
    nutTop.push(cylPt(u0, v0, zBase + 19, 11.0, phi));
  }
  // Left lit face of pentagon nut
  brush.wash(PAL.ironLight, 245);
  drawPoly([nutBot[1], nutBot[2], nutTop[2], nutTop[1]]);
  // Right shadowed face of pentagon nut
  brush.wash(PAL.ironDark, 245);
  drawPoly([nutBot[0], nutBot[1], nutTop[1], nutTop[0]]);
  // Top flat pentagon face
  brush.wash(PAL.primer, 240);
  drawPoly(nutTop);
  brush.noWash();

  brush.set("rotring", PAL.inkBlack, 0.42);
  strokePoly(collarBot, false);
  strokePoly([nutBot[0], nutBot[1], nutTop[1], nutTop[0]], true);
  strokePoly([nutBot[1], nutBot[2], nutTop[2], nutTop[1]], true);
  strokePoly(nutTop, true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
