  });
}

// ============================================================================
// COORDINATE SYSTEM: Forearm local space (u along arm, v across arm) -> Canvas
// ============================================================================
const ARM_CX = 600;
const ARM_CY = 615;
const ARM_ANGLE = -16;
const COS_A = Math.cos((ARM_ANGLE * Math.PI) / 180);
const SIN_A = Math.sin((ARM_ANGLE * Math.PI) / 180);

function P(u, v) {
  return [
    ARM_CX + u * COS_A - v * SIN_A,
    ARM_CY + u * SIN_A + v * COS_A
  ];
}

function PW(u, v, w) {
  return [
    ARM_CX + u * COS_A - v * SIN_A,
    ARM_CY + u * SIN_A + v * COS_A,
    w
  ];
}

// Anatomical top and bottom contours of the forearm in local v-coordinates
function topV(u) {
  let t = (u + 750) / 1500; // 0 at wrist (-750), 1 at elbow (+750)
  let base = -215 - 105 * Math.pow(t, 0.75);
  // Swell of brachioradialis muscle around u = 180..450
  let muscle = -28 * Math.exp(-Math.pow((u - 260) / 260, 2));
  // Slight wrist narrowing around u = -480
  let wrist = 16 * Math.exp(-Math.pow((u + 480) / 180, 2));
  return base + muscle + wrist;
}

function botV(u) {
  let t = (u + 750) / 1500;
  let base = 205 + 115 * Math.pow(t, 0.85);
  // Flexor belly curve around u = 120..380
  let belly = 24 * Math.exp(-Math.pow((u - 200) / 280, 2));
  let wrist = -14 * Math.exp(-Math.pow((u + 460) / 190, 2));
  return base + belly + wrist;
}

// Helper for safe polygon rendering
function polyWash(pts, col, alpha = 255) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  let p = new brush.Polygon(pts);
  p.wash(col, alpha);
  brush.noWash();
}

function polyFill(pts, col, alpha = 120, bleed = 0.25, tex = 0.3) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  let p = new brush.Polygon(pts);
  p.fill(col, alpha, bleed, tex);
  brush.noFill();
}

function polyStroke(pts, brushName, col, weight = 1, closed = true) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  let sp = pts.map(pt => [pt[0], pt[1], pt[2] !== undefined ? pt[2] : 1]);
  if ( closed ) {
    sp.push([pts[0][0], pts[0][1], 1]);
  }
  brush.spline(sp, 0.35);
}

// Interpolate between two point arrays for whip-shading
function lerpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function samplePolyline(pts, t) {
  if (t <= 0) return pts[0];
  if (t >= 1) return pts[pts.length - 1];
  let total = pts.length - 1;
  let idx = Math.floor(t * total);
  let frac = t * total - idx;
  if (idx >= total) return pts[total];
  return lerpPt(pts[idx], pts[idx + 1], frac);
}

// ============================================================================
// DOTTED WHIP-SHADING ENGINE (American Traditional Coil/Magnum Stipple)
// ============================================================================
function whipShadeBand(rootCurveUV, tipCurveUV, opts = {}) {
  let stepsAlong = opts.stepsAlong || 38;
  let numDotsPerRay = opts.dotsPerRay || 14;
  let solidFrac = opts.solidFrac !== undefined ? opts.solidFrac : 0.22;
  let col = opts.color || "#0d0e12";
  let curveBend = opts.bend || 0;

  let rootPts = rootCurveUV.map(p => P(p[0], p[1]));
  let tipPts = tipCurveUV.map(p => P(p[0], p[1]));

  // 1. Solid black base band near the root curve
  if (solidFrac > 0.02) {
    let basePoly = [];
    for (let i = 0; i <= 16; i++) {
      basePoly.push(samplePolyline(rootPts, i / 16));
    }
    for (let i = 16; i >= 0; i--) {
      let s = i / 16;
      let rPt = samplePolyline(rootPts, s);
      let tPt = samplePolyline(tipPts, s);
      let jitter = (noise(s * 8, rPt[0] * 0.02) - 0.5) * 0.12;
      basePoly.push(lerpPt(rPt, tPt, Math.max(0.05, solidFrac + jitter)));
    }
    polyWash(basePoly, col, 245);
  }

  // 2. Whip-shaded magnum needle stipple trajectories from root to tip
  for (let i = 0; i <= stepsAlong; i++) {
    let s = i / stepsAlong;
    let rPt = samplePolyline(rootPts, s);
    let tPt = samplePolyline(tipPts, s);
    let dx = tPt[0] - rPt[0];
    let dy = tPt[1] - rPt[1];
    let dist = Math.hypot(dx, dy);
    if (dist < 2) continue;

    // Perpendicular vector for whip arc curvature
    let nx = -dy / dist;
    let ny = dx / dist;

    // Short solid whip flick emerging from the black root
    let flickEnd = Math.min(0.55, solidFrac + random(0.12, 0.28));
    let fPt = lerpPt(rPt, tPt, flickEnd);
    fPt[0] += nx * curveBend * Math.sin(flickEnd * Math.PI);
    fPt[1] += ny * curveBend * Math.sin(flickEnd * Math.PI);
    brush.set("rotring", col, random(1.1, 1.9));
    brush.line(rPt[0], rPt[1], fPt[0], fPt[1]);

    // Dotted stipple trail fading toward tipCurve
    for (let j = 0; j < numDotsPerRay; j++) {
      let uFrac = solidFrac * 0.7 + (1 - solidFrac * 0.7) * Math.pow(j / numDotsPerRay, 0.85);
      uFrac += random(-0.04, 0.04);
      if (uFrac < 0.05 || uFrac > 0.98) continue;

      // Drop-off probability toward open skin break
      if (random() > Math.pow(1 - uFrac, 0.55) * 1.15) continue;

      let bx = rPt[0] + dx * uFrac + nx * curveBend * Math.sin(uFrac * Math.PI) + random(-1.8, 1.8);
      let by = rPt[1] + dy * uFrac + ny * curveBend * Math.sin(uFrac * Math.PI) + random(-1.8, 1.8);

      let w = map(uFrac, 0.1, 1.0, 1.65, 0.55) * random(0.8, 1.2);
      brush.set("needle_dot", col, w);
      let stepLen = map(uFrac, 0.1, 1.0, 2.8, 0.9);
      let dirX = dx / dist;
      let dirY = dy / dist;
      brush.line(bx, by, bx + dirX * stepLen, by + dirY * stepLen);
    }
  }
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================
function draw() {
  translate(-width / 2, -height / 2);
  background("#140c08");

  drawStudioLeatherBackground();
  drawForearmBaseAndVolume();
  drawInflammationAndErythema();
  drawSkinPoresAndHairs(false); // Under-tattoo & peripheral skin texture
  drawTraditionalPantherTattoo();
  drawSkinPoresAndHairs(true);  // Hairs and pores overlapping/surrounding
  drawTrappedPlasmaAndInk();
  drawClingFilmWrap();

  noLoop();
}

