// ============================================================================
// 2. FOREARM SILHOUETTE & VOLUMETRIC FLESH MODELING
// ============================================================================
function buildArmStripPolygon(uMin, uMax, vFracTop, vFracBot, steps = 32) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let u = lerp(uMin, uMax, i / steps);
    let v = lerp(topV(u), botV(u), vFracTop);
    pts.push(P(u, v));
  }
  for (let i = steps; i >= 0; i--) {
    let u = lerp(uMin, uMax, i / steps);
    let v = lerp(topV(u), botV(u), vFracBot);
    pts.push(P(u, v));
  }
  return pts;
}

function drawForearmBaseAndVolume() {
  // 1. Opaque base silhouette of the forearm
  let fullArm = buildArmStripPolygon(-800, 800, 0.0, 1.0, 40);
  polyWash(fullArm, "#d99b7e", 255);

  // 2. Cylindrical 3D shading bands from top contour to bottom contour
  let bands = [
    { t0: 0.00, t1: 0.08, col: "#8c4c38", a: 190 }, // Turning top edge shadow
    { t0: 0.03, t1: 0.16, col: "#b86d54", a: 170 }, // Upper slope warm transition
    { t0: 0.10, t1: 0.30, col: "#de9d80", a: 180 }, // Upper midtone
    { t0: 0.20, t1: 0.52, col: "#f0bca3", a: 210 }, // Broad dorsal lit zone
    { t0: 0.28, t1: 0.44, col: "#fae3cf", a: 165 }, // Central studio light ridge
    { t0: 0.48, t1: 0.72, col: "#d48d6f", a: 180 }, // Lower midtone roll-off
    { t0: 0.65, t1: 0.88, col: "#a65b43", a: 200 }, // Core shadow along ulna
    { t0: 0.80, t1: 0.96, col: "#783927", a: 215 }, // Deep warm underside shadow
    { t0: 0.91, t1: 1.00, col: "#573129", a: 210 }  // Reflected studio shadow edge
  ];

  for (let b of bands) {
    let strip = buildArmStripPolygon(-800, 800, b.t0, b.t1, 32);
    polyWash(strip, b.col, b.a);
  }

  // 3. Organic watercolor skin mottling (warm peach, golden ochre, cool olive, rose)
  let mottles = [
    { u: -520, v: -60, ru: 180, rv: 110, col: "#f5cdb6", a: 75 },
    { u: -380, v: 90,  ru: 210, rv: 120, col: "#c97b63", a: 70 },
    { u: 440,  v: -90, ru: 220, rv: 140, col: "#f2c2a7", a: 80 },
    { u: 480,  v: 130, ru: 240, rv: 130, col: "#b5654d", a: 85 },
