    { u: -580, v: 30,  ru: 160, rv: 140, col: "#d69c78", a: 65 },
    { u: 580,  v: -30, ru: 180, rv: 160, col: "#e8b092", a: 70 }
  ];

  for (let m of mottles) {
    let pts = [];
    for (let a = 0; a < 360; a += 20) {
      let n = 0.8 + 0.35 * noise(m.u * 0.01 + cos(a), m.v * 0.01 + sin(a));
      let u = m.u + cos(a) * m.ru * n;
      let v = constrain(m.v + sin(a) * m.rv * n, topV(u) + 6, botV(u) - 6);
      pts.push(P(u, v));
    }
    polyFill(pts, m.col, m.a, 0.38, 0.3);
