    [[-560, 62], [-430, 15], [-310, -25]],
    [[-680, -95], [-510, -120], [-350, -155], [-160, -195]],
    [[260, 195], [410, 165], [570, 140], [720, 125]],
    [[310, -210], [470, -185], [640, -150]]
  ];

  for (let vPath of veins) {
    let pts = vPath.map(p => P(p[0], p[1]));
    brush.set("marker", "#4f757a", 1.1);
    brush.spline(pts.map(p => [p[0], p[1], 0.6]), 0.45);
    brush.set("charcoal", "#e8a892", 1.6);
    brush.spline(pts.map(p => [p[0] + 2, p[1] + 2, 0.5]), 0.45);
