  // Broad outer erythema flare around all parts of the flash
  let outerZones = [
    { u: -130, v: -20, ru: 240, rv: 210, col: "#e35664", a: 85 }, // Head & jaws halo
    { u: 90,   v: -45, ru: 260, rv: 190, col: "#de4b5a", a: 80 }, // Torso & spine halo
    { u: -260, v: 95,  ru: 190, rv: 145, col: "#e65060", a: 90 }, // Front slashing paw & slashes
    { u: -250, v: -135, ru: 165, rv: 115, col: "#df5262", a: 80 }, // Raised right paw & leaf
    { u: -35,  v: 120, ru: 185, rv: 145, col: "#e84858", a: 95 }, // Scarlet rose halo
    { u: 235,  v: 105, ru: 165, rv: 135, col: "#db4d5c", a: 80 }, // Hind leg halo
