  for (let z of outerZones) {
    let pts = [];
    for (let a = 0; a < 360; a += 18) {
      let n = 0.82 + 0.32 * noise(z.u * 0.015 + cos(a) * 1.3, z.v * 0.015 + sin(a) * 1.3);
      let u = z.u + cos(a) * z.ru * n;
