  let hotZones = [
    { u: -140, v: -15, ru: 185, rv: 160, col: "#d4263b", a: 95 },
    { u: 60,   v: -35, ru: 210, rv: 150, col: "#cf2338", a: 90 },
    { u: -275, v: 105, ru: 145, rv: 110, col: "#db253b", a: 100 },
