// ============================================================================
// 4. HYPERREAL SKIN PORES, LANGER'S LINES & FINE HAIRS
// ============================================================================
function drawSkinPoresAndHairs(isOverPass) {
  let count = isOverPass ? 750 : 2200;

  // Skin pores and microscopic diamond sulci cutis (Langer's lines)
  for (let i = 0; i < count; i++) {
    let u = random(-730, 730);
    let tV = topV(u);
    let bV = botV(u);
    let v = random(tV + 6, bV - 6);

    // On over-pass, stay outside the solid core of the tattoo or in skin-breaks
    let inTattooBox = u > -380 && u < 390 && v > -220 && v < 220;
    if (isOverPass && inTattooBox && random() < 0.72) continue;

    let pt = P(u, v);
    let vNorm = (v - tV) / (bV - tV); // 0 top, 1 bottom

    // Determine pore color based on inflammation and cylindrical lighting
    let isInflamed = u > -440 && u < 440 && v > -255 && v < 245 &&
                     Math.hypot(u / 430, v / 245) < 1.05;

    let poreCol;
    if (isInflamed) {
      poreCol = random(["#9e1e30", "#b82e40", "#7d1424", "#c94455"]);
    } else if (vNorm > 0.68) {
      poreCol = random(["#5c281b", "#733424", "#4a1e13"]);
    } else if (vNorm < 0.22) {
      poreCol = random(["#7d402d", "#96513c"]);
    } else {
      poreCol = random(["#a85d44", "#bd6f55", "#8f4934", "#c97d63"]);
    }

    // Tiny follicular pore dot
    brush.set("rotring", poreCol, random(0.45, 0.95));
    let ang = (ARM_ANGLE + random(-35, 35)) * (Math.PI / 180);
    let len = random(0.8, 2.2);
    brush.line(pt[0], pt[1], pt[0] + Math.cos(ang) * len, pt[1] + Math.sin(ang) * len);

    // Occasional wet skin micro-glint beside pore on dorsal lit surface
    if (vNorm > 0.18 && vNorm < 0.58 && random() < 0.16) {
      brush.set("rotring", isInflamed ? "#ffc4cc" : "#fff2e8", random(0.4, 0.75));
      brush.line(pt[0] + 1.2, pt[1] - 1.2, pt[0] + 2.4, pt[1] - 0.8);
    }
  }

  // Fine Langer's line skin crease cross-hatching
  let creaseCount = isOverPass ? 120 : 380;
  for (let i = 0; i < creaseCount; i++) {
    let u = random(-700, 700);
    let v = random(topV(u) + 12, botV(u) - 12);
    if (isOverPass && u > -360 && u < 370 && v > -200 && v < 200) continue;

    let p1 = P(u, v);
    let diag = random() < 0.5 ? 28 : -28;
    let p2 = P(u + random(8, 18), v + (diag > 0 ? random(5, 12) : random(-12, -5)));
    let isInflamed = Math.hypot(u / 420, v / 235) < 1.0;
    brush.set("2H", isInflamed ? "#b02e3f" : "#9c563f", random(0.35, 0.65));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Fine forearm hairs (shaved in the immediate tattoo center, natural along edges & wrist/elbow)
  if (isOverPass) {
    // 1. Tiny shaved follicle stubble dots inside the shaved tattoo prep area
    for (let i = 0; i < 190; i++) {
      let u = random(-460, 440);
      let v = random(topV(u) + 20, botV(u) - 20);
      // Avoid solid black panther interior
      if (u > -340 && u < 340 && v > -170 && v < 160 && random() < 0.82) continue;
      let pt = P(u, v);
      brush.set("rotring", "#2e1b12", random(0.65, 1.1));
      brush.line(pt[0], pt[1], pt[0] + 1.8, pt[1] + 0.8);
    }

    // 2. Full fine arm hairs along outer dorsal/ventral borders and un-shaved wrist/elbow ends
    for (let i = 0; i < 340; i++) {
      let u = random(-730, 730);
      let tV = topV(u);
      let bV = botV(u);
      let v;
      // Place hairs on outer margins or beyond the shaved central patch
      if (Math.abs(u) > 430 && random() < 0.65) {
        v = random(tV + 5, bV - 5);
      } else {
        v = random() < 0.55
          ? random(tV + 4, tV + 75)
          : random(bV - 85, bV - 4);
      }

      // Hair flows toward the wrist/ulnar side with natural curve
      let hairLenU = random(-42, -22);
      let hairLenV = v < 0 ? random(8, 24) : random(-18, 14);

      // If under cling film (-520 < u < 490), some hairs are pressed flat and kinked
      let underFilm = u > -520 && u < 490;
      let midU = u + hairLenU * 0.5 + (underFilm ? random(-6, 6) : 0);
      let midV = v + hairLenV * 0.55 + (underFilm ? random(-8, 8) : random(-3, 3));

      let p0 = P(u, v);
      let p1 = P(midU, midV);
      let p2 = P(u + hairLenU, v + hairLenV);

      let hairCol = random(["#1f120b", "#2e1b10", "#3d2517", "#170d08"]);
      brush.set("rotring", hairCol, random(0.45, 0.9));
      brush.spline([
        [p0[0], p0[1], 1.1],
        [p1[0], p1[1], 0.85],
        [p2[0], p2[1], 0.2]
      ], 0.45);
    }
  }
}

// ============================================================================
// 5. THE AMERICAN TRADITIONAL PANTHER TATTOO (THE FLASH)
// ============================================================================
function drawTraditionalPantherTattoo() {
  // Palette: Vivid, saturated American Traditional flash pigments
  const INK_BLACK   = "#0c0d12";
  const INK_CHAR    = "#161821";
  const SCARLET     = "#e6152b";
  const SCARLET_BRT = "#ff293e";
  const SCARLET_DRK = "#9e0818";
  const CANARY      = "#ffdd00";
  const CANARY_BRT  = "#ffea42";
  const CANARY_GOLD = "#f29c00";
  const JADE        = "#00a669";
  const JADE_BRT    = "#00cc82";
  const JADE_DRK    = "#045c3a";
  const SKIN_BREAK  = "#f2969c"; // Inflamed skin showing in traditional skin-breaks

  // --------------------------------------------------------------------------
  // A. CANARY YELLOW FLASH SUNBURST / HALO RAYS (Graphic flat yellow fills)
  // --------------------------------------------------------------------------
  let yellowRays = [
    // Upper-left ray behind head
    [[-175, -105], [-265, -210], [-185, -180], [-145, -225], [-105, -135]],
    // Upper-center ray behind shoulder
    [[-65, -115], [-95, -230], [-25, -185], [35, -235], [45, -120]],
    // Upper-right ray behind back/tail
    [[95, -90], [135, -205], [185, -160], [245, -195], [205, -80]],
    // Lower-right ray behind hind leg
    [[145, 35], [285, 45], [245, 95], [310, 140], [175, 110]],
    // Lower-left ray behind rose & front leg
    [[-125, 85], [-235, 195], [-155, 180], [-115, 225], [-55, 135]]
  ];

  for (let ray of yellowRays) {
    let pts = ray.map(p => P(p[0], p[1]));
    polyWash(pts, CANARY, 250);

    // Warm golden core toward center of flash
    let innerPts = [pts[0], lerpPt(pts[0], pts[1], 0.55), pts[2], lerpPt(pts[4], pts[3], 0.55), pts[4]];
    polyWash(innerPts, CANARY_GOLD, 165);

    // Dotted whip-shading at the root of each yellow ray
    whipShadeBand([ray[0], ray[4]], [ray[1], ray[2], ray[3]], {
      stepsAlong: 18,
      dotsPerRay: 10,
      solidFrac: 0.12,
      color: INK_BLACK
    });

    // Bold black traditional outline
    polyStroke(pts, "pen", INK_BLACK, 3.2, true);
  }

  // --------------------------------------------------------------------------
  // B. JADE GREEN TRADITIONAL SERRATED ROSE LEAVES
  // --------------------------------------------------------------------------
  let jadeLeaves = [
    { // Leaf 1: Top-left flanking raised paw
      base: [-210, -130], tip: [-335, -195],
      sideA: [[-245, -185], [-285, -205], [-315, -205]],
      sideB: [[-245, -120], [-285, -140], [-320, -168]]
    },
    { // Leaf 2: Bottom-left under scarlet rose
      base: [-95, 145], tip: [-210, 220],
      sideA: [[-145, 145], [-180, 170], [-205, 195]],
      sideB: [[-105, 190], [-145, 215], [-180, 225]]
    },
    { // Leaf 3: Bottom-center-right under rose
      base: [20, 140], tip: [135, 220],
      sideA: [[25, 185], [65, 210], [105, 225]],
      sideB: [[65, 140], [105, 165], [128, 195]]
    },
    { // Leaf 4: Mid-right under tail arch
      base: [235, -25], tip: [365, 25],
      sideA: [[280, -35], [325, -20], [355, 2]],
      sideB: [[265, 22], [305, 35], [340, 35]]
    },
    { // Leaf 5: Upper-center tucked behind shoulder
      base: [45, -115], tip: [95, -225],
      sideA: [[30, -160], [50, -195], [75, -218]],
      sideB: [[85, -140], [105, -175], [105, -205]]
    }
  ];

  for (let lf of jadeLeaves) {
    let uvOutline = [
      lf.base,
      lf.sideA[0], [lf.sideA[0][0] + 6, lf.sideA[0][1] + 8],
      lf.sideA[1], [lf.sideA[1][0] + 5, lf.sideA[1][1] + 7],
      lf.sideA[2],
      lf.tip,
      lf.sideB[2], [lf.sideB[1][0] + 5, lf.sideB[1][1] - 7],
      lf.sideB[1], [lf.sideB[0][0] + 6, lf.sideB[0][1] - 8],
      lf.sideB[0]
    ];
    let pts = uvOutline.map(p => P(p[0], p[1]));

    // Flat Jade fill
    polyWash(pts, JADE, 255);

    // Bright Jade highlight along sideA edge (skin-break / light side)
    let hiPts = [lf.base, lf.sideA[0], lf.sideA[1], lf.sideA[2], lf.tip].map(p => P(p[0], p[1]));
    polyWash(hiPts, JADE_BRT, 180);

    // Deep Jade shadow on sideB
    let shPts = [lf.base, lf.sideB[0], lf.sideB[1], lf.sideB[2], lf.tip].map(p => P(p[0], p[1]));
