    polyWash([pts[0], lerpPt(pts[0], pts[1], 0.55), pts[2]], CANARY, 210);
    polyStroke(pts, "pen", INK_BLACK, 3.0, true);
  }
  // Lower incisors
  for (let k = 0; k < 4; k++) {
    let u0 = -156 + k * 9.5;
    let inc = [[u0, 40], [u0 + 4.5, 30], [u0 + 9, 40]].map(p => P(p[0], p[1]));
    polyWash(inc, "#fffbe6", 255);
    polyStroke(inc, "pen", INK_BLACK, 2.3, true);
  }

  // Dynamic S-Curving Scarlet Tongue Thrusting Out of the Jaws
  let tongueUV = [
    [-125, 22], [-148, 20], [-175, 25], [-208, 36], [-235, 38],
    [-248, 26], [-238, 15], [-218, 22], [-192, 46], [-158, 52],
    [-128, 42], [-115, 30]
  ];
  let tonguePts = tongueUV.map(p => P(p[0], p[1]));
  polyWash(tonguePts, SCARLET, 255);
  // Bright scarlet highlight along upper curve of tongue
  polyWash(tongueUV.slice(2, 9).map(p => P(p[0], p[1])), SCARLET_BRT, 210);
  // Whip-shading at root of tongue inside throat
  whipShadeBand(
    [[-125, 22], [-118, 35]],
    [[-165, 26], [-162, 46]],
    { stepsAlong: 14, dotsPerRay: 9, solidFrac: 0.22, color: INK_BLACK }
  );
  polyStroke(tonguePts, "pen", INK_BLACK, 3.4, true);
  // Central tongue groove line
  let groovePts = [[-128, 30], [-162, 34], [-198, 38], [-226, 30]].map(p => P(p[0], p[1]));
  polyStroke(groovePts, "pen", INK_BLACK, 2.6, false);

  // Upper Canine Fangs & Incisors (Overlapping top of mouth)
  let upperFangs = [
    [[-178, 0], [-170, 28], [-158, 2]], // Upper left canine
    [[-118, 2], [-106, 28], [-98, 0]]   // Upper right canine
  ];
  for (let fg of upperFangs) {
    let pts = fg.map(p => P(p[0], p[1]));
    polyWash(pts, "#fffbe6", 255);
    polyWash([pts[0], lerpPt(pts[0], pts[1], 0.55), pts[2]], CANARY, 210);
    polyStroke(pts, "pen", INK_BLACK, 3.2, true);
  }
  for (let k = 0; k < 4; k++) {
    let u0 = -156 + k * 9.5;
    let inc = [[u0, 2], [u0 + 4.5, 12], [u0 + 9, 2]].map(p => P(p[0], p[1]));
    polyWash(inc, "#fffbe6", 255);
    polyStroke(inc, "pen", INK_BLACK, 2.3, true);
  }

  // Re-stroke bold head contour & whisker lines
  polyStroke(headSkullUV.map(p => P(p[0], p[1])), "pen", INK_BLACK, 4.2, true);

  let whiskers = [
    [[-188, -12], [-225, -22], [-258, -18]],
    [[-190, -2],  [-228, -5],  [-262, 6]],
    [[-88, -12],  [-52, -22],  [-18, -18]],
    [[-86, -2],   [-48, -5],   [-14, 6]]
  ];
  for (let wh of whiskers) {
    polyStroke(wh.map(p => P(p[0], p[1])), "pen", INK_BLACK, 2.8, false);
  }
}

// ============================================================================
// 6. BEADS OF PLASMA, SEEPING INK & WETNESS TRAPPED UNDER PLASTIC
// ============================================================================
function drawTrappedPlasmaAndInk() {
  // 1. Weeping liquefied ink & serous plasma puddles pressed flat between skin and plastic
  let puddles = [
    { u: -155, v: 45,  ru: 55, rv: 35, col: "#241118", a: 115 }, // Dark ink/plasma under jaw
    { u: -45,  v: 135, ru: 65, rv: 45, col: "#8f1424", a: 105 }, // Crimson plasma over rose
    { u: 55,   v: -55, ru: 75, rv: 42, col: "#1c1218", a: 110 }, // Inky smear over ribs
    { u: -275, v: 95,  ru: 60, rv: 45, col: "#7a1824", a: 105 }, // Plasma pool over slashes
    { u: 215,  v: 85,  ru: 50, rv: 38, col: "#29141a", a: 100 }, // Haunch ink ooze
    { u: -95,  v: -95, ru: 58, rv: 36, col: "#b83228", a: 95 },  // Amber-blood plasma pool
    { u: 145,  v: 15,  ru: 62, rv: 34, col: "#c44935", a: 90 }   // Serous fluid pocket
  ];

  for (let pd of puddles) {
    let pts = [];
    for (let a = 0; a < 360; a += 24) {
      let n = 0.7 + 0.45 * noise(pd.u * 0.03 + cos(a) * 1.5, pd.v * 0.03 + sin(a) * 1.5);
      pts.push(P(pd.u + cos(a) * pd.ru * n, pd.v + sin(a) * pd.rv * n));
    }
    polyFill(pts, pd.col, pd.a, 0.42, 0.5);
  }

  // 2. Discrete beads of plasma, blood, and ink trapped under the cling film
  let numBeads = 230;
  for (let i = 0; i < numBeads; i++) {
    // Cluster beads around the tattoo perimeter and along plastic crease channels
    let u = random(-450, 440);
    let v = random(-235, 225);
    if (v < topV(u) + 18 || v > botV(u) - 18) continue;

    let distTattoo = Math.hypot(u / 390, v / 215);
    if (distTattoo > 1.12 && random() < 0.75) continue;

    let r = random() < 0.18 ? random(6.5, 13.5) : random(2.2, 6.2);
    let stretch = random(1.0, 1.55);
    let rot = random(360);

    // Choose fluid type: serous amber-pink plasma, crimson blood-plasma, or black ink-plasma bead
    let typeRand = random();
    let bodyCol, rimCol;
    if (typeRand < 0.42) {
      // Amber-rose serous plasma
      bodyCol = random(["#e05848", "#eb785b", "#d4463b", "#f08c6e"]);
      rimCol  = "#7a1b24";
    } else if (typeRand < 0.75) {
      // Angry crimson blood-plasma droplet
      bodyCol = random(["#b81428", "#cf1d32", "#960c1e"]);
      rimCol  = "#4a0610";
    } else {
      // Weeping black/charcoal ink mixed with plasma
      bodyCol = random(["#18141c", "#261820", "#331922"]);
      rimCol  = "#0a080c";
    }

    let cPt = P(u, v);
    let beadPts = [];
    for (let a = 0; a < 360; a += 36) {
      let radA = r * (0.88 + 0.24 * noise(i * 10 + cos(a), sin(a)));
      let lx = cos(a) * radA * stretch;
      let ly = sin(a) * radA;
      let rx = lx * cos(rot) - ly * sin(rot);
      let ry = lx * sin(rot) + ly * cos(rot);
      beadPts.push([cPt[0] + rx, cPt[1] + ry]);
    }

    // Translucent fluid bead body + meniscus rim
    polyWash(beadPts, bodyCol, random(155, 220));
    polyStroke(beadPts, "rotring", rimCol, map(r, 2, 14, 0.5, 1.3), true);

    // Razor-sharp white specular pinpoint highlight on top-left of every wet bead
    let hiX = cPt[0] - r * 0.32;
    let hiY = cPt[1] - r * 0.35;
    brush.set("film_specular", "#ffffff", map(r, 2, 14, 0.75, 1.9));
    brush.line(hiX, hiY, hiX + r * 0.42, hiY + r * 0.12);

    // Secondary reflected light crescent on larger beads
    if (r > 6.5) {
      brush.set("rotring", "#ffd6de", 0.8);
      brush.line(cPt[0] + r * 0.25, cPt[1] + r * 0.32, cPt[0] + r * 0.5, cPt[1] + r * 0.15);
    }
  }
}

// ============================================================================
// 7. THE CLING FILM WRAP & SHARP WHITE SPECULAR CREASES
// ============================================================================
function drawClingFilmWrap() {
  const WRAP_LEFT  = -535;
  const WRAP_RIGHT = 495;

  // 1. Subtle glossy plastic sheen bands across the wrapped forearm zone
  let sheenBands = [
    { u0: -490, u1: -260, u2: -140, u3: -380, a: 22, col: "#e4f0fc" },
    { u0: -210, u1: 30,   u2: 160,  u3: -90,  a: 25, col: "#ffffff" },
    { u0: 80,   u1: 340,  u2: 460,  u3: 210,  a: 22, col: "#e4f0fc" },
    // Horizontal dorsal cylinder reflection strip along the main ridge of the arm
    { isHorizontal: true, v0: -135, v1: -15, a: 24, col: "#ffffff" }
  ];

  for (let sb of sheenBands) {
    if (sb.isHorizontal) {
      let hPts = [];
      for (let u = WRAP_LEFT; u <= WRAP_RIGHT; u += 45) hPts.push(P(u, sb.v0 + sin(u * 0.8) * 8));
      for (let u = WRAP_RIGHT; u >= WRAP_LEFT; u -= 45) hPts.push(P(u, sb.v1 + cos(u * 0.8) * 8));
      polyWash(hPts, sb.col, sb.a);
    } else {
      let dPts = [
        P(sb.u0, topV(sb.u0) - 6),
        P(sb.u1, topV(sb.u1) - 6),
        P(sb.u2, botV(sb.u2) + 6),
        P(sb.u3, botV(sb.u3) + 6)
      ];
      polyWash(dPts, sb.col, sb.a);
    }
  }

  // 2. Protruding crinkled plastic wrap silhouette along top and bottom forearm edges
  for (let side of [-1, 1]) {
    let edgePts = [];
    for (let u = WRAP_LEFT; u <= WRAP_RIGHT; u += 22) {
      let baseV = side < 0 ? topV(u) : botV(u);
      let crinkleOffset = side * (6 + 14 * Math.pow(noise(u * 0.035, side * 10), 1.4));
      edgePts.push(P(u, baseV + crinkleOffset));
    }
    // Thin translucent plastic overhang lip
    let returnPts = [];
    for (let u = WRAP_RIGHT; u >= WRAP_LEFT; u -= 22) {
      let baseV = side < 0 ? topV(u) : botV(u);
      returnPts.push(P(u, baseV - side * 8));
    }
    polyWash([...edgePts, ...returnPts], "#e8f2fa", 38);
    polyStroke(edgePts, "film_specular", "#ffffff", 1.35, false);
    polyStroke(edgePts.map(p => [p[0], p[1] + side * 2.5]), "rotring", "#2b161c", 0.75, false);
  }

  // 3. Trapped air-bubble pockets under the film (around tattoo contour swells)
  let airPockets = [
    [[-320, -45], [-275, -52], [-255, -25], [-295, -15]],
    [[-85, 65],   [-45, 58],   [-32, 85],   [-75, 92]],
    [[115, -125], [168, -132], [178, -105], [125, -98]],
    [[165, 65],   [205, 58],   [212, 88],   [172, 92]],
    [[-215, 145], [-165, 138], [-155, 168], [-205, 172]],
    [[285, -55],  [335, -62],  [342, -32],  [292, -28]]
  ];
  for (let ap of airPockets) {
    let pts = ap.map(p => P(p[0], p[1]));
    polyWash(pts, "#f0f7ff", 42);
    polyStroke(pts, "rotring", "#ffffff", 1.2, true);
  }

  // 4. Primary Tension Creases & Wrinkle Networks (Lifted out in sharp white)
  let mainCreasesUV = [
    // Long diagonal tension folds sweeping across the panther tattoo
    [[-515, -185], [-410, -110], [-285, -35], [-165, 35], [-45, 125], [65, 225]],
    [[-460, -225], [-320, -145], [-185, -58], [-72, 18], [55, 98], [195, 245]],
    [[-310, -255], [-195, -165], [-92, -72], [18, 12], [142, 115], [275, 265]],
    [[-145, -278], [-35, -175], [68, -75], [175, 25], [295, 145], [415, 285]],
    [[45, -305],   [145, -195], [242, -88], [345, 35], [455, 185]],
    // Counter-diagonal intersecting tension creases (forming stretched plastic diamonds)
    [[-485, 215], [-365, 115], [-235, 28], [-115, -52], [15, -145], [145, -265]],
    [[-335, 245], [-215, 138], [-98, 42], [25, -48], [158, -155], [295, -295]],
    [[-125, 272], [-12, 158], [108, 52], [228, -58], [358, -182], [468, -305]],
    [[95, 295],   [198, 175], [295, 62], [395, -65], [485, -195]],
    // Short sharp branch kinks radiating off main creases
    [[-285, -35], [-235, -8], [-175, -12]],
    [[-185, -58], [-132, -32], [-78, -38]],
    [[-92, -72],  [-35, -45],  [28, -55]],
    [[68, -75],   [125, -52],  [192, -62]],
    [[-215, 138], [-145, 118], [-75, 132]],
    [[108, 52],   [172, 38],   [238, 52]]
  ];

  for (let cr of mainCreasesUV) {
    let pts = cr.map(p => P(p[0], p[1]));

    // (a) Narrow dark refractive shadow line right under the plastic fold
    let shadowPts = pts.map(p => [p[0] + 2.5, p[1] + 3.2, 0.9]);
    brush.set("2H", "#1f0e14", 1.15);
    brush.spline(shadowPts, 0.25);

    // (b) Soft cool blue-white specular glow halo along the ridge
    let glowPts = pts.map((p, idx) => [
      p[0], p[1],
      idx === 0 || idx === pts.length - 1 ? 0.4 : 1.2
    ]);
    brush.set("charcoal", "#dcebfa", 1.35);
    brush.spline(glowPts, 0.25);

    // (c) Razor-sharp bright white specular crease line
    let specPts = pts.map((p, idx) => {
      let w = idx === 0 || idx === pts.length - 1 ? 0.35 : random(1.15, 1.85);
      return [p[0], p[1], w];
    });
    brush.set("film_specular", "#ffffff", 1.55);
    brush.spline(specPts, 0.22);

    // (d) Double-edge parallel micro-refraction line on taut plastic segments
    for (let k = 0; k < pts.length - 1; k++) {
      if (random() < 0.65) {
        let a = pts[k];
        let b = pts[k + 1];
        let m = lerpPt(a, b, 0.55);
        brush.set("rotring", "#ffffff", random(0.85, 1.45));
        brush.line(a[0] - 2.5, a[1] - 2.2, m[0] - 2.5, m[1] - 2.2);
      }
    }
  }

  // 5. Sharp triangular & diamond specular facets where plastic creases kink and intersect
  let specularFacetsUV = [
    [[-188, -58], [-162, -64], [-172, -42]],
    [[-95, -72],  [-65, -78],  [-78, -55]],
    [[-118, -52], [-88, -58],  [-102, -36]],
    [[22, -48],   [55, -55],   [38, -32]],
    [[65, -75],   [98, -82],   [82, -56]],
    [[-235, 28],  [-202, 22],  [-218, 45]],
    [[-72, 18],   [-42, 12],   [-56, 36]],
    [[18, 12],    [48, 6],     [32, 30]],
    [[172, 25],   [205, 18],   [188, 42]],
    [[-215, 138], [-182, 130], [-198, 155]],
    [[105, 52],   [138, 45],   [120, 68]],
    [[242, -88],  [275, -95],  [258, -68]],
    [[-320, -145], [-288, -152], [-302, -128]]
  ];

  for (let fc of specularFacetsUV) {
    let pts = fc.map(p => P(p[0], p[1]));
    polyWash(pts, "#ffffff", 225);
    polyStroke(pts, "film_specular", "#ffffff", 1.4, true);
  }

  // 6. Bunched, gathered cling-film seams at the left wrist end (u ≈ -535) and right elbow end (u ≈ +495)
  for (let endU of [WRAP_LEFT, WRAP_RIGHT]) {
    let tV = topV(endU) - 10;
    let bV = botV(endU) + 10;

    // 9 overlapping gathered plastic ribbon folds at each end of the wrap
    for (let f = 0; f < 9; f++) {
      let foldPts = [];
      let steps = 10;
      for (let s = 0; s <= steps; s++) {
        let v = lerp(tV, bV, s / steps);
        let wave = sin(s * 38 + f * 45) * random(8, 22) + (f - 4) * 5.5;
        foldPts.push(P(endU + wave, v));
      }

      // Translucent gathered plastic shadow
      brush.set("2H", "#26151a", 1.1);
      brush.spline(foldPts.map(p => [p[0] + 2, p[1] + 2, 0.9]), 0.35);

      // Sharp white bunched plastic highlights
      brush.set("film_specular", "#ffffff", random(1.1, 2.1));
      brush.spline(foldPts.map(p => [p[0], p[1], random(0.6, 1.5)]), 0.35);
    }

    // Short tension crinkles pulling inward from the bunched wrap borders
    let dir = endU < 0 ? 1 : -1;
    for (let c = 0; c < 18; c++) {
      let v0 = random(tV + 18, bV - 18);
      let lenU = dir * random(35, 115);
      let dv = random(-32, 32);
      let p0 = P(endU + random(-12, 12), v0);
      let p1 = P(endU + lenU * 0.5, v0 + dv * 0.6 + random(-8, 8));
      let p2 = P(endU + lenU, v0 + dv);

      brush.set("film_specular", "#ffffff", random(0.85, 1.65));
      brush.spline([
        [p0[0], p0[1], 1.4],
        [p1[0], p1[1], 0.9],
        [p2[0], p2[1], 0.15]
      ], 0.3);
    }
  }
}

