// Half-drop repeat lattice dimensions
const TW = 360;
const TH = 440;
const LIGHT_X = -0.58;
const LIGHT_Y = -0.81;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(8831);

  // Custom brushes tailored for 1200x1200 hyperreal surface detailing
  brush.add("crust_shader", {
    type: "default",
    weight: 1.6,
    scatter: 0.35,
    sharpness: 0.28,
    grain: 14,
    opacity: 85,
    spacing: 0.3,
    pressure: [0.3, 1.15, 0.3],
    noise: 0.7
  });

  brush.add("gloss_pen", {
    type: "default",
    weight: 0.95,
    scatter: 0.04,
    sharpness: 0.88,
    grain: 3,
    opacity: 210,
    spacing: 0.18,
    pressure: [0.15, 1.25, 0.15],
    noise: 0.3
  });

  brush.add("dough_fiber", {
    type: "default",
    weight: 0.55,
    scatter: 0.1,
    sharpness: 0.72,
    grain: 7,
    opacity: 165,
    spacing: 0.22,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.5
  });

  brush.add("block_chatter", {
    type: "spray",
    weight: 5.5,
    scatter: 2.2,
    opacity: 42,
    spacing: 0.75,
    pressure: [0.6, 1.0, 0.6]
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.clip([0, 0, width, height]);

  // Collect all visible half-drop repeat nodes covering 1200x1200 edge-to-edge
  const nodes = [];
  for (let col = -1; col <= 4; col++) {
    for (let row = -1; row <= 3; row++) {
      const isOdd = Math.abs(col) % 2 === 1;
      const px = col * TW + 140;
      const py = row * TH + (isOdd ? TH / 2 : 0) + 110;
      nodes.push({
        col,
        row,
        px,
        py,
        rx: px,
        ry: py + TH / 2,
        variant: Math.abs(col * 7 + row * 13) % 4
      });
    }
  }

  // -------------------------------------------------------------------------
  // PASS 1: BLOCK-PRINTED FLAT GROUND (INDIGO & MADDER BROWN + OFF-REGISTER SLIPS)
  // -------------------------------------------------------------------------
  drawBlockPrintedGround(nodes);

  // -------------------------------------------------------------------------
  // PASS 2: CAST SHADOWS OF TRELLIS, PRETZELS, KNOTTED ROLLS & CARAWAY SEEDS
  // -------------------------------------------------------------------------
  for (const n of nodes) {
    if (inBounds(n.px, n.py, 320)) {
      drawPretzelAndTrellisShadow(n.px, n.py);
    }
    if (inBounds(n.rx, n.ry, 260)) {
      drawKnottedRollShadow(n.rx, n.ry, n.variant);
      drawCarawayFoliageCluster(n.rx, n.ry, n.variant, true);
    }
  }

  // -------------------------------------------------------------------------
  // PASS 3: UNDER-WEAVING TRELLIS DOUGH CORDS (INTERLOCKING CONNECTIONS)
  // -------------------------------------------------------------------------
  for (const n of nodes) {
    if (inBounds(n.px, n.py, 340)) {
      drawUnderWeavingTrellisArms(n.px, n.py, n.variant);
    }
  }

  // -------------------------------------------------------------------------
  // PASS 4: HYPERREAL KNOTTED BREAD ROLLS IN INTERSTITIAL TRELLIS CELLS
  // -------------------------------------------------------------------------
  for (const n of nodes) {
    if (inBounds(n.rx, n.ry, 240)) {
      drawKnottedBreadRoll(n.rx, n.ry, n.variant);
    }
  }

  // -------------------------------------------------------------------------
  // PASS 5: CARAWAY SEED FOLIAGE ("WHERE LEAVES WOULD BE") & SCATTERED SEEDS
  // -------------------------------------------------------------------------
  for (const n of nodes) {
    if (inBounds(n.rx, n.ry, 280)) {
      drawCarawayFoliageCluster(n.rx, n.ry, n.variant, false);
    }
  }

  // -------------------------------------------------------------------------
  // PASS 6: INTERLOCKING SALT-CRUSTED PRETZELS (LOOPS, BELLY, TWIST & OVER-ARMS)
  // -------------------------------------------------------------------------
  for (const n of nodes) {
    if (inBounds(n.px, n.py, 320)) {
      drawHyperrealPretzel(n.px, n.py, n.variant);
    }
  }

  brush.noClip();
  noLoop();
}

// ===========================================================================
// GEOMETRY & PRIMITIVE RENDERING HELPERS
// ===========================================================================

function inBounds(x, y, pad) {
  return x >= -pad && x <= width + pad && y >= -pad && y <= height + pad;
}

function washPoly(pts, col, op = 255) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, op);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function fillPoly(pts, col, op = 140, bleed = 0.06, tex = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, op);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.2);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function strokeSpline(pts, brushName, col, weight = 1, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.spline(pts, curv);
}

function strokeLine(x1, y1, x2, y2, brushName, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
}

// Catmull-Rom interpolation of control points with radius profile
function sampleTubeSpine(ctrlPts, radii, steps = 26) {
  const n = ctrlPts.length;
  const samples = [];
  for (let s = 0; s <= steps; s++) {
    const tGlobal = (s / steps) * (n - 1);
    const idx = Math.min(Math.floor(tGlobal), n - 2);
    const u = tGlobal - idx;

    const p0 = ctrlPts[Math.max(0, idx - 1)];
    const p1 = ctrlPts[idx];
    const p2 = ctrlPts[idx + 1];
    const p3 = ctrlPts[Math.min(n - 1, idx + 2)];

    const r0 = radii[Math.max(0, idx - 1)];
    const r1 = radii[idx];
    const r2 = radii[idx + 1];
    const r3 = radii[Math.min(n - 1, idx + 2)];

    const u2 = u * u;
    const u3 = u2 * u;

    const x =
      0.5 *
      (2 * p1[0] +
        (-p0[0] + p2[0]) * u +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3);
    const y =
      0.5 *
      (2 * p1[1] +
        (-p0[1] + p2[1]) * u +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3);
    const r =
      0.5 *
      (2 * r1 +
        (-r0 + r2) * u +
        (2 * r0 - 5 * r1 + 4 * r2 - r3) * u2 +
        (-r0 + 3 * r1 - 3 * r2 + r3) * u3);

    samples.push({ x, y, r: Math.max(1.5, r), t: s / steps });
  }

  for (let i = 0; i < samples.length; i++) {
    const prev = samples[Math.max(0, i - 1)];
    const next = samples[Math.min(samples.length - 1, i + 1)];
    let dx = next.x - prev.x;
    let dy = next.y - prev.y;
    const len = Math.hypot(dx, dy) || 1;
    dx /= len;
    dy /= len;
    samples[i].tx = dx;
    samples[i].ty = dy;
    samples[i].nx = -dy;
    samples[i].ny = dx;
  }
  return samples;
}

// Build a closed tube polygon with width factor `wFrac` and directional light shift `lShift`
function buildTubePolygon(spine, wFrac, lShift = 0, capRound = true) {
  const left = [];
  const right = [];
  const len = spine.length;

  for (let i = 0; i < len; i++) {
    const s = spine[i];
    // Taper gently at the very tips if inner shading layer
    let endTaper = 1.0;
    if (lShift > 0) {
      const edgeDist = Math.min(s.t, 1 - s.t);
      if (edgeDist < 0.08) endTaper = 0.35 + (edgeDist / 0.08) * 0.65;
    }
    const rad = s.r * wFrac * endTaper;
    const sx = s.x + LIGHT_X * s.r * lShift;
    const sy = s.y + LIGHT_Y * s.r * lShift;

    left.push([sx + s.nx * rad, sy + s.ny * rad]);
    right.push([sx - s.nx * rad, sy - s.ny * rad]);
  }

  const poly = [];
  // Start cap
  if (capRound && len > 0) {
    const s0 = spine[0];
    const rad0 = s0.r * wFrac * (lShift > 0 ? 0.35 : 1.0);
    const sx0 = s0.x + LIGHT_X * s0.r * lShift;
    const sy0 = s0.y + LIGHT_Y * s0.r * lShift;
    poly.push([sx0 - s0.tx * rad0 * 0.45, sy0 - s0.ty * rad0 * 0.45]);
  }
  for (let i = 0; i < left.length; i++) poly.push(left[i]);
  // End cap
  if (capRound && len > 0) {
    const s1 = spine[len - 1];
    const rad1 = s1.r * wFrac * (lShift > 0 ? 0.35 : 1.0);
    const sx1 = s1.x + LIGHT_X * s1.r * lShift;
    const sy1 = s1.y + LIGHT_Y * s1.r * lShift;
    poly.push([sx1 + s1.tx * rad1 * 0.45, sy1 + s1.ty * rad1 * 0.45]);
  }
  for (let i = right.length - 1; i >= 0; i--) poly.push(right[i]);
  return poly;
}

// Render a volumetric 3D lye-browned or golden-glazed dough tube along `spine`
function renderDoughTube(spine, style = "pretzel", opts = {}) {
  const isRoll = style === "roll";
  const cAbyss = isRoll ? PAL.crustAbyss : PAL.crustAbyss;
  const cDark = isRoll ? PAL.rollDark : PAL.crustDark;
  const cMid = isRoll ? PAL.rollMid : PAL.crustMid;
  const cWarm = isRoll ? PAL.rollWarm : PAL.crustWarm;
  const cLit = isRoll ? PAL.rollLit : PAL.crustLit;
  const cGold = isRoll ? PAL.rollGold : PAL.crustGold;

  // 1. Base silhouette in deepest roasted espresso-umber
  const basePoly = buildTubePolygon(spine, 1.0, 0);
  washPoly(basePoly, cAbyss, 250);

  // 2. Cool twilight indigo reflected bounce light along the lower-right shadow rim
  const bouncePts = [];
  for (let i = 1; i < spine.length - 1; i++) {
    const s = spine[i];
    bouncePts.push([
      s.x - LIGHT_X * s.r * 0.78 + s.nx * s.r * 0.08,
      s.y - LIGHT_Y * s.r * 0.78 + s.ny * s.r * 0.08,
      0.7
    ]);
  }
  strokeSpline(bouncePts, "crust_shader", PAL.crustBounce, 1.25, 0.5);

  // 3. Nested light-shifted 3D cylindrical tonal bands
  washPoly(buildTubePolygon(spine, 0.88, 0.07), cDark, 235);
  washPoly(buildTubePolygon(spine, 0.73, 0.16), cMid, 225);
  washPoly(buildTubePolygon(spine, 0.56, 0.25), cWarm, 215);
  washPoly(buildTubePolygon(spine, 0.38, 0.34), cLit, 205);
  washPoly(buildTubePolygon(spine, 0.21, 0.41), cGold, 190);

  if (isRoll) {
    washPoly(buildTubePolygon(spine, 0.11, 0.44), PAL.rollHoney, 165);
  }

  // 4. Cross-contour baked skin wrinkles & longitudinal stretch striations
  const step = Math.max(2, Math.floor(spine.length / 9));
  for (let i = 2; i < spine.length - 2; i += step) {
    const s = spine[i];
    const w = s.r * 0.78;
    const arcPts = [
      [s.x - s.nx * w * 0.75, s.y - s.ny * w * 0.75, 0.3],
      [
        s.x + LIGHT_X * s.r * 0.25 + s.tx * s.r * 0.14,
        s.y + LIGHT_Y * s.r * 0.25 + s.ty * s.r * 0.14,
        0.9
      ],
      [s.x + s.nx * w * 0.75, s.y + s.ny * w * 0.75, 0.3]
    ];
    strokeSpline(arcPts, "2B", i % 2 === 0 ? cDark : cWarm, 0.75, 0.6);
  }

  // 5. High-gloss lye glaze / egg-wash specular ribbons (broken into realistic segments)
  if (opts.gloss !== false) {
    const startIdx = opts.glossStart || 2;
    const endIdx = spine.length - (opts.glossEnd || 3);
    let seg = [];
    for (let i = startIdx; i <= endIdx; i++) {
      const s = spine[i];
      const gx = s.x + LIGHT_X * s.r * 0.43;
      const gy = s.y + LIGHT_Y * s.r * 0.43;
      if (i % 7 !== 4) {
        seg.push([gx, gy, 0.4 + 0.6 * Math.sin((i / spine.length) * Math.PI)]);
      } else {
        if (seg.length >= 2) {
          strokeSpline(seg, "gloss_pen", PAL.glossCool, 1.05, 0.5);
          strokeSpline(seg, "rotring", PAL.glossWarm, 0.65, 0.5);
        }
        seg = [];
      }
    }
    if (seg.length >= 2) {
      strokeSpline(seg, "gloss_pen", PAL.glossCool, 1.05, 0.5);
      strokeSpline(seg, "rotring", PAL.glossWarm, 0.65, 0.5);
    }

    // Secondary parallel micro-glint
    const glint = [];
    for (let i = startIdx + 2; i <= endIdx - 2; i += 2) {
      const s = spine[i];
      glint.push([
        s.x + LIGHT_X * s.r * 0.26,
        s.y + LIGHT_Y * s.r * 0.26,
        0.5
      ]);
    }
    if (glint.length >= 2) {
      strokeSpline(glint, "rotring", isRoll ? PAL.rollHoney : PAL.crustGold, 0.7, 0.5);
    }
  }
}

// Render a hyperreal cracked baking split showing pale stretched inner dough
function renderDoughSplit(spine, startFrac, endFrac, maxHalfWidth, shiftAlongLight = 0.15) {
  const sub = [];
  for (let i = 0; i < spine.length; i++) {
    const t = spine[i].t;
    if (t >= startFrac && t <= endFrac) {
      const u = (t - startFrac) / (endFrac - startFrac);
      // Lenticular baker's score profile: tapers sharply at ends, full in middle
      const env = Math.sin(u * Math.PI) * (0.85 + 0.15 * Math.sin(u * Math.PI * 3));
      sub.push({
        x: spine[i].x + LIGHT_X * spine[i].r * shiftAlongLight,
        y: spine[i].y + LIGHT_Y * spine[i].r * shiftAlongLight,
        tx: spine[i].tx,
        ty: spine[i].ty,
        nx: spine[i].nx,
        ny: spine[i].ny,
        w: maxHalfWidth * env,
        u
      });
    }
  }
  if (sub.length < 3) return;

  const buildSplitPoly = (scaleW, offsetN = 0) => {
    const upper = [];
    const lower = [];
    for (let i = 0; i < sub.length; i++) {
      const p = sub[i];
      const jag = (i % 2 === 0 ? 1 : -1) * p.w * 0.08;
      const w = p.w * scaleW;
      upper.push([
        p.x + p.nx * (w + offsetN + jag),
        p.y + p.ny * (w + offsetN + jag)
      ]);
      lower.push([
        p.x - p.nx * (w - offsetN - jag),
        p.y - p.ny * (w - offsetN - jag)
      ]);
    }
    return upper.concat(lower.reverse());
  };

  // 1. Dark torn outer crust lip
  washPoly(buildSplitPoly(1.22, 0), PAL.splitLip, 245);
  // 2. Toasted caramel & amber baked transition rim
  washPoly(buildSplitPoly(1.04, 0), PAL.splitToast, 235);
  washPoly(buildSplitPoly(0.90, 0), PAL.splitAmber, 225);
  // 3. Recessed shadow inside the split (cast by the upper torn crust overhang)
  washPoly(buildSplitPoly(0.76, 0), PAL.doughShadow, 240);
  // 4. Pale creamy dough interior shifted slightly away from upper overhang
  washPoly(buildSplitPoly(0.64, -1.1), PAL.doughBase, 245);
  washPoly(buildSplitPoly(0.42, -1.5), PAL.doughLight, 235);

  // 5. Transverse stretched gluten dough strands bridging the split + crumb pores
  for (let i = 1; i < sub.length - 1; i++) {
    const p = sub[i];
    if (p.w < 2.2) continue;
    const x1 = p.x + p.nx * p.w * 0.72;
    const y1 = p.y + p.ny * p.w * 0.72;
    const x2 = p.x - p.nx * p.w * 0.75 + p.tx * 2.5;
    const y2 = p.y - p.ny * p.w * 0.75 + p.ty * 2.5;

    strokeLine(x1, y1, x2, y2, "dough_fiber", PAL.doughFiber, 0.85);
    if (i % 2 === 0) {
      strokeLine(
        x1 - p.tx * 1.8,
        y1 - p.ty * 1.8,
        x2 + p.tx * 1.2,
        y2 + p.ty * 1.2,
        "2H",
        PAL.doughShadow,
        0.65
      );
    }
  }

  // 6. Ragged dark crust serrations along both torn lips of the split
  const upperLip = [];
  const lowerLip = [];
  for (let i = 0; i < sub.length; i++) {
    const p = sub[i];
    const jag = (i % 2 === 0 ? 1.4 : -1.1);
    upperLip.push([p.x + p.nx * (p.w * 1.05 + jag), p.y + p.ny * (p.w * 1.05 + jag), 0.7]);
    lowerLip.push([p.x - p.nx * (p.w * 1.02 - jag), p.y - p.ny * (p.w * 1.02 - jag), 0.6]);
  }
  strokeSpline(upperLip, "rotring", PAL.crustAbyss, 0.8, 0.4);
  strokeSpline(lowerLip, "rotring", PAL.splitToast, 0.65, 0.4);
}

// Render an individual faceted coarse salt crystal with its tiny cast shadow
function drawSaltCrystal(x, y, sz = 6.5, ang = 25) {
  const rad = (ang * Math.PI) / 180;
  const ca = Math.cos(rad);
  const sa = Math.sin(rad);
  const rot = (px, py) => [x + px * ca - py * sa, y + px * sa + py * ca];

  // Outer hexagonal/rhomboid crystal vertices
  const v0 = rot(-sz * 0.55, -sz * 0.42);
  const v1 = rot(sz * 0.15, -sz * 0.58);
  const v2 = rot(sz * 0.62, -sz * 0.18);
  const v3 = rot(sz * 0.48, sz * 0.48);
  const v4 = rot(-sz * 0.22, sz * 0.55);
  const v5 = rot(-sz * 0.62, sz * 0.12);
  const outer = [v0, v1, v2, v3, v4, v5];

  // 1. Tiny sharp cast shadow offset opposite the light vector
  const shx = -LIGHT_X * sz * 0.58;
  const shy = -LIGHT_Y * sz * 0.58;
  const shadowPoly = outer.map((p) => [p[0] + shx, p[1] + shy]);
  washPoly(shadowPoly, PAL.saltShadow, 220);

  // 2. Twilight-tinted shadow facets (bottom-right)
  washPoly(outer, PAL.saltSide, 240);

  // 3. Mid-tone crystalline facet
  const center = rot(-sz * 0.06, -sz * 0.06);
  washPoly([v5, v0, v1, v2, center], PAL.saltMid, 245);

  // 4. Bright upper-left lit facet
  const topFacet = [
    v0,
    v1,
    rot(sz * 0.22, -sz * 0.12),
    rot(-sz * 0.15, sz * 0.18),
    v5
  ];
  washPoly(topFacet, PAL.saltTop, 250);

  // 5. Crisp internal facet cleavage lines & pure white specular glint
  strokeLine(v0[0], v0[1], v1[0], v1[1], "rotring", PAL.saltEdge, 0.75);
  strokeLine(v0[0], v0[1], v5[0], v5[1], "rotring", PAL.saltEdge, 0.75);
  strokeLine(v0[0], v0[1], center[0], center[1], "rotring", PAL.saltEdge, 0.65);
  strokeLine(v3[0], v3[1], v4[0], v4[1], "rotring", PAL.crustAbyss, 0.5);
}

// Render a hyperreal curved, longitudinally ridged caraway seed with tiny cast shadow
function drawCarawaySeed(x, y, len = 19, angDeg = 30, bend = 0.22, shadowOnly = false) {
  const rad = (angDeg * Math.PI) / 180;
  const ca = Math.cos(rad);
  const sa = Math.sin(rad);
  const halfL = len * 0.5;
  const maxW = len * 0.16;

  // Build crescent spine & hull in local coordinates then rotate
  const steps = 8;
  const upper = [];
  const lower = [];
  const ridgeTop = [];
  const ridgeMid = [];
  const ridgeBot = [];

  for (let i = 0; i <= steps; i++) {
    const u = i / steps;
    const s = (u - 0.5) * 2; // -1 .. +1
    const lx = s * halfL;
    const camber = (1 - s * s) * len * bend;
    // Taper sharply at both mericarp tips
    const w = Math.sin(u * Math.PI) * maxW * (1 - 0.15 * s);

    const ux = lx;
    const uy = -camber - w;
    const bx = lx;
    const by = -camber + w * 0.85;

    upper.push([x + ux * ca - uy * sa, y + ux * sa + uy * ca]);
    lower.push([x + bx * ca - by * sa, y + bx * sa + by * ca]);

    if (i >= 1 && i <= steps - 1) {
      const r1y = -camber - w * 0.45;
      const r2y = -camber - w * 0.05;
      const r3y = -camber + w * 0.38;
      ridgeTop.push([x + lx * ca - r1y * sa, y + lx * sa + r1y * ca, 0.6]);
      ridgeMid.push([x + lx * ca - r2y * sa, y + lx * sa + r2y * ca, 0.8]);
      ridgeBot.push([x + lx * ca - r3y * sa, y + lx * sa + r3y * ca, 0.5]);
    }
  }

  const hull = upper.concat(lower.reverse());

  if (shadowOnly) {
    const shx = -LIGHT_X * 3.8;
    const shy = -LIGHT_Y * 3.8;
    washPoly(
      hull.map((p) => [p[0] + shx, p[1] + shy]),
      PAL.seedShadow,
      195
    );
    return;
  }

  // 1. Dark roasted brown caraway hull
  washPoly(hull, PAL.seedDark, 248);

  // 2. Lit upper half of seed body
  const litHull = upper.concat(ridgeMid.map((p) => [p[0], p[1]]).reverse());
  washPoly(litHull, PAL.seedBody, 235);

  // 3. Characteristic pale longitudinal ridges (5-ribbed mericarp appearance)
  strokeSpline(ridgeBot, "rotring", PAL.seedRibDark, 0.55, 0.5);
  strokeSpline(ridgeTop, "rotring", PAL.seedRibMid, 0.6, 0.5);
  strokeSpline(ridgeMid, "rotring", PAL.seedRibLight, 0.72, 0.5);

  // Tiny pale stem-scar tip (stylopodium) at one end
  const tip = upper[0];
  strokeLine(tip[0], tip[1], tip[0] - ca * 1.8, tip[1] - sa * 1.8, "rotring", PAL.seedRibLight, 0.65);
}

// ===========================================================================
// LAYER 1: BLOCK-PRINTED WALLPAPER GROUND (INDIGO & MADDER + OFF-REGISTER SLIPS)
// ===========================================================================

function drawBlockPrintedGround(nodes) {
  // Base dusky twilight indigo paper ground
  background(PAL.groundBase);

  // Subtle woven wallpaper rag-paper ground texture
  for (let y = 8; y < height; y += 16) {
    strokeLine(0, y, width, y, "2H", y % 32 === 0 ? PAL.indigoDark : PAL.indigoMid, 0.55);
  }
  for (let x = 10; x < width; x += 22) {
    strokeLine(x, 0, x, height, "2H", PAL.indigoDark, 0.45);
  }

  // Helper to generate flat block-printed Morris backing shapes at each node
  const buildOgeeStrapPoly = (px, py, dx, dy, ox = 0, oy = 0) => {
    const steps = 14;
    const left = [];
    const right = [];
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const x = px + dx * t + ox;
      const y = py + dy * t + oy;
      const wave = Math.sin(t * Math.PI * 2) * 18;
      const scallop = Math.sin(t * Math.PI * 7) * 4.5;
      const w = 22 + Math.abs(scallop);
      const nx = -dy / Math.hypot(dx, dy);
      const ny = dx / Math.hypot(dx, dy);
      left.push([x + nx * (wave + w), y + ny * (wave + w)]);
      right.push([x + nx * (wave - w), y + ny * (wave - w)]);
    }
    return left.concat(right.reverse());
  };

  const buildRosetteMedallion = (rx, ry, rad, petals, ox = 0, oy = 0) => {
    const pts = [];
    const total = petals * 8;
    for (let i = 0; i < total; i++) {
      const a = (i / total) * Math.PI * 2;
      const lobe = Math.abs(Math.cos((a * petals) / 2));
      const notch = Math.cos(a * petals * 2) * 0.06;
      const r = rad * (0.72 + 0.28 * lobe + notch);
      pts.push([rx + ox + Math.cos(a) * r, ry + oy + Math.sin(a) * r]);
    }
    return pts;
  };

  const buildFoliateBackingLeaf = (rx, ry, angDeg, dist, len, ox = 0, oy = 0) => {
    const rad = (angDeg * Math.PI) / 180;
    const cx = rx + Math.cos(rad) * dist + ox;
    const cy = ry + Math.sin(rad) * dist + oy;
    const ca = Math.cos(rad);
    const sa = Math.sin(rad);
    const pts = [];
    const steps = 12;
    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const s = (u - 0.5) * len;
      const serrate = Math.sin(u * Math.PI * 5) * 4.5;
      const w = Math.sin(u * Math.PI) * (len * 0.28) + Math.abs(serrate);
      pts.push([cx + s * ca - w * sa, cy + s * sa + w * ca]);
    }
    for (let i = steps; i >= 0; i--) {
      const u = i / steps;
      const s = (u - 0.5) * len;
      const serrate = Math.sin(u * Math.PI * 5) * 4.5;
      const w = Math.sin(u * Math.PI) * (len * 0.28) + Math.abs(serrate);
      pts.push([cx + s * ca + w * sa, cy + s * sa - w * ca]);
    }
    return pts;
  };

  const leafAngles = [32, 148, 212, 328, 82, 262];

  // -------------------------------------------------------------------------
  // 1A. OFF-REGISTER SLIP PASS (warm unprinted paper slip & cool slate slip)
  // -------------------------------------------------------------------------
  for (const n of nodes) {
    // Occasional stronger off-register slip on alternating blocks
    const slipX = n.col % 2 === 0 ? 9.5 : -8.5;
    const slipY = n.row % 2 === 0 ? -6.5 : 7.0;

    if (inBounds(n.px, n.py, 400)) {
      washPoly(
        buildOgeeStrapPoly(n.px, n.py, TW / 2, TH / 2, slipX, slipY),
        PAL.slipWarm,
        150
      );
      washPoly(
        buildOgeeStrapPoly(n.px, n.py, -TW / 2, TH / 2, slipX, slipY),
        PAL.slipWarm,
        150
      );
      washPoly(
        buildRosetteMedallion(n.px, n.py - 12, 118, 6, slipX, slipY),
        PAL.slipCool,
        140
      );
    }

    if (inBounds(n.rx, n.ry, 320)) {
      washPoly(
        buildRosetteMedallion(n.rx, n.ry, 108, 8, slipX, slipY),
        PAL.slipWarm,
        165
      );
      for (let k = 0; k < leafAngles.length; k++) {
        const d = k < 4 ? 112 : 92;
        const l = k < 4 ? 86 : 64;
        washPoly(
          buildFoliateBackingLeaf(n.rx, n.ry, leafAngles[k], d, l, slipX, slipY),
          k % 2 === 0 ? PAL.slipWarm : PAL.slipCool,
          145
        );
      }
    }
  }

  // -------------------------------------------------------------------------
  // 1B. MAIN MADDER BROWN FLAT WOODBLOCK PRINT PASS
  // -------------------------------------------------------------------------
  for (const n of nodes) {
    const regJitterX = ((n.col + n.row) % 3 - 1) * 2.5;
    const regJitterY = ((n.col * 2 - n.row) % 3 - 1) * 2.0;

    if (inBounds(n.px, n.py, 400)) {
      washPoly(
        buildOgeeStrapPoly(n.px, n.py, TW / 2, TH / 2, regJitterX, regJitterY),
        PAL.madderMid,
        235
      );
      washPoly(
        buildOgeeStrapPoly(n.px, n.py, -TW / 2, TH / 2, regJitterX, regJitterY),
        PAL.madderMid,
        235
      );
      washPoly(
        buildRosetteMedallion(n.px, n.py - 12, 116, 6, regJitterX, regJitterY),
        PAL.madderDark,
        230
      );
      washPoly(
        buildRosetteMedallion(n.px, n.py - 12, 86, 6, -regJitterX, -regJitterY),
        PAL.madderBright,
        210
      );
    }

    if (inBounds(n.rx, n.ry, 320)) {
      washPoly(
        buildRosetteMedallion(n.rx, n.ry, 106, 8, regJitterX, regJitterY),
        PAL.madderMid,
        240
      );
      washPoly(
        buildRosetteMedallion(n.rx, n.ry, 82, 8, regJitterX + 4, regJitterY - 3),
        PAL.madderBright,
        220
      );
      for (let k = 0; k < leafAngles.length; k++) {
        const d = k < 4 ? 112 : 92;
        const l = k < 4 ? 84 : 62;
        washPoly(
          buildFoliateBackingLeaf(n.rx, n.ry, leafAngles[k], d, l, regJitterX, regJitterY),
          k < 4 ? PAL.madderMid : PAL.madderSoft,
          225
        );
      }
    }
  }

  // -------------------------------------------------------------------------
  // 1C. DEEP INDIGO & PRUSSIAN COUNTER-BLOCK PRINT PASS (WITH OVERPRINT RIMS)
  // -------------------------------------------------------------------------
  for (const n of nodes) {
    const ox = -5.5;
    const oy = 4.5;
    if (inBounds(n.px, n.py, 360)) {
      washPoly(
        buildRosetteMedallion(n.px, n.py - 12, 66, 6, ox, oy),
        PAL.indigoLight,
        225
      );
      washPoly(
        buildRosetteMedallion(n.px, n.py - 12, 46, 6, 0, 0),
        PAL.indigoDark,
        235
      );
    }
    if (inBounds(n.rx, n.ry, 300)) {
      washPoly(
        buildRosetteMedallion(n.rx, n.ry, 64, 8, ox, oy),
        PAL.indigoMid,
        235
      );
      for (let k = 0; k < 4; k++) {
        washPoly(
          buildFoliateBackingLeaf(n.rx, n.ry, leafAngles[k], 112, 54, ox, oy),
          PAL.indigoLight,
          210
        );
        // Block-printed midrib veins with slight registration shift
        const rad = (leafAngles[k] * Math.PI) / 180;
        const x1 = n.rx + Math.cos(rad) * 76 + ox * 1.4;
        const y1 = n.ry + Math.sin(rad) * 76 + oy * 1.4;
        const x2 = n.rx + Math.cos(rad) * 146 + ox * 1.4;
        const y2 = n.ry + Math.sin(rad) * 146 + oy * 1.4;
        strokeLine(x1, y1, x2, y2, "rotring", PAL.overprint, 1.1);
        strokeLine(x1 - 5, y1 + 3, x2 - 5, y2 + 3, "rotring", PAL.slipWarm, 0.8);
      }
    }
  }

  // -------------------------------------------------------------------------
  // 1D. BROKEN INK COVERAGE & PEARWOOD BLOCK-PRINT GRAIN CHATTER
  // -------------------------------------------------------------------------
  for (let i = 0; i < 210; i++) {
    const bx = (i * 173.7) % width;
    const by = (i * 293.3 + (i % 7) * 41) % height;
    const len = 35 + (i % 5) * 18;
    // Vertical/diagonal woodgrain striations breaking up the flat block coverage
    strokeLine(
      bx,
      by,
      bx + (i % 3 - 1) * 4,
      by + len,
      "2B",
      i % 2 === 0 ? PAL.groundBase : PAL.madderDark,
      0.85
    );
    if (i % 3 === 0) {
      strokeLine(
        bx + 6,
        by - 10,
        bx + 6,
        by + len * 0.7,
        "block_chatter",
        i % 4 === 0 ? PAL.indigoMid : PAL.slipWarm,
        0.9
      );
    }
  }
}

// ===========================================================================
// LAYER 2 & 3 & 6: PRETZEL & INTERLOCKING TRELLIS GEOMETRY
// ===========================================================================

function getPretzelStrands(px, py) {
  // 1. Incoming upper-left trellis arm (from upper-left neighbour's lower-right arm at px - TW/2, py - TH/2)
  // Passes UNDER the pretzel's left loop arch and folds OVER the thick belly arch
  const armInLeft = sampleTubeSpine(
    [
      [px - TW / 2, py - TH / 2],
      [px - 148, py - 88],
      [px - 112, py - 58],
      [px - 76, py - 94],
      [px - 56, py - 42]
    ],
    [13.5, 13.5, 13.0, 12.5, 10.5],
    22
  );

  // 2. Incoming upper-right trellis arm (from upper-right neighbour's lower-left arm at px + TW/2, py - TH/2)
  const armInRight = sampleTubeSpine(
    [
      [px + TW / 2, py - TH / 2],
      [px + 148, py - 88],
      [px + 112, py - 58],
      [px + 76, py - 94],
      [px + 56, py - 42]
    ],
    [13.5, 13.5, 13.0, 12.5, 10.5],
    22
  );

  // 3. Outgoing lower-left trellis arm (emerges from center twist, sweeps OVER lower loop to px - TW/2, py + TH/2)
  const armOutLeft = sampleTubeSpine(
    [
      [px + 14, py - 12],
      [px - 22, py + 12],
      [px - 78, py + 52],
      [px - 134, py + 84],
      [px - TW / 2, py + TH / 2]
    ],
    [14.5, 14.5, 14.0, 13.5, 13.5],
    24
  );

  // 4. Outgoing lower-right trellis arm (emerges from center twist, sweeps OVER lower loop to px + TW/2, py + TH/2)
  const armOutRight = sampleTubeSpine(
    [
      [px - 14, py - 12],
      [px + 22, py + 12],
      [px + 78, py + 52],
      [px + 134, py + 84],
      [px + TW / 2, py + TH / 2]
    ],
    [14.5, 14.5, 14.0, 13.5, 13.5],
    24
  );

  // 5. Left lower loop strand (from left shoulder down around lower-left loop into central twist)
  const loopLeft = sampleTubeSpine(
    [
      [px - 128, py - 22],
      [px - 142, py + 32],
      [px - 102, py + 82],
      [px - 38, py + 66],
      [px, py + 24],
      [px + 16, py - 10]
    ],
    [20.5, 18.5, 17.5, 16.0, 15.0, 14.5],
    26
  );

  // 6. Right lower loop strand (crosses OVER loopLeft at the central twist)
  const loopRight = sampleTubeSpine(
    [
      [px + 128, py - 22],
      [px + 142, py + 32],
      [px + 102, py + 82],
      [px + 38, py + 66],
      [px, py + 24],
      [px - 16, py - 10]
    ],
    [20.5, 18.5, 17.5, 16.0, 15.0, 14.5],
    26
  );

  // 7. Thick upper belly arch (signature swollen Bavarian pretzel crest with deep score split)
  const bellyArch = sampleTubeSpine(
    [
      [px - 128, py - 22],
      [px - 124, py - 76],
      [px - 68, py - 114],
      [px, py - 124],
      [px + 68, py - 114],
      [px + 124, py - 76],
      [px + 128, py - 22]
    ],
    [20.5, 23.0, 26.5, 28.0, 26.5, 23.0, 20.5],
    32
  );

  return {
    armInLeft,
    armInRight,
    armOutLeft,
    armOutRight,
    loopLeft,
    loopRight,
    bellyArch
  };
}

function drawPretzelAndTrellisShadow(px, py) {
  const s = getPretzelStrands(px, py);
  const shx = -LIGHT_X * 14;
  const shy = -LIGHT_Y * 14;

  const shadowStrand = (spine) => {
    const shifted = spine.map((pt) => ({
      ...pt,
      x: pt.x + shx,
      y: pt.y + shy
    }));
    washPoly(buildTubePolygon(shifted, 1.06, 0), PAL.shadowCast, 175);
  };

  shadowStrand(s.armInLeft);
  shadowStrand(s.armInRight);
  shadowStrand(s.armOutLeft);
  shadowStrand(s.armOutRight);
  shadowStrand(s.loopLeft);
  shadowStrand(s.loopRight);
  shadowStrand(s.bellyArch);
}

// Pass 3: Draw the incoming trellis cords that duck UNDER the pretzel's side arches
function drawUnderWeavingTrellisArms(px, py, variant) {
  const s = getPretzelStrands(px, py);

  // First half of armInLeft & armInRight (which pass under the upper-side loop of the pretzel)
  const subLeft = s.armInLeft.slice(0, 13);
  const subRight = s.armInRight.slice(0, 13);

  renderDoughTube(subLeft, "pretzel", { glossStart: 1, glossEnd: 2 });
  renderDoughTube(subRight, "pretzel", { glossStart: 1, glossEnd: 2 });

  // Small tension crust split on the incoming trellis cords
  renderDoughSplit(subLeft, 0.15, 0.42, 4.2, 0.1);
  renderDoughSplit(subRight, 0.15, 0.42, 4.2, 0.1);

  // Salt crystals along the under-passing trellis cords
  drawSaltCrystal(px - 154, py - 92, 5.5, 18);
  drawSaltCrystal(px - 135, py - 76, 6.2, 64);
  drawSaltCrystal(px + 152, py - 90, 5.8, 42);
  drawSaltCrystal(px + 132, py - 74, 5.2, 115);
}

// Pass 6: Draw the main hyperreal pretzel, its central twist, outgoing trellis arms, and folded tips
function drawHyperrealPretzel(px, py, variant) {
  const s = getPretzelStrands(px, py);

  // 1. Cast shadow where incoming trellis arms pass UNDER the side arches
  washPoly(
    [
      [px - 132, py - 72],
      [px - 98, py - 68],
      [px - 102, py - 42],
      [px - 136, py - 46]
    ],
    PAL.shadowCast,
    185
  );
  washPoly(
    [
      [px + 132, py - 72],
      [px + 98, py - 68],
      [px + 102, py - 42],
      [px + 136, py - 46]
    ],
    PAL.shadowCast,
    185
  );

  // 2. Left lower loop strand (goes under right loop strand at the central twist)
  renderDoughTube(s.loopLeft, "pretzel");
  renderDoughSplit(s.loopLeft, 0.18, 0.46, 5.5, 0.12);

  // Cast shadow of loopRight crossing OVER loopLeft at the central twist (px, py + 24)
  washPoly(
    [
      [px - 22, py + 36],
      [px + 18, py + 12],
      [px + 26, py + 28],
      [px - 14, py + 50]
    ],
    PAL.crustAbyss,
    225
  );

  // 3. Right lower loop strand (crosses OVER loopLeft at central twist)
  renderDoughTube(s.loopRight, "pretzel");
  renderDoughSplit(s.loopRight, 0.16, 0.44, 5.5, 0.12);

  // 4. Outgoing lower trellis arms (twist over the lower loops to interlock with neighbours below)
  // Cast shadow onto lower loops at (px ± 110, py + 72)
  washPoly(
    [
      [px - 132, py + 70],
      [px - 88, py + 52],
      [px - 80, py + 72],
      [px - 124, py + 92]
    ],
    PAL.crustAbyss,
    210
  );
  washPoly(
    [
      [px + 132, py + 70],
      [px + 88, py + 52],
      [px + 80, py + 72],
      [px + 124, py + 92]
    ],
    PAL.crustAbyss,
    210
  );

  renderDoughTube(s.armOutLeft, "pretzel");
  // Cast shadow at the upper central twist crossing (px, py - 2)
  washPoly(
    [
      [px - 16, py - 8],
      [px + 16, py + 8],
      [px + 10, py + 22],
      [px - 20, py + 6]
    ],
    PAL.crustAbyss,
    220
  );
  renderDoughTube(s.armOutRight, "pretzel");

  renderDoughSplit(s.armOutLeft, 0.35, 0.68, 4.5, 0.12);
  renderDoughSplit(s.armOutRight, 0.35, 0.68, 4.5, 0.12);

  // 5. Thick upper belly arch (the hero curve of the pretzel)
  renderDoughTube(s.bellyArch, "pretzel", { glossStart: 3, glossEnd: 3 });

  // Deep signature baker's score split along the swollen crest of the belly arch
  renderDoughSplit(s.bellyArch, 0.22, 0.78, 10.8, -0.06);
  // Secondary hairline crust crack beside the main belly split
  renderDoughSplit(s.bellyArch, 0.08, 0.24, 4.2, 0.22);
  renderDoughSplit(s.bellyArch, 0.76, 0.92, 4.2, 0.22);

  // Extra glossy lye-crust specular ridge right below the belly split
  const bellyGloss = [];
  for (let i = 7; i <= 25; i++) {
    const pt = s.bellyArch[i];
    bellyGloss.push([
      pt.x + pt.nx * pt.r * 0.42,
      pt.y + pt.ny * pt.r * 0.42,
      0.85
    ]);
  }
  strokeSpline(bellyGloss, "gloss_pen", PAL.glossCool, 1.2, 0.5);
  strokeSpline(bellyGloss, "rotring", PAL.glossPure, 0.7, 0.5);

  // 6. Terminal ends of incoming trellis arms folding OVER the shoulders of the belly arch
  const tipLeft = s.armInLeft.slice(10);
  const tipRight = s.armInRight.slice(10);

  // Cast shadow of the folded pretzel tips onto the belly arch shoulders
  for (const tip of [tipLeft, tipRight]) {
    const sh = tip.map((pt) => ({ ...pt, x: pt.x + 5.5, y: pt.y + 7.5 }));
    washPoly(buildTubePolygon(sh, 1.08, 0), PAL.crustAbyss, 215);
  }

  renderDoughTube(tipLeft, "pretzel", { glossStart: 1, glossEnd: 2 });
  renderDoughTube(tipRight, "pretzel", { glossStart: 1, glossEnd: 2 });

  // Pale toasted dough dimple at the pinched terminal tips of the pretzel arms
  const endL = tipLeft[tipLeft.length - 1];
  const endR = tipRight[tipRight.length - 1];
  for (const ep of [endL, endR]) {
    washPoly(
      [
        [ep.x - 5, ep.y - 3],
        [ep.x + 4, ep.y - 5],
        [ep.x + 6, ep.y + 3],
        [ep.x - 3, ep.y + 6]
      ],
      PAL.splitToast,
      230
    );
    washPoly(
      [
        [ep.x - 2.5, ep.y - 1.5],
        [ep.x + 2.5, ep.y - 2.5],
        [ep.x + 3, ep.y + 2],
        [ep.x - 2, ep.y + 3]
      ],
      PAL.doughBase,
      235
    );
  }

  // 7. Coarse faceted salt crystals with tiny cast shadows across the pretzel
  const saltCoords = [
    // Belly arch crystals
    [-92, -96, 7.2, 15],
    [-76, -108, 5.4, 52],
    [-52, -124, 7.8, 28],
    [-34, -104, 6.0, 74],
    [-16, -128, 6.8, 11],
    [4, -106, 8.2, 39],
    [22, -126, 5.8, 63],
    [44, -108, 7.4, 19],
    [62, -118, 6.2, 82],
    [88, -94, 7.0, 45],
    [108, -68, 5.6, 22],
    [-112, -64, 6.4, 67],
    // Side loops
    [-136, -8, 6.8, 33],
    [-142, 18, 5.5, 78],
    [-132, 46, 7.2, 14],
    [-108, 76, 6.0, 51],
    [-68, 76, 5.4, 29],
    [134, -12, 6.5, 44],
    [140, 22, 7.4, 12],
    [128, 52, 5.8, 68],
    [104, 78, 6.6, 37],
    [64, 74, 5.6, 81],
    // Central twist & outgoing trellis arms
    [-4, 28, 6.8, 24],
    [12, 16, 5.4, 59],
    [-14, -4, 6.2, 17],
    [8, -14, 5.8, 72],
    [-48, 34, 6.4, 41],
    [-94, 62, 7.0, 19],
    [52, 36, 6.2, 63],
    [96, 64, 6.8, 27],
    // Folded terminal arm tips
    [-68, -74, 5.8, 35],
    [-58, -52, 6.4, 71],
    [66, -72, 6.0, 48],
    [58, -50, 5.6, 16]
  ];

  for (let i = 0; i < saltCoords.length; i++) {
    const sc = saltCoords[i];
    const jx = ((i * 19 + variant * 7) % 5 - 2) * 1.1;
    const jy = ((i * 11 + variant * 13) % 5 - 2) * 1.1;
    drawSaltCrystal(px + sc[0] + jx, py + sc[1] + jy, sc[2], sc[3] + variant * 15);
  }
}

// ===========================================================================
// LAYER 4: HYPERREAL KNOTTED BREAD ROLLS (INTERSTITIAL BRAIDED MEDALLIONS)
// ===========================================================================

function drawKnottedRollShadow(rx, ry, variant) {
  const shx = -LIGHT_X * 15;
  const shy = -LIGHT_Y * 15;
  const pts = [];
  const total = 40;
  const baseAng = variant * 18;
  for (let i = 0; i < total; i++) {
    const a = (i / total) * Math.PI * 2;
    const lobe = Math.abs(Math.cos(((a + (baseAng * Math.PI) / 180) * 5) / 2));
    const r = 64 + 16 * lobe;
    pts.push([rx + shx + Math.cos(a) * r, ry + shy + Math.sin(a) * r]);
  }
  washPoly(pts, PAL.shadowCast, 185);
}

function drawKnottedBreadRoll(rx, ry, variant) {
  const baseRot = variant * 18;

  // 1. Deep caramelized interior recess disk so creases between braided lobes are rich & dark
  const basePts = [];
  for (let i = 0; i < 30; i++) {
    const a = (i / 30) * Math.PI * 2;
    basePts.push([rx + Math.cos(a) * 62, ry + Math.sin(a) * 62]);
  }
  washPoly(basePts, PAL.crustAbyss, 250);

  // 2. Five interlocking plump braided dough lobes twisting in a rosette knot
  const numLobes = 5;
  for (let k = 0; k < numLobes; k++) {
    const a0 = baseRot + k * 72;
    const ptPol = (deg, rad) => {
      const r = (deg * Math.PI) / 180;
      return [rx + Math.cos(r) * rad, ry + Math.sin(r) * rad];
    };

    const lobeCtrl = [
      ptPol(a0 - 22, 14),
      ptPol(a0 - 4, 38),
      ptPol(a0 + 20, 58),
      ptPol(a0 + 48, 54),
      ptPol(a0 + 72, 30)
    ];
    const lobeRadii = [13.5, 20.5, 24.5, 21.5, 14.0];
    const spine = sampleTubeSpine(lobeCtrl, lobeRadii, 22);

    // Deep crease shadow cast onto the preceding lobe
    const shSpine = spine.map((pt) => ({ ...pt, x: pt.x + 5, y: pt.y + 6 }));
    washPoly(buildTubePolygon(shSpine, 1.08, 0), PAL.crustAbyss, 215);

    // Render plump golden-mahogany braided dough lobe
    renderDoughTube(spine, "roll", { glossStart: 3, glossEnd: 4 });

    // Pale stretched dough split in the high-tension crease of each lobe
    renderDoughSplit(spine, 0.14, 0.52, 6.2, -0.18);
  }

  // 3. Central tucked dough knot crown emerging from the vortex and folding over lobe 0
  const cAng = baseRot + 12;
  const cPol = (deg, rad) => {
    const r = (deg * Math.PI) / 180;
    return [rx + Math.cos(r) * rad, ry + Math.sin(r) * rad];
  };
  const crownSpine = sampleTubeSpine(
    [
      cPol(cAng + 185, 28),
      cPol(cAng + 115, 16),
      [rx, ry - 2],
      cPol(cAng - 10, 18),
      cPol(cAng + 35, 32)
    ],
    [14.5, 19.5, 22.5, 19.5, 13.5],
    20
  );

  const crownShadow = crownSpine.map((pt) => ({ ...pt, x: pt.x + 5.5, y: pt.y + 6.5 }));
  washPoly(buildTubePolygon(crownShadow, 1.1, 0), PAL.crustAbyss, 225);

  renderDoughTube(crownSpine, "roll", { glossStart: 2, glossEnd: 3 });
  renderDoughSplit(crownSpine, 0.28, 0.72, 6.5, 0.1);

  // 4. Caraway seeds & coarse salt grains nestled in the creases & crown of the knotted roll
  for (let k = 0; k < numLobes; k++) {
    const aCrease = ((baseRot + k * 72 + 54) * Math.PI) / 180;
    const sx = rx + Math.cos(aCrease) * 38;
    const sy = ry + Math.sin(aCrease) * 38;
    drawCarawaySeed(sx, sy, 15.5, baseRot + k * 72 - 20, 0.2, true);
    drawCarawaySeed(sx, sy, 15.5, baseRot + k * 72 - 20, 0.2, false);

    const sx2 = rx + Math.cos(aCrease - 0.35) * 52;
    const sy2 = ry + Math.sin(aCrease - 0.35) * 52;
    drawSaltCrystal(sx2, sy2, 5.2, k * 47);
  }
  drawCarawaySeed(rx - 8, ry - 6, 16, baseRot + 40, 0.22, false);
  drawSaltCrystal(rx + 10, ry - 10, 5.8, 30);
}

// ===========================================================================
// LAYER 5: CARAWAY SEED FOLIAGE ("WHERE LEAVES WOULD BE") & SCATTERED SEEDS
// ===========================================================================

function drawCarawayFoliageCluster(rx, ry, variant, shadowOnly = false) {
  // Four diagonal Morris foliate sprays radiating from around the knotted bread roll
  // into the spandrels between the interlocking pretzels
  const sprayDirs = [34, 146, 214, 326];

  for (let d = 0; d < sprayDirs.length; d++) {
    const baseDeg = sprayDirs[d];
    const rad = (baseDeg * Math.PI) / 180;
    const ca = Math.cos(rad);
    const sa = Math.sin(rad);
    const nx = -sa;
    const ny = ca;

    // Subtle toasted-wheat Morris stem arc connecting the seed leaflets
    if (!shadowOnly) {
      const stemPts = [];
      for (let s = 0; s <= 4; s++) {
        const dist = 84 + s * 17;
        const curve = Math.sin((s / 4) * Math.PI) * 8 * (d % 2 === 0 ? 1 : -1);
        stemPts.push([
          rx + ca * dist + nx * curve,
          ry + sa * dist + ny * curve,
          0.6
        ]);
      }
      strokeSpline(stemPts, "2H", PAL.seedRibDark, 0.7, 0.5);
    }

    // 7 caraway seeds arranged like pinnate Morris willow/acanthus leaflets along the spray
    const leaflets = [
      // Terminal tip seed
      { dist: 156, lat: 0, angOff: 4, len: 21, bend: 0.22 },
      // Upper pair of seed-leaflets
      { dist: 136, lat: -15, angOff: -38, len: 19.5, bend: 0.24 },
      { dist: 136, lat: 15, angOff: 38, len: 19.5, bend: -0.24 },
      // Middle pair of seed-leaflets
      { dist: 114, lat: -22, angOff: -48, len: 21, bend: 0.25 },
      { dist: 114, lat: 22, angOff: 48, len: 21, bend: -0.25 },
      // Basal pair of seed-leaflets near the knotted roll
      { dist: 92, lat: -18, angOff: -56, len: 18, bend: 0.22 },
      { dist: 92, lat: 18, angOff: 56, len: 18, bend: -0.22 }
    ];

    for (let i = 0; i < leaflets.length; i++) {
      const lf = leaflets[i];
      const sx = rx + ca * lf.dist + nx * lf.lat;
      const sy = ry + sa * lf.dist + ny * lf.lat;
      drawCarawaySeed(
        sx,
        sy,
        lf.len,
        baseDeg + lf.angOff,
        lf.bend,
        shadowOnly
      );
    }
  }

  // Lateral florets (triplets of caraway seeds at left & right of the knotted roll)
  for (const side of [-1, 1]) {
    const bx = rx + side * 102;
    const by = ry;
    const baseA = side === 1 ? 0 : 180;
    drawCarawaySeed(bx, by, 20, baseA, 0.2, shadowOnly);
    drawCarawaySeed(bx - side * 8, by - 14, 17.5, baseA - side * 42, 0.24, shadowOnly);
    drawCarawaySeed(bx - side * 8, by + 14, 17.5, baseA + side * 42, -0.24, shadowOnly);
  }

  // Rhythmically scattered loose caraway seeds & detached salt grains on the ground
  const looseSeeds = [
    [-156, -24, 18, 72, 0.22],
    [156, 26, 18.5, -68, -0.22],
    [-42, -104, 17, 15, 0.2],
    [44, -102, 17.5, 162, -0.2],
    [-46, 104, 18, -22, 0.24],
    [48, 102, 17, 205, -0.22]
  ];
  for (let i = 0; i < looseSeeds.length; i++) {
    const ls = looseSeeds[i];
    drawCarawaySeed(
      rx + ls[0],
      ry + ls[1],
      ls[2],
      ls[3] + variant * 12,
      ls[4],
      shadowOnly
    );
  }

  if (!shadowOnly) {
    drawSaltCrystal(rx - 134, ry - 14, 4.8, 22);
    drawSaltCrystal(rx + 136, ry + 16, 5.0, 61);
    drawSaltCrystal(rx - 28, ry - 94, 4.5, 44);
    drawSaltCrystal(rx + 30, ry + 94, 4.6, 19);
  }
}

