// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function shapeFromPts(pts, curvature = 0.22) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function washPoly(pts, col, opacity = 220, curvature = 0.22) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  shapeFromPts(pts, curvature);
  brush.noWash();
}

function fillPoly(pts, col, opacity = 85, bleed = 0.18, bleedDir = "out", tex = 0.72, border = 0.82, curvature = 0.22) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, bleedDir);
  brush.fillTexture(tex, border);
  shapeFromPts(pts, curvature);
  brush.noFill();
}

function subdivideOrganic(pts, iterations = 2, jitterScale = 0.16, seedOffset = 0) {
  let curr = pts.map(p => [p[0], p[1]]);
  for (let it = 0; it < iterations; it++) {
    let next = [];
    for (let i = 0; i < curr.length; i++) {
      let p1 = curr[i];
      let p2 = curr[(i + 1) % curr.length];
      next.push(p1);
      let mx = (p1[0] + p2[0]) * 0.5;
      let my = (p1[1] + p2[1]) * 0.5;
      let dx = p2[0] - p1[0];
      let dy = p2[1] - p1[1];
      let len = sqrt(dx * dx + dy * dy);
      let nx = -dy / (len || 1);
      let ny = dx / (len || 1);
      let nVal = noise(mx * 0.008 + seedOffset, my * 0.008 + it * 13.7) - 0.5;
      let disp = nVal * len * jitterScale * 2.0;
      next.push([mx + nx * disp, my + ny * disp]);
    }
    curr = next;
  }
  return curr;
}

function insetPolygon(pts, cx, cy, scaleFactor, noiseAmt = 6, seedOff = 0) {
  return pts.map((p, idx) => {
    let dx = p[0] - cx;
    let dy = p[1] - cy;
    let n = (noise(p[0] * 0.01 + seedOff, p[1] * 0.01 + idx) - 0.5) * 2 * noiseAmt;
    let len = sqrt(dx * dx + dy * dy) || 1;
    return [
      cx + dx * scaleFactor + (dx / len) * n,
      cy + dy * scaleFactor + (dy / len) * n
    ];
  });
}

function centroid(pts) {
  let sx = 0, sy = 0;
  for (let p of pts) {
    sx += p[0];
    sy += p[1];
  }
  return [sx / pts.length, sy / pts.length];
}

function pointInPoly(x, y, vs) {
  let inside = false;
  for (let i = 0, j = vs.length - 1; i < vs.length; j = i++) {
    let xi = vs[i][0], yi = vs[i][1];
    let xj = vs[j][0], yj = vs[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 0.0001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

// ============================================================================
// 1. PINK BUTCHER PAPER & PENCIL-GRAIN CRUMPLED RIDGES
// ============================================================================

function drawButcherPaperGround() {
  // Subtle large chiller-light variations across the pink butcher paper
  const paperZones = [
    { pts: [[0, 0], [680, 0], [590, 540], [0, 620]], col: "#edd8d1", op: 36 },
    { pts: [[560, 0], [1200, 0], [1200, 680], [610, 580]], col: "#d9bfc0", op: 32 },
    { pts: [[0, 540], [620, 610], [580, 1200], [0, 1200]], col: "#dcc0ba", op: 38 },
    { pts: [[570, 590], [1200, 560], [1200, 1200], [520, 1200]], col: "#cfb4b1", op: 42 },
    { pts: [[180, 120], [1040, 150], [1060, 1060], [140, 1040]], col: "#f2dfda", op: 26 }
  ];

  for (let z of paperZones) {
    let sub = subdivideOrganic(z.pts, 2, 0.18, 11);
    fillPoly(sub, z.col, z.op, 0.38, "out", 0.55, 0.25, 0.3);
  }

  // Fine matte butcher-paper fibre grain across the sheet
  brush.noFill();
  brush.noWash();
  brush.hatchStyle("2H", "#c9ada7", 0.42);
  brush.hatch(9, 14, { rand: 0.14 });
  brush.noStroke();
  brush.rect(10, 10, 1180, 1180, "corner");
  brush.noHatch();

  brush.hatchStyle("cpencil", "#f3e3de", 0.38);
  brush.hatch(13, 104, { rand: 0.18 });
  brush.noStroke();
  brush.rect(10, 10, 1180, 1180, "corner");
  brush.noHatch();
}

function generatePaperCreases() {
  // A triangulated network of outer & through-running paper fold vertices
  const nodes = [
    [0, 85], [310, 0], [760, 0], [1200, 110],
    [1200, 470], [1200, 870], [940, 1200], [420, 1200],
    [0, 1040], [0, 520],
    // Interior paper crease vertices
    [165, 195], [445, 145], [845, 165], [1045, 295],
    [1085, 650], [995, 965], [685, 1065], [265, 1015],
    [115, 765], [135, 415],
    // Deep interior nodes (creases passing under the steak)
    [355, 365], [735, 345], [835, 745], [435, 825]
  ];

  const edges = [
    // Outer to ring
    [0, 10], [1, 10], [1, 11], [2, 11], [2, 12], [3, 12], [3, 13],
    [4, 13], [4, 14], [5, 14], [5, 15], [6, 15], [6, 16], [7, 16],
    [7, 17], [8, 17], [8, 18], [9, 18], [9, 19], [0, 19],
    // Perimeter ring connections
    [10, 11], [11, 12], [12, 13], [13, 14], [14, 15],
    [15, 16], [16, 17], [17, 18], [18, 19], [19, 10],
    // Secondary diagonal crumple ridges
    [10, 20], [11, 20], [11, 21], [12, 21], [13, 21],
    [14, 22], [15, 22], [16, 22], [16, 23], [17, 23],
    [18, 23], [19, 20], [20, 21], [21, 22], [22, 23], [23, 20]
  ];

  let creases = [];
  for (let i = 0; i < edges.length; i++) {
    let a = nodes[edges[i][0]];
    let b = nodes[edges[i][1]];
    let steps = 9;
    let pts = [];
    let dx = b[0] - a[0];
    let dy = b[1] - a[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;

    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let px = lerp(a[0], b[0], t);
      let py = lerp(a[1], b[1], t);
      let wobble = sin(t * 180) * (noise(px * 0.009, py * 0.009, i) - 0.5) * 28;
      pts.push([px + nx * wobble, py + ny * wobble]);
    }
    creases.push({
      pts,
      strength: random(0.55, 1.15),
      nx, ny,
      angle: atan2(dy, dx)
    });
  }
  return creases;
}

function drawPaperCreaseNetwork(creases) {
  for (let c of creases) {
    let pts = c.pts;
    let nx = c.nx;
    let ny = c.ny;
    let st = c.strength;

    // 1. Cool diffuse chiller-cabinet shadow band on one side of the ridge
    let shadowWidth = 18 * st;
    let shadowPoly = [];
    for (let i = 0; i < pts.length; i++) {
      shadowPoly.push([pts[i][0], pts[i][1]]);
    }
    for (let i = pts.length - 1; i >= 0; i--) {
      let taper = sin((i / (pts.length - 1)) * 180);
      let w = shadowWidth * (0.35 + 0.65 * taper);
      shadowPoly.push([pts[i][0] + nx * w, pts[i][1] + ny * w]);
    }
    washPoly(shadowPoly, "#cbb0ab", 46 * st, 0.15);

    // Deeper core shadow right against the fold spine
    brush.set("velvet_wash", "#b69894", 0.55 * st);
    let spineShadowPts = pts.map(p => [p[0] + nx * 3.5, p[1] + ny * 3.5, random(0.4, 0.9)]);
    brush.spline(spineShadowPts, 0.35);

    // 2. Pencil grain skimming across the crumpled paper ridge
    // Grazing short directional graphite & colored-pencil strokes across the crest
    let totalSegments = pts.length - 1;
    for (let i = 0; i < totalSegments; i++) {
      let p1 = pts[i];
      let p2 = pts[i + 1];
      let segSteps = 10;
      for (let k = 0; k < segSteps; k++) {
        if (random() > 0.78) continue;
        let t = k / segSteps;
        let gx = lerp(p1[0], p2[0], t);
        let gy = lerp(p1[1], p2[1], t);
        let env = sin(((i + t) / totalSegments) * 180);
        let hLen = random(5, 18) * st * (0.4 + 0.6 * env);
        let jitterAng = c.angle + 68 + random(-14, 14);
        let ca = cos(jitterAng);
        let sa = sin(jitterAng);

        // Dark graphite tooth on shadow flank of ridge
        brush.set(random() < 0.5 ? "2B" : "HB", "#9c7e79", random(0.28, 0.52) * st);
        brush.line(
          gx - ca * 1.5,
          gy - sa * 1.5,
          gx + ca * hLen,
          gy + sa * hLen
        );

        // Warm dry paper-tooth highlight on lit flank of ridge
        if (random() < 0.65) {
          brush.set("cpencil", "#f9ece8", random(0.32, 0.6) * st);
          brush.line(
            gx - ca * hLen * 0.65,
            gy - sa * hLen * 0.65,
            gx + ca * 1.0,
            gy + sa * 1.0
          );
        }
      }
    }

    // 3. Crisp graphite & chalk-pink crease spine line
    brush.set("2H", "#8f706b", 0.38 * st);
    let ridgePts = pts.map(p => [p[0], p[1], random(0.3, 0.85)]);
    brush.spline(ridgePts, 0.3);

    brush.set("cpencil", "#fbf0ec", 0.52 * st);
    let litPts = pts.map(p => [p[0] - nx * 2.2, p[1] - ny * 2.2, random(0.4, 0.95)]);
    brush.spline(litPts, 0.3);
  }
}

// ============================================================================
// 2. ANATOMICAL GEOMETRY OF THE RIBEYE STEAK
// ============================================================================

function buildRibeyeAnatomy() {
  // Overall ribeye silhouette (filling ~80% of the 1200x1200 frame)
  const rawOutline = [
    [145, 675], [132, 555], [158, 430], [228, 322],
    [345, 244], [492, 202], [655, 198], [808, 232],
    [932, 302], [1024, 405], [1068, 535], [1058, 672],
    [998, 795], [892, 898], [748, 958], [582, 978],
    [418, 956], [278, 886], [186, 792]
  ];
  const outerContour = subdivideOrganic(rawOutline, 3, 0.14, 31);

  // 1. SPINALIS DORSI (The Ribeye Cap / Deckle)
  // Sweeping crescent muscle wrapping around top-left and top arch
  // Parameterized along an arc from angle 165 deg (left) clockwise to 332 deg (top-right)
  let spinalisLobes = [];
  const capCount = 12;
  const capCx = 565, capCy = 575;

  for (let i = 0; i < capCount; i++) {
    let t0 = i / capCount;
    let t1 = (i + 1) / capCount;
    // Leave irregular Calacatta fat channels (width 6..16px) between cap bundles
    let gap = 0.012 + 0.01 * noise(i * 1.7, 9.2);
    let a0 = lerp(192, 336, t0 + gap);
    let a1 = lerp(192, 336, t1 - gap);

    let lobePts = [];
    let steps = 5;
    // Outer rim of Spinalis
    for (let s = 0; s <= steps; s++) {
      let a = lerp(a0, a1, s / steps);
      let radOut = getSpinalisOuterRadius(a);
      lobePts.push([capCx + cos(a) * radOut, capCy + sin(a) * radOut]);
    }
    // Inner rim of Spinalis (bordering the intermuscular fat seam)
    for (let s = steps; s >= 0; s--) {
      let a = lerp(a0, a1, s / steps);
      let radIn = getSpinalisInnerRadius(a);
      lobePts.push([capCx + cos(a) * radIn, capCy + sin(a) * radIn]);
    }

    let organicLobe = subdivideOrganic(lobePts, 2, 0.18, 100 + i * 7);
    let c = centroid(organicLobe);
    let midA = (a0 + a1) * 0.5;
    spinalisLobes.push({
      pts: organicLobe,
      center: c,
      grainAngle: midA + 12, // Radial muscle grain in the cap
      region: "spinalis",
      id: i
    });
  }

  // 2. COMPLEXUS / MULTIFIDUS DORSI
  // Wedge-shaped muscle tucked between the Spinalis cap, central fat kernel, and Longissimus eye
  const complexusRaw = [
    [[455, 382], [552, 362], [568, 428], [468, 442]],
    [[566, 360], [668, 358], [678, 418], [580, 426]],
    [[682, 360], [775, 372], [768, 426], [690, 420]]
  ];
  let complexusLobes = complexusRaw.map((pts, idx) => {
    let sub = subdivideOrganic(pts, 2, 0.18, 210 + idx * 13);
    return {
      pts: sub,
      center: centroid(sub),
      grainAngle: -12 + idx * 8,
      region: "complexus",
      id: idx
    };
  });

  // 3. LONGISSIMUS DORSI (The Center Eye of the Ribeye)
  // Large oval muscle belly occupying the center & lower-right, subdivided into organic territories
  // separated by primary Calacatta fat rivers
  let eyeLobes = [];
  const eyeCx = 655, eyeCy = 685;
  const eyeRx = 335, eyeRy = 235;
  const gridCols = 5;
  const gridRows = 4;

  // Warped anatomical grid helper
  function eyeGridPt(u, v) {
    // u in [-1, 1], v in [-1, 1]
    // Slightly flatten top-left where the central fat kernel indents the eye
    let indent = 0;
    if (u < -0.15 && v < -0.1) {
      indent = (-0.15 - u) * (-0.1 - v) * 165;
    }
    let bx = eyeCx + u * eyeRx + v * 28 + indent * 0.65;
    let by = eyeCy + v * eyeRy - u * 18 + indent * 0.85;
    let wx = (noise(u * 1.8 + 4.1, v * 1.8 + 2.3) - 0.5) * 52;
    let wy = (noise(u * 1.8 + 8.7, v * 1.8 + 5.9) - 0.5) * 46;
    return [bx + wx, by + wy];
  }

  for (let r = 0; r < gridRows; r++) {
    for (let c = 0; c < gridCols; c++) {
      let u0 = map(c, 0, gridCols, -0.96, 0.96);
      let u1 = map(c + 1, 0, gridCols, -0.96, 0.96);
      let v0 = map(r, 0, gridRows, -0.94, 0.94);
      let v1 = map(r + 1, 0, gridRows, -0.94, 0.94);

      // Skip extreme corners outside the elliptical muscle belly
      let um = (u0 + u1) * 0.5;
      let vm = (v0 + v1) * 0.5;
      if (um * um + vm * vm > 1.08) continue;
      // Leave room at top-left of eye for the large central fat kernel
      if (r === 0 && c === 0) continue;

      // Shrink each cell slightly to create primary Calacatta fat seams between lobes
      let seamU = 0.022 + 0.018 * noise(c * 2.1, r * 2.1);
      let seamV = 0.024 + 0.018 * noise(c * 3.3 + 5, r * 3.3);
      let ua = u0 + seamU;
      let ub = u1 - seamU;
      let va = v0 + seamV;
      let vb = v1 - seamV;

      let cellPts = [
        eyeGridPt(ua, va),
        eyeGridPt((ua + ub) * 0.5, va),
        eyeGridPt(ub, va),
        eyeGridPt(ub, (va + vb) * 0.5),
        eyeGridPt(ub, vb),
        eyeGridPt((ua + ub) * 0.5, vb),
        eyeGridPt(ua, vb),
        eyeGridPt(ua, (va + vb) * 0.5)
      ];

      // Clamp points inside the outerLongissimus envelope
      cellPts = cellPts.map(p => clampToEyeEnvelope(p[0], p[1], eyeCx, eyeCy, eyeRx, eyeRy));
      let subCell = subdivideOrganic(cellPts, 2, 0.19, 300 + r * 17 + c * 5);
      let ctr = centroid(subCell);

      eyeLobes.push({
        pts: subCell,
        center: ctr,
        grainAngle: 28 + (noise(ctr[0] * 0.005, ctr[1] * 0.005) - 0.5) * 26,
        region: "longissimus",
        id: r * 10 + c
      });
    }
  }

  // 4. TAIL / LIP MUSCLE SLIPS (Left heel & lower-left rim)
  const tailRaw = [
    [[172, 668], [268, 652], [292, 748], [194, 755]],
    [[212, 772], [308, 762], [338, 848], [248, 845]]
  ];
  let tailLobes = tailRaw.map((pts, idx) => {
    let sub = subdivideOrganic(pts, 2, 0.18, 500 + idx * 19);
    return {
      pts: sub,
      center: centroid(sub),
      grainAngle: 62 + idx * 14,
      region: "tail",
      id: idx
    };
  });

  // 5. CENTRAL FAT KERNEL ("The Eye Fat") & OUTER FAT LOBES
  const centralFatKernel = subdivideOrganic([
    [295, 595], [345, 455], [442, 412], [462, 465],
    [548, 455], [512, 535], [405, 565], [345, 625]
  ], 3, 0.17, 701);

  const rightFatKernel = subdivideOrganic([
    [915, 375], [988, 412], [1035, 515], [982, 545], [928, 452]
  ], 2, 0.16, 709);

  const bottomLeftFatLobe = subdivideOrganic([
    [325, 815], [412, 855], [465, 932], [358, 918], [285, 865]
  ], 2, 0.16, 719);

  return {
    outerContour,
    spinalisLobes,
    complexusLobes,
    eyeLobes,
    tailLobes,
    allMuscleLobes: [...spinalisLobes, ...complexusLobes, ...eyeLobes, ...tailLobes],
    centralFatKernel,
    rightFatKernel,
    bottomLeftFatLobe
  };
}

function getSpinalisOuterRadius(angleDeg) {
  // Distance from (565, 575) to outer cap boundary
  let t = map(angleDeg, 190, 340, 0, 1);
  let base = 365 + sin(t * 180) * 32 - t * 22;
  let n = (noise(cos(angleDeg) * 1.5 + 2, sin(angleDeg) * 1.5 + 2) - 0.5) * 28;
  return base + n;
}

function getSpinalisInnerRadius(angleDeg) {
  // Distance from (565, 575) to inner cap boundary (fat seam)
  let t = map(angleDeg, 190, 340, 0, 1);
  let thickness = 118 + sin(t * 180) * 44 - pow(t, 2) * 38;
  let n = (noise(cos(angleDeg) * 2.2 + 7, sin(angleDeg) * 2.2 + 7) - 0.5) * 24;
  return getSpinalisOuterRadius(angleDeg) - thickness + n;
}

function clampToEyeEnvelope(x, y, cx, cy, rx, ry) {
  let dx = (x - cx) / rx;
  let dy = (y - cy) / ry;
  let d = sqrt(dx * dx + dy * dy);
  if (d > 0.96) {
    let scale = 0.96 / d;
    return [cx + (x - cx) * scale, cy + (y - cy) * scale];
  }
  return [x, y];
}

// ============================================================================
// 3. FAINT PINK BLOOD SEEP WICKING INTO PAPER FIBRES
// ============================================================================

function drawBloodSeep(outerContour, creases) {
  let c = centroid(outerContour);

  // Build 3 concentric irregular wicking halos expanding outward into the paper
  let seepOuter = outerContour.map((p, i) => {
    let dx = p[0] - c[0];
    let dy = p[1] - c[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let ang = atan2(dy, dx);
    // Seep pools slightly wider on lower-right, bottom, and upper-left paper troughs
    let poolBias = 1.0 + 0.45 * sin(ang * 2 - 35) + 0.3 * sin(ang * 3 + 50);
    let wickDist = (26 + 54 * noise(p[0] * 0.009, p[1] * 0.009)) * poolBias;
    return [p[0] + (dx / len) * wickDist, p[1] + (dy / len) * wickDist];
  });

  let seepMid = outerContour.map((p, i) => {
    let dx = p[0] - c[0];
    let dy = p[1] - c[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let ang = atan2(dy, dx);
    let poolBias = 1.0 + 0.4 * sin(ang * 2 - 35);
    let wickDist = (14 + 32 * noise(p[0] * 0.012 + 5, p[1] * 0.012 + 5)) * poolBias;
    return [p[0] + (dx / len) * wickDist, p[1] + (dy / len) * wickDist];
  });

  let seepInner = outerContour.map((p, i) => {
    let dx = p[0] - c[0];
    let dy = p[1] - c[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let wickDist = 5 + 14 * noise(p[0] * 0.018 + 9, p[1] * 0.018 + 9);
    return [p[0] + (dx / len) * wickDist, p[1] + (dy / len) * wickDist];
  });

  // Pass 1: Faint pale rose-salmon outer wicking halo
  fillPoly(seepOuter, "#e39b9e", 42, 0.38, "out", 0.78, 0.88, 0.25);

  // Pass 2: Mid myoglobin pink-rose seep
  fillPoly(seepMid, "#d67278", 48, 0.28, "out", 0.74, 0.85, 0.25);

  // Pass 3: Deeper carmine-rose purge right against the meat edge
  fillPoly(seepInner, "#ba424d", 62, 0.2, "out", 0.7, 0.8, 0.25);

  // Capillary feathering into the paper fibres & dried pigment tide-line
  for (let i = 0; i < seepOuter.length; i++) {
    let p1 = seepOuter[i];
    let p2 = seepOuter[(i + 1) % seepOuter.length];

    // Dried granulating tide-line at the outer edge of the blood seep
    brush.set("granulate_edge", "#c45e66", random(0.35, 0.75));
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    if (random() < 0.65) {
      brush.set("2H", "#bd565e", random(0.25, 0.45));
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // Fine capillary wicking threads along paper grain
    if (i % 2 === 0) {
      let pm = seepMid[i];
      let dx = p1[0] - pm[0];
      let dy = p1[1] - pm[1];
      brush.set("velvet_wash", "#dc8288", random(0.3, 0.6));
      brush.line(pm[0], pm[1], p1[0] + dx * 0.35, p1[1] + dy * 0.35);
    }
  }
}

function drawSteakContactShadow(outerContour) {
  let c = centroid(outerContour);
  // Tight dark plum-crimson contact shadow where the wet meat edge meets the paper
  let contactRing = outerContour.map(p => {
    let dx = p[0] - c[0];
    let dy = p[1] - c[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    return [p[0] + (dx / len) * 2.5 + 1.5, p[1] + (dy / len) * 2.5 + 2.5];
  });

  washPoly(contactRing, "#5e1822", 125, 0.22);

  for (let i = 0; i < outerContour.length; i++) {
    let p1 = outerContour[i];
    let p2 = outerContour[(i + 1) % outerContour.length];
    brush.set("2B", "#420b12", random(0.45, 0.85));
    brush.line(p1[0] + 1, p1[1] + 2, p2[0] + 1, p2[1] + 2);
  }
}

// ============================================================================
// 4. CREAMY IVORY SUET & INTERMUSCULAR FAT FOUNDATION
// ============================================================================

function drawFatFoundation(steakGeo) {
  // Opaque creamy-ivory base over the entire ribeye silhouette so paper creases underneath are covered
  washPoly(steakGeo.outerContour, "#f8f0e6", 252, 0.22);
  washPoly(steakGeo.outerContour, "#f5eadc", 190, 0.22);

  // Subtle wet-in-wet watercolor modeling of the ivory fat matrix
