  fillPoly(steakGeo.centralFatKernel, "#e8dcd8", 55, 0.25, "in", 0.65, 0.55, 0.25);
  fillPoly(steakGeo.rightFatKernel, "#e5d7d4", 52, 0.25, "in", 0.65, 0.55, 0.25);
  fillPoly(steakGeo.bottomLeftFatLobe, "#eadbd5", 50, 0.25, "in", 0.65, 0.55, 0.25);

  // Warm buttery suet & blush transfusion washes along the intermuscular seam
  let seamCurve = [
    [225, 655], [325, 565], [415, 482], [545, 438],
    [695, 428], [835, 422], [955, 445]
  ];
  for (let i = 0; i < seamCurve.length - 1; i++) {
    let p1 = seamCurve[i];
    let p2 = seamCurve[i + 1];
    brush.set("velvet_wash", "#edd6c4", random(1.1, 1.8));
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Soft rose-pink transfusion where muscle pigments bleed into the edge of the fat seam
    brush.set("velvet_wash", "#e6b4b7", random(0.8, 1.35));
    brush.line(p1[0] + random(-18, 18), p1[1] + random(-18, 18), p2[0] + random(-18, 18), p2[1] + random(-18, 18));
  }
}

// ============================================================================
// 5. WET-IN-WET ALIZARIN & MADDER-CARMINE MUSCLE COMPARTMENTS
// ============================================================================

function drawMuscleCompartments(steakGeo) {
  const allLobes = steakGeo.allMuscleLobes;

  // Color palette for muscle compartments:
  // Madder carmine, alizarin crimson, venetian rose-red, and deep oxblood-burgundy
  const baseWashColors = ["#b52d3a", "#a62330", "#c23b47", "#991d29"];
  const madderFills = ["#a82230", "#b82e3b", "#961a27", "#c43845"];
  const alizarinCoreFills = ["#78111c", "#660b15", "#871723", "#570710"];

  // PASS A: Luminous rose-carmine wet under-wash for every muscle compartment
  // Slightly expanded soft blush halo first so muscle bleeds wet-in-wet into the ivory fat seams
  for (let i = 0; i < allLobes.length; i++) {
    let lobe = allLobes[i];
    let bleedHalo = insetPolygon(lobe.pts, lobe.center[0], lobe.center[1], 1.045, 3, i * 11);
    washPoly(bleedHalo, "#e8a5aa", 85, 0.25);

    let baseCol = baseWashColors[i % baseWashColors.length];
    washPoly(lobe.pts, baseCol, 205, 0.22);
  }

  // PASS B: Wet-in-wet Madder Carmine watercolor fills (batched by color for performance)
  // High fillTexture borderIntensity (0.92) creates crisp granulating edges where the paint dried!
  for (let cIdx = 0; cIdx < madderFills.length; cIdx++) {
    let col = madderFills[cIdx];
    for (let i = cIdx; i < allLobes.length; i += madderFills.length) {
      let lobe = allLobes[i];
      fillPoly(lobe.pts, col, 95, 0.14, "in", 0.84, 0.94, 0.22);
    }
  }

  // PASS C: Deep Alizarin Crimson inner muscle bellies (off-center sub-polygons within each lobe)
  for (let cIdx = 0; cIdx < alizarinCoreFills.length; cIdx++) {
    let col = alizarinCoreFills[cIdx];
    for (let i = cIdx; i < allLobes.length; i += alizarinCoreFills.length) {
      let lobe = allLobes[i];
      let subCore = insetPolygon(
        lobe.pts,
        lobe.center[0] + random(-12, 12),
        lobe.center[1] + random(-12, 12),
        random(0.58, 0.78),
        7,
        i * 23 + 90
      );
      fillPoly(subCore, col, 92, 0.16, "out", 0.86, 0.92, 0.24);
    }
  }

  // PASS D: Fibrous Muscle Fascicle Striations & Crisp Dried Granulating Boundaries
  for (let i = 0; i < allLobes.length; i++) {
    let lobe = allLobes[i];
    let pts = lobe.pts;
    let cx = lobe.center[0];
    let cy = lobe.center[1];
    let ga = lobe.grainAngle;
    let ca = cos(ga);
    let sa = sin(ga);

    // 1. Crisp granulating pigment boundary where alizarin/carmine muscle meets ivory fat
    for (let j = 0; j < pts.length; j++) {
      let p1 = pts[j];
      let p2 = pts[(j + 1) % pts.length];
      brush.set("granulate_edge", "#5c0912", random(0.55, 1.05));
      brush.line(p1[0], p1[1], p2[0], p2[1]);

      if (random() < 0.75) {
        brush.set("2B", "#47050c", random(0.35, 0.65));
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }

    // 2. Internal velvety sarcomere / muscle-bundle texture along anatomical grain
    let fiberCount = lobe.region === "longissimus" ? 42 : 28;
    for (let f = 0; f < fiberCount; f++) {
      let rx = cx + random(-75, 75);
      let ry = cy + random(-65, 65);
      if (!pointInPoly(rx, ry, pts)) continue;

      let fLen = random(10, 28);
      let x1 = rx - ca * fLen * 0.5;
      let y1 = ry - sa * fLen * 0.5;
      let x2 = rx + ca * fLen * 0.5;
      let y2 = ry + sa * fLen * 0.5;
      if (!pointInPoly(x2, y2, pts)) continue;

      let tonePick = random();
      if (tonePick < 0.45) {
        // Deep oxblood-alizarin crevice between muscle fibers
        brush.set("velvet_wash", "#590810", random(0.35, 0.75));
        brush.line(x1, y1, x2, y2);
      } else if (tonePick < 0.8) {
        // Warm madder-rose midtone bundle
        brush.set("velvet_wash", "#b82d39", random(0.4, 0.8));
        brush.line(x1, y1, x2, y2);
      } else {
        // Fine dark crimson grain line
        brush.set("2B", "#42040a", random(0.28, 0.5));
        brush.line(x1, y1, x2, y2);
      }
    }
  }
}

// ============================================================================
// 6. CALACATTA INTRAMUSCULAR MARBLING & GRANULATING EDGES
// ============================================================================

function drawCalacattaMarbling(steakGeo) {
  // Every muscle lobe receives a rich dendritic network of Calacatta-like ivory fat veins
  // that branch at acute geological angles, bleed softly into the muscle,
  // and leave crisp granulating alizarin edges where the paint dried.
  const allLobes = steakGeo.allMuscleLobes;

  for (let i = 0; i < allLobes.length; i++) {
    let lobe = allLobes[i];
    let pts = lobe.pts;
    let ga = lobe.grainAngle;

    // Number of primary Calacatta vein trees per muscle compartment
    let numTrees = lobe.region === "longissimus" ? 6 : (lobe.region === "spinalis" ? 5 : 3);

    for (let t = 0; t < numTrees; t++) {
      // Pick a starting point on the perimeter of the muscle lobe (growing inward from the fat seam)
      let startIdx = floor(map(t + random(0.15, 0.85), 0, numTrees, 0, pts.length)) % pts.length;
      let startPt = pts[startIdx];

      // Aim generally across the lobe or along the local muscle grain with Calacatta angularity
      let toCenterAng = atan2(lobe.center[1] - startPt[1], lobe.center[0] - startPt[0]);
      let initAng = lerpAngleDeg(toCenterAng, ga + (random() < 0.5 ? 0 : 180), 0.55) + random(-22, 22);
      let initWidth = lobe.region === "spinalis" ? random(4.2, 7.5) : random(3.5, 6.8);
      let maxLen = lobe.region === "longissimus" ? random(65, 135) : random(48, 95);

      growCalacattaVein(
        startPt[0],
        startPt[1],
        initAng,
        initWidth,
        maxLen,
        0,
        pts,
        steakGeo.outerContour
      );
    }

    // Additional fine island rivulets ("flecking" / micro-marbling inside the muscle belly)
    let fleckCount = lobe.region === "longissimus" ? 11 : 7;
    for (let f = 0; f < fleckCount; f++) {
      let fx = lobe.center[0] + random(-65, 65);
      let fy = lobe.center[1] + random(-55, 55);
      if (!pointInPoly(fx, fy, pts)) continue;

      let fAng = ga + random(-28, 28);
      growCalacattaVein(
        fx,
        fy,
        fAng,
        random(1.6, 3.2),
        random(22, 48),
        2,
        pts,
        steakGeo.outerContour
      );
    }
  }
}

function lerpAngleDeg(a, b, amt) {
  let diff = ((b - a + 540) % 360) - 180;
  return a + diff * amt;
}

function growCalacattaVein(x, y, angle, width, totalLen, depth, lobePoly, outerPoly) {
  if (depth > 3 || width < 0.65 || totalLen < 10) return;

  let stepLen = 8.5;
  let steps = floor(totalLen / stepLen);
  if (steps < 2) return;

  let backbone = [[x, y, width]];
  let currX = x;
  let currY = y;
  let currAng = angle;
  let currW = width;

  let childBranches = [];

  for (let s = 1; s <= steps; s++) {
    let t = s / steps;
    // Calacatta veining has characteristic angular geological inflections mixed with flow
    let angleTurn = (noise(currX * 0.018 + depth * 7, currY * 0.018 + s * 0.3) - 0.5) * 42;
    if (s % 3 === 0) angleTurn += random(-24, 24);
    currAng += angleTurn;

    let nx = currX + cos(currAng) * stepLen;
    let ny = currY + sin(currAng) * stepLen;

    // Keep inside steak silhouette
    if (!pointInPoly(nx, ny, outerPoly)) break;

    // Swell at branching nodes and taper toward tips
    let swell = 1.0 + 0.38 * sin(t * 540 + depth * 60);
    currW = width * (1.0 - 0.72 * pow(t, 0.85)) * swell;
    backbone.push([nx, ny, max(0.55, currW)]);

    // Spawn branching Calacatta rivulets at acute angles (28 - 58 degrees)
    let branchProb = depth === 0 ? 0.34 : (depth === 1 ? 0.26 : 0.16);
    if (s >= 1 && s < steps - 1 && random() < branchProb) {
      let side = random() < 0.5 ? 1 : -1;
      let bAng = currAng + side * random(28, 56);
      let bWidth = currW * random(0.52, 0.78);
      let bLen = (totalLen - s * stepLen) * random(0.65, 1.05);
      childBranches.push({ x: nx, y: ny, ang: bAng, w: bWidth, len: bLen });
    }

    currX = nx;
    currY = ny;
  }

  if (backbone.length < 2) return;

  // RENDER THE CALACATTA VEIN IN 4 HYPERREAL WATERCOLOR PASSES:

  // 1. Soft Wet-in-Wet Rose/Blush Bleed into the surrounding muscle
  let bleedColor = depth === 0 ? "#e0858c" : "#d66972";
  brush.set("velvet_wash", bleedColor, constrain(width * 0.22, 0.3, 1.15));
  let bleedSpline = backbone.map(p => [p[0], p[1], constrain(p[2] * 0.28, 0.25, 1.1)]);
  brush.spline(bleedSpline, 0.35);

  // 2. Crisp Granulating Dried Edges along BOTH flanks of the vein
  let leftRibbon = [];
  let rightRibbon = [];
  for (let i = 0; i < backbone.length; i++) {
    let p = backbone[i];
    let pNext = backbone[min(i + 1, backbone.length - 1)];
    let pPrev = backbone[max(i - 1, 0)];
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let px = -dy / len;
    let py = dx / len;
    let hw = p[2] * 0.55;

    leftRibbon.push([p[0] + px * hw, p[1] + py * hw]);
    rightRibbon.push([p[0] - px * hw, p[1] - py * hw]);

    // Granulated dark alizarin/oxblood pigment flocculation at the dried vein edge
    if (i < backbone.length - 1) {
      let p2 = backbone[i + 1];
      let hw2 = p2[2] * 0.55 + 1.0;
      brush.set("granulate_edge", "#54070f", constrain(p[2] * 0.14, 0.25, 0.75));
      brush.line(
        p[0] + px * (hw + 1.0), p[1] + py * (hw + 1.0),
        p2[0] + px * hw2, p2[1] + py * hw2
      );
      brush.line(
        p[0] - px * (hw + 1.0), p[1] - py * (hw + 1.0),
        p2[0] - px * hw2, p2[1] - py * hw2
      );
    }
  }

  // 3. Creamy Ivory Calacatta Fat Core
  if (width >= 2.6 && leftRibbon.length >= 3) {
    let veinPoly = [...leftRibbon, ...rightRibbon.reverse()];
    let ivoryCol = depth === 0 ? "#f8f0e4" : "#f3e3d8";
    washPoly(veinPoly, ivoryCol, depth === 0 ? 225 : 185, 0.2);
  }

  // Fine branching ivory stroke along the vein centerline
  let coreColor = depth <= 1 ? "#faf3e8" : "#f2d8d9";
  brush.set("calacatta_vein", coreColor, constrain(width * 0.24, 0.22, 1.1));
  let coreSpline = backbone.map(p => [p[0], p[1], constrain(p[2] * 0.32, 0.2, 1.2)]);
  brush.spline(coreSpline, 0.32);

  // Subtle warm tallow / cool chiller tint inside wider Calacatta trunks
  if (depth === 0 && width > 4.0) {
    brush.set("cpencil", "#e3d2c4", 0.42);
    brush.spline(coreSpline, 0.32);
  }

  // 4. Recurse on child rivulets
  for (let b of childBranches) {
    growCalacattaVein(b.x, b.y, b.ang, b.w, b.len, depth + 1, lobePoly, outerPoly);
  }
}

// ============================================================================
// 7. INTERNAL SUET MODELING, TRANSLUCENT FISSURES & OUTER RIM DETAILS
// ============================================================================

function drawSuetDetailsAndRim(steakGeo) {
  // Like true Calacatta marble and raw beef suet, the large intermuscular fat pockets
  // have delicate grey-taupe/violet fissures, warm tallow clouds, and fine pink capillaries
  const fatCenters = [
    [415, 495, 85], [335, 585, 52], [535, 442, 45],
    [715, 432, 38], [865, 432, 42], [975, 475, 48],
    [385, 885, 46], [215, 605, 38], [985, 685, 35]
  ];

  for (let fc of fatCenters) {
    let cx = fc[0], cy = fc[1], rad = fc[2];

    // Cool chiller-cabinet grey-violet marble fissures inside the fat
    for (let k = 0; k < 7; k++) {
      let a1 = random(360);
      let r1 = random(8, rad * 0.8);
      let x1 = cx + cos(a1) * r1;
      let y1 = cy + sin(a1) * r1;
      let a2 = a1 + random(60, 160);
      let r2 = random(8, rad * 0.85);
      let x2 = cx + cos(a2) * r2;
      let y2 = cy + sin(a2) * r2;
      let mx = (x1 + x2) * 0.5 + random(-14, 14);
      let my = (y1 + y2) * 0.5 + random(-14, 14);

      // Soft cool fissure wash
      brush.set("velvet_wash", "#d4c3be", random(0.35, 0.65));
      brush.spline([[x1, y1, 0.3], [mx, my, 0.8], [x2, y2, 0.25]], 0.4);

      // Crisp fine fissure line
      brush.set("2H", "#bba5a0", random(0.28, 0.48));
      brush.spline([[x1, y1, 0.2], [mx, my, 0.7], [x2, y2, 0.2]], 0.4);

      // Tiny rose capillary thread in the suet
      if (random() < 0.45) {
        brush.set("cpencil", "#d98288", random(0.25, 0.42));
        brush.line(x1, y1, mx, my);
      }
    }

    // Creamy high-value suet pillow domes
    for (let d = 0; d < 4; d++) {
      let dx = cx + random(-rad * 0.45, rad * 0.45);
      let dy = cy + random(-rad * 0.45, rad * 0.45);
      brush.set("calacatta_vein", "#fdf8f0", random(0.65, 1.2));
      brush.line(dx - 8, dy - 4, dx + 8, dy + 4);
    }
  }

  // Outer Perimeter Rim of the Ribeye:
  // Trimmed tallow edge, connective silverskin sheen, and granulating crimson-ochre edge
  const outer = steakGeo.outerContour;
  for (let i = 0; i < outer.length; i++) {
    let p1 = outer[i];
    let p2 = outer[(i + 1) % outer.length];
    let p3 = outer[(i + 2) % outer.length];

    // Warm tallow-ochre & rose glaze along the trimmed outer fat edge
    brush.set("velvet_wash", random() < 0.5 ? "#dfc2a8" : "#d98a8e", random(0.45, 0.85));
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Crisp granulating outer watercolor contour
    brush.set("granulate_edge", "#8f2430", random(0.4, 0.8));
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    if (i % 2 === 0) {
      brush.set("HB", "#7a2029", random(0.28, 0.48));
      brush.spline([[p1[0], p1[1], 0.3], [p2[0], p2[1], 0.8], [p3[0], p3[1], 0.3]], 0.35);
    }
  }
}

// ============================================================================
// 8. GLISTENING MOISTURE & LIFTED WATERCOLOR HIGHLIGHTS
// ============================================================================

function drawGlisteningHighlights(steakGeo) {
  const allLobes = steakGeo.allMuscleLobes;

  // A. Softly "Lifted" Damp-Brush Watercolor Highlights inside the Muscle Bellies
  // (Luminous pale icy-rose & salmon-pink zones where wet pigment was lifted)
  for (let i = 0; i < allLobes.length; i++) {
    let lobe = allLobes[i];
    let cx = lobe.center[0];
    let cy = lobe.center[1];
    let ga = lobe.grainAngle;
    let ca = cos(ga);
    let sa = sin(ga);

    let liftCount = lobe.region === "longissimus" ? 9 : 6;
    for (let l = 0; l < liftCount; l++) {
      let lx = cx + random(-60, 60);
      let ly = cy + random(-50, 50);
      if (!pointInPoly(lx, ly, lobe.pts)) continue;

      let len = random(8, 22);
      let x1 = lx - ca * len * 0.5;
      let y1 = ly - sa * len * 0.5;
      let x2 = lx + ca * len * 0.5;
      let y2 = ly + sa * len * 0.5;

      // Soft lifted rose-pink glow
      brush.set("velvet_wash", "#f0a8ae", random(0.45, 0.85));
      brush.line(x1, y1, x2, y2);

      brush.set("calacatta_vein", "#f7cdd0", random(0.32, 0.6));
      brush.line(x1, y1, x2, y2);
    }
  }

  // B. Crisp Glistening Moisture Beads & Specular Micro-Shards (Cool Chiller Light)
  // Placed along the convex ridges of muscle bundles and the wet lips of Calacatta veins
  for (let i = 0; i < allLobes.length; i++) {
    let lobe = allLobes[i];
    let pts = lobe.pts;
    let cx = lobe.center[0];
    let cy = lobe.center[1];
    let ga = lobe.grainAngle;
    let ca = cos(ga);
    let sa = sin(ga);

    // 1. Glistening wet speculars inside muscle bellies
    let specCount = lobe.region === "longissimus" ? 14 : 9;
    for (let s = 0; s < specCount; s++) {
      let sx = cx + random(-68, 68);
      let sy = cy + random(-58, 58);
      if (!pointInPoly(sx, sy, pts)) continue;

      // Tiny dark alizarin ring right beside the specular bead for maximum wet contrast
      brush.set("2B", "#45040b", random(0.3, 0.55));
      brush.line(sx - 2, sy + 1.5, sx + 3, sy + 2.0);

      // Crisp cool-white chiller specular shard
      let sLen = random(2.5, 7.5);
      let mx = sx + ca * sLen * 0.5 + random(-2, 2);
      let my = sy + sa * sLen * 0.5 + random(-2, 2);
      brush.set("wet_sheen", "#f7fafc", random(0.45, 0.95));
      brush.spline([
        [sx, sy, 0.3],
        [mx, my, 1.1],
        [sx + ca * sLen, sy + sa * sLen, 0.2]
      ], 0.35);

      // Pinpoint moisture glint next to the shard
      if (random() < 0.7) {
        brush.set("wet_sheen", "#ffffff", random(0.6, 1.1));
        brush.line(sx - 2.5, sy - 1.5, sx - 1.0, sy - 1.0);
      }
    }

    // 2. Wet meniscus highlights along the boundary where muscle meets fat seam
    for (let j = 0; j < pts.length; j += 2) {
      if (random() > 0.55) continue;
      let p1 = pts[j];
      let p2 = pts[(j + 1) % pts.length];
      let mx = (p1[0] + p2[0]) * 0.5;
      let my = (p1[1] + p2[1]) * 0.5;

      brush.set("wet_sheen", "#fdf7f8", random(0.4, 0.85));
      brush.line(p1[0], p1[1], mx, my);
    }
  }

  // C. Glistening Sheen on the Creamy Fat Kernel & Pooled Blood Seep
  const wetFatZones = [
    [405, 485], [345, 565], [525, 445], [685, 428],
    [845, 425], [965, 465], [375, 875], [225, 615]
  ];
  for (let wz of wetFatZones) {
    for (let k = 0; k < 6; k++) {
      let hx = wz[0] + random(-35, 35);
      let hy = wz[1] + random(-35, 35);
      let ang = random(360);
      let l = random(4, 11);
      brush.set("wet_sheen", "#ffffff", random(0.55, 1.05));
      brush.line(hx, hy, hx + cos(ang) * l, hy + sin(ang) * l);
    }
  }

  // Wet highlights along the pooled blood seep right against the bottom & right meat edge
  const outer = steakGeo.outerContour;
  for (let i = 0; i < outer.length; i += 3) {
    let p = outer[i];
    let pNext = outer[(i + 1) % outer.length];
    let dx = pNext[0] - p[0];
    let dy = pNext[1] - p[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;
    // Offset 5..12px into the wet blood seep pool
    let off = random(4, 11);
    let wx = p[0] - nx * off;
    let wy = p[1] - ny * off;

    brush.set("wet_sheen", "#fceef0", random(0.4, 0.8));
    brush.line(wx, wy, wx + (dx / len) * random(5, 12), wy + (dy / len) * random(5, 12));
  }
}

// Hyperreal Flemish-Mirror Study: Parked Car Side Mirror in Carmine, Verdigris & Lead-White

let GLASS_POLY = [];
let GLASS_NORMALS = [];
let GLASS_RADII = new Float32Array(3600);
const GCX = 595;
const GCY = 562;
const N_PERIM = 180;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
