// ============================================================================
// GEOMETRY & OPTICAL PROJECTION HELPERS
// ============================================================================

function buildMirrorGeometry() {
  // 9 control points defining an iconic aerodynamic European side-mirror contour
  const ctrl = [
    [248, 332], // top-left (inner upper corner)
    [445, 282], // top-mid-left
    [735, 294], // top-mid-right
    [945, 362], // top-right (outer upper corner)
    [982, 560], // right-mid (outer edge)
    [928, 772], // bottom-right (outer lower corner)
    [585, 826], // bottom-mid
    [238, 795], // bottom-left (inner lower corner)
    [198, 562]  // left-mid (inner edge)
  ];

  const M = ctrl.length;
  GLASS_POLY = [];
  for (let i = 0; i < N_PERIM; i++) {
    let tGlobal = (i / N_PERIM) * M;
    let idx = Math.floor(tGlobal);
    let t = tGlobal - idx;
    let p0 = ctrl[(idx - 1 + M) % M];
    let p1 = ctrl[idx];
    let p2 = ctrl[(idx + 1) % M];
    let p3 = ctrl[(idx + 2) % M];
    GLASS_POLY.push(catmullRomPoint(p0, p1, p2, p3, t));
  }

  // Compute smooth outward normals
  GLASS_NORMALS = [];
  for (let i = 0; i < N_PERIM; i++) {
    let prev = GLASS_POLY[(i - 2 + N_PERIM) % N_PERIM];
    let next = GLASS_POLY[(i + 2) % N_PERIM];
    let dx = next[0] - prev[0];
    let dy = next[1] - prev[1];
    let len = Math.hypot(dx, dy) || 1;
    let nx = dy / len;
    let ny = -dx / len;
    // Ensure normal points outward from (GCX, GCY)
    let p = GLASS_POLY[i];
    if ((p[0] - GCX) * nx + (p[1] - GCY) * ny < 0) {
      nx = -nx;
      ny = -ny;
    }
    GLASS_NORMALS.push([nx, ny]);
  }

  // Build 0.1-degree polar radius lookup table for O(1) clipping
  for (let a = 0; a < 3600; a++) {
    let rad = (a * 0.1 - 180) * (Math.PI / 180);
    let dx = Math.cos(rad);
    let dy = Math.sin(rad);
    let bestR = 300;
    for (let i = 0; i < N_PERIM; i++) {
      let p1 = GLASS_POLY[i];
      let p2 = GLASS_POLY[(i + 1) % N_PERIM];
      let hit = raySegmentIntersect(GCX, GCY, dx, dy, p1[0], p1[1], p2[0], p2[1]);
      if (hit !== null) {
        bestR = hit;
        break;
      }
    }
    GLASS_RADII[a] = bestR;
  }
}

function catmullRomPoint(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * t +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * t +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
  );
  return [x, y];
}

function raySegmentIntersect(ox, oy, dx, dy, x1, y1, x2, y2) {
  let sx = x2 - x1;
  let sy = y2 - y1;
  let denom = dx * sy - dy * sx;
  if (Math.abs(denom) < 1e-7) return null;
  let t = ((x1 - ox) * sy - (y1 - oy) * sx) / denom;
  let u = ((x1 - ox) * dy - (y1 - oy) * dx) / denom;
  if (t >= 0 && u >= -0.001 && u <= 1.001) return t;
  return null;
}

function getGlassRadiusAt(x, y) {
  let ang = Math.atan2(y - GCY, x - GCX) * (180 / Math.PI);
  let idx = Math.floor((ang + 180) * 10) % 3600;
  if (idx < 0) idx += 3600;
  return GLASS_RADII[idx];
}

function isInsideGlass(x, y, margin = 0) {
  let r = Math.hypot(x - GCX, y - GCY);
  return r <= getGlassRadiusAt(x, y) + margin;
}

function clampPointToGlass(x, y, margin = 1.5) {
  let dx = x - GCX;
  let dy = y - GCY;
  let r = Math.hypot(dx, dy);
  let rMax = getGlassRadiusAt(x, y) + margin;
  if (r > rMax && r > 0.001) {
    let s = rMax / r;
    return [GCX + dx * s, GCY + dy * s];
  }
  return [x, y];
}

// Evaluates point on bezel/housing ring at perimeter index `idx` (can be float)
// `s` in [0, 1] = plastic bezel; `s` in [1, 3] = lacquered oxblood housing
function getFramePoint(idxFloat, s) {
  let i0 = ((Math.floor(idxFloat) % N_PERIM) + N_PERIM) % N_PERIM;
  let i1 = (i0 + 1) % N_PERIM;
  let frac = idxFloat - Math.floor(idxFloat);

  let p0 = GLASS_POLY[i0];
  let p1 = GLASS_POLY[i1];
  let n0 = GLASS_NORMALS[i0];
  let n1 = GLASS_NORMALS[i1];

  let px = p0[0] + (p1[0] - p0[0]) * frac;
  let py = p0[1] + (p1[1] - p0[1]) * frac;
  let nx = n0[0] + (n1[0] - n0[0]) * frac;
  let ny = n0[1] + (n1[1] - n0[1]) * frac;
  let nlen = Math.hypot(nx, ny) || 1;
  nx /= nlen;
  ny /= nlen;

  // Directional thickness profiles for bezel and outer cowl
  let topFactor = Math.max(0, -ny);
  let botFactor = Math.max(0, ny);
  let leftFactor = Math.max(0, -nx);
  let rightFactor = Math.max(0, nx);

  let bezelW = 20 + 6 * topFactor + 24 * botFactor + 10 * leftFactor + 2 * rightFactor;
  let cowlW = 48 + 76 * topFactor + 32 * botFactor + 48 * leftFactor + 8 * rightFactor;

  let offset = 0;
  if (s <= 1.0) {
    offset = s * bezelW;
  } else {
    offset = bezelW + ((s - 1.0) / 2.0) * cowlW;
  }

  // Slight sculpted aerodynamic sweep on upper-left and upper cowl
  let sweepX = s > 1.0 ? -12 * ((s - 1.0) / 2.0) * leftFactor * topFactor : 0;
  let sweepY = s > 1.0 ? -10 * ((s - 1.0) / 2.0) * topFactor : 0;

  return [px + nx * offset + sweepX, py + ny * offset + sweepY];
}

function getRingPatch(iStart, iEnd, sInner, sOuter, steps = 16) {
  let pts = [];
  for (let k = 0; k <= steps; k++) {
    let idx = iStart + (iEnd - iStart) * (k / steps);
    pts.push(getFramePoint(idx, sInner));
  }
  for (let k = steps; k >= 0; k--) {
    let idx = iStart + (iEnd - iStart) * (k / steps);
    pts.push(getFramePoint(idx, sOuter));
  }
  return pts;
}

// Convex spherical mirror optical projection: maps virtual scene (u, v) -> canvas [x, y]
function sceneToMirror(u, v) {
  // Subtle extra wide-angle refraction past the aspheric blind-spot line (u > 0.56)
  let uEff = u;
  if (u > 0.56) {
    uEff = 0.56 + (u - 0.56) * 1.16;
  }
  let r2 = uEff * uEff + v * v;
  let k = 0.46;
  let scale = 1.0 / Math.sqrt(1.0 + k * r2);

  // Barrel-curved coordinates around optical center
  let rx = 472;
  let ry = 338;
  let x = GCX + uEff * scale * rx;
  let y = GCY + v * scale * ry;
  return [x, y];
}

// Converts a polygon in (u, v) scene space to a glass-clamped screen polygon
function projectScenePoly(uvPts, subdivide = 6, margin = 1.5) {
  let screenPts = [];
  let n = uvPts.length;
  for (let i = 0; i < n; i++) {
    let a = uvPts[i];
    let b = uvPts[(i + 1) % n];
    for (let s = 0; s < subdivide; s++) {
      let t = s / subdivide;
      let u = a[0] + (b[0] - a[0]) * t;
      let v = a[1] + (b[1] - a[1]) * t;
      let p = sceneToMirror(u, v);
      screenPts.push(clampPointToGlass(p[0], p[1], margin));
    }
  }
  return screenPts;
}

// Projects a polyline in (u, v) scene space and clips it strictly inside the glass
function projectSceneCurve(uvPts, subdivide = 6, margin = 0.5) {
  let raw = [];
  for (let i = 0; i < uvPts.length - 1; i++) {
    let a = uvPts[i];
    let b = uvPts[i + 1];
    let steps = (i === uvPts.length - 2) ? subdivide + 1 : subdivide;
    for (let s = 0; s < steps; s++) {
      let t = s / subdivide;
      let u = a[0] + (b[0] - a[0]) * t;
      let v = a[1] + (b[1] - a[1]) * t;
      raw.push(sceneToMirror(u, v));
    }
  }
  return clipScreenCurveToGlass(raw, margin);
}

function clipScreenCurveToGlass(pts, margin = 0.5) {
  let runs = [];
  let current = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (isInsideGlass(p[0], p[1], margin)) {
      current.push(p);
    } else {
      if (current.length > 0) {
        let clamped = clampPointToGlass(p[0], p[1], margin);
        current.push(clamped);
        if (current.length >= 2) runs.push(current);
        current = [];
      }
    }
  }
  if (current.length >= 2) runs.push(current);
  return runs;
}

// ============================================================================
// SAFE P5.BRUSH DRAWING WRAPPERS
// ============================================================================

function washPoly(pts, col, alpha = 100) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, alpha);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function fillPoly(pts, col, alpha = 90, bleed = 0.08, tex = 0.35, border = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function hatchPoly(pts, brushName, col, weight, dist, angle, opts = { rand: 0.04 }) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noMass();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noHatch();
}

function strokeCurve(pts, brushName, col, weight = 0.5, curvature = 0.3) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(brushName, col, weight);
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, curvature);
  }
  brush.noStroke();
}

function strokeSceneCurve(uvPts, brushName, col, weight = 0.4, subdivide = 6, curvature = 0.25) {
  let runs = projectSceneCurve(uvPts, subdivide, 0.5);
  for (let r of runs) {
    strokeCurve(r, brushName, col, weight, curvature);
  }
}

function washScenePoly(uvPts, col, alpha = 110, subdivide = 5) {
  let pts = projectScenePoly(uvPts, subdivide, 1.5);
  washPoly(pts, col, alpha);
}

function fillScenePoly(uvPts, col, alpha = 85, bleed = 0.06, tex = 0.3, border = 0.2, subdivide = 5) {
  let pts = projectScenePoly(uvPts, subdivide, 1.5);
  fillPoly(pts, col, alpha, bleed, tex, border);
}

function hatchScenePoly(uvPts, brushName, col, weight, dist, angle, subdivide = 5) {
  let pts = projectScenePoly(uvPts, subdivide, 1.0);
  hatchPoly(pts, brushName, col, weight, dist, angle, { rand: 0.03 });
}

