  // --- THE BAKERY AWNING (Alternating Carmine & Lead-White Stripes, curving in convex glass) ---
  // Slopes outward from building wall (vTop = -0.19) to front valance (vFront = -0.04) across u: -0.21 to +0.31
  const nStripes = 13;
  const uAwningStart = -0.21;
  const uAwningEnd = 0.31;
  const duStripe = (uAwningEnd - uAwningStart) / nStripes;

  // Cast shadow under the awning
  washScenePoly([[-0.21, -0.05], [0.31, -0.04], [0.31, 0.01], [-0.21, 0.0]], "#081414", 210, 6);

  for (let s = 0; s < nStripes; s++) {
    let u0 = uAwningStart + s * duStripe;
    let u1 = u0 + duStripe;
