  strokeSceneCurve([[uAwningStart, -0.19], [0.05, -0.19], [uAwningEnd, -0.19]], "rotring", "#182226", 0.38, 6, 0.2);
  strokeSceneCurve([[uAwningStart + 0.006, -0.055], [0.056, -0.055], [uAwningEnd + 0.006, -0.055]], "flemish_pen", "#f8fbfc", 0.45, 6, 0.2);

  // --- BUILDING 3: Right-center Blue-Slate Guild House (u: 0.32 to 0.68) ---
