  strokeSceneCurve([[0.32, -0.49], [0.50, -0.47], [0.68, -0.45]], "flemish_pen", "#c2d2d8", 0.4, 4, 0.2);

  // Tall windows on Building 3
  for (let row = 0; row < 2; row++) {
