      fillScenePoly([[uL, vT], [uR, vT], [uR, vT + 0.06], [uL, vT + 0.06]], "#648e9c", 105, 0.04, 0.2, 0.1, 2);
      strokeSceneCurve([[uL, vT], [uR, vT], [uR, vB], [uL, vB], [uL, vT]], "flemish_pen", "#c2d2d8", 0.26, 2, 0.05);
    }
  }

  // --- BUILDING 4: Far-Right Corner Building curving across the blind-spot line (u: 0.68 to 1.15) ---
  let b4Wall = [[0.68, -0.42], [1.15, -0.34], [1.15, 0.15], [0.68, 0.14]];
