  }

  // Wet vertical reflection glazes on the cobblestones (sky, carmine awning, verdigris shopfront)
  // Luminous sky reflection channel down the center-right of the wet street
  fillScenePoly([[-0.12, 0.22], [0.38, 0.22], [0.52, 0.85], [-0.24, 0.85]], "#6c929e", 75, 0.18, 0.35, 0.15, 6);
