  // Carmine bakery awning & woman's coat reflection on wet pavement
  fillScenePoly([[-0.18, 0.21], [0.28, 0.21], [0.24, 0.46], [-0.16, 0.44]], "#7c1220", 72, 0.15, 0.35, 0.15, 5);
  fillScenePoly([[0.22, 0.28], [0.36, 0.28], [0.34, 0.56], [0.20, 0.56]], "#8e1424", 85, 0.14, 0.3, 0.15, 4);

  // Verdigris reflections under shopfront & painter
