  // Curving cobblestone courses & individual glinting wet stone tops
  for (let row = 0; row < 15; row++) {
    let t = row / 14;
    let v = 0.23 + t * t * 0.74;
    let weight = 0.22 + t * 0.22;
    let uStart = -0.64;
    let uEnd = 1.08;

    // Dark course seam
    strokeSceneCurve([[uStart, v], [-0.1, v], [0.4, v], [uEnd, v]], "rotring", "#121e24", weight, 8, 0.3);

    // Individual wet cobble highlights along the course
    let stepU = 0.065 + t * 0.035;
    for (let u = uStart + (row % 2) * stepU * 0.5; u < uEnd - stepU; u += stepU) {
      if ((Math.sin(u * 37 + row * 19) > -0.25)) {
        let hCol = (u > -0.15 && u < 0.38) ? "#d4e6ec" : "#6c8892";
        strokeSceneCurve([[u + 0.008, v - 0.004], [u + stepU * 0.68, v - 0.004]], "flemish_pen", hCol, weight * 0.85, 2, 0.2);
