function makeUVCircle(uc, vc, ru, rv, n = 20) {
  let pts = [];
  for (let i = 0; i <= n; i++) {
    let a = (i / n) * Math.PI * 2;
    pts.push([uc + Math.cos(a) * ru, vc + Math.sin(a) * rv]);
  }
  return pts;
}

