function drawGlassOpticalSurface() {
  // 1. Curved translucent sky sheen across upper dome of convex glass
  fillScenePoly([[-0.85, -0.92], [0.75, -0.92], [0.55, -0.42], [-0.65, -0.42]], "#dceef4", 24, 0.2, 0.2, 0.1, 8);
