  // 2. Aspheric Blind-Spot Vertical Dotted Etched Line at u = 0.56
  for (let v = -0.94; v <= 0.92; v += 0.036) {
    strokeSceneCurve([[0.56, v], [0.56, v + 0.016]], "rotring", "#182830", 0.32, 2, 0.1);
    strokeSceneCurve([[0.562, v + 0.002], [0.562, v + 0.015]], "flemish_pen", "#d8ecef", 0.26, 2, 0.1);
  }

  // 3. Minuscule Calligraphic Mirror Safety/Flemish Inscription along bottom curve (v = 0.88)
  for (let u = -0.32; u <= 0.32; u += 0.018) {
    if (Math.abs(Math.sin(u * 95)) > 0.22) {
      let h = 0.008 + 0.005 * Math.cos(u * 140);
      strokeSceneCurve([[u, 0.885], [u + 0.004, 0.885 - h], [u + 0.009, 0.885]], "flemish_pen", "#d4e4ea", 0.22, 2, 0.1);
    }
  }

  // 4. Prismatic Beveled Glass Edge Refraction Ring just inside GLASS_POLY
  let bevelPtsInner = [];
  let bevelPtsOuter = [];
  for (let i = 0; i <= N_PERIM; i++) {
    let idx = i % N_PERIM;
    let p = GLASS_POLY[idx];
    let n = GLASS_NORMALS[idx];
    bevelPtsOuter.push([p[0] - n[0] * 2, p[1] - n[1] * 2]);
    bevelPtsInner.push([p[0] - n[0] * 9, p[1] - n[1] * 9]);
  }
  // Upper-left & top bevel catches icy verdigris and lead-white refraction
  strokeCurve(bevelPtsInner.slice(0, 85), "flemish_pen", "#9cd4ce", 0.55, 0.3);
  strokeCurve(bevelPtsInner.slice(10, 68), "flemish_pen", "#f0f9fa", 0.65, 0.3);
