  strokeCurve(bevelPtsInner.slice(85, 165), "flemish_pen", "#527882", 0.45, 0.3);
  // Deep shadow crease right where glass meets the recessed plastic bezel
  strokeCurve(bevelPtsOuter, "rotring", "#060a0c", 0.75, 0.3);
}

