function drawMirrorHousingAndBezel() {
  // --- PART A: RECESSED MATTE CHARCOAL/SLATE PLASTIC BEZEL (s = 0.0 to 1.0) ---
  // Divide perimeter into 12 angular sectors for directional lighting on the plastic rim
  const nSectors = 18;
  const stepI = N_PERIM / nSectors;

  for (let k = 0; k < nSectors; k++) {
    let i0 = k * stepI;
    let i1 = (k + 1) * stepI;
    let midI = (i0 + i1) * 0.5;
    let n = GLASS_NORMALS[Math.floor(midI) % N_PERIM];

    // Bottom plastic lip faces UP toward the cool sky, so it's lighter slate-grey (#24323a)
    // Top plastic overhang faces DOWN into shadow, so it's deep charcoal-black (#0c1114)
    let skyFacing = Math.max(0, n[1]); // ny > 0 is bottom rim (interior wall faces up)
    let baseCol = skyFacing > 0.35 ? "#1e2a30" : (n[0] < -0.3 ? "#151e24" : "#0d1317");

    let patch = getRingPatch(i0 - 0.3, i1 + 0.3, 0.0, 1.02, 10);
    washPoly(patch, baseCol, 248);
  }

  // Upward-facing lower plastic ledge glaze (i = 95 to 160, s = 0.15 to 0.92)
  let lowerLedge = getRingPatch(96, 158, 0.12, 0.90, 32);
  fillPoly(lowerLedge, "#32444e", 115, 0.08, 0.4, 0.25);
  let lowerLedgeCore = getRingPatch(106, 148, 0.22, 0.72, 24);
  fillPoly(lowerLedgeCore, "#465c68", 85, 0.08, 0.35, 0.2);

  // Fine molded texture hatching along the matte plastic bezel
  for (let k = 0; k < nSectors; k++) {
    let i0 = k * stepI;
    let i1 = (k + 1) * stepI;
    let patch = getRingPatch(i0, i1, 0.05, 0.95, 6);
    hatchPoly(patch, "2H", "#080c0e", 0.28, 4.5, k * 20);
  }

  // Crisp inner & outer bevel seams of the plastic rim
  let innerRimCurve = [];
  let outerBezelSeam = [];
  for (let i = 0; i <= N_PERIM; i++) {
    innerRimCurve.push(getFramePoint(i, 0.04));
    outerBezelSeam.push(getFramePoint(i, 0.98));
  }
  strokeCurve(innerRimCurve, "rotring", "#05080a", 0.75, 0.3);
  strokeCurve(innerRimCurve.slice(95, 162), "flemish_pen", "#68828e", 0.45, 0.3);
  strokeCurve(outerBezelSeam, "rotring", "#06090b", 0.85, 0.3);

  // --- PART B: LACQUERED OXBLOOD RED HOUSING (s = 1.0 to 3.0) ---
  // 1. Deepest oxblood-black foundation across the entire housing shell
  for (let k = 0; k < nSectors; k++) {
    let i0 = k * stepI;
    let i1 = (k + 1) * stepI;
    let patch = getRingPatch(i0 - 0.3, i1 + 0.3, 1.0, 3.0, 10);
    washPoly(patch, "#220307", 248);
  }

  // 2. Multi-pass transparent oxblood & carmine glazes (Flemish jewel-like depth)
  const lacquerGlazes = [
    // Broad oxblood midtone body
    [0, 90, 1.05, 2.92, "#4a0610", 155, 0.10],
    [90, 180, 1.05, 2.92, "#38040b", 165, 0.10],
    // Rich carmine glow across upper cowl, left cheek, and outer sweep
    [0, 78, 1.12, 2.75, "#6e0a18", 135, 0.12],
    [135, 180, 1.12, 2.78, "#680916", 130, 0.12],
    // Luminous saturated carmine core in the thick upper-left and top dome
    [4, 66, 1.20, 2.52, "#921022", 125, 0.14],
    [10, 56, 1.28, 2.32, "#b4182c", 110, 0.14],
    [16, 48, 1.35, 2.10, "#cc2238", 85, 0.12],
    // Lower housing chin carmine reflection & dark street shadow core
    [88, 155, 1.08, 1.85, "#180205", 160, 0.10],
    [95, 148, 1.75, 2.65, "#5c0914", 115, 0.12],
    // Cool verdigris-slate secondary ground reflection along the bottom turning edge
    [85, 155, 2.45, 2.96, "#243c42", 95, 0.12],
    [98, 142, 2.60, 2.94, "#466c74", 75, 0.10],
    // Left cheek luminous carmine-verdigris interplay
    [145, 178, 1.25, 2.35, "#881020", 110, 0.12],
    [152, 175, 1.40, 2.05, "#ad182b", 90, 0.10]
  ];

  for (let g of lacquerGlazes) {
    let patch = getRingPatch(g[0], g[1], g[2], g[3], 28);
    fillPoly(patch, g[4], g[5], g[6], 0.28, 0.18);
  }

  // 3. Smooth lacquer marker glaze sweeps along the curved housing contours
  const sweepS = [1.3, 1.6, 1.9, 2.2, 2.5];
  for (let sVal of sweepS) {
    let curveTop = [];
    for (let i = 4; i <= 72; i += 2) {
      curveTop.push(getFramePoint(i, sVal));
    }
    strokeCurve(curveTop, "lacquer_glaze", "#8e1020", 1.1, 0.35);
  }

  // 4. High-gloss cool sky reflection band across the upper dome of the oxblood shell
  let skyBandOuter = getRingPatch(8, 68, 1.38, 2.22, 32);
  fillPoly(skyBandOuter, "#527886", 70, 0.12, 0.22, 0.12);

  let skyBandMid = getRingPatch(12, 62, 1.48, 2.02, 28);
  fillPoly(skyBandMid, "#8ab0be", 80, 0.10, 0.18, 0.10);

  let skyBandInner = getRingPatch(16, 56, 1.56, 1.88, 24);
  fillPoly(skyBandInner, "#c4dfe8", 95, 0.08, 0.15, 0.10);

  // 5. Razor-sharp lead-white specular highlight ribbons on the lacquered housing
  // Primary upper-dome specular ribbon (broken subtly at i = 40 by a reflected roofline)
  let specLeft = getRingPatch(18, 39, 1.64, 1.79, 18);
  washPoly(specLeft, "#eef7fa", 215);
  let specLeftCore = getRingPatch(21, 37, 1.68, 1.75, 14);
