  let specRightCore = getRingPatch(43, 52, 1.68, 1.73, 10);
  washPoly(specRightCore, "#ffffff", 230);

  // Secondary vertical-curved specular streak on the left sculpted cheek (i = 152..174)
  let cheekSpecGlow = getRingPatch(150, 175, 1.38, 1.72, 18);
  fillPoly(cheekSpecGlow, "#d88a96", 75, 0.10, 0.2, 0.1);
  let cheekSpecCore = getRingPatch(154, 171, 1.48, 1.58, 14);
  washPoly(cheekSpecCore, "#f2f7f9", 185);

  // Tight specular ridge highlight along s = 1.06 (where oxblood lacquer turns in toward the plastic bezel)
  let ridgeCurveTop = [];
  let ridgeCurveBot = [];
  let outerShellContour = [];
  for (let i = 0; i <= N_PERIM; i++) {
    outerShellContour.push(getFramePoint(i, 3.0));
    if (i >= 2 && i <= 82) ridgeCurveTop.push(getFramePoint(i, 1.07));
    if (i >= 92 && i <= 168) ridgeCurveBot.push(getFramePoint(i, 1.06));
