function drawRainSpottedDust() {
  // 1. Diffuse dusty film along the lower plastic bezel ledge & outer corners
  let dustFilmBand = getRingPatch(90, 165, 0.08, 0.94, 28);
  fillPoly(dustFilmBand, "#687478", 28, 0.15, 0.5, 0.3);

  // Fine spray of mineral dust along the bottom plastic rim & lower housing lip
  for (let i = 86; i <= 168; i += 2.2) {
    let p1 = getFramePoint(i, random(0.15, 0.88));
    let p2 = getFramePoint(i + 1.5, random(0.15, 0.88));
    strokeCurve([p1, p2], "dust_stipple", "#8e9a9c", 0.55, 0.1);
  }
  // Dust accumulation in the upper bezel crevice as well
  for (let i = 5; i <= 80; i += 3.5) {
    let p1 = getFramePoint(i, random(0.08, 0.45));
    let p2 = getFramePoint(i + 1.2, random(0.08, 0.45));
    strokeCurve([p1, p2], "dust_stipple", "#6c787a", 0.38, 0.1);
  }

  // 2. Dried Rain-Spotted Dust Rings on the Plastic Rim (s in [0.14, 0.86])
  // Each evaporated raindrop leaves a foreshortened ring of pale mineral dust with a slightly darker interior
  const nBezelSpots = 68;
  for (let k = 0; k < nBezelSpots; k++) {
    // Concentrate spots along the bottom ledge (i: 90..168), with scattered spots around sides/top
    let idx = (k < 50) ? random(90, 168) : random(0, 90);
    let s = random(0.16, 0.84);
    let center = getFramePoint(idx, s);
    let n = GLASS_NORMALS[Math.floor(idx) % N_PERIM];
    let tangAngle = Math.atan2(n[0], -n[1]) * (180 / Math.PI);

    let rx = random(3.2, 11.5);
    let ry = rx * random(0.45, 0.72); // Foreshortened on the sloped rim
    let spotPoly = makeEllipsePoly(center[0], center[1], rx, ry, tangAngle, 16);

    // Slightly cleaner/darker interior where the drop washed dust outward
    washPoly(spotPoly, "#10171b", 85);

    // Pale mineral-dust ring perimeter (ochre-ash / cool lead-grey / verdigris-silt)
    let ringCol = (k % 3 === 0) ? "#aeb8b6" : (k % 3 === 1 ? "#8a9698" : "#c4ceca");
    strokeCurve(spotPoly, "2H", ringCol, random(0.26, 0.42), 0.3);

    // Tiny silt accumulation crescent on the lower side of the dried drop ring
    let lowerArc = spotPoly.slice(4, 12);
    strokeCurve(lowerArc, "flemish_pen", "#d2dcd8", random(0.22, 0.34), 0.3);
  }

  // 3. Dried Rain-Spotted Dust Rings on the Lower & Outer Oxblood Lacquer Housing (s in [1.15, 2.85])
  const nLacquerSpots = 42;
  for (let k = 0; k < nLacquerSpots; k++) {
    let idx = (k < 30) ? random(78, 165) : random(50, 78);
    let s = random(1.18, 2.82);
    let center = getFramePoint(idx, s);
    let n = GLASS_NORMALS[Math.floor(idx) % N_PERIM];
    let tangAngle = Math.atan2(n[0], -n[1]) * (180 / Math.PI);

    let rx = random(4.0, 13.5);
    let ry = rx * random(0.50, 0.80);
    let spotPoly = makeEllipsePoly(center[0], center[1], rx, ry, tangAngle, 16);

    // Subtle interior glaze
    washPoly(spotPoly, "#2d0409", 60);

    // Delicate pale dust ring sitting atop the glossy oxblood lacquer
    let ringCol = (k % 2 === 0) ? "#9ca6a8" : "#b8c2c0";
    strokeCurve(spotPoly, "2H", ringCol, random(0.24, 0.38), 0.3);
    strokeCurve(spotPoly.slice(5, 11), "flemish_pen", "#d6e0de", 0.25, 0.3);
  }

  // 4. Fresh Glistening Micro-Droplets (with dark upper shadow & pinpoint lead-white bottom catchlight)
  const freshDrops = [
    [104, 0.55, 5.2], [116, 0.42, 6.8], [128, 0.65, 4.5], [139, 0.48, 7.2],
    [151, 0.58, 5.0], [95,  1.45, 6.0], [112, 2.15, 7.8], [124, 1.85, 5.5],
    [136, 2.35, 8.4], [148, 1.65, 6.2], [68,  1.95, 5.4], [76,  2.25, 6.5],
    [22,  2.45, 5.8], [35,  2.60, 4.8], [162, 1.90, 6.0]
  ];

  for (let fd of freshDrops) {
    let c = getFramePoint(fd[0], fd[1]);
    let r = fd[2];
    let dropPoly = makeEllipsePoly(c[0], c[1], r, r * 0.82, 0, 14);
    let shadowArc = dropPoly.slice(8, 14);
    let glowPoly = makeEllipsePoly(c[0], c[1] + r * 0.2, r * 0.65, r * 0.45, 0, 10);

    // Dark upper refraction inside droplet
    washPoly(dropPoly, "#090d10", 160);
    // Transmitted carmine or verdigris-slate belly glow
    let bellyCol = fd[1] > 1.0 ? "#a81828" : "#4e6c76";
    washPoly(glowPoly, bellyCol, 185);
    strokeCurve(shadowArc, "rotring", "#040608", 0.42, 0.3);

    // Pinpoint lead-white specular spark on the droplet
    strokeCurve([[c[0] - r * 0.28, c[1] - r * 0.22], [c[0] + r * 0.12, c[1] - r * 0.26]], "flemish_pen", "#ffffff", 0.62, 0.1);
    strokeCurve([[c[0] - r * 0.15, c[1] + r * 0.42], [c[0] + r * 0.22, c[1] + r * 0.38]], "flemish_pen", "#e8f4f8", 0.38, 0.1);
  }
}

function makeEllipsePoly(cx, cy, rx, ry, angleDeg = 0, n = 16) {
  let pts = [];
  let rad = angleDeg * (Math.PI / 180);
  let ca = Math.cos(rad);
  let sa = Math.sin(rad);
  for (let i = 0; i <= n; i++) {
    let a = (i / n) * Math.PI * 2;
    let ex = Math.cos(a) * rx;
    let ey = Math.sin(a) * ry;
    pts.push([
      cx + ex * ca - ey * sa,
      cy + ex * sa + ey * ca
    ]);
  }
  return pts;
}

// Hyperrealist study of a dented silver-gilt bowling trophy seen from below
// Medium: Dense charcoal and graphite tonal work with restrained watercolour glazes

const CX = 605;
const TILT = -1.8; // Slight monumental tilt in degrees

// Palette: Muted earth tones, warm gilt, tarnished purple/brown/blue-black, amber haze
const PAL = {
