  giltBrass: "#a88334",
  giltOldBrass: "#856625",
  giltPale: "#e6c97a",
  giltHighlight: "#f7e7b4",

  tarnishPurple: "#3b2238",
  tarnishPlum: "#522f4b",
  tarnishViolet: "#281729",
  tarnishBrown: "#3b281a",
  tarnishSmoky: "#543b28",
  tarnishUmber: "#241810",

  graphiteBlue: "#18202c",
  graphiteDark: "#10151d",
  graphiteMid: "#293342",
  graphiteSlate: "#434f61",
  graphiteSilver: "#8c96a3",
  charcoalDeep: "#0b0d11",

  woodDark: "#21130b",
  woodMid: "#3b2314",
  woodWarm: "#59361e"
};

