// ============================================================================
// MATHEMATICAL 3D TROPHY GEOMETRY, DENT PERTURBATION & SURFACE NORMALS
// ============================================================================

// Returns base radius R(y) of the trophy at vertical coordinate y (150..1195)
function getBaseRadius(y) {
  if (y > 1135) {
    // Heavy mahogany / silver-gilt plinth base
    return map(y, 1135, 1200, 325, 355);
  } else if (y > 1075) {
    // Stepped ogee foot moulding
    let t = (y - 1075) / 60;
    return 255 + 70 * pow(t, 0.7) + 12 * sin(t * 180);
  } else if (y > 955) {
    // Sweeping concave pedestal foot bell
    let t = (y - 955) / 120;
    return 88 + 167 * pow(t, 1.65);
  } else if (y > 845) {
    // Bulbous gadrooned stem knop
    let t = (y - 845) / 110; // 0 at top, 1 at bottom
    let bell = sin(t * 180);
    return 84 + 66 * pow(bell, 0.85);
  } else if (y > 775) {
    // Upper stem collar & calyx ring
    let t = (y - 775) / 70;
    return 132 - 48 * sin(t * 90) + 10 * sin(t * 360);
  } else if (y > 220) {
    // THE GREAT CUP BOWL (y = 220 rim down to y = 775 calyx)
    let t = (775 - y) / 555; // 0 at bottom of bowl, 1 at top lip
    if (t < 0.22) {
      // Lower gadrooned calyx swelling rapidly outward (seen from underneath!)
      let u = t / 0.22;
      return 132 + 168 * (1 - pow(1 - u, 2.2));
    } else if (t < 0.76) {
      // Full monumental belly curving up to slight neck waist
      let u = (t - 0.22) / 0.54;
      return 300 + 38 * sin(u * 155) - 18 * pow(u, 2.0);
    } else {
      // Flaring trumpet neck and heavy rolled lip at y = 220
      let u = (t - 0.76) / 0.24;
      let lipRoll = u > 0.82 ? 16 * sin(((u - 0.82) / 0.18) * 180) : 0;
      return 282 + 58 * pow(u, 1.55) + lipRoll;
    }
  } else if (y > 148) {
    // Domed gadrooned lid rising above the rim
    let t = (220 - y) / 72;
    return 312 * pow(1 - t * 0.74, 0.78) + 8 * sin(t * 360);
  } else {
    // Small pedestal cap for the bowler figure
    return 82;
  }
}

// Low-angle vertical ellipse foreshortening ratio (worm's-eye view)
// Because eye level is near y = 1190, higher rings curve strongly UPWARD in front
function getEllipseRatio(y) {
  return constrain(map(1215 - y, 0, 1080, 0.085, 0.285), 0.07, 0.30);
}

// Computes radial displacement dr and angular/vertical derivatives from DENTS & REPOUSSE RIBS
function getSurfacePerturbation(y, thetaDeg) {
  let dr = 0;
  let ddr_dtheta = 0;
  let ddr_dy = 0;

  // 1. PRIMARY DEEP DENT on the right-center belly (y ~ 478, theta ~ +25 deg)
  let u1 = (thetaDeg - 25) * 4.4;
  let v1 = y - 478;
  // Rotate dent axes by -16 degrees for natural oblique impact
  let dx1 = u1 * 0.961 - v1 * 0.276;
  let dy1 = u1 * 0.276 + v1 * 0.961;
  let rx1 = 98, ry1 = 82;
  let r2_1 = (dx1 * dx1) / (rx1 * rx1) + (dy1 * dy1) / (ry1 * ry1);

  if (r2_1 < 1.65) {
    let r1 = sqrt(r2_1);
    // Deep concave crater in center + sharp buckled ridge around rim (r1 ~ 0.88..1.18)
    let crater = r2_1 < 1.0 ? -35 * pow(1 - r2_1, 1.85) : 0;
    let buckle = 7.5 * exp(-pow((r1 - 0.96) / 0.16, 2)) * (1 + 0.35 * sin(atan2(dy1, dx1) * 2));
    // Secondary diagonal crease inside the dent
    let crease = r2_1 < 0.9 ? -6.5 * exp(-pow((dy1 - 0.25 * dx1 + 10) / 14, 2)) * (1 - r2_1) : 0;
    let dTotal = crater + buckle + crease;
    dr += dTotal;

    // Approximate partial derivatives for accurate reflection warping
    let slope = r2_1 < 1.0 ? 120 * r1 * (1 - r2_1) : -35 * (r1 - 0.96) * exp(-pow((r1 - 0.96) / 0.16, 2));
    ddr_dtheta += slope * (dx1 / (rx1 * rx1)) * 0.55 + crease * 0.08;
    ddr_dy += slope * (dy1 / (ry1 * ry1)) * 0.45 + (dy1 > 0 ? -0.35 : 0.42) * abs(dTotal) * 0.03;
  }

  // 2. SECONDARY SMALLER DING on lower-left belly (y ~ 595, theta ~ -37 deg)
  let dx2 = (thetaDeg + 37) * 4.1;
  let dy2 = y - 595;
  let r2_2 = (dx2 * dx2) / (46 * 46) + (dy2 * dy2) / (36 * 36);
  if (r2_2 < 1.4) {
    let crater2 = r2_2 < 1.0 ? -14 * pow(1 - r2_2, 1.7) : 0;
    let buckle2 = 3.2 * exp(-pow((sqrt(r2_2) - 0.95) / 0.18, 2));
    dr += crater2 + buckle2;
    ddr_dtheta += (dx2 / 46) * 18 * exp(-r2_2 * 1.5);
    ddr_dy += (dy2 / 36) * 18 * exp(-r2_2 * 1.5);
  }

  // 3. GADROONED FLUTES on the lower cup calyx (y = 655..775) and stem knop (y = 850..950)
  if (y > 650 && y < 775) {
    let tG = constrain(map(y, 650, 765, 0, 1), 0, 1);
    let env = sin(tG * 180);
    let fluteFreq = 16; // 16 repousse lobes around front half
    let wave = abs( cos(thetaDeg * (fluteFreq / 2)) );
    dr += 7.5 * env * pow(wave, 0.7);
    ddr_dtheta += -12 * env * sin(thetaDeg * fluteFreq);
  } else if (y > 850 && y < 950) {
    let env = sin(map(y, 850, 950, 0, 180));
    dr += 4.5 * env * cos(thetaDeg * 9);
    ddr_dtheta += -8 * env * sin(thetaDeg * 9);
  }

  return { dr, ddr_dtheta, ddr_dy };
}

// Projects 3D trophy coordinate (y, thetaDeg, extraRadialOffset) to 2D canvas (x, y)
// Also returns 3D surface normal (nx, ny, nz) for realistic lighting & reflection
function trophyPoint(y, thetaDeg, extraR = 0) {
  let baseR = getBaseRadius(y);
  let pert = getSurfacePerturbation(y, thetaDeg);
  let r = baseR + pert.dr + extraR;
  let ellRatio = getEllipseRatio(y);
  let ry = r * ellRatio;

  // Centerline shifts slightly with monumental tilt
  let dyRef = 650 - y;
  let cxLocal = CX + dyRef * sin(TILT);

  let sx = cxLocal + r * sin(thetaDeg);
  // Front (cos(thetaDeg) > 0) arches UPWARD (smaller y) because we look from below!
  let sy = y - ry * cos(thetaDeg);

  // Slope of profile dR/dy
  let dR_dy = (getBaseRadius(y + 2) - getBaseRadius(y - 2)) * 0.25 + pert.ddr_dy;
  let nx = sin(thetaDeg) - (pert.ddr_dtheta / max(40, r)) * cos(thetaDeg);
  let ny = dR_dy * 0.65 - 0.26 * cos(thetaDeg); // Tilted toward low viewer
  let nz = cos(thetaDeg) + (pert.ddr_dtheta / max(40, r)) * sin(thetaDeg);
  let len = sqrt(nx * nx + ny * ny + nz * nz) || 1;

  return {
    x: sx,
    y: sy,
    r: r,
    baseR: baseR,
    dr: pert.dr,
    nx: nx / len,
    ny: ny / len,
    nz: nz / len
  };
}

// Evaluates the distorted reflection of the wood-panelled clubhouse at surface normal (nx, ny, nz)
// Returns { tone: 0..1 (0=dark, 1=bright), isWoodPanel, isStile, isWindow, tarnishWeight }
function evaluateClubhouseReflection(y, thetaDeg, pt) {
  // View vector looking upward from low camera
  let vx = 0, vy = 0.34, vz = 0.94;
  let dotVN = vx * pt.nx + vy * pt.ny + vz * pt.nz;
  // Reflected ray R = V - 2*(V.N)*N
  let rx = vx - 2 * dotVN * pt.nx;
  let ry = vy - 2 * dotVN * pt.ny;
  let rz = vz - 2 * dotVN * pt.nz;

  let refAzimuth = atan2(rx, max(0.05, abs(rz))); // -90 to +90 deg
  let refElev = ry; // Vertical reflection elevation

  // Clubhouse wood panelling geometry in reflection space:
  // 7 vertical mahogany panels wrapping across the room
  let panelPhase = ((refAzimuth + 180) % 24) / 24; // 0..1 per panel bay
  let isStile = panelPhase < 0.14 || panelPhase > 0.86;
  let isBevel = (panelPhase >= 0.14 && panelPhase < 0.22) || (panelPhase <= 0.86 && panelPhase > 0.78);

  // Horizontal wainscot rails and coffered ceiling beams
  let isDadoRail = abs(refElev - 0.18) < 0.045 || abs(refElev + 0.24) < 0.04;
  let isCeilingWindow = refElev > 0.25 && !isStile && abs(refElev - 0.48) < 0.16;
  let isWarmLamp = pow(max(0, 1 - dist(refAzimuth, refElev * 90, -24, 34) / 26), 2) +
                   0.8 * pow(max(0, 1 - dist(refAzimuth, refElev * 90, 32, 28) / 22), 2);

  // Base metallic reflectance (0 = deep shadow, 1 = bright gilt specular)
  let tone = 0.32;
  if (isCeilingWindow) tone = 0.82;
  else if (isDadoRail) tone = 0.22;
  else if (isStile) tone = 0.44;
  else if (isBevel) tone = panelPhase < 0.5 ? 0.68 : 0.14; // Bevel catchlight vs shadow
  else {
    // Inside recessed wooden panel: cathedral woodgrain modulation
    let grain = noise(refAzimuth * 0.35, refElev * 9.0);
    tone = 0.24 + 0.18 * grain;
  }

  tone = constrain(tone + isWarmLamp * 0.45, 0.05, 1.0);

  // Inside the deep dent, add dramatic crease shadow and buckled rim highlight
  if (pt.dr < -4) {
    tone *= map(pt.dr, -35, -4, 0.35, 0.85);
    if (pt.ny < -0.15) tone = min(1.0, tone + 0.48); // Inverted upward catchlight on dent ridge
  } else if (pt.dr > 2.0) {
    tone = min(1.0, tone + 0.32); // Worn high point on buckled dent rim
  }

  // Tarnish distribution: half-tarnished organic bloom-patches + heavy in scroll zones
  let nTarnish = noise(thetaDeg * 0.045 + 10, y * 0.0085 + 20);
  let scrollBand = (y > 335 && y < 465) || (y > 585 && y < 695) ? 0.22 : 0;
  let dentTarnish = pt.dr < -8 ? 0.32 : 0;
  let tarnish = constrain(nTarnish * 1.15 - 0.28 + scrollBand + dentTarnish, 0, 1);

  return {
    tone,
    tarnish,
    refAzimuth,
    refElev,
    isStile,
    isBevel,
    isDadoRail,
    isCeilingWindow
  };
}

// ============================================================================
// MAIN RENDERING PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.bgDeep);

  // 1. Dim out-of-focus amber haze background
  drawAmberHazeBackground();

  // 2. Watercolour underpainting: warm gilt glazes & tarnish bloom-patches
  drawTrophyWatercolourGlazes();

  // 3. Distorted wood-panelled clubhouse reflection wrapping around the belly & dent
  drawWoodPanelledReflection();

  // 4. Dense charcoal & graphite tonal work on base, stem, calyx, rim, lid & dent
  drawMonumentalTonalStructure();

  // 5. Engraved baroque scrolls with bruised purple, smoky brown & blue-black tarnish
  drawEngravedScrollsAndCartouche();

  // 6. Ornate cast-gilt scroll handles & foreshortened bowler figure at the summit
  drawOrnateScrollHandles();
  drawForeshortenedBowlerFigure();

  // 7. Smudged adult fingerprints clouding the belly — every whorl rendered
  drawSmudgedFingerprints();

  // 8. Final hyperreal specular highlights, worn gilt brass & micro-scratches
  drawFinalSurfacePolish();

  noLoop();
}

// ============================================================================
// 1. DIM OUT-OF-FOCUS AMBER HAZE BACKGROUND
// ============================================================================

function drawAmberHazeBackground() {
  brush.noStroke();

  // Soft radial amber glow behind the trophy (batched by color for performance)
  const glowLayers = [
    { col: PAL.bgUmber, op: 95, bleed: 0.45, r: 580, n: 7 },
    { col: PAL.bgAmberDark, op: 80, bleed: 0.42, r: 470, n: 8 },
    { col: PAL.bgAmberMid, op: 65, bleed: 0.38, r: 370, n: 7 },
    { col: PAL.bgAmberBright, op: 50, bleed: 0.35, r: 260, n: 6 },
    { col: PAL.bgAmberGlow, op: 38, bleed: 0.32, r: 165, n: 5 }
  ];

  for (let layer of glowLayers) {
    brush.fill(layer.col, layer.op);
    brush.fillBleed(layer.bleed, "out");
    brush.fillTexture(0.55, 0.18);
    for (let i = 0; i < layer.n; i++) {
      let ang = i * (360 / layer.n) + random(-18, 18);
      let distFromCenter = random(40, layer.r * 0.55);
      let gx = CX + cos(ang) * distFromCenter;
      let gy = 520 + sin(ang) * distFromCenter * 1.15;
      brush.circle(gx, gy, layer.r * random(0.55, 0.92), 0.35);
    }
  }

  // Deep shadowy corners (vignette) in smoky umber & charcoal
  brush.fill(PAL.bgDeep, 130);
  brush.fillBleed(0.4, "in");
  const corners = [
    [80, 90, 320], [1120, 90, 320],
    [60, 600, 260], [1140, 600, 260],
    [90, 1120, 340], [1110, 1120, 340]
  ];
  for (let c of corners) {
    brush.circle(c[0], c[1], c[2], 0.4);
  }

  // Out-of-focus amber bokeh orbs in the dim clubhouse background
  const bokehCols = [PAL.bgAmberBright, PAL.bgAmberGlow, PAL.giltOchre];
  for (let bCol of bokehCols) {
    brush.fill(bCol, 24);
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.3, 0.1);
    for (let i = 0; i < 6; i++) {
      let side = i % 2 === 0 ? random(70, 250) : random(950, 1130);
      let by = random(120, 920);
      brush.circle(side, by, random(45, 105), 0.2);
    }
  }
  brush.noFill();

  // Atmospheric charcoal grain and subtle diagonal haze lines in background
  brush.set("spray", PAL.bgAmberMid, 1.1);
  for (let i = 0; i < 45; i++) {
    let y = random(40, 1160);
    let x1 = random(20, 300);
    let x2 = random(900, 1180);
    brush.line(x1, y, x1 + random(-60, 60), y + random(-40, 40));
    brush.line(x2, y, x2 + random(-60, 60), y + random(-40, 40));
  }
}

// ============================================================================
// 2. RESTRAINED WATERCOLOUR GLAZES FOR GILT & TARNISH BLOOMS
// ============================================================================

function drawTrophyWatercolourGlazes() {
  brush.noStroke();

  // First, lay down a solid dark-metallic silhouette wash so background doesn't bleed through
  brush.wash(PAL.tarnishUmber, 215);
  brush.beginShape(0.2);
  for (let y = 1185; y >= 155; y -= 22) {
    let p = trophyPoint(y, -90);
    brush.vertex(p.x, p.y);
  }
  for (let y = 155; y <= 1185; y += 22) {
    let p = trophyPoint(y, 90);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
  brush.noWash();

  // Collect glaze patches into color batches for optimal p5.brush fill caching
  let patchesOchre = [];
  let patchesBrass = [];
  let patchesPaleGilt = [];
  let patchesPurple = [];
  let patchesSmokyBrown = [];
  let patchesBlueBlack = [];

  for (let y = 215; y <= 1150; y += 34) {
    let stepTheta = y < 775 ? 14 : 20;
    for (let th = -82; th <= 82; th += stepTheta) {
      let pt = trophyPoint(y, th);
      let ref = evaluateClubhouseReflection(y, th, pt);
      let rad = map(pt.r, 85, 340, 22, 54) * random(0.8, 1.25);

      if (ref.tarnish > 0.56) {
        // Tarnished bloom patch
        let nType = noise(th * 0.08, y * 0.015 + 50);
        if (nType < 0.38) patchesPurple.push({ x: pt.x, y: pt.y, r: rad });
        else if (nType < 0.72) patchesSmokyBrown.push({ x: pt.x, y: pt.y, r: rad });
        else patchesBlueBlack.push({ x: pt.x, y: pt.y, r: rad });
      } else if (ref.tone > 0.48) {
        // Worn high point showing warm gilt (yellow ochre & old brass)
        if (ref.tone > 0.75) patchesPaleGilt.push({ x: pt.x, y: pt.y, r: rad * 0.85 });
        else if ((th + y) % 2 === 0) patchesOchre.push({ x: pt.x, y: pt.y, r: rad });
        else patchesBrass.push({ x: pt.x, y: pt.y, r: rad });
      } else {
        patchesSmokyBrown.push({ x: pt.x, y: pt.y, r: rad * 0.9 });
      }
    }
  }

  // Render batched watercolour glazes
  const renderBatch = (list, col, op, bleed) => {
    brush.fill(col, op);
    brush.fillBleed(bleed, "out");
    brush.fillTexture(0.62, 0.28);
    for (let p of list) {
      brush.circle(p.x, p.y, p.r, 0.38);
    }
  };

  renderBatch(patchesSmokyBrown, PAL.tarnishBrown, 75, 0.35);
  renderBatch(patchesBrass, PAL.giltBrass, 82, 0.28);
  renderBatch(patchesOchre, PAL.giltOchre, 88, 0.30);
  renderBatch(patchesPurple, PAL.tarnishPurple, 85, 0.38);
  renderBatch(patchesBlueBlack, PAL.graphiteBlue, 92, 0.32);
  renderBatch(patchesPaleGilt, PAL.giltPale, 75, 0.22);

  // Concentrated bruised-purple & blue-black watercolour bloom inside the main dent & scroll bands
  brush.fill(PAL.tarnishPlum, 95);
  brush.fillBleed(0.42, "out");
  for (let i = 0; i < 8; i++) {
    let pt = trophyPoint(478 + random(-55, 55), 25 + random(-14, 14));
    brush.circle(pt.x, pt.y, random(28, 52), 0.4);
  }
  brush.noFill();
}

// ============================================================================
// 3. DISTORTED WOOD-PANELLED CLUBHOUSE REFLECTION ON THE BELLY
// ============================================================================

function drawWoodPanelledReflection() {
  // The clubhouse reflection wraps around the bulbous cup belly (y = 235..760)
  // We trace vertical wooden panel stiles, recessed mahogany grain & horizontal rails
  // directly through the perturbed 3D surface normals (so the dent warps them!)

  for (let y = 240; y <= 755; y += 4.5) {
    for (let th = -86; th <= 86; th += 2.2) {
      let pt = trophyPoint(y, th);
      let ptNext = trophyPoint(y + 5, th + (pt.dr < -5 ? 1.8 : 0.3));
      let ref = evaluateClubhouseReflection(y, th, pt);

      // Determine stroke color and brush from reflection features + tarnish
      let col, brName = "2B", w = 0.48;

      if (ref.isCeilingWindow && ref.tarnish < 0.55) {
        // Distorted warm amber window / ceiling reflection
        col = ref.tone > 0.8 ? PAL.giltHighlight : PAL.giltPale;
        brName = "cpencil";
        w = 0.58;
      } else if (ref.isBevel && ref.tone > 0.6) {
        // Bright old-brass catchlight on vertical wood panel bevel
        col = PAL.giltOchre;
        brName = "HB";
        w = 0.45;
      } else if (ref.isDadoRail || ref.isStile) {
        // Dark mahogany rail or vertical stile warped around the curve
        col = ref.tarnish > 0.5 ? PAL.graphiteDark : PAL.woodDark;
        brName = "charcoal";
        w = 0.52;
      } else {
        // Recessed wood panel grain blended with tarnish bloom
        if (ref.tarnish > 0.65) {
          col = (th + floor(y)) % 3 === 0 ? PAL.tarnishPurple : PAL.graphiteBlue;
          brName = "charcoal";
          w = 0.50;
        } else if (ref.tarnish > 0.42) {
          col = PAL.tarnishBrown;
          brName = "2B";
          w = 0.45;
        } else {
          col = ref.tone > 0.4 ? PAL.giltBrass : PAL.woodMid;
          brName = "2B";
          w = 0.42;
        }
      }

      brush.set(brName, col, w);
      brush.line(pt.x, pt.y, ptNext.x, ptNext.y);
    }
  }

  // Draw continuous warped horizontal wainscot rails & coffered ceiling beams wrapping the belly
  const railHeights = [295, 385, 515, 635, 715];
  for (let ry of railHeights) {
    for (let pass = 0; pass < 3; pass++) {
      let yOff = (pass - 1) * 3.5;
      let pts = [];
      for (let th = -86; th <= 86; th += 4) {
        let p = trophyPoint(ry + yOff, th);
        // Warp rail vertically according to surface normal ny (strong kink inside the dent!)
        let warpY = p.ny * 36;
        pts.push([p.x, p.y + warpY, map(abs(th), 0, 90, 1.1, 0.5)]);
      }
      brush.set(
        pass === 1 ? "charcoal" : "HB",
        pass === 1 ? PAL.woodDark : PAL.giltOchre,
        pass === 1 ? 0.65 : 0.38
      );
      brush.spline(pts, 0.4);
    }
  }
}

// ============================================================================
// 4. DENSE CHARCOAL & GRAPHITE TONAL STRUCTURE (BASE, STEM, RIM, LID & DENT)
// ============================================================================

function drawMonumentalTonalStructure() {
  // A. Cross-contour elliptical rings from bottom plinth (y=1185) to lid (y=150)
  // Because we look from below, every ring arches strongly UPWARD across the front!
  for (let y = 152; y <= 1185; y += 3.2) {
    // Skip dense belly center on some passes so wood reflection breathes through
    let isBelly = y > 250 && y < 655;
    if (isBelly && floor(y) % 2 === 0) continue;

    let stepTh = isBelly ? 7 : 5;
    for (let th = -88; th < 88; th += stepTh) {
      let p1 = trophyPoint(y, th);
      let p2 = trophyPoint(y, min(88, th + stepTh));
      let ref = evaluateClubhouseReflection(y, th, p1);

      // Select graphite/charcoal/gilt pencil for cross-contour modeling
      let col, br = "2B", w = 0.42;
      let edgeDarkening = abs(th) > 64;

      if (edgeDarkening) {
        // Deep charcoal & blue-black graphite turning the form at the silhouette edges
        col = abs(th) > 78 ? PAL.charcoalDeep : PAL.graphiteDark;
        br = "charcoal";
        w = 0.62;
      } else if (ref.tone > 0.72 && ref.tarnish < 0.5) {
        col = ref.tone > 0.85 ? PAL.giltHighlight : PAL.giltPale;
        br = "cpencil";
        w = 0.46;
      } else if (ref.tone > 0.46 && ref.tarnish < 0.55) {
        col = PAL.giltOchre;
        br = "HB";
        w = 0.38;
      } else if (ref.tarnish > 0.62) {
        col = (floor(y) + th) % 2 === 0 ? PAL.tarnishPurple : PAL.graphiteBlue;
        br = "2B";
        w = 0.45;
      } else {
        col = PAL.tarnishBrown;
        br = "2B";
        w = 0.40;
      }

      brush.set(br, col, w);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // B. UNDERSIDE OF OVERHANGING MOULDINGS (Worm's-eye perspective anchor!)
  // Looking up from below, we see the dark, dramatic undersides of:
  // 1) Top rolled lip (y=220), 2) Lower cup overhang (y=755), 3) Knop underside (y=925), 4) Foot ledges (y=1080, 1140)
  const overhangs = [
    { y: 222, depth: 18, weight: 0.85 },
    { y: 695, depth: 14, weight: 0.65 },
    { y: 772, depth: 12, weight: 0.70 },
    { y: 922, depth: 15, weight: 0.75 },
    { y: 1078, depth: 16, weight: 0.80 },
    { y: 1138, depth: 20, weight: 0.90 }
  ];

  for (let ov of overhangs) {
    for (let d = 0; d <= ov.depth; d += 2.5) {
      let pts = [];
      for (let th = -88; th <= 88; th += 5) {
        let p = trophyPoint(ov.y + d, th);
        pts.push([p.x, p.y, map(abs(th), 0, 90, 1.3, 0.6)]);
      }
      let isHighlightEdge = d === 0 || d >= ov.depth - 2.5;
      brush.set(
        isHighlightEdge ? "cpencil" : "charcoal",
        isHighlightEdge ? (d === 0 ? PAL.giltPale : PAL.giltOldBrass) : PAL.charcoalDeep,
        isHighlightEdge ? 0.52 : ov.weight
      );
      brush.spline(pts, 0.35);
    }
  }

  // C. GADROONED CALYX FLUTES (y = 655..775) & STEM KNOP RIBS (y = 850..950)
  for (let th = -82; th <= 82; th += 11.25) {
    // Calyx ribs seen from below
    let ribShadow = [];
    let ribGilt = [];
    for (let y = 655; y <= 772; y += 8) {
      let pS = trophyPoint(y, th - 2.5);
      let pG = trophyPoint(y, th + 2.0);
      ribShadow.push([pS.x, pS.y, 1.0]);
      ribGilt.push([pG.x, pG.y, 0.9]);
    }
    brush.set("charcoal", PAL.graphiteDark, 0.58);
    brush.spline(ribShadow, 0.4);
    brush.set("cpencil", PAL.giltOchre, 0.48);
    brush.spline(ribGilt, 0.4);

    // Knop ribs
    let knopShadow = [];
    let knopGilt = [];
    for (let y = 852; y <= 948; y += 8) {
      let pS = trophyPoint(y, th - 2.2);
      let pG = trophyPoint(y, th + 2.0);
      knopShadow.push([pS.x, pS.y, 0.9]);
      knopGilt.push([pG.x, pG.y, 0.85]);
    }
    brush.set("2B", PAL.charcoalDeep, 0.50);
    brush.spline(knopShadow, 0.4);
    brush.set("HB", PAL.giltPale, 0.42);
    brush.spline(knopGilt, 0.4);
  }

  // D. HYPERREAL RENDERING OF THE MAIN DENT (y ~ 478, theta ~ +25 deg)
  drawDeepDentDetail();
}

function drawDeepDentDetail() {
  // Concentric contour & stress-buckle hatching around and inside the main dent
  for (let ring = 0.12; ring <= 1.32; ring += 0.055) {
    let pts = [];
    for (let a = 0; a <= 360; a += 10) {
      let dx = cos(a) * 98 * ring;
      let dy = sin(a) * 82 * ring;
      // Inverse rotate by +16 deg
      let u = dx * 0.961 + dy * 0.276;
      let v = -dx * 0.276 + dy * 0.961;
      let th = 25 + u / 4.4;
      let y = 478 + v;
      if (th > -85 && th < 85) {
        let p = trophyPoint(y, th);
        pts.push([p.x, p.y, 0.8 + 0.4 * sin(a * 2)]);
      }
    }
    if (pts.length > 3) {
      let isBuckleRidge = ring > 0.86 && ring < 1.12;
      let isDeepHollow = ring < 0.58;
      let col = isBuckleRidge
        ? PAL.giltHighlight
        : isDeepHollow
        ? PAL.graphiteDark
        : PAL.tarnishPurple;
      let br = isBuckleRidge ? "cpencil" : isDeepHollow ? "charcoal" : "2B";
      brush.set(br, col, isBuckleRidge ? 0.50 : 0.44);
      brush.spline(pts, 0.45);
    }
  }

  // Sharp diagonal impact crease across the center of the dent
  for (let off = -16; off <= 16; off += 2.2) {
    let creasePts = [];
    for (let s = -78; s <= 78; s += 8) {
      let th = 25 + s / 4.6;
      let y = 478 + s * 0.32 + off + 6 * sin(s * 2.5);
      let p = trophyPoint(y, th);
      creasePts.push([p.x, p.y, 1.0 - abs(s) / 95]);
    }
    let col = off < -5
      ? PAL.giltPale // Upper buckled lip catching light from below
      : off < 4
      ? PAL.charcoalDeep // Deep pinched fold shadow
      : PAL.tarnishPlum; // Bruised purple tarnish gathered in the fold
    brush.set(off < -5 ? "cpencil" : "charcoal", col, 0.48);
    brush.spline(creasePts, 0.4);
  }
}

// ============================================================================
// 5. ENGRAVED BAROQUE SCROLLS & TARNISHED CARTOUCHE
// ============================================================================

function drawEngravedScrollsAndCartouche() {
  // Helper to draw a 3D-mapped engraved scroll spiral on the trophy surface
  // Gathering bruised purple, smoky brown & blue-black graphite in the grooves
  // and warm gilt yellow-ochre / old brass on the worn raised edges!
  const drawScrollSpiral = (yCenter, thCenter, scaleX, scaleY, dirX, dirY, turns = 2.3) => {
    let shadowPts = [];
    let tarnishPts = [];
    let giltPts = [];

    let maxAngle = turns * 360;
    for (let a = 0; a <= maxAngle; a += 12) {
      let frac = 1 - a / (maxAngle * 1.12);
      let radX = scaleX * pow(frac, 0.82);
      let radY = scaleY * pow(frac, 0.82);

      let th = thCenter + dirX * radX * cos(a);
      let y = yCenter + dirY * radY * sin(a);
      if (abs(th) > 85) continue;

      let pShadow = trophyPoint(y - 1.5, th - 0.4, -1.5);
      let pTarnish = trophyPoint(y + 1.0, th + 0.3, -1.0);
      let pGilt = trophyPoint(y + 2.8, th + 0.6, 1.5); // Lower bezel catches light from below!

      let pr = 0.45 + 0.75 * frac;
      shadowPts.push([pShadow.x, pShadow.y, pr]);
      tarnishPts.push([pTarnish.x, pTarnish.y, pr * 1.1]);
      giltPts.push([pGilt.x, pGilt.y, pr * 0.95]);
    }

    if (shadowPts.length > 3) {
      // 1. Bruised purple / smoky brown tarnish bloom gathered inside the scroll channel
      brush.set("stump", (thCenter + yCenter) % 2 === 0 ? PAL.tarnishPurple : PAL.tarnishBrown, 0.65);
      brush.spline(tarnishPts, 0.5);

      // 2. Deep incised blue-black graphite engraving cut
      brush.set("micro_graphite", PAL.graphiteDark, 1.15);
      brush.spline(shadowPts, 0.5);
      brush.set("2B", PAL.graphiteBlue, 0.45);
      brush.spline(tarnishPts, 0.5);

      // 3. Worn high point bezel gleaming in warm gilt yellow ochre & old brass
      brush.set("cpencil", PAL.giltOchre, 0.46);
      brush.spline(giltPts, 0.5);
      brush.set("micro_graphite", PAL.giltHighlight, 0.85);
      brush.spline(giltPts.slice(0, floor(giltPts.length * 0.65)), 0.5);
    }

    // Add acanthus leaf frills radiating off the outer curve of the scroll
    for (let leafA = 35; leafA <= 220; leafA += 45) {
      let leafPts = [];
      let leafGilt = [];
      for (let t = 0; t <= 1; t += 0.2) {
        let a = leafA + t * 55;
        let rMult = 1.0 + t * 0.42;
        let th = thCenter + dirX * scaleX * rMult * cos(a);
        let y = yCenter + dirY * scaleY * rMult * sin(a) - sin(t * 180) * 8;
        if (abs(th) <= 85) {
          let p1 = trophyPoint(y, th);
          let p2 = trophyPoint(y + 2.2, th + 0.4);
          leafPts.push([p1.x, p1.y, 1 - t * 0.6]);
          leafGilt.push([p2.x, p2.y, 1 - t * 0.6]);
        }
      }
      if (leafPts.length > 2) {
        brush.set("2B", PAL.tarnishPlum, 0.44);
        brush.spline(leafPts, 0.4);
        brush.set("micro_graphite", PAL.charcoalDeep, 0.95);
        brush.spline(leafPts, 0.4);
        brush.set("HB", PAL.giltPale, 0.36);
        brush.spline(leafGilt, 0.4);
      }
    }
  };

  // UPPER BELLY SCROLL FRIEZE & CENTRAL SHIELD CARTOUCHE (y = 335..465)
  const upperScrolls = [
    // Flanking the central cartouche (around theta = -6 deg)
    { y: 385, th: -24, sx: 11, sy: 34, dx: -1, dy: 1, turns: 2.4 },
    { y: 425, th: -42, sx: 13, sy: 38, dx: 1, dy: -1, turns: 2.5 },
    { y: 390, th: -62, sx: 11, sy: 32, dx: -1, dy: 1, turns: 2.2 },
    { y: 385, th: 12, sx: 11, sy: 34, dx: 1, dy: 1, turns: 2.4 },
    { y: 425, th: 31, sx: 13, sy: 38, dx: -1, dy: -1, turns: 2.5 }, // Warped right into the dent!
    { y: 390, th: 52, sx: 11, sy: 32, dx: 1, dy: 1, turns: 2.2 },
    { y: 430, th: 70, sx: 9, sy: 28, dx: -1, dy: -1, turns: 2.0 }
  ];
  for (let s of upperScrolls) {
    drawScrollSpiral(s.y, s.th, s.sx, s.sy, s.dx, s.dy, s.turns);
  }

  // LOWER BELLY ACANTHUS SCROLL REGISTER (y = 585..685)
  const lowerScrolls = [
    { y: 625, th: -66, sx: 10, sy: 30, dx: 1, dy: 1, turns: 2.1 },
    { y: 635, th: -44, sx: 12, sy: 35, dx: -1, dy: -1, turns: 2.4 },
    { y: 620, th: -20, sx: 13, sy: 36, dx: 1, dy: 1, turns: 2.5 },
    { y: 630, th: 4, sx: 13, sy: 36, dx: -1, dy: 1, turns: 2.5 },
    { y: 620, th: 28, sx: 12, sy: 35, dx: 1, dy: -1, turns: 2.4 },
    { y: 635, th: 50, sx: 11, sy: 32, dx: -1, dy: 1, turns: 2.2 },
    { y: 625, th: 70, sx: 9, sy: 28, dx: 1, dy: -1, turns: 2.0 }
  ];
  for (let s of lowerScrolls) {
    drawScrollSpiral(s.y, s.th, s.sx, s.sy, s.dx, s.dy, s.turns);
  }

  // CENTRAL ENGRAVED BOWLING CARTOUCHE SHIELD (y = 335..455, theta = -6 deg)
  let cTh = -6, cY = 395;
  for (let ring = 0.85; ring <= 1.12; ring += 0.09) {
    let shieldPts = [];
    for (let a = 0; a <= 360; a += 10) {
      // Baroque shield contour with pinched waist
      let pinch = 1 + 0.18 * cos(a * 2) - 0.1 * sin(a * 3);
      let th = cTh + 13 * ring * pinch * cos(a);
      let y = cY + 46 * ring * pinch * sin(a);
      let p = trophyPoint(y, th);
      shieldPts.push([p.x, p.y, 0.9]);
    }
    let isGilt = ring > 0.98;
    brush.set(
      isGilt ? "cpencil" : "micro_graphite",
      isGilt ? PAL.giltPale : PAL.graphiteDark,
      isGilt ? 0.48 : 1.15
    );
    brush.spline(shieldPts, 0.45);
  }

  // Crossed ten-pins & subtle engraved lettering lines inside the shield cartouche
  for (let row = -22; row <= 22; row += 7) {
    let linePts = [];
    let span = 8 * cos((row / 28) * 70);
    for (let th = cTh - span; th <= cTh + span; th += 1.5) {
      let y = cY + row + 1.8 * sin(th * 45);
      let p = trophyPoint(y, th);
      linePts.push([p.x, p.y, 0.8]);
    }
    brush.set("micro_graphite", row % 14 === 0 ? PAL.giltHighlight : PAL.graphiteBlue, 0.9);
    brush.spline(linePts, 0.3);
  }
}

// ============================================================================
// 6A. ORNATE CAST-GILT ACANTHUS SCROLL HANDLES (LEFT & RIGHT FLANKS)
// ============================================================================

function drawOrnateScrollHandles() {
  // Draw both left (side = -1) and right (side = +1) grand S-scroll handles
  for (let side of [-1, 1]) {
    let thAttachTop = side * 86;
    let thAttachBot = side * 84;
    let pTop = trophyPoint(272, thAttachTop);
    let pMidCup = trophyPoint(460, side * 88);
    let pBot = trophyPoint(685, thAttachBot);

    // Build centerline spine of the double-volute handle
    let spine = [];
    const numSteps = 65;
    for (let i = 0; i <= numSteps; i++) {
      let t = i / numSteps; // 0 at top attachment, 1 at bottom attachment
      let baseY = lerp(pTop.y, pBot.y, t);
      let baseX = lerp(pTop.x, pBot.x, t);

      // Dramatic outward baroque S-curve
      let archOut = 0;
      let yCurl = 0;
      if (t < 0.22) {
        // Upper volute rising above the attachment before sweeping outward
        let u = t / 0.22;
        archOut = 148 * sin(u * 115);
        yCurl = -52 * sin(u * 180);
      } else if (t < 0.72) {
        // Long sweeping outer ear tapering inward
        let u = (t - 0.22) / 0.50;
        archOut = 134 * cos(u * 65) + 28 * sin(u * 180);
        yCurl = 12 * sin(u * 180);
      } else {
        // Lower snail-scroll volute curling back into the lower calyx
        let u = (t - 0.72) / 0.28;
        archOut = 72 * sin((1 - u) * 140) + 24 * sin(u * 360);
        yCurl = 22 * cos(u * 270);
      }

      let thick = 21 * (0.55 + 0.65 * sin(t * 180) + 0.22 * sin(t * 540));
      spine.push({
        x: baseX + side * archOut,
        y: baseY + yCurl,
        r: thick,
        t: t
      });
    }

    // Watercolour underglaze along the handle
    brush.noStroke();
    brush.fill(PAL.tarnishBrown, 120);
    brush.fillBleed(0.2, "in");
    for (let i = 0; i < spine.length; i += 3) {
      brush.circle(spine[i].x, spine[i].y, spine[i].r * 1.1, 0.25);
    }
    brush.noFill();

    // Render 3D tube cross-contours & longitudinal flutes along the handle
    for (let i = 0; i < spine.length - 1; i++) {
      let s1 = spine[i];
      let s2 = spine[i + 1];
      let dx = s2.x - s1.x;
      let dy = s2.y - s1.y;
      let len = sqrt(dx * dx + dy * dy) || 1;
      // Normal perpendicular to handle spine
      let nx = -dy / len;
      let ny = dx / len;

      // Cross-contour bands across handle thickness
      for (let f = -1.0; f <= 1.0; f += 0.22) {
        let px1 = s1.x + nx * s1.r * f;
        let py1 = s1.y + ny * s1.r * f;
        let px2 = s2.x + nx * s2.r * f;
        let py2 = s2.y + ny * s2.r * f;

        // Seen from below: bottom-facing surfaces & outer ridges catch warm gilt; crevices hold tarnish
        let lightVal = f * side * 0.55 + (ny > 0 ? 0.35 : -0.25);
        let col, br = "2B", w = 0.45;
        if (abs(f) > 0.82) {
          col = PAL.charcoalDeep;
          br = "charcoal";
          w = 0.58;
        } else if (lightVal > 0.35) {
          col = lightVal > 0.55 ? PAL.giltHighlight : PAL.giltOchre;
          br = "cpencil";
          w = 0.50;
        } else if (lightVal > 0.0) {
          col = PAL.giltOldBrass;
          br = "HB";
          w = 0.42;
        } else {
          col = (i % 2 === 0) ? PAL.tarnishPurple : PAL.graphiteDark;
          br = "charcoal";
          w = 0.52;
        }
        brush.set(br, col, w);
        brush.line(px1, py1, px2, py2);
      }
    }

    // Acanthus leaf crestings on the top volute and mid-handle clasp
    const crestIndices = [8, 14, 28, 48, 56];
    for (let idx of crestIndices) {
      let sp = spine[idx];
      for (let k = -3; k <= 3; k++) {
        let leafPts = [];
        for (let m = 0; m <= 5; m++) {
          let ang = (side > 0 ? -35 : 215) + k * 14 + m * side * 12;
          let rad = m * 8.5;
          leafPts.push([sp.x + cos(ang) * rad, sp.y + sin(ang) * rad, 1.1 - m * 0.16]);
        }
        brush.set(abs(k) <= 1 ? "cpencil" : "charcoal", abs(k) <= 1 ? PAL.giltPale : PAL.graphiteDark, 0.48);
        brush.spline(leafPts, 0.45);
      }
    }
  }
}

// ============================================================================
// 6B. FORESHORTENED BOWLER FIGURE AT THE SUMMIT (SEEN FROM BELOW)
// ============================================================================

function drawForeshortenedBowlerFigure() {
  // Situated atop the domed lid pedestal around (x ~ 586, y = 152 up to y = 26)
  // Classic dynamic bowling follow-through pose seen dramatically from underneath!
  let basePt = trophyPoint(150, 0);
  let bx = basePt.x;
  let by = basePt.y + 6;

  // Helper to draw a foreshortened 3D metallic limb segment between two points with radii
  const drawMetallicLimb = (x1, y1, r1, x2, y2, r2, steps = 16) => {
    let dx = x2 - x1, dy = y2 - y1;
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len, ny = dx / len;

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let cx = lerp(x1, x2, t);
      let cy = lerp(y1, y2, t);
      let r = lerp(r1, r2, t) * (1 + 0.15 * sin(t * 180));

      for (let f = -1.0; f <= 1.0; f += 0.25) {
        let px1 = cx + nx * r * f;
        let py1 = cy + ny * r * f;
        let px2 = cx + dx / steps + nx * r * f;
        let py2 = cy + dy / steps + ny * r * f;

        // Rim light from amber background & gilt underside reflection
        let isGilt = f < -0.25 || f > 0.65;
        let col = isGilt ? (abs(f) > 0.72 ? PAL.giltHighlight : PAL.giltOchre) : PAL.charcoalDeep;
        brush.set(isGilt ? "cpencil" : "charcoal", col, isGilt ? 0.45 : 0.58);
        brush.line(px1, py1, px2, py2);
      }
    }
  };

  // 1. Foreshortened striding legs rising from pedestal cap
  drawMetallicLimb(bx - 16, by, 13, bx - 8, by - 54, 16, 14); // Planted front left leg
  drawMetallicLimb(bx + 20, by - 8, 10, bx + 54, by - 38, 12, 12); // Trailing kicked-back right leg

  // 2. Torso leaning dynamically forward-left (seen from underneath)
  let hipX = bx - 2, hipY = by - 54;
  let shldrX = bx - 14, shldrY = by - 96;
  drawMetallicLimb(hipX, hipY, 22, shldrX, shldrY, 26, 16);

  // 3. Sweeping right arm extending forward-left holding/delivering the BOWLING BALL
  let elbowX = shldrX - 38, elbowY = shldrY + 8;
  let handX = shldrX - 78, handY = shldrY - 12;
  drawMetallicLimb(shldrX - 12, shldrY + 4, 11, elbowX, elbowY, 9, 10);
  drawMetallicLimb(elbowX, elbowY, 9, handX, handY, 8, 10);

  // THE BOWLING BALL (prominent sphere seen from below in the bowler's hand!)
  let ballX = handX - 14, ballY = handY - 8, ballR = 23;
  brush.noStroke();
  brush.wash(PAL.graphiteDark, 235);
  brush.circle(ballX, ballY, ballR, 0.15);
  brush.noWash();

  for (let a = 0; a < 360; a += 14) {
    for (let rad = 4; rad <= ballR; rad += 3.5) {
      let px = ballX + cos(a) * rad;
      let py = ballY + sin(a) * rad;
      let isUnderGilt = sin(a) > 0.25; // Underside of bowling ball catches warm gilt glow!
      let isRim = rad > ballR - 4 && cos(a) < -0.2;
      let col = isRim ? PAL.giltHighlight : isUnderGilt ? PAL.giltOchre : PAL.charcoalDeep;
      brush.set(isUnderGilt || isRim ? "cpencil" : "2B", col, 0.45);
      brush.line(px, py, px - sin(a) * 4, py + cos(a) * 4);
    }
  }

  // 4. Counter-balance left arm sweeping backward-right
  drawMetallicLimb(shldrX + 16, shldrY + 2, 10, shldrX + 68, shldrY + 18, 7, 14);

  // 5. Foreshortened head & chin seen from below at the very apex (y ~ 36)
  let headX = shldrX - 4, headY = shldrY - 22;
  drawMetallicLimb(shldrX, shldrY - 4, 11, headX, headY, 13, 8);
  brush.set("cpencil", PAL.giltHighlight, 0.52);
  brush.arc(headX, headY, 13, 180, 360);
}

// ============================================================================
// 7. SMUDGED ADULT FINGERPRINTS CLOUDING THE BELLY — EVERY WHORL RENDERED
// ============================================================================

function drawSmudgedFingerprints() {
  // 5 life-sized adult fingerprint smudges across the monumental cup belly
  // where hands have gripped the trophy:
  // 4 fingers on the left-center belly + 1 large thumbprint right next to the dent!
  const prints = [
    { y: 445, th: -34, rx: 36, ry: 52, rot: 14, type: "whorl", swirl: 1.0 },
    { y: 495, th: -15, rx: 38, ry: 56, rot: 8, type: "twin_loop", swirl: -1.0 },
    { y: 558, th: -31, rx: 34, ry: 49, rot: 18, type: "whorl", swirl: 0.8 },
    { y: 615, th: -46, rx: 30, ry: 43, rot: 24, type: "loop", swirl: 1.1 },
    // Prominent adult thumbprint right on the center-right belly beside the dent!
    { y: 512, th: 8, rx: 44, ry: 62, rot: -16, type: "whorl", swirl: -1.15 }
  ];

  for (let fp of prints) {
    let centerPt = trophyPoint(fp.y, fp.th);

    // 1. Oily sebaceous smudge clouding the specular reflection underneath
    brush.noStroke();
    brush.fill(PAL.giltOldBrass, 36);
    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.45, 0.15);
    brush.circle(centerPt.x, centerPt.y, (fp.rx + fp.ry) * 0.52, 0.3);
    brush.noFill();

    // Soft directional smear strokes with the dry stump brush
    brush.set("stump", PAL.graphiteSlate, 0.42);
    for (let s = -0.7; s <= 0.7; s += 0.28) {
      let p1 = trophyPoint(fp.y - fp.ry * 0.65, fp.th + s * 6);
      let p2 = trophyPoint(fp.y + fp.ry * 0.75, fp.th + s * 6 + 2.5);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }

    // Helper to project local normalized fingerprint coordinates (u in -1..1, v in -1.25..1.25)
    // onto the 3D curved surface of the trophy cup
    const mapFP = (u, v) => {
      // Rotate by finger angle
      let ca = cos(fp.rot), sa = sin(fp.rot);
      let dx = (u * fp.rx) * ca - (v * fp.ry) * sa;
      let dy = (u * fp.rx) * sa + (v * fp.ry) * ca;
      let th = fp.th + dx / 5.2;
      let y = fp.y + dy;
      return trophyPoint(y, th);
    };

    // 2. Render EVERY INDIVIDUAL FRICTION RIDGE WHORL (52 nested ridge contours per print!)
    // Includes spiral/concentric cores, twin-loop S-twist, triradius deltas, and bifurcations
    const totalRidges = 46;
    for (let k = 1; k <= totalRidges; k++) {
      let rNorm = k / totalRidges; // 0.02 (inner core) to 1.0 (outer pad margin)

      // Determine how many angular segments to break the ridge into (simulating pores & smudges)
      let aStart = rNorm < 0.62 ? 0 : -155;
      let aEnd = rNorm < 0.62 ? 360 : 155;

      let segPts = [];
      for (let a = aStart; a <= aEnd; a += 8) {
        // Parametric dermatoglyphic whorl deformation:
        // Core spirals tightly; middle mantle pinches outward toward two lower deltas at a = +-125 deg
        let spiralTwist = (1 - rNorm) * 65 * fp.swirl;
        let ang = a + spiralTwist;

        let u = rNorm * sin(ang);
        let v = -rNorm * cos(ang) * 1.08 - (1 - rNorm) * 0.12;

        // Twin-loop S-inflection near the core
        if (fp.type === "twin_loop" && rNorm < 0.55) {
          u += 0.14 * (1 - rNorm / 0.55) * sin(v * 320);
        }

        // Delta flare at lower-left and lower-right of the whorl (v > 0.25)
        if (v > 0.15 && rNorm > 0.42) {
          let deltaPull = pow((v - 0.15) * (rNorm - 0.42), 0.85) * 0.42;
          u += (u > 0 ? 1 : -1) * deltaPull;
        }

        // Subtle organic micro-wobble along ridge
        let micro = (noise(k * 0.3, a * 0.04, fp.y) - 0.5) * 0.025;
        u += micro;
        v += micro;

        // Clip strictly to the oval pad footprint
        if (u * u + (v * v) / 1.35 <= 1.05) {
          let pt = mapFP(u, v);
          let pressure = 0.65 + 0.45 * sin(a * 3 + k * 25);
          segPts.push([pt.x, pt.y, pressure]);

          // Occasional realistic pore break / smudge gap along the ridge
          let poreGap = noise(k * 1.7, a * 0.15) > 0.76;
          if ((poreGap || a === aEnd) && segPts.length >= 3) {
            // Alternate between oily pale gilt/silver ridge catchlights and fine graphite grooves
            let isBrightRidge = k % 2 === 0;
            let col = isBrightRidge
              ? (pt.dr < -4 ? PAL.graphiteSilver : PAL.giltPale)
              : PAL.graphiteDark;
            brush.set("micro_graphite", col, isBrightRidge ? 0.92 : 0.78);
            brush.spline(segPts, 0.35);
            segPts = [];
          }
        } else if (segPts.length >= 3) {
          brush.set("micro_graphite", k % 2 === 0 ? PAL.giltPale : PAL.graphiteDark, 0.82);
          brush.spline(segPts, 0.35);
          segPts = [];
        } else {
          segPts = [];
        }
      }

      // Draw ridge bifurcations (Y-splits where one friction ridge divides into two)
      if (k > 8 && k < 34 && k % 4 === 0) {
        let bifAngle = (k * 67) % 240 - 120;
        let bPts = [];
        for (let b = 0; b <= 1; b += 0.25) {
          let rB = rNorm + b * (1.2 / totalRidges);
          let aB = bifAngle + b * 24;
          let uB = rB * sin(aB);
          let vB = -rB * cos(aB) * 1.08 - (1 - rB) * 0.12;
          let ptB = mapFP(uB, vB);
          bPts.push([ptB.x, ptB.y, 0.85]);
        }
        brush.set("micro_graphite", PAL.giltHighlight, 0.85);
        brush.spline(bPts, 0.3);
      }
    }

    // 3. Transverse basal ridges below the two deltas (v = 0.68..1.18) & phalanx joint crease
    for (let bRow = 0.68; bRow <= 1.16; bRow += 0.038) {
      let isJointCrease = abs(bRow - 0.94) < 0.025;
      if (isJointCrease) continue; // Leave a clean realistic gap at the finger joint crease!

      let basePts = [];
      let maxU = sqrt(max(0, 1.02 - (bRow * bRow) / 1.38));
      for (let u = -maxU; u <= maxU; u += 0.12) {
        // Arch gently upward in center to meet the lower whorl core
        let archV = bRow - 0.11 * exp(-u * u * 5.0) * (1.2 - bRow);
        let pt = mapFP(u, archV);
        basePts.push([pt.x, pt.y, 0.8 * (1 - abs(u) / (maxU + 0.1))]);
      }
      if (basePts.length >= 3) {
        let isLight = floor(bRow * 30) % 2 === 0;
        brush.set(
          "micro_graphite",
          isLight ? PAL.giltPale : PAL.graphiteBlue,
          isLight ? 0.88 : 0.75
        );
        brush.spline(basePts, 0.35);
      }
    }
  }
}

