function drawFinalSurfacePolish() {
  // 1. Circular lathe-spinning & wiping micro-scratches catching the raking gilt light
  for (let i = 0; i < 95; i++) {
    let y = random(230, 1060);
    let thStart = random(-72, 48);
    let thSpan = random(10, 28);
    let scratchPts = [];
    for (let s = 0; s <= 1; s += 0.2) {
      let th = thStart + s * thSpan;
      let yCurve = y + sin(s * 180) * random(-4, 4);
      let p = trophyPoint(yCurve, th);
      scratchPts.push([p.x, p.y, sin(s * 180) * 0.95]);
    }
    let isBright = i % 3 !== 0;
    brush.set(
      "micro_graphite",
      isBright ? PAL.giltHighlight : PAL.graphiteDark,
      isBright ? 0.72 : 0.65
    );
    brush.spline(scratchPts, 0.3);
  }

  // 2. Intense specular glints on the highest worn gilt points:
  //    - Upper lip rim (y = 218)
  //    - Left-front belly specular lobe (theta ~ -18 deg)
  //    - Upper-left ridge of the deep dent
  //    - Gadrooned calyx bosses & knop highlights
  const specularArcs = [
    { y: 217, th1: -48, th2: -8, w: 0.72 },
    { y: 221, th1: 10, th2: 42, w: 0.62 },
    { y: 315, th1: -28, th2: -10, w: 0.55 },
    { y: 425, th1: 11, th2: 29, w: 0.75 }, // Dent upper buckle highlight
    { y: 678, th1: -36, th2: -12, w: 0.60 },
    { y: 895, th1: -32, th2: 8, w: 0.62 },
    { y: 1074, th1: -42, th2: 18, w: 0.65 },
    { y: 1134, th1: -46, th2: 22, w: 0.68 }
  ];

  for (let sp of specularArcs) {
    let pts = [];
    for (let th = sp.th1; th <= sp.th2; th += 2.5) {
      let p = trophyPoint(sp.y, th);
      let env = sin(map(th, sp.th1, sp.th2, 0, 180));
      pts.push([p.x, p.y, 0.5 + 0.85 * env]);
    }
    brush.set("cpencil", PAL.giltHighlight, sp.w);
    brush.spline(pts, 0.4);
  }

  // 3. Subtle graphite & sulfide tarnish pitting / stipple across tarnished zones
  brush.set("spray", PAL.charcoalDeep, 0.55);
  for (let i = 0; i < 55; i++) {
    let y = random(240, 1120);
    let th = random(-80, 80);
    let p = trophyPoint(y, th);
    let ref = evaluateClubhouseReflection(y, th, p);
    if (ref.tarnish > 0.52) {
      brush.line(p.x, p.y, p.x + random(-14, 14), p.y + random(-10, 10));
    }
  }
}

