// =============================================================================
// CORE DRAWING HELPERS (ALL USING p5.brush)
// =============================================================================

function drawPoly(pts, opts = {}) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  if (opts.wash) {
    brush.wash(opts.wash, opts.washAlpha ?? 255);
  }
  if (opts.fill) {
    brush.fill(opts.fill, opts.fillAlpha ?? 130);
    brush.fillBleed(opts.bleed ?? 0.06, opts.bleedDir ?? "out");
    brush.fillTexture(opts.tex ?? 0.5, opts.border ?? 0.35);
  }
  if (opts.hatch) {
    brush.hatchStyle(
      opts.hatchBrush ?? "2H",
      opts.hatchColor ?? PAL.ink,
      opts.hatchWeight ?? 0.45
    );
    brush.hatch(
      opts.hatchDist ?? 5,
      opts.hatchAngle ?? 45,
      opts.hatchOpts ?? { rand: 0.03 }
    );
  }
  if (opts.stroke) {
    brush.set(opts.brush ?? "rotring", opts.stroke, opts.weight ?? 0.6);
  } else {
    brush.noStroke();
  }

  brush.beginShape(opts.curvature ?? 0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);

  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noStroke();
}

function strokeLine(x1, y1, x2, y2, brushName, col, weight) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function strokeSpline(pts, curv, brushName, col, weight) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.spline(pts, curv ?? 0.5);
}

function getEllipsePts(cx, cy, rx, ry, rotDeg = 0, steps = 28) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let ex = cos(a) * rx;
    let ey = sin(a) * ry;
    pts.push([cx + ex * c - ey * s, cy + ex * s + ey * c]);
  }
  return pts;
}

function getRoundRectPts(x, y, w, h, r, rotDeg = 0, cx = null, cy = null) {
  let pts = [];
  let rad = min(r, w / 2, h / 2);
  let corners = [
    [x + w - rad, y + rad, -90, 0],
    [x + w - rad, y + h - rad, 0, 90],
    [x + rad, y + h - rad, 90, 180],
    [x + rad, y + rad, 180, 270]
  ];
  let ox = cx ?? x + w / 2;
  let oy = cy ?? y + h / 2;
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let k = 0; k < 4; k++) {
    let [ccx, ccy, a1, a2] = corners[k];
    for (let st = 0; st <= 5; st++) {
      let a = lerp(a1, a2, st / 5);
      let px = ccx + cos(a) * rad;
      let py = ccy + sin(a) * rad;
      if (rotDeg !== 0) {
        let dx = px - ox;
        let dy = py - oy;
        px = ox + dx * c - dy * s;
        py = oy + dx * s + dy * c;
      }
      pts.push([px, py]);
    }
  }
  return pts;
}

// Builds a 3D slab in Chaekgeori tilted reverse perspective (back edge slightly wider than front edge)
function drawRevPerspBox(cfg) {
  let {
    fx, fy, fw, bw, dx, dy, h,
    topCol, frontCol, sideCol,
    topShade, isPageFront, isPageSide,
    strokeCol = PAL.ink, weight = 0.55
  } = cfg;

  // Front top edge: (fx, fy) to (fx + fw, fy)
  // Back top edge: shifted by (dx, dy) with width bw (reverse perspective: bw > fw)
  let bLeftX = fx + dx - (bw - fw) * 0.45;
  let bRightX = bLeftX + bw;
  let bY = fy + dy;

  let pFL = [fx, fy];
  let pFR = [fx + fw, fy];
  let pBR = [bRightX, bY];
  let pBL = [bLeftX, bY];

  let pFLb = [fx, fy + h];
  let pFRb = [fx + fw, fy + h];
  let pBRb = [bRightX, bY + h];
  let pBLb = [bLeftX, bY + h];

  // Side face (left or right depending on dx)
  if (dx >= 0) {
    let sidePts = [pFR, pBR, pBRb, pFRb];
    drawPoly(sidePts, {
      wash: sideCol,
      washAlpha: 250,
      hatch: isPageSide,
      hatchBrush: "2H",
      hatchColor: "#8c7a64",
      hatchDist: 2.5,
      hatchAngle: atan2(bY - fy, bRightX - (fx + fw)),
      stroke: strokeCol,
      weight: weight
    });
  } else {
    let sidePts = [pBL, pFL, pFLb, pBLb];
    drawPoly(sidePts, {
      wash: sideCol,
      washAlpha: 250,
      hatch: isPageSide,
      hatchBrush: "2H",
      hatchColor: "#8c7a64",
      hatchDist: 2.5,
      hatchAngle: atan2(fy - bY, fx - bLeftX),
      stroke: strokeCol,
      weight: weight
    });
  }

  // Front face
  let frontPts = [pFL, pFR, pFRb, pFLb];
  drawPoly(frontPts, {
    wash: frontCol,
    washAlpha: 255,
    hatch: isPageFront,
    hatchBrush: "2H",
    hatchColor: "#9c8a72",
    hatchDist: 2.4,
    hatchAngle: 0,
    stroke: strokeCol,
    weight: weight
  });

  // Top face
  let topPts = [pBL, pBR, pFR, pFL];
  drawPoly(topPts, {
    wash: topCol,
    washAlpha: 255,
    hatch: !!topShade,
    hatchBrush: "cpencil",
    hatchColor: topShade || PAL.ink,
    hatchDist: 4,
    hatchAngle: 20,
    stroke: strokeCol,
    weight: weight
  });

  return { pFL, pFR, pBR, pBL, pFLb, pFRb, pBRb, pBLb };
}

