// =============================================================================
// 2. CHAEKGEORI COMPARTMENT ARCHITECTURE (REVERSE PERSPECTIVE & MINERAL WASH)
// =============================================================================

function drawSingleCompartment(x, y, w, h, cfg) {
  let {
    backCol, floorCol, sideCol, ceilCol,
    tiltDir, floorDepth, sideW, ceilH,
    matGrid, backPanelBorder
  } = cfg;

  // In Chaekgeori tilted reverse perspective:
  // The floor plane rises steeply from y + h up to y + h - floorDepth,
  // and the back edge splays wider or shifts laterally!
  let bx1, bx2, by1, by2;
  if (tiltDir === "right") {
    // Left side wall visible, floor tilts up and right, back wall splays outward on right
    bx1 = x + sideW;
    bx2 = x + w;
    by1 = y + ceilH;
    by2 = y + h - floorDepth;

    // Back wall
    drawPoly([[bx1, by1], [bx2, by1 - 10], [bx2, by2 - 14], [bx1, by2]], {
      wash: backCol,
      washAlpha: 210,
      fill: backCol,
      fillAlpha: 95,
      bleed: 0.05,
      tex: 0.55,
      border: 0.4,
      stroke: PAL.ink,
      weight: 0.55
    });

    if (backPanelBorder) {
      let m = 18;
      drawPoly(
        [
          [bx1 + m, by1 + m],
          [bx2 - m, by1 - 10 + m],
          [bx2 - m, by2 - 14 - m],
          [bx1 + m, by2 - m]
        ],
        {
          stroke: backPanelBorder,
          brush: "pen",
          weight: 0.45
        }
      );
    }

    // Ceiling underside plane
    drawPoly([[x, y], [x + w, y], [bx2, by1 - 10], [bx1, by1]], {
      wash: ceilCol,
      washAlpha: 225,
      fill: ceilCol,
      fillAlpha: 105,
      bleed: 0.04,
      tex: 0.5,
      stroke: PAL.ink,
      weight: 0.55
    });

    // Left inner wall plane (reverse perspective splay)
    drawPoly([[x, y], [bx1, by1], [bx1, by2], [x, y + h]], {
      wash: sideCol,
      washAlpha: 230,
      fill: sideCol,
      fillAlpha: 115,
      bleed: 0.05,
      tex: 0.55,
      stroke: PAL.ink,
      weight: 0.55
    });

    // Tilted Floor plane
    let floorPts = [[x, y + h], [bx1, by2], [bx2, by2 - 14], [x + w, y + h]];
    drawPoly(floorPts, {
      wash: floorCol,
      washAlpha: 235,
      fill: floorCol,
      fillAlpha: 120,
      bleed: 0.05,
      tex: 0.6,
      hatch: !!matGrid,
      hatchBrush: "pen",
      hatchColor: PAL.inkSoft,
      hatchWeight: 0.3,
      hatchDist: 14,
      hatchAngle: -6,
      stroke: PAL.ink,
      weight: 0.65
    });

    // Reverse perspective floor plank lines (diverging toward the back!)
    for (let k = 1; k <= 4; k++) {
      let t = k / 5;
      let fx = lerp(x, x + w, t);
      let bkx = lerp(bx1, bx2, pow(t, 0.88));
      let bky = lerp(by2, by2 - 14, pow(t, 0.88));
      strokeLine(fx, y + h, bkx, bky, "pen", PAL.inkSoft, 0.35);
    }
  } else if (tiltDir === "left") {
    // Right side wall visible, floor tilts up and left
    bx1 = x;
    bx2 = x + w - sideW;
    by1 = y + ceilH;
    by2 = y + h - floorDepth;

    // Back wall
    drawPoly([[bx1, by1 - 10], [bx2, by1], [bx2, by2], [bx1, by2 - 14]], {
      wash: backCol,
      washAlpha: 210,
      fill: backCol,
      fillAlpha: 95,
      bleed: 0.05,
      tex: 0.55,
      border: 0.4,
      stroke: PAL.ink,
      weight: 0.55
    });

    if (backPanelBorder) {
      let m = 18;
      drawPoly(
        [
          [bx1 + m, by1 - 10 + m],
          [bx2 - m, by1 + m],
          [bx2 - m, by2 - m],
          [bx1 + m, by2 - 14 - m]
        ],
        {
          stroke: backPanelBorder,
          brush: "pen",
          weight: 0.45
        }
      );
    }

    // Ceiling underside
    drawPoly([[x, y], [x + w, y], [bx2, by1], [bx1, by1 - 10]], {
      wash: ceilCol,
      washAlpha: 225,
      fill: ceilCol,
      fillAlpha: 105,
      bleed: 0.04,
      tex: 0.5,
      stroke: PAL.ink,
      weight: 0.55
    });

    // Right inner wall plane
    drawPoly([[bx2, by1], [x + w, y], [x + w, y + h], [bx2, by2]], {
      wash: sideCol,
      washAlpha: 230,
      fill: sideCol,
      fillAlpha: 115,
      bleed: 0.05,
      tex: 0.55,
      stroke: PAL.ink,
      weight: 0.55
    });

    // Tilted Floor plane
    let floorPts = [[x, y + h], [bx1, by2 - 14], [bx2, by2], [x + w, y + h]];
    drawPoly(floorPts, {
      wash: floorCol,
      washAlpha: 235,
      fill: floorCol,
      fillAlpha: 120,
      bleed: 0.05,
      tex: 0.6,
      hatch: !!matGrid,
      hatchBrush: "pen",
      hatchColor: PAL.inkSoft,
      hatchWeight: 0.3,
      hatchDist: 14,
      hatchAngle: 6,
      stroke: PAL.ink,
      weight: 0.65
    });

    for (let k = 1; k <= 4; k++) {
      let t = k / 5;
      let fx = lerp(x, x + w, t);
      let bkx = lerp(bx1, bx2, 1 - pow(1 - t, 0.88));
      let bky = lerp(by2 - 14, by2, 1 - pow(1 - t, 0.88));
      strokeLine(fx, y + h, bkx, bky, "pen", PAL.inkSoft, 0.35);
    }
  } else {
    // Diverging dual-wall reverse perspective
    let sL = sideW * 0.75;
    let sR = sideW * 0.75;
    by1 = y + ceilH;
    by2 = y + h - floorDepth;

    drawPoly([[x + sL, by1], [x + w - sR, by1], [x + w - sR * 0.6, by2], [x + sL * 0.6, by2]], {
      wash: backCol,
      washAlpha: 215,
      fill: backCol,
      fillAlpha: 95,
      bleed: 0.05,
      tex: 0.55,
      stroke: PAL.ink,
      weight: 0.55
    });
    drawPoly([[x, y], [x + w, y], [x + w - sR, by1], [x + sL, by1]], {
      wash: ceilCol,
      washAlpha: 225,
      fill: ceilCol,
      fillAlpha: 100,
      bleed: 0.04,
      stroke: PAL.ink,
      weight: 0.55
    });
    drawPoly([[x, y], [x + sL, by1], [x + sL * 0.6, by2], [x, y + h]], {
      wash: sideCol,
      washAlpha: 230,
      fill: sideCol,
      fillAlpha: 110,
      bleed: 0.05,
      stroke: PAL.ink,
      weight: 0.55
    });
    drawPoly([[x + w - sR, by1], [x + w, y], [x + w, y + h], [x + w - sR * 0.6, by2]], {
      wash: PAL.ochreDark,
      washAlpha: 230,
      fill: PAL.ochreDark,
      fillAlpha: 110,
      bleed: 0.05,
      stroke: PAL.ink,
      weight: 0.55
    });
    drawPoly([[x, y + h], [x + sL * 0.6, by2], [x + w - sR * 0.6, by2], [x + w, y + h]], {
      wash: floorCol,
      washAlpha: 235,
      fill: floorCol,
      fillAlpha: 120,
      bleed: 0.05,
      tex: 0.6,
      stroke: PAL.ink,
      weight: 0.65
    });
  }
}

