  let lRx = 31, lRy = 24, lRot = 7;

  // 1. Delicate Cast Shadow of the Frames & Temple Arms onto the Comic Page
  let shL = getEllipsePts(Lcx + 5, Lcy + 11, lRx, lRy, lRot, 28);
  let shR = getEllipsePts(Rcx + 5, Rcy + 11, lRx, lRy, lRot, 28);
