  drawPoly(shR, { stroke: "#5c4d3c", brush: "cpencil", weight: 1.2 });
  // Temple arm shadows
  strokeLine(Lcx - 28, Lcy + 6, 785, 154, "cpencil", "#6b5a47", 1.1);
  strokeLine(Rcx + 29, Rcy + 8, 976, 152, "cpencil", "#6b5a47", 1.1);

  // 2. Temple Arms (Folding back into the comic crease, gold wire + tortoiseshell ear tips)
