  strokeSpline([[804, 153], [790, 141], [773, 147]], 0.5, "pen", "#d98929", 0.7);

  // Right temple arm
  strokeLine(Rcx + 30, Rcy - 2, 965, 154, "rotring", "#d49b28", 1.3);
  strokeLine(Rcx + 30, Rcy - 3, 965, 153, "rotring", PAL.goldBright, 0.55);
  strokeSpline([[965, 154], [978, 140], [998, 144], [1006, 156]], 0.5, "rotring", "#4a2210", 1.9);
  strokeSpline([[965, 153], [978, 139], [996, 143]], 0.5, "pen", "#d98929", 0.7);

  // 3. Translucent Lenses with Anti-Reflective Cyan/Emerald Tint & Refracted Lines
  let lensLPts = getEllipsePts(Lcx, Lcy, lRx, lRy, lRot, 32);
  let lensRPts = getEllipsePts(Rcx, Rcy, lRx, lRy, lRot, 32);
  drawPoly(lensLPts, { wash: "#8ce0c8", washAlpha: 48 });
  drawPoly(lensRPts, { wash: "#8ce0c8", washAlpha: 48 });

  // Refracted shifted panel border inside Left Lens
  strokeLine(Lcx - 18, Lcy + 3, Lcx + 22, Lcy - 2, "rotring", PAL.ink, 0.75);
  // Crisp Diagonal Specular Lens Glare Streaks (White + Ice Cyan)
  drawPoly([[Lcx - 18, Lcy - 16], [Lcx - 6, Lcy - 18], [Lcx - 16, Lcy + 15], [Lcx - 24, Lcy + 11]], {
    wash: PAL.white, washAlpha: 215
  });
  drawPoly([[Lcx - 1, Lcy - 18], [Lcx + 5, Lcy - 18], [Lcx - 6, Lcy + 17], [Lcx - 11, Lcy + 16]], {
    wash: "#bdf7e8", washAlpha: 185
  });

  drawPoly([[Rcx - 18, Rcy - 16], [Rcx - 6, Rcy - 18], [Rcx - 16, Rcy + 15], [Rcx - 24, Rcy + 11]], {
    wash: PAL.white, washAlpha: 215
  });
  drawPoly([[Rcx - 1, Rcy - 18], [Rcx + 5, Rcy - 18], [Rcx - 6, Rcy + 17], [Rcx - 11, Rcy + 16]], {
    wash: "#bdf7e8", washAlpha: 185
  });

  // 4. Silicone Nose Pads & Gold Wire Arms
  drawPoly(getEllipsePts(Lcx + 25, Lcy + 4, 3.5, 6.5, -18, 12), {
    wash: "#edf7f2", washAlpha: 220, stroke: "#b89028", weight: 0.4
  });
  drawPoly(getEllipsePts(Rcx - 25, Rcy + 2, 3.5, 6.5, 22, 12), {
    wash: "#edf7f2", washAlpha: 220, stroke: "#b89028", weight: 0.4
  });

  // 5. Tortoiseshell & Gold Frames (Browline / Round Classic Frames)
  // Outer rim dark tortoiseshell
  drawPoly(lensLPts, { stroke: "#381808", brush: "rotring", weight: 2.3 });
  drawPoly(lensRPts, { stroke: "#381808", brush: "rotring", weight: 2.3 });
  // Lower gold wire rim highlight
  for (let side of [[Lcx, Lcy], [Rcx, Rcy]]) {
    let [scx, scy] = side;
    // Tortoiseshell amber mottling spots along upper brow rim
    for (let a = 195; a <= 345; a += 25) {
      let mx = scx + cos(a) * lRx;
      let my = scy + sin(a) * lRy;
      strokeLine(mx - 3, my, mx + 3, my + 1, "pen", "#d98224", 1.3);
      strokeLine(mx - 1, my - 1, mx + 2, my - 1, "rotring", "#ffcf70", 0.6);
    }
    // Specular white-gold rim glint at top-left of frame
    strokeLine(scx - 18, scy - 19, scx - 6, scy - 23, "rotring", PAL.white, 0.85);
  }

  // Gold Nose Bridge & End-pieces
  strokeSpline([[Lcx + 29, Lcy - 5], [882, 196], [Rcx - 29, Rcy - 6]], 0.5, "rotring", "#381808", 2.0);
  strokeSpline([[Lcx + 29, Lcy - 5], [882, 196], [Rcx - 29, Rcy - 6]], 0.5, "rotring", "#e8b438", 1.2);
  strokeSpline([[Lcx + 30, Lcy - 6], [882, 195], [Rcx - 30, Rcy - 7]], 0.5, "rotring", PAL.white, 0.55);

  // Metal hinge lugs on left and right outer edges
  drawPoly([[Lcx - 36, Lcy - 6], [Lcx - 29, Lcy - 5], [Lcx - 29, Lcy], [Lcx - 36, Lcy - 1]], {
