function drawStandingRamenPacket(x, y, w, h) {
  // Tilted reverse-perspective foil pouch in glossy black, gold, and crimson
  let bodyPts = [
    [x + 8, y], [x + w - 4, y - 10],
    [x + w + 8, y + h - 8], [x - 4, y + h]
  ];
  drawPoly(bodyPts, {
    wash: "#1e1a18",
    hatch: true,
    hatchBrush: "cpencil",
    hatchColor: "#0d0b0a",
    hatchDist: 4,
    hatchAngle: 35,
    stroke: PAL.ink,
    weight: 0.65
  });

  // Top & bottom metallic gold crimped seals
  let topCrimp = [];
  for (let i = 0; i <= 14; i++) {
    let px = lerp(x + 6, x + w - 2, i / 14);
    let py = lerp(y, y - 10, i / 14) + (i % 2 === 0 ? -5 : 0);
    topCrimp.push([px, py]);
  }
  topCrimp.push([x + w - 4, y + 6], [x + 8, y + 16]);
  drawPoly(topCrimp, { wash: "#d9a22b", stroke: PAL.ink, weight: 0.45 });

  // Vivid crimson-and-gold diagonal banner on standing packet
  drawPoly([[x + 6, y + 28], [x + w - 2, y + 18], [x + w + 2, y + 96], [x + 2, y + 106]], {
    wash: "#c92818", stroke: "#f0b938", weight: 0.7
  });
  // Central gold medallion on standing packet
  drawPoly(getEllipsePts(x + w * 0.52, y + 65, 34, 28, -5, 20), {
    wash: "#f2be38", stroke: PAL.ink, weight: 0.6
  });
  // Bold Hangul/Hanja strokes inside medallion
  strokeLine(x + w * 0.52 - 14, y + 56, x + w * 0.52 + 14, y + 54, "rotring", PAL.ink, 1.3);
  strokeLine(x + w * 0.52, y + 48, x + w * 0.52, y + 78, "rotring", PAL.ink, 1.3);
  strokeLine(x + w * 0.52 - 10, y + 68, x + w * 0.52 + 12, y + 66, "rotring", "#c92818", 1.1);

  // Bowl graphic at bottom of standing packet
  drawPoly(getEllipsePts(x + w * 0.52, y + 142, 44, 24, -4, 22), {
    wash: "#f0a824", stroke: "#f5e6c4", weight: 0.6
  });
  for (let n = 0; n < 8; n++) {
    let nx = x + 36 + n * 9;
    strokeSpline([[nx, y + 135], [nx + 5, y + 148], [nx + 10, y + 136]], 0.6, "pen", "#fff2a6", 0.7);
  }

  // Sharp plastic foil crinkle highlights
  drawPoly([[x + 14, y + 18], [x + 24, y + 16], [x + 18, y + 150], [x + 10, y + 148]], {
    wash: PAL.white, washAlpha: 165
  });
  strokeSpline([[x + w - 16, y + 20], [x + w - 24, y + 75], [x + w - 12, y + 130]], 0.5, "pen", PAL.white, 1.1);
}

