function drawHeroRedRamenPacket(x, y, w, h) {
  // Reverse perspective pillow pouch: back edge (top) is wider than front edge (bottom)!
  let pTL = [x + 14, y];
  let pTR = [x + w + 26, y - 14];
  let pBR = [x + w + 8, y + h - 12];
  let pBL = [x - 4, y + h];

  // Left corrugated zig-zag crimp seal fin
  let leftFin = [pTL, pBL];
  for (let i = 12; i >= 0; i--) {
    let t = i / 12;
    let fx = lerp(pTL[0], pBL[0], t) - 22 + (i % 2 === 0 ? -5 : 0);
    let fy = lerp(pTL[1], pBL[1], t) + 4;
    leftFin.push([fx, fy]);
  }
  drawPoly(leftFin, {
    wash: "#c42016",
    hatch: true,
    hatchBrush: "pen",
    hatchColor: "#7a0e08",
    hatchDist: 3.5,
    hatchAngle: 8,
    stroke: PAL.ink,
    weight: 0.5
  });
  // Silver-gold foil strip on outer crimp edge
  strokeLine(pTL[0] - 20, pTL[1] + 4, pBL[0] - 20, pBL[1] + 4, "pen", "#e8c458", 1.2);

  // Right corrugated zig-zag crimp seal fin
  let rightFin = [pTR, pBR];
  for (let i = 12; i >= 0; i--) {
    let t = i / 12;
    let fx = lerp(pTR[0], pBR[0], t) + 22 + (i % 2 === 0 ? 5 : 0);
    let fy = lerp(pTR[1], pBR[1], t) - 2;
    rightFin.push([fx, fy]);
  }
  drawPoly(rightFin, {
    wash: "#b01810",
    hatch: true,
    hatchBrush: "pen",
    hatchColor: "#690a05",
    hatchDist: 3.5,
    hatchAngle: -8,
    stroke: PAL.ink,
    weight: 0.5
  });

  // Main puffed pillow body of the Hero Red Ramen Packet
  let bodyPts = [
    pTL,
    [lerp(pTL[0], pTR[0], 0.5), lerp(pTL[1], pTR[1], 0.5) - 8],
    pTR,
    [lerp(pTR[0], pBR[0], 0.5) + 8, lerp(pTR[1], pBR[1], 0.5)],
    pBR,
    [lerp(pBL[0], pBR[0], 0.5), lerp(pBL[1], pBR[1], 0.5) + 10],
    pBL,
    [lerp(pTL[0], pBL[0], 0.5) - 8, lerp(pTL[1], pBL[1], 0.5)]
  ];
  drawPoly(bodyPts, {
    wash: "#d92418",
    stroke: PAL.ink,
    weight: 0.7,
    curvature: 0.15
  });

  // Deep crimson crinkle shadow troughs on corners & lower belly
  drawPoly([pBL, [x + 95, y + h - 18], [x + w + 8, y + h - 12], [x + 130, y + h + 8]], {
    wash: "#8a1008",
    washAlpha: 210,
    hatch: true,
    hatchBrush: "cpencil",
    hatchColor: "#4f0602",
    hatchDist: 3,
    hatchAngle: -6
  });
  drawPoly([pTL, [x + 65, y + 6], [x + 42, y + 52], [x + 2, y + 68]], {
    wash: "#9e140c", washAlpha: 185
  });

  // Black & Gold Diagonal Accent Slash on Packet Corner
  drawPoly([pTL, [x + 98, y - 4], [x + 8, y + 78], [x + 4, y + 42]], {
    wash: "#1c1816", stroke: "#f0c242", weight: 0.8
  });

  // ILLUSTRATED BOWL OF NOODLES ON RIGHT HALF OF PACKET
  let bowlCx = x + 198, bowlCy = y + 96;
  // Black ceramic bowl rim on label
  drawPoly(getEllipsePts(bowlCx, bowlCy, 56, 36, -5, 26), {
    wash: "#1c1816", stroke: "#e8b638", weight: 0.8
  });
  // Spicy red broth inside bowl graphic
  drawPoly(getEllipsePts(bowlCx, bowlCy - 2, 48, 29, -5, 24), {
    wash: "#b81d12"
  });
  // Golden curly ramen noodles inside the illustrated bowl
  for (let i = 0; i < 16; i++) {
    let ang = i * 22;
    let r1 = random(6, 36);
    let nx = bowlCx + cos(ang) * r1;
    let ny = bowlCy - 2 + sin(ang) * (r1 * 0.55);
    strokeSpline(
      [[nx - 10, ny - 3], [nx, ny + 5], [nx + 10, ny - 2], [nx + 16, ny + 4]],
      0.65,
      "pen",
      i % 2 === 0 ? "#f7c838" : "#ffe885",
      0.85
    );
  }
  // Shiitake mushroom slice (dark brown star-slit cap) + green scallion rings + red chili
  drawPoly(getEllipsePts(bowlCx + 12, bowlCy - 8, 13, 9, -10, 14), {
    wash: "#3d2212", stroke: "#e8d2b0", weight: 0.45
  });
  strokeLine(bowlCx + 7, bowlCy - 8, bowlCx + 17, bowlCy - 8, "pen", "#f5e6cc", 0.55);
  strokeLine(bowlCx + 12, bowlCy - 13, bowlCx + 12, bowlCy - 3, "pen", "#f5e6cc", 0.55);
  // Green scallion rings
  let scallions = [[bowlCx - 18, bowlCy - 6], [bowlCx - 8, bowlCy + 8], [bowlCx + 24, bowlCy + 5]];
  for (let sc of scallions) {
    drawPoly(getEllipsePts(sc[0], sc[1], 6, 4, 15, 12), {
      wash: "#3ea848", stroke: "#b8f2a6", weight: 0.4
    });
  }
  // Red chili slice rings
  drawPoly(getEllipsePts(bowlCx - 4, bowlCy - 14, 6, 4, -15, 12), {
    wash: "#ff2a1a", stroke: "#ffcf70", weight: 0.4
  });

  // ICONIC OCTAGONAL SHIELD EMBLEM (Left-Center of Packet)
  let embCx = x + 106, embCy = y + 76;
  let octOuter = [];
  let octInner = [];
  for (let i = 0; i < 8; i++) {
    let a = i * 45 + 22.5;
    octOuter.push([embCx + cos(a) * 52, embCy + sin(a) * 48]);
    octInner.push([embCx + cos(a) * 45, embCy + sin(a) * 41]);
  }
  drawPoly(octOuter, { wash: "#f2c438", stroke: PAL.white, weight: 0.9 });
  drawPoly(octInner, { wash: "#171412", stroke: "#d92418", weight: 0.7 });

  // BOLD CALLIGRAPHY CHARACTER '辛' (SHIN) INSIDE OCTAGON SHIELD!
  // Rendered with crisp white brush/pen strokes for unmistakable authenticity
  let chX = embCx, chY = embCy - 2;
  // Top dot
  strokeLine(chX - 2, chY - 28, chX + 3, chY - 21, "marker", PAL.white, 1.3);
  // First horizontal bar
  strokeLine(chX - 24, chY - 19, chX + 24, chY - 21, "marker", PAL.white, 1.4);
  // Two vertical slants between bars
  strokeLine(chX - 11, chY - 18, chX - 7, chY - 6, "marker", PAL.white, 1.1);
  strokeLine(chX + 12, chY - 19, chX + 7, chY - 6, "marker", PAL.white, 1.1);
  // Middle wide horizontal bar
  strokeLine(chX - 30, chY - 5, chX + 30, chY - 7, "marker", PAL.white, 1.5);
  // Lower horizontal bar
  strokeLine(chX - 21, chY + 9, chX + 21, chY + 7, "marker", PAL.white, 1.3);
  // Central vertical stroke piercing down
  strokeLine(chX, chY - 5, chX, chY + 29, "marker", PAL.white, 1.5);
  // Red stamp seal box next to calligraphy
  drawPoly([[chX + 16, chY + 12], [chX + 28, chY + 12], [chX + 28, chY + 25], [chX + 16, chY + 25]], {
    wash: "#d92418", stroke: PAL.white, weight: 0.35
  });

  // Mini white & gold Hangul sub-label ('라면') & weight spec at bottom-left
  drawPoly([[x + 22, y + 128], [x + 88, y + 124], [x + 88, y + 144], [x + 22, y + 148]], {
    wash: "#171412", stroke: "#f2c438", weight: 0.45
  });
  strokeLine(x + 30, y + 136, x + 46, y + 135, "rotring", PAL.white, 0.85);
  strokeLine(x + 54, y + 135, x + 78, y + 134, "rotring", "#f2c438", 0.85);

  // =========================================================================
  // HYPERREAL FOIL CRINKLE SPECULAR GLOSS HIGHLIGHTS ON THE RAMEN PACKET
  // =========================================================================
  // Long angular white specular reflection ribbons across the pinched plastic film
  drawPoly([[x + 32, y + 8], [x + 158, y - 2], [x + 142, y + 12], [x + 42, y + 18]], {
    wash: "#ff9b87", washAlpha: 170
  });
  drawPoly([[x + 45, y + 10], [x + 138, y + 2], [x + 128, y + 8], [x + 52, y + 14]], {
    wash: PAL.white, washAlpha: 235
  });

  // Diagonal crinkle lightning reflections near left and bottom-center
  drawPoly([[x + 12, y + 62], [x + 42, y + 48], [x + 34, y + 58], [x + 14, y + 72]], {
    wash: PAL.white, washAlpha: 215
  });
  drawPoly([[x + 122, y + 132], [x + 195, y + 126], [x + 182, y + 138], [x + 115, y + 142]], {
    wash: PAL.white, washAlpha: 210
  });
  // Razor-sharp pinpoint glints along the gold emblem and right crimp ridge
  strokeSpline([[x + 235, y + 12], [x + 252, y + 58], [x + 244, y + 118]], 0.5, "rotring", PAL.white, 1.1);
  strokeSpline([[x + 16, y + 95], [x + 38, y + 115], [x + 76, y + 120]], 0.5, "pen", "#ffd2c4", 0.9);
}

function drawCupRamenWithChopsticks(cx, cy) {
  // Tapered white-and-red paper noodle cup in front-right of L2
  let topRx = 56, topRy = 22;
  let botRx = 40, botRy = 15;
  let cupH = 128;

  // Cup body silhouette
  let bodyPts = [
    [cx - topRx, cy],
    [cx + topRx, cy],
    [cx + botRx, cy + cupH],
    [cx - botRx, cy + cupH]
  ];
  // Bottom ellipse
  let botEll = getEllipsePts(cx, cy + cupH, botRx, botRy, 0, 20);
  drawPoly(botEll, { wash: "#d92418", stroke: PAL.ink, weight: 0.55 });
  drawPoly(bodyPts, {
    wash: "#fcf8f0",
    hatch: true,
    hatchBrush: "cpencil",
    hatchColor: "#c4b69e",
    hatchDist: 4.5,
    hatchAngle: 90,
    stroke: PAL.ink,
    weight: 0.6
  });

  // Red & Gold Curved Graphic Band around the Cup
  let bandPts = [
    [cx - 51, cy + 28], [cx + 51, cy + 28],
    [cx + 44, cy + 92], [cx - 44, cy + 92]
  ];
  drawPoly(bandPts, { wash: "#d92418", stroke: "#f0c242", weight: 0.7 });

  // Vertical black & gold calligraphy badge on the cup
  drawPoly([[cx - 16, cy + 34], [cx + 16, cy + 34], [cx + 14, cy + 86], [cx - 14, cy + 86]], {
    wash: "#1a1614", stroke: "#f0c242", weight: 0.55
  });
  strokeLine(cx - 8, cy + 46, cx + 8, cy + 46, "rotring", PAL.white, 1.0);
  strokeLine(cx, cy + 40, cx, cy + 62, "rotring", PAL.white, 1.0);
  strokeLine(cx - 7, cy + 72, cx + 7, cy + 72, "rotring", "#f0c242", 0.9);

  // Specular highlight strip down left side of cup
  drawPoly([[cx - 38, cy + 10], [cx - 26, cy + 10], [cx - 20, cy + 120], [cx - 28, cy + 120]], {
    wash: PAL.white, washAlpha: 155
  });

  // Cup Top Rim & Open Interior showing Curly Noodles
  drawPoly(getEllipsePts(cx, cy, topRx + 3, topRy + 2, 0, 28), {
    wash: "#e8dec8", stroke: PAL.ink, weight: 0.65
  });
  drawPoly(getEllipsePts(cx, cy + 2, topRx - 4, topRy - 3, 0, 26), {
    wash: "#8a2814", stroke: PAL.ink, weight: 0.5
  });
  // Noodles & freeze-dried green onion/egg bits inside open cup
  for (let i = 0; i < 12; i++) {
    let nx = cx + random(-32, 28);
    let ny = cy + random(-8, 10);
    strokeSpline([[nx - 8, ny], [nx, ny + 4], [nx + 8, ny - 2]], 0.6, "pen", "#f7cc46", 0.85);
  }
  drawPoly(getEllipsePts(cx - 12, cy + 4, 5, 3, 0, 10), { wash: "#46a844" });
  drawPoly(getEllipsePts(cx + 14, cy + 2, 5, 3.5, 0, 10), { wash: "#ffd644" });

