function drawSojuShotGlass(gx, gy, hasLiquid) {
  let topR = 20, botR = 14, h = 46;
  // Thick clear glass base block
  drawPoly([
    [gx - botR - 1, gy + h - 12], [gx + botR + 1, gy + h - 12],
    [gx + botR, gy + h], [gx - botR, gy + h]
  ], {
    wash: "#b8d4cc", washAlpha: 210, stroke: "#2b423b", weight: 0.5
  });
  drawPoly(getEllipsePts(gx, gy + h, botR, 6, 0, 18), {
    wash: "#8ab5a9", washAlpha: 220, stroke: "#1f332d", weight: 0.55
  });

  // Glass cup walls
  drawPoly([
    [gx - topR, gy], [gx + topR, gy],
    [gx + botR, gy + h], [gx - botR, gy + h]
  ], {
    wash: "#e4f2ee", washAlpha: 95, stroke: "#2b423b", weight: 0.55
  });

  // Clear liquid & bright meniscus inside shot glass
  if (hasLiquid) {
    let liqY = gy + 13;
    let liqR = lerp(topR, botR, 13 / h);
    drawPoly([
      [gx - liqR, liqY], [gx + liqR, liqY],
      [gx + botR + 1, gy + h - 12], [gx - botR - 1, gy + h - 12]
    ], {
      wash: "#d0ede4", washAlpha: 115
    });
    drawPoly(getEllipsePts(gx, liqY, liqR, 5, 0, 18), {
      wash: "#eefaf6", washAlpha: 175, stroke: PAL.white, weight: 0.7
    });
  }

  // Rim ellipse & vertical white glass reflections
  drawPoly(getEllipsePts(gx, gy, topR, 6.5, 0, 22), {
    stroke: PAL.white, brush: "rotring", weight: 0.9
  });
  drawPoly(getEllipsePts(gx, gy, topR, 6.5, 0, 22), {
    stroke: "#2b423b", brush: "rotring", weight: 0.45
  });
  drawPoly([
    [gx - topR + 4, gy + 4], [gx - topR + 9, gy + 4],
    [gx - botR + 7, gy + h - 4], [gx - botR + 3, gy + h - 4]
  ], {
    wash: PAL.white, washAlpha: 225
  });
  strokeLine(gx + topR - 5, gy + 5, gx + botR - 4, gy + h - 5, "rotring", PAL.white, 0.8);
}

