function drawTimberBeam(x, y, w, h, isVert = false) {
  drawPoly([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], {
    wash: PAL.ochre,
    fill: PAL.ochre,
    fillAlpha: 115,
    bleed: 0.03,
    tex: 0.5,
    stroke: PAL.ink,
    weight: 0.75
  });
  // Subtle wood grain ink lines
  if (isVert) {
    strokeLine(x + w * 0.5, y + 6, x + w * 0.5, y + h - 6, "pen", PAL.ochreDark, 0.35);
  } else {
    strokeLine(x + 6, y + h * 0.5, x + w - 6, y + h * 0.5, "pen", PAL.ochreDark, 0.35);
  }
}

// Traditional Korean Chaekgeori Corner Fretwork Bracket (완자무늬)
function drawFretworkCorner(x, y, dirX, dirY, col) {
  // dirX: 1 for left corner, -1 for right corner
  let s1 = 46, s2 = 28, t = 9;
  // Horizontal arm
  drawPoly([
    [x, y], [x + dirX * s1, y],
    [x + dirX * s1, y + dirY * t], [x, y + dirY * t]
  ], { wash: col, stroke: PAL.ink, weight: 0.55 });
  // Vertical arm
  drawPoly([
    [x, y], [x + dirX * t, y],
    [x + dirX * t, y + dirY * s1], [x, y + dirY * s1]
  ], { wash: col, stroke: PAL.ink, weight: 0.55 });
  // Inner stepped return hook
  drawPoly([
    [x + dirX * s2, y + dirY * t], [x + dirX * (s2 + t), y + dirY * t],
    [x + dirX * (s2 + t), y + dirY * s2], [x + dirX * t, y + dirY * s2],
    [x + dirX * t, y + dirY * (s2 - t)], [x + dirX * s2, y + dirY * (s2 - t)]
  ], { wash: PAL.gold, stroke: PAL.ink, weight: 0.5 });
}

