function drawOrchidBlossom(fx, fy, sc, rotDeg) {
  push();
  translate(fx, fy);
  rotate(rotDeg);

  // 1. Dorsal Sepal (Top) & Two Lateral Sepals (Bottom-Left & Bottom-Right)
  let topSepal = getEllipsePts(0, -20 * sc, 13 * sc, 21 * sc, 0, 18);
  let botLeftSepal = getEllipsePts(-14 * sc, 15 * sc, 12 * sc, 19 * sc, 35, 18);
  let botRightSepal = getEllipsePts(14 * sc, 15 * sc, 12 * sc, 19 * sc, -35, 18);

  for (let sep of [botLeftSepal, botRightSepal, topSepal]) {
    drawPoly(sep, {
      wash: "#f5efe4",
      fill: "#dfd3c0",
      fillAlpha: 85,
      bleed: 0.02,
      stroke: "#8c7b68",
      weight: 0.45
    });
  }

  // 2. Two Large Broad Lateral Petals (Left & Right Wings)
  let leftPetal = getEllipsePts(-22 * sc, -3 * sc, 22 * sc, 17 * sc, -12, 20);
  let rightPetal = getEllipsePts(22 * sc, -3 * sc, 22 * sc, 17 * sc, 12, 20);
  for (let pet of [leftPetal, rightPetal]) {
    drawPoly(pet, {
      wash: "#fcfaf5",
      stroke: "#7d6b58",
      weight: 0.5
    });
  }
  // Velvety white highlight on upper petal edges
  strokeSpline([[-34 * sc, -12 * sc], [-22 * sc, -17 * sc], [-10 * sc, -11 * sc]], 0.5, "rotring", PAL.white, 0.9);
  strokeSpline([[10 * sc, -11 * sc], [22 * sc, -17 * sc], [34 * sc, -12 * sc]], 0.5, "rotring", PAL.white, 0.9);

  // Delicate Magenta-Rose Throat Flush & Veining radiating from center
  drawPoly(getEllipsePts(0, 0, 12 * sc, 10 * sc, 0, 14), {
    wash: "#e89eb8", washAlpha: 145
  });
  for (let a of [-155, -135, -25, -45, 90]) {
    strokeLine(0, 0, cos(a) * 18 * sc, sin(a) * 15 * sc, "pen", "#c94a78", 0.4);
  }

  // 3. Sculpted 3D Trilobed Labellum (Lip) in Golden-Yellow & Deep Carmine Spots!
  let lipPts = [
    [-9 * sc, 0], [0, -5 * sc], [9 * sc, 0],
    [11 * sc, 10 * sc], [0, 19 * sc], [-11 * sc, 10 * sc]
  ];
  drawPoly(lipPts, {
    wash: "#f5be2e",
    stroke: "#7a1230",
    weight: 0.5,
    curvature: 0.2
  });
  // Carmine-maroon center throat & spots on labellum
  drawPoly(getEllipsePts(0, 7 * sc, 5 * sc, 6 * sc, 0, 12), {
    wash: "#9c143c"
  });
  // White anther cap column at center
  drawPoly(getEllipsePts(0, -2 * sc, 4 * sc, 4.5 * sc, 0, 12), {
    wash: PAL.white, stroke: "#8c7b68", weight: 0.4
  });

  pop();
}

