function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. BEATEN MULBERRY BARK-CLOTH GROUND (DUSKY TWILIGHT RAW SIENNA & BUFF)
  // =========================================================================
  background("#9e8262");

  // Watercolor undertones simulating uneven beaten bark thickness & twilight mood
  brush.noStroke();
  brush.noHatch();

  // Deep twilight umber-slate vignette around the perimeter
  brush.fill("#463932", 62);
  brush.fillBleed(0.45, "in");
  brush.fillTexture(0.8, 0.45);
  brush.rect(0, 0, 1200, 140, "corner");
  brush.rect(0, 1060, 1200, 140, "corner");
  brush.rect(0, 140, 140, 920, "corner");
  brush.rect(1060, 140, 140, 920, "corner");

  // Raw sienna organic patches
  brush.fill("#875c34", 48);
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.75, 0.35);
  for (let i = 0; i < 8; i++) {
    let px = random(120, 1080);
    let py = random(120, 1080);
    brush.circle(px, py, random(180, 320), 0.35);
  }

  // Warm beaten buff center glow
  brush.fill("#cbb28e", 55);
  brush.fillBleed(0.38, "out");
  brush.circle(600, 580, 420, 0.25);
  brush.circle(600, 580, 280, 0.2);

  // Dusky twilight violet-slate subtle cast across upper & lower registers
  brush.fill("#54494b", 38);
  brush.fillBleed(0.35, "out");
  brush.rect(80, 80, 1040, 240, "corner");
  brush.rect(80, 880, 1040, 240, "corner");
  brush.noFill();

  // Felted, fibrous grain of mulberry bark (dry hatching in raw sienna & buff)
  drawBarkClothFibers();

  // =========================================================================
  // 2. CEREMONIAL RULED PANELS & HAND-STAMPED GEOMETRIC BANDS
  // =========================================================================
  drawTapaOrnament();

  // Rubbed bark-fiber pass over the stamped ink so the pigment looks uneven & rubbed-on
  drawRubbedInkOverpass();

  // =========================================================================
  // 3. HYPERREAL OPENED TIN OF CORNED BEEF (CENTERPIECE)
  // =========================================================================
  drawCastShadows();
  drawTinBodyAndLabel();
  drawTinTopRimAndCavity();
  drawCornedBeefAndWaxyFat();
  drawPeeledCurlingLid();
  drawWindingKeyAndCoil();

  noLoop();
}

// ---------------------------------------------------------------------------
// BARK-CLOTH FIBROUS TEXTURE
// ---------------------------------------------------------------------------
function drawBarkClothFibers() {
  // Layer A: Macro cross-hatch across panels in raw sienna and warm buff
  let siennaCols = ["#7a522c", "#8e643b", "#684525", "#9c7348"];
  let buffCols = ["#c7ae8b", "#d8c2a3", "#b89b74", "#e3d0b4"];
  let twilightCols = ["#57483f", "#4b3e39", "#69584d"];

  // Horizontal & vertical felted bast fiber patches
  for (let gx = 0; gx < 1200; gx += 150) {
    for (let gy = 0; gy < 1200; gy += 150) {
      let colS = random(siennaCols);
      let colB = random(buffCols);

      brush.noStroke();
      brush.hatchStyle("bark_fiber", colS, random(0.7, 1.1));
      brush.hatch(random(4.5, 6.5), random(-4, 4), { rand: 0.25 });
      brush.rect(gx + random(-10, 10), gy + random(-10, 10), 165, 165, "corner");

      brush.hatchStyle("bark_fiber", colB, random(0.65, 1.0));
      brush.hatch(random(5.0, 7.5), 90 + random(-4, 4), { rand: 0.25 });
      brush.rect(gx + random(-10, 10), gy + random(-10, 10), 165, 165, "corner");
      brush.noHatch();
    }
  }

  // Layer B: Long wavy mulberry bast fibers running across the cloth
  brush.field("waves");
  brush.wiggle(2.2);

  for (let i = 0; i < 650; i++) {
    let x = random(15, 1185);
    let y = random(15, 1185);
    let len = random(65, 220);
    let isHoriz = random() < 0.58;
    let ang = isHoriz ? random(-6, 6) : 90 + random(-6, 6);

    let r = random();
    if (r < 0.45) {
      brush.set("bark_fiber", random(siennaCols), random(0.55, 1.15));
    } else if (r < 0.82) {
      brush.set("bark_fiber", random(buffCols), random(0.55, 1.1));
    } else {
      brush.set("cpencil", random(twilightCols), random(0.5, 0.9));
    }
    brush.flowLine(x, y, len, ang);
  }

  // Diagonal felted mulberry web fibers (fine binding hairs)
  for (let i = 0; i < 320; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    let ang = random([random(15, 35), random(145, 165), random(-35, -15)]);
    brush.set("cpencil", random() < 0.5 ? "#d8c3a5" : "#78512d", random(0.4, 0.75));
    brush.flowLine(x, y, random(40, 110), ang);
  }

  brush.noField();
}

