function drawTapaOrnament() {
  const umber1 = "#3d2214";
  const umber2 = "#54301d";
  const black1 = "#1a1718";
  const black2 = "#262122";
  const buffLine = "#d6c09e";

  // Helper: hand-ruled bark-cloth line (slightly uneven double pass)
  function ruledLine(x1, y1, x2, y2, col, w = 1.2) {
    brush.wiggle(1.2);
    brush.set("tapa_stamp", col, w);
    brush.line(x1, y1, x2, y2);
    brush.set("cpencil", col, w * 0.7);
    brush.line(
      x1 + random(-1, 1),
      y1 + random(-1, 1),
      x2 + random(-1, 1),
      y2 + random(-1, 1)
    );
    brush.noField();
  }

  // Helper: hand-stamped polygon filled with dense, slightly uneven rubbed hatching
  function stampedPoly(pts, col, ang = 45, spacing = 3.2, outlineW = 0.85) {
    let poly = new brush.Polygon(pts);
    brush.noStroke();
    brush.hatchStyle("tapa_stamp", col, random(0.85, 1.15));
    brush.hatch(spacing, ang + random(-3, 3), { rand: 0.18 });
    poly.hatch(spacing, ang + random(-3, 3), { rand: 0.18 });
    brush.noHatch();
    poly.draw("cpencil", col, outlineW);
  }

  // Helper: stamped four-pointed or eight-pointed ceremonial star (fetu)
  function stampedStar(cx, cy, outerR, innerR, points, colMain, colAccent) {
    // Subtle square framing compartment
    let sq = outerR * 1.05;
    ruledLine(cx - sq, cy - sq, cx + sq, cy - sq, colAccent, 0.8);
    ruledLine(cx + sq, cy - sq, cx + sq, cy + sq, colAccent, 0.8);
    ruledLine(cx + sq, cy + sq, cx - sq, cy + sq, colAccent, 0.8);
    ruledLine(cx - sq, cy + sq, cx - sq, cy - sq, colAccent, 0.8);

    // Diagonal background rays
    ruledLine(cx - sq, cy - sq, cx + sq, cy + sq, colAccent, 0.55);
    ruledLine(cx + sq, cy - sq, cx - sq, cy + sq, colAccent, 0.55);

    // Individual star blades (alternating burnt umber & lamp black halves)
    let step = 360 / points;
    for (let i = 0; i < points; i++) {
      let aMid = i * step;
      let aLeft = aMid - step * 0.5;
      let aRight = aMid + step * 0.5;

      let tipX = cx + cos(aMid) * outerR;
      let tipY = cy + sin(aMid) * outerR;
      let lX = cx + cos(aLeft) * innerR;
      let lY = cy + sin(aLeft) * innerR;
      let rX = cx + cos(aRight) * innerR;
      let rY = cy + sin(aRight) * innerR;

      let c1 = i % 2 === 0 ? colMain : colAccent;
      let c2 = i % 2 === 0 ? colAccent : colMain;

      stampedPoly([[cx, cy], [lX, lY], [tipX, tipY]], c1, aMid + 30, 3.0, 0.7);
      stampedPoly([[cx, cy], [tipX, tipY], [rX, rY]], c2, aMid - 30, 3.0, 0.7);
    }

    // Corner infill triangles inside the star box
    let cOff = sq * 0.92;
    let cLeg = sq * 0.34;
    let corners = [
      [[cx - cOff, cy - cOff], [cx - cOff + cLeg, cy - cOff], [cx - cOff, cy - cOff + cLeg]],
      [[cx + cOff, cy - cOff], [cx + cOff - cLeg, cy - cOff], [cx + cOff, cy - cOff + cLeg]],
      [[cx + cOff, cy + cOff], [cx + cOff - cLeg, cy + cOff], [cx + cOff, cy + cOff - cLeg]],
      [[cx - cOff, cy + cOff], [cx - cOff + cLeg, cy + cOff], [cx - cOff, cy + cOff - cLeg]]
    ];
    for (let cPts of corners) {
      stampedPoly(cPts, colMain, 45, 3.2, 0.65);
    }

    // Center buff & lamp-black rosette eye
    brush.noFill();
    brush.set("tapa_stamp", buffLine, 1.1);
    brush.circle(cx, cy, innerR * 0.42, 0.15);
    brush.set("tapa_stamp", black1, 0.9);
    brush.circle(cx, cy, innerR * 0.18, 0.15);
  }

  // Helper: band of stamped triangles (nihoniho / sawtooth motif)
  function drawTriangleBand(x1, y1, x2, y2, count, dir, colA, colB) {
    let isHoriz = abs(x2 - x1) > abs(y2 - y1);
    for (let i = 0; i < count; i++) {
      let t0 = i / count;
      let t1 = (i + 0.5) / count;
      let t2 = (i + 1) / count;
      let col = i % 2 === 0 ? colA : colB;

      if (isHoriz) {
        let xa = lerp(x1, x2, t0);
        let xm = lerp(x1, x2, t1);
        let xb = lerp(x1, x2, t2);
        let baseY = dir > 0 ? y1 : y2;
        let tipY = dir > 0 ? y2 : y1;
        stampedPoly([[xa, baseY], [xb, baseY], [xm, tipY]], col, 60, 3.3, 0.75);
      } else {
        let ya = lerp(y1, y2, t0);
        let ym = lerp(y1, y2, t1);
        let yb = lerp(y1, y2, t2);
        let baseX = dir > 0 ? x1 : x2;
        let tipX = dir > 0 ? x2 : x1;
        stampedPoly([[baseX, ya], [baseX, yb], [tipX, ym]], col, 30, 3.3, 0.75);
      }
    }
  }

  // Helper: band of hand-stamped chevrons
  function drawChevronBand(x, y, w, h, count, orientation, colA, colB) {
    if (orientation === "H") {
      let step = w / count;
      let midY = y + h * 0.5;
      for (let i = 0; i < count; i++) {
        if (i % 2 !== 0) continue;
        let sx = x + i * step;
        let tk = step * 0.65;
        let tipShift = step * 0.75;
        let col = (i / 2) % 2 === 0 ? colA : colB;
        let pts = [
          [sx, y + 4],
          [sx + tk, y + 4],
          [sx + tk + tipShift, midY],
          [sx + tk, y + h - 4],
          [sx, y + h - 4],
          [sx + tipShift, midY]
        ];
        stampedPoly(pts, col, 45, 3.1, 0.75);
      }
    } else {
      let step = h / count;
      let midX = x + w * 0.5;
      for (let i = 0; i < count; i++) {
        if (i % 2 !== 0) continue;
        let sy = y + i * step;
        let tk = step * 0.65;
        let tipShift = step * 0.75;
        let col = (i / 2) % 2 === 0 ? colA : colB;
        let pts = [
          [x + 4, sy],
          [x + 4, sy + tk],
          [midX, sy + tk + tipShift],
          [x + w - 4, sy + tk],
          [x + w - 4, sy],
          [midX, sy + tipShift]
        ];
        stampedPoly(pts, col, -45, 3.1, 0.75);
      }
    }
  }

  // -------------------------------------------------------------------------
  // RING 1: OUTERMOST BORDER FRAME & SAWTOOTH TRIANGLE REGISTER (56..112)
  // -------------------------------------------------------------------------
  let r0 = 56;
  let r1 = 112;
  ruledLine(r0, r0, 1200 - r0, r0, black1, 1.5);
  ruledLine(1200 - r0, r0, 1200 - r0, 1200 - r0, black1, 1.5);
  ruledLine(1200 - r0, 1200 - r0, r0, 1200 - r0, black1, 1.5);
  ruledLine(r0, 1200 - r0, r0, r0, black1, 1.5);

  ruledLine(r1, r1, 1200 - r1, r1, umber1, 1.3);
  ruledLine(1200 - r1, r1, 1200 - r1, 1200 - r1, umber1, 1.3);
  ruledLine(1200 - r1, 1200 - r1, r1, 1200 - r1, umber1, 1.3);
  ruledLine(r1, 1200 - r1, r1, r1, umber1, 1.3);

  // Outer sawtooth triangles on all 4 sides
  drawTriangleBand(r1, r0 + 4, 1200 - r1, r1 - 4, 22, 1, black1, umber1);
  drawTriangleBand(r1, 1200 - r1 + 4, 1200 - r1, 1200 - r0 - 4, 22, -1, black1, umber1);
  drawTriangleBand(r0 + 4, r1, r1 - 4, 1200 - r1, 22, 1, umber1, black1);
  drawTriangleBand(1200 - r1 + 4, r1, 1200 - r0 - 4, 1200 - r1, 22, -1, umber1, black1);

  // Corner squares of Ring 1 (small 4-point stars)
  let c1Centers = [
    [84, 84],
    [1116, 84],
    [1116, 1116],
    [84, 1116]
  ];
  for (let [cx, cy] of c1Centers) {
    stampedStar(cx, cy, 22, 8, 4, black1, umber1);
  }

  // -------------------------------------------------------------------------
  // RULED DIVIDER BAND (112..130) WITH HAND-STAMPED TICKS
  // -------------------------------------------------------------------------
  let r2 = 130;
  ruledLine(r2, r2, 1200 - r2, r2, black1, 1.4);
  ruledLine(1200 - r2, r2, 1200 - r2, 1200 - r2, black1, 1.4);
  ruledLine(1200 - r2, 1200 - r2, r2, 1200 - r2, black1, 1.4);
  ruledLine(r2, 1200 - r2, r2, r2, black1, 1.4);

  for (let t = r2; t <= 1200 - r2; t += 16) {
    ruledLine(t, r1 + 3, t, r2 - 3, umber2, 0.85);
    ruledLine(t, 1200 - r2 + 3, t, 1200 - r1 - 3, umber2, 0.85);
    ruledLine(r1 + 3, t, r2 - 3, t, umber2, 0.85);
    ruledLine(1200 - r2 + 3, t, 1200 - r1 - 3, t, umber2, 0.85);
  }

  // -------------------------------------------------------------------------
  // RING 2: WIDE CEREMONIAL REGISTER (130..250)
  // -------------------------------------------------------------------------
  let r3 = 250;
  ruledLine(r3, r3, 1200 - r3, r3, black1, 1.5);
  ruledLine(1200 - r3, r3, 1200 - r3, 1200 - r3, black1, 1.5);
  ruledLine(1200 - r3, 1200 - r3, r3, 1200 - r3, black1, 1.5);
  ruledLine(r3, 1200 - r3, r3, r3, black1, 1.5);

  // Four Grand Corner Medallions (8-pointed stars at TL, TR, BR, BL)
  let grandCorners = [
    [190, 190],
    [1010, 190],
    [1010, 1010],
    [190, 1010]
  ];
  for (let [cx, cy] of grandCorners) {
    stampedStar(cx, cy, 52, 17, 8, black1, umber1);
  }

  // Sub-compartments along Top, Bottom, Left, Right (from 250 to 950 = 700px, 5 panels of 140px)
  for (let i = 0; i < 5; i++) {
    let pStart = 250 + i * 140;
    let pEnd = pStart + 140;
    let pMid = pStart + 70;

    // Panel divider lines
    ruledLine(pStart, r2, pStart, r3, black1, 1.2);
    ruledLine(pStart, 1200 - r3, pStart, 1200 - r2, black1, 1.2);
    ruledLine(r2, pStart, r3, pStart, black1, 1.2);
    ruledLine(1200 - r3, pStart, 1200 - r2, pStart, black1, 1.2);

    if (i % 2 === 1) {
      // Cardinal & intermediate star medallions
      stampedStar(pMid, 190, 48, 15, 8, umber1, black1);
      stampedStar(pMid, 1010, 48, 15, 8, umber1, black1);
      stampedStar(190, pMid, 48, 15, 8, umber1, black1);
      stampedStar(1010, pMid, 48, 15, 8, umber1, black1);
    } else {
      // Twin Chevron corridors in burnt umber and lamp black
      // Top panel
      ruledLine(pStart, 190, pEnd, 190, umber1, 1.0);
      drawChevronBand(pStart + 6, r2 + 4, 128, 52, 12, "H", black1, umber1);
      drawChevronBand(pStart + 6, 194, 128, 52, 12, "H", umber1, black1);

      // Bottom panel
      ruledLine(pStart, 1010, pEnd, 1010, umber1, 1.0);
      drawChevronBand(pStart + 6, 1200 - r3 + 4, 128, 52, 12, "H", umber1, black1);
      drawChevronBand(pStart + 6, 1014, 128, 52, 12, "H", black1, umber1);

      // Left panel
      ruledLine(190, pStart, 190, pEnd, umber1, 1.0);
      drawChevronBand(r2 + 4, pStart + 6, 52, 128, 12, "V", black1, umber1);
      drawChevronBand(194, pStart + 6, 52, 128, 12, "V", umber1, black1);

      // Right panel
      ruledLine(1010, pStart, 1010, pEnd, umber1, 1.0);
      drawChevronBand(1200 - r3 + 4, pStart + 6, 52, 128, 12, "V", umber1, black1);
      drawChevronBand(1014, pStart + 6, 52, 128, 12, "V", black1, umber1);
    }
  }
  // Closing panel dividers at 950
  ruledLine(950, r2, 950, r3, black1, 1.2);
  ruledLine(950, 1200 - r3, 950, 1200 - r2, black1, 1.2);
  ruledLine(r2, 950, r3, 950, black1, 1.2);
  ruledLine(1200 - r3, 950, 1200 - r2, 950, black1, 1.2);

  // -------------------------------------------------------------------------
  // RING 3: INNER RULED CHEVRON & OPPOSING TRIANGLE BAND (250..312)
  // -------------------------------------------------------------------------
  let r4 = 266;
  let r5 = 312;

  // Burnt umber solid rubbed band between r3 (250) and r4 (266)
  stampedPoly([[r3, r3], [1200 - r3, r3], [1200 - r4, r4], [r4, r4]], umber1, 0, 3.0, 0.9);
  stampedPoly([[r4, 1200 - r4], [1200 - r4, 1200 - r4], [1200 - r3, 1200 - r3], [r3, 1200 - r3]], umber1, 0, 3.0, 0.9);
  stampedPoly([[r3, r3], [r4, r4], [r4, 1200 - r4], [r3, 1200 - r3]], umber2, 90, 3.0, 0.9);
  stampedPoly([[1200 - r4, r4], [1200 - r3, r3], [1200 - r3, 1200 - r3], [1200 - r4, 1200 - r4]], umber2, 90, 3.0, 0.9);

  ruledLine(r5, r5, 1200 - r5, r5, black1, 1.5);
  ruledLine(1200 - r5, r5, 1200 - r5, 1200 - r5, black1, 1.5);
  ruledLine(1200 - r5, 1200 - r5, r5, 1200 - r5, black1, 1.5);
  ruledLine(r5, 1200 - r5, r5, r5, black1, 1.5);

  // Interlocking opposing triangles inside Ring 3 (266..312)
  drawTriangleBand(r5, r4 + 4, 1200 - r5, r5 - 4, 16, -1, black1, umber1);
  drawTriangleBand(r5, 1200 - r5 + 4, 1200 - r5, 1200 - r4 - 4, 16, 1, black1, umber1);
  drawTriangleBand(r4 + 4, r5, r5 - 4, 1200 - r5, 16, -1, umber1, black1);
  drawTriangleBand(1200 - r5 + 4, r5, 1200 - r4 - 4, 1200 - r5, 16, 1, umber1, black1);

  // Corner 4-point stars in Ring 3
  let c3Centers = [
    [289, 289],
    [911, 289],
    [911, 911],
    [289, 911]
  ];
  for (let [cx, cy] of c3Centers) {
    stampedStar(cx, cy, 19, 7, 4, umber1, black1);
  }

  // -------------------------------------------------------------------------
  // INNER SANCTUM FIELD (312..888) — SYMMETRICAL ALTAR GRID BEHIND THE TIN
  // -------------------------------------------------------------------------
  let r6 = 328;
  ruledLine(r6, r6, 1200 - r6, r6, umber1, 1.1);
  ruledLine(1200 - r6, r6, 1200 - r6, 1200 - r6, umber1, 1.1);
  ruledLine(1200 - r6, 1200 - r6, r6, 1200 - r6, umber1, 1.1);
  ruledLine(r6, 1200 - r6, r6, r6, umber1, 1.1);

  // Ceremonial axes & diagonals crossing the inner sanctum
  ruledLine(r6, 600, 1200 - r6, 600, black2, 1.1);
  ruledLine(600, r6, 600, 1200 - r6, black2, 1.1);
  ruledLine(r6, r6, 1200 - r6, 1200 - r6, umber1, 0.95);
  ruledLine(1200 - r6, r6, r6, 1200 - r6, umber1, 0.95);

  // Four inner sanctum corner stars (partially glimpsed around the tin)
  let sanctumStars = [
    [390, 390],
    [810, 390],
    [810, 810],
    [390, 810]
  ];
  for (let [cx, cy] of sanctumStars) {
    stampedStar(cx, cy, 42, 14, 8, black1, umber1);
  }

  // Lateral chevron & triangle wings flanking the tin at Left (328..400), Right (800..872), Bottom (800..872)
  drawChevronBand(334, 455, 52, 290, 18, "V", umber1, black1);
  drawChevronBand(814, 455, 52, 290, 18, "V", black1, umber1);
  drawChevronBand(455, 814, 290, 52, 18, "H", umber1, black1);
  drawChevronBand(455, 334, 290, 52, 18, "H", black1, umber1);

  // Central ceremonial sunburst halo directly behind the tin (radius 255)
  let rayCount = 32;
  for (let i = 0; i < rayCount; i++) {
    let a0 = (i * 360) / rayCount;
    let aMid = ((i + 0.5) * 360) / rayCount;
    let a1 = ((i + 1) * 360) / rayCount;
    let rIn = 195;
    let rOut = 262;
    let pts = [
      [600 + cos(a0) * rIn, 600 + sin(a0) * rIn],
      [600 + cos(a1) * rIn, 600 + sin(a1) * rIn],
      [600 + cos(aMid) * rOut, 600 + sin(aMid) * rOut]
    ];
    stampedPoly(pts, i % 2 === 0 ? black1 : umber1, aMid, 3.2, 0.7);
  }
}

// ---------------------------------------------------------------------------
// RUBBED-ON INK EFFECT (FIBROUS BARK HIGHLIGHTS SCRAPING OVER STAMPED INK)
// ---------------------------------------------------------------------------
function drawRubbedInkOverpass() {
  brush.field("waves");
  brush.wiggle(1.8);
  let rubCols = ["#a88964", "#c2a783", "#8d673f", "#d6be9c"];

  // Lightly drag dry bark fibers across the stamped registers so ink looks hand-rubbed
  for (let i = 0; i < 420; i++) {
    let x = random(45, 1155);
    let y = random(45, 1155);
    // Concentrate on the outer ornament rings
    if (x > 360 && x < 840 && y > 360 && y < 840 && random() < 0.7) continue;

    let ang = random() < 0.5 ? random(-5, 5) : 90 + random(-5, 5);
    brush.set("bark_fiber", random(rubCols), random(0.45, 0.85));
    brush.flowLine(x, y, random(35, 110), ang);
  }
  brush.noField();
}

// ---------------------------------------------------------------------------
// HELPER: ROUNDED TRAPEZOID / RECTANGLE VERTEX GENERATOR
// ---------------------------------------------------------------------------
function getRoundedTrapPoints(xTopL, xTopR, yTop, xBotL, xBotR, yBot, rTop, rBot, steps = 7) {
  let pts = [];
  // Top-Left corner (180 to 270 deg)
  let tlCx = xTopL + rTop;
  let tlCy = yTop + rTop;
  for (let i = 0; i <= steps; i++) {
    let a = map(i, 0, steps, 180, 270);
    pts.push([tlCx + cos(a) * rTop, tlCy + sin(a) * rTop]);
  }
  // Top-Right corner (270 to 360 deg)
  let trCx = xTopR - rTop;
  let trCy = yTop + rTop;
  for (let i = 0; i <= steps; i++) {
    let a = map(i, 0, steps, 270, 360);
    pts.push([trCx + cos(a) * rTop, trCy + sin(a) * rTop]);
  }
  // Bottom-Right corner (0 to 90 deg)
  let brCx = xBotR - rBot;
  let brCy = yBot - rBot;
  for (let i = 0; i <= steps; i++) {
    let a = map(i, 0, steps, 0, 90);
    pts.push([brCx + cos(a) * rBot, brCy + sin(a) * rBot]);
  }
  // Bottom-Left corner (90 to 180 deg)
  let blCx = xBotL + rBot;
  let blCy = yBot - rBot;
  for (let i = 0; i <= steps; i++) {
    let a = map(i, 0, steps, 90, 180);
    pts.push([blCx + cos(a) * rBot, blCy + sin(a) * rBot]);
  }
  return pts;
}

// ---------------------------------------------------------------------------
// 3A. CAST SHADOWS ON THE BARK-CLOTH
// ---------------------------------------------------------------------------
function drawCastShadows() {
  brush.noStroke();
  brush.noHatch();

  // Soft twilight umber shadow beneath the main tin body
  let shadowOuter = getRoundedTrapPoints(365, 865, 430, 395, 855, 895, 48, 44, 6);
  let polyS1 = new brush.Polygon(shadowOuter);
  polyS1.fill("#1d1616", 95, 0.32, 0.65);

  let shadowMid = getRoundedTrapPoints(380, 845, 640, 392, 838, 882, 42, 40, 6);
  let polyS2 = new brush.Polygon(shadowMid);
  polyS2.fill("#140f10", 125, 0.22, 0.55);

  // Cast shadow of the curling lid & winding key to upper-right
  brush.fill("#1c1516", 85);
  brush.fillBleed(0.28, "out");
  brush.circle(845, 345, 78, 0.25);
  brush.circle(615, 355, 180, 0.2);
  brush.noFill();

  // Crisp contact shadow hatching directly under the tin base (y ~ 850..875)
  brush.hatchStyle("charcoal", "#120d0e", 1.1);
  brush.hatch(2.5, 12, { rand: 0.1 });
  let contactPts = getRoundedTrapPoints(385, 825, 830, 395, 820, 868, 25, 25, 5);
  let polyContact = new brush.Polygon(contactPts);
  polyContact.hatch(2.5, 12, { rand: 0.1 });
  brush.noHatch();
}

// ---------------------------------------------------------------------------
// 3B. FRONT METALLIC BODY OF THE TIN & LITHOGRAPHED LABEL BAND
// ---------------------------------------------------------------------------
function drawTinBodyAndLabel() {
  // The front metallic wall extends from the top rim (y = 385..655) down to the tapered base (y = 858)
  // Top rim outer bounds: x = 355..845, y = 385..655 (r = 46)
  // Base outer bounds: x = 382..818, y = 620..858 (r = 38)

  let bodyPts = getRoundedTrapPoints(355, 845, 590, 382, 818, 858, 42, 38, 8);
  let bodyPoly = new brush.Polygon(bodyPts);

  // Base metallic steel-umber wash
  bodyPoly.wash("#3a3f46", 235);
  bodyPoly.fill("#2b3038", 110, 0.08, 0.35);

  // Vertical cylindrical shading strips across the front face of the tin
  // Simulating hyperreal anisotropic brushed tinplate reflecting dusky twilight + warm bark cloth
  let numStrips = 88;
  for (let i = 0; i < numStrips; i++) {
    let t = i / (numStrips - 1);
    let xTop = lerp(357, 843, t);
    let xBot = lerp(383, 817, t);

    // Corner curve drop-off at bottom and top
    let cornerInset = 0;
    if (t < 0.09) cornerInset = map(t, 0, 0.09, 28, 0);
    else if (t > 0.91) cornerInset = map(t, 0.91, 1, 0, 28);

    let yStart = 640 - cornerInset * 0.6;
    let yEnd = 856 - cornerInset;

    // Determine metallic reflection tone based on horizontal position t
    let col;
    let w = 1.3;
    if (t < 0.06) {
      col = "#1e2329"; // Far left dark edge turn
    } else if (t < 0.13) {
      col = lerpColor(color("#6c7885"), color("#eef6fc"), map(t, 0.06, 0.13, 0, 1)); // Left corner specular buildup
      w = 1.6;
    } else if (t < 0.18) {
      col = lerpColor(color("#ffffff"), color("#7c8792"), map(t, 0.13, 0.18, 0, 1)); // Main left corner glint!
      w = 1.8;
    } else if (t < 0.38) {
      col = lerpColor(color("#5c554e"), color("#363a40"), map(t, 0.18, 0.38, 0, 1)); // Warm bark reflection into dark steel
    } else if (t < 0.56) {
      col = lerpColor(color("#363a40"), color("#7a7267"), map(t, 0.38, 0.56, 0, 1)); // Center soft warm sheen
    } else if (t < 0.78) {
      col = lerpColor(color("#7a7267"), color("#262b32"), map(t, 0.56, 0.78, 0, 1)); // Right-center dark core
    } else if (t < 0.88) {
      col = lerpColor(color("#38404a"), color("#d7e4ed"), map(t, 0.78, 0.88, 0, 1)); // Right corner secondary highlight!
      w = 1.6;
    } else if (t < 0.93) {
      col = lerpColor(color("#d7e4ed"), color("#4b535e"), map(t, 0.88, 0.93, 0, 1));
    } else {
      col = "#181c21"; // Far right shadow edge
    }

    brush.set("cpencil", col, w);
    brush.line(xTop, yStart, xBot, yEnd);
  }

  // -------------------------------------------------------------------------
  // LITHOGRAPHED CORNED BEEF LABEL BAND (DUSKY OXBLOOD CRIMSON, GOLD & NAVY)
  // -------------------------------------------------------------------------
  // Curved horizontal band following the front contour of the tin (y ~ 705 to 818)
  function drawTinBand(yT, yB, colHex, opacityVal = 210) {
    let tTop = map(yT, 600, 858, 0, 1);
    let tBot = map(yB, 600, 858, 0, 1);
    let xlT = lerp(356, 382, tTop);
    let xrT = lerp(844, 818, tTop);
    let xlB = lerp(356, 382, tBot);
    let xrB = lerp(844, 818, tBot);

    let pts = [];
    let steps = 24;
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let x = lerp(xlT, xrT, u);
      let curveY = sin(u * 180) * 14;
      pts.push([x, yT + curveY]);
    }
    for (let i = steps; i >= 0; i--) {
      let u = i / steps;
      let x = lerp(xlB, xrB, u);
      let curveY = sin(u * 180) * 14;
      pts.push([x, yB + curveY]);
    }
    let p = new brush.Polygon(pts);
    p.wash(colHex, opacityVal);
    return pts;
  }

  // Main oxblood crimson band
  drawTinBand(704, 814, "#681d20", 215);
  // Gold top & bottom litho borders
  drawTinBand(700, 707, "#b89148", 220);
  drawTinBand(811, 818, "#b89148", 220);

  // Central dark twilight-navy crest panel on the front of the tin
  let crestPts = [
    [515, 724],
    [685, 724],
    [678, 806],
    [522, 806]
  ];
  let crestPoly = new brush.Polygon(crestPts);
  crestPoly.wash("#1b222e", 225);
  crestPoly.draw("cpencil", "#c7a158", 1.3);

  // Subtle typographic / heraldic gold & buff markings inside the label (abstracted hyperreal glint)
  brush.set("cpencil", "#d8b872", 0.9);
  brush.line(538, 744, 662, 744);
  brush.set("metal_glint", "#e8d5a7", 1.1);
  for (let lx = 535; lx <= 655; lx += 15) {
    brush.line(lx, 760, lx + 9, 760);
    brush.line(lx + 2, 774, lx + 8, 774);
  }
  brush.set("cpencil", "#a8833e", 0.8);
  brush.line(548, 790, 652, 790);

  // Re-apply vertical cylinder specular glints & shadows OVER the painted label so it reads as metallic tin
  for (let i = 0; i < 65; i++) {
    let t = i / 64;
    let xTop = lerp(364, 836, t);
    let xBot = lerp(380, 820, t);
    let curveY = sin(t * 180) * 14;
    let y1 = 698 + curveY;
    let y2 = 820 + curveY;

    if (t > 0.10 && t < 0.19) {
      // Bright left specular reflection cutting across the crimson & gold paint
      let alphaCol = t < 0.145 ? "#ffffff" : "#d9e4ec";
      brush.set("metal_glint", alphaCol, random(0.8, 1.4));
      brush.line(xTop, y1, xBot, y2);
    } else if (t > 0.80 && t < 0.89) {
      // Secondary right corner specular glint
      brush.set("cpencil", "#c9d6e0", random(0.7, 1.1));
      brush.line(xTop, y1, xBot, y2);
    } else if (t < 0.08 || t > 0.91 || (t > 0.65 && t < 0.78)) {
      // Dark twilight shading on the cylinder turns
      brush.set("charcoal", "#171316", random(0.6, 1.0));
      brush.line(xTop, y1, xBot, y2);
    }
  }

  // -------------------------------------------------------------------------
  // EMBOSSED HORIZONTAL STRUCTURAL RIBS & TORN KEY-STRIP TRACK
  // -------------------------------------------------------------------------
  function drawEmbossedRib(yBase, shadowCol, highlightCol, wMul = 1.0) {
    let t = map(yBase, 600, 858, 0, 1);
    let xl = lerp(356, 382, t) + 6;
    let xr = lerp(844, 818, t) - 6;
    let sPts = [];
    let hPts = [];
    let steps = 20;
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let x = lerp(xl, xr, u);
      let cy = yBase + sin(u * 180) * 14;
      sPts.push([x, cy]);
      hPts.push([x, cy + 3.2]);
    }
    brush.set("cpencil", shadowCol, 1.2 * wMul);
    brush.spline(sPts, 0.3);
    brush.set("metal_glint", highlightCol, 1.1 * wMul);
    brush.spline(hPts, 0.3);
  }

  // Structural ribs above and below the label
  drawEmbossedRib(682, "#1a1e24", "#e6f0f7", 1.1);
  drawEmbossedRib(826, "#1a1e24", "#dce7ef", 1.1);
  drawEmbossedRib(840, "#181b20", "#eef7fc", 1.2);

  // Torn metal key-strip track at y ~ 664 (where the winding key tore open the seal)
  let trackY = 662;
  let stepsT = 36;
  for (let i = 0; i < stepsT; i++) {
    let u0 = i / stepsT;
    let u1 = (i + 1) / stepsT;
    let x0 = lerp(364, 836, u0);
    let x1 = lerp(364, 836, u1);
    let y0 = trackY + sin(u0 * 180) * 13;
    let y1 = trackY + sin(u1 * 180) * 13;

    // Dark recessed meat/shadow gap
    brush.set("rotring", "#1a0c0e", 1.6);
    brush.line(x0, y0, x1, y1);

    // Jagged sheared tinplate burrs above and below the tear track
    brush.set("metal_glint", i % 2 === 0 ? "#ffffff" : "#b8c7d4", random(0.8, 1.3));
    brush.line(x0, y0 - 2.5, x1, y1 - 2.0 + random(-1.5, 1.5));
    brush.line(x0, y0 + 2.8, x1, y1 + 2.5 + random(-1.5, 1.5));
  }

  // Bottom double-seamed base rim of the tin (y = 852..860)
  drawEmbossedRib(851, "#121519", "#f0f7fc", 1.35);
}

// ---------------------------------------------------------------------------
// 3C. TOP DOUBLE-SEAMED TINPLATE RIM & INNER CAVITY
// ---------------------------------------------------------------------------
function drawTinTopRimAndCavity() {
  // Outer rim of the top face: x = 350..850, y = 380..656, corner radius = 48
  let outerRimPts = getRoundedTrapPoints(350, 850, 380, 354, 846, 656, 48, 46, 10);
  let outerRimPoly = new brush.Polygon(outerRimPts);

  // Metallic base wash of the top rim
  outerRimPoly.wash("#8a96a1", 240);

  // Bevel ring 1 (recessed channel inside outer rolled seam)
  let midRimPts = getRoundedTrapPoints(360, 840, 390, 364, 836, 646, 40, 38, 10);
  let midRimPoly = new brush.Polygon(midRimPts);
  midRimPoly.wash("#424952", 230);

  // Bevel ring 2 (inner lip shelf before sheared opening)
  let innerLipPts = getRoundedTrapPoints(369, 831, 399, 373, 827, 637, 34, 32, 10);
  let innerLipPoly = new brush.Polygon(innerLipPts);
  innerLipPoly.wash("#adb9c4", 235);

  // Dark deep cavity of the open tin (where the meat sits)
  let cavityPts = getRoundedTrapPoints(377, 823, 407, 381, 819, 629, 28, 27, 10);
  let cavityPoly = new brush.Polygon(cavityPts);
  cavityPoly.wash("#210d10", 250);

  // Directional metallic shading and brilliant specular glints around the top rim bevels
  let rimCount = outerRimPts.length;
  for (let i = 0; i < rimCount; i++) {
    let pOut = outerRimPts[i];
    let pMid = midRimPts[i];
    let pIn = innerLipPts[i];
    let pCav = cavityPts[i];

    // Angle around center (600, 518)
    let ang = atan2(pOut[1] - 518, pOut[0] - 600);
    // Bright specular zones at top-left (-145 deg) and bottom-right (+35 deg)
    let spec1 = cos((ang + 140) * 2);
    let spec2 = cos((ang - 35) * 2);
    let spec = max(spec1, spec2);

    let rimCol;
    if (spec > 0.65) {
      rimCol = "#ffffff";
    } else if (spec > 0.2) {
      rimCol = "#d4e0e8";
    } else if (spec > -0.3) {
      rimCol = "#6e7882";
    } else {
      rimCol = "#2b3138";
    }

    brush.set("metal_glint", rimCol, 1.3);
    brush.line(pOut[0], pOut[1], pMid[0], pMid[1]);

    // Inner bevel contrast
    let inCol = spec > 0.3 ? "#2b3138" : "#c5d2dc";
    brush.set("cpencil", inCol, 1.1);
    brush.line(pMid[0], pMid[1], pIn[0], pIn[1]);

    // Sheared inner cut edge (gleaming white-silver wire burr)
    brush.set("metal_glint", spec > -0.2 ? "#ffffff" : "#9aa6b0", 1.15);
    brush.line(pIn[0], pIn[1], pCav[0], pCav[1]);
  }

  // Outer contour & razor-sharp specular highlights along the rolled rim crown
  outerRimPoly.draw("rotring", "#1a1f24", 1.2);
  midRimPoly.draw("rotring", "#252b32", 0.9);
  cavityPoly.draw("metal_glint", "#f2f8fc", 1.15);

  // Extra pure white specular streaks along front-left and front-right rounded corners of the rim
  brush.set("metal_glint", "#ffffff", 1.7);
  brush.line(398, 651, 535, 653);
  brush.line(710, 652, 804, 650);
  brush.line(354, 435, 356, 560);
  brush.line(844, 445, 842, 575);
}

// ---------------------------------------------------------------------------
// 3D. MARBLED PINK MEAT & WAXY FAT SHEEN
// ---------------------------------------------------------------------------
function drawCornedBeefAndWaxyFat() {
  // The loaf of corned beef sits inside cavity (377..823, 407..629), slightly pulled away from the tin walls
  let meatBasePts = getRoundedTrapPoints(385, 815, 415, 389, 811, 621, 24, 23, 9);
  let meatBasePoly = new brush.Polygon(meatBasePts);

  // Base cured beef wash & mass
  meatBasePoly.wash("#7d3339", 245);
  meatBasePoly.fill("#662329", 140, 0.12, 0.55);

  // Clip or constrain all internal meat marbling within the meat loaf boundary
  // Interlocking coarse-ground cured brisket muscle bundles
  let meatColors = [
    "#5c1d23", // deep cured claret shadow
    "#732a31", // rich oxblood meat
    "#8f3b42", // mid cured beef
    "#a84e54", // dusky rose corned beef
    "#bf656b", // marbled pink meat
    "#cf797e", // lighter pink muscle fiber
    "#823539"  // warm terracotta-rose
  ];

  // Generate 42 organic muscle-bundle patches across the loaf surface
  for (let i = 0; i < 42; i++) {
    let cx = random(408, 792);
    let cy = random(432, 604);
    let rx = random(24, 58);
    let ry = random(16, 38);
    let col = random(meatColors);

    let bPts = [];
    let vCount = 10;
    for (let v = 0; v < vCount; v++) {
      let a = (v * 360) / vCount;
      let n = noise(cx * 0.02 + cos(a), cy * 0.02 + sin(a));
      let rMod = map(n, 0, 1, 0.65, 1.25);
      let px = constrain(cx + cos(a) * rx * rMod, 389, 811);
      let py = constrain(cy + sin(a) * ry * rMod, 418, 618);
      bPts.push([px, py]);
    }

    let bPoly = new brush.Polygon(bPts);
    bPoly.fill(col, random(95, 165), 0.15, 0.5);

    // Directional shredded brisket fibers inside each muscle bundle
    let fiberAng = random(-35, 35) + (cy > 520 ? 10 : -10);
    brush.noStroke();
    brush.hatchStyle("cpencil", random(["#4d161b", "#b85c62", "#d98287", "#6e252c"]), random(0.7, 1.1));
    brush.hatch(random(2.4, 3.8), fiberAng, { rand: 0.22 });
    bPoly.hatch(random(2.4, 3.8), fiberAng, { rand: 0.22 });
    brush.noHatch();
  }

  // Fine fibrous meat grain strokes across the entire loaf
  brush.field("curved");
  brush.wiggle(2.5);
  for (let i = 0; i < 380; i++) {
    let fx = random(394, 806);
    let fy = random(422, 612);
    let fLen = random(14, 38);
    let fAng = random(-28, 28);
    let fCol = random(["#4a1419", "#692228", "#9e464c", "#c4686e", "#de8b90", "#b0565b"]);
    brush.set("cpencil", fCol, random(0.55, 1.05));
    brush.flowLine(fx, fy, fLen, fAng);
  }
  brush.noField();

  // -------------------------------------------------------------------------
  // EMBOSSED LID PRESSURE-INDENTATION RING ON THE MEAT SURFACE
  // -------------------------------------------------------------------------
  // Classic rectangular mold-mark pressed into the top of canned corned beef
  let indentOuter = getRoundedTrapPoints(438, 762, 450, 442, 758, 586, 18, 18, 6);
  let indentInner = getRoundedTrapPoints(482, 718, 476, 485, 715, 560, 12, 12, 6);

  let polyIndOut = new brush.Polygon(indentOuter);
  let polyIndIn = new brush.Polygon(indentInner);

  // Dark crevice groove & bright wet bevel along the mold mark
  polyIndOut.draw("charcoal", "#471419", 1.25);
  polyIndIn.draw("charcoal", "#471419", 1.1);

  // -------------------------------------------------------------------------
  // WAXY TALLOW FAT DEPOSITS, VEINS & CORNER ACCUMULATIONS
  // -------------------------------------------------------------------------
  // Helper to draw a realistic layered waxy fat pocket (translucent edge -> cream core -> ivory sheen)
  function drawFatPocket(cx, cy, rx, ry, rotAng = 0) {
    let outerPts = [];
    let midPts = [];
    let corePts = [];
    let steps = 12;
    for (let i = 0; i < steps; i++) {
      let a = (i * 360) / steps;
      let n = noise(cx * 0.03 + cos(a) * 1.5, cy * 0.03 + sin(a) * 1.5);
      let rScale = map(n, 0, 1, 0.55, 1.3);
      let dx = cos(a) * rx * rScale;
      let dy = sin(a) * ry * rScale;
      // Rotate
      let rdx = dx * cos(rotAng) - dy * sin(rotAng);
      let rdy = dx * sin(rotAng) + dy * cos(rotAng);

      let ox = constrain(cx + rdx, 387, 813);
      let oy = constrain(cy + rdy, 417, 619);
      let mx = constrain(cx + rdx * 0.72, 389, 811);
      let my = constrain(cy + rdy * 0.72, 419, 617);
      let ix = constrain(cx + rdx * 0.42, 391, 809);
      let iy = constrain(cy + rdy * 0.42, 421, 615);

      outerPts.push([ox, oy]);
      midPts.push([mx, my]);
      corePts.push([ix, iy]);
    }

    // 1. Translucent pink-amber waxy transition
    let pOut = new brush.Polygon(outerPts);
    pOut.wash("#cfa394", 150);

    // 2. Warm creamy tallow mass
    let pMid = new brush.Polygon(midPts);
    pMid.wash("#e3d2b4", 210);
    brush.noStroke();
    brush.hatchStyle("waxy_fat", "#ebe0c7", 0.9);
    brush.hatch(2.2, rotAng + 20, { rand: 0.1 });
    pMid.hatch(2.2, rotAng + 20, { rand: 0.1 });
    brush.noHatch();

    // 3. Ivory waxy specular core
    let pCore = new brush.Polygon(corePts);
    pCore.wash("#f7f0df", 230);
    pCore.draw("metal_glint", "#ffffff", 0.85);
  }

  // Characteristic corner & edge fat accumulations (where tallow solidifies against the tin)
  drawFatPocket(412, 434, 28, 16, -25);
  drawFatPocket(786, 436, 32, 18, 22);
  drawFatPocket(784, 598, 34, 19, -18);
  drawFatPocket(416, 596, 30, 17, 25);
  drawFatPocket(595, 424, 36, 11, 4);
  drawFatPocket(625, 610, 38, 12, -3);
  drawFatPocket(396, 515, 14, 32, 85);
  drawFatPocket(802, 520, 15, 30, -80);

  // Internal marbled fat pockets & veins across the pink meat
  let fatPockets = [
    [468, 488, 22, 11, 15],
    [535, 462, 18, 9, -12],
    [665, 474, 25, 12, 20],
    [728, 525, 20, 11, -28],
    [642, 548, 26, 13, 10],
    [515, 558, 23, 12, -16],
    [578, 514, 19, 10, 32],
    [452, 545, 16, 9, -8],
    [695, 574, 21, 10, 14],
    [558, 588, 18, 8, -5]
  ];
  for (let [fx, fy, frx, fry, fang] of fatPockets) {
    drawFatPocket(fx, fy, frx, fry, fang);
  }

  // Fine branching veins of waxy white/cream fat marbling the meat bundles
  for (let i = 0; i < 95; i++) {
    let x1 = random(395, 805);
    let y1 = random(422, 612);
    let vPts = [[x1, y1]];
    let cx = x1;
    let cy = y1;
    let ang = random(360);
    let segs = int(random(3, 6));
    for (let s = 0; s < segs; s++) {
      ang += random(-45, 45);
      cx = constrain(cx + cos(ang) * random(8, 18), 392, 808);
      cy = constrain(cy + sin(ang) * random(6, 14), 420, 614);
      vPts.push([cx, cy]);
    }
    brush.set("waxy_fat", random(["#e6d7bc", "#f2e8d5", "#d4be9e"]), random(0.65, 1.15));
    brush.spline(vPts, 0.45);
  }

  // -------------------------------------------------------------------------
  // WET GELATINOUS & WAXY SPECULAR SHEEN GLINTS ON THE MEAT
  // -------------------------------------------------------------------------
  // Micro-highlights along the pressure ridges and fat margins
  for (let i = 0; i < 110; i++) {
    let gx = random(398, 802);
    let gy = random(425, 610);
    let gLen = random(4, 14);
    let gAng = random(-20, 20);
    let gCol = random() < 0.6 ? "#ffffff" : "#fae3e6";
    brush.set("metal_glint", gCol, random(0.6, 1.15));
    brush.line(gx, gy, gx + cos(gAng) * gLen, gy + sin(gAng) * gLen);
  }

  // Specular highlights tracing the rectangular mold-mark bevels
  brush.set("metal_glint", "#ffeef0", 1.1);
  brush.line(455, 452, 745, 452);
  brush.line(458, 588, 742, 588);
  brush.line(495, 478, 705, 478);
  brush.line(498, 562, 702, 562);

  // Deep shadow recess around the outer perimeter of the meat loaf inside the tin wall
  meatBasePoly.draw("charcoal", "#1f090c", 1.35);
}

// ---------------------------------------------------------------------------
// 3E. THE CURLING PEELED METAL LID (DRAMATIC 3D METALLIC SCROLL)
// ---------------------------------------------------------------------------
function drawPeeledCurlingLid() {
  // The tinplate lid is still hinged along the back-left/top rim (y ~ 382)
  // and curls upward and forward in a gleaming three-dimensional scroll (y: 175..385)

  // 1. UNDERSIDE OF THE PEELED LID (arching up from y = 382 to y = 185)
  let lidUnderPts = getRoundedTrapPoints(378, 775, 182, 368, 795, 384, 38, 22, 8);
  let lidUnderPoly = new brush.Polygon(lidUnderPts);
  lidUnderPoly.wash("#4a525c", 242);

  // Horizontal cylinder shading across the arched underside of the lid
  // Reflecting the pink meat below, the warm bark cloth, and the cool twilight sky
  let lidRows = 68;
  for (let r = 0; r < lidRows; r++) {
    let t = r / (lidRows - 1);
    let y = lerp(185, 382, t);

    // Taper & rounded corner inset at top
    let xL = lerp(380, 370, t);
    let xR = lerp(773, 793, t);
    if (t < 0.16) {
      let cIn = map(t, 0, 0.16, 34, 0);
      xL += cIn;
      xR -= cIn;
    }

    // Subtle upward arch curve across the lid width
    let col;
    let w = 1.35;
    if (t < 0.10) {
      // Top over-curl shadow before the crest highlight
      col = lerpColor(color("#1d2229"), color("#7a8794"), t / 0.10);
    } else if (t < 0.22) {
      // Brilliant horizontal specular band along the upper curve!
      col = lerpColor(color("#dce8f0"), color("#ffffff"), map(t, 0.10, 0.22, 0, 1));
      w = 1.75;
    } else if (t < 0.34) {
      col = lerpColor(color("#ffffff"), color("#545d68"), map(t, 0.22, 0.34, 0, 1));
    } else if (t < 0.56) {
      // Mid-underside reflecting the warm rose-pink meat & raw sienna bark cloth!
      col = lerpColor(color("#483b3e"), color("#8f5659"), sin(map(t, 0.34, 0.56, 0, 180)));
    } else if (t < 0.76) {
      // Secondary metallic reflection band
      col = lerpColor(color("#3a424b"), color("#c8d6e0"), sin(map(t, 0.56, 0.76, 0, 180)));
      w = 1.5;
    } else {
      // Deep shadow crease near the hinge at the back rim of the tin
      col = lerpColor(color("#4a525c"), color("#161a20"), map(t, 0.76, 1, 0, 1));
    }

    let rowPts = [];
    let steps = 16;
    for (let s = 0; s <= steps; s++) {
      let u = s / steps;
      let px = lerp(xL, xR, u);
      let py = y - sin(u * 180) * 12;
      rowPts.push([px, py]);
    }
    brush.set("cpencil", col, w);
    brush.spline(rowPts, 0.35);
  }

  // Stamped concentric stiffening rings on the underside of the lid
  let ringRadii = [
    [435, 720, 228, 345],
    [475, 680, 248, 325],
    [515, 640, 266, 307]
  ];
  for (let [rxL, rxR, ryT, ryB] of ringRadii) {
    let rPts = getRoundedTrapPoints(rxL, rxR, ryT, rxL - 4, rxR + 4, ryB, 16, 16, 6);
    let rPoly = new brush.Polygon(rPts);
    rPoly.draw("rotring", "#232830", 1.0);
    let rPtsHi = getRoundedTrapPoints(rxL + 2, rxR - 2, ryT + 3, rxL - 2, rxR + 2, ryB + 3, 15, 15, 6);
    let rPolyHi = new brush.Polygon(rPtsHi);
    rPolyHi.draw("metal_glint", "#e6f0f7", 0.95);
  }

  // Waxy cream fat & gelatin patches clinging to the underside of the peeled lid!
  let lidFatSpots = [
    [455, 295, 24, 11, -12],
    [675, 310, 28, 13, 15],
    [565, 268, 22, 9, 5],
    [510, 338, 19, 8, -8],
    [635, 255, 18, 8, 18]
  ];
  for (let [fx, fy, frx, fry, fang] of lidFatSpots) {
    let fPts = [];
    for (let i = 0; i < 10; i++) {
      let a = (i * 360) / 10;
      let rMod = random(0.75, 1.25);
      fPts.push([fx + cos(a + fang) * frx * rMod, fy + sin(a + fang) * fry * rMod]);
    }
    let fPoly = new brush.Polygon(fPts);
    fPoly.wash("#dfd0b4", 185);
    fPoly.draw("waxy_fat", "#f7f0df", 0.9);
    brush.set("metal_glint", "#ffffff", 0.75);
    brush.line(fx - frx * 0.4, fy, fx + frx * 0.4, fy - 2);
  }

  // 2. THE ROLLED OVER-CURL AT THE TOP OF THE LID (y = 172..248)
  // The top edge of the lid curls forward toward the viewer like a cylinder
  let curlTopPts = [];
  let curlSteps = 24;
  for (let i = 0; i <= curlSteps; i++) {
    let u = i / curlSteps;
    let x = lerp(384, 770, u);
    let archY = 176 - sin(u * 180) * 14;
    curlTopPts.push([x, archY]);
  }
  for (let i = curlSteps; i >= 0; i--) {
    let u = i / curlSteps;
    let x = lerp(376, 778, u);
    let lipY = 238 - sin(u * 180) * 10;
    curlTopPts.push([x, lipY]);
  }
