// Oblique top-down 3D-to-2D projection from phone-space (x, y, z) to canvas [cx, cy]
function P(x, y, z = 0) {
  const ang = -15.5;
  const c = Math.cos((ang * Math.PI) / 180);
  const s = Math.sin((ang * Math.PI) / 180);
  const rx = x * c - y * s;
  const ry = x * s + y * c;
  // Subtle perspective foreshortening (camera slightly below looking up-down)
  const persp = 1.0 / (1.0 - ry * 0.00016);
  const tilt = 0.91;
  const cx = 608 + rx * 0.96 * persp - z * 0.26;
  const cy = 612 + ry * tilt * 0.96 * persp - z * 0.82;
  return [cx, cy];
}

// Clip a 2D polygon against the positive half-plane on the left side of directed line A -> B
function clipHalfPlane(poly, ax, ay, bx, by) {
  if (!poly || poly.length < 3) return [];
  const out = [];
  const dx = bx - ax;
  const dy = by - ay;
  const inside = (p) => dx * (p[1] - ay) - dy * (p[0] - ax) >= -1e-5;
  const intersect = (p1, p2) => {
    const rx = p2[0] - p1[0];
    const ry = p2[1] - p1[1];
    const denom = dx * ry - dy * rx;
    if (Math.abs(denom) < 1e-9) return p1;
    const t = (dx * (ay - p1[1]) - dy * (ax - p1[0])) / denom;
    return [p1[0] + t * rx, p1[1] + t * ry];
  };
  for (let i = 0; i < poly.length; i++) {
    const cur = poly[i];
    const prev = poly[(i + poly.length - 1) % poly.length];
    const curIn = inside(cur);
    const prevIn = inside(prev);
    if (curIn) {
      if (!prevIn) out.push(intersect(prev, cur));
      out.push(cur);
    } else if (prevIn) {
      out.push(intersect(prev, cur));
    }
  }
  return out;
}

// Clip arbitrary polygon `subject` against convex polygon `clipPoly` (CCW winding)
function clipPolyToConvex(subject, clipPoly) {
  let res = subject;
  for (let i = 0; i < clipPoly.length; i++) {
    if (res.length < 3) return [];
    const a = clipPoly[i];
    const b = clipPoly[(i + 1) % clipPoly.length];
    res = clipHalfPlane(res, a[0], a[1], b[0], b[1]);
  }
  return res;
}

// Clip a 2D line segment [p1, p2] against a convex polygon
function clipSegmentToConvex(p1, p2, clipPoly) {
  let t0 = 0;
  let t1 = 1;
  const dx = p2[0] - p1[0];
  const dy = p2[1] - p1[1];
  for (let i = 0; i < clipPoly.length; i++) {
    const a = clipPoly[i];
    const b = clipPoly[(i + 1) % clipPoly.length];
    const ex = b[0] - a[0];
    const ey = b[1] - a[1];
    // Inward normal for CCW polygon is (-ey, ex)
    const nx = -ey;
    const ny = ex;
    const num = nx * (p1[0] - a[0]) + ny * (p1[1] - a[1]);
    const den = nx * dx + ny * dy;
    if (Math.abs(den) < 1e-9) {
      if (num < 0) return null;
    } else {
      const t = -num / den;
      if (den < 0) {
        if (t < t1) t1 = t;
      } else {
        if (t > t0) t0 = t;
      }
      if (t0 > t1) return null;
    }
  }
  return [
    [p1[0] + t0 * dx, p1[1] + t0 * dy],
    [p1[0] + t1 * dx, p1[1] + t1 * dy]
  ];
}

// Build a rounded rectangle polygon in CCW order
function makeRoundedRect(w, h, r, segs = 5) {
  const pts = [];
  const corners = [
    { cx: w - r, cy: h - r, a0: 0, a1: 90 },
    { cx: -w + r, cy: h - r, a0: 90, a1: 180 },
    { cx: -w + r, cy: -h + r, a0: 180, a1: 270 },
    { cx: w - r, cy: -h + r, a0: 270, a1: 360 }
  ];
  for (const c of corners) {
    for (let i = 0; i <= segs; i++) {
      if (i === 0 && pts.length > 0) continue;
      const a = ((c.a0 + ((c.a1 - c.a0) * i) / segs) * Math.PI) / 180;
      pts.push([c.cx + Math.cos(a) * r, c.cy + Math.sin(a) * r]);
    }
  }
  return pts;
}

// Helper to draw a projected 2D polygon using brush.beginShape
function drawProjectedPoly(pts, z = 0, shiftX = 0, shiftY = 0, curvature = 0.02) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    const [cx, cy] = P(pts[i][0] + shiftX, pts[i][1] + shiftY, z);
    brush.vertex(cx, cy);
  }
  brush.endShape(true);
}

function polygonArea(pts) {
  if (!pts || pts.length < 3) return 0;
  let a = 0;
  for (let i = 0; i < pts.length; i++) {
    const p1 = pts[i];
    const p2 = pts[(i + 1) % pts.length];
    a += p1[0] * p2[1] - p2[0] * p1[1];
  }
  return Math.abs(a) * 0.5;
}

function polygonCentroid(pts) {
  let sx = 0, sy = 0;
  for (const p of pts) {
    sx += p[0];
    sy += p[1];
  }
  return [sx / pts.length, sy / pts.length];
}

