  // =========================================================================
  // Impact point near bottom-right where phone struck ground
  const IMP = { x: 182, y: 332 };

  // 20 primary radial fracture angles from IMP covering all 360 degrees
  const baseAngles = [
    -168, -153, -139, -126, -114, -101, -87, -71, -52, -28,
    4, 38, 68, 95, 118, 138, 154, 169, 181, 192
  ];
  const numRays = baseAngles.length;
  const ringRadii = [0, 26, 58, 98, 148, 212, 290, 385, 500, 640, 820, 1080];
  const numRings = ringRadii.length - 1;

  // Precompute jittered vertices along each ray at each ring radius
  const gridPts = [];
  for (let i = 0; i < numRays; i++) {
    const rayPts = [];
    const baseA = baseAngles[i];
    for (let k = 0; k <= numRings; k++) {
      if (k === 0) {
        rayPts.push([IMP.x, IMP.y]);
      } else {
        const r = ringRadii[k] * (1 + (noise(i * 0.7, k * 0.5) - 0.5) * 0.14);
        const a = ((baseA + (noise(i * 1.3, k * 0.4) - 0.5) * 4.5) * Math.PI) / 180;
        rayPts.push([IMP.x + Math.cos(a) * r, IMP.y + Math.sin(a) * r]);
      }
    }
    gridPts.push(rayPts);
  }

  const shards = [];
  const crackSegments = [];

  for (let i = 0; i < numRays; i++) {
    const ni = (i + 1) % numRays;
    // Sector-coherent shift + individual shard jitter so adjacent sectors step visibly
    const sectorAng = ((baseAngles[i] + 15) * Math.PI) / 180;
    const sectorShiftX = Math.cos(sectorAng) * 5.5 + (i % 3 - 1) * 3.8;
    const sectorShiftY = Math.sin(sectorAng) * 5.5 + ((i + 1) % 3 - 1) * 3.8;

    for (let k = 0; k < numRings; k++) {
      const p00 = gridPts[i][k];
      const p10 = gridPts[ni][k];
      const p11 = gridPts[ni][k + 1];
      const p01 = gridPts[i][k + 1];

      // Build convex cell in CCW order
      let cell = k === 0 ? [p00, p01, p11] : [p00, p01, p11, p10];
      // Ensure CCW winding
      const signedA =
        (cell[1][0] - cell[0][0]) * (cell[2][1] - cell[0][1]) -
        (cell[1][1] - cell[0][1]) * (cell[2][0] - cell[0][0]);
      if (signedA < 0) cell.reverse();

      const clipped = clipPolyToConvex(screenPoly, cell);
      if (clipped.length >= 3 && polygonArea(clipped) > 18) {
        // Subdivide large outer cells with a secondary bifurcation crack
        if (k >= 5 && (i + k) % 2 === 0 && polygonArea(clipped) > 3800) {
          const midIn = [(p00[0] + p10[0]) * 0.5, (p00[1] + p10[1]) * 0.5];
          const midOut = [
            p01[0] * 0.44 + p11[0] * 0.56,
            p01[1] * 0.44 + p11[1] * 0.56
          ];
          const subA = clipHalfPlane(clipped, midIn[0], midIn[1], midOut[0], midOut[1]);
          const subB = clipHalfPlane(clipped, midOut[0], midOut[1], midIn[0], midIn[1]);
          const subList = [subA, subB];
          for (let sIdx = 0; sIdx < 2; sIdx++) {
            const sp = subList[sIdx];
            if (sp.length >= 3 && polygonArea(sp) > 15) {
              const distFactor = map(k, 0, numRings, 1.35, 0.55);
              shards.push({
                poly: sp,
                ring: k,
                ray: i,
                dx: (sectorShiftX + random(-3.2, 3.2) + (sIdx - 0.5) * 3.0) * distFactor,
                dy: (sectorShiftY + random(-3.2, 3.2) - (sIdx - 0.5) * 2.6) * distFactor,
                tilt: random(-1, 1)
              });
            }
          }
          const seg = clipSegmentToConvex(midIn, midOut, screenPoly);
          if (seg) crackSegments.push({ p1: seg[0], p2: seg[1], weight: 0.72, ring: k, isRadial: true });
        } else {
          const distFactor = map(k, 0, numRings, 1.4, 0.55);
          shards.push({
            poly: clipped,
            ring: k,
            ray: i,
            dx: (sectorShiftX + random(-3.0, 3.0)) * distFactor,
            dy: (sectorShiftY + random(-3.0, 3.0)) * distFactor,
            tilt: random(-1, 1)
          });
        }

        // Collect radial and ring crack segments inside screenPoly
        const radSeg = clipSegmentToConvex(p00, p01, screenPoly);
        if (radSeg) {
          crackSegments.push({
            p1: radSeg[0],
            p2: radSeg[1],
            weight: map(k, 0, numRings, 1.35, 0.85),
            ring: k,
            isRadial: true
          });
        }
        if (k > 0) {
          const ringSeg = clipSegmentToConvex(p00, p10, screenPoly);
          if (ringSeg) {
            crackSegments.push({
              p1: ringSeg[0],
              p2: ringSeg[1],
              weight: map(k, 1, numRings, 1.15, 0.65),
              ring: k,
              isRadial: false
            });
          }
        }
      }
    }
  }

  // =========================================================================
  // 4. HYPERREAL LOCK-SCREEN WATERCOLOUR PHOTO: CHILD AT THE BEACH
