    { col: "#252f42", op: 155, bleed: 0.18, poly: [[-62, 228], [14, 228], [28, 355], [-78, 362]] },
    { col: "#4e3e4a", op: 135, bleed: 0.20, poly: [[-48, 232], [6, 232], [12, 325], [-58, 330]] },
