    { col: "#546e8c", op: 145, bleed: 0.10, poly: [[-28, 45], [18, 46], [15, 126], [-22, 126]] }, // shaded right side of back
    { col: "#f7c4a3", op: 175, bleed: 0.09, poly: [[-65, 42], [-42, 42], [-44, 122], [-60, 122]] }, // sunlit left edge
    // Left arm reaching out toward the surf + small coral beach bucket
    { col: "#cf826c", op: 185, bleed: 0.07, poly: [[-96, 86], [-58, 52], [-52, 68], [-88, 98]] },
    { col: "#c95b52", op: 195, bleed: 0.08, poly: [[-116, 98], [-82, 96], [-86, 134], [-112, 134]] }, // small coral bucket
