  brush.noFill();

  // =========================================================================
  // 5. FINE PENCIL & MARKER DETAILS IN THE PHOTO (CLIPPED & SHIFTED BY SHARDS)
  // =========================================================================
  // Build crisp linear details in photo-space: horizon line, wave ripples, shirt stripes,
  // bucket handle, water sparkles, and the glowing lock-screen clock ("07:14")
  const photoLines = [];

  // Horizon line & distant wave crests
  photoLines.push({ p1: [-260, -3], p2: [260, -5], br: "cpencil", col: "#10233b", w: 0.9 });
  photoLines.push({ p1: [-240, -6], p2: [120, -7], br: "pen", col: "#fce0bf", w: 0.65 });

  // Shimmering water ripples & foam lines
  const waveY = [14, 28, 46, 68, 92, 116, 134, 150, 175, 208, 232, 275];
  for (let wy of waveY) {
    for (let wx = -230; wx < 210; wx += random(45, 85)) {
      const len = random(28, 68);
      const col =
        wy < 95
          ? wx > -135 && wx < 45
            ? "#fce2c4"
            : "#6ca0bf"
          : wy < 160
          ? "#eef4f8"
          : "#8aa8bf";
      photoLines.push({
        p1: [wx, wy + random(-2, 2)],
        p2: [wx + len, wy + random(-2, 2)],
        br: "cpencil",
        col: col,
        w: wy > 110 && wy < 160 ? 1.05 : 0.65
      });
    }
  }

  // Child's coastal striped shirt details, hat weave, and silhouette rim light
  for (let sy = 52; sy <= 118; sy += 11) {
    photoLines.push({ p1: [-58, sy], p2: [14, sy + 2], br: "cpencil", col: "#2c4361", w: 0.75 });
  }
  // Sunlit rim contour on child's hat, shoulder, arm, and bucket
  photoLines.push({ p1: [-78, 8], p2: [-54, -22], br: "pen", col: "#fff0d6", w: 0.85 });
  photoLines.push({ p1: [-54, -22], p2: [10, -20], br: "pen", col: "#fff0d6", w: 0.8 });
  photoLines.push({ p1: [-64, 42], p2: [-58, 124], br: "pen", col: "#ffe5c4", w: 0.85 });
  photoLines.push({ p1: [-96, 86], p2: [-58, 52], br: "pen", col: "#ffdcb8", w: 0.75 });
  photoLines.push({ p1: [-116, 98], p2: [-98, 78], br: "rotring", col: "#f5e3d3", w: 0.55 }); // bucket handle
  photoLines.push({ p1: [-98, 78], p2: [-82, 96], br: "rotring", col: "#f5e3d3", w: 0.55 });

  // Lock-screen clock ("07:42") & UI elements in screen coordinates (sliced by shards!)
  const addGlyphStroke = (x1, y1, x2, y2, w = 1.45, col = "#f5ece4") => {
    photoLines.push({ p1: [x1, y1], p2: [x2, y2], br: "marker", col, w });
    photoLines.push({ p1: [x1, y1], p2: [x2, y2], br: "pen", col: "#ffffff", w: w * 0.45 });
  };
  // Digit '0' (x: -118..-78, y: -365..-285)
  addGlyphStroke(-114, -362, -82, -362);
  addGlyphStroke(-82, -362, -82, -288);
  addGlyphStroke(-82, -288, -114, -288);
  addGlyphStroke(-114, -288, -114, -362);
  // Digit '7' (x: -62..-24, y: -362..-288)
  addGlyphStroke(-64, -362, -22, -362);
  addGlyphStroke(-22, -362, -46, -288);
  // Colon ':'
  addGlyphStroke(-2, -338, -2, -332, 1.6);
  addGlyphStroke(-2, -310, -2, -304, 1.6);
  // Digit '4' (x: 18..58, y: -362..-288)
  addGlyphStroke(46, -362, 16, -316);
  addGlyphStroke(16, -316, 58, -316);
  addGlyphStroke(46, -362, 46, -288);
  // Digit '2' (x: 74..114, y: -362..-288)
  addGlyphStroke(74, -356, 110, -362);
  addGlyphStroke(110, -362, 112, -328);
  addGlyphStroke(112, -328, 74, -288);
  addGlyphStroke(74, -288, 114, -288);

  // Small date line above clock & bottom home bar
  addGlyphStroke(-58, -388, 58, -388, 0.65, "#dfd7cf");
  addGlyphStroke(-72, 456, 72, 456, 1.35, "#e6dfd8");
  // Status bar battery & signal icons
  addGlyphStroke(175, -452, 205, -452, 0.8, "#e6dfd8");
  addGlyphStroke(-200, -452, -172, -452, 0.8, "#e6dfd8");

  // Draw all photo lines clipped to each shard and shifted by (s.dx, s.dy)
  for (const pl of photoLines) {
    brush.set(pl.br, pl.col, pl.w);
    for (const s of shards) {
      const seg = clipSegmentToConvex(pl.p1, pl.p2, s.poly);
      if (seg) {
        const [c1x, c1y] = P(seg[0][0] + s.dx, seg[0][1] + s.dy, 22);
        const [c2x, c2y] = P(seg[1][0] + s.dx, seg[1][1] + s.dy, 22);
        brush.line(c1x, c1y, c2x, c2y);
