    }
  }

  // =========================================================================
  // 6. TILTED SHARD GLASS GLARE & FINGERPRINT SMEARS ON THE SCREEN
  // =========================================================================
  // Subtle differential twilight sky reflection on individual tilted shards
  for (let i = 0; i < shards.length; i++) {
    const s = shards[i];
    if (s.tilt > 0.35 && polygonArea(s.poly) > 350) {
