  ];
  for (const sm of smearCenters) {
    // Milky translucent skin-oil smudge sweeps
    for (let r = 8; r <= sm.rx; r += 5.5) {
      const arcPts = [];
      for (let a = -125; a <= 125; a += 18) {
        const rad = (a * Math.PI) / 180;
