  // Front-facing camera pill & earpiece speaker slit at top of screen (y = -442, -474)
  const [camL, camR] = [P(-36, -442, 22.5), P(36, -442, 22.5)];
  brush.set("marker", "#07090e", 3.2);
  brush.line(camL[0], camL[1], camR[0], camR[1]);
  const [lensX, lensY] = P(22, -442, 22.6);
  brush.set("pen", "#2d4c75", 1.1);
  brush.circle(lensX, lensY, 4.5, 0.05);
  brush.set("rotring", "#a9ccf0", 0.55);
  brush.line(lensX - 2, lensY - 2, lensX + 1, lensY - 1);

  // =========================================================================
  // 7. THE WORN RUBBER CASE RIM / LIP (z = 26)
  // =========================================================================
  // Construct 4 overlapping rim bands around the screen between outerCasePoly and innerLipPoly
  const N = outerCasePoly.length;
  for (let i = 0; i < N; i++) {
    const ni = (i + 1) % N;
    const quad = [
      outerCasePoly[i],
      outerCasePoly[ni],
      innerLipPoly[ni],
      innerLipPoly[i]
    ];
    // Dark recessed interior shadow along the inside edge of the rubber lip
    brush.set("charcoal", "#06080c", 1.6);
    const [in1, in2] = [P(innerLipPoly[i][0], innerLipPoly[i][1], 23), P(innerLipPoly[ni][0], innerLipPoly[ni][1], 23)];
    brush.line(in1[0], in1[1], in2[0], in2[1]);

    // Dense matte rubber body on the raised lip
    brush.noStroke();
    brush.wash("#1d222d", 240);
    drawProjectedPoly(quad, 26, 0, 0, 0.01);
    brush.noWash();

    // Dry pigment mass texture on the rubber rim
    brush.mass("charcoal", i < N / 2 ? "#282f3d" : "#181c26", {
      precision: 0.65,
      strength: 0.55,
      gradient: 0.3,
      outline: false
    });
    drawProjectedPoly(quad, 26.2, 0, 0, 0.01);
    brush.noMass();
  }

  // Worn rubber edge details: scuffs, frayed micro-nicks, and polished thumb-wear highlights
  for (let i = 0; i < N; i++) {
    const ni = (i + 1) % N;
    const pA = innerLipPoly[i];
    const pB = innerLipPoly[ni];
    const [c1x, c1y] = P(pA[0], pA[1], 26.5);
    const [c2x, c2y] = P(pB[0], pB[1], 26.5);
    // Crisp inner bevel of the rubber case
    brush.set("cpencil", "#464f63", 0.95);
    brush.line(c1x, c1y, c2x, c2y);

    // Outer edge bevel
    const [o1x, o1y] = P(outerCasePoly[i][0], outerCasePoly[i][1], 26.2);
    const [o2x, o2y] = P(outerCasePoly[ni][0], outerCasePoly[ni][1], 26.2);
    brush.set("cpencil", "#353c4d", 0.85);
    brush.line(o1x, o1y, o2x, o2y);
  }

  // Exact localized wear & abrasions on the rubber lip (especially near impact corner & thumb zone)
  for (let w = 0; w < 115; w++) {
    const idx = floor(random(N));
    const t = random(0, 1);
    const rx = lerp(innerLipPoly[idx][0], outerCasePoly[idx][0], t);
    const ry = lerp(innerLipPoly[idx][1], outerCasePoly[idx][1], t);
    const [wx, wy] = P(rx, ry, 26.6);
    const nearImpact = dist(rx, ry, IMP.x, IMP.y) < 220;
    const col = nearImpact
      ? random(["#687185", "#7e889c", "#4d5568", "#10131a"])
      : random(["#4f576b", "#5e677d", "#12161f"]);
    brush.set("rubber_scuff", col, nearImpact ? 1.15 : 0.75);
    const ang = random(360);
    const len = nearImpact ? random(5, 16) : random(3, 10);
    brush.line(wx, wy, wx + cos(ang) * len, wy + sin(ang) * len);
  }

  // Gouged rubber scratches right at the bottom-right corner where the drop happened
  for (let g = 0; g < 18; g++) {
    const gx = random(160, 285);
    const gy = random(340, 515);
    if (gx > 250 || gy > 480) {
      const [c1, c2] = [P(gx, gy, 26.8), P(gx + random(-14, 14), gy + random(-14, 14), 26.8)];
