  // Top earpiece speaker recess slit at the top bezel edge
  const [sp1, sp2] = [P(-42, -488, 25), P(42, -488, 25)];
  brush.set("marker", "#06080c", 1.8);
  brush.line(sp1[0], sp1[1], sp2[0], sp2[1]);
  brush.set("rotring", "#555f75", 0.55);
  brush.line(sp1[0], sp1[1] + 2, sp2[0], sp2[1] + 2);

  // =========================================================================
  // 8. KINTSUGI GOLD SEAMS (WARM YELLOW OCHRE, PALE HIGHLIGHTS, FINE PEN & MARKER)
  // =========================================================================
  // Drawn at z = 23.2 (proud of the glass surface at z = 22!)

  // Pass 8A: Cast shadow / dark bronze-umber under-bevel beneath every raised gold seam
  for (const seg of crackSegments) {
    const [x1, y1] = P(seg.p1[0], seg.p1[1], 22.6);
