    brush.set("pen", "#4a2e0b", 1.05 * seg.weight);
    brush.line(x1 + 2.0, y1 + 2.4, x2 + 2.0, y2 + 2.4);
  }

  // Pass 8B: Pooled gold lacquer patch at the primary impact crater (IMP)
  const craterPoly = [];
  for (let i = 0; i < numRays; i++) {
    const pt = gridPts[i][1];
    craterPoly.push([
      lerp(IMP.x, pt[0], 0.72),
