    ]);
  }
  const clippedCrater = clipPolyToConvex(craterPoly, screenPoly);
  brush.noStroke();
  brush.wash("#8c5c16", 240);
  drawProjectedPoly(clippedCrater, 22.9, 2, 2, 0.08);
  brush.wash("#d6982c", 250);
  drawProjectedPoly(clippedCrater, 23.3, 0, 0, 0.08);
  brush.noWash();

  // Pass 8C: Warm yellow ochre & antique gold marker body of every crack
  for (const seg of crackSegments) {
    const [x1, y1] = P(seg.p1[0], seg.p1[1], 23.2);
    const [x2, y2] = P(seg.p2[0], seg.p2[1], 23.2);
    const mx = (x1 + x2) * 0.5 + (noise(seg.p1[0] * 0.05, seg.p1[1] * 0.05) - 0.5) * 3.2;
    const my = (y1 + y2) * 0.5 + (noise(seg.p2[0] * 0.05, seg.p2[1] * 0.05) - 0.5) * 3.2;

    // Warm yellow-ochre marker base
    brush.set("kintsugi_core", "#c98b27", 0.95 * seg.weight);
    brush.spline(
      [
        [x1, y1, 0.85],
        [mx, my, 1.15],
        [x2, y2, 0.85]
      ],
      0.35
    );

    // Rich golden ochre mid-ridge in confident fine pen
    brush.set("pen", "#e3ac3c", 0.9 * seg.weight);
    brush.spline(
      [
        [x1, y1, 0.7],
        [mx, my, 1.1],
        [x2, y2, 0.7]
      ],
      0.35
    );
  }

  // Pass 8D: Confident continuous radial master-strokes sweeping from the impact point
  for (let i = 0; i < numRays; i++) {
    const raySpline = [];
    for (let k = 0; k <= numRings; k++) {
      const pt = gridPts[i][k];
      // Check if inside or near screenPoly
      if (pt[0] >= -262 && pt[0] <= 262 && pt[1] >= -490 && pt[1] <= 490) {
        const [cx, cy] = P(pt[0], pt[1], 23.4);
        const press = map(k, 0, numRings, 1.35, 0.55);
        raySpline.push([cx, cy, press]);
      }
    }
    if (raySpline.length >= 2) {
      brush.set("rotring", "#a36b14", 0.85);
      brush.spline(raySpline, 0.3);
      brush.set("pen", "#edb948", 0.95);
      brush.spline(raySpline, 0.3);
    }
  }

  // Pass 8E: Pooled gold lacquer nodules at crack intersections + pale champagne highlights
  for (let i = 0; i < numRays; i++) {
    for (let k = 1; k < numRings; k++) {
      const pt = gridPts[i][k];
      if (pt[0] >= -252 && pt[0] <= 252 && pt[1] >= -480 && pt[1] <= 480) {
        const [nx, ny] = P(pt[0], pt[1], 23.5);
        const beadSize = map(k, 1, numRings, 3.2, 1.4);
        // Raised gold lacquer bead at vertex junction
        brush.set("marker", "#d4962a", beadSize * 0.65);
        brush.line(nx - 1.2, ny - 0.8, nx + 1.2, ny + 0.8);
        // Pale specular pinpoint highlight on upper-left of each gold bead
        brush.set("rotring", "#fff6d6", beadSize * 0.38);
        brush.line(nx - 1.5, ny - 1.5, nx - 0.3, ny - 0.5);
      }
    }
  }

  // Pass 8F: Crisp pale champagne & cream-white specular ridge highlights along every gold seam
  for (const seg of crackSegments) {
    const [x1, y1] = P(seg.p1[0], seg.p1[1], 23.6);
    const [x2, y2] = P(seg.p2[0], seg.p2[1], 23.6);
    // Upper-left ridge catches the pale twilight window light
    brush.set("kintsugi_glint", "#f8e296", 0.72 * seg.weight);
    brush.line(x1 - 0.9, y1 - 1.1, x2 - 0.9, y2 - 1.1);

    // Brightest white-gold specular glint on major radial and inner ring seams
    if (seg.weight > 0.82 || seg.ring <= 4) {
      const gx1 = lerp(x1, x2, 0.15) - 1.1;
      const gy1 = lerp(y1, y2, 0.15) - 1.3;
      const gx2 = lerp(x1, x2, 0.82) - 1.1;
      const gy2 = lerp(y1, y2, 0.82) - 1.3;
      brush.set("rotring", "#fffdf2", 0.52 * seg.weight);
      brush.line(gx1, gy1, gx2, gy2);
    }
  }

  // Highlight ridges on the solid gold impact crater fill
  const [impX, impY] = P(IMP.x, IMP.y, 23.7);
  brush.set("pen", "#fae49c", 1.1);
  brush.circle(impX - 2, impY - 2, 11, 0.35);
  brush.set("rotring", "#ffffff", 0.75);
  brush.line(impX - 10, impY - 7, impX + 4, impY - 11);
  brush.line(impX - 7, impY + 4, impX + 8, impY - 2);

  // =========================================================================
  // 9. EXACT DUST SPECKS, MICRO-LINT & GLASS CRUMBS ON SCREEN, CREVICE & COUNTER
  // =========================================================================
  // Tiny dust motes & lint fibers trapped along the rubber case crevice (innerLipPoly)
  for (let i = 0; i < 95; i++) {
    const idx = floor(random(innerLipPoly.length));
    const nIdx = (idx + 1) % innerLipPoly.length;
    const p = [
      lerp(innerLipPoly[idx][0], innerLipPoly[nIdx][0], random()),
      lerp(innerLipPoly[idx][1], innerLipPoly[nIdx][1], random())
    ];
    const [dx, dy] = P(p[0] + random(-5, 5), p[1] + random(-5, 5), 24.0);
    const dustCol = random(["#f0e8d8", "#cbd4e2", "#e8d29c", "#9aa5b8"]);
    brush.set("rotring", dustCol, random(0.32, 0.65));
    if (random() < 0.3) {
      // Tiny curved lint fiber
      const a = random(360);
      brush.line(dx, dy, dx + cos(a) * random(3, 6), dy + sin(a) * random(3, 6));
    } else {
      // Pinprick dust mote
      brush.line(dx, dy, dx + 0.9, dy + 0.6);
    }
  }

  // Dust specks & tiny gold/glass crumbs resting on the screen surface
  for (let i = 0; i < 130; i++) {
    const sx = random(-245, 245);
    const sy = random(-470, 470);
    const [dx, dy] = P(sx, sy, 23.8);
    const nearCrater = dist(sx, sy, IMP.x, IMP.y) < 160;
    const col = nearCrater
      ? random(["#fae5a0", "#ffffff", "#d99d36", "#d8e4f0"])
      : random(["#f4eee6", "#c4d0de", "#fae6a8", "#8f9eb3"]);
    const w = nearCrater ? random(0.4, 0.85) : random(0.28, 0.55);
    brush.set("rotring", col, w);
    brush.line(dx, dy, dx + random(0.6, 2.0), dy + random(-1.2, 1.2));
  }

  // Subtle dust & tiny stone/gold flecks scattered on the slate kitchen counter around the phone
  for (let i = 0; i < 80; i++) {
    const angle = random(360);
    const rad = random(360, 580);
    const cx = 610 + cos(angle) * rad;
    const cy = 612 + sin(angle) * rad;
    if (cx > 25 && cx < 1175 && cy > 25 && cy < 1175) {
      const isGoldFleck = random() < 0.18;
      brush.set("rotring", isGoldFleck ? "#e8bd56" : random(["#5c6578", "#8590a6", "#11141c"]), random(0.35, 0.75));
      brush.line(cx, cy, cx + random(0.8, 2.4), cy + random(-1.5, 1.5));
    }
  }

  noLoop();
}

const TILT = -10.5;
const GRAV_TILT = -2.2;

function pt(x, y, deg = TILT) {
  const rad = (deg * Math.PI) / 180;
  const dx = x - 600;
  const dy = y - 600;
  return [
    600 + dx * Math.cos(rad) - dy * Math.sin(rad),
    600 + dx * Math.sin(rad) + dy * Math.cos(rad)
  ];
}

function ellipsePts(cx, cy, rx, ry, rotDeg = 0, n = 36, startDeg = 0, endDeg = 360, tiltDeg = TILT) {
  const pts = [];
  const rot = (rotDeg * Math.PI) / 180;
  const cr = Math.cos(rot);
  const sr = Math.sin(rot);
  const closed = Math.abs(endDeg - startDeg - 360) < 0.01;
  const count = closed ? n : n + 1;
  for (let i = 0; i < count; i++) {
    const t = i / n;
    const a = ((startDeg + (endDeg - startDeg) * t) * Math.PI) / 180;
    const lx = rx * Math.cos(a);
    const ly = ry * Math.sin(a);
    const wx = cx + lx * cr - ly * sr;
    const wy = cy + lx * sr + ly * cr;
    pts.push(pt(wx, wy, tiltDeg));
  }
  return pts;
}

function washRaw(pts, col, alpha = 255, curvature = 0.12) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function washPoly(pts, col, alpha = 255, curvature = 0.12, deg = TILT) {
  washRaw(pts.map(p => pt(p[0], p[1], deg)), col, alpha, curvature);
}

function fillRaw(pts, col, alpha = 140, bleed = 0.08, tex = 0.35, border = 0.2, curvature = 0.15) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function fillPoly(pts, col, alpha = 140, bleed = 0.08, tex = 0.35, border = 0.2, curvature = 0.15, deg = TILT) {
  fillRaw(pts.map(p => pt(p[0], p[1], deg)), col, alpha, bleed, tex, border, curvature);
}

function hatchRaw(pts, brushName, col, weight, dist, angle, opts = { rand: 0.04 }, curvature = 0.12) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noHatch();
}

function hatchPoly(pts, brushName, col, weight, dist, angle, opts = { rand: 0.04 }, curvature = 0.12, deg = TILT) {
  hatchRaw(pts.map(p => pt(p[0], p[1], deg)), brushName, col, weight, dist, angle + deg, opts, curvature);
}

function strokeRaw(pts, brushName, col, weight = 1, curvature = 0.2, closed = false) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
    return;
  }
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    if (pts[i].length > 2) {
      brush.vertex(pts[i][0], pts[i][1], pts[i][2]);
    } else {
      brush.vertex(pts[i][0], pts[i][1]);
    }
  }
  brush.endShape(closed);
}

function tSpline(pts, brushName, col, weight = 1, curvature = 0.5, deg = TILT) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  const tPts = pts.map(p => {
    const tp = pt(p[0], p[1], deg);
    return p.length > 2 ? [tp[0], tp[1], p[2]] : tp;
  });
  if (tPts.length === 2) {
    brush.line(tPts[0][0], tPts[0][1], tPts[1][0], tPts[1][1]);
  } else {
    brush.spline(tPts, curvature);
  }
}

function tLine(x1, y1, x2, y2, brushName, col, weight = 1, deg = TILT) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  const p1 = pt(x1, y1, deg);
  const p2 = pt(x2, y2, deg);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
}

