  fillPoly([[130, 180], [330, 220], [420, 580], [110, 580]], "#ff8e6e", 85, 0.22, 0.3, 0.15);

  // Center Seam: Bruised Violet & Warm Plum
  washPoly([[430, -240], [740, -240], [810, 650], [510, 650]], "#21072b", 215, 0.08);
  fillPoly([[465, -150], [705, -150], [770, 645], [540, 645]], "#46115c", 145, 0.16, 0.4, 0.25);
  fillPoly([[500, 20], [665, 20], [725, 640], [565, 640]], "#71228f", 115, 0.18, 0.35, 0.2);
  hatchPoly([[480, -80], [690, -80], [750, 640], [545, 640]], "chiselMarker", "#9338b0", 1.1, 14, -68, { rand: 0.06 });

  // Right Wall Zone: Acid Cyan Beam cutting into Deep Inky Shadow
  washPoly([[680, -240], [1480, -240], [1480, 650], [740, 650]], "#05141a", 235, 0.05);
  washPoly([[670, -180], [1140, -180], [1040, 650], [720, 650]], "#06313b", 210, 0.08);
  fillPoly([[685, -90], [1050, -60], [970, 640], [715, 640]], "#007c8a", 135, 0.16, 0.4, 0.25);
  fillPoly([[705, 40], [975, 80], [915, 635], [730, 635]], "#00c9bf", 115, 0.18, 0.35, 0.2);
