// ============================================================================
// 2. LOOMING PATTERNED DAMASK WALLPAPER
// ============================================================================
function drawDamaskWallpaper() {
  const spacingX = 160;
  const spacingY = 196;

  for (let row = -1; row <= 3; row++) {
    const wy = 40 + row * spacingY;
    const xOffset = (row % 2 === 0) ? 0 : spacingX * 0.5;

    for (let col = -1; col <= 7; col++) {
      const wx = 30 + col * spacingX + xOffset;
      if (wy > 605 || wx < -120 || wx > 1220) continue;

      // Vignette & diagonal gobo shadow modulation
      const distCenter = Math.hypot((wx - 520) * 0.85, (wy - 250) * 1.15);
      if (distCenter > 680) continue;

      // Determine gel color based on horizontal/diagonal seam
      const seamX = 565 + (wy - 200) * 0.18;
      let hiCol, midCol, shCol, weightBoost;
      if (wx < seamX - 85) {
        // Hot Magenta / Warm Coral zone
        hiCol = wx > 120 && wy > 100 ? "#ff7a8a" : "#ff2e6d";
        midCol = "#b81448";
        shCol = "#21030d";
        weightBoost = 1.0;
      } else if (wx <= seamX + 85) {
        // Bruised Violet Seam
        hiCol = "#c76bdd";
        midCol = "#6e218a";
        shCol = "#160421";
        weightBoost = 0.95;
      } else if (wx < 1010) {
        // Acid Cyan zone
        hiCol = wx < 880 ? "#6bffec" : "#00b8b0";
        midCol = "#006d75";
        shCol = "#031114";
        weightBoost = 0.95;
      } else {
        // Far right deep shadow
        hiCol = "#0d3840";
        midCol = "#072026";
        shCol = "#02080a";
        weightBoost = 0.65;
      }

      drawDamaskMotif(wx, wy, hiCol, midCol, shCol, weightBoost);
    }
  }
}

function drawDamaskMotif(cx, cy, hiCol, midCol, shCol, wScale) {
  // 1. Ogee outer frame (left and right S-curves)
  const ogeeL = [
    [cx, cy - 96],
    [cx - 38, cy - 64],
    [cx - 74, cy - 22],
    [cx - 74, cy + 22],
    [cx - 38, cy + 64],
    [cx, cy + 96]
  ];
  const ogeeR = [
    [cx, cy - 96],
    [cx + 38, cy - 64],
    [cx + 74, cy - 22],
    [cx + 74, cy + 22],
    [cx + 38, cy + 64],
    [cx, cy + 96]
  ];

  // Embossed dark shadow offset
  tSpline(ogeeL.map(p => [p[0] + 2.5, p[1] + 2.5]), "cpencil", shCol, 1.2 * wScale, 0.55);
  tSpline(ogeeR.map(p => [p[0] + 2.5, p[1] + 2.5]), "cpencil", shCol, 1.2 * wScale, 0.55);
  // Lit ridge of ogee lattice
  tSpline(ogeeL, "cpencil", midCol, 1.0 * wScale, 0.55);
  tSpline(ogeeR, "cpencil", midCol, 1.0 * wScale, 0.55);

  // Inner parallel ogee thread
  const ogeeInL = [
    [cx, cy - 82],
    [cx - 56, cy - 18],
    [cx - 56, cy + 18],
    [cx, cy + 82]
  ];
  const ogeeInR = [
    [cx, cy - 82],
    [cx + 56, cy - 18],
    [cx + 56, cy + 18],
    [cx, cy + 82]
  ];
  tSpline(ogeeInL, "rotring", hiCol, 0.65 * wScale, 0.5);
  tSpline(ogeeInR, "rotring", hiCol, 0.65 * wScale, 0.5);

  // 2. Central Baroque Pomegranate / Acanthus Vase
  const corePoly = [
    [cx, cy - 42],
    [cx + 22, cy - 18],
    [cx + 18, cy + 16],
    [cx, cy + 36],
    [cx - 18, cy + 16],
    [cx - 22, cy - 18]
  ];
  washPoly(corePoly.map(p => [p[0] + 2, p[1] + 2]), shCol, 150, 0.25);
  washPoly(corePoly, midCol, 115, 0.25);
  tSpline([...corePoly, corePoly[0]], "cpencil", hiCol, 0.9 * wScale, 0.4);

  // Inner tear-drop seed & crown petals
  const crown = [
    [cx - 16, cy - 38],
    [cx - 9, cy - 58],
    [cx, cy - 46],
    [cx + 9, cy - 58],
    [cx + 16, cy - 38]
  ];
  tSpline(crown, "cpencil", hiCol, 0.95 * wScale, 0.35);

  // 3. Symmetrical Curling Acanthus Fronds
  for (let side of [-1, 1]) {
    const frondUpper = [
      [cx + side * 12, cy - 22],
      [cx + side * 36, cy - 38],
      [cx + side * 46, cy - 16],
      [cx + side * 30, cy - 4]
    ];
    const frondLower = [
      [cx + side * 12, cy + 8],
      [cx + side * 42, cy + 4],
      [cx + side * 44, cy + 28],
      [cx + side * 22, cy + 34]
    ];
    const stemBase = [
      [cx, cy + 36],
      [cx + side * 18, cy + 52],
      [cx + side * 8, cy + 68]
    ];
    tSpline(frondUpper.map(p => [p[0] + 2, p[1] + 2]), "cpencil", shCol, 1.1 * wScale, 0.5);
    tSpline(frondUpper, "cpencil", hiCol, 0.95 * wScale, 0.5);
    tSpline(frondLower.map(p => [p[0] + 2, p[1] + 2]), "cpencil", shCol, 1.1 * wScale, 0.5);
    tSpline(frondLower, "cpencil", hiCol, 0.9 * wScale, 0.5);
    tSpline(stemBase, "cpencil", midCol, 0.85 * wScale, 0.45);
  }
}

// ============================================================================
// 3. WALL SHADOW CUTS & WAINSCOT DADO RAIL
// ============================================================================
function drawWallShadowsAndDado() {
  // Hard-edged noir shadow cuts looming across upper-left and upper-right wall
  washPoly([[-260, -240], [390, -240], [95, 340], [-260, 480]], "#090206", 220, 0.02);
  washPoly([[-260, -240], [210, -240], [-30, 260], [-260, 350]], "#050104", 245, 0.02);

  // Diagonal architectural shadow slash on right wall
  washPoly([[890, -240], [1480, -240], [1480, 645], [965, 645], [820, 210]], "#04080b", 230, 0.04);
  washPoly([[1010, -240], [1480, -240], [1480, 645], [1050, 645]], "#020406", 250, 0.02);

  // Subtle shadow bar across upper wall
  washPoly([[260, -240], [780, -240], [660, 45], [190, 95]], "#0c030a", 155, 0.05);

  // Wainscot / Dado Molding at the wall-table horizon (y = 596..638)
  washPoly([[-260, 596], [1480, 596], [1480, 638], [-260, 638]], "#0d0409", 250, 0);
  // Top bevel of molding catching magenta, violet, and cyan gels
  tLine(-220, 598, 490, 598, "chiselMarker", "#d91b5c", 1.2);
  tLine(60, 599, 440, 599, "glossPen", "#ff758f", 1.1);
