// ============================================================================
// 7. THE HYPERREAL ROTARY DIAL (BEZEL, NUMERALS, FINGER HOLES & STOP BRACKET)
// ============================================================================
function drawRotaryDial(cx, cy, rx, ry) {
  // 1. Cast Shadow of Dial Assembly on the Sloped Bakelite Face
  washRaw(ellipsePts(cx - 5, cy + 9, rx + 5, ry + 5, 0, 44), "#380d2a", 185, 0.15);
  washRaw(ellipsePts(cx + 5, cy + 9, rx + 5, ry + 5, 0, 44), "#0b2e38", 185, 0.15);

  // 2. Outer Chrome / Brass Bezel Ring
  washRaw(ellipsePts(cx, cy, rx + 3, ry + 3, 0, 48), "#1c0919", 250, 0.15);
  // Metallic segments around bezel: magenta left, gold top/bottom, cyan right
  strokeRaw(ellipsePts(cx, cy, rx + 1, ry + 1, 0, 24, 110, 250), "chiselMarker", "#ff2a6d", 1.5, 0.2, false);
  strokeRaw(ellipsePts(cx, cy, rx + 1, ry + 1, 0, 24, -70, 70), "chiselMarker", "#00f5d4", 1.5, 0.2, false);
  strokeRaw(ellipsePts(cx, cy, rx + 1, ry + 1, 0, 16, 65, 115), "chiselMarker", "#f4a261", 1.3, 0.2, false);
  strokeRaw(ellipsePts(cx, cy, rx + 1, ry + 1, 0, 16, 245, 295), "chiselMarker", "#ffd166", 1.3, 0.2, false);
  strokeRaw(ellipsePts(cx, cy, rx, ry, 0, 48), "glossPen", "#fff5eb", 1.2, 0.2, true);

  // 3. Recessed Cream Number Plate
  const plateRx = rx - 8;
  const plateRy = ry - 7;
  washRaw(ellipsePts(cx, cy, plateRx, plateRy, 0, 48), "#faebd7", 250, 0.15);
  // Left magenta-coral tint on number plate
  fillRaw(ellipsePts(cx - 18, cy, plateRx * 0.78, plateRy * 0.92, 0, 32), "#ff8fa3", 95, 0.12, 0.25, 0.1);
  // Right cyan tint on number plate
  fillRaw(ellipsePts(cx + 18, cy, plateRx * 0.78, plateRy * 0.92, 0, 32), "#72efdd", 85, 0.12, 0.25, 0.1);
  // Inner bezel shadow crescent at top of number plate
  strokeRaw(ellipsePts(cx, cy, plateRx - 2, plateRy - 2, 0, 28, 190, 350), "chiselMarker", "#3d122e", 1.1, 0.2, false);

  // 4. The 10 Dial Numerals (1, 2, 3, 4, 5, 6, 7, 8, 9, 0)
  const dialAngles = [-52, -82, -112, -142, -172, 158, 128, 98, 68, 36];
  const numerals = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "0"];
  const numRx = plateRx * 0.71;
  const numRy = plateRy * 0.71;

  for (let i = 0; i < 10; i++) {
    const aRad = (dialAngles[i] * Math.PI) / 180;
    const nx = cx + numRx * Math.cos(aRad);
    const ny = cy + numRy * Math.sin(aRad);
    drawDialNumeral(numerals[i], nx, ny, 7.5);
  }

  // 5. Center Cap & Red/Gold Emblem Dot
  washRaw(ellipsePts(cx, cy, 34, 29, 0, 36), "#1f0818", 250, 0.15);
  strokeRaw(ellipsePts(cx, cy, 33, 28, 0, 36), "glossPen", "#ffd166", 1.2, 0.2, true);
  washRaw(ellipsePts(cx, cy, 27, 23, 0, 32), "#faebd7", 245, 0.15);
  washRaw(ellipsePts(cx, cy, 13, 11, 0, 24), "#d91b5c", 240, 0.15);
  tLine(cx - 8, cy - 5, cx + 6, cy - 5, "glossPen", "#ffffff", 1.3);

  // 6. Translucent Acrylic Finger Wheel (Refraction Sheen + 10 Finger Holes)
  // Diagonal glossy refraction bars across the clear plastic wheel
  washPoly([
    [cx - 72, cy - 48], [cx - 42, cy - 66], [cx + 68, cy + 44], [cx + 42, cy + 62]
  ], "#ffe3ec", 65, 0.05);
  washPoly([
    [cx - 28, cy - 75], [cx + 6, cy - 78], [cx + 82, cy + 12], [cx + 64, cy + 34]
  ], "#caf0f8", 65, 0.05);

  // Outer edge of the clear acrylic wheel (slightly larger than number plate)
  strokeRaw(ellipsePts(cx, cy - 2, plateRx + 2, plateRy + 2, 0, 48), "glossPen", "#ffffff", 1.3, 0.2, true);

  // The 10 Circular Finger Holes in the Acrylic Wheel
  for (let i = 0; i < 10; i++) {
    const aRad = (dialAngles[i] * Math.PI) / 180;
    const hx = cx + numRx * Math.cos(aRad);
    const hy = cy + numRy * Math.sin(aRad);
    const hrx = 17.5;
    const hry = 14.8;

    // Subtle shadow cast by finger hole rim onto number plate
    strokeRaw(ellipsePts(hx + 1.5, hy + 2, hrx, hry, 0, 20), "rotring", "#3b0d26", 0.75, 0.2, true);
    // Refractive acrylic bevel around each finger hole
    const holeRimCol = hx < cx ? "#ff6b8b" : "#00f5d4";
    strokeRaw(ellipsePts(hx, hy, hrx, hry, 0, 24), "cpencil", holeRimCol, 1.0, 0.2, true);
    strokeRaw(ellipsePts(hx, hy, hrx, hry, 0, 14, -150, -20), "glossPen", "#ffffff", 1.25, 0.2, false);
  }

  // 7. Chrome Finger-Stop Bracket at Lower-Right (around 12°..22°)
