function drawDialNumeral(ch, x, y, s) {
  const c = "#1a0612";
  const w = 1.05;
  if (ch === "1") {
    tLine(x - 2, y - s * 0.6, x + 1, y - s, "rotring", c, w);
    tLine(x + 1, y - s, x + 1, y + s, "rotring", c, w);
    tLine(x - 3, y + s, x + 4, y + s, "rotring", c, w);
  } else if (ch === "2") {
    tSpline([[x - s * 0.6, y - s * 0.5], [x, y - s], [x + s * 0.6, y - s * 0.4], [x - s * 0.6, y + s], [x + s * 0.7, y + s]], "rotring", c, w, 0.35);
  } else if (ch === "3") {
    tSpline([[x - s * 0.6, y - s * 0.7], [x + s * 0.5, y - s * 0.9], [x + s * 0.4, y - s * 0.1], [x - s * 0.2, y]], "rotring", c, w, 0.4);
    tSpline([[x - s * 0.2, y], [x + s * 0.6, y + s * 0.2], [x + s * 0.5, y + s * 0.9], [x - s * 0.6, y + s * 0.7]], "rotring", c, w, 0.4);
  } else if (ch === "4") {
    tLine(x + s * 0.3, y - s, x - s * 0.7, y + s * 0.3, "rotring", c, w);
    tLine(x - s * 0.7, y + s * 0.3, x + s * 0.7, y + s * 0.3, "rotring", c, w);
    tLine(x + s * 0.3, y - s, x + s * 0.3, y + s, "rotring", c, w);
  } else if (ch === "5") {
    tLine(x + s * 0.6, y - s, x - s * 0.5, y - s, "rotring", c, w);
    tLine(x - s * 0.5, y - s, x - s * 0.6, y - s * 0.1, "rotring", c, w);
    tSpline([[x - s * 0.6, y - s * 0.1], [x + s * 0.6, y - s * 0.1], [x + s * 0.6, y + s * 0.8], [x - s * 0.6, y + s * 0.8]], "rotring", c, w, 0.4);
  } else if (ch === "6") {
    tSpline([[x + s * 0.5, y - s * 0.8], [x - s * 0.5, y - s * 0.4], [x - s * 0.6, y + s * 0.6], [x + s * 0.1, y + s], [x + s * 0.6, y + s * 0.4], [x, y - s * 0.1], [x - s * 0.5, y + s * 0.2]], "rotring", c, w, 0.45);
  } else if (ch === "7") {
    tLine(x - s * 0.6, y - s, x + s * 0.6, y - s, "rotring", c, w);
    tLine(x + s * 0.6, y - s, x - s * 0.2, y + s, "rotring", c, w);
  } else if (ch === "8") {
    strokeRaw(ellipsePts(x, y - s * 0.45, s * 0.52, s * 0.45, 0, 14), "rotring", c, w, 0.2, true);
    strokeRaw(ellipsePts(x, y + s * 0.48, s * 0.62, s * 0.52, 0, 14), "rotring", c, w, 0.2, true);
  } else if (ch === "9") {
    tSpline([[x + s * 0.5, y - s * 0.2], [x, y + s * 0.1], [x - s * 0.6, y - s * 0.4], [x, y - s], [x + s * 0.6, y - s * 0.4], [x + s * 0.4, y + s * 0.6], [x - s * 0.4, y + s * 0.9]], "rotring", c, w, 0.45);
  } else if (ch === "0") {
    strokeRaw(ellipsePts(x, y, s * 0.62, s * 0.92, 0, 18), "rotring", c, w, 0.2, true);
  }
}

