// 9. TAUT COILED CORD & DANGLING CREAM RECEIVER IN FOREGROUND
// ============================================================================
function drawTautCordAndDanglingReceiver() {
  // Note: While the table & phone are canted at TILT (-10.5°), once the cord drops
  // off the table edge it hangs nearly vertically by gravity! We compute the upper
  // anchor on the tilted phone/table and the lower receiver in GRAV_TILT (-2.2°).
  const pStart = pt(278, 654, TILT);      // Cord exit grommet on left of phone base
  const pEdge = pt(302, 858, TILT);       // Point where taut cord crosses table bullnose
  const pHandsetTop = pt(392, 995, GRAV_TILT); // Entry into dangling receiver earpiece

  // 1. Cast Shadow of the Taut Cord on the Table & Front Bevel
  strokeRaw([
    [pStart[0] + 12, pStart[1] + 6],
    [pEdge[0] + 14, pEdge[1] + 6],
    [pEdge[0] + 16, pEdge[1] + 55]
  ], "chiselMarker", "#030005", 2.4, 0.25, false);

  // 2. Render the Taut Helical Coiled Cord (24 stretched loops!)
  const totalCoils = 24;
  for (let i = 0; i < totalCoils; i++) {
    const t0 = i / totalCoils;
    const t1 = (i + 1) / totalCoils;

    // Two-segment spine: pStart -> pEdge (t = 0..0.52), pEdge -> pHandsetTop (t = 0.52..1.0)
    const getSpine = (t) => {
      if (t < 0.52) {
        const u = t / 0.52;
        return [
          lerp(pStart[0], pEdge[0], u),
          lerp(pStart[1], pEdge[1], u)
        ];
      } else {
        const u = (t - 0.52) / 0.48;
        return [
          lerp(pEdge[0], pHandsetTop[0], u),
          lerp(pEdge[1], pHandsetTop[1], u)
        ];
      }
    };

    const s0 = getSpine(t0);
    const sMid = getSpine((t0 + t1) * 0.5);
    const s1 = getSpine(t1);
    const coilW = 19;

    // Back-loop of helix (darker bruised violet & crimson)
    const backLoop = [
      [s0[0] - coilW * 0.85, s0[1]],
      [sMid[0] + coilW * 0.95, sMid[1] - 2],
      [s1[0] - coilW * 0.85, s1[1]]
    ];
    strokeRaw(backLoop, "chiselMarker", "#3b0921", 1.35, 0.45, false);

    // Front-loop of helix (cream vinyl tube lit by hot magenta left, cyan right)
    const frontLoop = [
      [s0[0] - coilW, s0[1] + 1],
      [sMid[0] + coilW, sMid[1] + 3],
      [s1[0] - coilW, s1[1] + 8]
    ];
    // Dark under-edge of coil
    strokeRaw(frontLoop.map(p => [p[0], p[1] + 3.5]), "rotring", "#12020a", 1.4, 0.5, false);
    // Warm cream body of coil
    strokeRaw(frontLoop, "chiselMarker", "#f2d0b6", 1.55, 0.5, false);
    // Hot magenta highlight on left bend of each coil
    strokeRaw([
      [s0[0] - coilW, s0[1] + 1],
      [s0[0] - coilW * 0.2, s0[1] + 2],
      [sMid[0] + coilW * 0.25, sMid[1] + 2]
    ], "glossPen", "#ff2a6d", 1.5, 0.45, false);
    strokeRaw([
      [s0[0] - coilW * 0.95, s0[1]],
      [s0[0] - coilW * 0.35, s0[1] + 1],
      [s0[0] + 2, s0[1] + 1.5]
    ], "glossPen", "#ffffff", 1.25, 0.4, false);
    // Acid cyan bounce on right bend of each coil
    strokeRaw([
      [sMid[0] + coilW * 0.3, sMid[1] + 2],
      [sMid[0] + coilW, sMid[1] + 3],
      [s1[0] - coilW * 0.2, s1[1] + 6]
    ], "glossPen", "#00f5d4", 1.25, 0.45, false);
  }

  // 3. THE DANGLING CREAM BAKELITE RECEIVER (in GRAV_TILT space)
  // Top Earpiece Bell around (400, 1020), Sculpted Handle Bar down to Lower Mouthpiece Bell around (565, 1105)
  const gDeg = GRAV_TILT;

  // Rubber strain-relief grommet at top of receiver
  washPoly([[382, 982], [402, 986], [400, 1006], [378, 1002]], "#4a0c24", 250, 0.1, gDeg);
  tLine(384, 984, 381, 1000, "glossPen", "#ff4d88", 1.2, gDeg);

  // --- Sculpted Prismatic Handle Bar (Connecting Earpiece & Mouthpiece) ---
  // Upper-left plane of handle bar (drenched in Hot Magenta & Warm Cream)
  const barUpper = [
    [392, 996], [428, 1002], [568, 1074], [546, 1094], [412, 1024]
  ];
  washPoly(barUpper, "#f5dec4", 250, 0.15, gDeg);
  fillPoly(barUpper, "#ff4d88", 150, 0.12, 0.3, 0.15, 0.15, gDeg);
  // Lower-right plane of handle bar (Bruised Violet & Acid Cyan rim)
  const barLower = [
    [412, 1024], [546, 1094], [532, 1114], [398, 1044]
  ];
  washPoly(barLower, "#2e0d3a", 245, 0.15, gDeg);
  fillPoly(barLower, "#00b4b8", 130, 0.12, 0.3, 0.15, 0.15, gDeg);

  // Central Prismatic Ridge of Handle Bar (Blazing Liquid Specular Ribbon!)
  tSpline([[404, 1012, 0.8], [478, 1050, 1.4], [552, 1088, 0.9]], "chiselMarker", "#ff8fa3", 1.3, 0.4, gDeg);
  tSpline([[406, 1014, 0.7], [478, 1051, 1.3], [550, 1089, 0.8]], "glossPen", "#ffffff", 2.0, 0.4, gDeg);
  // Cyan rim along lower edge of handle bar
  tSpline([[402, 1042], [468, 1078], [532, 1112]], "glossPen", "#00f5d4", 1.45, 0.4, gDeg);

  // --- Upper Earpiece Bell & Perforated Cap (centered around 382, 1036) ---
  // Back conical housing of earpiece
  const earBellBack = [
    [354, 996], [414, 992], [432, 1022], [408, 1068], [344, 1052]
  ];
  washPoly(earBellBack, "#d91b5c", 245, 0.22, gDeg);
  fillPoly(earBellBack, "#ff758f", 140, 0.12, 0.3, 0.15, 0.2, gDeg);
  tSpline([[358, 998], [394, 994], [424, 1012]], "glossPen", "#ffe3ec", 1.7, 0.45, gDeg);

  // Angled Earpiece Cap Face (facing three-quarters toward viewer)
  const earCx = 372;
  const earCy = 1042;
  // Outer bakelite cap rim
  washRaw(ellipsePts(earCx, earCy, 52, 38, -28, 36, 0, 360, gDeg), "#f5dec4", 250, 0.15);
  fillRaw(ellipsePts(earCx - 8, earCy - 6, 44, 32, -28, 28, 0, 360, gDeg), "#ff4d88", 130, 0.12, 0.3, 0.15);
  fillRaw(ellipsePts(earCx + 10, earCy + 8, 40, 28, -28, 28, 0, 360, gDeg), "#7209b7", 110, 0.12, 0.3, 0.15);
  strokeRaw(ellipsePts(earCx, earCy, 52, 38, -28, 36, 0, 360, gDeg), "glossPen", "#ff8fa3", 1.3, 0.2, true);
  strokeRaw(ellipsePts(earCx, earCy, 52, 38, -28, 20, 150, 310, gDeg), "glossPen", "#ffffff", 1.6, 0.2, false);

  // Recessed inner bowl of earpiece cap
  washRaw(ellipsePts(earCx - 2, earCy + 2, 38, 27, -28, 32, 0, 360, gDeg), "#380a22", 230, 0.15);
