function drawReceiverHoles(cx, cy, ringRx, ringRy, rotDeg, tiltDeg, rimCol) {
  const rot = (rotDeg * Math.PI) / 180;
  const cr = Math.cos(rot);
  const sr = Math.sin(rot);

  // Center hole
  washRaw(ellipsePts(cx, cy, 4.2, 3.2, rotDeg, 12, 0, 360, tiltDeg), "#090208", 250, 0.1);
  strokeRaw(ellipsePts(cx + 0.8, cy + 0.8, 4.2, 3.2, rotDeg, 10, -90, 90, tiltDeg), "glossPen", rimCol, 0.85, 0.2, false);

  // 8 surrounding acoustic holes
  for (let i = 0; i < 8; i++) {
    const a = (i * 45 * Math.PI) / 180;
    const lx = ringRx * Math.cos(a);
    const ly = ringRy * Math.sin(a);
    const hx = cx + lx * cr - ly * sr;
    const hy = cy + lx * sr + ly * cr;
    washRaw(ellipsePts(hx, hy, 4.0, 3.0, rotDeg, 12, 0, 360, tiltDeg), "#090208", 250, 0.1);
    strokeRaw(ellipsePts(hx + 0.8, hy + 0.8, 4.0, 3.0, rotDeg, 10, -90, 90, tiltDeg), "glossPen", rimCol, 0.8, 0.2, false);
  }
}

