const Y_RABBET_TABLE = [-170, -52, 66, 184, 302, 422, 542, 660, 778, 894, 1012];

// =============================================================================
// GEOMETRY & PROJECTION ENGINE
// =============================================================================

function stemFrontX(y) {
  let t = constrain(y / 1045, -0.25, 1.1);
  let tPos = max(0, t);
  let arch = Math.sin(Math.PI * Math.pow(constrain(t, 0, 1), 0.84));
  letlinearHook = t < 0 ? -t * 28 : 0;
  return 312 - 46 * arch + 168 * Math.pow(tPos, 2.55) + letlinearHook;
}

function stemBevelX(y) {
  let t = constrain(y / 1045, 0, 1);
  return stemFrontX(y) + 28 - 5 * t;
}

function stemRabbetX(y) {
  let t = constrain(y / 1045, -0.2, 1.05);
  let tClamped = constrain(t, 0, 1);
  return stemFrontX(y) + 86 + 15 * Math.sin(tClamped * Math.PI) - 12 * tClamped * tClamped;
}

function interpRabbetY(v) {
  let idx = constrain(Math.floor(v), 0, 9);
  let frac = v - idx;
  return lerp(Y_RABBET_TABLE[idx], Y_RABBET_TABLE[idx + 1], frac);
}

// Maps (u in [0,1], v in [0,10]) on the starboard hull surface to 2D canvas (x,y)
function hullPoint(u, v) {
  let fv = constrain(v / 10, 0, 1);
  let yRab = interpRabbetY(v);
  let xRab = stemRabbetX(yRab);

  let wHull = 698 + 58 * Math.sin(fv * Math.PI * 0.85) - 295 * Math.pow(fv, 2.35);
  let thetaDeg = (0.18 * u + 0.82 * Math.pow(constrain(u, 0, 1), 0.91)) * 80;
  let thetaRad = thetaDeg * Math.PI / 180;
  let sin80 = Math.sin(80 * Math.PI / 180);
  let x = xRab + wHull * (Math.sin(thetaRad) / sin80);

  let yEnd = 236 + 918 * Math.pow(fv, 0.92) - 102 * Math.pow(fv, 3.15);
  let su = 1 - Math.pow(1 - constrain(u, 0, 1), 1.62);
  let belly = 36 * Math.sin(Math.PI * fv) * Math.sin(Math.PI * Math.pow(constrain(u, 0, 1), 0.86));
  let y = yRab + (yEnd - yRab) * su + belly;

  return { x, y };
}

// Local 3D foreshortening factor along u
function hullForeshorten(u) {
  let thetaDeg = (0.18 * u + 0.82 * Math.pow(constrain(u, 0, 1), 0.91)) * 80;
  return Math.max(0.22, Math.cos(thetaDeg * Math.PI / 180));
}

// Thickness of the overlapping clinker lap edge at strake k, position u
function lapStepThickness(u, k) {
  let fk = k / 10;
  return (12.5 - 3.8 * u * u) * (1.04 - 0.18 * fk);
}

// Port-side foreshortened bow cheek point (left of the stempost)
function portHullPoint(uPort, v) {
  let fv = constrain(v / 10, 0, 1);
  let yRab = interpRabbetY(v) + 18;
  let xFront = stemFrontX(yRab);
  // Swells out to the left of the stempost in the mid-bow
  let swell = 78 * Math.pow(Math.sin(fv * Math.PI), 0.85) * Math.sin(uPort * Math.PI * 0.92);
  let stepOut = (10 - v) * 2.1 * Math.pow(uPort, 0.6);
  let x = xFront + 6 - (swell + stepOut);
  let y = yRab + (95 - 55 * fv) * Math.pow(uPort, 1.35);
  return { x, y };
}

// Safe wrapper guaranteeing brush.set() is always active before any stroke
function useBrush(name, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(name, col, weight);
}

