function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paper);

  // Clip to tall vertical composition with full top-bleed crop at y = 0
  brush.clip([45, 0, 1155, 1170]);

  // 1. Batched Watercolor & Tar Under-Washes (Grouped by color for speed)
  drawUnderWashes();

  // 2. Interior Framing & Opposite Port Bow Cheek (Left Silhouette Steps)
  drawInteriorBowAndGunwale();
  drawPortCheekClinkerSteps();

  // 3. Starboard Clinker Strakes: Carved Wood Grain, Knots & Lap Geometry
  for (let s = 0; s < 10; s++) {
    drawClinkerStrakeCarving(s);
  }

  // 4. Deep Plank Lap Undercuts, Tar Caulking Seams & Bevel Gouge Marks
  for (let s = 1; s <= 10; s++) {
    drawPlankLapEdgeAndShadow(s);
  }

  // 5. The Towering Carved Oak Stempost, Hooked Scarph, Iron Stem-Band & Ring
  drawStempostAndIronwork();

  // 6. Exact Clinker Iron Rivets, Roves & Weeping Rust Accent
  drawAllClinkerRivets();

  // 7. Pale Grey Salt Crust & Encrusting Coastal Lichens
  drawSaltCrustAndLichen();

  // 8. Norwegian Shingle Beach, Haul-Out Timber Roller (Lunn) & Seaweed
  drawShingleBeachAndRoller();

  // 9. Final Museum Framing & Atmospheric Drypoint Unification
  drawFinalFinishingTouches();

  brush.noClip();
  noLoop();
}

// =============================================================================
// 1. BATCHED RAW-UMBER, SEPIA & TAR-BLACK UNDER-WASHES
// =============================================================================

function drawUnderWashes() {
  brush.noStroke();
  brush.noHatch();

  // Pass A: Atmospheric Nordic coastal mist & raw-umber ground washes
  brush.fill(PAL.mistLight, 75);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.25);
  drawPolyShape([
    [120, 0], [1080, 0], [1110, 1150], [90, 1150]
  ]);

  brush.fill(PAL.mistUmber, 58);
  brush.fillBleed(0.4, "out");
  drawPolyShape([
    [180, 60], [540, 0], [490, 960], [130, 1020]
  ]);
  drawPolyShape([
    [340, 880], [1120, 910], [1130, 1165], [80, 1165]
  ]);

  // Pass B: Base raw-umber washes for the 10 clinker strakes (batched)
  brush.fill(PAL.rawUmber, 105);
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.68, 0.42);
  for (let s = 0; s < 10; s += 2) {
    drawStrakeWashPolygon(s);
  }

  brush.fill(PAL.rawUmberD, 125);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.72, 0.48);
  for (let s = 1; s < 10; s += 2) {
    drawStrakeWashPolygon(s);
  }

  // Pass C: Deep sepia & pine-tar washes on lower hull, stempost & lap shadows
  brush.fill(PAL.sepiaDeep, 145);
  brush.fillBleed(0.14, "out");
  brush.fillTexture(0.75, 0.55);

  // Stempost main body wash
  let stemPts = [];
  for (let y = -10; y <= 1040; y += 65) {
    stemPts.push([stemFrontX(y), max(0, y)]);
  }
  for (let y = 1040; y >= -10; y -= 65) {
    stemPts.push([stemRabbetX(y) + 6, max(0, y)]);
  }
  drawPolyShape(stemPts);

  // Port bow cheek dark wash (left of stempost)
  let portPts = [];
  for (let v = 1.8; v <= 8.8; v += 0.7) {
    let p = portHullPoint(0.55, v);
    portPts.push([p.x, max(0, p.y)]);
  }
  for (let v = 8.8; v >= 1.8; v -= 0.7) {
    let yR = interpRabbetY(v) + 18;
    portPts.push([stemFrontX(yR) + 6, max(0, yR)]);
  }
  drawPolyShape(portPts);

  // Lower tar-soaked strakes (s = 6..9) extra dark pine-tar pass
  brush.fill(PAL.tarBlack, 130);
  brush.fillBleed(0.12, "in");
  for (let s = 6; s < 10; s++) {
    drawStrakeLapShadowBand(s, 0.52);
  }
  // Upper strakes thinner under-lap tar shadow band
  brush.fill(PAL.sepiaInk, 115);
  for (let s = 1; s < 6; s++) {
    drawStrakeLapShadowBand(s, 0.34);
  }

  // Pass D: Single Accent Under-Washes — Weeping Iron Oxide / Rust Bleeds
  brush.fill(PAL.rustWash, 68);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.6, 0.35);
  for (let s = 1; s <= 9; s++) {
    let numRivets = 15;
    for (let r = 1; r < numRivets; r++) {
      let hash = Math.sin(s * 37.3 + r * 19.7) * 43758.5453;
      let rng = hash - Math.floor(hash);
      if (rng < 0.38) {
        let u = (r + 0.2) / numRivets;
        let pTop = hullPoint(u, s - 0.16);
        if (pTop.y > 5 && pTop.y < 1030) {
          let dripLen = 24 + rng * 68;
          let w = 6 + rng * 8;
          drawPolyShape([
            [pTop.x - w * 0.5, pTop.y - 3],
            [pTop.x + w * 0.5, pTop.y - 2],
            [pTop.x + w * 0.35 - 3, pTop.y + dripLen],
            [pTop.x - w * 0.35 - 5, pTop.y + dripLen * 0.95]
          ]);
        }
      }
    }
  }

  brush.noFill();
}

function drawPolyShape(pts) {
  if (pts.length < 3) return;
  brush.beginShape(0.12);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawStrakeWashPolygon(s) {
  let pts = [];
  let steps = 14;
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let p = hullPoint(u, s);
    pts.push([p.x, max(-5, p.y)]);
  }
  for (let i = steps; i >= 0; i--) {
    let u = i / steps;
    let p = hullPoint(u, s + 1);
    pts.push([p.x, max(-5, p.y)]);
  }
  drawPolyShape(pts);
}

function drawStrakeLapShadowBand(s, bandFraction) {
  let pts = [];
  let steps = 12;
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let p = hullPoint(u, s);
    pts.push([p.x, max(-5, p.y)]);
  }
  for (let i = steps; i >= 0; i--) {
    let u = i / steps;
    let p = hullPoint(u, s + bandFraction);
    pts.push([p.x, max(-5, p.y)]);
  }
  drawPolyShape(pts);
}

// =============================================================================
// 2. INTERIOR FRAMING, GUNWALE & PORT CHEEK CLINKER SILHOUETTE STEPS
// =============================================================================

function drawInteriorBowAndGunwale() {
  // Above the sheer strake (v = 0) between x = 560 and x = 1015, y = 0..236,
  // we glimpse the shadowed interior of the opposite port bow & heavy oak rib.
  brush.noStroke();
  brush.fill(PAL.rawUmberD, 135);
  brush.fillBleed(0.15, "in");
  let intPts = [[545, 0], [965, 0], [1012, 232]];
  for (let u = 0.9; u >= 0.25; u -= 0.15) {
    let p = hullPoint(u, 0);
    if (p.y >= -5) intPts.push([p.x, max(0, p.y)]);
  }
  drawPolyShape(intPts);
  brush.noFill();

  // Interior port planking lines & heavy carved breasthook rib
  for (let k = 0; k < 28; k++) {
    let frac = k / 28;
    let yStart = frac * 175;
    let xStart = 555 + frac * 140;
    let xEnd = 940 + frac * 70;
    let yEnd = frac * 225;
    useBrush("gouge_fine", k % 3 === 0 ? PAL.tarBlack : PAL.sepiaInk, 0.85);
    brush.line(xStart, yStart, xEnd, yEnd);
  }

  // Heavy oak framing rib (spant) curving inside the upper bow
  for (let i = 0; i < 18; i++) {
    let offset = (i - 9) * 2.2;
    let col = i < 4 ? PAL.tarBlack : (i > 14 ? PAL.oakLight : PAL.sepiaInk);
    useBrush("gouge_deep", col, 0.9);
    let pts = [
      [735 + offset, 0, 0.8],
      [755 + offset, 58, 1.1],
      [788 + offset, 118, 0.9]
    ];
    brush.spline(pts, 0.35);
  }

  // Carved oak gunwale (esing) rail along v = 0
  let gunwaleSteps = 45;
  for (let layer = 0; layer < 8; layer++) {
    let vOff = -0.18 + (layer / 7) * 0.22;
    let col = layer < 2 ? PAL.oakCarve : (layer > 5 ? PAL.tarBlack : PAL.sepiaInk);
    useBrush(layer < 2 ? "carve_ridge" : "gouge_deep", col, 1.0);
    let pts = [];
    for (let i = 10; i <= gunwaleSteps; i++) {
      let u = i / gunwaleSteps;
      let p = hullPoint(u, vOff);
      if (p.y >= -2) {
        pts.push([p.x, p.y, 0.5 + 0.6 * Math.sin((i / gunwaleSteps) * Math.PI)]);
      }
    }
    if (pts.length > 2) brush.spline(pts, 0.3);
  }
}

function drawPortCheekClinkerSteps() {
  // Draw the foreshortened port strakes on the left of the stempost with exact stepped laps
  for (let s = 1; s < 9; s++) {
    let grainLines = 18;
    for (let g = 0; g <= grainLines; g++) {
      let v = s + (g / grainLines);
      let pts = [];
      for (let m = 0; m <= 12; m++) {
        let uP = (m / 12) * 0.72;
        let p = portHullPoint(uP, v);
        if (p.y >= 0 && p.y <= 1020) {
          pts.push([p.x, p.y, 0.4 + 0.7 * (1 - uP)]);
        }
      }
      if (pts.length > 2) {
        let isLap = g > grainLines - 3;
        let col = isLap ? PAL.tarBlack : (g % 3 === 0 ? PAL.sepiaDeep : PAL.rawUmberD);
        useBrush(isLap ? "gouge_deep" : "gouge_fine", col, isLap ? 1.15 : 0.8);
        brush.spline(pts, 0.3);
      }
    }

    // Sharp stepped clinker lap notch on the outer port silhouette
    let pOuterUpper = portHullPoint(0.58, s + 0.96);
    let pOuterLower = portHullPoint(0.54, s + 1.02);
    if (pOuterUpper.y > 10 && pOuterUpper.y < 980) {
      useBrush("gouge_deep", PAL.tarBlack, 1.3);
      brush.line(pOuterUpper.x - 9, pOuterUpper.y + 2, pOuterLower.x + 4, pOuterLower.y + 4);
      useBrush("carve_ridge", PAL.oakCarve, 0.9);
      brush.line(pOuterUpper.x - 9, pOuterUpper.y, pOuterUpper.x + 12, pOuterUpper.y - 5);
    }
  }
}

// =============================================================================
// 3. STARBOARD CLINKER STRAKES: CARVED WOOD GRAIN & INTERLACED SPIRAL KNOTS
// =============================================================================

function getPlankGrainDeflection(u, vRel, s) {
  let knots = STRAKE_KNOTS[s] || [];
  let dv = 0;
  let nearKnot = false;
  let minKnotDist = 999;

  for (let k = 0; k < knots.length; k++) {
    let kn = knots[k];
    let du = (u - kn.u) / kn.ru;
    let dvr = (vRel - kn.v) / kn.rv;
    let distSq = du * du + dvr * dvr;
    let dist = Math.sqrt(distSq);
    if (dist < minKnotDist) minKnotDist = dist;

    if (dist < 0.72) {
      nearKnot = true;
    }

    // Smooth fiber parting around knot + subtle swirl twist
    let gauss = Math.exp(-0.55 * distSq);
    let signV = dvr >= 0 ? 1 : -1;
    let part = signV * (0.24 * kn.rv) * gauss / (0.35 + Math.abs(dvr));
    let swirl = kn.dir * 0.065 * du * Math.exp(-0.85 * distSq);
    dv += part + swirl;
  }

  // Natural oak cathedral-arch figure along the plank
  let cathedral = 0.045 * Math.sin(u * Math.PI * 3.2 + s * 1.7) * Math.sin(vRel * Math.PI);
  let microWobble = 0.015 * (noise(u * 6.5, vRel * 4.2 + s * 10) - 0.5);

  return {
    v: constrain(vRel + dv + cathedral + microWobble, 0.02, 0.98),
    nearKnot,
    minKnotDist
  };
}

function drawClinkerStrakeCarving(s) {
  // Determine density of carved gouge lines across this strake
  let numGrainLines = 58;
  let uSteps = 54;

  for (let g = 0; g <= numGrainLines; g++) {
    let vBase = 0.03 + (g / numGrainLines) * 0.94;

    // March along u in carved gouge segments (simulating woodcarver's chisel cuts)
    let segPts = [];
    let segCounter = 0;
    let targetSegLen = 5 + Math.floor(random(0, 7));

    for (let i = 0; i <= uSteps; i++) {
      let u = i / uSteps;
      let defl = getPlankGrainDeflection(u, vBase, s);

      // Leave the immediate inner eye of knots open for the spiral knot generator
      if (defl.minKnotDist < 0.52) {
        if (segPts.length >= 3) {
          flushGougeSegment(segPts, s, vBase, defl.minKnotDist);
        }
        segPts = [];
        segCounter = 0;
        continue;
      }

      let pt = hullPoint(u, s + defl.v);
      if (pt.y < -3 || pt.y > 1065) {
        if (segPts.length >= 3) {
          flushGougeSegment(segPts, s, vBase, defl.minKnotDist);
        }
        segPts = [];
        segCounter = 0;
        continue;
      }

      let tSeg = segCounter / targetSegLen;
      let pressure = 0.35 + 0.95 * Math.sin(constrain(tSeg, 0, 1) * Math.PI);
      segPts.push([pt.x, pt.y, pressure]);
      segCounter++;

      if (segCounter >= targetSegLen || i === uSteps) {
        if (segPts.length >= 3) {
          flushGougeSegment(segPts, s, vBase, defl.minKnotDist);
        }
        // Slight overlap or chisel lift between gouge cuts
        segPts = i < uSteps ? [[pt.x, pt.y, 0.3]] : [];
        segCounter = 1;
        targetSegLen = 5 + Math.floor(random(0, 8));
      }
    }
  }

  // Draw the carved spiral knots and burl whorls on this strake
  let knots = STRAKE_KNOTS[s] || [];
  for (let k = 0; k < knots.length; k++) {
    drawCarvedSpiralKnot(s, knots[k]);
  }

  // Add weathered oak drying checks (splits along the grain near the stem hood-ends)
  let numChecks = 4;
  for (let c = 0; c < numChecks; c++) {
    let vCheck = 0.18 + 0.65 * ((c + 0.3 * (s % 3)) / numChecks);
    let uEnd = 0.08 + random(0.06, 0.16);
    let checkPts = [];
    for (let m = 0; m <= 8; m++) {
      let u = (m / 8) * uEnd;
      let defl = getPlankGrainDeflection(u, vCheck, s);
      let p = hullPoint(u, s + defl.v);
      if (p.y >= 0) {
        checkPts.push([p.x, p.y, 1.35 * (1 - m / 8)]);
      }
    }
    if (checkPts.length >= 3) {
      useBrush("gouge_deep", PAL.tarBlack, 1.15);
      brush.spline(checkPts, 0.25);
    }
  }
}

function flushGougeSegment(pts, s, vBase, knotDist) {
  let midPt = pts[Math.floor(pts.length / 2)];
  let uApprox = constrain((midPt[0] - 350) / 700, 0, 1);

  // Darken under the upper lap (vBase < 0.28) and on lower tarred strakes (s >= 6)
  let inLapShadow = vBase < 0.26;
  let nearBevelHighlight = vBase > 0.78 && vBase < 0.94;
  let r = random();

  let col = PAL.sepiaInk;
  let bName = "gouge_fine";
  let w = 0.85;

  if (inLapShadow) {
    col = r < 0.65 ? PAL.tarBlack : PAL.sepiaDeep;
    bName = "gouge_deep";
    w = 1.05;
  } else if (s >= 7) {
    col = r < 0.5 ? PAL.tarBlack : (r < 0.85 ? PAL.sepiaDeep : PAL.rawUmberD);
    bName = r < 0.45 ? "gouge_deep" : "gouge_fine";
    w = 0.95;
  } else if (knotDist < 1.15) {
    col = r < 0.55 ? PAL.sepiaDeep : PAL.tarBlack;
    bName = "gouge_deep";
    w = 0.95;
  } else {
    if (r < 0.32) {
      col = PAL.sepiaDeep;
      bName = "gouge_deep";
      w = 0.88;
    } else if (r < 0.76) {
      col = PAL.sepiaInk;
      bName = "gouge_fine";
      w = 0.82;
    } else {
      col = PAL.rawUmber;
      bName = "gouge_fine";
      w = 0.78;
    }
  }

  useBrush(bName, col, w);
  brush.spline(pts, 0.32);

  // Carved chisel ridge highlight immediately beside select gouge cuts
  if ((nearBevelHighlight && r < 0.42) || (!inLapShadow && r > 0.86 && uApprox < 0.82)) {
    let ridgePts = [];
    for (let i = 0; i < pts.length; i++) {
      ridgePts.push([pts[i][0], pts[i][1] - 1.4, pts[i][2] * 0.8]);
    }
    useBrush("carve_ridge", r > 0.93 ? PAL.oakCarve : PAL.oakLight, 0.75);
    brush.spline(ridgePts, 0.32);
  }
}

function drawCarvedSpiralKnot(s, kn) {
  let centerPt = hullPoint(kn.u, s + kn.v);
  if (centerPt.y < 5 || centerPt.y > 1030) return;

  // Double interlaced spiral curling from knot heart into surrounding wood grain
  for (let arm = 0; arm < 2; arm++) {
    let armPhase = arm * Math.PI;
    let totalTurns = 2.65;
    let steps = 42;
    let spiralPts = [];

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let angle = armPhase + kn.dir * t * totalTurns * Math.PI * 2;
      let rScale = Math.pow(t, 0.82);
      let uOff = Math.cos(angle) * kn.ru * 0.58 * rScale;
      let vOff = Math.sin(angle) * kn.rv * 0.62 * rScale;

      let p = hullPoint(kn.u + uOff, s + constrain(kn.v + vOff, 0.04, 0.96));
      let press = 0.35 + 1.05 * Math.sin(t * Math.PI);
      spiralPts.push([p.x, p.y, press]);

      // Break into carved spiral gouge arcs so it reads as hand-carved engraving
      if (spiralPts.length >= 11 || i === steps) {
        if (spiralPts.length >= 3) {
          useBrush(t < 0.5 ? "gouge_deep" : "gouge_fine", t < 0.45 ? PAL.tarBlack : PAL.sepiaDeep, 0.95);
          brush.spline(spiralPts, 0.38);

          // Adjacent pale carved ridge on outer turns
          if (t > 0.35 && arm === 0) {
            let hPts = spiralPts.map(q => [q[0] + 1.2, q[1] - 1.2, q[2] * 0.7]);
            useBrush("carve_ridge", PAL.oakLight, 0.7);
            brush.spline(hPts, 0.38);
          }
        }
        spiralPts = [[p.x, p.y, 0.35]];
      }
    }
  }

  // Concentric elliptical gouge rings framing the spiral eye
  for (let ring = 1; ring <= kn.rings; ring++) {
    let rf = 0.55 + (ring / kn.rings) * 0.52;
    let numArcs = 3;
    for (let a = 0; a < numArcs; a++) {
      let aStart = (a / numArcs) * Math.PI * 2 + ring * 0.4;
      let aEnd = aStart + (Math.PI * 2 / numArcs) * 0.76;
      let arcPts = [];
      for (let m = 0; m <= 8; m++) {
        let ang = lerp(aStart, aEnd, m / 8);
        let uP = kn.u + Math.cos(ang) * kn.ru * rf * 0.65;
        let vP = kn.v + Math.sin(ang) * kn.rv * rf * 0.68;
        let p = hullPoint(uP, s + constrain(vP, 0.03, 0.97));
        arcPts.push([p.x, p.y, 0.4 + 0.8 * Math.sin((m / 8) * Math.PI)]);
      }
      useBrush("gouge_fine", ring % 2 === 0 ? PAL.tarBlack : PAL.sepiaInk, 0.85);
      brush.spline(arcPts, 0.35);
    }
  }

  // Radial star-checks (cracks in the dense heartwood of the knot)
  for (let c = 0; c < 4; c++) {
    let ang = c * (Math.PI / 2) + 0.35 + kn.dir * 0.2;
    let pIn = hullPoint(kn.u + Math.cos(ang) * kn.ru * 0.06, s + kn.v + Math.sin(ang) * kn.rv * 0.06);
    let pOut = hullPoint(kn.u + Math.cos(ang) * kn.ru * 0.48, s + constrain(kn.v + Math.sin(ang) * kn.rv * 0.48, 0.05, 0.95));
    useBrush("gouge_deep", PAL.tarBlack, 1.15);
    brush.line(pIn.x, pIn.y, pOut.x, pOut.y);
  }
}

// =============================================================================
// 4. CLINKER PLANK LAP UNDERCUTS, BEVEL GOUGES & TAR CAULKING SEAMS
// =============================================================================

function drawPlankLapEdgeAndShadow(s) {
  let steps = 64;

  // A. Deep cast shadow & pine-tar caulking seam directly under lap s
  for (let pass = 0; pass < 4; pass++) {
    let yShift = 1.2 + pass * 2.1;
    let pts = [];
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let p = hullPoint(u, s);
      if (p.y >= -4 && p.y <= 1065) {
        pts.push([p.x, p.y + yShift, 0.7 + 0.5 * Math.sin(u * Math.PI)]);
      }
    }
    if (pts.length >= 3) {
      let col = pass < 2 ? PAL.tarBlack : PAL.sepiaDeep;
      useBrush("gouge_deep", col, 1.45 - pass * 0.22);
      brush.spline(pts, 0.3);
    }
  }

  // B. Short diagonal undercut shadow-hatching strokes beneath the lap step
  let hatchCount = 115;
  for (let h = 0; h <= hatchCount; h++) {
    let u = h / hatchCount;
    let pLap = hullPoint(u, s);
    if (pLap.y < 0 || pLap.y > 1055) continue;

    let pBelow = hullPoint(min(1, u + 0.012), s + 0.14 + 0.06 * noise(u * 12, s));
    useBrush("gouge_fine", h % 2 === 0 ? PAL.tarBlack : PAL.sepiaDeep, 0.92);
    brush.line(pLap.x, pLap.y + 1, pBelow.x, pBelow.y);
  }

  // C. The Overlapping Plank Bevel ("Land") of strake s-1 just above lap s
  let bevelCount = 96;
  for (let b = 0; b <= bevelCount; b++) {
    let u = b / bevelCount;
    let pBot = hullPoint(u, s);
    if (pBot.y < 0 || pBot.y > 1055) continue;

    let thick = lapStepThickness(u, s);
    // Short chisel-chamfer strokes across the thickness of the plank edge
    let xTop = pBot.x + 1.8;
    let yTop = pBot.y - thick;

    useBrush("gouge_fine", b % 3 === 0 ? PAL.sepiaDeep : PAL.rawUmberD, 0.78);
    brush.line(xTop, yTop, pBot.x, pBot.y);

    if (b % 2 === 0 && u < 0.88) {
      useBrush("carve_ridge", PAL.oakCarve, 0.75);
      brush.line(xTop, yTop, xTop - 0.8, yTop + thick * 0.45);
    }
  }

  // D. Upper arris highlight of the bevel (catches top light along the plank step)
  let arrisPts = [];
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let p = hullPoint(u, s);
    let thick = lapStepThickness(u, s);
    if (p.y >= 0 && p.y <= 1050) {
      arrisPts.push([p.x, p.y - thick, 0.45 + 0.65 * (1 - u * 0.6)]);
    }
  }
  if (arrisPts.length >= 3) {
    useBrush("carve_ridge", PAL.oakCarve, 0.95);
    brush.spline(arrisPts, 0.3);
  }

  // E. Stepped hood-end notch where plank lap s tucks into the stempost rabbet
  let pRab = hullPoint(0, s);
  if (pRab.y >= 5 && pRab.y <= 1030) {
    let thick = lapStepThickness(0, s);
    useBrush("gouge_deep", PAL.tarBlack, 1.4);
    brush.line(pRab.x - 7, pRab.y - thick, pRab.x + 3, pRab.y + 2);
    useBrush("carve_ridge", PAL.saltBright, 0.9);
    brush.line(pRab.x - 6, pRab.y - thick, pRab.x + 14, pRab.y - thick + 4);
  }
}

// =============================================================================
// 5. THE CARVED OAK STEMPOST, HOOKED SCARPH, IRON STEM-BAND & MOORING RING
// =============================================================================

function drawStempostAndIronwork() {
  // 1. Vertical heart-oak grain following the curve of the stempost
  let numStemFiles = 34;
  let yStep = 18;

  for (let f = 0; f <= numStemFiles; f++) {
    let frac = f / numStemFiles; // 0 = front cutwater, 1 = rabbet line
    let segPts = [];
    let segCount = 0;
    let maxSeg = 6 + Math.floor(random(0, 6));

    for (let y = -10; y <= 1042; y += yStep) {
      let xF = stemFrontX(y) + 12; // inside the iron stem-band
      let xR = stemRabbetX(y);

      // Slight grain deflection around stem knot at y = 390 and scarph at y = 830
      let knotDefl = 0;
      let dyKnot = (y - 390) / 52;
      let dxKnot = (frac - 0.56) / 0.24;
      let dSq = dyKnot * dyKnot + dxKnot * dxKnot;
      if (dSq < 2.2) {
        knotDefl = (dxKnot >= 0 ? 1 : -1) * 0.14 * Math.exp(-0.7 * dSq);
      }

      let x = lerp(xF, xR, constrain(frac + knotDefl, 0.02, 0.98));
      let press = 0.4 + 0.9 * Math.sin((segCount / maxSeg) * Math.PI);
      segPts.push([x, max(0, y), press]);
      segCount++;

      if (segCount >= maxSeg || y + yStep > 1042) {
        if (segPts.length >= 3) {
          let isBevelLine = Math.abs(frac - 0.24) < 0.06;
          let isRabbetGroove = frac > 0.88;
          let col = isRabbetGroove ? PAL.tarBlack : (isBevelLine ? PAL.oakCarve : (f % 2 === 0 ? PAL.sepiaDeep : PAL.sepiaInk));
          let bType = isBevelLine ? "carve_ridge" : (isRabbetGroove ? "gouge_deep" : "gouge_fine");
          useBrush(bType, col, isRabbetGroove ? 1.25 : 0.9);
          brush.spline(segPts, 0.3);
        }
        segPts = [[x, max(0, y), 0.35]];
        segCount = 1;
        maxSeg = 5 + Math.floor(random(0, 7));
      }
    }
  }

  // 2. Carved spiral knot on the oak stempost at y = 390
  let xKnotC = lerp(stemFrontX(390) + 12, stemRabbetX(390), 0.56);
  drawStemKnot(xKnotC, 390, 22, 38);

  // 3. Deep vertical weathering checks (fissures split into the ancient oak stem)
  let checks = [
    { y1: 40, y2: 265, frac: 0.48 },
    { y1: 180, y2: 340, frac: 0.72 },
    { y1: 455, y2: 695, frac: 0.42 },
    { y1: 620, y2: 810, frac: 0.66 },
    { y1: 870, y2: 1015, frac: 0.52 }
  ];
  for (let ch of checks) {
    let pts = [];
    for (let y = ch.y1; y <= ch.y2; y += 16) {
      let t = (y - ch.y1) / (ch.y2 - ch.y1);
      let x = lerp(stemFrontX(y) + 12, stemRabbetX(y), ch.frac + 0.03 * Math.sin(t * Math.PI * 2));
      pts.push([x, y, 1.45 * Math.sin(t * Math.PI)]);
    }
    useBrush("gouge_deep", PAL.tarBlack, 1.35);
    brush.spline(pts, 0.25);

    let hPts = pts.map(p => [p[0] + 1.8, p[1], p[2] * 0.75]);
    useBrush("carve_ridge", PAL.oakCarve, 0.85);
    brush.spline(hPts, 0.25);
  }

  // 4. Traditional Norwegian Hooked Scarph Joint (Skjerf / Lask) at y = 785..885
  let yS1 = 785, yS2 = 835, yS3 = 885;
  let xS1 = stemFrontX(yS1) + 12;
  let xMidA = lerp(stemFrontX(yS2) + 12, stemRabbetX(yS2), 0.58);
  let xMidB = lerp(stemFrontX(yS2) + 12, stemRabbetX(yS2), 0.36);
  let xS3 = stemRabbetX(yS3);

  useBrush("gouge_deep", PAL.tarBlack, 1.5);
  brush.line(xS1, yS1, xMidA, yS2);
  brush.line(xMidA, yS2, xMidB, yS2 - 8); // The hooked nib of the scarph
  brush.line(xMidB, yS2 - 8, xS3, yS3);

  useBrush("carve_ridge", PAL.oakCarve, 0.95);
  brush.line(xS1 + 1.5, yS1 + 2, xMidA + 1.5, yS2 + 2);
  brush.line(xMidB + 1.5, yS2 - 6, xS3 + 1.5, yS3 + 2);

  // 4 heavy scarph bolts with diamond iron roves & rust trails
  for (let b = 0; b < 4; b++) {
    let yB = 796 + b * 24;
    let fracB = b % 2 === 0 ? 0.32 : 0.68;
    let xB = lerp(stemFrontX(yB) + 14, stemRabbetX(yB), fracB);
    drawIronRivetDetailed(xB, yB, 6.8, 0.95, true, true);
  }

  // 5. Forged Iron Stem-Band (Stemjern) along the leading cutwater edge
  for (let y = 0; y <= 1035; y += 6) {
    let xF = stemFrontX(y);
    let xIn = xF + 12;
    let isRust = noise(y * 0.03) > 0.46;
    useBrush("gouge_deep", isRust ? PAL.rustDeep : PAL.tarBlack, 1.15);
    brush.line(xF, y, xIn, y + 2);

    if (y % 18 === 0) {
      // Metallic highlight on outer cutwater arris
      useBrush("carve_ridge", y > 820 ? PAL.saltBright : PAL.oakLight, 0.85);
      brush.line(xF + 1, y, xF + 1, y + 12);
    }
    if (y % 64 === 20) {
      // Countersunk stem-band iron spike & rust bleed
      drawIronRivetDetailed(xF + 6, y, 4.5, 0.8, true, true);
    }
  }

  // 6. Heavy Hand-Forged Iron Mooring Ring & Eye-Bolt at y = 515
  drawStemMooringRing(lerp(stemFrontX(515), stemRabbetX(515), 0.44), 515);
}

function drawStemKnot(cx, cy, rx, ry) {
  for (let t = 0; t < 38; t++) {
    let f = t / 38;
    let ang1 = f * Math.PI * 5;
    let ang2 = ang1 + 0.55;
    let x1 = cx + Math.cos(ang1) * rx * f;
    let y1 = cy + Math.sin(ang1) * ry * f;
    let x2 = cx + Math.cos(ang2) * rx * (f + 0.04);
    let y2 = cy + Math.sin(ang2) * ry * (f + 0.04);
    useBrush("gouge_deep", t % 2 === 0 ? PAL.tarBlack : PAL.sepiaDeep, 0.95);
    brush.line(x1, y1, x2, y2);
  }
}

function drawStemMooringRing(cx, cy) {
  // Cast shadow of the iron ring against the tarred oak stempost
  for (let a = 0; a < 360; a += 8) {
    let x1 = cx + 6 + Math.cos(a * Math.PI / 180) * 24;
    let y1 = cy + 32 + Math.sin(a * Math.PI / 180) * 29;
    let x2 = cx + 6 + Math.cos((a + 12) * Math.PI / 180) * 24;
    let y2 = cy + 32 + Math.sin((a + 12) * Math.PI / 180) * 29;
    useBrush("gouge_deep", PAL.tarBlack, 1.6);
    brush.line(x1, y1, x2, y2);
  }

  // Weeping rust stain beneath the eye-bolt
  for (let i = 0; i < 16; i++) {
    let xR = cx - 7 + i * 0.9;
    useBrush("gouge_fine", i % 2 === 0 ? PAL.rustCore : PAL.rustBright, 0.9);
    brush.line(xR, cy + 5, xR - 2, cy + 68 + random(0, 35));
  }

  // Forged iron ring body (layered torus strokes)
  for (let rOff = -3.5; rOff <= 3.5; rOff += 1.4) {
    let col = rOff < -1.5 ? PAL.oakCarve : (rOff > 1.5 ? PAL.tarBlack : PAL.rustDeep);
    useBrush(rOff < -1.5 ? "carve_ridge" : "gouge_deep", col, 1.15);
    let ringPts = [];
    for (let a = 0; a <= 360; a += 15) {
      let rad = a * Math.PI / 180;
      ringPts.push([
        cx + Math.cos(rad) * (24 + rOff),
        cy + 26 + Math.sin(rad) * (28 + rOff),
        0.9
      ]);
    }
    brush.spline(ringPts, 0.4);
  }

  // Heavy forged eye-bolt staple driven into the stempost
  drawIronRivetDetailed(cx, cy, 9.5, 1.0, true, true);
}

// =============================================================================
// 6. EXACT CLINKER IRON RIVETS, ROVES & WEEPING RUST ACCENT
// =============================================================================

function drawAllClinkerRivets() {
  // A. Hood-end pairs of heavy iron spikes along the stempost rabbet
  for (let s = 0; s < 10; s++) {
    for (let pair = 0; pair < 2; pair++) {
      let v = s + (pair === 0 ? 0.34 : 0.74);
      let p = hullPoint(0.022, v);
      if (p.y >= 8 && p.y <= 1030) {
        drawIronRivetDetailed(p.x, p.y, 5.8, 0.95, pair === 1, true);
      }
    }
  }

  // B. Clinker lap rivets (båtsaum) along the lower overlapping edge of every strake
  for (let s = 1; s <= 9; s++) {
    let numRivets = 16;
    for (let r = 1; r < numRivets; r++) {
      let u = (r + 0.15) / numRivets;
      // Positioned in the "land" (overlapping lower margin of strake s-1 just above lap s)
      let pLap = hullPoint(u, s);
      let thick = lapStepThickness(u, s);
      let rx = pLap.x + 1.2;
      let ry = pLap.y - thick - 6.5;

      if (ry < 6 || ry > 1035) continue;

      let foreshorten = hullForeshorten(u);
      let hash = Math.sin(s * 41.1 + r * 23.7) * 43758.5453;
      let rng = hash - Math.floor(hash);
      let hasWeepingRust = rng < 0.44;
      let isDiamondRove = (r + s) % 3 === 0;

      drawIronRivetDetailed(rx, ry, 5.2, foreshorten, hasWeepingRust, isDiamondRove);
    }
  }

  // C. Foreshortened rivets on the port bow cheek (left of stempost)
  for (let s = 2; s <= 8; s++) {
    for (let m = 1; m <= 3; m++) {
      let uP = m * 0.16;
      let p = portHullPoint(uP, s + 0.82);
      if (p.y > 10 && p.y < 970) {
        drawIronRivetDetailed(p.x, p.y, 4.4, 0.55, m === 2, false);
      }
    }
  }
}

function drawIronRivetDetailed(cx, cy, size, foreshorten, hasRust, isDiamond) {
  let rx = size * foreshorten;
  let ry = size;

  // 1. Crushed-oak hammer dimple around the iron head
  for (let side = -1; side <= 1; side += 2) {
    let dimplePts = [
      [cx - rx * 1.8, cy + side * 1.2, 0.3],
      [cx, cy + side * (ry * 1.35), 1.1],
      [cx + rx * 1.8, cy + side * 1.2, 0.3]
    ];
    useBrush("gouge_fine", PAL.tarBlack, 0.9);
    brush.spline(dimplePts, 0.35);
  }

  // 2. The Single Accent: Oxidized Iron Halo & Weeping Rust Streak
  if (hasRust) {
    let streakCount = 4 + Math.floor(random(0, 4));
    for (let k = 0; k < streakCount; k++) {
      let xOff = (k - streakCount / 2) * (rx * 0.42);
      let len = 14 + random(8, 42) * (k === Math.floor(streakCount / 2) ? 1.45 : 0.75);
      let col = k % 2 === 0 ? PAL.rustBright : (k % 3 === 0 ? PAL.rustCore : PAL.rustDeep);
      useBrush("gouge_fine", col, 0.88);
      brush.line(cx + xOff, cy + ry * 0.6, cx + xOff - 1.8, cy + len);
    }

    // Crusty orange-rust oxide flecks around the nail head
    useBrush("2B", PAL.rustBright, 0.85);
    for (let f = 0; f < 4; f++) {
      let ang = random(0, 360) * Math.PI / 180;
      let d = random(0.8, 1.45);
      brush.line(
        cx + Math.cos(ang) * rx * d,
        cy + Math.sin(ang) * ry * d,
        cx + Math.cos(ang) * rx * d + 1.8,
        cy + Math.sin(ang) * ry * d + 1.2
      );
    }
  }

  // 3. Forged square/diamond iron rove & central clenched nail boss
  let corners = isDiamond
    ? [
        [cx, cy - ry * 1.15],
        [cx + rx * 1.15, cy],
        [cx, cy + ry * 1.15],
        [cx - rx * 1.15, cy]
      ]
    : [
        [cx - rx * 0.88, cy - ry * 0.85],
        [cx + rx * 0.88, cy - ry * 0.78],
        [cx + rx * 0.85, cy + ry * 0.88],
        [cx - rx * 0.85, cy + ry * 0.82]
      ];

  // Fill iron head with tight dark cross-strokes
  useBrush("gouge_deep", PAL.tarBlack, 1.25);
  brush.line(corners[0][0], corners[0][1], corners[1][0], corners[1][1]);
  brush.line(corners[1][0], corners[1][1], corners[2][0], corners[2][1]);
  brush.line(corners[2][0], corners[2][1], corners[3][0], corners[3][1]);
  brush.line(corners[3][0], corners[3][1], corners[0][0], corners[0][1]);
  brush.line(corners[0][0], corners[0][1], corners[2][0], corners[2][1]);
  brush.line(corners[3][0], corners[3][1], corners[1][0], corners[1][1]);

  // 4. Forged iron facet glint (top-left bevel) & rust pit on central nail peen
  useBrush("carve_ridge", PAL.saltBright, 0.85);
  brush.line(corners[3][0], corners[3][1], corners[0][0], corners[0][1]);
  useBrush("gouge_fine", PAL.rustBright, 0.9);
  brush.line(cx - 1, cy - 1, cx + 1.5, cy + 1.2);
}

// =============================================================================
// 7. PALE GREY SALT CRUST & ENCRUSTING COASTAL LICHENS
// =============================================================================

function drawSaltCrustAndLichen() {
  // A. Crystalline pale-grey salt crust clinging to plank laps & lower hull grain ridges
  for (let s = 2; s <= 9; s++) {
    let saltDensity = s >= 6 ? 68 : 34;
    for (let i = 0; i < saltDensity; i++) {
      let u = random(0.02, 0.92);
      // Prefer accumulating just above the plank lap ledge or along grain checks
      let vRel = random() < 0.68 ? random(0.76, 0.96) : random(0.15, 0.65);
      let p = hullPoint(u, s + vRel);
      if (p.y < 10 || p.y > 1035) continue;

      let span = random(6, 22) * hullForeshorten(u);
      useBrush("salt_crust", i % 3 === 0 ? PAL.saltBright : PAL.saltGrey, random(0.55, 0.95));
      brush.line(p.x, p.y, p.x + span, p.y + span * 0.35);

      if (i % 4 === 0) {
        useBrush("carve_ridge", PAL.saltBright, 0.7);
        brush.line(p.x, p.y - 1, p.x + span * 0.65, p.y + span * 0.2);
      }
    }
  }

  // B. Salt crust along the stempost cutwater & scarph crevices
  for (let y = 120; y < 1010; y += 14) {
    if (random() < 0.58) {
      let x = lerp(stemFrontX(y) + 10, stemRabbetX(y), random(0.08, 0.85));
      useBrush("salt_crust", random() < 0.5 ? PAL.saltGrey : PAL.saltBright, 0.75);
      brush.line(x, y, x + random(3, 10), y + random(5, 16));
    }
  }

  // C. Encrusting coastal lichen rosettes (Pale grey Parmelia + occasional orange Xanthoria)
  let lichenClusters = 42;
  for (let c = 0; c < lichenClusters; c++) {
    let s = Math.floor(random(0, 7));
    let u = random(0.03, 0.78);
    let v = random(0.55, 0.94);
    let p = hullPoint(u, s + v);
    if (p.y < 15 || p.y > 960) continue;

    let isOrangeAccent = c % 6 === 0; // Subtle echo of the iron-oxide accent color
    let radius = random(4, 11);
    let petals = 7;

    for (let k = 0; k < petals; k++) {
      let ang = (k / petals) * Math.PI * 2 + random(-0.2, 0.2);
      let r1 = radius * random(0.3, 0.6);
      let r2 = radius * random(0.75, 1.15);
      let x1 = p.x + Math.cos(ang) * r1;
      let y1 = p.y + Math.sin(ang) * r1 * 0.75;
      let x2 = p.x + Math.cos(ang + 0.35) * r2;
      let y2 = p.y + Math.sin(ang + 0.35) * r2 * 0.75;

      let col = isOrangeAccent
        ? (k % 2 === 0 ? PAL.rustBright : PAL.rustCore)
        : (k % 2 === 0 ? PAL.saltBright : PAL.lichenGrey);
      useBrush("carve_ridge", col, 0.85);
      brush.line(x1, y1, x2, y2);
    }
    // Dark apothecia center inside lichen rosette
    useBrush("gouge_fine", PAL.sepiaDeep, 0.75);
    brush.circle(p.x, p.y, radius * 0.25, 0.3);
  }
}

// =============================================================================
// 8. NORWEGIAN SHINGLE BEACH, TIMBER ROLLER (LUNN) & BLADDERWRACK SEAWEED
// =============================================================================

function drawShingleBeachAndRoller() {
  // 1. Generate depth-sorted shingle beach cobbles (rullestein)
  let stones = [];
  let rows = 9;
  for (let r = 0; r < rows; r++) {
    let fr = r / (rows - 1);
    let yRow = 918 + Math.pow(fr, 1.15) * 232;
    let avgRx = 14 + fr * 29;
    let avgRy = 8 + fr * 16;

    let xCursor = 75 + (r % 2) * 18;
    while (xCursor < 1125) {
      let rx = avgRx * random(0.72, 1.32);
      let ry = avgRy * random(0.68, 1.22);
      let cx = xCursor + rx * 0.9;
      let cy = yRow + random(-avgRy * 0.35, avgRy * 0.35);

      // Avoid placing background stones inside the upper hull body above the keel line
      let inHull = false;
      if (cy < 1035 && cx > stemFrontX(cy) - 25 && cx < 910) {
        let uApprox = constrain((cx - 430) / 460, 0, 1);
        let pKeel = hullPoint(uApprox, 10);
        if (cy < pKeel.y - 6) inHull = true;
      }

      if (!inHull) {
        stones.push({
          cx, cy, rx, ry,
          tilt: random(-14, 14),
          tone: random()
        });
      }
      xCursor += rx * random(1.55, 1.95);
    }
  }

  // Batched watercolor under-washes for the shingle stones
  brush.noStroke();
  brush.fill(PAL.rawUmber, 88);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.65, 0.45);
  for (let i = 0; i < stones.length; i += 3) {
    drawStonePolygonWash(stones[i]);
  }

  brush.fill(PAL.sepiaInk, 105);
  for (let i = 1; i < stones.length; i += 3) {
    drawStonePolygonWash(stones[i]);
  }

  brush.fill(PAL.lichenGrey, 90);
  for (let i = 2; i < stones.length; i += 3) {
    drawStonePolygonWash(stones[i]);
  }
  brush.noFill();

  // 2. Draw the scarred Pine Haul-Out Roller (Lunningsstokk) wedged under the forefoot
  drawHaulOutRoller();

  // 3. Carved contour-hatching on every shingle cobble & dark interstitial crevices
  for (let st of stones) {
    // Skip stones directly occluded by the haul-out roller log
    if (st.cx > 325 && st.cx < 775 && st.cy > 1022 && st.cy < 1084) continue;
    drawCarvedShingleStone(st);
  }

  // 4. Tangled dried Bladderwrack Seaweed (Blæretang) & keel ground shadow
  drawKeelShadowAndSeaweed();
}

function drawStonePolygonWash(st) {
  let pts = [];
  let radTilt = st.tilt * Math.PI / 180;
  let cosT = Math.cos(radTilt), sinT = Math.sin(radTilt);
  for (let a = 0; a < 8; a++) {
    let ang = (a / 8) * Math.PI * 2;
    let lx = Math.cos(ang) * st.rx;
    let ly = Math.sin(ang) * st.ry;
    pts.push([
      st.cx + lx * cosT - ly * sinT,
      st.cy + lx * sinT + ly * cosT
    ]);
  }
  drawPolyShape(pts);
}

function drawCarvedShingleStone(st) {
  let radTilt = st.tilt * Math.PI / 180;
  let cosT = Math.cos(radTilt), sinT = Math.sin(radTilt);

  let toWorld = (lx, ly) => [
    st.cx + lx * cosT - ly * sinT,
    st.cy + lx * sinT + ly * cosT
  ];

  // Deep crevice shadow underneath the cobble
  let shadowPts = [];
  for (let i = 0; i <= 8; i++) {
    let ang = (0.08 + (i / 8) * 0.84) * Math.PI;
    let p = toWorld(Math.cos(ang) * st.rx * 1.03, Math.sin(ang) * st.ry * 1.06 + 2.2);
    shadowPts.push([p[0], p[1], 0.5 + 0.8 * Math.sin((i / 8) * Math.PI)]);
  }
  useBrush("gouge_deep", PAL.tarBlack, 1.25);
  brush.spline(shadowPts, 0.35);

  // Carved curved contour-hatching wrapping the 3D ellipsoid of the stone
  let numContours = Math.max(5, Math.floor(st.ry / 2.2));
  for (let c = 0; c <= numContours; c++) {
    let vf = -0.82 + (c / numContours) * 1.68; // -1 = top highlight, +1 = bottom shadow
    let spanX = st.rx * Math.sqrt(Math.max(0.05, 1 - vf * vf * 0.88));
    let archY = vf * st.ry + (1 - vf * vf) * st.ry * 0.22;

    let pts = [];
    for (let m = 0; m <= 6; m++) {
      let uf = -1 + (m / 6) * 2;
      let lx = uf * spanX;
      let ly = archY - (1 - uf * uf) * st.ry * 0.16;
      let wp = toWorld(lx, ly);
      pts.push([wp[0], wp[1], 0.35 + 0.75 * (1 - uf * uf)]);
    }

    if (vf < -0.38) {
      // Sun/sky-lit top crown of the stone: pale salt-grey & bone ridge
      useBrush("carve_ridge", c === 0 ? PAL.saltBright : PAL.oakCarve, 0.8);
      brush.spline(pts, 0.35);
    } else {
      let col = vf > 0.35 ? PAL.tarBlack : (st.tone < 0.45 ? PAL.sepiaDeep : PAL.rawUmberD);
      useBrush(vf > 0.4 ? "gouge_deep" : "gouge_fine", col, vf > 0.4 ? 0.95 : 0.78);
      brush.spline(pts, 0.35);
    }
  }

  // Quartz vein or salt-crust fleck on select Norwegian gneiss/granite cobbles
  if (st.tone > 0.68 && st.rx > 22) {
    let p1 = toWorld(-st.rx * 0.55, -st.ry * 0.15);
    let p2 = toWorld(st.rx * 0.48, st.ry * 0.22);
    useBrush("carve_ridge", PAL.saltBright, 0.95);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function drawHaulOutRoller() {
  // Timber roller (lunningsstokk) from (330, 1042) to (770, 1068), radius ~24px
  let x1 = 330, y1 = 1044;
  let x2 = 770, y2 = 1070;
  let rLog = 24;

  brush.noStroke();
  brush.fill(PAL.rawUmberD, 145);
  brush.fillBleed(0.12, "in");
  drawPolyShape([
    [x1, y1 - rLog], [x2, y2 - rLog],
    [x2 + 12, y2 + rLog], [x1 - 8, y1 + rLog]
  ]);
  brush.noFill();

  // Carved log grain & deep keel-friction gouges in the middle of the roller
  for (let g = 0; g <= 18; g++) {
    let f = (g / 18) * 2 - 1; // -1 top, +1 bottom
    let pts = [];
    for (let m = 0; m <= 16; m++) {
      let t = m / 16;
      let lx = lerp(x1, x2, t);
      let ly = lerp(y1, y2, t) + f * rLog;
      // Crushed depression around t = 0.28..0.48 where the iron-shod keel rests on the log
      if (t > 0.24 && t < 0.52 && f < 0.2) {
        ly += 6.5 * Math.sin(((t - 0.24) / 0.28) * Math.PI);
      }
      pts.push([lx, ly, 0.5 + 0.7 * Math.sin(t * Math.PI)]);
    }
    let col = f > 0.35 ? PAL.tarBlack : (f < -0.55 ? PAL.oakCarve : PAL.sepiaDeep);
    useBrush(f < -0.55 ? "carve_ridge" : "gouge_deep", col, f > 0.4 ? 1.25 : 0.9);
    brush.spline(pts, 0.3);
  }

  // End-grain spiral rings on the left sawn face of the roller log
  for (let ring = 1; ring <= 5; ring++) {
    let rf = ring / 5;
    let ringPts = [];
    for (let a = 0; a <= 360; a += 30) {
      let rad = a * Math.PI / 180;
      ringPts.push([
        x1 + Math.cos(rad) * 11 * rf,
        y1 + Math.sin(rad) * rLog * rf,
        0.8
      ]);
    }
    useBrush("gouge_fine", ring % 2 === 0 ? PAL.tarBlack : PAL.sepiaInk, 0.85);
    brush.spline(ringPts, 0.4);
  }
}

function drawKeelShadowAndSeaweed() {
  // Deep cast shadow where the forefoot & garboard strake meet the roller and shingle
  for (let i = 0; i < 65; i++) {
    let u = i / 65;
    let pKeel = hullPoint(u, 10);
    useBrush("gouge_deep", PAL.tarBlack, 1.35);
    brush.line(pKeel.x - 4, pKeel.y, pKeel.x - 16, pKeel.y + 14 + random(0, 12));
  }

  // Tangled strands of dried black/sepia Norwegian bladderwrack (blæretang) with air vesicles
  let clumps = [
    { x: 265, y: 1035, n: 14 },
    { x: 465, y: 1055, n: 18 },
    { x: 685, y: 1068, n: 15 },
    { x: 855, y: 1048, n: 12 }
  ];
  for (let cl of clumps) {
    for (let s = 0; s < cl.n; s++) {
      let pts = [];
      let curX = cl.x + random(-45, 45);
      let curY = cl.y + random(-14, 24);
      for (let m = 0; m < 6; m++) {
        pts.push([curX, curY, 0.5 + 0.7 * (1 - m / 6)]);
        curX += random(-18, 22);
        curY += random(4, 14);
      }
      useBrush("gouge_deep", s % 3 === 0 ? PAL.rustDeep : PAL.tarBlack, 1.0);
      brush.spline(pts, 0.45);

      // Bladderwrack paired vesicles (air bladders)
      let mid = pts[2];
      useBrush("gouge_fine", PAL.sepiaDeep, 0.85);
      brush.circle(mid[0], mid[1], 3.8, 0.25);
      useBrush("carve_ridge", PAL.oakLight, 0.65);
      brush.arc(mid[0], mid[1], 3.2, 200, 330);
    }
  }
}

