function drawFinalFinishingTouches() {
  // Fine drypoint atmospheric cross-hatching in the shadow behind the stempost (left)
  for (let y = 25; y < 920; y += 9) {
    let xEdge = stemFrontX(y);
    let span = 28 + 35 * Math.sin((y / 920) * Math.PI);
    useBrush("2H", PAL.rawUmberL, 0.65);
