// Utility: clean consecutive near-duplicate vertices for Polygon stability
function cleanPts(pts, minDist = 0.75) {
  if (!pts || pts.length === 0) return [];
  let out = [[pts[0][0], pts[0][1]]];
  for (let i = 1; i < pts.length; i++) {
    let prev = out[out.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (Math.hypot(dx, dy) >= minDist) {
      out.push([pts[i][0], pts[i][1]]);
    }
  }
  if (out.length > 2) {
    let first = out[0];
    let last = out[out.length - 1];
    if (Math.hypot(first[0] - last[0], first[1] - last[1]) < minDist) {
      out.pop();
    }
  }
  return out;
}

// Catmull-Rom / corner-aware polygon builder
// Points can be [x, y] (smooth) or [x, y, 1] (sharp corner)
function buildPoly(ctrl, steps = 8, closed = true) {
  let n = ctrl.length;
  if (n < 3) return cleanPts(ctrl);
  let res = [];
  let count = closed ? n : n - 1;
  for (let i = 0; i < count; i++) {
    let p0 = ctrl[(i - 1 + n) % n];
    let p1 = ctrl[i];
    let p2 = ctrl[(i + 1) % n];
    let p3 = ctrl[(i + 2) % n];
    if (!closed) {
      if (i === 0) p0 = p1;
      if (i + 2 >= n) p3 = p2;
    }
    let sharp1 = p1[2] === 1;
    let sharp2 = p2[2] === 1;
    if (sharp1 && sharp2) {
      res.push([p1[0], p1[1]]);
      continue;
    }
    let segSteps = steps;
    for (let s = 0; s < segSteps; s++) {
      let t = s / segSteps;
      let t2 = t * t;
      let t3 = t2 * t;
      let m0x = sharp1 ? (p2[0] - p1[0]) : 0.5 * (p2[0] - p0[0]);
      let m0y = sharp1 ? (p2[1] - p1[1]) : 0.5 * (p2[1] - p0[1]);
      let m1x = sharp2 ? (p2[0] - p1[0]) : 0.5 * (p3[0] - p1[0]);
      let m1y = sharp2 ? (p2[1] - p1[1]) : 0.5 * (p3[1] - p1[1]);
      let h00 = 2 * t3 - 3 * t2 + 1;
      let h10 = t3 - 2 * t2 + t;
      let h01 = -2 * t3 + 3 * t2;
      let h11 = t3 - t2;
      let x = h00 * p1[0] + h10 * m0x + h01 * p2[0] + h11 * m1x;
      let y = h00 * p1[1] + h10 * m0y + h01 * p2[1] + h11 * m1y;
      res.push([x, y]);
    }
  }
  if (!closed) {
    let last = ctrl[n - 1];
    res.push([last[0], last[1]]);
  }
  return cleanPts(res);
}

// Render a polygon with alcohol-marker wash, optional directional marker hatch, and optional contour stroke
function markerPoly(pts, opts = {}) {
  let cleaned = cleanPts(pts);
  if (cleaned.length < 3) return null;
  let poly = new brush.Polygon(cleaned);

  if (opts.washColor) {
    let op = opts.washOpacity !== undefined ? opts.washOpacity : 235;
    poly.wash(opts.washColor, op);
    brush.noWash();
  }

  if (opts.hatchColor && opts.hatchDist) {
    let hb = opts.hatchBrush || "chisel";
    let hw = opts.hatchWeight !== undefined ? opts.hatchWeight : 1.0;
    let ha = opts.hatchAngle !== undefined ? opts.hatchAngle : 35;
    let hopts = opts.hatchOpts || { rand: 0.03, continuous: true, gradient: 0.15 };
    brush.set(hb, opts.hatchColor, hw);
    brush.hatchStyle(hb, opts.hatchColor, hw);
    poly.hatch(opts.hatchDist, ha, hopts);
    brush.noHatch();
  }

  if (opts.strokeColor) {
    let sb = opts.strokeBrush || "fine_nib";
    let sw = opts.strokeWeight !== undefined ? opts.strokeWeight : 0.8;
    brush.set(sb, opts.strokeColor, sw);
    poly.draw(sb, opts.strokeColor, sw);
  }
  return poly;
}

// Helper for elliptical polygon points
function ellipsePts(cx, cy, rx, ry, rotDeg = 0, num = 36) {
  let pts = [];
  let rad = (rotDeg * Math.PI) / 180;
  let ca = Math.cos(rad);
  let sa = Math.sin(rad);
  for (let i = 0; i < num; i++) {
    let a = (i / num) * Math.PI * 2;
    let lx = Math.cos(a) * rx;
    let ly = Math.sin(a) * ry;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

// Safe spline wrapper ensuring brush state is set
function drawSpline(pts, brushName, col, weight = 1, curv = 0.5) {
  let cleaned = cleanPts(pts, 1.0);
  if (cleaned.length < 3) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.spline(cleaned, curv);
}

// Safe line wrapper
function drawLine(x1, y1, x2, y2, brushName, col, weight = 1) {
  if (Math.hypot(x2 - x1, y2 - y1) < 0.5) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
}

