function drawTabletop() {
  // Crisp tilted tabletop edge from (0, 575) to (1200, 490)
  let tablePoly = [[0, 575, 1], [1200, 490, 1], [1200, 1200, 1], [0, 1200, 1]];
  markerPoly(tablePoly, {
    washColor: "#FFF5FA",
    washOpacity: 250,
    hatchBrush: "alcohol_blend",
    hatchColor: PAL.pinkLight,
    hatchDist: 18,
    hatchAngle: -4,
    hatchWeight: 1.2
  });

  // Loud geometric kitsch tabletop stripes / perspective tiles in Bubblegum Pink, Sunlit Cream, and Cobalt-Cyan
  let numStripes = 9;
  for (let i = 0; i < numStripes; i++) {
    let t0 = i / numStripes;
    let t1 = (i + 0.52) / numStripes;
    let topX0 = -80 + t0 * 1360;
    let topX1 = -80 + t1 * 1360;
    let topY0 = 575 - ((topX0) / 1200) * 85;
    let topY1 = 575 - ((topX1) / 1200) * 85;
    let botX0 = -260 + t0 * 1720;
    let botX1 = -260 + t1 * 1720;

    let stripePts = [
      [constrain(topX0, 0, 1200), constrain(topY0, 490, 580), 1],
      [constrain(topX1, 0, 1200), constrain(topY1, 490, 580), 1],
      [constrain(botX1, 0, 1200), 1200, 1],
      [constrain(botX0, 0, 1200), 1200, 1]
    ];
    let col = i % 2 === 0 ? PAL.pinkLight : "#D6F6FF";
    let hCol = i % 2 === 0 ? PAL.pinkBright : PAL.cobSky;
    markerPoly(stripePts, {
      washColor: col,
      washOpacity: 155,
      hatchBrush: "chisel",
      hatchColor: hCol,
      hatchDist: 16,
      hatchAngle: -68,
      hatchWeight: 0.75
    });
  }

  // Intense noon-light hot zone across center tabletop
  markerPoly(
    ellipsePts(610, 780, 480, 230, -8, 36),
    { washColor: PAL.banSun, washOpacity: 75 }
  );

  // Razor-sharp table horizon trim line
  drawLine(0, 575, 1200, 490, "chisel", PAL.cobNight, 1.4);
  drawLine(0, 579, 1200, 494, "posca", PAL.white, 1.1);
}

