// ============================================================================
// 6. HYPERREAL BUNCH OF BANANAS (Draped over the radio, bruised & speckled)
// ============================================================================
function drawHyperrealBananas() {
  // Hard Noon Cast Shadow of the Bananas falling onto the Radio Top, Bezel, and Grille
  let bananaShadowOnRadio = buildPoly([
    [255, 555], [320, 512, 1], [625, 485, 1], [670, 595, 1],
    [615, 735, 1], [545, 720, 1], [525, 625],
    [455, 755, 1], [385, 745, 1], [365, 645],
    [295, 665, 1], [238, 630, 1]
  ], 6, true);
  markerPoly(bananaShadowOnRadio, {
    washColor: PAL.cobNight,
    washOpacity: 205,
    hatchBrush: "chisel",
    hatchColor: PAL.redDark,
    hatchDist: 7,
    hatchAngle: -15,
    hatchWeight: 0.9,
    strokeBrush: "fine_nib",
    strokeColor: PAL.redDeep,
    strokeWeight: 0.85
  });

  // Helper to render one multi-faceted, bruised, speckled hyperreal banana finger
  function renderBananaFinger(cfg) {
    let { topEdge, ridge1, ridge2, botEdge, tipPts, greenNeckPts, bounceCol, speckleSeed } = cfg;

    // 1. Dorsal Sunlit Facet (between topEdge and ridge1)
    let facetSunPts = buildPoly([...topEdge, ...ridge1.slice().reverse()], 7, true);
    markerPoly(facetSunPts, {
      washColor: PAL.banSun,
      washOpacity: 248,
      hatchBrush: "chisel",
      hatchColor: PAL.banBright,
      hatchDist: 7,
      hatchAngle: cfg.hatchAng || 25,
      hatchWeight: 0.85
    });

    // 2. Central Saturated Midtone Facet (between ridge1 and ridge2)
    let facetMidPts = buildPoly([...ridge1, ...ridge2.slice().reverse()], 7, true);
    markerPoly(facetMidPts, {
      washColor: PAL.banBright,
      washOpacity: 248,
      hatchBrush: "chisel",
      hatchColor: PAL.banMid,
      hatchDist: 6,
      hatchAngle: (cfg.hatchAng || 25) - 12,
      hatchWeight: 0.95
    });

    // 3. Lower Turning Core Shadow & Bounce-Light Facet (between ridge2 and botEdge)
    let facetShadePts = buildPoly([...ridge2, ...botEdge.slice().reverse()], 7, true);
    markerPoly(facetShadePts, {
      washColor: PAL.banAmber,
      washOpacity: 248,
      hatchBrush: "chisel",
      hatchColor: PAL.banOchre,
      hatchDist: 6,
      hatchAngle: (cfg.hatchAng || 25) - 20,
      hatchWeight: 0.95
    });

    // Warm lipstick-red / pink reflected bounce light along the bottom edge from the radio!
    drawSpline(botEdge, "alcohol_blend", bounceCol || PAL.redHighlight, 1.3, 0.4);
    drawSpline(ridge2, "chisel", PAL.bruiseLight, 0.9, 0.4);

    // Chartreuse-green unripe neck near the stem crown
    if (greenNeckPts) {
      markerPoly(buildPoly(greenNeckPts, 5, true), {
        washColor: PAL.banGreen,
        washOpacity: 210,
        hatchBrush: "fine_nib",
        hatchColor: PAL.banOlive,
        hatchDist: 6,
        hatchAngle: 45,
        hatchWeight: 0.75
      });
    }

    // Blinding noon highlight ribbon along the main upper ridge (ridge1)
    drawSpline(ridge1, "posca", PAL.white, 1.15, 0.4);
    drawSpline(topEdge, "fine_nib", PAL.banMid, 0.85, 0.4);
    drawSpline(botEdge, "rotring", PAL.bruiseDark, 0.95, 0.4);

    // Woody dark blossom tip at the distal end
    if (tipPts) {
      markerPoly(buildPoly(tipPts, 4, true), {
        washColor: PAL.bruiseDark,
        washOpacity: 248,
        strokeBrush: "rotring",
        strokeColor: PAL.black,
        strokeWeight: 0.9
      });
    }

    // 4. Hyperreal Bruises & Sugar Speckles along the facets
    randomSeed(speckleSeed);
    let len = ridge1.length;
    // Larger irregular ripe bruises along ridge1 and ridge2
    for (let b = 0; b < 6; b++) {
      let t = random(0.18, 0.85);
      let idx = Math.floor(t * (len - 1));
      let pA = ridge1[idx];
      let pB = ridge2[idx];
      let bx = lerp(pA[0], pB[0], random(0.1, 0.9)) + random(-10, 10);
      let by = lerp(pA[1], pB[1], random(0.1, 0.9)) + random(-10, 10);
      let rx = random(10, 24);
      let ry = random(5, 11);
      let rot = random(-40, 40);
      // Amber bruise halo
      markerPoly(ellipsePts(bx, by, rx * 1.35, ry * 1.35, rot, 14), {
        washColor: PAL.banOchre,
        washOpacity: 155
      });
      // Dark chocolate bruise core
      markerPoly(ellipsePts(bx, by, rx, ry, rot, 14), {
        washColor: b % 2 === 0 ? PAL.bruiseMid : PAL.bruiseDark,
        washOpacity: 225,
        hatchBrush: "fine_nib",
        hatchColor: PAL.bruiseDark,
        hatchDist: 4,
        hatchAngle: rot,
        hatchWeight: 0.65
      });
    }

    // 135+ Sugar Freckles & Leopard Spots per banana finger
    for (let s = 0; s < 135; s++) {
      let u = random(0.08, 0.94);
      let v = random(0.0, 1.0);
      let seg = u * (len - 1);
      let i0 = Math.floor(seg);
      let i1 = Math.min(len - 1, i0 + 1);
      let frac = seg - i0;

      let tx = lerp(topEdge[i0][0], topEdge[i1][0], frac);
      let ty = lerp(topEdge[i0][1], topEdge[i1][1], frac);
      let bx = lerp(botEdge[i0][0], botEdge[i1][0], frac);
      let by = lerp(botEdge[i0][1], botEdge[i1][1], frac);

      let sx = lerp(tx, bx, v) + random(-4, 4);
      let sy = lerp(ty, by, v) + random(-4, 4);
      let r = random(1.2, 4.8);
      if (random() < 0.16) r = random(5.0, 8.2);

      let col = random() < 0.55 ? PAL.bruiseDark : (random() < 0.5 ? PAL.bruiseMid : PAL.bruiseLight);
      markerPoly(ellipsePts(sx, sy, r, r * random(0.6, 1.2), random(180), 8), {
        washColor: col,
        washOpacity: 235
      });
    }
  }

  // BANANA 1: Back-Left Finger (arching from crown over left corner of radio)
  renderBananaFinger({
    topEdge: [[555, 345], [440, 340], [325, 385], [235, 470], [185, 555]],
    ridge1:  [[558, 358], [448, 362], [340, 412], [255, 492], [202, 570]],
    ridge2:  [[562, 372], [458, 388], [358, 442], [278, 515], [220, 582]],
    botEdge: [[568, 385], [470, 412], [378, 468], [298, 535], [238, 592]],
    greenNeckPts: [[555, 345, 1], [505, 342], [515, 392], [568, 385, 1]],
    tipPts: [[185, 555, 1], [172, 572, 1], [188, 592, 1], [238, 592, 1], [202, 570]],
    bounceCol: PAL.pinkBright,
    hatchAng: -25,
    speckleSeed: 101
  });

  // BANANA 5: Far-Right Finger (arching right toward the Guaraná bottle)
  renderBananaFinger({
    topEdge: [[605, 342], [685, 368], [748, 435], [782, 525], [770, 608]],
    ridge1:  [[595, 355], [668, 388], [726, 455], [756, 540], [748, 616]],
    ridge2:  [[585, 368], [648, 410], [700, 478], [728, 555], [725, 622]],
    botEdge: [[575, 382], [628, 430], [675, 498], [702, 568], [705, 626]],
    greenNeckPts: [[605, 342, 1], [645, 355], [615, 405], [575, 382, 1]],
    tipPts: [[770, 608, 1], [772, 628, 1], [742, 636, 1], [705, 626, 1], [748, 616]],
    bounceCol: PAL.guaGlow,
    hatchAng: 48,
    speckleSeed: 505
  });

  // BANANA 2: Upper-Left Foreground Finger (draping heavily over the left bezel of the radio)
  renderBananaFinger({
    topEdge: [[564, 355], [462, 378], [362, 438], [292, 528], [258, 622]],
    ridge1:  [[572, 368], [478, 402], [385, 468], [318, 552], [282, 636]],
    ridge2:  [[580, 382], [496, 428], [412, 498], [348, 578], [308, 648]],
    botEdge: [[588, 396], [512, 452], [435, 524], [374, 598], [330, 655]],
    greenNeckPts: [[564, 355, 1], [520, 366], [540, 418], [588, 396, 1]],
    tipPts: [[258, 622, 1], [252, 645, 1], [278, 662, 1], [330, 655, 1], [282, 636]],
    bounceCol: PAL.redHighlight,
    hatchAng: -32,
    speckleSeed: 202
