  // BANANA 4: Right-Center Finger (curving down over the right side of the tuning dial)
  renderBananaFinger({
    topEdge: [[598, 356], [645, 412], [668, 498], [662, 598], [628, 688]],
    ridge1:  [[586, 368], [622, 428], [640, 514], [634, 608], [602, 692]],
    ridge2:  [[574, 380], [596, 446], [610, 530], [602, 618], [576, 694]],
    botEdge: [[564, 392], [572, 462], [582, 545], [574, 625], [552, 692]],
