    botEdge: [[610, 396], [592, 472], [558, 568], [528, 655], [504, 724]],
    greenNeckPts: [[580, 362, 1], [552, 395], [598, 430], [610, 396, 1]],
    tipPts: [[422, 712, 1], [428, 738, 1], [468, 742, 1], [504, 724, 1], [452, 720]],
    bounceCol: PAL.redBright,
    hatchAng: -58,
