  // Colored-pencil ("cpencil") micro-crosshatching to enrich the hyperreal transitions
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // Warm ochre & crimson colored pencil grain on the banana ridges
  for (let i = 0; i < 18; i++) {
    let t = i / 17;
    let x1 = lerp(540, 445, t);
    let y1 = lerp(420, 680, t);
    drawLine(x1 - 12, y1 - 6, x1 + 14, y1 + 8, "cpencil", i % 2 === 0 ? PAL.banOchre : PAL.redBright, 0.85);
  }

  // Dazzling noon starburst glints on the brightest specular points (Bottle Cap, Radio Chrome, Bottle Shoulder, Parrot Eye)
  let starbursts = [
    [864, 214, 18], // Guaraná crown cap
    [908, 475, 22], // Guaraná glass shoulder
    [634, 496, 16], // Radio top-right chrome corner
    [484, 68, 15],  // Antenna ball tip
    [1018, 525, 16] // Plastic parrot head dome
  ];

  for (let sb of starbursts) {
    let [sx, sy, rad] = sb;
    drawLine(sx - rad, sy, sx + rad, sy, "posca", PAL.white, 1.15);
    drawLine(sx, sy - rad, sx, sy + rad, "posca", PAL.white, 1.15);
    drawLine(sx - rad * 0.6, sy - rad * 0.6, sx + rad * 0.6, sy + rad * 0.6, "posca", PAL.banSun, 0.85);
    drawLine(sx - rad * 0.6, sy + rad * 0.6, sx + rad * 0.6, sy - rad * 0.6, "posca", PAL.banSun, 0.85);
  }
}

// Hyperreal Cut-Crystal Whisky Tumbler with Refracted Marigold in Ice
// Rendered with p5.brush (layered watercolour washes + sharp coloured pencil)

function clipPolyHalfPlane(poly, ax, ay, bx, by, sign) {
  if (!poly || poly.length < 3) return [];
  let out = [];
  for (let i = 0; i < poly.length; i++) {
    let cur = poly[i];
    let prev = poly[(i + poly.length - 1) % poly.length];
    let dCur = ((bx - ax) * (cur[1] - ay) - (by - ay) * (cur[0] - ax)) * sign;
    let dPrev = ((bx - ax) * (prev[1] - ay) - (by - ay) * (prev[0] - ax)) * sign;
    if (dCur >= 0) {
      if (dPrev < 0) {
        let t = dPrev / (dPrev - dCur);
        out.push([
          prev[0] + t * (cur[0] - prev[0]),
          prev[1] + t * (cur[1] - prev[1])
        ]);
      }
      out.push(cur);
    } else if (dPrev >= 0) {
      let t = dPrev / (dPrev - dCur);
      out.push([
        prev[0] + t * (cur[0] - prev[0]),
        prev[1] + t * (cur[1] - prev[1])
      ]);
    }
  }
  return out;
}

function clipPolyToConvexBoundary(poly, boundary) {
  let res = poly;
  for (let i = 0; i < boundary.length; i++) {
    let a = boundary[i];
    let b = boundary[(i + 1) % boundary.length];
    res = clipPolyHalfPlane(res, a[0], a[1], b[0], b[1], 1);
    if (res.length < 3) return [];
  }
  return res;
}

function pointInConvexPolygon(x, y, boundary) {
  for (let i = 0; i < boundary.length; i++) {
    let a = boundary[i];
    let b = boundary[(i + 1) % boundary.length];
    if ((b[0] - a[0]) * (y - a[1]) - (b[1] - a[1]) * (x - a[0]) < 0) return false;
  }
  return true;
}

function pointInShard(x, y, faults, signs, cubeBoundary) {
  if (!pointInConvexPolygon(x, y, cubeBoundary)) return false;
  for (let k = 0; k < faults.length; k++) {
    let f = faults[k];
    let side = ((f[2] - f[0]) * (y - f[1]) - (f[3] - f[1]) * (x - f[0])) * signs[k];
    if (side < 0) return false;
  }
  return true;
}

function drawFreePoly(pts, curvature = 0.08, closeShape = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    if (pts[i].length > 2) {
      brush.vertex(pts[i][0], pts[i][1], pts[i][2]);
    } else {
      brush.vertex(pts[i][0], pts[i][1]);
    }
  }
  brush.endShape(closeShape);
}

function makeEllipseArc(cx, cy, rx, ry, a0, a1, steps, wobble = 0, pFn = null) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ang = a0 + (a1 - a0) * t;
    let rad = (ang * Math.PI) / 180;
    let n = wobble > 0 ? (noise(cx * 0.01 + Math.cos(rad) * 2, cy * 0.01 + Math.sin(rad) * 2) - 0.5) * wobble : 0;
    let x = cx + Math.cos(rad) * (rx + n);
    let y = cy + Math.sin(rad) * (ry + n * 0.35);
    if (pFn) {
      pts.push([x, y, pFn(t)]);
    } else {
      pts.push([x, y]);
    }
  }
  return pts;
}

function makeEllipsePoly(cx, cy, rx, ry, steps = 40, wobble = 0) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let rad = (ang * Math.PI) / 180;
    let n = wobble > 0 ? (noise(i * 0.25, cy * 0.01) - 0.5) * wobble : 0;
    pts.push([cx + Math.cos(rad) * (rx + n), cy + Math.sin(rad) * (ry + n * 0.35)]);
  }
  return pts;
}

function getTumblerHalfWidth(y) {
  // Subtle tapered heavy rocks tumbler from y=230 (rx=248) to y=920 (rx=214)
  let t = constrain((y - 230) / (920 - 230), 0, 1);
  return lerp(248, 214, Math.pow(t, 0.92));
}

function getTumblerEllipseRy(y) {
  let t = constrain((y - 230) / (920 - 230), 0, 1);
  return lerp(40, 56, t);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(88314);

  // Register custom sharp coloured pencil & crystalline prism brushes
  brush.add("sharp_cpencil", {
    type: "default",
    weight: 0.42,
    scatter: 0.14,
    sharpness: 0.86,
    grain: 18,
    opacity: 195,
    spacing: 0.11,
    pressure: [0.4, 1.15, 0.35],
    noise: 0.35
  });

  brush.add("prism_glaze", {
    type: "marker",
    weight: 2.2,
    scatter: 0.08,
    opacity: 42,
    spacing: 0.25,
    pressure: [0.7, 1.1, 0.7],
    markerTip: false,
    noise: 0.15
  });

  brush.add("fine_whisker", {
    type: "default",
    weight: 0.26,
    scatter: 0.06,
    sharpness: 0.94,
    grain: 12,
    opacity: 220,
    spacing: 0.09,
    pressure: [0.2, 1.0, 0.15],
    noise: 0.2
  });
}

function draw() {
