  brush.fill("#ffbe0b", 85);
  drawFreePoly(makeEllipsePoly(CX, 752, 250, 32, 32, 6), 0.1);
  brush.noFill();

  // =========================================================================
  // 2. RICH WALNUT WOOD GRAIN & COLOURED PENCIL TEXTURE ON BAR
  // =========================================================================
  // Perspective wood grain lines and cathedral walnut figures across the bar
  let grainColors = ["#120602", "#1c0b05", "#2d140a", "#4a2412", "#6b361b", "#8c4a27"];
  for (let row = 0; row < 165; row++) {
    let t = row / 165;
    let yBase = BAR_HORIZON_Y + Math.pow(t, 1.32) * (1205 - BAR_HORIZON_Y);
    let col = grainColors[row % grainColors.length];
    let w = lerp(0.25, 0.78, t) * random(0.75, 1.25);

    brush.set(row % 3 === 0 ? "sharp_cpencil" : "cpencil", col, w);

    let pts = [];
    let steps = 28;
    for (let s = 0; s <= steps; s++) {
      let sx = -20 + (s / steps) * 1240;
      // Walnut burl / cathedral arch wave around x = 350 and x = 860
      let arch1 = Math.exp(-Math.pow((sx - 320) / 220, 2)) * 22 * Math.sin(t * 9);
      let arch2 = Math.exp(-Math.pow((sx - 890) / 260, 2)) * 28 * Math.cos(t * 7);
      let n = (noise(sx * 0.004, yBase * 0.018) - 0.5) * lerp(8, 34, t);
      let py = yBase + arch1 + arch2 + n;
      let p = 0.5 + 0.5 * Math.sin((s / steps) * Math.PI);
      pts.push([sx, py, p]);
    }
    brush.spline(pts, 0.35);
  }

  // Fine specular wood pores catching the warm backlight
  for (let i = 0; i < 190; i++) {
    let px = random(40, 1160);
    let py = random(BAR_HORIZON_Y + 4, 1185);
    let t = (py - BAR_HORIZON_Y) / (1200 - BAR_HORIZON_Y);
    let distFromCenter = Math.abs(px - (CX + 80));
    let isLit = distFromCenter < 390;
    let poreCol = isLit
      ? (random() < 0.6 ? "#b86b28" : "#f5a623")
      : (random() < 0.7 ? "#3a1b0d" : "#5c2c16");
    brush.set("fine_whisker", poreCol, lerp(0.25, 0.55, t));
    let len = lerp(14, 52, t) * random(0.5, 1.3);
    brush.line(px, py, px + len, py + random(-1.5, 1.5));
  }

  // =========================================================================
  // 3. CAST SHADOW & PRISMATIC CAUSTIC SLIVERS ON THE WALNUT WOOD
  // =========================================================================
  // Shadow footprint cast forward-right and forward-left from the heavy glass base
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fill("#0e0401", 190);
  drawFreePoly(makeEllipsePoly(CX + 18, BASE_Y + 24, 265, 74, 40, 6), 0.08);
  brush.fill("#1a0903", 145);
  drawFreePoly(makeEllipsePoly(CX + 65, BASE_Y + 52, 370, 108, 44, 10), 0.08);
  brush.noFill();

  // Prismatic caustic slivers thrown by the cut-crystal facets onto the walnut bar
  // Sweeping out across the front-left, front, and especially front-right of the glass
  let causticSlivers = [
    // [angleDeg, rStart, rEnd, spreadStart, spreadEnd, washCol, pencilCol, iceEdgeCol]
    [16, 205, 550, 4, 22, "#ff7b00", "#ffbe0b", "#bce4ff"],
    [25, 200, 585, 5, 28, "#f59e0b", "#fff3b0", "#d8f3ff"],
    [35, 195, 560, 4, 24, "#ff5400", "#ffb703", "#90e0ef"],
    [46, 190, 520, 6, 32, "#ffb703", "#fffdf0", "#caf0f8"],
    [58, 185, 480, 5, 26, "#ff6d00", "#ffd166", "#a8dadc"],
    [71, 180, 440, 4, 20, "#e07a10", "#ffbe0b", "#d8f3ff"],
    [85, 175, 395, 4, 18, "#ff9100", "#ffe599", "#bce4ff"],
    [102, 175, 380, 4, 17, "#f59e0b", "#ffd166", "#caf0f8"],
    [118, 180, 415, 5, 21, "#ff6d00", "#ffbe0b", "#90e0ef"],
    [134, 190, 450, 4, 19, "#e07a10", "#ffe599", "#d8f3ff"],
    [149, 198, 470, 3, 15, "#c45108", "#f59e0b", "#a8dadc"],
    // Secondary crisp interior caustic arcs near the glass base
    [21, 185, 355, 3, 12, "#fff3b0", "#ffffff", "#e0f7ff"],
    [39, 182, 375, 3, 14, "#ffe599", "#ffffff", "#bce4ff"],
    [52, 178, 360, 3, 13, "#ffbe0b", "#fff3b0", "#d8f3ff"],
    [65, 174, 340, 3, 11, "#ff9100", "#ffe599", "#e0f7ff"],
    [110, 172, 320, 3, 11, "#ffb703", "#fff3b0", "#bce4ff"]
  ];

  for (let cs of causticSlivers) {
    let [ang, r0, r1, w0, w1, wCol, pCol, iceCol] = cs;
    let rad = (ang * Math.PI) / 180;
    let perpX = -Math.sin(rad);
    let perpY = Math.cos(rad) * 0.42;

    // Slight curvature to each caustic sliver
    let curveBend = Math.sin(rad * 2) * 18;
    let x0 = CX + Math.cos(rad) * r0;
    let y0 = (BASE_Y - 12) + Math.sin(rad) * (r0 * 0.36);
    let xm = CX + Math.cos(rad) * ((r0 + r1) * 0.5) + perpX * curveBend;
    let ym = (BASE_Y - 12) + Math.sin(rad) * ((r0 + r1) * 0.5 * 0.38) + perpY * curveBend;
    let x1 = CX + Math.cos(rad) * r1 + perpX * curveBend * 1.6;
    let y1 = (BASE_Y - 12) + Math.sin(rad) * (r1 * 0.4) + perpY * curveBend * 1.6;

    let sliverPoly = [
      [x0 - perpX * w0, y0 - perpY * w0],
      [xm - perpX * ((w0 + w1) * 0.55), ym - perpY * ((w0 + w1) * 0.55)],
      [x1 - perpX * w1, y1 - perpY * w1],
      [x1 + perpX * w1, y1 + perpY * w1],
      [xm + perpX * ((w0 + w1) * 0.55), ym + perpY * ((w0 + w1) * 0.55)],
      [x0 + perpX * w0, y0 + perpY * w0]
    ];

    // Luminous wash base
    brush.noStroke();
    brush.wash(wCol, 90);
    drawFreePoly(sliverPoly, 0.12);
    brush.noWash();

    // Coloured pencil hatching inside the caustic sliver following wood grain
