    brush.hatch(3.5, 4 + random(-3, 3), { rand: 0.08, gradient: 0.35 });
    drawFreePoly(sliverPoly, 0.12);
    brush.noHatch();

    // Cold blue-white dispersive chromatic fringe along one edge of the sliver
    brush.set("sharp_cpencil", iceCol, 0.52);
    brush.spline([
      [x0 - perpX * w0, y0 - perpY * w0, 0.9],
      [xm - perpX * ((w0 + w1) * 0.52), ym - perpY * ((w0 + w1) * 0.52), 0.8],
