    ...makeEllipseArc(CX, SHAM_TOP_Y - 55, rxSham - 10, rySham * 0.75, 0, 180, 22),
    ...makeEllipseArc(CX, SHAM_TOP_Y + 5, rxSham - 6, rySham, 180, 0, 22)
