  drawFreePoly(rightWhiskyWall, 0.08);
  drawFreePoly(bottomWhiskyPool, 0.08);

  // Blazing backlit honey-gold core in the center of the whisky
  brush.fillBleed(0.28, "out");
  brush.fill("#ffd166", 135);
  drawFreePoly(makeEllipsePoly(CX, 565, 168, 145, 36, 10), 0.1);
