  // Whisky Meniscus Ellipse (y = 392)
  let meniscusPoly = makeEllipsePoly(CX, MENISCUS_Y, rxMen - 5, ryMen, 44, 2);
  brush.fillBleed(0.15, "in");
  brush.fill("#f5a623", 120);
  drawFreePoly(meniscusPoly, 0.06);
  brush.fill("#ffe599", 95);
  drawFreePoly(makeEllipsePoly(CX, MENISCUS_Y, rxMen - 42, ryMen * 0.74, 38, 2), 0.06);
  brush.noFill();

  // =========================================================================
  // 5. THE FLOATING ICE CUBE: 3D GEOMETRY & INTERNAL CLEAVAGE PLANES
  // =========================================================================
  // Single large artisanal ice cube tilted in the whisky:
  // Upper crown emerges above the meniscus (y=312 to 392), lower body submerged (y=392 to 705)
  const ICE_CX = CX + 4;
  const ICE_CY = 516;

  // 6 vertices of the 3D tilted hexagonal projection of the large cube
  const V_TOP   = [ICE_CX - 8,  308];
  const V_TR    = [ICE_CX + 158, 366];
  const V_BR    = [ICE_CX + 148, 634];
  const V_BOT   = [ICE_CX + 6,  706];
  const V_BL    = [ICE_CX - 154, 622];
  const V_TL    = [ICE_CX - 162, 376];
  const V_FRONT = [ICE_CX + 8,  456]; // Central front corner where top, left, and right faces meet

  const cubeBoundary = [V_TOP, V_TR, V_BR, V_BOT, V_BL, V_TL];
  const iceTopFace   = [V_TOP, V_TR, V_FRONT, V_TL];
  const iceLeftFace  = [V_TL, V_FRONT, V_BOT, V_BL];
  const iceRightFace = [V_FRONT, V_TR, V_BR, V_BOT];

  // Watercolour & wash layers for the ice cube faces
  brush.noStroke();
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.52, 0.35);

  // Top face of the ice cube (catching cold blue-white light & pale honey rim)
  brush.fill("#dcf0ff", 145);
  drawFreePoly(iceTopFace, 0.06);
  brush.fill("#ffffff", 95);
  drawFreePoly([
    [lerp(V_TOP[0], V_FRONT[0], 0.15), lerp(V_TOP[1], V_FRONT[1], 0.15)],
    [lerp(V_TR[0], V_FRONT[0], 0.2), lerp(V_TR[1], V_FRONT[1], 0.2)],
    [V_FRONT[0], V_FRONT[1] - 10],
    [lerp(V_TL[0], V_FRONT[0], 0.2), lerp(V_TL[1], V_FRONT[1], 0.2)]
  ], 0.08);

  // Left submerged face (glacial cyan-blue blended with warm honey amber)
  brush.fill("#a8d8f8", 110);
  drawFreePoly(iceLeftFace, 0.06);
  brush.fill("#f59e0b", 85);
  drawFreePoly([
    [V_TL[0] + 18, V_TL[1] + 45],
    [V_FRONT[0] - 8, V_FRONT[1] + 15],
    [V_BOT[0] - 10, V_BOT[1] - 18],
    [V_BL[0] + 16, V_BL[1] - 12]
  ], 0.08);

  // Right submerged face (warmer honey-gold refraction with cold blue-white outer bevel)
  brush.fill("#ffbe0b", 105);
  drawFreePoly(iceRightFace, 0.06);
  brush.fill("#cce8ff", 95);
  drawFreePoly([
    [V_FRONT[0] + 12, V_FRONT[1] + 8],
    [V_TR[0] - 12, V_TR[1] + 22],
    [V_BR[0] - 14, V_BR[1] - 15],
    [V_BOT[0] + 12, V_BOT[1] - 25]
  ], 0.08);
  brush.noFill();

  // Coloured pencil shading on the ice cube facets before the marigold core
  brush.hatchStyle("cpencil", "#90c8f0", 0.45);
  brush.hatch(5.5, -24, { rand: 0.06, gradient: 0.4 });
  drawFreePoly(iceTopFace, 0.05);
  brush.noHatch();

  brush.hatchStyle("cpencil", "#72b4e8", 0.42);
  brush.hatch(6.5, 38, { rand: 0.07, gradient: 0.5 });
  drawFreePoly(iceLeftFace, 0.05);
  brush.noHatch();

  // =========================================================================
  // 6. THE FROZEN ORANGE MARIGOLD: FRACTURED BY REFRACTION ACROSS ICE SHARDS
  // =========================================================================
  // Define 3 internal optical fault planes slicing through the ice cube:
  // Fault 0: Main diagonal fracture from bottom-left to top-right
  // Fault 1: Steep cross-fissure from top-left-center to bottom-right-center
  // Fault 2: Upper sub-meniscus cleavage plane
  const FAULTS = [
    [ICE_CX - 170, ICE_CY + 78,  ICE_CX + 170, ICE_CY - 82],
    [ICE_CX - 78,  ICE_CY - 175, ICE_CX + 86,  ICE_CY + 175],
    [ICE_CX - 170, ICE_CY - 52,  ICE_CX + 170, ICE_CY - 22]
  ];

  // All 8 shard sign combinations (s0, s1, s2 in {-1, +1}), each with distinct
  // optical displacement (dx, dy), radial magnification (scale), angular shear (dAng),
  // ghost offset (gx, gy), and chromatic shift!
  const SHARDS = [
    { signs: [ 1,  1,  1], dx: -16, dy: -14, scale: 1.12, dAng: -9,  gx: -11, gy: -8,  tint: "cold" },
    { signs: [ 1,  1, -1], dx:  14, dy: -18, scale: 1.08, dAng:  11, gx:  12, gy: -9,  tint: "warm" },
    { signs: [ 1, -1,  1], dx: -19, dy:   9, scale: 1.16, dAng: -13, gx: -14, gy:  7,  tint: "cadmium" },
    { signs: [ 1, -1, -1], dx:   4, dy:  -6, scale: 1.03, dAng:   4, gx:   9, gy: -7,  tint: "honey" },
    { signs: [-1,  1,  1], dx:  18, dy:  12, scale: 1.15, dAng:  14, gx:  13, gy:  9,  tint: "warm" },
    { signs: [-1,  1, -1], dx:  -8, dy:  15, scale: 0.94, dAng:  -7, gx: -10, gy: 11,  tint: "cold" },
    { signs: [-1, -1,  1], dx:  22, dy:  -8, scale: 1.19, dAng:  16, gx:  15, gy: -6,  tint: "cadmium" },
    { signs: [-1, -1, -1], dx: -12, dy:  19, scale: 1.07, dAng: -11, gx: -11, gy: 12,  tint: "honey" }
  ];

  const FLOWER_CX = ICE_CX - 2;
  const FLOWER_CY = ICE_CY + 8;

  // Build the canonical 3D ruffled Tagetes (Marigold) blossom petals from outer ring to inner core
  // So we can project & clip every petal cleanly into all 8 refractive shards!
  let marigoldPetals = [];

  // Subtle dark olive-sepia stem receptacle tucked beneath the lower-left petals
  let calyxPetals = [
    { ang: 112, r0: 18, r1: 92, w0: 10, w1: 22, col: "#3d4a1d", edge: "#708238", dark: "#22290f" },
    { ang: 128, r0: 15, r1: 104, w0: 12, w1: 25, col: "#4a5723", edge: "#8fa347", dark: "#22290f" },
    { ang: 96,  r0: 18, r1: 86, w0: 9,  w1: 18, col: "#344016", edge: "#667830", dark: "#1b210b" }
  ];

  // 6 concentric tiers of ruffled marigold petals (from outer skirt to tight central pom-pom)
  const rings = [
    { count: 22, rMin: 24, rMax: 132, wMin: 11, wMax: 34, fillCol: "#b82302", washCol: "#d93804", strokeCol: "#6e0e00", tipCol: "#ff8800", highlightCol: "#ffb703" },
    { count: 20, rMin: 20, rMax: 112, wMin: 10, wMax: 31, fillCol: "#d93804", washCol: "#f25405", strokeCol: "#8a1800", tipCol: "#ff9e00", highlightCol: "#ffd166" },
    { count: 18, rMin: 16, rMax: 92,  wMin: 9,  wMax: 27, fillCol: "#f25405", washCol: "#ff6d00", strokeCol: "#9e2100", tipCol: "#ffb703", highlightCol: "#ffe599" },
    { count: 16, rMin: 12, rMax: 72,  wMin: 8,  wMax: 23, fillCol: "#ff6d00", washCol: "#ff8800", strokeCol: "#b02b00", tipCol: "#ffd166", highlightCol: "#fff3b0" },
    { count: 13, rMin: 7,  rMax: 50,  wMin: 7,  wMax: 18, fillCol: "#ff8800", washCol: "#ffaa00", strokeCol: "#c43c00", tipCol: "#ffe599", highlightCol: "#ffffff" },
    { count: 10, rMin: 2,  rMax: 28,  wMin: 5,  wMax: 13, fillCol: "#e05300", washCol: "#ffbe0b", strokeCol: "#801500", tipCol: "#fff3b0", highlightCol: "#ffffff" }
  ];

  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    let rg = rings[rIdx];
    for (let i = 0; i < rg.count; i++) {
      let baseAng = (i / rg.count) * 360 + rIdx * 19.5 + random(-6, 6);
      // Foreshorten slightly vertically because we view the flower somewhat side-on
      let rad = (baseAng * Math.PI) / 180;
      let perspectiveScale = 0.84 + 0.16 * Math.abs(Math.cos(rad));
      let len0 = rg.rMin * perspectiveScale;
      let len1 = rg.rMax * random(0.88, 1.1) * perspectiveScale;
      let w0 = rg.wMin * random(0.85, 1.15);
      let w1 = rg.wMax * random(0.88, 1.16);
      let curl = random(-14, 14);

      marigoldPetals.push({
        ring: rIdx,
        ang: baseAng,
        r0: len0,
        r1: len1,
        w0: w0,
        w1: w1,
        curl: curl,
        fillCol: rg.fillCol,
        washCol: rg.washCol,
        strokeCol: rg.strokeCol,
        tipCol: rg.tipCol,
        highlightCol: rg.highlightCol,
        seed: random(1000)
      });
    }
  }

  // Helper to build a ruffled marigold petal polygon and vein lines under a shard's optical transform
  function buildTransformedPetal(p, shard, isGhost = false) {
    let scale = shard.scale * (isGhost ? 1.05 : 1.0);
    let ang = p.ang + shard.dAng + (isGhost ? 4 : 0);
    let dx = shard.dx + (isGhost ? shard.gx : 0);
    let dy = shard.dy + (isGhost ? shard.gy : 0);

    let rad = (ang * Math.PI) / 180;
    let dirX = Math.cos(rad);
    let dirY = Math.sin(rad) * 0.88; // Slight perspective compression
    let perpX = -Math.sin(rad);
    let perpY = Math.cos(rad) * 0.88;

    let r0 = p.r0 * scale;
    let r1 = p.r1 * scale;
    let w0 = p.w0 * scale;
    let w1 = p.w1 * scale;
    let curl = p.curl * 0.65;

    let bx = FLOWER_CX + dx + dirX * r0;
    let by = FLOWER_CY + dy + dirY * r0;
    let mx = FLOWER_CX + dx + dirX * ((r0 + r1) * 0.55) + perpX * (curl * 0.4);
    let my = FLOWER_CY + dy + dirY * ((r0 + r1) * 0.55) + perpY * (curl * 0.4);
    let tx = FLOWER_CX + dx + dirX * r1 + perpX * curl;
    let ty = FLOWER_CY + dy + dirY * r1 + perpY * curl;

    // Ruffled fan-like marigold petal contour with characteristic notched outer ridge
    let poly = [
      [bx - perpX * w0 * 0.5, by - perpY * w0 * 0.5],
      [mx - perpX * w1 * 0.46, my - perpY * w1 * 0.46],
      [tx - perpX * w1 * 0.52 - dirX * 4, ty - perpY * w1 * 0.52 - dirY * 4],
      [tx - perpX * w1 * 0.28 + dirX * 5, ty - perpY * w1 * 0.28 + dirY * 5],
      [tx - perpX * w1 * 0.06 - dirX * 3, ty - perpY * w1 * 0.06 - dirY * 3],
      [tx + perpX * w1 * 0.18 + dirX * 6, ty + perpY * w1 * 0.18 + dirY * 6],
      [tx + perpX * w1 * 0.52 - dirX * 3, ty + perpY * w1 * 0.52 - dirY * 3],
      [mx + perpX * w1 * 0.46, my + perpY * w1 * 0.46],
      [bx + perpX * w0 * 0.5, by + perpY * w0 * 0.5]
    ];

    // Clip polygon against cube boundary and the 3 signed fault half-planes of this shard
    let clipped = clipPolyToConvexBoundary(poly, cubeBoundary);
    for (let k = 0; k < FAULTS.length; k++) {
      if (clipped.length < 3) break;
      let f = FAULTS[k];
      clipped = clipPolyHalfPlane(clipped, f[0], f[1], f[2], f[3], shard.signs[k]);
    }

    // Ruffled outer tip ridge points (indices 2..6 of unclipped poly)
    let tipRidge = [poly[2], poly[3], poly[4], poly[5], poly[6]];

    // 3 longitudinal petal veins for sharp coloured pencil striations
    let veins = [];
    for (let v = -1; v <= 1; v++) {
      let vf = v * 0.28;
      let vPts = [
        [bx + perpX * w0 * vf, by + perpY * w0 * vf],
        [mx + perpX * w1 * vf, my + perpY * w1 * vf],
        [tx + perpX * w1 * vf * 1.1, ty + perpY * w1 * vf * 1.1]
      ];
      veins.push(vPts);
    }

    return { clipped, tipRidge, veins };
  }

  // First: Lay down luminous watercolour washes for the marigold core inside the ice
  brush.noStroke();
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.62, 0.42);
  for (let sh of SHARDS) {
    let cx = FLOWER_CX + sh.dx;
    let cy = FLOWER_CY + sh.dy;
    let basePoly = makeEllipsePoly(cx, cy, 118 * sh.scale, 102 * sh.scale, 32, 10);
    basePoly = clipPolyToConvexBoundary(basePoly, cubeBoundary);
    for (let k = 0; k < FAULTS.length; k++) {
      basePoly = clipPolyHalfPlane(basePoly, FAULTS[k][0], FAULTS[k][1], FAULTS[k][2], FAULTS[k][3], sh.signs[k]);
    }
    if (basePoly.length >= 3) {
      brush.fill(sh.tint === "cold" ? "#ff7b00" : "#e84a00", 95);
      drawFreePoly(basePoly, 0.08);
    }
  }
  brush.noFill();

  // Render the calyx sepals in the lower-left shards
  for (let sh of SHARDS) {
    for (let cp of calyxPetals) {
      let fakeP = { ang: cp.ang, r0: cp.r0, r1: cp.r1, w0: cp.w0, w1: cp.w1, curl: -6 };
      let geom = buildTransformedPetal(fakeP, sh, false);
      if (geom.clipped.length >= 3) {
        brush.noStroke();
        brush.wash(cp.col, 145);
        drawFreePoly(geom.clipped, 0.06);
        brush.noWash();
        brush.set("sharp_cpencil", cp.dark, 0.45);
        drawFreePoly(geom.clipped, 0.06, true);
        brush.set("sharp_cpencil", cp.edge, 0.42);
        for (let v of geom.veins) {
          if (pointInShard(v[1][0], v[1][1], FAULTS, sh.signs, cubeBoundary)) {
            brush.spline(v, 0.25);
          }
        }
      }
    }
  }

  // PASS A: Render the DOUBLED / GHOST REFRACTION petals in each shard
  // (Creates the unmistakable birefringent optical doubling across internal ice fissures)
  for (let sh of SHARDS) {
    for (let i = 0; i < marigoldPetals.length; i += 2) {
      let p = marigoldPetals[i];
      let ghostGeom = buildTransformedPetal(p, sh, true);
      if (ghostGeom.clipped.length < 3) continue;

      let ghostWash = sh.tint === "cold" ? "#b8e2ff" : (sh.tint === "honey" ? "#ffd166" : "#ff8800");
      let ghostStroke = sh.tint === "cold" ? "#d8f3ff" : "#ffb703";

      brush.noStroke();
      brush.wash(ghostWash, 68);
      drawFreePoly(ghostGeom.clipped, 0.05);
      brush.noWash();

      brush.set("sharp_cpencil", ghostStroke, 0.36);
      drawFreePoly(ghostGeom.clipped, 0.05, true);
    }
  }

  // PASS B: Render the PRIMARY REFRACTED MARIGOLD PETALS across all 8 shards
  for (let sh of SHARDS) {
    for (let i = 0; i < marigoldPetals.length; i++) {
      let p = marigoldPetals[i];
      let geom = buildTransformedPetal(p, sh, false);
      if (geom.clipped.length < 3) continue;

      // 1. Rich cadmium / honey wash body
      let wCol = p.washCol;
      if (sh.tint === "cold" && p.ring < 2) wCol = "#e05300";
      if (sh.tint === "honey" && p.ring > 2) wCol = "#ffaa00";

      brush.noStroke();
      brush.wash(wCol, 155);
      drawFreePoly(geom.clipped, 0.05);
      brush.noWash();

      // 2. Coloured pencil tonal hatching inside the petal (cupped shadow at petal base)
      if (i % 2 === 0) {
        brush.hatchStyle("cpencil", p.fillCol, 0.38);
        brush.hatch(3.2, p.ang + sh.dAng, { rand: 0.06, gradient: 0.45 });
        drawFreePoly(geom.clipped, 0.05);
        brush.noHatch();
      }

      // 3. Sharp coloured pencil contour around the sliced/refracted petal polygon
      brush.set("sharp_cpencil", p.strokeCol, 0.44);
      drawFreePoly(geom.clipped, 0.05, true);

      // 4. Longitudinal petal veins in luminous honey or deep carmine
      brush.set("fine_whisker", p.tipCol, 0.36);
      for (let v of geom.veins) {
        if (
          pointInShard(v[0][0], v[0][1], FAULTS, sh.signs, cubeBoundary) &&
          pointInShard(v[2][0], v[2][1], FAULTS, sh.signs, cubeBoundary)
        ) {
          brush.spline(v, 0.25);
        }
      }

      // 5. Crisp crenellated ruffled petal tip highlight (if tip lies inside this shard)
      let tipMid = geom.tipRidge[2];
      if (pointInShard(tipMid[0], tipMid[1], FAULTS, sh.signs, cubeBoundary)) {
        let tipEdgeCol = (sh.tint === "cold" && i % 3 === 0) ? "#e0f4ff" : p.highlightCol;
        brush.set("sharp_cpencil", tipEdgeCol, 0.52);
        brush.spline(geom.tipRidge, 0.22);
      }
    }
  }

  // Tightly curled florets right at the marigold eye (split across the central shards)
  for (let sh of SHARDS) {
    for (let c = 0; c < 18; c++) {
      let ang = c * 20 + sh.dAng;
      let r = random(3, 18) * sh.scale;
      let fx = FLOWER_CX + sh.dx + Math.cos((ang * Math.PI) / 180) * r;
      let fy = FLOWER_CY + sh.dy + Math.sin((ang * Math.PI) / 180) * r * 0.85;
      if (pointInShard(fx, fy, FAULTS, sh.signs, cubeBoundary)) {
        brush.set("sharp_cpencil", c % 2 === 0 ? "#801500" : "#ffbe0b", 0.48);
        let arcPts = makeEllipseArc(fx, fy, 4.5, 3.5, ang, ang + 210, 6);
        brush.spline(arcPts, 0.3);
      }
    }
  }

  // =========================================================================
  // 7. INTERNAL ICE FISSURES, CLEAVAGE PLANES & TRAPPED BUBBLE TRAILS
  // =========================================================================
  // Render the 3 major internal fracture planes cutting through the ice & marigold
  for (let k = 0; k < FAULTS.length; k++) {
    let f = FAULTS[k];
    // Clip fault line to the ice cube boundary
    let steps = 36;
    let faultPts = [];
    let upperLipPts = [];
    let lowerLipPts = [];

    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let x = lerp(f[0], f[2], t);
      let y = lerp(f[1], f[3], t);
      // Organic crystalline step-fracture jitter
      let jitter = (noise(x * 0.02, y * 0.02, k * 10) - 0.5) * 14;
      let nx = -(f[3] - f[1]) / 340;
      let ny = (f[2] - f[0]) / 340;
      let px = x + nx * jitter;
      let py = y + ny * jitter;

      if (pointInConvexPolygon(px, py, cubeBoundary)) {
        let p = Math.sin(t * Math.PI);
        faultPts.push([px, py, 0.4 + 0.8 * p]);
        upperLipPts.push([px + nx * 4.5, py + ny * 4.5, 0.3 + 0.7 * p]);
        lowerLipPts.push([px - nx * 4.2, py - ny * 4.2, 0.3 + 0.7 * p]);
      }
    }

    if (faultPts.length > 3) {
      // Translucent cold blue-white veil along the internal cleavage ribbon
      let veilPoly = [
        ...upperLipPts.map(pt => [pt[0], pt[1]]),
        ...lowerLipPts.slice().reverse().map(pt => [pt[0], pt[1]])
      ];
      brush.noStroke();
      brush.wash("#d8f3ff", 85);
      drawFreePoly(veilPoly, 0.08);
      brush.noWash();

      // Feather-crack hackle marks radiating briefly from the fracture plane
      for (let h = 2; h < faultPts.length - 2; h += 2) {
        let pt = faultPts[h];
        let hAng = atan2(f[3] - f[1], f[2] - f[0]) + (h % 4 === 0 ? 52 : -48);
        let hLen = random(10, 28);
        let hx = pt[0] + Math.cos((hAng * Math.PI) / 180) * hLen;
        let hy = pt[1] + Math.sin((hAng * Math.PI) / 180) * hLen;
        brush.set("fine_whisker", h % 3 === 0 ? "#ffbe0b" : "#bce4ff", 0.34);
        brush.line(pt[0], pt[1], hx, hy);
      }

      // Refracted cadmium-orange edge on one side of the fissure
      brush.set("sharp_cpencil", "#ff7b00", 0.52);
      brush.spline(lowerLipPts, 0.25);

      // Glacial blue-white shadow edge on the opposite side
      brush.set("sharp_cpencil", "#7ab8e8", 0.5);
      brush.spline(upperLipPts, 0.25);

      // Razor-sharp pure white crystalline fracture core
      brush.set("fine_whisker", "#ffffff", 0.68);
      brush.spline(faultPts, 0.22);
    }
  }

  // Secondary branching micro-fissures inside the ice cube
  for (let m = 0; m < 18; m++) {
    let startPt = [
      FLOWER_CX + random(-115, 115),
      FLOWER_CY + random(-135, 125)
    ];
    if (!pointInConvexPolygon(startPt[0], startPt[1], cubeBoundary)) continue;
    let mPts = [[startPt[0], startPt[1], 0.9]];
    let curX = startPt[0];
    let curY = startPt[1];
    let ang = random(360);
    for (let seg = 0; seg < 5; seg++) {
      ang += random(-32, 32);
      curX += Math.cos((ang * Math.PI) / 180) * random(12, 26);
      curY += Math.sin((ang * Math.PI) / 180) * random(12, 26);
      if (!pointInConvexPolygon(curX, curY, cubeBoundary)) break;
      mPts.push([curX, curY, 1.0 - seg * 0.18]);
    }
    if (mPts.length >= 3) {
      brush.set("fine_whisker", m % 2 === 0 ? "#e6f6ff" : "#ffd166", 0.38);
      brush.spline(mPts, 0.2);
    }
  }

  // TRAPPED BUBBLE TRAILS: Streams of silvery-blue air bubbles frozen around the marigold
  // and rising toward the upper-center of the ice cube
  let bubbleTrails = 28;
  for (let t = 0; t < bubbleTrails; t++) {
    let startAng = (t / bubbleTrails) * 360 + random(-8, 8);
    let rStart = random(28, 122);
    let bx = FLOWER_CX + Math.cos((startAng * Math.PI) / 180) * rStart;
    let by = FLOWER_CY + Math.sin((startAng * Math.PI) / 180) * rStart * 0.85;

    // Trail curves outward and upward toward the ice crown
    let numBubbles = floor(random(6, 14));
    for (let b = 0; b < numBubbles; b++) {
      let frac = b / numBubbles;
      let radOut = rStart + frac * random(35, 78);
      let driftUp = frac * random(25, 68);
      let wobbleX = Math.sin(frac * 8 + t) * 7;
      let px = FLOWER_CX + Math.cos((startAng * Math.PI) / 180) * radOut + wobbleX;
      let py = FLOWER_CY + Math.sin((startAng * Math.PI) / 180) * radOut * 0.85 - driftUp;

      if (!pointInConvexPolygon(px, py, cubeBoundary)) continue;

      let bRad = lerp(3.8, 1.3, frac) * random(0.8, 1.25);

      // Elongated teardrop/spherical trapped air bubble
      brush.noStroke();
      brush.wash("#d8f3ff", 140);
      drawFreePoly(makeEllipsePoly(px, py, bRad, bRad * 1.25, 10), 0.1);
      brush.noWash();

      // Dark amber/indigo refractive rim
      brush.set("fine_whisker", "#5c2804", 0.3);
      brush.circle(px, py, bRad, 0.08);

      // Bright cold blue-white pinpoint glint
      brush.set("fine_whisker", "#ffffff", 0.45);
      brush.line(px - bRad * 0.35, py - bRad * 0.4, px + bRad * 0.15, py - bRad * 0.15);
    }
  }

  // =========================================================================
  // 8. ICE CUBE RIDGES & WHISKY MENISCUS INTERSECTION RING
  // =========================================================================
  // Crisp bevelled ridges of the floating ice cube
  let iceEdges = [
    [V_TOP, V_TR, "#ffffff", 0.72],
    [V_TOP, V_TL, "#e0f4ff", 0.68],
    [V_TL, V_FRONT, "#ffffff", 0.82],
    [V_TR, V_FRONT, "#d8f3ff", 0.78],
    [V_FRONT, V_BOT, "#bce4ff", 0.65],
    [V_TL, V_BL, "#90c8f0", 0.58],
    [V_TR, V_BR, "#ffe599", 0.62],
    [V_BL, V_BOT, "#ffb703", 0.55],
    [V_BR, V_BOT, "#ff9100", 0.58]
  ];

  for (let ie of iceEdges) {
    let [p0, p1, col, w] = ie;
    let edgePts = [];
    for (let s = 0; s <= 16; s++) {
      let t = s / 16;
      let x = lerp(p0[0], p1[0], t) + (noise(s * 0.3, p0[1] * 0.01) - 0.5) * 6;
      let y = lerp(p0[1], p1[1], t) + (noise(s * 0.3, p0[0] * 0.01) - 0.5) * 6;
      edgePts.push([x, y, 0.4 + 0.7 * Math.sin(t * Math.PI)]);
    }
    brush.set("sharp_cpencil", "#7ab8e8", w * 1.15);
    brush.spline(edgePts, 0.25);
    brush.set("fine_whisker", col, w * 0.85);
    brush.spline(edgePts, 0.25);
  }

  // Front meniscus arc of the whisky & glowing surface tension collar around the emerging ice cube
  let backMeniscusPts = makeEllipseArc(CX, MENISCUS_Y, rxMen - 5, ryMen, 180, 360, 32, 3, (t) => 0.4 + 0.6 * Math.sin(t * Math.PI));
  let frontMeniscusPts = makeEllipseArc(CX, MENISCUS_Y, rxMen - 5, ryMen, 0, 180, 36, 3, (t) => 0.5 + 0.6 * Math.sin(t * Math.PI));

  brush.set("sharp_cpencil", "#c45108", 0.55);
  brush.spline(backMeniscusPts, 0.3);
  brush.set("fine_whisker", "#ffe599", 0.52);
  brush.spline(makeEllipseArc(CX, MENISCUS_Y + 2, rxMen - 8, ryMen - 2, 190, 350, 28, 2), 0.3);

  // Liquid meniscus collar clinging to the ice cube at y ~ 392
  let iceCollarPts = [
    [ICE_CX - 160, MENISCUS_Y - 6, 0.5],
    [ICE_CX - 85,  MENISCUS_Y + 18, 0.9],
    [ICE_CX + 6,   MENISCUS_Y + 24, 1.1],
    [ICE_CX + 92,  MENISCUS_Y + 16, 0.9],
    [ICE_CX + 156, MENISCUS_Y - 8, 0.5]
  ];
  brush.set("sharp_cpencil", "#ff9100", 0.68);
  brush.spline(iceCollarPts, 0.35);
  brush.set("fine_whisker", "#ffffff", 0.62);
  brush.spline(iceCollarPts.map(pt => [pt[0], pt[1] - 2.5, pt[2]]), 0.35);

  // Front meniscus rim of the whisky (double-ringed amber & cold blue-white highlight)
  brush.set("sharp_cpencil", "#9c3304", 0.65);
  brush.spline(frontMeniscusPts, 0.3);
  brush.set("sharp_cpencil", "#ffbe0b", 0.58);
  brush.spline(makeEllipseArc(CX, MENISCUS_Y - 2, rxMen - 7, ryMen - 1, 6, 174, 32, 2), 0.3);
  brush.set("fine_whisker", "#e8f6ff", 0.52);
  brush.spline(makeEllipseArc(CX, MENISCUS_Y - 4, rxMen - 10, ryMen - 3, 18, 162, 28, 1.5), 0.3);

  // =========================================================================
  // 9. HEAVY CUT-CRYSTAL BASE (SHAM) & GEOMETRIC CUT FACETS
  // =========================================================================
  // First: The thick solid crystal base (sham) from y = 768 to y = 918
  // Acts like a massive optical lens trapping bands of dark walnut, blazing amber, and ice blue
  let shamPoly = [
    ...makeEllipseArc(CX, SHAM_TOP_Y, rxSham, rySham, 0, 180, 28),
    ...makeEllipseArc(CX, BASE_Y, rxBase, ryBase, 180, 0, 28)
  ];

  brush.noStroke();
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.5, 0.35);
  brush.fill("#d8ecfa", 85);
  drawFreePoly(shamPoly, 0.05);

  // Internal elliptical optical rings inside the heavy crystal sham
  let shamBands = [
    { y: 785, rx: rxSham - 14, ry: rySham * 0.88, col: "#3d1606", op: 155 },
    { y: 812, rx: rxSham - 22, ry: rySham * 0.84, col: "#ff7b00", op: 140 },
    { y: 836, rx: rxBase - 18, ry: ryBase * 0.78, col: "#ffd166", op: 150 },
    { y: 862, rx: rxBase - 12, ry: ryBase * 0.86, col: "#260e04", op: 165 },
    { y: 888, rx: rxBase - 8,  ry: ryBase * 0.92, col: "#bce4ff", op: 130 },
    { y: 906, rx: rxBase - 16, ry: ryBase * 0.76, col: "#ff9100", op: 135 }
  ];

  for (let sb of shamBands) {
    let bandPoly = [
      ...makeEllipseArc(CX, sb.y - 11, sb.rx, sb.ry, 8, 172, 24),
      ...makeEllipseArc(CX, sb.y + 11, sb.rx * 0.98, sb.ry * 1.02, 172, 8, 24)
    ];
    brush.wash(sb.col, sb.op);
    drawFreePoly(bandPoly, 0.06);
    brush.noWash();
  }
  brush.noFill();

  // Geometric Cut-Crystal Facets around the lower half of the tumbler (y = 532 to y = 895)
  // Classic rocks glass diamond-and-wedge cut pattern
  const CUT_Y0 = 532; // Upper crown of wedge cuts
  const CUT_Y1 = 648; // Mid diamond equator
  const CUT_Y2 = 768; // Sham shoulder
  const CUT_Y3 = 892; // Lower base bevels

  const NUM_COLS = 8; // 8 facet columns across the visible front hemisphere (10 deg to 170 deg)
  function getCylPoint(colFloat, yLevel) {
    let ang = 8 + (colFloat / NUM_COLS) * 164;
    let rad = (ang * Math.PI) / 180;
    let rx = getTumblerHalfWidth(yLevel);
    let ry = getTumblerEllipseRy(yLevel);
    return [
      CX + Math.cos(rad) * rx,
      yLevel + Math.sin(rad) * ry
    ];
  }

  for (let c = 0; c < NUM_COLS; c++) {
    // Vertices for this column's diamond & wedge cut crystal cell
    let pTopL  = getCylPoint(c,       CUT_Y0 + 22);
    let pTopM  = getCylPoint(c + 0.5, CUT_Y0 - 18);
    let pTopR  = getCylPoint(c + 1,   CUT_Y0 + 22);

    let pMidL  = getCylPoint(c,       CUT_Y1);
    let pMidM  = getCylPoint(c + 0.5, CUT_Y1);
    let pMidR  = getCylPoint(c + 1,   CUT_Y1);

    let pShamL = getCylPoint(c,       CUT_Y2);
    let pShamM = getCylPoint(c + 0.5, CUT_Y2);
    let pShamR = getCylPoint(c + 1,   CUT_Y2);

    let pBotL  = getCylPoint(c,       CUT_Y3);
    let pBotM  = getCylPoint(c + 0.5, CUT_Y3 + 10);
    let pBotR  = getCylPoint(c + 1,   CUT_Y3);

    // 4 bevel triangles of the upper diamond (between CUT_Y0 and CUT_Y2, centered at pMidM)
    let bevels = [
      // Upper-left bevel
      { pts: [pTopM, pMidM, pMidL], col: c % 2 === 0 ? "#e0f4ff" : "#ffd166", op: 58, hatchAng: 32, pCol: "#ffffff" },
      // Upper-right bevel
      { pts: [pTopM, pMidR, pMidM], col: c % 2 === 0 ? "#ff9100" : "#bce4ff", op: 52, hatchAng: -32, pCol: "#ffbe0b" },
      // Lower-left bevel
      { pts: [pMidL, pMidM, pShamM], col: c % 2 === 0 ? "#4a1904" : "#ff6d00", op: 64, hatchAng: -45, pCol: "#f59e0b" },
      // Lower-right bevel
      { pts: [pMidM, pMidR, pShamM], col: c % 2 === 0 ? "#ffbe0b" : "#381203", op: 60, hatchAng: 45, pCol: "#e0f4ff" },
      // Flanking lower-left wedge
      { pts: [pMidL, pShamM, pShamL], col: "#cce8ff", op: 48, hatchAng: 15, pCol: "#90c8f0" },
      // Flanking lower-right wedge
      { pts: [pMidR, pShamR, pShamM], col: "#ff7b00", op: 48, hatchAng: -15, pCol: "#ffd166" },
      // Heavy crystal sham vertical bevels (between CUT_Y2 and CUT_Y3)
      { pts: [pShamL, pShamM, pBotM, pBotL], col: c % 2 === 0 ? "#2b0f04" : "#e8f6ff", op: 68, hatchAng: 85, pCol: "#bce4ff" },
      { pts: [pShamM, pShamR, pBotR, pBotM], col: c % 2 === 0 ? "#ffb703" : "#3a1405", op: 65, hatchAng: 95, pCol: "#fff3b0" }
    ];

    for (let bv of bevels) {
      // Translucent optical facet wash
      brush.noStroke();
      brush.wash(bv.col, bv.op);
      drawFreePoly(bv.pts, 0.02);
      brush.noWash();

      // Fine coloured pencil prism hatching across the facet
      brush.hatchStyle("sharp_cpencil", bv.pCol, 0.34);
      brush.hatch(4.8, bv.hatchAng, { rand: 0.04, gradient: 0.5 });
      drawFreePoly(bv.pts, 0.02);
      brush.noHatch();
    }

    // Crisp Engraved Mitre Cuts (V-grooves catching blinding white, cold ice-blue, and dark amber)
    let mitreLines = [
      [pTopM, pMidL, "#ffffff", "#7ab8e8"],
      [pTopM, pMidR, "#fff3b0", "#9c3304"],
      [pMidL, pShamM, "#bce4ff", "#4a1904"],
      [pMidR, pShamM, "#ffffff", "#c45108"],
      [pTopM, pShamM, "#e8f6ff", "#ff9100"], // Vertical diamond spine
      [pMidL, pMidR, "#ffd166", "#7ab8e8"],  // Horizontal diamond equator
      [pShamL, pBotL, "#ffffff", "#260e04"], // Sham pillar cut
      [pShamM, pBotM, "#bce4ff", "#ff7b00"]  // Sham center cut
    ];

    for (let ml of mitreLines) {
      let [a, b, hiCol, shCol] = ml;
      // Dark refractive shadow lip of the V-groove
      brush.set("sharp_cpencil", shCol, 0.52);
      brush.line(a[0] + 1.8, a[1] + 1.2, b[0] + 1.8, b[1] + 1.2);
      // Blazing highlight lip of the V-groove
      brush.set("fine_whisker", hiCol, 0.62);
      brush.line(a[0], a[1], b[0], b[1]);
    }

    // Star-cut fan rays rising slightly above each diamond peak (pTopM)
    for (let ray = -2; ray <= 2; ray++) {
      let rAng = -90 + ray * 19;
      let rLen = ray === 0 ? 44 : (Math.abs(ray) === 1 ? 34 : 24);
      let rx = pTopM[0] + Math.cos((rAng * Math.PI) / 180) * rLen;
      let ry = pTopM[1] + Math.sin((rAng * Math.PI) / 180) * rLen;
      brush.set("sharp_cpencil", "#9c3304", 0.42);
      brush.line(pTopM[0] + 1.2, pTopM[1], rx + 1.2, ry);
      brush.set("fine_whisker", ray % 2 === 0 ? "#ffffff" : "#bce4ff", 0.55);
      brush.line(pTopM[0], pTopM[1], rx, ry);
    }
  }

  // =========================================================================
  // 10. GLASS RIM, VERTICAL WALL SPECULARS & HEAVY FOOT CONTOURS
  // =========================================================================
  // Upper Glass Rim Ellipse at y = 232 (thick polished crystal lip)
  let outerRimBack  = makeEllipseArc(CX, RIM_Y, rxRim, ryRim, 180, 360, 36, 2, (t) => 0.5 + 0.5 * Math.sin(t * Math.PI));
  let innerRimBack  = makeEllipseArc(CX, RIM_Y + 4, rxRim - 11, ryRim - 5, 180, 360, 36, 2, (t) => 0.5 + 0.5 * Math.sin(t * Math.PI));
  let outerRimFront = makeEllipseArc(CX, RIM_Y, rxRim, ryRim, 0, 180, 40, 2, (t) => 0.6 + 0.5 * Math.sin(t * Math.PI));
  let innerRimFront = makeEllipseArc(CX, RIM_Y + 5, rxRim - 11, ryRim - 5, 0, 180, 40, 2, (t) => 0.6 + 0.5 * Math.sin(t * Math.PI));

  // Rim wash
  let rimBandPoly = [
    ...outerRimFront.map(pt => [pt[0], pt[1]]),
    ...innerRimFront.slice().reverse().map(pt => [pt[0], pt[1]])
  ];
  brush.noStroke();
  brush.wash("#e6f5ff", 125);
  drawFreePoly(rimBandPoly, 0.05);
  brush.noWash();

  // Rim pencil and ink-sharp highlights
  brush.set("sharp_cpencil", "#4a2412", 0.58);
  brush.spline(outerRimBack, 0.3);
  brush.set("sharp_cpencil", "#90c8f0", 0.52);
  brush.spline(innerRimBack, 0.3);
  brush.set("fine_whisker", "#ffffff", 0.68);
  brush.spline(makeEllipseArc(CX, RIM_Y + 2, rxRim - 5, ryRim - 2, 200, 340, 28, 1.5), 0.3);

  brush.set("sharp_cpencil", "#2b1207", 0.65);
  brush.spline(outerRimFront, 0.3);
  brush.set("sharp_cpencil", "#7ab8e8", 0.58);
  brush.spline(innerRimFront, 0.3);
  brush.set("fine_whisker", "#ffffff", 0.85);
  brush.spline(makeEllipseArc(CX, RIM_Y + 2.5, rxRim - 5, ryRim - 2.5, 12, 168, 34, 1.5, (t) => 0.5 + 0.7 * Math.sin(t * Math.PI)), 0.3);
  brush.set("fine_whisker", "#ffe599", 0.55);
  brush.spline(makeEllipseArc(CX, RIM_Y + 4, rxRim - 8, ryRim - 4, 25, 155, 28, 1.5), 0.3);

  // Left and Right outer glass contours & vertical cylindrical specular ribbons
  let leftOuterContour = [];
  let rightOuterContour = [];
  for (let s = 0; s <= 32; s++) {
    let t = s / 32;
    let y = lerp(RIM_Y, BASE_Y, t);
    let rx = getTumblerHalfWidth(y);
    let p = 0.5 + 0.6 * Math.sin(t * Math.PI);
    leftOuterContour.push([CX - rx, y, p]);
    rightOuterContour.push([CX + rx, y, p]);
  }

  brush.set("sharp_cpencil", "#260e04", 0.75);
  brush.spline(leftOuterContour, 0.2);
  brush.spline(rightOuterContour, 0.2);

  // Inner glass wall thickness lines (showing heavy crystal wall on left and right)
  let leftInnerWall = leftOuterContour.map(pt => [pt[0] + 13, pt[1], pt[2] * 0.85]);
  let rightInnerWall = rightOuterContour.map(pt => [pt[0] - 13, pt[1], pt[2] * 0.85]);

  brush.set("sharp_cpencil", "#bce4ff", 0.55);
  brush.spline(leftInnerWall, 0.2);
  brush.set("sharp_cpencil", "#ffbe0b", 0.55);
  brush.spline(rightInnerWall, 0.2);

  // Vertical specular highlight bars on the smooth upper cylinder (left cold blue-white, right warm honey)
  let leftSpecBar = [
    [CX - rxRim + 28, RIM_Y + 28],
    [CX - rxRim + 44, RIM_Y + 32],
    [CX - getTumblerHalfWidth(520) + 46, 520],
    [CX - getTumblerHalfWidth(520) + 30, 515]
  ];
  let rightSpecBar = [
    [CX + rxRim - 46, RIM_Y + 32],
    [CX + rxRim - 26, RIM_Y + 28],
    [CX + getTumblerHalfWidth(520) - 28, 515],
    [CX + getTumblerHalfWidth(520) - 48, 520]
  ];
  brush.noStroke();
  brush.wash("#e8f6ff", 95);
  drawFreePoly(leftSpecBar, 0.04);
  brush.wash("#fff3b0", 85);
  drawFreePoly(rightSpecBar, 0.04);
  brush.noWash();

  brush.set("fine_whisker", "#ffffff", 0.65);
  brush.line(leftSpecBar[0][0] + 4, leftSpecBar[0][1], leftSpecBar[3][0] + 4, leftSpecBar[3][1]);
  brush.line(rightSpecBar[1][0] - 4, rightSpecBar[1][1], rightSpecBar[2][0] - 4, rightSpecBar[2][1]);

  // Heavy Tumbler Base Bottom Ellipses (y = 918)
  let baseBottomFront = makeEllipseArc(CX, BASE_Y, rxBase, ryBase, 0, 180, 38, 2.5, (t) => 0.6 + 0.6 * Math.sin(t * Math.PI));
  let baseInnerFront  = makeEllipseArc(CX, BASE_Y - 12, rxBase - 14, ryBase - 6, 6, 174, 34, 2, (t) => 0.5 + 0.6 * Math.sin(t * Math.PI));

  brush.set("sharp_cpencil", "#120602", 0.88);
  brush.spline(baseBottomFront, 0.3);
  brush.set("sharp_cpencil", "#ff9100", 0.65);
  brush.spline(baseInnerFront, 0.3);
  brush.set("fine_whisker", "#ffffff", 0.8);
  brush.spline(makeEllipseArc(CX, BASE_Y - 5, rxBase - 6, ryBase - 3, 18, 162, 32, 1.5), 0.3);
  brush.set("fine_whisker", "#bce4ff", 0.65);
  brush.spline(makeEllipseArc(CX, BASE_Y - 9, rxBase - 10, ryBase - 5, 28, 152, 28, 1.5), 0.3);

  // =========================================================================
  // 11. CONDENSATION CRAWLING DOWN THE TUMBLER (DROPLETS & RIVULETS)
  // =========================================================================
  // Subtle chilled mist on the exterior glass between y = 310 and y = 780
  for (let m = 0; m < 75; m++) {
    let my = random(310, 770);
    let rx = getTumblerHalfWidth(my) - 18;
    let mx = CX + random(-rx, rx);
    let mistCol = Math.abs(mx - CX) < 110 ? "#ffd166" : "#d8f3ff";
    brush.set("spray", mistCol, random(0.35, 0.65));
    brush.line(mx, my, mx + random(-8, 8), my + random(-6, 6));
  }

  // Slow vertical condensation rivulets crawling down the chilled glass
  let rivuletTracks = [
    { ang: 34,  yStart: 355, yEnd: 685 },
    { ang: 56,  yStart: 380, yEnd: 745 },
    { ang: 78,  yStart: 335, yEnd: 640 },
    { ang: 104, yStart: 390, yEnd: 780 },
    { ang: 128, yStart: 360, yEnd: 710 },
    { ang: 148, yStart: 410, yEnd: 690 },
    { ang: 67,  yStart: 470, yEnd: 825 }
  ];

  for (let rv of rivuletTracks) {
    let steps = 22;
    let trackShadow = [];
    let trackLight = [];
    let curAng = rv.ang;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let y = lerp(rv.yStart, rv.yEnd, t);
      curAng += (noise(rv.ang, y * 0.025) - 0.5) * 2.2;
      let rad = (curAng * Math.PI) / 180;
      let rx = getTumblerHalfWidth(y);
      let ry = getTumblerEllipseRy(y);
      let x = CX + Math.cos(rad) * rx;
      let py = y + Math.sin(rad) * ry;
      let p = 0.3 + 0.7 * Math.sin(t * Math.PI);
      trackShadow.push([x + 1.8, py, p]);
      trackLight.push([x - 1.2, py, p]);
    }

    // Wet refractive track
    brush.set("sharp_cpencil", "#7c2d08", 0.38);
    brush.spline(trackShadow, 0.35);
    brush.set("fine_whisker", "#e8f6ff", 0.44);
    brush.spline(trackLight, 0.35);

    // Heavy pendant drop at the bottom tip of each rivulet
    let tip = trackLight[trackLight.length - 1];
    let dropW = 5.5;
    let dropH = 8.5;
    brush.noStroke();
    brush.wash("#ffbe0b", 165);
    drawFreePoly(makeEllipsePoly(tip[0] + 0.8, tip[1] + 2, dropW, dropH, 12), 0.1);
    brush.noWash();
    brush.set("sharp_cpencil", "#4a1904", 0.45);
    brush.arc(tip[0] + 0.8, tip[1] + 2, dropW, 180, 360);
    brush.set("fine_whisker", "#ffffff", 0.58);
    brush.line(tip[0] - 2, tip[1] - 2, tip[0] - 0.5, tip[1] + 2);
  }

  // 195 Hyperreal Condensation Droplets beaded across the glass surface
  for (let d = 0; d < 195; d++) {
    let ang = random(10, 170);
    let rad = (ang * Math.PI) / 180;
    let yBase = random(285, 855);
    let rx = getTumblerHalfWidth(yBase);
    let ry = getTumblerEllipseRy(yBase);

    let dx = CX + Math.cos(rad) * rx;
    let dy = yBase + Math.sin(rad) * ry;

    // Vary droplet size: mix of micro-beads, medium drops, and heavy swollen beads
    let sizeRoll = random();
    let rDrop = sizeRoll < 0.62 ? random(1.6, 3.2) : (sizeRoll < 0.9 ? random(3.3, 5.4) : random(5.5, 8.2));
    let stretch = rDrop > 4.5 ? random(1.18, 1.45) : random(1.0, 1.18);

    // Determine local background behind droplet for realistic inverted lens refraction
    let inIceZone = Math.abs(dx - ICE_CX) < 155 && dy > 320 && dy < 700;
    let inWhiskyZone = dy > MENISCUS_Y && dy < SHAM_TOP_Y;

    let bellyCol = inIceZone
      ? (random() < 0.5 ? "#bce4ff" : "#ff9100")
      : (inWhiskyZone ? "#ffb703" : "#d8f3ff");
    let shadowCol = inWhiskyZone ? "#591902" : "#2c4257";

    // 1. Refracted luminous belly of the droplet
    brush.noStroke();
    brush.wash(bellyCol, 155);
    drawFreePoly(makeEllipsePoly(dx, dy, rDrop, rDrop * stretch, 10), 0.1);
    brush.noWash();

    // 2. Dark crescent shadow at the upper/outer edge (lens inversion of backlit source)
    brush.set("fine_whisker", shadowCol, rDrop > 4 ? 0.44 : 0.3);
    let shArc = makeEllipseArc(dx, dy - rDrop * 0.15, rDrop, rDrop * stretch, 195, 345, 7);
    brush.spline(shArc, 0.25);

    // 3. Cast micro-shadow directly below the droplet
    brush.set("fine_whisker", shadowCol, 0.28);
    let underArc = makeEllipseArc(dx, dy + rDrop * 0.25, rDrop * 0.9, rDrop * stretch * 0.85, 20, 160, 6);
    brush.spline(underArc, 0.25);

    // 4. Pinpoint cold blue-white / pure white specular glint on the droplet
    brush.set("fine_whisker", "#ffffff", rDrop > 3.5 ? 0.55 : 0.38);
    brush.line(
      dx - rDrop * 0.38,
      dy - rDrop * 0.35,
      dx - rDrop * 0.1,
      dy - rDrop * 0.15
    );
    if (rDrop > 4.5) {
      // Secondary warm cadmium lower caustic dot inside the large droplet
      brush.set("fine_whisker", "#fff3b0", 0.45);
      brush.line(dx + rDrop * 0.15, dy + rDrop * 0.45, dx + rDrop * 0.35, dy + rDrop * 0.35);
    }
  }

  // =========================================================================
  // 12. FINAL PRISMATIC SPARKS & COLOURED PENCIL FINISHING ACCENTS
  // =========================================================================
  // Intense diamond-point glints where cut-crystal mitre intersections catch the bar light
  for (let c = 1; c < NUM_COLS; c++) {
    let pMid = getCylPoint(c, CUT_Y1);
    let pSham = getCylPoint(c + 0.5, CUT_Y2);
    let sparkPts = [pMid, pSham];

    for (let sp of sparkPts) {
      brush.set("fine_whisker", "#bce4ff", 0.55);
      brush.line(sp[0] - 11, sp[1], sp[0] + 11, sp[1]);
      brush.line(sp[0], sp[1] - 9, sp[0], sp[1] + 9);
      brush.set("fine_whisker", "#ffffff", 0.75);
      brush.line(sp[0] - 5, sp[1] - 5, sp[0] + 5, sp[1] + 5);
      brush.line(sp[0] - 5, sp[1] + 5, sp[0] + 5, sp[1] - 5);
    }
  }

  noLoop();
}
